                </p>
              </div>
              <div className="flex gap-2">
                <Button
                  variant="primary"
                  onClick={() => approve(user.id)}
                  loading={actionLoading === user.id}
                  disabled={actionLoading !== null}
                >
                  Approve
                </Button>
                <Button
                  variant="danger"
                  onClick={() => setRejectTarget(user)}
                  disabled={actionLoading !== null}
                >
                  Reject
                </Button>
              </div>
            </div>
