                  addExtension();
                }
              }}
              placeholder="e.g. png"
              className="min-h-11 md:min-h-9 bg-surface border border-border rounded px-3 py-2 text-text placeholder:text-text-muted/70 focus:outline-none focus:ring-2 focus:ring-primary w-40 text-sm"
            />
