          <div>
            <p className="text-sm font-medium">Strip EXIF Data</p>
            <p className="text-text-muted text-xs">
              Remove metadata (GPS, camera info) from uploaded images for privacy
            </p>
          </div>
        </label>

        {error && <p className="text-danger text-sm">{error}</p>}
        {success && <p className="text-online text-sm">{success}</p>}

        <Button type="submit" loading={saving}>
          Save Settings
        </Button>
      </form>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { api, ApiError } from '../../lib/api';
import { Button } from '../../components/ui/Button';
import type { FileSettings, StorageStats } from '../../lib/contracts/admin';

const RETENTION_OPTIONS = [
  { value: null as number | null, label: 'Off (keep forever)' },
  { value: 7, label: '7 days' },
  { value: 30, label: '30 days' },
  { value: 90, label: '90 days' },
  { value: 365, label: '365 days' },
];

export function formatBytes(bytesStr: string): string {
  const bytes = Number(bytesStr);
  if (bytes === 0) return '0 B';
  if (bytes >= 1073741824) return `${(bytes / 1073741824).toFixed(2)} GB`;
  if (bytes >= 1048576) return `${(bytes / 1048576).toFixed(2)} MB`;
  if (bytes >= 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${bytes} B`;
}

export function StorageSettings() {
  const [stats, setStats] = useState<StorageStats | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [newExtension, setNewExtension] = useState('');

  // Editable copies of settings
  const [maxSizeMB, setMaxSizeMB] = useState(25);
  const [allowedExtensions, setAllowedExtensions] = useState<string[]>([]);
  const [retentionDays, setRetentionDays] = useState<number | null>(null);
  const [exifStrip, setExifStrip] = useState(true);

  useEffect(() => {
    Promise.all([
      api.get<FileSettings>('/admin/settings/files'),
      api.get<StorageStats>('/admin/storage'),
    ])
      .then(([fileSettings, storageStats]) => {
        setStats(storageStats);
        setMaxSizeMB(Math.round((fileSettings['files.max_size_bytes'] ?? 26214400) / 1048576));
        setAllowedExtensions(fileSettings['files.allowed_extensions'] ?? []);
        // A stored 0 (old #155 bug) means no limit; saving it back would fail validation
        setRetentionDays(fileSettings['files.retention_days'] || null);
        setExifStrip(fileSettings['files.exif_strip'] ?? true);
      })
      .catch((err) => {
        setError(err instanceof ApiError ? err.code : 'Failed to load file settings');
      })
      .finally(() => setLoading(false));
  }, []);

  async function handleSave(e: React.FormEvent) {
    e.preventDefault();
    setSaving(true);
    setError('');
    setSuccess('');
    try {
      await api.patch('/admin/settings/files', {
        'files.max_size_bytes': maxSizeMB * 1048576,
        'files.allowed_extensions': allowedExtensions,
        'files.retention_days': retentionDays,
        'files.exif_strip': exifStrip,
      });
      setSuccess('File settings saved.');
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to save settings');
    } finally {
      setSaving(false);
    }
  }

  function addExtension() {
    const ext = newExtension.trim().toLowerCase().replace(/^\./, '');
    if (ext && /^[a-z0-9]+$/.test(ext) && !allowedExtensions.includes(ext)) {
      setAllowedExtensions([...allowedExtensions, ext]);
    }
    setNewExtension('');
  }

  function removeExtension(ext: string) {
    setAllowedExtensions(allowedExtensions.filter((e) => e !== ext));
  }

  if (loading) {
    return <p className="text-text-muted">Loading file settings...</p>;
  }

  return (
    <div>
      <h2 className="text-xl font-bold mb-6">File Storage</h2>

      {/* Storage Usage Section */}
      {stats && (
        <div className="mb-8">
          <h3 className="text-sm font-semibold text-text-muted uppercase tracking-wide mb-3">
            Storage Usage
          </h3>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-4">
            <div className="bg-surface rounded-lg border border-border p-4">
              <p className="text-text-muted text-sm">Total Files</p>
              <p className="text-2xl font-bold">{stats.totalFiles}</p>
            </div>
            <div className="bg-surface rounded-lg border border-border p-4">
              <p className="text-text-muted text-sm">Total Storage</p>
              <p className="text-2xl font-bold">{formatBytes(stats.totalBytes)}</p>
            </div>
            <div className="bg-surface rounded-lg border border-border p-4">
              <p className="text-text-muted text-sm">Images</p>
              <p className="text-2xl font-bold">
                {stats.imageCount}
                <span className="text-sm font-normal text-text-muted ml-2">
                  ({formatBytes(stats.imageBytes)})
                </span>
              </p>
            </div>
          </div>

          {stats.quotaBytes && stats.quotaUsedPercent != null && (
            <div className="bg-surface rounded-lg border border-border p-4">
              <div className="flex justify-between text-sm mb-2">
                <span className="text-text-muted">Quota Usage</span>
                <span>
                  {formatBytes(stats.totalBytes)} of {formatBytes(stats.quotaBytes)}
                  <span className="text-text-muted ml-2">
                    ({stats.quotaUsedPercent.toFixed(1)}%)
                  </span>
                </span>
              </div>
              <div className="w-full bg-surface-hover rounded-full h-3">
                <div
                  className={`h-3 rounded-full transition-all ${
                    stats.quotaUsedPercent >= 90
                      ? 'bg-danger'
                      : stats.quotaUsedPercent >= 70
                        ? 'bg-warn'
                        : 'bg-primary'
                  }`}
                  style={{ width: `${Math.min(stats.quotaUsedPercent, 100)}%` }}
                />
              </div>
            </div>
          )}

          {stats.expiringFiles > 0 && (
            <p className="text-text-muted text-sm mt-2">
              {stats.expiringFiles} file{stats.expiringFiles !== 1 ? 's' : ''} pending expiration
            </p>
          )}
        </div>
      )}

      {/* Settings Section */}
      <h3 className="text-sm font-semibold text-text-muted uppercase tracking-wide mb-3">
        Settings
      </h3>
      <form onSubmit={handleSave} className="max-w-lg flex flex-col gap-5">
        {/* Max File Size */}
        <div className="flex flex-col gap-1">
          <label htmlFor="max-file-size" className="text-sm text-text-muted">
            Max File Size (MB)
          </label>
          <input
            id="max-file-size"
            type="number"
            min={1}
            value={maxSizeMB}
            onChange={(e) => setMaxSizeMB(Number(e.target.value))}
            className="min-h-11 md:min-h-9 bg-surface border border-border rounded px-3 py-2 text-text focus:outline-none focus:ring-2 focus:ring-primary w-32"
          />
          <span className="text-xs text-text-muted">
            {(maxSizeMB * 1048576).toLocaleString()} bytes
          </span>
        </div>

        {/* Allowed Extensions */}
        <div className="flex flex-col gap-2">
          <label className="text-sm text-text-muted">Allowed Extensions</label>
          <div className="flex flex-wrap gap-2">
            {allowedExtensions.map((ext) => (
              <span
                key={ext}
                className="inline-flex items-center gap-1 bg-primary/15 text-text text-sm pl-2.5 pr-1 py-1 rounded"
              >
                .{ext}
                <button
                  type="button"
                  onClick={() => removeExtension(ext)}
                  className="min-w-7 min-h-7 inline-flex items-center justify-center rounded text-text-muted hover:text-danger hover:bg-danger/15 ml-0.5"
                  aria-label={`Remove .${ext}`}
                >
                  ×
                </button>
              </span>
            ))}
          </div>
          <div className="flex gap-2">
            <input
              type="text"
              value={newExtension}
              onChange={(e) => setNewExtension(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter') {
                  e.preventDefault();
                  addExtension();
                }
              }}
              placeholder="e.g. png"
              className="min-h-11 md:min-h-9 bg-surface border border-border rounded px-3 py-2 text-text placeholder:text-text-muted/70 focus:outline-none focus:ring-2 focus:ring-primary w-40 text-sm"
            />
            <Button type="button" variant="secondary" onClick={addExtension}>
              Add
            </Button>
          </div>
        </div>

        {/* Retention Period */}
        <fieldset className="flex flex-col gap-1">
          <legend className="text-sm text-text-muted mb-2">File Retention</legend>
          {RETENTION_OPTIONS.map((opt) => (
            <label
              key={String(opt.value)}
              className={`min-h-11 md:min-h-9 flex items-center gap-3 p-2 rounded border cursor-pointer ${
                retentionDays === opt.value
                  ? 'border-primary bg-primary/10'
                  : 'border-border hover:bg-surface-hover'
              }`}
            >
              <input
                type="radio"
                name="retentionDays"
                checked={retentionDays === opt.value}
                onChange={() => setRetentionDays(opt.value)}
                className="accent-primary"
              />
              <span className="text-sm">{opt.label}</span>
            </label>
          ))}
        </fieldset>

        {/* EXIF Stripping */}
        <label className="min-h-11 flex items-center gap-3 cursor-pointer">
          <input
            type="checkbox"
            checked={exifStrip}
            onChange={(e) => setExifStrip(e.target.checked)}
            className="w-4 h-4 rounded border-border accent-primary"
          />
          <div>
            <p className="text-sm font-medium">Strip EXIF Data</p>
            <p className="text-text-muted text-xs">
              Remove metadata (GPS, camera info) from uploaded images for privacy
            </p>
          </div>
        </label>

        {error && <p className="text-danger text-sm">{error}</p>}
        {success && <p className="text-online text-sm">{success}</p>}

        <Button type="submit" loading={saving}>
          Save Settings
        </Button>
      </form>
    </div>
  );
}

import { useEffect, useState, useRef, useCallback } from 'react';
import { api, ApiError } from '../../lib/api';
import { Button } from '../../components/ui/Button';
import type { AdminUser, PaginatedUsers } from '../../lib/contracts/admin';

type StatusFilter = 'all' | 'active' | 'pending' | 'suspended';

const LIMIT = 20;

export function UserTable() {
  const [users, setUsers] = useState<any>([]);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(1);
  const [status, setStatus] = useState<StatusFilter>('all');
  const [search, setSearch] = useState('');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [banTarget, setBanTarget] = useState<AdminUser | null>(null);
  const [banLoading, setBanLoading] = useState(false);
  const [banResult, setBanResult] = useState('');
  const debounceRef = useRef<ReturnType<typeof setTimeout>>(undefined);
  const searchRef = useRef(search);
  searchRef.current = search;

  const fetchUsers = useCallback(async (p: number, s: StatusFilter, q: string) => {
    setLoading(true);
    setError('');
    try {
      const params = new URLSearchParams({ page: String(p), limit: String(LIMIT) });
      if (s !== 'all') params.set('status', s);
      if (q) params.set('search', q);
      const res = await api.get<PaginatedUsers>(`/admin/users?${params}`);
      setUsers(res.users);
      setTotal(res.total);
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to load users');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchUsers(page, status, searchRef.current);
  }, [page, status, fetchUsers]);

  function handleSearchChange(value: string) {
    setSearch(value);
    clearTimeout(debounceRef.current);
    debounceRef.current = setTimeout(() => {
      setPage(1);
      fetchUsers(1, status, value);
    }, 300);
  }

  function handleStatusChange(value: StatusFilter) {
    setStatus(value);
    setPage(1);
  }

  async function banUser() {
    if (!banTarget) return;
    setBanLoading(true);
    try {
      await api.post(`/admin/users/${banTarget.id}/ban`);
      setUsers((prev) =>
        prev.map((u) =>
          u.id === banTarget.id ? { ...u, accountStatus: 'suspended' as const } : u
        )
      );
      setBanResult('Account banned');
      setBanTarget(null);
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to ban user');
    } finally {
      setBanLoading(false);
    }
  }

  const totalPages = Math.ceil(total / LIMIT);

  return (
    <div>
      <h2 className="text-xl font-bold mb-4">All Users</h2>

      <div className="flex gap-3 mb-4">
        <select
          value={status}
          onChange={(e) => handleStatusChange(e.target.value as StatusFilter)}
          className="min-h-11 md:min-h-9 bg-surface border border-border rounded px-3 py-2 text-text text-sm focus:outline-none focus:ring-2 focus:ring-primary"
        >
          <option value="all">All</option>
          <option value="active">Active</option>
          <option value="pending">Pending</option>
          <option value="suspended">Banned</option>
        </select>
        <input
          type="text"
          placeholder="Search users..."
          value={search}
          onChange={(e) => handleSearchChange(e.target.value)}
          className="min-h-11 md:min-h-9 bg-surface border border-border rounded px-3 py-2 text-text text-sm placeholder:text-text-muted/70 focus:outline-none focus:ring-2 focus:ring-primary flex-1 max-w-xs"
        />
      </div>

      {error && <p className="text-danger text-sm mb-4">{error}</p>}
      {banResult && (
        <p className="text-online text-sm mb-4">
          {banResult}
          <button className="ml-2 min-h-11 md:min-h-8 px-2 underline text-text-muted hover:text-text" onClick={() => setBanResult('')}>dismiss</button>
        </p>
      )}

      <div className="overflow-x-auto">
        <table className="w-full text-sm">
          <thead>
            <tr className="border-b border-border text-left text-text-muted">
              <th className="pb-2 pr-4">Username</th>
              <th className="pb-2 pr-4">Email</th>
              <th className="pb-2 pr-4">Status</th>
              <th className="pb-2 pr-4">Admin</th>
              <th className="pb-2 pr-4">Joined</th>
              <th className="pb-2">Actions</th>
            </tr>
          </thead>
          <tbody>
            {loading ? (
              <tr>
                <td colSpan={6} className="py-8 text-center text-text-muted">
                  Loading...
                </td>
              </tr>
            ) : users.length === 0 ? (
              <tr>
                <td colSpan={6} className="py-8 text-center text-text-muted">
                  No users found.
                </td>
              </tr>
            ) : (
              users.map((user) => (
                <tr key={user.id} className="border-b border-border">
                  <td className="py-3 pr-4">{user.username}</td>
                  <td className="py-3 pr-4 text-text-muted">{user.email ?? '—'}</td>
                  <td className="py-3 pr-4">
                    <StatusChip status={user.accountStatus} />
                  </td>
                  <td className="py-3 pr-4">
                    {user.isInstanceAdmin && (
                      <span className="text-accent text-xs font-medium bg-accent/10 px-2 py-0.5 rounded">
                        Admin
                      </span>
                    )}
                  </td>
                  <td className="py-3 pr-4 text-text-muted">
                    {new Date(user.createdAt).toLocaleDateString()}
                  </td>
                  <td className="py-3">
                    {user.accountStatus === 'active' && !user.isInstanceAdmin && (
                      <Button
                        variant="danger"
                        className="text-xs !px-3 !py-1 min-h-11 md:min-h-8"
                        onClick={() => { setBanTarget(user); setBanResult(''); }}
                      >
                        Ban
                      </Button>
                    )}
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      {totalPages > 1 && (
        <div className="flex items-center justify-between mt-4">
          <Button
            variant="secondary"
            onClick={() => setPage((p) => Math.max(1, p - 1))}
            disabled={page <= 1}
          >
            Previous
          </Button>
          <span className="text-text-muted text-sm">
            Page {page} of {totalPages}
          </span>
          <Button
            variant="secondary"
            onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
            disabled={page >= totalPages}
          >
            Next
          </Button>
        </div>
      )}

      <BanDialog
        target={banTarget}
        onConfirm={banUser}
        onCancel={() => setBanTarget(null)}
        loading={banLoading}
      />
    </div>
  );
}

function StatusChip({ status }: { status: AdminUser['accountStatus'] }) {
  const styles = {
    active: 'text-online bg-online/10',
    pending: 'text-warn bg-warn/10',
    suspended: 'text-danger bg-danger/10',
  };

  const labels: Record<AdminUser['accountStatus'], string> = {
    active: 'active',
    pending: 'pending',
    suspended: 'Banned',
  };

  return (
    <span className={`text-xs font-medium px-2 py-0.5 rounded ${styles[status]}`}>
      {labels[status]}
    </span>
  );
}

function BanDialog({
  target,
  onConfirm,
  onCancel,
  loading,
}: {
  target: AdminUser | null;
  onConfirm: () => void;
  onCancel: () => void;
  loading: boolean;
}) {
  if (!target) return null;

  return (
    <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center">
      <div className="bg-surface rounded-lg border border-border p-6 max-w-md w-full mx-4">
        <h2 className="text-lg font-bold">Ban user</h2>
        <p className="text-text-muted text-sm mt-2">
          Are you sure you want to ban {target.username}?
        </p>
        <div className="flex justify-end gap-2 mt-6">
          <Button variant="secondary" onClick={onCancel} disabled={loading}>
            Cancel
          </Button>
          <Button variant="danger" onClick={onConfirm} loading={loading}>
            Ban
          </Button>
        </div>
      </div>
    </div>
  );
}

