  function handleSearchChange(value: string) {
    setSearch(value);
    clearTimeout(debounceRef.current);
    debounceRef.current = setTimeout(() => {
      setPage(1);
      fetchUsers(1, status, value);
    }, 300);
  }

  function handleStatusChange(value: StatusFilter) {
    setStatus(value);
    setPage(1);
  }

  async function banUser() {
    if (!banTarget) return;
    setBanLoading(true);
    try {
      await api.post(`/admin/users/${banTarget.id}/ban`);
      setUsers((prev) =>
        prev.map((u) =>
          u.id === banTarget.id ? { ...u, accountStatus: 'suspended' as const } : u
        )
      );
      setBanResult('Account banned');
      setBanTarget(null);
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to ban user');
    } finally {
      setBanLoading(false);
    }
  }

  const totalPages = Math.ceil(total / LIMIT);

  return (
    <div>
      <h2 className="text-xl font-bold mb-4">All Users</h2>

      <div className="flex gap-3 mb-4">
        <select
          value={status}
          onChange={(e) => handleStatusChange(e.target.value as StatusFilter)}
          className="min-h-11 md:min-h-9 bg-surface border border-border rounded px-3 py-2 text-text text-sm focus:outline-none focus:ring-2 focus:ring-primary"
        >
          <option value="all">All</option>
          <option value="active">Active</option>
          <option value="pending">Pending</option>
          <option value="suspended">Banned</option>
        </select>
        <input
          type="text"
          placeholder="Search users..."
          value={search}
          onChange={(e) => handleSearchChange(e.target.value)}
          className="min-h-11 md:min-h-9 bg-surface border border-border rounded px-3 py-2 text-text text-sm placeholder:text-text-muted/70 focus:outline-none focus:ring-2 focus:ring-primary flex-1 max-w-xs"
        />
      </div>

      {error && <p className="text-danger text-sm mb-4">{error}</p>}
      {banResult && (
        <p className="text-online text-sm mb-4">
          {banResult}
          <button className="ml-2 min-h-11 md:min-h-8 px-2 underline text-text-muted hover:text-text" onClick={() => setBanResult('')}>dismiss</button>
        </p>
      )}

      <div className="overflow-x-auto">
        <table className="w-full text-sm">
          <thead>
            <tr className="border-b border-border text-left text-text-muted">
              <th className="pb-2 pr-4">Username</th>
              <th className="pb-2 pr-4">Email</th>
              <th className="pb-2 pr-4">Status</th>
              <th className="pb-2 pr-4">Admin</th>
              <th className="pb-2 pr-4">Joined</th>
              <th className="pb-2">Actions</th>
            </tr>
          </thead>
          <tbody>
            {loading ? (
              <tr>
                <td colSpan={6} className="py-8 text-center text-text-muted">
                  Loading...
                </td>
              </tr>
            ) : users.length === 0 ? (
              <tr>
                <td colSpan={6} className="py-8 text-center text-text-muted">
                  No users found.
                </td>
              </tr>
            ) : (
              users.map((user) => (
                <tr key={user.id} className="border-b border-border">
                  <td className="py-3 pr-4">{user.username}</td>
                  <td className="py-3 pr-4 text-text-muted">{user.email ?? '—'}</td>
                  <td className="py-3 pr-4">
                    <StatusChip status={user.accountStatus} />
                  </td>
                  <td className="py-3 pr-4">
                    {user.isInstanceAdmin && (
                      <span className="text-accent text-xs font-medium bg-accent/10 px-2 py-0.5 rounded">
                        Admin
                      </span>
                    )}
                  </td>
                  <td className="py-3 pr-4 text-text-muted">
                    {new Date(user.createdAt).toLocaleDateString()}
                  </td>
                  <td className="py-3">
                    {user.accountStatus === 'active' && !user.isInstanceAdmin && (
                      <Button
                        variant="danger"
                        className="text-xs !px-3 !py-1 min-h-11 md:min-h-8"
                        onClick={() => { setBanTarget(user); setBanResult(''); }}
                      >
                        Ban
                      </Button>
                    )}
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      {totalPages > 1 && (
        <div className="flex items-center justify-between mt-4">
          <Button
            variant="secondary"
            onClick={() => setPage((p) => Math.max(1, p - 1))}
            disabled={page <= 1}
          >
            Previous
          </Button>
          <span className="text-text-muted text-sm">
            Page {page} of {totalPages}
          </span>
          <Button
            variant="secondary"
            onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
            disabled={page >= totalPages}
          >
            Next
          </Button>
        </div>
      )}

      <BanDialog
        target={banTarget}
        onConfirm={banUser}
        onCancel={() => setBanTarget(null)}
        loading={banLoading}
      />
    </div>
  );
}

function StatusChip({ status }: { status: AdminUser['accountStatus'] }) {
  const styles = {
    active: 'text-online bg-online/10',
    pending: 'text-warn bg-warn/10',
    suspended: 'text-danger bg-danger/10',
  };

  const labels: Record<AdminUser['accountStatus'], string> = {
    active: 'active',
    pending: 'pending',
    suspended: 'Banned',
  };

  return (
    <span className={`text-xs font-medium px-2 py-0.5 rounded ${styles[status]}`}>
      {labels[status]}
    </span>
  );
}

function BanDialog({
  target,
  onConfirm,
  onCancel,
  loading,
}: {
  target: AdminUser | null;
  onConfirm: () => void;
  onCancel: () => void;
  loading: boolean;
}) {
  if (!target) return null;

  return (
    <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center">
      <div className="bg-surface rounded-lg border border-border p-6 max-w-md w-full mx-4">
        <h2 className="text-lg font-bold">Ban user</h2>
        <p className="text-text-muted text-sm mt-2">
          Are you sure you want to ban {target.username}?
        </p>
        <div className="flex justify-end gap-2 mt-6">
          <Button variant="secondary" onClick={onCancel} disabled={loading}>
            Cancel
          </Button>
          <Button variant="danger" onClick={onConfirm} loading={loading}>
            Ban
          </Button>
        </div>
      </div>
    </div>
  );
}

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useSocket } from '../../hooks/useSocket';
import type { AgentSessionUpdatePayload } from '../../lib/contracts/ws-events';
import { useChannelStore } from '../../stores/channelStore';
import { useMessageStore } from '../../stores/messageStore';
import { useThreadStore } from '../../stores/threadStore';
import { useAgentPresenceStore } from '../../stores/agentPresenceStore';
import { ProtocolBadge } from '../messages/ProtocolBadge';
import { latestProtocol } from '../messages/latestProtocol';
import {
  OWN_SESSION_LABEL, STATE_LABEL, compactTokens, deriveChips, listProfiles, listSessions, ownChipLabel, ownSessionChips, ownSessionDetail, resetTime,
  type AgentProfile, type AgentSession, type OwnSessionStatus,
} from './agentSessions';
import { SessionSheet, StateDot, type SheetMode } from './SessionSheet';
import { ChannelAgentsControl } from './ChannelAgents';
import { BoxModeBadge } from '../boxes/BoxModeBadge';
import { boxModeLabel } from '../boxes/boxRules';

/**
 * Console Strip (docs/planning/ui-redesign.md 6.2): one horizontally scrolling row under the
 * channel header with a chip per agent in this channel (live first), a "+ Agent" chip, and a
 * chip per active agora-collab thread. Agent chips open the Session Sheet; thread chips call
 * onOpenThread. Sessions refresh on channel change, on every agent_session notice in the
 * channel, and every 20 seconds while the page is visible.
 */

interface ConsoleStripProps {
  channelId: any;
  onOpenThread: (threadId: string) => void;
}

const POLL_MS = 20_000;
const NO_SESSIONS: AgentSession[] = [];

// The pill is 32px tall, centered in a 44px touch target.
const CHIP_TARGET = 'group flex min-h-[44px] shrink-0 items-center rounded-full focus-visible:outline-none';
const CHIP_PILL = 'flex h-8 items-center gap-1.5 whitespace-nowrap rounded-full border border-border bg-surface-hover px-3 text-[13px] text-text transition-colors group-hover:bg-bg group-focus-visible:outline-2 group-focus-visible:outline-offset-1 group-focus-visible:outline-accent';

export function ConsoleStrip({ channelId, onOpenThread }: ConsoleStripProps) {
  const stripRef = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const strip = stripRef.current;
    if (!strip) return;
    const onWheel = (event: WheelEvent) => {
      // Preserve horizontal trackpad gestures, Shift+wheel and browser zoom.
      if (event.ctrlKey || event.shiftKey || Math.abs(event.deltaY) <= Math.abs(event.deltaX)) return;
      const max = strip.scrollWidth - strip.clientWidth;
      if (max <= 0) return;
      const unit = event.deltaMode === 1 ? 16 : event.deltaMode === 2 ? strip.clientWidth : 1;
      const next = Math.max(0, Math.min(max, strip.scrollLeft + event.deltaY * unit));
      if (next === strip.scrollLeft) return;
      strip.scrollLeft = next;
      event.preventDefault();
    };
    // React's delegated wheel listener can be passive; cancellation is needed only
    // when this strip consumes a vertical wheel. At either edge, let the page scroll.
    strip.addEventListener('wheel', onWheel, { passive: false });
    return () => strip.removeEventListener('wheel', onWheel);
  }, []);
  const socket = useSocket();
  const serverId = useChannelStore(s => s.channels.get(channelId)?.serverId ?? null);
  const [loaded, setLoaded] = useState<{ channelId: string; sessions: AgentSession[] }>({ channelId, sessions: [] });
  const [sheetState, setSheet] = useState<{ mode: SheetMode; key: number; channelId: string } | null>(null);
  const [profiles, setProfiles] = useState<AgentProfile[] | null>(null);
  const [profilesError, setProfilesError] = useState('');
  const channelRef = useRef(channelId);
  useEffect(() => { channelRef.current = channelId; }, [channelId]);

  // Another channel's chips and sheet never show here, even before this channel loads.
  const sessions = loaded.channelId === channelId ? loaded.sessions : NO_SESSIONS;
  const sheet = sheetState?.channelId === channelId ? sheetState : null;

  const refresh = useCallback(() => {
    const forChannel = channelId;
    listSessions(forChannel)
      .then(list => { if (channelRef.current === forChannel) setLoaded({ channelId: forChannel, sessions: list }); })
      .catch(() => { /* keep the last good list; the next poll or notice retries */ });
  }, [channelId]);

  useEffect(() => { refresh(); }, [refresh]);
  useEffect(() => {
    if (!socket) return;
    const onSessionUpdate = (event: AgentSessionUpdatePayload) => {
      if (event.channelId === channelId) refresh();
    };
    socket.on('AgentSessionUpdate', onSessionUpdate);
    return () => { socket.off('AgentSessionUpdate', onSessionUpdate); };
  }, [socket, channelId, refresh]);

  // Poll while visible; catch up as soon as the page is shown again.
  useEffect(() => {
    let timer: ReturnType<typeof setInterval> | null = null;
    const start = () => {
      if (timer === null) timer = setInterval(() => { refresh(); }, POLL_MS);
    };
    const stop = () => {
      if (timer !== null) { clearInterval(timer); timer = null; }
    };
    const onVisibility = () => {
      if (document.visibilityState === 'visible') { refresh(); start(); } else stop();
    };
    if (document.visibilityState === 'visible') start();
    document.addEventListener('visibilitychange', onVisibility);
    return () => { stop(); document.removeEventListener('visibilitychange', onVisibility); };
  }, [refresh]);

  // Every session change posts an agent_session notice into the channel.
  const channelMessages = useMessageStore(s => s.byChannel.get(channelId));
  const lastNoticeId = useMemo(() => {
    if (!channelMessages) return undefined;
    for (let i = channelMessages.length - 1; i >= 0; i--) {
      if (channelMessages[i].systemEvent === 'agent_session') return channelMessages[i].id;
    }
    return undefined;
  }, [channelMessages]);
  // The first notice seen in a channel is history (the channel load already fetched); a later one is news.
  const seenNotice = useRef<{ channelId: string; id: string | undefined } | null>(null);
  useEffect(() => {
    const seen = seenNotice.current;
    seenNotice.current = { channelId, id: lastNoticeId };
    if (seen && seen.channelId === channelId && seen.id !== lastNoticeId && lastNoticeId !== undefined) refresh();
  }, [channelId, lastNoticeId, refresh]);

  // Active collab threads (the data ActiveThreadsBar used).
  const activeThreads = useThreadStore(s => s.activeThreads.get(channelId));
  const threadTotal = useThreadStore(s => s.threadTotals?.get(channelId));
  const hasMoreThreads = useThreadStore(s => !!s.hasMoreThreads?.get(channelId));
  const repliesByThread = useThreadStore(s => s.repliesByThread);
  const loadActiveThreads = useThreadStore(s => s.loadActiveThreads);
  const loadMoreThreads = useThreadStore(s => s.loadMoreThreads);
  useEffect(() => { void loadActiveThreads(channelId).catch(() => {}); }, [channelId, loadActiveThreads]);
  // The thread chips start collapsed behind one count chip (#18); the choice is remembered per browser
  const [threadsOpen, setThreadsOpen] = useState(readThreadsOpen);
  const toggleThreads = () => setThreadsOpen(open => { writeThreadsOpen(!open); return !open; });

  const threads = useMemo(() => (activeThreads ?? []).filter(t => !t.threadClosedAt).map(t => {
    const parent = channelMessages?.find(m => m.id === t.id);
    const cached = [...(parent ? [parent] : []), ...(repliesByThread.get(t.id) ?? [])]
      .filter(m => !t.latestProtocol || m.id >= t.latestProtocol.messageId)
      .sort((a, b) => a.id.localeCompare(b.id));
    const protocol = latestProtocol(cached) ?? t.latestProtocol ?? undefined;
    return { thread: t, protocol };
  }), [activeThreads, channelMessages, repliesByThread]);

  const chips = useMemo(() => deriveChips(sessions), [sessions]);
  const present = useAgentPresenceStore(s => s.byChannel.get(channelId));
  const ownChips = useMemo(() => ownSessionChips(present?.values() ?? [], sessions), [present, sessions]);
  // "idle 12m" and "not listening 2h" on terminal chips move on with the clock
  const [now, setNow] = useState(() => Date.now());
  useEffect(() => {
    const timer = setInterval(() => setNow(Date.now()), 60_000);
    return () => clearInterval(timer);
  }, []);

  const openStart = () => {
    setSheet({ mode: { kind: 'start' }, key: Date.now(), channelId });
    if (!serverId) { setProfilesError('Could not find this channel\'s server.'); return; }
    setProfilesError('');
    listProfiles(serverId)
      .then(setProfiles)
      .catch(() => setProfilesError('Could not load the agents on this server.'));
  };

  return (
    <div
      ref={stripRef}
      role="toolbar"
      aria-label="Agents and active threads"
      className="console-strip flex min-h-[44px] w-full min-w-0 max-w-full shrink-0 items-center gap-2 overflow-x-auto border-b border-border bg-surface/60 px-3"
    >
      {chips.map(chip => {
        const tokens = chip.session.state !== 'ended' && chip.session.tokensUsed > 0 ? compactTokens(chip.session.tokensUsed) : null;
        // A rate-limited agent says so on the chip, with the reset time (#147)
        const resets = chip.state === 'sleeping' && chip.session.sleepingUntil ? resetTime(chip.session.sleepingUntil) : null;
        return (
          <button
            key={chip.profile}
            type="button"
            className={CHIP_TARGET}
            aria-haspopup="dialog"
            aria-label={`${chip.profile}${boxModeLabel(chip.session) ? ` (${boxModeLabel(chip.session)})` : ''}: ${STATE_LABEL[chip.state].toLowerCase()}${resets ? `, resets ${resets}` : ''}${tokens ? `, ${tokens} tokens` : ''}. Open session controls`}
            onClick={() => setSheet({ mode: { kind: 'profile', profile: chip.profile }, key: Date.now(), channelId })}
          >
            <span className={CHIP_PILL}>
              <StateDot state={chip.state} />
              <span className="font-medium">{chip.profile}</span>
              <BoxModeBadge profile={chip.session} />
              {resets && <span className="text-xs text-text-muted">Sleeping · <span className="hidden sm:inline">resets </span>{resets}</span>}
              {tokens && <span className="font-mono text-xs text-text-muted">{tokens}</span>}
            </span>
          </button>
        );
      })}

      {ownChips.map(chip => {
        const working = !!chip.session?.running && chip.status !== 'offline';
        const { text: label, warn } = ownChipLabel(chip, now);
        const pill = (
          <span className={`${CHIP_PILL} border-dashed`}>
            <OwnSessionDot status={chip.status} working={working} />
            <span className="font-medium">{chip.username}</span>
            <span className={`text-xs ${warn ? 'font-medium text-warn' : 'text-text-muted'}`}>{chip.session ? `terminal · ${label}` : label}</span>
          </span>
        );
        // With a terminal session (#112) the chip opens its sheet; without one it is presence only
        return chip.session ? (
          <button
            key={`own-${chip.userId}`}
            type="button"
            className={CHIP_TARGET}
            aria-haspopup="dialog"
            title={`${OWN_SESSION_LABEL[chip.status]}. ${ownSessionDetail(chip)}`}
            aria-label={`${chip.username}: terminal session, ${label}. Open session details`}
            data-testid="own-session-chip"
            onClick={() => setSheet({ mode: { kind: 'terminal', botId: chip.userId }, key: Date.now(), channelId })}
          >
            {pill}
          </button>
        ) : (
          <span
            key={`own-${chip.userId}`}
            role="img"
            className={`${CHIP_TARGET} cursor-default`}
            title={`${OWN_SESSION_LABEL[chip.status]}. ${ownSessionDetail(chip)}`}
            aria-label={`${chip.username}: ${OWN_SESSION_LABEL[chip.status].toLowerCase()}`}
            data-testid="own-session-chip"
          >
            {pill}
          </span>
        );
      })}

      <ChannelAgentsControl key={channelId} channelId={channelId} serverId={serverId} />
      <button type="button" className={CHIP_TARGET} aria-haspopup="dialog" aria-label="Start an agent" onClick={openStart}>
        <span className={`${CHIP_PILL} border-dashed text-text-muted group-hover:text-text`}>Start agent</span>
      </button>

      {threads.length > 0 && <span aria-hidden="true" className="h-5 w-px shrink-0 bg-border" />}

      {threads.length > 0 && (() => {
        // Every open thread in the channel, not the pages loaded so far (#14)
        const total = Math.max(threadTotal ?? threads.length, threads.length);
        const waiting = threads.filter(t => t.protocol?.yieldTo || t.thread.waiting).length;
        return (
          <button
            type="button"
            className={CHIP_TARGET}
            aria-expanded={threadsOpen}
            aria-label={`Active threads (${total})${waiting ? `, ${waiting} waiting on someone` : ''}. ${threadsOpen ? 'Hide' : 'Show'} them`}
            data-testid="threads-toggle"
            onClick={toggleThreads}
          >
            <span className={CHIP_PILL}>
              <svg className={`h-3 w-3 shrink-0 text-text-muted transition-transform ${threadsOpen ? 'rotate-90' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2.5} strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
                <path d="M9 6l6 6-6 6" />
              </svg>
              <span className="font-medium">Threads</span>
              <span className="font-mono text-xs text-text-muted">{total}</span>
              {waiting > 0 && <span className="text-xs text-text-muted">· {waiting} waiting</span>}
            </span>
          </button>
        );
      })()}

      {threadsOpen && threads.map(({ thread, protocol }) => {
        const snippet = thread.content ? thread.content.replace(/\s+/g, ' ').trim() : '(deleted)';
        return (
          <button
            key={thread.id}
            type="button"
            className={CHIP_TARGET}
            title={snippet}
            aria-label={`Open thread${protocol ? ` (${protocol.state}${protocol.yieldTo ? `, next: ${protocol.yieldTo}` : ''})` : ''}: ${snippet.slice(0, 80)}, ${thread.replyCount} ${thread.replyCount === 1 ? 'reply' : 'replies'}`}
            onClick={() => onOpenThread(thread.id)}
          >
            <span className={CHIP_PILL}>
              <svg className="h-3.5 w-3.5 shrink-0 text-accent" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
                <path d="M21 15a2 2 0 01-2 2H7l-4 4V5a2 2 0 012-2h14a2 2 0 012 2z" />
              </svg>
              {protocol && <ProtocolBadge protocol={{ ...protocol, yieldTo: undefined }} />}
              {protocol?.yieldTo && <span className="text-xs text-text-muted">→ {protocol.yieldTo}</span>}
              <span className="max-w-[10rem] truncate">{snippet}</span>
              <span className="font-mono text-xs text-text-muted">{thread.replyCount}</span>
            </span>
          </button>
        );
      })}

      {threadsOpen && hasMoreThreads && threads.length > 0 && (
        <button
          type="button"
          className={CHIP_TARGET}
          aria-label={`Show more threads${threadTotal !== undefined && threadTotal > threads.length ? ` (${threadTotal - threads.length} more)` : ''}`}
          onClick={() => { void loadMoreThreads(channelId).catch(() => {}); }}
        >
          <span className={`${CHIP_PILL} border-dashed text-text-muted group-hover:text-text`}>
            {threadTotal !== undefined && threadTotal > threads.length ? `+${threadTotal - threads.length} more` : 'More'}
          </span>
        </button>
      )}

      {sheet && (
        <SessionSheet
          key={sheet.key}
          open
          onClose={() => setSheet(null)}
          channelId={channelId}
          mode={sheet.mode}
          sessions={sessions}
          profiles={profiles}
          profilesError={profilesError}
          onChanged={() => { refresh(); }}
        />
      )}
    </div>
  );
}

/** A ring, not a filled dot, so a user's own session never reads as a hosted one. */
function OwnSessionDot({ status, working = false }: { status: OwnSessionStatus; working?: boolean }) {
  const tone = working ? 'border-online bg-online motion-safe:animate-pulse' : status === 'listening' ? 'border-online bg-online/40 motion-safe:animate-pulse' : status === 'connected' ? 'border-online' : 'border-text-dim';
  return <span aria-hidden="true" className={`inline-block h-2.5 w-2.5 shrink-0 rounded-full border-2 ${tone}`} />;
}

const THREADS_OPEN_KEY = 'agora.consoleStrip.threadsOpen';

/** Collapsed unless this browser chose to show the thread chips (#18). Storage can throw or be empty. */
function readThreadsOpen(): boolean {
  try { return localStorage.getItem(THREADS_OPEN_KEY) === '1'; } catch { return false; }
}

function writeThreadsOpen(open: boolean): void {
  try { localStorage.setItem(THREADS_OPEN_KEY, open ? '1' : '0'); } catch { /* a convenience only */ }
}

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useSocket } from '../../hooks/useSocket';
import type { AgentSessionUpdatePayload } from '../../lib/contracts/ws-events';
import { useChannelStore } from '../../stores/channelStore';
import { useMessageStore } from '../../stores/messageStore';
import { useThreadStore } from '../../stores/threadStore';
import { useAgentPresenceStore } from '../../stores/agentPresenceStore';
import { ProtocolBadge } from '../messages/ProtocolBadge';
import { latestProtocol } from '../messages/latestProtocol';
import {
  OWN_SESSION_LABEL, STATE_LABEL, compactTokens, deriveChips, listProfiles, listSessions, ownChipLabel, ownSessionChips, ownSessionDetail, resetTime,
  type AgentProfile, type AgentSession, type OwnSessionStatus,
} from './agentSessions';
import { SessionSheet, StateDot, type SheetMode } from './SessionSheet';
import { ChannelAgentsControl } from './ChannelAgents';
import { BoxModeBadge } from '../boxes/BoxModeBadge';
import { boxModeLabel } from '../boxes/boxRules';

/**
 * Console Strip (docs/planning/ui-redesign.md 6.2): one horizontally scrolling row under the
 * channel header with a chip per agent in this channel (live first), a "+ Agent" chip, and a
 * chip per active agora-collab thread. Agent chips open the Session Sheet; thread chips call
 * onOpenThread. Sessions refresh on channel change, on every agent_session notice in the
 * channel, and every 20 seconds while the page is visible.
 */

interface ConsoleStripProps {
  channelId: string;
  onOpenThread: (threadId: any) => void;
}

const POLL_MS = 20_000;
const NO_SESSIONS: AgentSession[] = [];

// The pill is 32px tall, centered in a 44px touch target.
const CHIP_TARGET = 'group flex min-h-[44px] shrink-0 items-center rounded-full focus-visible:outline-none';
const CHIP_PILL = 'flex h-8 items-center gap-1.5 whitespace-nowrap rounded-full border border-border bg-surface-hover px-3 text-[13px] text-text transition-colors group-hover:bg-bg group-focus-visible:outline-2 group-focus-visible:outline-offset-1 group-focus-visible:outline-accent';

export function ConsoleStrip({ channelId, onOpenThread }: ConsoleStripProps) {
  const stripRef = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const strip = stripRef.current;
    if (!strip) return;
    const onWheel = (event: WheelEvent) => {
      // Preserve horizontal trackpad gestures, Shift+wheel and browser zoom.
      if (event.ctrlKey || event.shiftKey || Math.abs(event.deltaY) <= Math.abs(event.deltaX)) return;
      const max = strip.scrollWidth - strip.clientWidth;
      if (max <= 0) return;
      const unit = event.deltaMode === 1 ? 16 : event.deltaMode === 2 ? strip.clientWidth : 1;
      const next = Math.max(0, Math.min(max, strip.scrollLeft + event.deltaY * unit));
      if (next === strip.scrollLeft) return;
      strip.scrollLeft = next;
      event.preventDefault();
    };
    // React's delegated wheel listener can be passive; cancellation is needed only
    // when this strip consumes a vertical wheel. At either edge, let the page scroll.
    strip.addEventListener('wheel', onWheel, { passive: false });
    return () => strip.removeEventListener('wheel', onWheel);
  }, []);
  const socket = useSocket();
  const serverId = useChannelStore(s => s.channels.get(channelId)?.serverId ?? null);
  const [loaded, setLoaded] = useState<{ channelId: string; sessions: AgentSession[] }>({ channelId, sessions: [] });
  const [sheetState, setSheet] = useState<{ mode: SheetMode; key: number; channelId: string } | null>(null);
  const [profiles, setProfiles] = useState<AgentProfile[] | null>(null);
  const [profilesError, setProfilesError] = useState('');
  const channelRef = useRef(channelId);
  useEffect(() => { channelRef.current = channelId; }, [channelId]);

  // Another channel's chips and sheet never show here, even before this channel loads.
  const sessions = loaded.channelId === channelId ? loaded.sessions : NO_SESSIONS;
  const sheet = sheetState?.channelId === channelId ? sheetState : null;

  const refresh = useCallback(() => {
    const forChannel = channelId;
    listSessions(forChannel)
      .then(list => { if (channelRef.current === forChannel) setLoaded({ channelId: forChannel, sessions: list }); })
      .catch(() => { /* keep the last good list; the next poll or notice retries */ });
  }, [channelId]);

  useEffect(() => { refresh(); }, [refresh]);
  useEffect(() => {
    if (!socket) return;
    const onSessionUpdate = (event: AgentSessionUpdatePayload) => {
      if (event.channelId === channelId) refresh();
    };
    socket.on('AgentSessionUpdate', onSessionUpdate);
    return () => { socket.off('AgentSessionUpdate', onSessionUpdate); };
  }, [socket, channelId, refresh]);

  // Poll while visible; catch up as soon as the page is shown again.
  useEffect(() => {
    let timer: ReturnType<typeof setInterval> | null = null;
    const start = () => {
      if (timer === null) timer = setInterval(() => { refresh(); }, POLL_MS);
    };
    const stop = () => {
      if (timer !== null) { clearInterval(timer); timer = null; }
    };
    const onVisibility = () => {
      if (document.visibilityState === 'visible') { refresh(); start(); } else stop();
    };
    if (document.visibilityState === 'visible') start();
    document.addEventListener('visibilitychange', onVisibility);
    return () => { stop(); document.removeEventListener('visibilitychange', onVisibility); };
  }, [refresh]);

  // Every session change posts an agent_session notice into the channel.
  const channelMessages = useMessageStore(s => s.byChannel.get(channelId));
  const lastNoticeId = useMemo(() => {
    if (!channelMessages) return undefined;
    for (let i = channelMessages.length - 1; i >= 0; i--) {
      if (channelMessages[i].systemEvent === 'agent_session') return channelMessages[i].id;
    }
    return undefined;
  }, [channelMessages]);
  // The first notice seen in a channel is history (the channel load already fetched); a later one is news.
  const seenNotice = useRef<{ channelId: string; id: string | undefined } | null>(null);
  useEffect(() => {
    const seen = seenNotice.current;
    seenNotice.current = { channelId, id: lastNoticeId };
    if (seen && seen.channelId === channelId && seen.id !== lastNoticeId && lastNoticeId !== undefined) refresh();
  }, [channelId, lastNoticeId, refresh]);

  // Active collab threads (the data ActiveThreadsBar used).
  const activeThreads = useThreadStore(s => s.activeThreads.get(channelId));
  const threadTotal = useThreadStore(s => s.threadTotals?.get(channelId));
  const hasMoreThreads = useThreadStore(s => !!s.hasMoreThreads?.get(channelId));
  const repliesByThread = useThreadStore(s => s.repliesByThread);
  const loadActiveThreads = useThreadStore(s => s.loadActiveThreads);
  const loadMoreThreads = useThreadStore(s => s.loadMoreThreads);
  useEffect(() => { void loadActiveThreads(channelId).catch(() => {}); }, [channelId, loadActiveThreads]);
  // The thread chips start collapsed behind one count chip (#18); the choice is remembered per browser
  const [threadsOpen, setThreadsOpen] = useState(readThreadsOpen);
  const toggleThreads = () => setThreadsOpen(open => { writeThreadsOpen(!open); return !open; });

  const threads = useMemo(() => (activeThreads ?? []).filter(t => !t.threadClosedAt).map(t => {
    const parent = channelMessages?.find(m => m.id === t.id);
    const cached = [...(parent ? [parent] : []), ...(repliesByThread.get(t.id) ?? [])]
      .filter(m => !t.latestProtocol || m.id >= t.latestProtocol.messageId)
      .sort((a, b) => a.id.localeCompare(b.id));
    const protocol = latestProtocol(cached) ?? t.latestProtocol ?? undefined;
    return { thread: t, protocol };
  }), [activeThreads, channelMessages, repliesByThread]);

  const chips = useMemo(() => deriveChips(sessions), [sessions]);
  const present = useAgentPresenceStore(s => s.byChannel.get(channelId));
  const ownChips = useMemo(() => ownSessionChips(present?.values() ?? [], sessions), [present, sessions]);
  // "idle 12m" and "not listening 2h" on terminal chips move on with the clock
  const [now, setNow] = useState(() => Date.now());
  useEffect(() => {
    const timer = setInterval(() => setNow(Date.now()), 60_000);
    return () => clearInterval(timer);
  }, []);

  const openStart = () => {
    setSheet({ mode: { kind: 'start' }, key: Date.now(), channelId });
    if (!serverId) { setProfilesError('Could not find this channel\'s server.'); return; }
    setProfilesError('');
    listProfiles(serverId)
      .then(setProfiles)
      .catch(() => setProfilesError('Could not load the agents on this server.'));
  };

  return (
    <div
      ref={stripRef}
      role="toolbar"
      aria-label="Agents and active threads"
      className="console-strip flex min-h-[44px] w-full min-w-0 max-w-full shrink-0 items-center gap-2 overflow-x-auto border-b border-border bg-surface/60 px-3"
    >
      {chips.map(chip => {
        const tokens = chip.session.state !== 'ended' && chip.session.tokensUsed > 0 ? compactTokens(chip.session.tokensUsed) : null;
        // A rate-limited agent says so on the chip, with the reset time (#147)
        const resets = chip.state === 'sleeping' && chip.session.sleepingUntil ? resetTime(chip.session.sleepingUntil) : null;
        return (
          <button
            key={chip.profile}
            type="button"
            className={CHIP_TARGET}
            aria-haspopup="dialog"
            aria-label={`${chip.profile}${boxModeLabel(chip.session) ? ` (${boxModeLabel(chip.session)})` : ''}: ${STATE_LABEL[chip.state].toLowerCase()}${resets ? `, resets ${resets}` : ''}${tokens ? `, ${tokens} tokens` : ''}. Open session controls`}
            onClick={() => setSheet({ mode: { kind: 'profile', profile: chip.profile }, key: Date.now(), channelId })}
          >
            <span className={CHIP_PILL}>
              <StateDot state={chip.state} />
              <span className="font-medium">{chip.profile}</span>
              <BoxModeBadge profile={chip.session} />
              {resets && <span className="text-xs text-text-muted">Sleeping · <span className="hidden sm:inline">resets </span>{resets}</span>}
              {tokens && <span className="font-mono text-xs text-text-muted">{tokens}</span>}
            </span>
          </button>
        );
      })}

      {ownChips.map(chip => {
        const working = !!chip.session?.running && chip.status !== 'offline';
        const { text: label, warn } = ownChipLabel(chip, now);
        const pill = (
          <span className={`${CHIP_PILL} border-dashed`}>
            <OwnSessionDot status={chip.status} working={working} />
            <span className="font-medium">{chip.username}</span>
            <span className={`text-xs ${warn ? 'font-medium text-warn' : 'text-text-muted'}`}>{chip.session ? `terminal · ${label}` : label}</span>
          </span>
        );
        // With a terminal session (#112) the chip opens its sheet; without one it is presence only
        return chip.session ? (
          <button
            key={`own-${chip.userId}`}
            type="button"
            className={CHIP_TARGET}
            aria-haspopup="dialog"
            title={`${OWN_SESSION_LABEL[chip.status]}. ${ownSessionDetail(chip)}`}
            aria-label={`${chip.username}: terminal session, ${label}. Open session details`}
            data-testid="own-session-chip"
            onClick={() => setSheet({ mode: { kind: 'terminal', botId: chip.userId }, key: Date.now(), channelId })}
          >
            {pill}
          </button>
        ) : (
          <span
            key={`own-${chip.userId}`}
            role="img"
            className={`${CHIP_TARGET} cursor-default`}
            title={`${OWN_SESSION_LABEL[chip.status]}. ${ownSessionDetail(chip)}`}
            aria-label={`${chip.username}: ${OWN_SESSION_LABEL[chip.status].toLowerCase()}`}
            data-testid="own-session-chip"
          >
            {pill}
          </span>
        );
      })}

      <ChannelAgentsControl key={channelId} channelId={channelId} serverId={serverId} />
      <button type="button" className={CHIP_TARGET} aria-haspopup="dialog" aria-label="Start an agent" onClick={openStart}>
        <span className={`${CHIP_PILL} border-dashed text-text-muted group-hover:text-text`}>Start agent</span>
      </button>

      {threads.length > 0 && <span aria-hidden="true" className="h-5 w-px shrink-0 bg-border" />}

      {threads.length > 0 && (() => {
        // Every open thread in the channel, not the pages loaded so far (#14)
        const total = Math.max(threadTotal ?? threads.length, threads.length);
        const waiting = threads.filter(t => t.protocol?.yieldTo || t.thread.waiting).length;
        return (
          <button
            type="button"
            className={CHIP_TARGET}
            aria-expanded={threadsOpen}
            aria-label={`Active threads (${total})${waiting ? `, ${waiting} waiting on someone` : ''}. ${threadsOpen ? 'Hide' : 'Show'} them`}
            data-testid="threads-toggle"
            onClick={toggleThreads}
          >
            <span className={CHIP_PILL}>
              <svg className={`h-3 w-3 shrink-0 text-text-muted transition-transform ${threadsOpen ? 'rotate-90' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2.5} strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
                <path d="M9 6l6 6-6 6" />
              </svg>
              <span className="font-medium">Threads</span>
              <span className="font-mono text-xs text-text-muted">{total}</span>
              {waiting > 0 && <span className="text-xs text-text-muted">· {waiting} waiting</span>}
            </span>
          </button>
        );
      })()}

      {threadsOpen && threads.map(({ thread, protocol }) => {
        const snippet = thread.content ? thread.content.replace(/\s+/g, ' ').trim() : '(deleted)';
        return (
          <button
            key={thread.id}
            type="button"
            className={CHIP_TARGET}
            title={snippet}
            aria-label={`Open thread${protocol ? ` (${protocol.state}${protocol.yieldTo ? `, next: ${protocol.yieldTo}` : ''})` : ''}: ${snippet.slice(0, 80)}, ${thread.replyCount} ${thread.replyCount === 1 ? 'reply' : 'replies'}`}
            onClick={() => onOpenThread(thread.id)}
          >
            <span className={CHIP_PILL}>
              <svg className="h-3.5 w-3.5 shrink-0 text-accent" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
                <path d="M21 15a2 2 0 01-2 2H7l-4 4V5a2 2 0 012-2h14a2 2 0 012 2z" />
              </svg>
              {protocol && <ProtocolBadge protocol={{ ...protocol, yieldTo: undefined }} />}
              {protocol?.yieldTo && <span className="text-xs text-text-muted">→ {protocol.yieldTo}</span>}
              <span className="max-w-[10rem] truncate">{snippet}</span>
              <span className="font-mono text-xs text-text-muted">{thread.replyCount}</span>
            </span>
          </button>
        );
      })}

      {threadsOpen && hasMoreThreads && threads.length > 0 && (
        <button
          type="button"
          className={CHIP_TARGET}
          aria-label={`Show more threads${threadTotal !== undefined && threadTotal > threads.length ? ` (${threadTotal - threads.length} more)` : ''}`}
          onClick={() => { void loadMoreThreads(channelId).catch(() => {}); }}
        >
          <span className={`${CHIP_PILL} border-dashed text-text-muted group-hover:text-text`}>
            {threadTotal !== undefined && threadTotal > threads.length ? `+${threadTotal - threads.length} more` : 'More'}
          </span>
        </button>
      )}

      {sheet && (
        <SessionSheet
          key={sheet.key}
          open
          onClose={() => setSheet(null)}
          channelId={channelId}
          mode={sheet.mode}
          sessions={sessions}
          profiles={profiles}
          profilesError={profilesError}
          onChanged={() => { refresh(); }}
        />
      )}
    </div>
  );
}

/** A ring, not a filled dot, so a user's own session never reads as a hosted one. */
function OwnSessionDot({ status, working = false }: { status: OwnSessionStatus; working?: boolean }) {
  const tone = working ? 'border-online bg-online motion-safe:animate-pulse' : status === 'listening' ? 'border-online bg-online/40 motion-safe:animate-pulse' : status === 'connected' ? 'border-online' : 'border-text-dim';
  return <span aria-hidden="true" className={`inline-block h-2.5 w-2.5 shrink-0 rounded-full border-2 ${tone}`} />;
}

const THREADS_OPEN_KEY = 'agora.consoleStrip.threadsOpen';

/** Collapsed unless this browser chose to show the thread chips (#18). Storage can throw or be empty. */
function readThreadsOpen(): boolean {
  try { return localStorage.getItem(THREADS_OPEN_KEY) === '1'; } catch { return false; }
}

function writeThreadsOpen(open: boolean): void {
  try { localStorage.setItem(THREADS_OPEN_KEY, open ? '1' : '0'); } catch { /* a convenience only */ }
}

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useSocket } from '../../hooks/useSocket';
import type { AgentSessionUpdatePayload } from '../../lib/contracts/ws-events';
import { useChannelStore } from '../../stores/channelStore';
import { useMessageStore } from '../../stores/messageStore';
import { useThreadStore } from '../../stores/threadStore';
import { useAgentPresenceStore } from '../../stores/agentPresenceStore';
import { ProtocolBadge } from '../messages/ProtocolBadge';
import { latestProtocol } from '../messages/latestProtocol';
import {
  OWN_SESSION_LABEL, STATE_LABEL, compactTokens, deriveChips, listProfiles, listSessions, ownChipLabel, ownSessionChips, ownSessionDetail, resetTime,
  type AgentProfile, type AgentSession, type OwnSessionStatus,
} from './agentSessions';
import { SessionSheet, StateDot, type SheetMode } from './SessionSheet';
import { ChannelAgentsControl } from './ChannelAgents';
import { BoxModeBadge } from '../boxes/BoxModeBadge';
import { boxModeLabel } from '../boxes/boxRules';

/**
 * Console Strip (docs/planning/ui-redesign.md 6.2): one horizontally scrolling row under the
 * channel header with a chip per agent in this channel (live first), a "+ Agent" chip, and a
 * chip per active agora-collab thread. Agent chips open the Session Sheet; thread chips call
 * onOpenThread. Sessions refresh on channel change, on every agent_session notice in the
 * channel, and every 20 seconds while the page is visible.
 */

interface ConsoleStripProps {
  channelId: string;
  onOpenThread: (threadId: string) => void;
}

const POLL_MS = 20_000;
const NO_SESSIONS: any = [];

// The pill is 32px tall, centered in a 44px touch target.
