        return chip.session ? (
          <button
            key={`own-${chip.userId}`}
            type="button"
            className={CHIP_TARGET}
            aria-haspopup="dialog"
            title={`${OWN_SESSION_LABEL[chip.status]}. ${ownSessionDetail(chip)}`}
            aria-label={`${chip.username}: terminal session, ${label}. Open session details`}
            data-testid="own-session-chip"
            onClick={() => setSheet({ mode: { kind: 'terminal', botId: chip.userId }, key: Date.now(), channelId })}
          >
            {pill}
          </button>
        ) : (
          <span
            key={`own-${chip.userId}`}
            role="img"
            className={`${CHIP_TARGET} cursor-default`}
            title={`${OWN_SESSION_LABEL[chip.status]}. ${ownSessionDetail(chip)}`}
            aria-label={`${chip.username}: ${OWN_SESSION_LABEL[chip.status].toLowerCase()}`}
            data-testid="own-session-chip"
          >
            {pill}
          </span>
        );
      })}

      <ChannelAgentsControl key={channelId} channelId={channelId} serverId={serverId} />
      <button type="button" className={CHIP_TARGET} aria-haspopup="dialog" aria-label="Start an agent" onClick={openStart}>
        <span className={`${CHIP_PILL} border-dashed text-text-muted group-hover:text-text`}>Start agent</span>
      </button>

      {threads.length > 0 && <span aria-hidden="true" className="h-5 w-px shrink-0 bg-border" />}

      {threads.length > 0 && (() => {
        // Every open thread in the channel, not the pages loaded so far (#14)
        const total = Math.max(threadTotal ?? threads.length, threads.length);
        const waiting = threads.filter(t => t.protocol?.yieldTo || t.thread.waiting).length;
        return (
          <button
            type="button"
            className={CHIP_TARGET}
            aria-expanded={threadsOpen}
            aria-label={`Active threads (${total})${waiting ? `, ${waiting} waiting on someone` : ''}. ${threadsOpen ? 'Hide' : 'Show'} them`}
            data-testid="threads-toggle"
            onClick={toggleThreads}
          >
            <span className={CHIP_PILL}>
              <svg className={`h-3 w-3 shrink-0 text-text-muted transition-transform ${threadsOpen ? 'rotate-90' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2.5} strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
                <path d="M9 6l6 6-6 6" />
              </svg>
              <span className="font-medium">Threads</span>
              <span className="font-mono text-xs text-text-muted">{total}</span>
              {waiting > 0 && <span className="text-xs text-text-muted">· {waiting} waiting</span>}
            </span>
          </button>
        );
      })()}

      {threadsOpen && threads.map(({ thread, protocol }) => {
        const snippet = thread.content ? thread.content.replace(/\s+/g, ' ').trim() : '(deleted)';
        return (
          <button
            key={thread.id}
            type="button"
            className={CHIP_TARGET}
            title={snippet}
            aria-label={`Open thread${protocol ? ` (${protocol.state}${protocol.yieldTo ? `, next: ${protocol.yieldTo}` : ''})` : ''}: ${snippet.slice(0, 80)}, ${thread.replyCount} ${thread.replyCount === 1 ? 'reply' : 'replies'}`}
            onClick={() => onOpenThread(thread.id)}
          >
            <span className={CHIP_PILL}>
              <svg className="h-3.5 w-3.5 shrink-0 text-accent" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
                <path d="M21 15a2 2 0 01-2 2H7l-4 4V5a2 2 0 012-2h14a2 2 0 012 2z" />
              </svg>
