          </span>
        </button>
      )}

      {sheet && (
        <SessionSheet
          key={sheet.key}
          open
          onClose={() => setSheet(null)}
          channelId={channelId}
          mode={sheet.mode}
          sessions={sessions}
          profiles={profiles}
          profilesError={profilesError}
          onChanged={() => { refresh(); }}
        />
      )}
    </div>
  );
