  | { command: 'sessions' }
  | { command: 'resume'; sessionId: string; onLive?: 'shelve' | 'keep'; tokenBudget?: number }
  | { command: 'budget'; sessionId: string; tokenBudget: number }
  | { command: 'wake'; sessionId: string };

export interface CommandResponse {
  action?: string;
