        navigate('/app');
      }
    } catch (err) {
      if (err instanceof ApiError) {
        // Every code POST /auth/login sends is worded; anything else is shown as sent
        setError(signInErrorMessage(err.code) ?? err.code);
      } else {
        setError('An unexpected error occurred.');
      }
    }
  };

  const handlePasskey = async () => {
    setError('');
    setPasskeyBusy(true);
    try {
      // A typed username narrows the prompt to that account; otherwise any passkey
      // saved for this site may answer
      await loginWithPasskey(identifier.trim() || undefined);
      navigate(useAuthStore.getState().status === 'pending' ? '/pending' : '/app');
    } catch (err) {
      const message = passkeyErrorMessage(err);
      message && setError(message);
    } finally {
      setPasskeyBusy(false);
    }
  };

  // A visitor who is already signed in (or may be: the cookie is being checked)
  // never sees the form
  if (status === 'checking') return <PageSpinner />;
  if (status === 'authenticated') return <Navigate to="/app" replace />;

  return (
    <div className="flex items-center justify-center min-h-screen px-4">
      <div className="w-full max-w-md bg-surface rounded-lg p-8 border border-border">
        <h1 className="text-2xl font-bold text-center mb-6">
          {instance?.instanceName || 'Agora'}
        </h1>

        <form onSubmit={handleSubmit} className="flex flex-col gap-4">
          <Input
            label="Username or email"
            type="text"
            value={identifier}
            onChange={(e) => setIdentifier(e.target.value)}
            required
            autoComplete="username"
            autoCapitalize="none"
            spellCheck={false}
          />

          <Input
            label="Password"
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
            autoComplete="current-password"
          />

          {error && <p className="text-sm text-danger">{error}</p>}

          <Button type="submit" fullWidth loading={status === 'loading' && !passkeyBusy}>
            Sign in
          </Button>
        </form>

        {canUsePasskey && (
          <div className="mt-3">
            <Button type="button" variant="secondary" fullWidth loading={passkeyBusy} onClick={handlePasskey}>
              Sign in with a passkey
            </Button>
          </div>
        )}

        {instance?.registrationPolicy !== 'invite_only' && (
          <p className="text-center text-text-muted text-sm mt-4">
            Don't have an account?{' '}
            <Link to="/register" className="min-h-11 md:min-h-8 inline-flex items-center px-1 text-accent hover:underline">
              Register
            </Link>
          </p>
        )}
        <NotAffiliated className="mt-6" />
      </div>
    </div>
  );
}

