            )}
          </li>
        ))}
      </ul>
      {isOwner && (
        <form className="mt-2 flex items-start gap-2" onSubmit={e => { e.preventDefault(); add(); }}>
          <div className="flex-1">
            <input className={`${INPUT} font-mono`} value={entry} placeholder="example.com or *.example.com" maxLength={255}
