  if (box.state === 'running') return { label: 'running', tone: 'bg-online/20 text-online' };
  if (box.state === 'creating') return { label: 'creating', tone: 'bg-warn/20 text-warn' };
  return { label: box.state, tone: 'bg-surface text-text-muted' };
}

