      <input
        ref={fileInputRef}
        type="file"
        multiple
        className="hidden"
        onChange={handleFileInputChange}
      />

      {agentCommands.panel}

      <ReadingAloud />

      {/* Mention autocomplete (positioned above the input) */}
      <div className="relative">
        <MentionAutocomplete
          query={mentionQuery}
          serverId={activeServerId}
