import { useDraftStore, sendDraft, type DraftKey } from '../../stores/draftStore';
import { useState, useRef, useEffect, useCallback, useMemo, type KeyboardEvent, type DragEvent } from 'react';
import { useMessageStore } from '../../stores/messageStore';
import { useAuthStore } from '../../stores/authStore';
import { useServerStore } from '../../stores/serverStore';
import { useUploadStore } from '../../stores/uploadStore';
import { useSocket } from '../../hooks/useSocket';
import { MentionAutocomplete } from '../live/MentionAutocomplete';
import { usePalette, hexToRgb } from '../../theme';
import { useAgentCommands } from './AgentCommands';
import { MicButton } from '../voice/MicButton';
import { ReadingAloud } from '../voice/ReadingAloud';
import { appendDictation } from '../voice/appendDictation';
import { UploadPreview } from './UploadPreview';

// ─── Constants ────────────────────────────────────────────────────────────────

const MAX_ATTACHMENTS = 10;

// ─── Types ───────────────────────────────────────────────────────────────────

interface FloatingMessageInputProps {
  channelId: string;
  channelName?: string;
  accentColor: string;
  isDm?: boolean;
}

// ─── Helpers ─────────────────────────────────────────────────────────────────

// ─── Component ───────────────────────────────────────────────────────────────

export function FloatingMessageInput({
  channelId,
  channelName,
  accentColor,
  isDm,
}: FloatingMessageInputProps) {
  const P = usePalette();
  const accentRgb = hexToRgb(accentColor);

  const draftKey: DraftKey = `channel:${channelId}`;
  const content = useDraftStore(s => s.drafts[draftKey] ?? '');
  const setContent = (text: string) => useDraftStore.getState().setDraft(draftKey, text);
  const [sending, setSending] = useState(false);
  const [mentionQuery, setMentionQuery] = useState('');
  const [showMentions, setShowMentions] = useState(false);
  const [dragging, setDragging] = useState(false);
  const textareaRef = useRef<any>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const lastTypingRef = useRef(0);
  const dragCounterRef = useRef(0);

  const sendMessage = useMessageStore(s => s.sendMessage);
  const user = useAuthStore(s => s.user);
  const activeServerId = useServerStore(s => s.activeServerId);
  const socket = useSocket();
  const agentCommands = useAgentCommands(channelId, () => {
    if (useDraftStore.getState().getDraft(draftKey) === content) useDraftStore.getState().clearDraft(draftKey);
  });

  // Upload store
  const addUpload = useUploadStore(s => s.addUpload);
  const removeUpload = useUploadStore(s => s.removeUpload);
  const clearCompleted = useUploadStore(s => s.clearCompleted);
  const allUploads = useUploadStore(s => s.uploads);
  const uploads = useMemo(
    () => Array.from(allUploads.values()).filter(u => u.channelId === channelId && !u.threadId),
    [allUploads, channelId],
  );
  const completedIds = useMemo(
    () => uploads.filter(u => u.status === 'done' && u.result).map(u => u.result!.id),
    [uploads],
  );

  // Auto-resize textarea (1 to 4 rows)
  useEffect(() => {
    const el = textareaRef.current;
    if (el) {
      el.style.height = 'auto';
      el.style.height = `${Math.min(el.scrollHeight, 104)}px`;
    }
  }, [content]);

  // Handle files from any source
  const handleFiles = useCallback((files: FileList | File[]) => {
    const fileArray = Array.from(files);
    const currentCount = uploads.length;
    const allowed = fileArray.slice(0, MAX_ATTACHMENTS - currentCount);
    for (const file of allowed) {
      addUpload(channelId, file);
    }
  }, [channelId, addUpload, uploads.length]);

  // Send handler
  const handleSend = async () => {
    if (sending) return;
    const trimmed = content.trim();
    const hasAttachments = completedIds.length > 0;
    if ((!trimmed && !hasAttachments) || !user) return;

    // /start, /end, /sessions, /resume go to the agent sessions route, not the channel
    if (!hasAttachments && agentCommands.tryHandle(trimmed)) {
      setShowMentions(false);
      return;
    }

    // Check if all uploads are complete
    const pending = uploads.filter(u => u.status === 'uploading');
    if (pending.length > 0) return; // Wait for uploads to finish

    setSending(true);
    const sent = await sendDraft(draftKey, () => sendMessage(
      channelId, trimmed || '', user.id, user.username,
      hasAttachments ? completedIds : undefined,
    ));
    setSending(false);
    if (sent) {
      setShowMentions(false);
      clearCompleted(channelId);
    }
  };

  // Enter to send, Shift+Enter for newline
  const handleKeyDown = (e: KeyboardEvent<HTMLTextAreaElement>) => {
    if (showMentions) return; // Let MentionAutocomplete handle keyboard events
    // The autocomplete handles its keys in the capture phase and may already have
    // closed itself by now; a handled key must not also send (#17).
    if (e.defaultPrevented || e.nativeEvent.defaultPrevented) return;
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  // Typing emission (debounced 2s) + @mention detection
  const handleChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const value = e.target.value;
    setContent(value);

    // Emit typing event (debounced to every 2 seconds)
    const now = Date.now();
    if (socket && now - lastTypingRef.current > 2000) {
      socket.emit('Typing', { channelId });
      lastTypingRef.current = now;
    }

    // Detect @mention
    const cursorPos = e.target.selectionStart;
    const textUpToCursor = value.slice(0, cursorPos);
    const mentionMatch = textUpToCursor.match(/@([\w-]*)$/);
    if (mentionMatch) {
      setMentionQuery(mentionMatch[1]);
      setShowMentions(true);
    } else {
      setShowMentions(false);
    }
  };

  const handleMentionSelect = (username: string) => {
    const el = textareaRef.current;
    if (!el) return;
    const cursorPos = el.selectionStart;
    const textUpToCursor = content.slice(0, cursorPos);
    const atIndex = textUpToCursor.lastIndexOf('@');
    if (atIndex === -1) return;

    const before = content.slice(0, atIndex);
    const after = content.slice(cursorPos);
    const newContent = `${before}@${username} ${after}`;
    setContent(newContent);
    setShowMentions(false);

    // Restore focus and cursor position
    requestAnimationFrame(() => {
      el.focus();
      const newPos = atIndex + username.length + 2; // @username + space
      el.setSelectionRange(newPos, newPos);
    });
  };

  // File input change handler
  const handleFileInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      handleFiles(e.target.files);
    }
    // Reset so the same file can be selected again
    e.target.value = '';
  };

  // Paste handler for images
  const handlePaste = (e: React.ClipboardEvent) => {
    const items = e.clipboardData?.items;
    if (!items) return;
    const files: File[] = [];
    for (const item of items) {
      if (item.kind === 'file') {
        const file = item.getAsFile();
        if (file) files.push(file);
      }
    }
    if (files.length > 0) {
      handleFiles(files);
    }
  };

  // Drag and drop handlers
  const handleDragEnter = (e: DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    dragCounterRef.current++;
    if (e.dataTransfer.types.includes('Files')) {
      setDragging(true);
    }
  };

  const handleDragLeave = (e: DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    dragCounterRef.current--;
    if (dragCounterRef.current === 0) {
      setDragging(false);
    }
  };

  const handleDragOver = (e: DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
  };

  const handleDrop = (e: DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setDragging(false);
    dragCounterRef.current = 0;
    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      handleFiles(e.dataTransfer.files);
    }
  };

  // Dictated text goes into the draft for the person to check, never straight out
  const handleDictation = (text: string) => {
    const draft = useDraftStore.getState().getDraft(draftKey);
    setContent(appendDictation(draft, text));
    requestAnimationFrame(() => {
      const el = textareaRef.current;
      if (!el) return;
      el.focus();
      el.setSelectionRange(el.value.length, el.value.length);
    });
  };

  const hasContent = content.trim().length > 0;
  const hasAttachments = completedIds.length > 0;
  const hasPendingUploads = uploads.some(u => u.status === 'uploading');
  const canSend = (hasContent || hasAttachments) && !hasPendingUploads;

  return (
    <div
      className="shrink-0 px-2.5 pt-1.5 pb-[max(0.5rem,env(safe-area-inset-bottom))] md:px-5 md:pb-4 md:pt-2"
      onDragEnter={handleDragEnter}
      onDragLeave={handleDragLeave}
      onDragOver={handleDragOver}
      onDrop={handleDrop}
    >
      {/* Hidden file input */}
      <input
        ref={fileInputRef}
        type="file"
        multiple
        className="hidden"
        onChange={handleFileInputChange}
      />

      {agentCommands.panel}

      <ReadingAloud />

      {/* Mention autocomplete (positioned above the input) */}
      <div className="relative">
        <MentionAutocomplete
          query={mentionQuery}
          serverId={activeServerId}
          onSelect={handleMentionSelect}
          onClose={() => setShowMentions(false)}
          visible={showMentions}
        />
      </div>

      {/* Pill-shaped glass-blur input container */}
      <div
        className="relative rounded-2xl transition-all"
        style={{
          background: `${P.surface}dd`,
          backdropFilter: 'blur(16px)',
          WebkitBackdropFilter: 'blur(16px)',
          border: dragging
            ? `2px dashed ${P.primary}`
            : `1px solid ${hasContent ? `rgba(${accentRgb}, 0.3)` : P.border}`,
          boxShadow: hasContent
            ? `0 0 20px rgba(${accentRgb}, 0.08)`
            : '0 2px 12px rgba(0,0,0,0.2)',
        }}
      >
        {/* Drag overlay */}
        {dragging && (
          <div className="absolute inset-0 rounded-2xl flex items-center justify-center z-10"
            style={{ backgroundColor: `${P.bg}cc` }}>
            <span className="text-sm font-medium" style={{ color: P.primaryText }}>Drop files to upload</span>
          </div>
        )}

        {/* Pending uploads preview */}
        {uploads.length > 0 && (
          <div className="flex flex-wrap gap-2 px-3 pt-2.5">
            {uploads.map(upload => (
              <UploadPreview key={upload.id} upload={upload} onRemove={removeUpload} />
            ))}
          </div>
        )}

        {/* Single row: [+ attach 44x44] [textarea 1-4 rows] [mic 44x44] [send 44x44] */}
        <div className="flex items-end gap-1.5 px-2 py-1.5 md:px-2.5 md:py-2">
          <button
            type="button"
            className="min-h-11 min-w-11 md:min-h-9 md:min-w-9 md:h-9 md:w-9 rounded-xl flex items-center justify-center shrink-0 transition-colors hover:opacity-80"
            style={{ color: P.muted }}
            title="Attach file"
            aria-label="Attach file"
            onClick={() => fileInputRef.current?.click()}
          >
            <svg
              className="h-4 w-4"
              fill="none"
              viewBox="0 0 24 24"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
            >
              <line x1="12" y1="5" x2="12" y2="19" />
              <line x1="5" y1="12" x2="19" y2="12" />
            </svg>
          </button>

          <textarea
            ref={textareaRef}
            value={content}
            onChange={handleChange}
            onKeyDown={handleKeyDown}
            onPaste={handlePaste}
            placeholder={isDm ? `Message @${channelName || 'user'}` : `Message #${channelName || 'channel'}`}
            className="flex-1 bg-transparent text-[16px] md:text-[15px] leading-[1.4] outline-none min-w-0 py-2 md:py-1.5 px-1 resize-none overflow-y-auto placeholder:text-text-muted/70"
            style={{ color: P.text, caretColor: accentColor, maxHeight: 104 }}
            rows={1}
            maxLength={4000}
            disabled={!user}
          />

          <MicButton channelId={channelId} onText={handleDictation} />

          {/* Solid primary Send button */}
          <button
            type="button"
            onClick={handleSend}
            disabled={!canSend || !user}
            className="min-h-11 min-w-11 md:min-h-9 md:min-w-9 md:h-9 md:w-9 rounded-xl flex items-center justify-center shrink-0 transition-all disabled:cursor-not-allowed"
            style={{
              background: canSend ? P.primary : P.bg,
              color: canSend ? P.onPrimary : P.muted,
              opacity: canSend ? 1 : 0.5,
            }}
            title="Send message"
            aria-label="Send message"
          >
            <svg
              className="h-4 w-4"
              fill="none"
              viewBox="0 0 24 24"
              stroke="currentColor"
              strokeWidth="2.5"
              strokeLinecap="round"
              strokeLinejoin="round"
            >
              <line x1="22" y1="2" x2="11" y2="13" />
              <polygon points="22 2 15 22 11 13 2 9 22 2" />
            </svg>
          </button>
        </div>
      </div>
    </div>
  );
}

