// ─── Constants ────────────────────────────────────────────────────────────────

const MAX_ATTACHMENTS = 10;

// ─── Types ───────────────────────────────────────────────────────────────────

interface FloatingMessageInputProps {
  channelId: string;
  channelName?: string;
  accentColor: string;
  isDm?: boolean;
}

// ─── Helpers ─────────────────────────────────────────────────────────────────

// ─── Component ───────────────────────────────────────────────────────────────

export function FloatingMessageInput({
  channelId,
