        updatedAt: p.updatedAt, updatedBy: p.updatedBy } : prev);
      if (!dirty.current) setDraft(p.instructions);
    };
    socket.on('ChannelProjectUpdate', onUpdate);
    return () => { socket.off('ChannelProjectUpdate', onUpdate); };
  }, [socket, channelId]);

