                {project.verify && (
                  <button type="button" className={button} style={{ background: P.surface, border: `1px solid ${P.border}`, color: P.text }}
                    disabled={busy} onClick={() => save(() => projectApi.setVerify(channelId, null), 'Verify turned off.')}>
