import { MessageContent } from './MessageContent';
import { FileAttachment } from './FileAttachment';

interface Counts { passed: number; failed: number; skipped: number; durationMs?: number }
interface ReportData {
  title?: string;
  summary?: string | null;
  summarySource?: 'model' | 'computed' | null;
  totals?: Counts;
  suites?: (Counts & { name: string })[];
  failures?: { name: string; suite?: string; message: string }[];
}

const SUITES_SHOWN = 8;

export function duration(ms?: number): string {
  if (ms === undefined || ms === null) return '';
  if (ms < 1000) return `${ms} ms`;
  const s = ms / 1000;
  return s < 60 ? `${s.toFixed(1)} s` : `${Math.floor(s / 60)} min ${Math.round(s % 60)} s`;
}

/** Proportional passed / failed / skipped bar. */
function StackedBar({ counts, className = 'h-2.5' }: { counts: Counts; className?: string }) {
  const total = counts.passed + counts.failed + counts.skipped;
  // Any non-zero segment stays visible (3 failures in 2,000 tests shouldn't vanish)
  const seg = (n: number) => ({ width: total ? `${(n / total) * 100}%` : '0%', minWidth: n > 0 ? 4 : 0 });
  return (
    <div
      className={`flex w-full overflow-hidden rounded-full bg-surface-hover ${className}`}
      role="img"
      aria-label={`${counts.passed} passed, ${counts.failed} failed, ${counts.skipped} skipped`}
    >
      <div className="bg-online shrink" style={seg(counts.passed)} />
      <div className="bg-danger shrink-0" style={seg(counts.failed)} />
      <div className="bg-warn/70 shrink-0" style={seg(counts.skipped)} />
    </div>
  );
}

/**
 * Results card for a test run (WBS 4.1), drawn from the validated data a run posted
 * through the capability gateway. The full report is the attached Markdown file.
 */
export function ReportCard({ message }: { message: Message }) {
  const data = (message.systemData ?? {}) as ReportData;
  const totals = data.totals ?? { passed: 0, failed: 0, skipped: 0 };
  const suites = data.suites ?? [];
  const failures = data.failures ?? [];
  const total = totals.passed + totals.failed + totals.skipped;
  const passRate = total ? Math.round((totals.passed / total) * 1000) / 10 : 0;
  const failed = totals.failed > 0;
  const [allSuites, setAllSuites] = useState(false);
  const shownSuites = allSuites ? suites : suites.slice(0, SUITES_SHOWN);

  return (
    <div className="mx-4 my-2 rounded-lg border border-border bg-surface/60 px-4 py-3">
      <div className="flex items-center gap-2 mb-2 min-w-0">
        <svg className="h-4 w-4 text-accent shrink-0" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round">
          <path d="M9 11l3 3L22 4" /><path d="M21 12v7a2 2 0 01-2 2H5a2 2 0 01-2-2V5a2 2 0 012-2h11" />
        </svg>
        <span className="text-[15px] font-semibold text-text truncate">{data.title || 'Test report'}</span>
        <span className={`px-1.5 py-0.5 rounded text-[11px] font-semibold leading-none shrink-0 ${failed ? 'bg-danger/20 text-danger' : 'bg-online/20 text-online'}`}>
          {failed ? 'FAILED' : 'PASSED'}
        </span>
        {message.authorUsername && <span className="ml-auto text-[11px] text-text-muted shrink-0">by {message.authorUsername}</span>}
      </div>

      <div className="flex items-baseline gap-x-4 gap-y-1 flex-wrap mb-1.5 text-[13px]">
        <span className="text-[22px] font-semibold text-text tabular-nums">{passRate}%</span>
        <span className="text-text-muted tabular-nums"><span className="text-online font-medium">{totals.passed}</span> passed</span>
        <span className="text-text-muted tabular-nums"><span className={failed ? 'text-danger font-medium' : ''}>{totals.failed}</span> failed</span>
        <span className="text-text-muted tabular-nums">{totals.skipped} skipped</span>
        {totals.durationMs !== undefined && <span className="text-text-muted tabular-nums">{duration(totals.durationMs)}</span>}
      </div>
      <StackedBar counts={totals} />

      {data.summary && (
        <div className="mt-3">
          {data.summarySource === 'model' && <div className="text-[11px] font-semibold text-text-muted mb-0.5">AI summary</div>}
          <MessageContent content={data.summary} />
        </div>
      )}

      {suites.length > 0 && (
        <div className="mt-3">
          <div className="text-[13px] font-semibold text-text-muted mb-1">Suites</div>
          <ul className="space-y-1">
            {shownSuites.map(s => (
              <li key={s.name} className="grid grid-cols-[minmax(0,1fr)_7.5rem] sm:grid-cols-[minmax(0,1fr)_6rem_7.5rem] items-center gap-x-2 text-[13px]">
                <span className={`col-span-2 sm:col-span-1 truncate font-mono ${s.failed ? 'text-danger' : 'text-text-muted'}`} title={s.name}>{s.name}</span>
                <StackedBar counts={s} className="h-1.5" />
                <span className="text-text-muted tabular-nums whitespace-nowrap text-right text-[11px]">
                  {s.passed}/{s.passed + s.failed + s.skipped}{s.durationMs !== undefined ? ` · ${duration(s.durationMs)}` : ''}
                </span>
              </li>
            ))}
          </ul>
          {suites.length > SUITES_SHOWN && (
            <button className="mt-1 min-h-9 text-[13px] text-primary-text hover:underline" onClick={() => setAllSuites(v => !v)}>
              {allSuites ? 'Show fewer' : `Show all ${suites.length} suites`}
            </button>
          )}
        </div>
      )}

      {failures.length > 0 && (
        <div className="mt-3">
          <div className="text-[13px] font-semibold text-text-muted mb-1">
            Failures{totals.failed > failures.length ? ` (first ${failures.length} of ${totals.failed})` : ''}
          </div>
          <div className="space-y-1">
            {failures.map((f, i) => (
              <details key={i} className="rounded border border-border bg-bg/60">
                <summary className="cursor-pointer px-2 py-1.5 text-[13px] text-text break-words">
                  {f.suite && <span className="text-text-muted">{f.suite} › </span>}{f.name}
                </summary>
                <pre className="max-h-60 overflow-auto px-2 pb-2 text-[11px] text-text-muted font-mono whitespace-pre-wrap break-words">{f.message}</pre>
              </details>
            ))}
          </div>
        </div>
      )}

      {message.attachments && message.attachments.length > 0 && (
        <div className="mt-3 flex flex-col gap-1">
          {message.attachments.map(att => <FileAttachment key={att.id} attachment={att} />)}
        </div>
      )}
    </div>
  );
}

import { useState } from 'react';
import type { Message } from '../../stores/messageStore';
import { runtimeApi, ApiError } from '../../lib/api';
import { Button } from '../../components/ui/Button';
import { MessageContent } from './MessageContent';

/**
 * System messages from the sandboxed runtime: the approval request for a run, the
 * result summary when it finishes, and the notice when a tripwire pauses the bot. The server enforces who may approve; the
 * buttons are shown to everyone who can see the thread and fail with a message if
 * the viewer lacks Manage Bots.
 */
export function RuntimeCard({ message }: { message: Message }) {
  const data = (message.systemData ?? {}) as { kind?: any; runId?: string; status?: string; capabilities?: string[] };
  const runId = data.runId;
  const [code, setCode] = useState<string | null>(null);
  const [showCode, setShowCode] = useState(false);
  const [busy, setBusy] = useState<'approve' | 'deny' | 'code' | null>(null);
  const [error, setError] = useState('');

  const fail = (err: unknown, fallback: string) => setError(err instanceof ApiError ? err.code : fallback);

  async function toggleCode() {
    if (!runId) return;
    if (showCode) { setShowCode(false); return; }
    if (code === null) {
      setBusy('code');
      try { setCode(await runtimeApi.code(runId)); } catch (err) { fail(err, 'Could not load code'); setBusy(null); return; }
      setBusy(null);
    }
    setShowCode(true);
  }

  async function review(action: 'approve' | 'deny') {
    if (!runId) return;
    setBusy(action);
    setError('');
    try {
      await (action === 'approve' ? runtimeApi.approve(runId) : runtimeApi.deny(runId));
    } catch (err) {
      fail(err, `Could not ${action} the run`);
    } finally {
      setBusy(null);
    }
  }

  const isApproval = data.kind === 'runtime_approval';
  const pending = isApproval && data.status === 'pending';
  const statusTone: Record<string, string> = {
    pending: 'bg-warn/20 text-warn', approved: 'bg-online/20 text-online', denied: 'bg-danger/20 text-danger',
    succeeded: 'bg-online/20 text-online', failed: 'bg-danger/20 text-danger', timeout: 'bg-warn/20 text-warn',
    killed: 'bg-danger/20 text-danger', error: 'bg-danger/20 text-danger', paused: 'bg-danger/20 text-danger',
  };

  return (
    <div className="mx-4 my-2 rounded-lg border border-border bg-surface/60 px-4 py-3">
      <div className="flex items-center gap-2 mb-1">
        <svg className="h-4 w-4 text-accent shrink-0" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round">
          <polyline points="16 18 22 12 16 6" /><polyline points="8 6 2 12 8 18" />
        </svg>
        <span className="text-sm font-semibold text-text whitespace-nowrap">
          {isApproval ? 'Code run request' : data.kind === 'runtime_tripwire' ? 'Bot paused by tripwire' : 'Code run result'}
        </span>
        {data.status && (
          <span className={`px-1.5 py-0.5 rounded text-[10px] font-semibold leading-none ${statusTone[data.status] ?? 'bg-surface-hover text-text-muted'}`}>
            {data.status.toUpperCase()}
          </span>
        )}
      </div>
      {runId && <div className="text-[11px] text-text-dim font-mono mb-1 break-all">{runId}</div>}

      <div className="text-sm text-text-muted space-y-1">
        {splitFences(message.content ?? '').map((part, i) => part.code
          ? <pre key={i} className="max-h-60 overflow-auto rounded bg-bg p-2 text-xs text-text font-mono whitespace-pre-wrap break-words">{part.text}</pre>
          : <MessageContent key={i} content={part.text} />)}
      </div>

      {runId && (
        // Phone: full-width 44px buttons stacked, so Approve and Deny can't be mis-tapped. Desktop unchanged.
        <div className="mt-2 flex flex-col gap-2 md:flex-row md:flex-wrap md:items-center">
          <Button variant="secondary" onClick={toggleCode} loading={busy === 'code'} className={TOUCH}>
            {showCode ? 'Hide code' : 'View code'}
          </Button>
          {pending && (
            <>
              <Button onClick={() => review('approve')} loading={busy === 'approve'} className={TOUCH}>Approve</Button>
              <Button variant="danger" onClick={() => review('deny')} loading={busy === 'deny'} className={TOUCH}>Deny</Button>
            </>
          )}
          {error && <span className="text-danger text-sm" role="alert">{error}</span>}
        </div>
      )}

      {showCode && code !== null && (
        <pre className="mt-2 max-h-80 overflow-auto rounded bg-bg p-3 text-xs text-text font-mono whitespace-pre-wrap break-all">{code}</pre>
      )}
    </div>
  );
}

const TOUCH = 'min-h-[44px] w-full md:min-h-0 md:w-auto';

/** Split text on ``` fences so run output wraps instead of scrolling sideways. */
function splitFences(text: string): { text: string; code: boolean }[] {
  const parts = text.split(/```\n?/);
  return parts
    .map((t, i) => ({ text: i % 2 === 1 ? t.replace(/\n$/, '') : t.trim(), code: i % 2 === 1 }))
    .filter(p => p.text.length > 0);
}

