          )}
          {error && <span className="text-danger text-sm" role="alert">{error}</span>}
        </div>
      )}

      {showCode && code !== null && (
        <pre className="mt-2 max-h-80 overflow-auto rounded bg-bg p-3 text-xs text-text font-mono whitespace-pre-wrap break-all">{code}</pre>
