    </div>
  );
}

const TOUCH = 'min-h-[44px] w-full md:min-h-0 md:w-auto';

/** Split text on ``` fences so run output wraps instead of scrolling sideways. */
export function splitFences(text: string): { text: string; code: boolean }[] {
  const parts = text.split(/```\n?/);
  return parts
    .map((t, i) => ({ text: i % 2 === 1 ? t.replace(/\n$/, '') : t.trim(), code: i % 2 === 1 }))
    .filter(p => p.text.length > 0);
}

