            serverId={instanceServerId}
            adapters={state.adapters}
            providers={state.providers}
            agents={state.agents}
            budget={state.agentBudget}
            channels={state.channels}
            onChanged={reload}
          />
          <VoiceSection
            // Re-seed the form whenever the saved settings or the stt/tts routes change
            key={JSON.stringify(state.voice)}
            serverId={instanceServerId}
            settings={state.voice}
            onChanged={reload}
          />
          <DecisionsSection
            // Re-seed the form whenever the saved settings or the decide route change
            key={JSON.stringify({ ...state.decisions, today: undefined })}
            serverId={instanceServerId}
            settings={state.decisions}
            onChanged={reload}
          />
          <TagsSection
