import { useCallback, useEffect, useState } from 'react';
import { useServerStore } from '../../stores/serverStore';
import { api, serverApi, ApiError } from '../../lib/api';
import type { Channel } from '../../lib/contracts/server';
import { Button } from '../../components/ui/Button';
import { NotAffiliated } from '../../components/ui/NotAffiliated';
import { authLabel } from '../agents/agentSessions';
import { ChatGPTPlanConnect, type PlanConnection } from './ChatGPTPlanConnect';
import { useAuthStore } from '../../stores/authStore';
import { BoxesSection } from '../boxes/BoxesSection';
import { BoxModeBadge } from '../boxes/BoxModeBadge';

/**
 * Agent hosts and agents (docs/planning/agent-sessions-wbs.md, S6). The owner registers the
 * machine that runs agents (a host) and creates agents on it; members then use /start in a
 * channel. Tokens are shown once and go into the host's config file, never into a channel.
 */

/** kind 'box': the agora-host inside a box (docs/agent-boxes.md §8.1); listed under Boxes, not here. */
interface Host { id: any; name: string; createdAt: string; lastSeenAt: string | null; revokedAt: string | null; kind?: 'machine' | 'box' }
interface Profile {
  id: string; name: string; botId: string; hostId: string; adapter: 'codex' | 'claude' | 'gemini' | 'opencode';
  model: string | null; effort: string | null; workdirAlias: string; workspaceId?: string;
  wakeBudget: number; tokenBudget: number; runTimeoutSec: number;
  toolPresets?: string[]; allowedTools?: string[];
  /** Reported by the host at start (docs/provider-terms.md); subscription until then. */
  authMode?: 'subscription' | 'api_key' | 'siwc'; apiKeyEnv?: string | null; runApproval?: boolean; authReportedAt?: string | null;
  /** 'siwc' only: whose ChatGPT plan it runs on (docs/codex-chatgpt-plan.md). */
  planOwnerId?: string | null;
  /** Its host is a box (docs/agent-boxes.md §10); otherwise it runs unboxed on a machine. */
  boxed?: boolean; hostMode?: boolean;
}

const EFFORTS = ['', 'low', 'medium', 'high', 'xhigh'];

/** Built-in tool presets (agora-host/src/presets.ts); the host config can redefine them. */
const PRESETS: { name: string; label: string; detail: string }[] = [
  { name: 'readonly', label: 'Read-only', detail: 'read files and git history' },
  { name: 'dev', label: 'Dev', detail: 'edit files, git, gh, npm' },
  { name: 'research', label: 'Research', detail: 'web search and fetch' },
];
/** Same rule shape the server accepts: a Claude permission rule or a Codex word (write, network, web_search). */
const TOOL_RULE = /^[A-Za-z][A-Za-z0-9_]{0,99}(\([^(),\r\n]{1,200}\))?$/;
const input = 'min-h-11 md:min-h-9 bg-bg border border-border rounded px-3 py-1.5 text-sm text-text placeholder:text-text-muted/70 focus:outline-none focus:ring-2 focus:ring-primary';

function errorText(err: unknown): string {
  if (err instanceof ApiError) return err.status === 403 ? 'Only the server owner can do this.' : err.code;
  return 'Request failed';
}

function OnceToken({ label, token, onDone }: { label: string; token: string; onDone: () => void }) {
  return (
    <div className="mb-4 rounded border border-primary/50 bg-primary/10 p-3 text-sm">
      <p className="mb-2 text-text">{label} It is shown only now; put it in the host's config file.</p>
      <code className="block break-all rounded bg-bg p-2 font-mono text-xs text-text select-all">{token}</code>
      <div className="mt-2 flex gap-2">
        <Button variant="secondary" onClick={() => { void navigator.clipboard?.writeText(token); }}>Copy</Button>
        <Button variant="secondary" onClick={onDone}>Done</Button>
      </div>
    </div>
  );
}

export function AgentSessionsSettings() {
  const serverId = useServerStore(s => s.instanceServerId);
  const ownerId = useServerStore(s => (serverId ? s.servers.get(serverId)?.ownerId : undefined));
  const userId = useAuthStore(s => s.user?.id);
  const [hosts, setHosts] = useState<Host[]>([]);
  const [profiles, setProfiles] = useState<Profile[]>([]);
  const [channels, setChannels] = useState<Channel[]>([]);
  const [plans, setPlans] = useState<PlanConnection[]>([]);
  const [error, setError] = useState('');
  const [secret, setSecret] = useState<{ label: string; token: string } | null>(null);
  const [reloadKey, setReloadKey] = useState(0);
  const load = useCallback(() => setReloadKey(k => k + 1), []);

  useEffect(() => {
    if (!serverId) return;
    let cancelled = false;
    Promise.all([
      api.get<Host[]>(`/servers/${serverId}/agent-hosts`),
      api.get<Profile[]>(`/servers/${serverId}/agent-profiles`),
      serverApi.getChannels(serverId),
      // ChatGPT plan connections; an older server without them just shows none
      api.get<PlanConnection[]>(`/servers/${serverId}/agent-plans`).catch(() => [] as PlanConnection[]),
    ]).then(([h, p, c, pl]) => {
      if (cancelled) return;
      setHosts(h);
      setProfiles(p);
      setPlans(pl);
      setChannels(c.filter(ch => ch.channelType === 3));
      setError('');
    }).catch(err => { if (!cancelled) setError(errorText(err)); });
    return () => { cancelled = true; };
  }, [serverId, reloadKey]);

  if (!serverId) return null;
  // Box hosts are managed with their box; agents are created on machine hosts here
  const machineHosts = hosts.filter(h => h.kind !== 'box');
  const activeHosts = machineHosts.filter(h => !h.revokedAt);
  const isOwner = !!userId && !!ownerId && userId.trim() === ownerId.trim();

  return (
    <div className="max-w-3xl">
      <h2 className="text-xl font-bold text-text mb-2">Agents</h2>
      <p className="text-text-muted text-sm mb-6">
        An agent host runs on the machine with your agent CLIs and wakes agents when they are addressed. Create a host,
        put its token in the host's config, then create agents on it. In a channel, <code>/start &lt;agent&gt;</code> starts a session.
      </p>
      {error && <p className="text-danger text-sm mb-4">{error}</p>}
      {secret && <OnceToken label={secret.label} token={secret.token} onDone={() => setSecret(null)} />}

      <p className="text-text-muted text-xs mb-6">
        Each agent runs its CLI on your own login (<em>subscription</em>) or on an API key, as set in the host's config.
        Personal subscriptions are for one person, so only you can wake a subscription agent; give agents that other
        members wake an API key. A Codex agent can also run on a ChatGPT plan through Sign in with ChatGPT; only the
        person who connected their plan can wake it. See docs/provider-terms.md and docs/codex-chatgpt-plan.md.
      </p>

      <BoxesSection serverId={serverId} channels={channels} isOwner={isOwner} />
      <HostsSection serverId={serverId} hosts={machineHosts} onChange={load} onToken={setSecret} onError={setError} />
      <AgentsSection serverId={serverId} hosts={activeHosts} allHosts={hosts} profiles={profiles} channels={channels} plans={plans}
        onChange={load} onToken={setSecret} onError={setError} />
      <NotAffiliated className="mt-8" />
    </div>
  );
}

function HostsSection({ serverId, hosts, onChange, onToken, onError }: {
  serverId: string; hosts: Host[]; onChange: () => void;
  onToken: (s: { label: string; token: string }) => void; onError: (e: string) => void;
}) {
  const [name, setName] = useState('');
  const create = async () => {
    try {
      const res = await api.post<{ host: Host; token: string }>(`/servers/${serverId}/agent-hosts`, { name: name.trim() });
      setName('');
      onToken({ label: `Host token for "${res.host.name}".`, token: res.token });
      onChange();
    } catch (err) { onError(errorText(err)); }
  };
  const revoke = async (h: Host) => {
    if (!confirm(`Revoke host "${h.name}"? Its token stops working at once and its agents stop waking.`)) return;
    try { await api.delete(`/servers/${serverId}/agent-hosts/${h.id}`); onChange(); } catch (err) { onError(errorText(err)); }
  };
  return (
    <section className="mb-8">
      <h3 className="text-lg font-semibold text-text mb-3">Hosts</h3>
      <ul className="mb-3 flex flex-col gap-1">
        {hosts.length === 0 && <li className="text-text-muted text-sm">No hosts yet.</li>}
        {hosts.map(h => (
          <li key={h.id} className="flex items-center justify-between rounded border border-border bg-surface px-3 py-2 text-sm">
            <span className={h.revokedAt ? 'text-text-muted line-through' : 'text-text'}>
              {h.name}
              <span className="ml-2 text-xs text-text-muted">
                {h.revokedAt ? 'revoked' : h.lastSeenAt ? `last seen ${new Date(h.lastSeenAt).toLocaleString()}` : 'never connected'}
              </span>
            </span>
            {!h.revokedAt && <button className="min-h-11 md:min-h-8 px-2 text-xs text-danger hover:underline" onClick={() => void revoke(h)}>Revoke</button>}
          </li>
        ))}
      </ul>
      <div className="flex gap-2">
        <input className={input} placeholder="Host name, e.g. my-pc" value={name} maxLength={64} onChange={e => setName(e.target.value)} />
        <Button onClick={() => void create()} disabled={!name.trim()}>Create host</Button>
      </div>
    </section>
  );
}

function AgentsSection({ serverId, hosts, allHosts, profiles, channels, plans, onChange, onToken, onError }: {
  serverId: string; hosts: Host[]; allHosts: Host[]; profiles: Profile[]; channels: Channel[]; plans: PlanConnection[]; onChange: () => void;
  onToken: (s: { label: string; token: string }) => void; onError: (e: string) => void;
}) {
  const [form, setForm] = useState({ name: '', adapter: 'codex', hostId: '', workdirAlias: 'agora', workspaceId: 'primary', model: '', effort: 'high', channelId: '' });
  // A profile on a machine host runs unboxed; the owner confirms that (docs/agent-boxes.md §10)
  const [unboxedAck, setUnboxedAck] = useState(false);
  const set = (k: keyof typeof form) => (e: { target: { value: string } }) => setForm(f => ({ ...f, [k]: e.target.value }));
  const hostId = form.hostId || hosts[0]?.id || '';
  const opencode = form.adapter === 'opencode';

  const create = async () => {
    try {
      const res = await api.post<{ bot: { username: string }; token: string }>(`/servers/${serverId}/agents`, {
        name: form.name.trim().toLowerCase(), adapter: form.adapter, hostId, workdirAlias: form.workdirAlias.trim(),
        workspaceId: form.workspaceId.trim().toLowerCase(), hostModeAck: true,
        ...(form.model.trim() ? { model: form.model.trim() } : {}),
        ...(form.effort ? { effort: form.effort } : {}),
        ...(form.channelId ? { channelId: form.channelId } : {}),
      });
      setForm(f => ({ ...f, name: '' }));
      setUnboxedAck(false);
      onToken({ label: `Bot token for agent "${res.bot.username}".`, token: res.token });
      onChange();
    } catch (err) { onError(errorText(err)); }
  };

  return (
    <section>
      <h3 className="text-lg font-semibold text-text mb-3">Agents</h3>
      <ul className="mb-4 flex flex-col gap-2">
        {profiles.length === 0 && <li className="text-text-muted text-sm">No agents yet.</li>}
        {profiles.map(p => (
          <ProfileRow key={p.id} serverId={serverId} profile={p} host={allHosts.find(h => h.id === p.hostId && !h.revokedAt)} plan={plans.find(x => x.profileId === p.id)}
            onChange={onChange} onError={onError} />
        ))}
      </ul>

      {hosts.length === 0 ? (
        <p className="text-text-muted text-sm">Create a host first.</p>
      ) : (
        <div className="rounded border border-border bg-surface p-3">
          <h4 className="mb-2 text-sm font-semibold text-text">Create agent</h4>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 text-sm">
            <label className="flex flex-col gap-1 text-text-muted">Name (bot and /start name)
              <input className={input} value={form.name} maxLength={32} placeholder="codex" onChange={set('name')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">CLI
              <select className={input} value={form.adapter} onChange={set('adapter')}>
                <option value="codex">Codex</option>
                <option value="claude">Claude Code</option>
                {/* The host runs it over ACP (gemini --acp) and only with an API key */}
                <option value="gemini">Gemini CLI (ACP, API key)</option>
                {/* opencode acp on an OpenRouter key: any OpenRouter model, one model per agent */}
                <option value="opencode">opencode (ACP, OpenRouter key)</option>
              </select>
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Host
              <select className={input} value={hostId} onChange={set('hostId')}>
                {hosts.map(h => <option key={h.id} value={h.id}>{h.name}</option>)}
              </select>
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Workdir alias (mapped to a folder in the host config)
              <input className={input} value={form.workdirAlias} maxLength={64} onChange={set('workdirAlias')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">{opencode ? 'OpenRouter model ID (required)' : 'Model (optional)'}
              <input className={input} value={form.model} maxLength={64} placeholder={opencode ? 'qwen/qwen3-coder' : 'gpt-6.1-sol'} onChange={set('model')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Workspace ID (same repository = same ID across hosts)
              <input className={input} value={form.workspaceId} maxLength={64} onChange={set('workspaceId')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Effort
              <select className={input} value={form.effort} onChange={set('effort')}>
                {EFFORTS.map(e => <option key={e} value={e}>{e || 'CLI default'}</option>)}
              </select>
            </label>
            <label className="sm:col-span-2 flex flex-col gap-1 text-text-muted">Add to channel (optional)
              <select className={input} value={form.channelId} onChange={set('channelId')}>
                <option value="">None</option>
                {channels.map(c => <option key={c.id} value={c.id}>#{c.name}</option>)}
              </select>
            </label>
          </div>
          <label className="mt-3 flex min-h-11 md:min-h-8 items-start gap-2 text-sm text-text">
            <input type="checkbox" className="mt-1" checked={unboxedAck} onChange={e => setUnboxedAck(e.target.checked)} />
            <span>Run unboxed on this machine (it can read and change your files). <span className="text-text-muted">Only you can wake an unboxed agent. For anything that doesn&apos;t need this machine, create a box instead.</span></span>
          </label>
          <div className="mt-3">
            <Button onClick={() => void create()} disabled={!unboxedAck || !/^[a-z0-9][a-z0-9_-]*$/i.test(form.name.trim()) || !form.workdirAlias.trim() || (opencode && !form.model.trim())}>
              Create agent
            </Button>
          </div>
        </div>
      )}
    </section>
  );
}

function ProfileRow({ serverId, profile, host, plan, onChange, onError }: {
  serverId: string; profile: Profile; host: Host | undefined; plan?: PlanConnection; onChange: () => void; onError: (e: string) => void;
}) {
  const [model, setModel] = useState(profile.model ?? '');
  const [effort, setEffort] = useState(profile.effort ?? '');
  const [workspaceId, setWorkspaceId] = useState(profile.workspaceId ?? 'primary');
  const [wakeBudget, setWakeBudget] = useState(String(profile.wakeBudget));
  const validWakeBudget = Number.isInteger(Number(wakeBudget)) && Number(wakeBudget) >= 1 && Number(wakeBudget) <= 100000;
  const dirty = model !== (profile.model ?? '') || effort !== (profile.effort ?? '') || workspaceId !== (profile.workspaceId ?? 'primary') || wakeBudget !== String(profile.wakeBudget);
  // opencode's own default is an OpenCode Zen model, so an opencode agent always names one
  const opencode = profile.adapter === 'opencode';
  const validModel = !opencode || !!model.trim();

  const save = async () => {
    try {
      if (!validWakeBudget || !validModel) return;
      await api.patch(`/servers/${serverId}/agent-profiles/${profile.id}`, { model: model.trim() || null, effort: effort || null, workspaceId: workspaceId.trim().toLowerCase(), wakeBudget: Number(wakeBudget) });
      onChange();
    } catch (err) { onError(errorText(err)); }
  };
  const remove = async () => {
    if (!confirm(`Delete agent profile "${profile.name}"? Its bot stays; end its sessions first.`)) return;
    try { await api.delete(`/servers/${serverId}/agent-profiles/${profile.id}`); onChange(); } catch (err) { onError(errorText(err)); }
  };

  return (
    <li className="rounded border border-border bg-surface px-3 py-2 text-sm">
      <div className="flex items-center justify-between">
        <span className="text-text">
          <span className="font-medium">{profile.name}</span>
          <BoxModeBadge profile={profile} className="ml-2" />
          <span className="ml-2 text-xs text-text-muted">
            {profile.adapter} · {host?.name ?? 'revoked host'} · workdir {profile.workdirAlias} · {profile.wakeBudget} wakes · {profile.tokenBudget.toLocaleString()} tokens per session
          </span>
          <AuthBadge profile={profile} />
        </span>
        <button className="min-h-11 md:min-h-8 px-2 text-xs text-danger hover:underline" onClick={() => void remove()}>Delete</button>
      </div>
      <div className="mt-2 flex flex-wrap items-center gap-2">
        <label className="flex flex-col text-xs text-text-muted">Workspace ID (end sessions before changing)
          <input className={input} value={workspaceId} maxLength={64} onChange={e => setWorkspaceId(e.target.value)} />
        </label>
        <input className={input} value={model} placeholder={opencode ? 'OpenRouter model ID (required)' : 'model (CLI default)'} maxLength={64}
          aria-label={`Model for ${profile.name}`} onChange={e => setModel(e.target.value)} />
        <select className={input} value={effort} onChange={e => setEffort(e.target.value)}>
          {EFFORTS.map(e => <option key={e} value={e}>{e || 'CLI default'}</option>)}
        </select>
        <label className="flex flex-col text-xs text-text-muted">Wake budget per session
          <input className={input} type="number" min={1} max={100000} step={1} value={wakeBudget}
            onChange={e => setWakeBudget(e.target.value)} aria-label={`Wake budget for ${profile.name}`} />
        </label>
        {dirty && <Button variant="secondary" disabled={!validWakeBudget || !validModel} onClick={() => void save()}>Save</Button>}
      </div>
      {/* A box logs its CLI in from its Boxes entry instead */}
      {profile.adapter === 'codex' && host && host.kind !== 'box' && !profile.boxed && (
        <ChatGPTPlanConnect serverId={serverId} profileId={profile.id} hostName={host.name} plan={plan}
          siwcMode={profile.authMode === 'siwc'} onChange={onChange} />
      )}
      <ToolPermissions serverId={serverId} profile={profile} onChange={onChange} onError={onError} />
    </li>
  );
}

/** How the agent's CLI signs in, as its host reported it (docs/provider-terms.md). */
function AuthBadge({ profile }: { profile: Profile }) {
  const mode = profile.authMode ?? 'subscription';
  const tone = mode === 'api_key' ? 'bg-online/20 text-online' : 'bg-warn/20 text-warn';
  const detail = !profile.authReportedAt
    ? 'not reported by its host yet, so treated as a subscription'
    : mode === 'api_key' ? `key from ${profile.apiKeyEnv}`
    : mode === 'siwc' ? (profile.planOwnerId ? 'only the person who connected their plan can wake it' : 'no ChatGPT plan connected yet')
    : 'only you can wake it';
  return (
    <span className="mt-1 flex flex-wrap items-center gap-2 text-xs text-text-muted" data-testid={`auth-${profile.name}`}>
      <span className={`rounded px-1.5 py-0.5 font-semibold leading-none ${tone}`}>{authLabel(mode, profile.runApproval)}</span>
      {detail}
    </span>
  );
}

/**
 * Tool presets and always-allowed tools (#73). Saved on the server; the host reads them at
 * its next claim, so no host restart. Approving "always" on a tool card adds to the list.
 */
function ToolPermissions({ serverId, profile, onChange, onError }: {
  serverId: string; profile: Profile; onChange: () => void; onError: (e: string) => void;
}) {
  const presets = profile.toolPresets ?? [];
  const allowed = profile.allowedTools ?? [];
  const [rule, setRule] = useState('');
  const [busy, setBusy] = useState(false);
  const valid = TOOL_RULE.test(rule.trim()) && !allowed.includes(rule.trim());

  const patch = async (body: { toolPresets?: string[]; allowedTools?: string[] }) => {
    setBusy(true);
    try { await api.patch(`/servers/${serverId}/agent-profiles/${profile.id}`, body); onChange(); }
    catch (err) { onError(errorText(err)); }
    finally { setBusy(false); }
  };
  const toggle = (name: string) => void patch({ toolPresets: presets.includes(name) ? presets.filter(p => p !== name) : [...presets, name] });

  return (
    <div className="mt-3 border-t border-border pt-2">
      <div className="mb-1 text-xs font-semibold text-text-muted">Tools</div>
      <div className="flex flex-wrap gap-x-4 gap-y-1" role="group" aria-label={`Tool presets for ${profile.name}`}>
        {PRESETS.map(p => (
          <label key={p.name} className="flex min-h-11 md:min-h-8 items-center gap-2 text-sm text-text">
            <input type="checkbox" checked={presets.includes(p.name)} disabled={busy} onChange={() => toggle(p.name)} />
            {p.label} <span className="text-xs text-text-muted">{p.detail}</span>
          </label>
        ))}
        {presets.filter(n => !PRESETS.some(p => p.name === n)).map(n => (
          <label key={n} className="flex min-h-11 md:min-h-8 items-center gap-2 text-sm text-text">
            <input type="checkbox" checked disabled={busy} onChange={() => toggle(n)} /> {n} <span className="text-xs text-text-muted">from host config</span>
          </label>
        ))}
      </div>
      <p className="mt-1 text-xs text-text-muted">
        {presets.length === 0 ? 'No preset: the host config alone decides.' : 'Changes apply from the next wake; no host restart.'}
      </p>
      {allowed.length > 0 && (
        <ul className="mt-2 flex flex-wrap gap-1" aria-label={`Always allowed tools for ${profile.name}`}>
          {allowed.map(t => (
            <li key={t} className="flex items-center gap-1 rounded border border-border bg-bg px-2 font-mono text-xs text-text">
              <span className="break-all">{t}</span>
              <button className="min-h-11 min-w-11 md:min-h-7 md:min-w-7 text-danger" disabled={busy} aria-label={`Remove ${t}`}
                onClick={() => void patch({ allowedTools: allowed.filter(a => a !== t) })}>×</button>
            </li>
          ))}
        </ul>
      )}
      <div className="mt-2 flex items-center gap-2">
        <input className={`${input} flex-1 font-mono`} value={rule} placeholder="Always allow, e.g. Bash(cargo:*)" maxLength={310}
          aria-label={`Add an always-allowed tool for ${profile.name}`} onChange={e => setRule(e.target.value)} />
        <Button variant="secondary" disabled={!valid || busy} onClick={() => { const t = rule.trim(); setRule(''); void patch({ allowedTools: [...allowed, t] }); }}>Add</Button>
      </div>
    </div>
  );
}

import { useCallback, useEffect, useState } from 'react';
import { useServerStore } from '../../stores/serverStore';
import { api, serverApi, ApiError } from '../../lib/api';
import type { Channel } from '../../lib/contracts/server';
import { Button } from '../../components/ui/Button';
import { NotAffiliated } from '../../components/ui/NotAffiliated';
import { authLabel } from '../agents/agentSessions';
import { ChatGPTPlanConnect, type PlanConnection } from './ChatGPTPlanConnect';
import { useAuthStore } from '../../stores/authStore';
import { BoxesSection } from '../boxes/BoxesSection';
import { BoxModeBadge } from '../boxes/BoxModeBadge';

/**
 * Agent hosts and agents (docs/planning/agent-sessions-wbs.md, S6). The owner registers the
 * machine that runs agents (a host) and creates agents on it; members then use /start in a
 * channel. Tokens are shown once and go into the host's config file, never into a channel.
 */

/** kind 'box': the agora-host inside a box (docs/agent-boxes.md §8.1); listed under Boxes, not here. */
interface Host { id: string; name: any; createdAt: string; lastSeenAt: string | null; revokedAt: string | null; kind?: 'machine' | 'box' }
interface Profile {
  id: string; name: string; botId: string; hostId: string; adapter: 'codex' | 'claude' | 'gemini' | 'opencode';
  model: string | null; effort: string | null; workdirAlias: string; workspaceId?: string;
  wakeBudget: number; tokenBudget: number; runTimeoutSec: number;
  toolPresets?: string[]; allowedTools?: string[];
  /** Reported by the host at start (docs/provider-terms.md); subscription until then. */
  authMode?: 'subscription' | 'api_key' | 'siwc'; apiKeyEnv?: string | null; runApproval?: boolean; authReportedAt?: string | null;
  /** 'siwc' only: whose ChatGPT plan it runs on (docs/codex-chatgpt-plan.md). */
  planOwnerId?: string | null;
  /** Its host is a box (docs/agent-boxes.md §10); otherwise it runs unboxed on a machine. */
  boxed?: boolean; hostMode?: boolean;
}

const EFFORTS = ['', 'low', 'medium', 'high', 'xhigh'];

/** Built-in tool presets (agora-host/src/presets.ts); the host config can redefine them. */
const PRESETS: { name: string; label: string; detail: string }[] = [
  { name: 'readonly', label: 'Read-only', detail: 'read files and git history' },
  { name: 'dev', label: 'Dev', detail: 'edit files, git, gh, npm' },
  { name: 'research', label: 'Research', detail: 'web search and fetch' },
];
/** Same rule shape the server accepts: a Claude permission rule or a Codex word (write, network, web_search). */
const TOOL_RULE = /^[A-Za-z][A-Za-z0-9_]{0,99}(\([^(),\r\n]{1,200}\))?$/;
const input = 'min-h-11 md:min-h-9 bg-bg border border-border rounded px-3 py-1.5 text-sm text-text placeholder:text-text-muted/70 focus:outline-none focus:ring-2 focus:ring-primary';

function errorText(err: unknown): string {
  if (err instanceof ApiError) return err.status === 403 ? 'Only the server owner can do this.' : err.code;
  return 'Request failed';
}

function OnceToken({ label, token, onDone }: { label: string; token: string; onDone: () => void }) {
  return (
    <div className="mb-4 rounded border border-primary/50 bg-primary/10 p-3 text-sm">
      <p className="mb-2 text-text">{label} It is shown only now; put it in the host's config file.</p>
      <code className="block break-all rounded bg-bg p-2 font-mono text-xs text-text select-all">{token}</code>
      <div className="mt-2 flex gap-2">
        <Button variant="secondary" onClick={() => { void navigator.clipboard?.writeText(token); }}>Copy</Button>
        <Button variant="secondary" onClick={onDone}>Done</Button>
      </div>
    </div>
  );
}

export function AgentSessionsSettings() {
  const serverId = useServerStore(s => s.instanceServerId);
  const ownerId = useServerStore(s => (serverId ? s.servers.get(serverId)?.ownerId : undefined));
  const userId = useAuthStore(s => s.user?.id);
  const [hosts, setHosts] = useState<Host[]>([]);
  const [profiles, setProfiles] = useState<Profile[]>([]);
  const [channels, setChannels] = useState<Channel[]>([]);
  const [plans, setPlans] = useState<PlanConnection[]>([]);
  const [error, setError] = useState('');
  const [secret, setSecret] = useState<{ label: string; token: string } | null>(null);
  const [reloadKey, setReloadKey] = useState(0);
  const load = useCallback(() => setReloadKey(k => k + 1), []);

  useEffect(() => {
    if (!serverId) return;
    let cancelled = false;
    Promise.all([
      api.get<Host[]>(`/servers/${serverId}/agent-hosts`),
      api.get<Profile[]>(`/servers/${serverId}/agent-profiles`),
      serverApi.getChannels(serverId),
      // ChatGPT plan connections; an older server without them just shows none
      api.get<PlanConnection[]>(`/servers/${serverId}/agent-plans`).catch(() => [] as PlanConnection[]),
    ]).then(([h, p, c, pl]) => {
      if (cancelled) return;
      setHosts(h);
      setProfiles(p);
      setPlans(pl);
      setChannels(c.filter(ch => ch.channelType === 3));
      setError('');
    }).catch(err => { if (!cancelled) setError(errorText(err)); });
    return () => { cancelled = true; };
  }, [serverId, reloadKey]);

  if (!serverId) return null;
  // Box hosts are managed with their box; agents are created on machine hosts here
  const machineHosts = hosts.filter(h => h.kind !== 'box');
  const activeHosts = machineHosts.filter(h => !h.revokedAt);
  const isOwner = !!userId && !!ownerId && userId.trim() === ownerId.trim();

  return (
    <div className="max-w-3xl">
      <h2 className="text-xl font-bold text-text mb-2">Agents</h2>
      <p className="text-text-muted text-sm mb-6">
        An agent host runs on the machine with your agent CLIs and wakes agents when they are addressed. Create a host,
        put its token in the host's config, then create agents on it. In a channel, <code>/start &lt;agent&gt;</code> starts a session.
      </p>
      {error && <p className="text-danger text-sm mb-4">{error}</p>}
      {secret && <OnceToken label={secret.label} token={secret.token} onDone={() => setSecret(null)} />}

      <p className="text-text-muted text-xs mb-6">
        Each agent runs its CLI on your own login (<em>subscription</em>) or on an API key, as set in the host's config.
        Personal subscriptions are for one person, so only you can wake a subscription agent; give agents that other
        members wake an API key. A Codex agent can also run on a ChatGPT plan through Sign in with ChatGPT; only the
        person who connected their plan can wake it. See docs/provider-terms.md and docs/codex-chatgpt-plan.md.
      </p>

      <BoxesSection serverId={serverId} channels={channels} isOwner={isOwner} />
      <HostsSection serverId={serverId} hosts={machineHosts} onChange={load} onToken={setSecret} onError={setError} />
      <AgentsSection serverId={serverId} hosts={activeHosts} allHosts={hosts} profiles={profiles} channels={channels} plans={plans}
        onChange={load} onToken={setSecret} onError={setError} />
      <NotAffiliated className="mt-8" />
    </div>
  );
}

function HostsSection({ serverId, hosts, onChange, onToken, onError }: {
  serverId: string; hosts: Host[]; onChange: () => void;
  onToken: (s: { label: string; token: string }) => void; onError: (e: string) => void;
}) {
  const [name, setName] = useState('');
  const create = async () => {
    try {
      const res = await api.post<{ host: Host; token: string }>(`/servers/${serverId}/agent-hosts`, { name: name.trim() });
      setName('');
      onToken({ label: `Host token for "${res.host.name}".`, token: res.token });
      onChange();
    } catch (err) { onError(errorText(err)); }
  };
  const revoke = async (h: Host) => {
    if (!confirm(`Revoke host "${h.name}"? Its token stops working at once and its agents stop waking.`)) return;
    try { await api.delete(`/servers/${serverId}/agent-hosts/${h.id}`); onChange(); } catch (err) { onError(errorText(err)); }
  };
  return (
    <section className="mb-8">
      <h3 className="text-lg font-semibold text-text mb-3">Hosts</h3>
      <ul className="mb-3 flex flex-col gap-1">
        {hosts.length === 0 && <li className="text-text-muted text-sm">No hosts yet.</li>}
        {hosts.map(h => (
          <li key={h.id} className="flex items-center justify-between rounded border border-border bg-surface px-3 py-2 text-sm">
            <span className={h.revokedAt ? 'text-text-muted line-through' : 'text-text'}>
              {h.name}
              <span className="ml-2 text-xs text-text-muted">
                {h.revokedAt ? 'revoked' : h.lastSeenAt ? `last seen ${new Date(h.lastSeenAt).toLocaleString()}` : 'never connected'}
              </span>
            </span>
            {!h.revokedAt && <button className="min-h-11 md:min-h-8 px-2 text-xs text-danger hover:underline" onClick={() => void revoke(h)}>Revoke</button>}
          </li>
        ))}
      </ul>
      <div className="flex gap-2">
        <input className={input} placeholder="Host name, e.g. my-pc" value={name} maxLength={64} onChange={e => setName(e.target.value)} />
        <Button onClick={() => void create()} disabled={!name.trim()}>Create host</Button>
      </div>
    </section>
  );
}

function AgentsSection({ serverId, hosts, allHosts, profiles, channels, plans, onChange, onToken, onError }: {
  serverId: string; hosts: Host[]; allHosts: Host[]; profiles: Profile[]; channels: Channel[]; plans: PlanConnection[]; onChange: () => void;
  onToken: (s: { label: string; token: string }) => void; onError: (e: string) => void;
}) {
  const [form, setForm] = useState({ name: '', adapter: 'codex', hostId: '', workdirAlias: 'agora', workspaceId: 'primary', model: '', effort: 'high', channelId: '' });
  // A profile on a machine host runs unboxed; the owner confirms that (docs/agent-boxes.md §10)
  const [unboxedAck, setUnboxedAck] = useState(false);
  const set = (k: keyof typeof form) => (e: { target: { value: string } }) => setForm(f => ({ ...f, [k]: e.target.value }));
  const hostId = form.hostId || hosts[0]?.id || '';
  const opencode = form.adapter === 'opencode';

  const create = async () => {
    try {
      const res = await api.post<{ bot: { username: string }; token: string }>(`/servers/${serverId}/agents`, {
        name: form.name.trim().toLowerCase(), adapter: form.adapter, hostId, workdirAlias: form.workdirAlias.trim(),
        workspaceId: form.workspaceId.trim().toLowerCase(), hostModeAck: true,
        ...(form.model.trim() ? { model: form.model.trim() } : {}),
        ...(form.effort ? { effort: form.effort } : {}),
        ...(form.channelId ? { channelId: form.channelId } : {}),
      });
      setForm(f => ({ ...f, name: '' }));
      setUnboxedAck(false);
      onToken({ label: `Bot token for agent "${res.bot.username}".`, token: res.token });
      onChange();
    } catch (err) { onError(errorText(err)); }
  };

  return (
    <section>
      <h3 className="text-lg font-semibold text-text mb-3">Agents</h3>
      <ul className="mb-4 flex flex-col gap-2">
        {profiles.length === 0 && <li className="text-text-muted text-sm">No agents yet.</li>}
        {profiles.map(p => (
          <ProfileRow key={p.id} serverId={serverId} profile={p} host={allHosts.find(h => h.id === p.hostId && !h.revokedAt)} plan={plans.find(x => x.profileId === p.id)}
            onChange={onChange} onError={onError} />
        ))}
      </ul>

      {hosts.length === 0 ? (
        <p className="text-text-muted text-sm">Create a host first.</p>
      ) : (
        <div className="rounded border border-border bg-surface p-3">
          <h4 className="mb-2 text-sm font-semibold text-text">Create agent</h4>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 text-sm">
            <label className="flex flex-col gap-1 text-text-muted">Name (bot and /start name)
              <input className={input} value={form.name} maxLength={32} placeholder="codex" onChange={set('name')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">CLI
              <select className={input} value={form.adapter} onChange={set('adapter')}>
                <option value="codex">Codex</option>
                <option value="claude">Claude Code</option>
                {/* The host runs it over ACP (gemini --acp) and only with an API key */}
                <option value="gemini">Gemini CLI (ACP, API key)</option>
                {/* opencode acp on an OpenRouter key: any OpenRouter model, one model per agent */}
                <option value="opencode">opencode (ACP, OpenRouter key)</option>
              </select>
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Host
              <select className={input} value={hostId} onChange={set('hostId')}>
                {hosts.map(h => <option key={h.id} value={h.id}>{h.name}</option>)}
              </select>
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Workdir alias (mapped to a folder in the host config)
              <input className={input} value={form.workdirAlias} maxLength={64} onChange={set('workdirAlias')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">{opencode ? 'OpenRouter model ID (required)' : 'Model (optional)'}
              <input className={input} value={form.model} maxLength={64} placeholder={opencode ? 'qwen/qwen3-coder' : 'gpt-6.1-sol'} onChange={set('model')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Workspace ID (same repository = same ID across hosts)
              <input className={input} value={form.workspaceId} maxLength={64} onChange={set('workspaceId')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Effort
              <select className={input} value={form.effort} onChange={set('effort')}>
                {EFFORTS.map(e => <option key={e} value={e}>{e || 'CLI default'}</option>)}
              </select>
            </label>
            <label className="sm:col-span-2 flex flex-col gap-1 text-text-muted">Add to channel (optional)
              <select className={input} value={form.channelId} onChange={set('channelId')}>
                <option value="">None</option>
                {channels.map(c => <option key={c.id} value={c.id}>#{c.name}</option>)}
              </select>
            </label>
          </div>
          <label className="mt-3 flex min-h-11 md:min-h-8 items-start gap-2 text-sm text-text">
            <input type="checkbox" className="mt-1" checked={unboxedAck} onChange={e => setUnboxedAck(e.target.checked)} />
            <span>Run unboxed on this machine (it can read and change your files). <span className="text-text-muted">Only you can wake an unboxed agent. For anything that doesn&apos;t need this machine, create a box instead.</span></span>
          </label>
          <div className="mt-3">
            <Button onClick={() => void create()} disabled={!unboxedAck || !/^[a-z0-9][a-z0-9_-]*$/i.test(form.name.trim()) || !form.workdirAlias.trim() || (opencode && !form.model.trim())}>
              Create agent
            </Button>
          </div>
        </div>
      )}
    </section>
  );
}

function ProfileRow({ serverId, profile, host, plan, onChange, onError }: {
  serverId: string; profile: Profile; host: Host | undefined; plan?: PlanConnection; onChange: () => void; onError: (e: string) => void;
}) {
  const [model, setModel] = useState(profile.model ?? '');
  const [effort, setEffort] = useState(profile.effort ?? '');
  const [workspaceId, setWorkspaceId] = useState(profile.workspaceId ?? 'primary');
  const [wakeBudget, setWakeBudget] = useState(String(profile.wakeBudget));
  const validWakeBudget = Number.isInteger(Number(wakeBudget)) && Number(wakeBudget) >= 1 && Number(wakeBudget) <= 100000;
  const dirty = model !== (profile.model ?? '') || effort !== (profile.effort ?? '') || workspaceId !== (profile.workspaceId ?? 'primary') || wakeBudget !== String(profile.wakeBudget);
  // opencode's own default is an OpenCode Zen model, so an opencode agent always names one
  const opencode = profile.adapter === 'opencode';
  const validModel = !opencode || !!model.trim();

  const save = async () => {
    try {
      if (!validWakeBudget || !validModel) return;
      await api.patch(`/servers/${serverId}/agent-profiles/${profile.id}`, { model: model.trim() || null, effort: effort || null, workspaceId: workspaceId.trim().toLowerCase(), wakeBudget: Number(wakeBudget) });
      onChange();
    } catch (err) { onError(errorText(err)); }
  };
  const remove = async () => {
    if (!confirm(`Delete agent profile "${profile.name}"? Its bot stays; end its sessions first.`)) return;
    try { await api.delete(`/servers/${serverId}/agent-profiles/${profile.id}`); onChange(); } catch (err) { onError(errorText(err)); }
  };

  return (
    <li className="rounded border border-border bg-surface px-3 py-2 text-sm">
      <div className="flex items-center justify-between">
        <span className="text-text">
          <span className="font-medium">{profile.name}</span>
          <BoxModeBadge profile={profile} className="ml-2" />
          <span className="ml-2 text-xs text-text-muted">
            {profile.adapter} · {host?.name ?? 'revoked host'} · workdir {profile.workdirAlias} · {profile.wakeBudget} wakes · {profile.tokenBudget.toLocaleString()} tokens per session
          </span>
          <AuthBadge profile={profile} />
        </span>
        <button className="min-h-11 md:min-h-8 px-2 text-xs text-danger hover:underline" onClick={() => void remove()}>Delete</button>
      </div>
      <div className="mt-2 flex flex-wrap items-center gap-2">
        <label className="flex flex-col text-xs text-text-muted">Workspace ID (end sessions before changing)
          <input className={input} value={workspaceId} maxLength={64} onChange={e => setWorkspaceId(e.target.value)} />
        </label>
        <input className={input} value={model} placeholder={opencode ? 'OpenRouter model ID (required)' : 'model (CLI default)'} maxLength={64}
          aria-label={`Model for ${profile.name}`} onChange={e => setModel(e.target.value)} />
        <select className={input} value={effort} onChange={e => setEffort(e.target.value)}>
          {EFFORTS.map(e => <option key={e} value={e}>{e || 'CLI default'}</option>)}
        </select>
        <label className="flex flex-col text-xs text-text-muted">Wake budget per session
          <input className={input} type="number" min={1} max={100000} step={1} value={wakeBudget}
            onChange={e => setWakeBudget(e.target.value)} aria-label={`Wake budget for ${profile.name}`} />
        </label>
        {dirty && <Button variant="secondary" disabled={!validWakeBudget || !validModel} onClick={() => void save()}>Save</Button>}
      </div>
      {/* A box logs its CLI in from its Boxes entry instead */}
      {profile.adapter === 'codex' && host && host.kind !== 'box' && !profile.boxed && (
        <ChatGPTPlanConnect serverId={serverId} profileId={profile.id} hostName={host.name} plan={plan}
          siwcMode={profile.authMode === 'siwc'} onChange={onChange} />
      )}
      <ToolPermissions serverId={serverId} profile={profile} onChange={onChange} onError={onError} />
    </li>
  );
}

/** How the agent's CLI signs in, as its host reported it (docs/provider-terms.md). */
function AuthBadge({ profile }: { profile: Profile }) {
  const mode = profile.authMode ?? 'subscription';
  const tone = mode === 'api_key' ? 'bg-online/20 text-online' : 'bg-warn/20 text-warn';
  const detail = !profile.authReportedAt
    ? 'not reported by its host yet, so treated as a subscription'
    : mode === 'api_key' ? `key from ${profile.apiKeyEnv}`
    : mode === 'siwc' ? (profile.planOwnerId ? 'only the person who connected their plan can wake it' : 'no ChatGPT plan connected yet')
    : 'only you can wake it';
  return (
    <span className="mt-1 flex flex-wrap items-center gap-2 text-xs text-text-muted" data-testid={`auth-${profile.name}`}>
      <span className={`rounded px-1.5 py-0.5 font-semibold leading-none ${tone}`}>{authLabel(mode, profile.runApproval)}</span>
      {detail}
    </span>
  );
}

/**
 * Tool presets and always-allowed tools (#73). Saved on the server; the host reads them at
 * its next claim, so no host restart. Approving "always" on a tool card adds to the list.
 */
function ToolPermissions({ serverId, profile, onChange, onError }: {
  serverId: string; profile: Profile; onChange: () => void; onError: (e: string) => void;
}) {
  const presets = profile.toolPresets ?? [];
  const allowed = profile.allowedTools ?? [];
  const [rule, setRule] = useState('');
  const [busy, setBusy] = useState(false);
  const valid = TOOL_RULE.test(rule.trim()) && !allowed.includes(rule.trim());

  const patch = async (body: { toolPresets?: string[]; allowedTools?: string[] }) => {
    setBusy(true);
    try { await api.patch(`/servers/${serverId}/agent-profiles/${profile.id}`, body); onChange(); }
    catch (err) { onError(errorText(err)); }
    finally { setBusy(false); }
  };
  const toggle = (name: string) => void patch({ toolPresets: presets.includes(name) ? presets.filter(p => p !== name) : [...presets, name] });

  return (
    <div className="mt-3 border-t border-border pt-2">
      <div className="mb-1 text-xs font-semibold text-text-muted">Tools</div>
      <div className="flex flex-wrap gap-x-4 gap-y-1" role="group" aria-label={`Tool presets for ${profile.name}`}>
        {PRESETS.map(p => (
          <label key={p.name} className="flex min-h-11 md:min-h-8 items-center gap-2 text-sm text-text">
            <input type="checkbox" checked={presets.includes(p.name)} disabled={busy} onChange={() => toggle(p.name)} />
            {p.label} <span className="text-xs text-text-muted">{p.detail}</span>
          </label>
        ))}
        {presets.filter(n => !PRESETS.some(p => p.name === n)).map(n => (
          <label key={n} className="flex min-h-11 md:min-h-8 items-center gap-2 text-sm text-text">
            <input type="checkbox" checked disabled={busy} onChange={() => toggle(n)} /> {n} <span className="text-xs text-text-muted">from host config</span>
          </label>
        ))}
      </div>
      <p className="mt-1 text-xs text-text-muted">
        {presets.length === 0 ? 'No preset: the host config alone decides.' : 'Changes apply from the next wake; no host restart.'}
      </p>
      {allowed.length > 0 && (
        <ul className="mt-2 flex flex-wrap gap-1" aria-label={`Always allowed tools for ${profile.name}`}>
          {allowed.map(t => (
            <li key={t} className="flex items-center gap-1 rounded border border-border bg-bg px-2 font-mono text-xs text-text">
              <span className="break-all">{t}</span>
              <button className="min-h-11 min-w-11 md:min-h-7 md:min-w-7 text-danger" disabled={busy} aria-label={`Remove ${t}`}
                onClick={() => void patch({ allowedTools: allowed.filter(a => a !== t) })}>×</button>
            </li>
          ))}
        </ul>
      )}
      <div className="mt-2 flex items-center gap-2">
        <input className={`${input} flex-1 font-mono`} value={rule} placeholder="Always allow, e.g. Bash(cargo:*)" maxLength={310}
          aria-label={`Add an always-allowed tool for ${profile.name}`} onChange={e => setRule(e.target.value)} />
        <Button variant="secondary" disabled={!valid || busy} onClick={() => { const t = rule.trim(); setRule(''); void patch({ allowedTools: [...allowed, t] }); }}>Add</Button>
      </div>
    </div>
  );
}

import { useCallback, useEffect, useState } from 'react';
import { useServerStore } from '../../stores/serverStore';
import { api, serverApi, ApiError } from '../../lib/api';
import type { Channel } from '../../lib/contracts/server';
import { Button } from '../../components/ui/Button';
import { NotAffiliated } from '../../components/ui/NotAffiliated';
import { authLabel } from '../agents/agentSessions';
import { ChatGPTPlanConnect, type PlanConnection } from './ChatGPTPlanConnect';
import { useAuthStore } from '../../stores/authStore';
import { BoxesSection } from '../boxes/BoxesSection';
import { BoxModeBadge } from '../boxes/BoxModeBadge';

/**
 * Agent hosts and agents (docs/planning/agent-sessions-wbs.md, S6). The owner registers the
 * machine that runs agents (a host) and creates agents on it; members then use /start in a
 * channel. Tokens are shown once and go into the host's config file, never into a channel.
 */

/** kind 'box': the agora-host inside a box (docs/agent-boxes.md §8.1); listed under Boxes, not here. */
interface Host { id: string; name: string; createdAt: any; lastSeenAt: string | null; revokedAt: string | null; kind?: 'machine' | 'box' }
interface Profile {
  id: string; name: string; botId: string; hostId: string; adapter: 'codex' | 'claude' | 'gemini' | 'opencode';
  model: string | null; effort: string | null; workdirAlias: string; workspaceId?: string;
  wakeBudget: number; tokenBudget: number; runTimeoutSec: number;
  toolPresets?: string[]; allowedTools?: string[];
  /** Reported by the host at start (docs/provider-terms.md); subscription until then. */
  authMode?: 'subscription' | 'api_key' | 'siwc'; apiKeyEnv?: string | null; runApproval?: boolean; authReportedAt?: string | null;
  /** 'siwc' only: whose ChatGPT plan it runs on (docs/codex-chatgpt-plan.md). */
  planOwnerId?: string | null;
  /** Its host is a box (docs/agent-boxes.md §10); otherwise it runs unboxed on a machine. */
  boxed?: boolean; hostMode?: boolean;
}

const EFFORTS = ['', 'low', 'medium', 'high', 'xhigh'];

/** Built-in tool presets (agora-host/src/presets.ts); the host config can redefine them. */
const PRESETS: { name: string; label: string; detail: string }[] = [
  { name: 'readonly', label: 'Read-only', detail: 'read files and git history' },
  { name: 'dev', label: 'Dev', detail: 'edit files, git, gh, npm' },
  { name: 'research', label: 'Research', detail: 'web search and fetch' },
];
/** Same rule shape the server accepts: a Claude permission rule or a Codex word (write, network, web_search). */
const TOOL_RULE = /^[A-Za-z][A-Za-z0-9_]{0,99}(\([^(),\r\n]{1,200}\))?$/;
const input = 'min-h-11 md:min-h-9 bg-bg border border-border rounded px-3 py-1.5 text-sm text-text placeholder:text-text-muted/70 focus:outline-none focus:ring-2 focus:ring-primary';

function errorText(err: unknown): string {
  if (err instanceof ApiError) return err.status === 403 ? 'Only the server owner can do this.' : err.code;
  return 'Request failed';
}

function OnceToken({ label, token, onDone }: { label: string; token: string; onDone: () => void }) {
  return (
    <div className="mb-4 rounded border border-primary/50 bg-primary/10 p-3 text-sm">
      <p className="mb-2 text-text">{label} It is shown only now; put it in the host's config file.</p>
      <code className="block break-all rounded bg-bg p-2 font-mono text-xs text-text select-all">{token}</code>
      <div className="mt-2 flex gap-2">
        <Button variant="secondary" onClick={() => { void navigator.clipboard?.writeText(token); }}>Copy</Button>
        <Button variant="secondary" onClick={onDone}>Done</Button>
      </div>
    </div>
  );
}

export function AgentSessionsSettings() {
  const serverId = useServerStore(s => s.instanceServerId);
  const ownerId = useServerStore(s => (serverId ? s.servers.get(serverId)?.ownerId : undefined));
  const userId = useAuthStore(s => s.user?.id);
  const [hosts, setHosts] = useState<Host[]>([]);
  const [profiles, setProfiles] = useState<Profile[]>([]);
  const [channels, setChannels] = useState<Channel[]>([]);
  const [plans, setPlans] = useState<PlanConnection[]>([]);
  const [error, setError] = useState('');
  const [secret, setSecret] = useState<{ label: string; token: string } | null>(null);
  const [reloadKey, setReloadKey] = useState(0);
  const load = useCallback(() => setReloadKey(k => k + 1), []);

  useEffect(() => {
    if (!serverId) return;
    let cancelled = false;
    Promise.all([
      api.get<Host[]>(`/servers/${serverId}/agent-hosts`),
      api.get<Profile[]>(`/servers/${serverId}/agent-profiles`),
      serverApi.getChannels(serverId),
      // ChatGPT plan connections; an older server without them just shows none
      api.get<PlanConnection[]>(`/servers/${serverId}/agent-plans`).catch(() => [] as PlanConnection[]),
    ]).then(([h, p, c, pl]) => {
      if (cancelled) return;
      setHosts(h);
      setProfiles(p);
      setPlans(pl);
      setChannels(c.filter(ch => ch.channelType === 3));
      setError('');
    }).catch(err => { if (!cancelled) setError(errorText(err)); });
    return () => { cancelled = true; };
  }, [serverId, reloadKey]);

  if (!serverId) return null;
  // Box hosts are managed with their box; agents are created on machine hosts here
  const machineHosts = hosts.filter(h => h.kind !== 'box');
  const activeHosts = machineHosts.filter(h => !h.revokedAt);
  const isOwner = !!userId && !!ownerId && userId.trim() === ownerId.trim();

  return (
    <div className="max-w-3xl">
      <h2 className="text-xl font-bold text-text mb-2">Agents</h2>
      <p className="text-text-muted text-sm mb-6">
        An agent host runs on the machine with your agent CLIs and wakes agents when they are addressed. Create a host,
        put its token in the host's config, then create agents on it. In a channel, <code>/start &lt;agent&gt;</code> starts a session.
      </p>
      {error && <p className="text-danger text-sm mb-4">{error}</p>}
      {secret && <OnceToken label={secret.label} token={secret.token} onDone={() => setSecret(null)} />}

      <p className="text-text-muted text-xs mb-6">
        Each agent runs its CLI on your own login (<em>subscription</em>) or on an API key, as set in the host's config.
        Personal subscriptions are for one person, so only you can wake a subscription agent; give agents that other
        members wake an API key. A Codex agent can also run on a ChatGPT plan through Sign in with ChatGPT; only the
        person who connected their plan can wake it. See docs/provider-terms.md and docs/codex-chatgpt-plan.md.
      </p>

      <BoxesSection serverId={serverId} channels={channels} isOwner={isOwner} />
      <HostsSection serverId={serverId} hosts={machineHosts} onChange={load} onToken={setSecret} onError={setError} />
      <AgentsSection serverId={serverId} hosts={activeHosts} allHosts={hosts} profiles={profiles} channels={channels} plans={plans}
        onChange={load} onToken={setSecret} onError={setError} />
      <NotAffiliated className="mt-8" />
    </div>
  );
}

function HostsSection({ serverId, hosts, onChange, onToken, onError }: {
  serverId: string; hosts: Host[]; onChange: () => void;
  onToken: (s: { label: string; token: string }) => void; onError: (e: string) => void;
}) {
  const [name, setName] = useState('');
  const create = async () => {
    try {
      const res = await api.post<{ host: Host; token: string }>(`/servers/${serverId}/agent-hosts`, { name: name.trim() });
      setName('');
      onToken({ label: `Host token for "${res.host.name}".`, token: res.token });
      onChange();
    } catch (err) { onError(errorText(err)); }
  };
  const revoke = async (h: Host) => {
    if (!confirm(`Revoke host "${h.name}"? Its token stops working at once and its agents stop waking.`)) return;
    try { await api.delete(`/servers/${serverId}/agent-hosts/${h.id}`); onChange(); } catch (err) { onError(errorText(err)); }
  };
  return (
    <section className="mb-8">
      <h3 className="text-lg font-semibold text-text mb-3">Hosts</h3>
      <ul className="mb-3 flex flex-col gap-1">
        {hosts.length === 0 && <li className="text-text-muted text-sm">No hosts yet.</li>}
        {hosts.map(h => (
          <li key={h.id} className="flex items-center justify-between rounded border border-border bg-surface px-3 py-2 text-sm">
            <span className={h.revokedAt ? 'text-text-muted line-through' : 'text-text'}>
              {h.name}
              <span className="ml-2 text-xs text-text-muted">
                {h.revokedAt ? 'revoked' : h.lastSeenAt ? `last seen ${new Date(h.lastSeenAt).toLocaleString()}` : 'never connected'}
              </span>
            </span>
            {!h.revokedAt && <button className="min-h-11 md:min-h-8 px-2 text-xs text-danger hover:underline" onClick={() => void revoke(h)}>Revoke</button>}
          </li>
        ))}
      </ul>
      <div className="flex gap-2">
        <input className={input} placeholder="Host name, e.g. my-pc" value={name} maxLength={64} onChange={e => setName(e.target.value)} />
        <Button onClick={() => void create()} disabled={!name.trim()}>Create host</Button>
      </div>
    </section>
  );
}

function AgentsSection({ serverId, hosts, allHosts, profiles, channels, plans, onChange, onToken, onError }: {
  serverId: string; hosts: Host[]; allHosts: Host[]; profiles: Profile[]; channels: Channel[]; plans: PlanConnection[]; onChange: () => void;
  onToken: (s: { label: string; token: string }) => void; onError: (e: string) => void;
}) {
  const [form, setForm] = useState({ name: '', adapter: 'codex', hostId: '', workdirAlias: 'agora', workspaceId: 'primary', model: '', effort: 'high', channelId: '' });
  // A profile on a machine host runs unboxed; the owner confirms that (docs/agent-boxes.md §10)
  const [unboxedAck, setUnboxedAck] = useState(false);
  const set = (k: keyof typeof form) => (e: { target: { value: string } }) => setForm(f => ({ ...f, [k]: e.target.value }));
  const hostId = form.hostId || hosts[0]?.id || '';
  const opencode = form.adapter === 'opencode';

  const create = async () => {
    try {
      const res = await api.post<{ bot: { username: string }; token: string }>(`/servers/${serverId}/agents`, {
        name: form.name.trim().toLowerCase(), adapter: form.adapter, hostId, workdirAlias: form.workdirAlias.trim(),
        workspaceId: form.workspaceId.trim().toLowerCase(), hostModeAck: true,
        ...(form.model.trim() ? { model: form.model.trim() } : {}),
        ...(form.effort ? { effort: form.effort } : {}),
        ...(form.channelId ? { channelId: form.channelId } : {}),
      });
      setForm(f => ({ ...f, name: '' }));
      setUnboxedAck(false);
      onToken({ label: `Bot token for agent "${res.bot.username}".`, token: res.token });
      onChange();
    } catch (err) { onError(errorText(err)); }
  };

  return (
    <section>
      <h3 className="text-lg font-semibold text-text mb-3">Agents</h3>
      <ul className="mb-4 flex flex-col gap-2">
        {profiles.length === 0 && <li className="text-text-muted text-sm">No agents yet.</li>}
        {profiles.map(p => (
          <ProfileRow key={p.id} serverId={serverId} profile={p} host={allHosts.find(h => h.id === p.hostId && !h.revokedAt)} plan={plans.find(x => x.profileId === p.id)}
            onChange={onChange} onError={onError} />
        ))}
      </ul>

      {hosts.length === 0 ? (
        <p className="text-text-muted text-sm">Create a host first.</p>
      ) : (
        <div className="rounded border border-border bg-surface p-3">
          <h4 className="mb-2 text-sm font-semibold text-text">Create agent</h4>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 text-sm">
            <label className="flex flex-col gap-1 text-text-muted">Name (bot and /start name)
              <input className={input} value={form.name} maxLength={32} placeholder="codex" onChange={set('name')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">CLI
              <select className={input} value={form.adapter} onChange={set('adapter')}>
                <option value="codex">Codex</option>
                <option value="claude">Claude Code</option>
                {/* The host runs it over ACP (gemini --acp) and only with an API key */}
                <option value="gemini">Gemini CLI (ACP, API key)</option>
                {/* opencode acp on an OpenRouter key: any OpenRouter model, one model per agent */}
                <option value="opencode">opencode (ACP, OpenRouter key)</option>
              </select>
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Host
              <select className={input} value={hostId} onChange={set('hostId')}>
                {hosts.map(h => <option key={h.id} value={h.id}>{h.name}</option>)}
              </select>
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Workdir alias (mapped to a folder in the host config)
              <input className={input} value={form.workdirAlias} maxLength={64} onChange={set('workdirAlias')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">{opencode ? 'OpenRouter model ID (required)' : 'Model (optional)'}
              <input className={input} value={form.model} maxLength={64} placeholder={opencode ? 'qwen/qwen3-coder' : 'gpt-6.1-sol'} onChange={set('model')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Workspace ID (same repository = same ID across hosts)
              <input className={input} value={form.workspaceId} maxLength={64} onChange={set('workspaceId')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Effort
              <select className={input} value={form.effort} onChange={set('effort')}>
                {EFFORTS.map(e => <option key={e} value={e}>{e || 'CLI default'}</option>)}
              </select>
            </label>
            <label className="sm:col-span-2 flex flex-col gap-1 text-text-muted">Add to channel (optional)
              <select className={input} value={form.channelId} onChange={set('channelId')}>
                <option value="">None</option>
                {channels.map(c => <option key={c.id} value={c.id}>#{c.name}</option>)}
              </select>
            </label>
          </div>
          <label className="mt-3 flex min-h-11 md:min-h-8 items-start gap-2 text-sm text-text">
            <input type="checkbox" className="mt-1" checked={unboxedAck} onChange={e => setUnboxedAck(e.target.checked)} />
            <span>Run unboxed on this machine (it can read and change your files). <span className="text-text-muted">Only you can wake an unboxed agent. For anything that doesn&apos;t need this machine, create a box instead.</span></span>
          </label>
          <div className="mt-3">
            <Button onClick={() => void create()} disabled={!unboxedAck || !/^[a-z0-9][a-z0-9_-]*$/i.test(form.name.trim()) || !form.workdirAlias.trim() || (opencode && !form.model.trim())}>
              Create agent
            </Button>
          </div>
        </div>
      )}
    </section>
  );
}

function ProfileRow({ serverId, profile, host, plan, onChange, onError }: {
  serverId: string; profile: Profile; host: Host | undefined; plan?: PlanConnection; onChange: () => void; onError: (e: string) => void;
}) {
  const [model, setModel] = useState(profile.model ?? '');
  const [effort, setEffort] = useState(profile.effort ?? '');
  const [workspaceId, setWorkspaceId] = useState(profile.workspaceId ?? 'primary');
  const [wakeBudget, setWakeBudget] = useState(String(profile.wakeBudget));
  const validWakeBudget = Number.isInteger(Number(wakeBudget)) && Number(wakeBudget) >= 1 && Number(wakeBudget) <= 100000;
  const dirty = model !== (profile.model ?? '') || effort !== (profile.effort ?? '') || workspaceId !== (profile.workspaceId ?? 'primary') || wakeBudget !== String(profile.wakeBudget);
  // opencode's own default is an OpenCode Zen model, so an opencode agent always names one
  const opencode = profile.adapter === 'opencode';
  const validModel = !opencode || !!model.trim();

  const save = async () => {
    try {
      if (!validWakeBudget || !validModel) return;
      await api.patch(`/servers/${serverId}/agent-profiles/${profile.id}`, { model: model.trim() || null, effort: effort || null, workspaceId: workspaceId.trim().toLowerCase(), wakeBudget: Number(wakeBudget) });
      onChange();
    } catch (err) { onError(errorText(err)); }
  };
  const remove = async () => {
    if (!confirm(`Delete agent profile "${profile.name}"? Its bot stays; end its sessions first.`)) return;
    try { await api.delete(`/servers/${serverId}/agent-profiles/${profile.id}`); onChange(); } catch (err) { onError(errorText(err)); }
  };

  return (
    <li className="rounded border border-border bg-surface px-3 py-2 text-sm">
      <div className="flex items-center justify-between">
        <span className="text-text">
          <span className="font-medium">{profile.name}</span>
          <BoxModeBadge profile={profile} className="ml-2" />
          <span className="ml-2 text-xs text-text-muted">
            {profile.adapter} · {host?.name ?? 'revoked host'} · workdir {profile.workdirAlias} · {profile.wakeBudget} wakes · {profile.tokenBudget.toLocaleString()} tokens per session
          </span>
          <AuthBadge profile={profile} />
        </span>
        <button className="min-h-11 md:min-h-8 px-2 text-xs text-danger hover:underline" onClick={() => void remove()}>Delete</button>
      </div>
      <div className="mt-2 flex flex-wrap items-center gap-2">
        <label className="flex flex-col text-xs text-text-muted">Workspace ID (end sessions before changing)
          <input className={input} value={workspaceId} maxLength={64} onChange={e => setWorkspaceId(e.target.value)} />
        </label>
        <input className={input} value={model} placeholder={opencode ? 'OpenRouter model ID (required)' : 'model (CLI default)'} maxLength={64}
          aria-label={`Model for ${profile.name}`} onChange={e => setModel(e.target.value)} />
        <select className={input} value={effort} onChange={e => setEffort(e.target.value)}>
          {EFFORTS.map(e => <option key={e} value={e}>{e || 'CLI default'}</option>)}
        </select>
        <label className="flex flex-col text-xs text-text-muted">Wake budget per session
          <input className={input} type="number" min={1} max={100000} step={1} value={wakeBudget}
            onChange={e => setWakeBudget(e.target.value)} aria-label={`Wake budget for ${profile.name}`} />
        </label>
        {dirty && <Button variant="secondary" disabled={!validWakeBudget || !validModel} onClick={() => void save()}>Save</Button>}
      </div>
      {/* A box logs its CLI in from its Boxes entry instead */}
      {profile.adapter === 'codex' && host && host.kind !== 'box' && !profile.boxed && (
        <ChatGPTPlanConnect serverId={serverId} profileId={profile.id} hostName={host.name} plan={plan}
          siwcMode={profile.authMode === 'siwc'} onChange={onChange} />
      )}
      <ToolPermissions serverId={serverId} profile={profile} onChange={onChange} onError={onError} />
    </li>
  );
}

/** How the agent's CLI signs in, as its host reported it (docs/provider-terms.md). */
function AuthBadge({ profile }: { profile: Profile }) {
  const mode = profile.authMode ?? 'subscription';
  const tone = mode === 'api_key' ? 'bg-online/20 text-online' : 'bg-warn/20 text-warn';
  const detail = !profile.authReportedAt
    ? 'not reported by its host yet, so treated as a subscription'
    : mode === 'api_key' ? `key from ${profile.apiKeyEnv}`
    : mode === 'siwc' ? (profile.planOwnerId ? 'only the person who connected their plan can wake it' : 'no ChatGPT plan connected yet')
    : 'only you can wake it';
  return (
    <span className="mt-1 flex flex-wrap items-center gap-2 text-xs text-text-muted" data-testid={`auth-${profile.name}`}>
      <span className={`rounded px-1.5 py-0.5 font-semibold leading-none ${tone}`}>{authLabel(mode, profile.runApproval)}</span>
      {detail}
    </span>
  );
}

/**
 * Tool presets and always-allowed tools (#73). Saved on the server; the host reads them at
 * its next claim, so no host restart. Approving "always" on a tool card adds to the list.
 */
function ToolPermissions({ serverId, profile, onChange, onError }: {
  serverId: string; profile: Profile; onChange: () => void; onError: (e: string) => void;
}) {
  const presets = profile.toolPresets ?? [];
  const allowed = profile.allowedTools ?? [];
  const [rule, setRule] = useState('');
  const [busy, setBusy] = useState(false);
  const valid = TOOL_RULE.test(rule.trim()) && !allowed.includes(rule.trim());

  const patch = async (body: { toolPresets?: string[]; allowedTools?: string[] }) => {
    setBusy(true);
    try { await api.patch(`/servers/${serverId}/agent-profiles/${profile.id}`, body); onChange(); }
    catch (err) { onError(errorText(err)); }
    finally { setBusy(false); }
  };
  const toggle = (name: string) => void patch({ toolPresets: presets.includes(name) ? presets.filter(p => p !== name) : [...presets, name] });

  return (
    <div className="mt-3 border-t border-border pt-2">
      <div className="mb-1 text-xs font-semibold text-text-muted">Tools</div>
      <div className="flex flex-wrap gap-x-4 gap-y-1" role="group" aria-label={`Tool presets for ${profile.name}`}>
        {PRESETS.map(p => (
          <label key={p.name} className="flex min-h-11 md:min-h-8 items-center gap-2 text-sm text-text">
            <input type="checkbox" checked={presets.includes(p.name)} disabled={busy} onChange={() => toggle(p.name)} />
            {p.label} <span className="text-xs text-text-muted">{p.detail}</span>
          </label>
        ))}
        {presets.filter(n => !PRESETS.some(p => p.name === n)).map(n => (
          <label key={n} className="flex min-h-11 md:min-h-8 items-center gap-2 text-sm text-text">
            <input type="checkbox" checked disabled={busy} onChange={() => toggle(n)} /> {n} <span className="text-xs text-text-muted">from host config</span>
          </label>
        ))}
      </div>
      <p className="mt-1 text-xs text-text-muted">
        {presets.length === 0 ? 'No preset: the host config alone decides.' : 'Changes apply from the next wake; no host restart.'}
      </p>
      {allowed.length > 0 && (
        <ul className="mt-2 flex flex-wrap gap-1" aria-label={`Always allowed tools for ${profile.name}`}>
          {allowed.map(t => (
            <li key={t} className="flex items-center gap-1 rounded border border-border bg-bg px-2 font-mono text-xs text-text">
              <span className="break-all">{t}</span>
              <button className="min-h-11 min-w-11 md:min-h-7 md:min-w-7 text-danger" disabled={busy} aria-label={`Remove ${t}`}
                onClick={() => void patch({ allowedTools: allowed.filter(a => a !== t) })}>×</button>
            </li>
          ))}
        </ul>
      )}
      <div className="mt-2 flex items-center gap-2">
        <input className={`${input} flex-1 font-mono`} value={rule} placeholder="Always allow, e.g. Bash(cargo:*)" maxLength={310}
          aria-label={`Add an always-allowed tool for ${profile.name}`} onChange={e => setRule(e.target.value)} />
        <Button variant="secondary" disabled={!valid || busy} onClick={() => { const t = rule.trim(); setRule(''); void patch({ allowedTools: [...allowed, t] }); }}>Add</Button>
      </div>
    </div>
  );
}

import { useCallback, useEffect, useState } from 'react';
import { useServerStore } from '../../stores/serverStore';
import { api, serverApi, ApiError } from '../../lib/api';
import type { Channel } from '../../lib/contracts/server';
import { Button } from '../../components/ui/Button';
import { NotAffiliated } from '../../components/ui/NotAffiliated';
import { authLabel } from '../agents/agentSessions';
import { ChatGPTPlanConnect, type PlanConnection } from './ChatGPTPlanConnect';
import { useAuthStore } from '../../stores/authStore';
import { BoxesSection } from '../boxes/BoxesSection';
import { BoxModeBadge } from '../boxes/BoxModeBadge';

/**
 * Agent hosts and agents (docs/planning/agent-sessions-wbs.md, S6). The owner registers the
 * machine that runs agents (a host) and creates agents on it; members then use /start in a
 * channel. Tokens are shown once and go into the host's config file, never into a channel.
 */

/** kind 'box': the agora-host inside a box (docs/agent-boxes.md §8.1); listed under Boxes, not here. */
interface Host { id: string; name: string; createdAt: string; lastSeenAt: any; revokedAt: string | null; kind?: 'machine' | 'box' }
interface Profile {
  id: string; name: string; botId: string; hostId: string; adapter: 'codex' | 'claude' | 'gemini' | 'opencode';
  model: string | null; effort: string | null; workdirAlias: string; workspaceId?: string;
  wakeBudget: number; tokenBudget: number; runTimeoutSec: number;
  toolPresets?: string[]; allowedTools?: string[];
  /** Reported by the host at start (docs/provider-terms.md); subscription until then. */
  authMode?: 'subscription' | 'api_key' | 'siwc'; apiKeyEnv?: string | null; runApproval?: boolean; authReportedAt?: string | null;
  /** 'siwc' only: whose ChatGPT plan it runs on (docs/codex-chatgpt-plan.md). */
  planOwnerId?: string | null;
  /** Its host is a box (docs/agent-boxes.md §10); otherwise it runs unboxed on a machine. */
  boxed?: boolean; hostMode?: boolean;
}

const EFFORTS = ['', 'low', 'medium', 'high', 'xhigh'];

/** Built-in tool presets (agora-host/src/presets.ts); the host config can redefine them. */
const PRESETS: { name: string; label: string; detail: string }[] = [
  { name: 'readonly', label: 'Read-only', detail: 'read files and git history' },
  { name: 'dev', label: 'Dev', detail: 'edit files, git, gh, npm' },
  { name: 'research', label: 'Research', detail: 'web search and fetch' },
];
/** Same rule shape the server accepts: a Claude permission rule or a Codex word (write, network, web_search). */
const TOOL_RULE = /^[A-Za-z][A-Za-z0-9_]{0,99}(\([^(),\r\n]{1,200}\))?$/;
const input = 'min-h-11 md:min-h-9 bg-bg border border-border rounded px-3 py-1.5 text-sm text-text placeholder:text-text-muted/70 focus:outline-none focus:ring-2 focus:ring-primary';

function errorText(err: unknown): string {
  if (err instanceof ApiError) return err.status === 403 ? 'Only the server owner can do this.' : err.code;
  return 'Request failed';
}

function OnceToken({ label, token, onDone }: { label: string; token: string; onDone: () => void }) {
  return (
    <div className="mb-4 rounded border border-primary/50 bg-primary/10 p-3 text-sm">
      <p className="mb-2 text-text">{label} It is shown only now; put it in the host's config file.</p>
      <code className="block break-all rounded bg-bg p-2 font-mono text-xs text-text select-all">{token}</code>
      <div className="mt-2 flex gap-2">
        <Button variant="secondary" onClick={() => { void navigator.clipboard?.writeText(token); }}>Copy</Button>
        <Button variant="secondary" onClick={onDone}>Done</Button>
      </div>
    </div>
  );
}

export function AgentSessionsSettings() {
  const serverId = useServerStore(s => s.instanceServerId);
  const ownerId = useServerStore(s => (serverId ? s.servers.get(serverId)?.ownerId : undefined));
  const userId = useAuthStore(s => s.user?.id);
  const [hosts, setHosts] = useState<Host[]>([]);
  const [profiles, setProfiles] = useState<Profile[]>([]);
  const [channels, setChannels] = useState<Channel[]>([]);
  const [plans, setPlans] = useState<PlanConnection[]>([]);
  const [error, setError] = useState('');
  const [secret, setSecret] = useState<{ label: string; token: string } | null>(null);
  const [reloadKey, setReloadKey] = useState(0);
  const load = useCallback(() => setReloadKey(k => k + 1), []);

  useEffect(() => {
    if (!serverId) return;
    let cancelled = false;
    Promise.all([
      api.get<Host[]>(`/servers/${serverId}/agent-hosts`),
      api.get<Profile[]>(`/servers/${serverId}/agent-profiles`),
      serverApi.getChannels(serverId),
      // ChatGPT plan connections; an older server without them just shows none
      api.get<PlanConnection[]>(`/servers/${serverId}/agent-plans`).catch(() => [] as PlanConnection[]),
    ]).then(([h, p, c, pl]) => {
      if (cancelled) return;
      setHosts(h);
      setProfiles(p);
      setPlans(pl);
      setChannels(c.filter(ch => ch.channelType === 3));
      setError('');
    }).catch(err => { if (!cancelled) setError(errorText(err)); });
    return () => { cancelled = true; };
  }, [serverId, reloadKey]);

  if (!serverId) return null;
  // Box hosts are managed with their box; agents are created on machine hosts here
  const machineHosts = hosts.filter(h => h.kind !== 'box');
  const activeHosts = machineHosts.filter(h => !h.revokedAt);
  const isOwner = !!userId && !!ownerId && userId.trim() === ownerId.trim();

  return (
    <div className="max-w-3xl">
      <h2 className="text-xl font-bold text-text mb-2">Agents</h2>
      <p className="text-text-muted text-sm mb-6">
        An agent host runs on the machine with your agent CLIs and wakes agents when they are addressed. Create a host,
        put its token in the host's config, then create agents on it. In a channel, <code>/start &lt;agent&gt;</code> starts a session.
      </p>
      {error && <p className="text-danger text-sm mb-4">{error}</p>}
      {secret && <OnceToken label={secret.label} token={secret.token} onDone={() => setSecret(null)} />}

      <p className="text-text-muted text-xs mb-6">
        Each agent runs its CLI on your own login (<em>subscription</em>) or on an API key, as set in the host's config.
        Personal subscriptions are for one person, so only you can wake a subscription agent; give agents that other
        members wake an API key. A Codex agent can also run on a ChatGPT plan through Sign in with ChatGPT; only the
        person who connected their plan can wake it. See docs/provider-terms.md and docs/codex-chatgpt-plan.md.
      </p>

      <BoxesSection serverId={serverId} channels={channels} isOwner={isOwner} />
      <HostsSection serverId={serverId} hosts={machineHosts} onChange={load} onToken={setSecret} onError={setError} />
      <AgentsSection serverId={serverId} hosts={activeHosts} allHosts={hosts} profiles={profiles} channels={channels} plans={plans}
        onChange={load} onToken={setSecret} onError={setError} />
      <NotAffiliated className="mt-8" />
    </div>
  );
}

function HostsSection({ serverId, hosts, onChange, onToken, onError }: {
  serverId: string; hosts: Host[]; onChange: () => void;
  onToken: (s: { label: string; token: string }) => void; onError: (e: string) => void;
}) {
  const [name, setName] = useState('');
  const create = async () => {
    try {
      const res = await api.post<{ host: Host; token: string }>(`/servers/${serverId}/agent-hosts`, { name: name.trim() });
      setName('');
      onToken({ label: `Host token for "${res.host.name}".`, token: res.token });
      onChange();
    } catch (err) { onError(errorText(err)); }
  };
  const revoke = async (h: Host) => {
    if (!confirm(`Revoke host "${h.name}"? Its token stops working at once and its agents stop waking.`)) return;
    try { await api.delete(`/servers/${serverId}/agent-hosts/${h.id}`); onChange(); } catch (err) { onError(errorText(err)); }
  };
  return (
    <section className="mb-8">
      <h3 className="text-lg font-semibold text-text mb-3">Hosts</h3>
      <ul className="mb-3 flex flex-col gap-1">
        {hosts.length === 0 && <li className="text-text-muted text-sm">No hosts yet.</li>}
        {hosts.map(h => (
          <li key={h.id} className="flex items-center justify-between rounded border border-border bg-surface px-3 py-2 text-sm">
            <span className={h.revokedAt ? 'text-text-muted line-through' : 'text-text'}>
              {h.name}
              <span className="ml-2 text-xs text-text-muted">
                {h.revokedAt ? 'revoked' : h.lastSeenAt ? `last seen ${new Date(h.lastSeenAt).toLocaleString()}` : 'never connected'}
              </span>
            </span>
            {!h.revokedAt && <button className="min-h-11 md:min-h-8 px-2 text-xs text-danger hover:underline" onClick={() => void revoke(h)}>Revoke</button>}
          </li>
        ))}
      </ul>
      <div className="flex gap-2">
        <input className={input} placeholder="Host name, e.g. my-pc" value={name} maxLength={64} onChange={e => setName(e.target.value)} />
        <Button onClick={() => void create()} disabled={!name.trim()}>Create host</Button>
      </div>
    </section>
  );
}

function AgentsSection({ serverId, hosts, allHosts, profiles, channels, plans, onChange, onToken, onError }: {
  serverId: string; hosts: Host[]; allHosts: Host[]; profiles: Profile[]; channels: Channel[]; plans: PlanConnection[]; onChange: () => void;
  onToken: (s: { label: string; token: string }) => void; onError: (e: string) => void;
}) {
  const [form, setForm] = useState({ name: '', adapter: 'codex', hostId: '', workdirAlias: 'agora', workspaceId: 'primary', model: '', effort: 'high', channelId: '' });
  // A profile on a machine host runs unboxed; the owner confirms that (docs/agent-boxes.md §10)
  const [unboxedAck, setUnboxedAck] = useState(false);
  const set = (k: keyof typeof form) => (e: { target: { value: string } }) => setForm(f => ({ ...f, [k]: e.target.value }));
  const hostId = form.hostId || hosts[0]?.id || '';
  const opencode = form.adapter === 'opencode';

  const create = async () => {
    try {
      const res = await api.post<{ bot: { username: string }; token: string }>(`/servers/${serverId}/agents`, {
        name: form.name.trim().toLowerCase(), adapter: form.adapter, hostId, workdirAlias: form.workdirAlias.trim(),
        workspaceId: form.workspaceId.trim().toLowerCase(), hostModeAck: true,
        ...(form.model.trim() ? { model: form.model.trim() } : {}),
        ...(form.effort ? { effort: form.effort } : {}),
        ...(form.channelId ? { channelId: form.channelId } : {}),
      });
      setForm(f => ({ ...f, name: '' }));
      setUnboxedAck(false);
      onToken({ label: `Bot token for agent "${res.bot.username}".`, token: res.token });
      onChange();
    } catch (err) { onError(errorText(err)); }
  };

  return (
    <section>
      <h3 className="text-lg font-semibold text-text mb-3">Agents</h3>
      <ul className="mb-4 flex flex-col gap-2">
        {profiles.length === 0 && <li className="text-text-muted text-sm">No agents yet.</li>}
        {profiles.map(p => (
          <ProfileRow key={p.id} serverId={serverId} profile={p} host={allHosts.find(h => h.id === p.hostId && !h.revokedAt)} plan={plans.find(x => x.profileId === p.id)}
            onChange={onChange} onError={onError} />
        ))}
      </ul>

      {hosts.length === 0 ? (
        <p className="text-text-muted text-sm">Create a host first.</p>
      ) : (
        <div className="rounded border border-border bg-surface p-3">
          <h4 className="mb-2 text-sm font-semibold text-text">Create agent</h4>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 text-sm">
            <label className="flex flex-col gap-1 text-text-muted">Name (bot and /start name)
              <input className={input} value={form.name} maxLength={32} placeholder="codex" onChange={set('name')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">CLI
              <select className={input} value={form.adapter} onChange={set('adapter')}>
                <option value="codex">Codex</option>
                <option value="claude">Claude Code</option>
                {/* The host runs it over ACP (gemini --acp) and only with an API key */}
                <option value="gemini">Gemini CLI (ACP, API key)</option>
                {/* opencode acp on an OpenRouter key: any OpenRouter model, one model per agent */}
                <option value="opencode">opencode (ACP, OpenRouter key)</option>
              </select>
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Host
              <select className={input} value={hostId} onChange={set('hostId')}>
                {hosts.map(h => <option key={h.id} value={h.id}>{h.name}</option>)}
              </select>
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Workdir alias (mapped to a folder in the host config)
              <input className={input} value={form.workdirAlias} maxLength={64} onChange={set('workdirAlias')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">{opencode ? 'OpenRouter model ID (required)' : 'Model (optional)'}
              <input className={input} value={form.model} maxLength={64} placeholder={opencode ? 'qwen/qwen3-coder' : 'gpt-6.1-sol'} onChange={set('model')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Workspace ID (same repository = same ID across hosts)
              <input className={input} value={form.workspaceId} maxLength={64} onChange={set('workspaceId')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Effort
              <select className={input} value={form.effort} onChange={set('effort')}>
                {EFFORTS.map(e => <option key={e} value={e}>{e || 'CLI default'}</option>)}
              </select>
            </label>
            <label className="sm:col-span-2 flex flex-col gap-1 text-text-muted">Add to channel (optional)
              <select className={input} value={form.channelId} onChange={set('channelId')}>
                <option value="">None</option>
                {channels.map(c => <option key={c.id} value={c.id}>#{c.name}</option>)}
              </select>
            </label>
          </div>
          <label className="mt-3 flex min-h-11 md:min-h-8 items-start gap-2 text-sm text-text">
            <input type="checkbox" className="mt-1" checked={unboxedAck} onChange={e => setUnboxedAck(e.target.checked)} />
            <span>Run unboxed on this machine (it can read and change your files). <span className="text-text-muted">Only you can wake an unboxed agent. For anything that doesn&apos;t need this machine, create a box instead.</span></span>
          </label>
          <div className="mt-3">
            <Button onClick={() => void create()} disabled={!unboxedAck || !/^[a-z0-9][a-z0-9_-]*$/i.test(form.name.trim()) || !form.workdirAlias.trim() || (opencode && !form.model.trim())}>
              Create agent
            </Button>
          </div>
        </div>
      )}
    </section>
  );
}

function ProfileRow({ serverId, profile, host, plan, onChange, onError }: {
  serverId: string; profile: Profile; host: Host | undefined; plan?: PlanConnection; onChange: () => void; onError: (e: string) => void;
}) {
  const [model, setModel] = useState(profile.model ?? '');
  const [effort, setEffort] = useState(profile.effort ?? '');
  const [workspaceId, setWorkspaceId] = useState(profile.workspaceId ?? 'primary');
  const [wakeBudget, setWakeBudget] = useState(String(profile.wakeBudget));
  const validWakeBudget = Number.isInteger(Number(wakeBudget)) && Number(wakeBudget) >= 1 && Number(wakeBudget) <= 100000;
  const dirty = model !== (profile.model ?? '') || effort !== (profile.effort ?? '') || workspaceId !== (profile.workspaceId ?? 'primary') || wakeBudget !== String(profile.wakeBudget);
  // opencode's own default is an OpenCode Zen model, so an opencode agent always names one
  const opencode = profile.adapter === 'opencode';
  const validModel = !opencode || !!model.trim();

  const save = async () => {
    try {
      if (!validWakeBudget || !validModel) return;
      await api.patch(`/servers/${serverId}/agent-profiles/${profile.id}`, { model: model.trim() || null, effort: effort || null, workspaceId: workspaceId.trim().toLowerCase(), wakeBudget: Number(wakeBudget) });
      onChange();
    } catch (err) { onError(errorText(err)); }
  };
  const remove = async () => {
    if (!confirm(`Delete agent profile "${profile.name}"? Its bot stays; end its sessions first.`)) return;
    try { await api.delete(`/servers/${serverId}/agent-profiles/${profile.id}`); onChange(); } catch (err) { onError(errorText(err)); }
  };

  return (
    <li className="rounded border border-border bg-surface px-3 py-2 text-sm">
      <div className="flex items-center justify-between">
        <span className="text-text">
          <span className="font-medium">{profile.name}</span>
          <BoxModeBadge profile={profile} className="ml-2" />
          <span className="ml-2 text-xs text-text-muted">
            {profile.adapter} · {host?.name ?? 'revoked host'} · workdir {profile.workdirAlias} · {profile.wakeBudget} wakes · {profile.tokenBudget.toLocaleString()} tokens per session
          </span>
          <AuthBadge profile={profile} />
        </span>
        <button className="min-h-11 md:min-h-8 px-2 text-xs text-danger hover:underline" onClick={() => void remove()}>Delete</button>
      </div>
      <div className="mt-2 flex flex-wrap items-center gap-2">
        <label className="flex flex-col text-xs text-text-muted">Workspace ID (end sessions before changing)
          <input className={input} value={workspaceId} maxLength={64} onChange={e => setWorkspaceId(e.target.value)} />
        </label>
        <input className={input} value={model} placeholder={opencode ? 'OpenRouter model ID (required)' : 'model (CLI default)'} maxLength={64}
          aria-label={`Model for ${profile.name}`} onChange={e => setModel(e.target.value)} />
        <select className={input} value={effort} onChange={e => setEffort(e.target.value)}>
          {EFFORTS.map(e => <option key={e} value={e}>{e || 'CLI default'}</option>)}
        </select>
        <label className="flex flex-col text-xs text-text-muted">Wake budget per session
          <input className={input} type="number" min={1} max={100000} step={1} value={wakeBudget}
            onChange={e => setWakeBudget(e.target.value)} aria-label={`Wake budget for ${profile.name}`} />
        </label>
        {dirty && <Button variant="secondary" disabled={!validWakeBudget || !validModel} onClick={() => void save()}>Save</Button>}
      </div>
      {/* A box logs its CLI in from its Boxes entry instead */}
      {profile.adapter === 'codex' && host && host.kind !== 'box' && !profile.boxed && (
        <ChatGPTPlanConnect serverId={serverId} profileId={profile.id} hostName={host.name} plan={plan}
          siwcMode={profile.authMode === 'siwc'} onChange={onChange} />
      )}
      <ToolPermissions serverId={serverId} profile={profile} onChange={onChange} onError={onError} />
    </li>
  );
}

/** How the agent's CLI signs in, as its host reported it (docs/provider-terms.md). */
function AuthBadge({ profile }: { profile: Profile }) {
  const mode = profile.authMode ?? 'subscription';
  const tone = mode === 'api_key' ? 'bg-online/20 text-online' : 'bg-warn/20 text-warn';
  const detail = !profile.authReportedAt
    ? 'not reported by its host yet, so treated as a subscription'
    : mode === 'api_key' ? `key from ${profile.apiKeyEnv}`
    : mode === 'siwc' ? (profile.planOwnerId ? 'only the person who connected their plan can wake it' : 'no ChatGPT plan connected yet')
    : 'only you can wake it';
  return (
    <span className="mt-1 flex flex-wrap items-center gap-2 text-xs text-text-muted" data-testid={`auth-${profile.name}`}>
      <span className={`rounded px-1.5 py-0.5 font-semibold leading-none ${tone}`}>{authLabel(mode, profile.runApproval)}</span>
      {detail}
    </span>
  );
}

/**
 * Tool presets and always-allowed tools (#73). Saved on the server; the host reads them at
 * its next claim, so no host restart. Approving "always" on a tool card adds to the list.
 */
function ToolPermissions({ serverId, profile, onChange, onError }: {
  serverId: string; profile: Profile; onChange: () => void; onError: (e: string) => void;
}) {
  const presets = profile.toolPresets ?? [];
  const allowed = profile.allowedTools ?? [];
  const [rule, setRule] = useState('');
  const [busy, setBusy] = useState(false);
  const valid = TOOL_RULE.test(rule.trim()) && !allowed.includes(rule.trim());

  const patch = async (body: { toolPresets?: string[]; allowedTools?: string[] }) => {
    setBusy(true);
    try { await api.patch(`/servers/${serverId}/agent-profiles/${profile.id}`, body); onChange(); }
    catch (err) { onError(errorText(err)); }
    finally { setBusy(false); }
  };
  const toggle = (name: string) => void patch({ toolPresets: presets.includes(name) ? presets.filter(p => p !== name) : [...presets, name] });

  return (
    <div className="mt-3 border-t border-border pt-2">
      <div className="mb-1 text-xs font-semibold text-text-muted">Tools</div>
      <div className="flex flex-wrap gap-x-4 gap-y-1" role="group" aria-label={`Tool presets for ${profile.name}`}>
        {PRESETS.map(p => (
          <label key={p.name} className="flex min-h-11 md:min-h-8 items-center gap-2 text-sm text-text">
            <input type="checkbox" checked={presets.includes(p.name)} disabled={busy} onChange={() => toggle(p.name)} />
            {p.label} <span className="text-xs text-text-muted">{p.detail}</span>
          </label>
        ))}
        {presets.filter(n => !PRESETS.some(p => p.name === n)).map(n => (
          <label key={n} className="flex min-h-11 md:min-h-8 items-center gap-2 text-sm text-text">
            <input type="checkbox" checked disabled={busy} onChange={() => toggle(n)} /> {n} <span className="text-xs text-text-muted">from host config</span>
          </label>
        ))}
      </div>
      <p className="mt-1 text-xs text-text-muted">
        {presets.length === 0 ? 'No preset: the host config alone decides.' : 'Changes apply from the next wake; no host restart.'}
      </p>
      {allowed.length > 0 && (
        <ul className="mt-2 flex flex-wrap gap-1" aria-label={`Always allowed tools for ${profile.name}`}>
          {allowed.map(t => (
            <li key={t} className="flex items-center gap-1 rounded border border-border bg-bg px-2 font-mono text-xs text-text">
              <span className="break-all">{t}</span>
              <button className="min-h-11 min-w-11 md:min-h-7 md:min-w-7 text-danger" disabled={busy} aria-label={`Remove ${t}`}
                onClick={() => void patch({ allowedTools: allowed.filter(a => a !== t) })}>×</button>
            </li>
          ))}
        </ul>
      )}
      <div className="mt-2 flex items-center gap-2">
        <input className={`${input} flex-1 font-mono`} value={rule} placeholder="Always allow, e.g. Bash(cargo:*)" maxLength={310}
          aria-label={`Add an always-allowed tool for ${profile.name}`} onChange={e => setRule(e.target.value)} />
        <Button variant="secondary" disabled={!valid || busy} onClick={() => { const t = rule.trim(); setRule(''); void patch({ allowedTools: [...allowed, t] }); }}>Add</Button>
      </div>
    </div>
  );
}

import { useCallback, useEffect, useState } from 'react';
import { useServerStore } from '../../stores/serverStore';
import { api, serverApi, ApiError } from '../../lib/api';
import type { Channel } from '../../lib/contracts/server';
import { Button } from '../../components/ui/Button';
import { NotAffiliated } from '../../components/ui/NotAffiliated';
import { authLabel } from '../agents/agentSessions';
import { ChatGPTPlanConnect, type PlanConnection } from './ChatGPTPlanConnect';
import { useAuthStore } from '../../stores/authStore';
import { BoxesSection } from '../boxes/BoxesSection';
import { BoxModeBadge } from '../boxes/BoxModeBadge';

/**
 * Agent hosts and agents (docs/planning/agent-sessions-wbs.md, S6). The owner registers the
 * machine that runs agents (a host) and creates agents on it; members then use /start in a
 * channel. Tokens are shown once and go into the host's config file, never into a channel.
 */

/** kind 'box': the agora-host inside a box (docs/agent-boxes.md §8.1); listed under Boxes, not here. */
interface Host { id: string; name: string; createdAt: string; lastSeenAt: string | null; revokedAt: any; kind?: 'machine' | 'box' }
interface Profile {
  id: string; name: string; botId: string; hostId: string; adapter: 'codex' | 'claude' | 'gemini' | 'opencode';
  model: string | null; effort: string | null; workdirAlias: string; workspaceId?: string;
  wakeBudget: number; tokenBudget: number; runTimeoutSec: number;
  toolPresets?: string[]; allowedTools?: string[];
  /** Reported by the host at start (docs/provider-terms.md); subscription until then. */
  authMode?: 'subscription' | 'api_key' | 'siwc'; apiKeyEnv?: string | null; runApproval?: boolean; authReportedAt?: string | null;
  /** 'siwc' only: whose ChatGPT plan it runs on (docs/codex-chatgpt-plan.md). */
  planOwnerId?: string | null;
  /** Its host is a box (docs/agent-boxes.md §10); otherwise it runs unboxed on a machine. */
  boxed?: boolean; hostMode?: boolean;
}

const EFFORTS = ['', 'low', 'medium', 'high', 'xhigh'];

/** Built-in tool presets (agora-host/src/presets.ts); the host config can redefine them. */
const PRESETS: { name: string; label: string; detail: string }[] = [
  { name: 'readonly', label: 'Read-only', detail: 'read files and git history' },
  { name: 'dev', label: 'Dev', detail: 'edit files, git, gh, npm' },
  { name: 'research', label: 'Research', detail: 'web search and fetch' },
];
/** Same rule shape the server accepts: a Claude permission rule or a Codex word (write, network, web_search). */
const TOOL_RULE = /^[A-Za-z][A-Za-z0-9_]{0,99}(\([^(),\r\n]{1,200}\))?$/;
const input = 'min-h-11 md:min-h-9 bg-bg border border-border rounded px-3 py-1.5 text-sm text-text placeholder:text-text-muted/70 focus:outline-none focus:ring-2 focus:ring-primary';

function errorText(err: unknown): string {
  if (err instanceof ApiError) return err.status === 403 ? 'Only the server owner can do this.' : err.code;
  return 'Request failed';
}

function OnceToken({ label, token, onDone }: { label: string; token: string; onDone: () => void }) {
  return (
    <div className="mb-4 rounded border border-primary/50 bg-primary/10 p-3 text-sm">
      <p className="mb-2 text-text">{label} It is shown only now; put it in the host's config file.</p>
      <code className="block break-all rounded bg-bg p-2 font-mono text-xs text-text select-all">{token}</code>
      <div className="mt-2 flex gap-2">
        <Button variant="secondary" onClick={() => { void navigator.clipboard?.writeText(token); }}>Copy</Button>
        <Button variant="secondary" onClick={onDone}>Done</Button>
      </div>
    </div>
  );
}

export function AgentSessionsSettings() {
  const serverId = useServerStore(s => s.instanceServerId);
  const ownerId = useServerStore(s => (serverId ? s.servers.get(serverId)?.ownerId : undefined));
  const userId = useAuthStore(s => s.user?.id);
  const [hosts, setHosts] = useState<Host[]>([]);
  const [profiles, setProfiles] = useState<Profile[]>([]);
  const [channels, setChannels] = useState<Channel[]>([]);
  const [plans, setPlans] = useState<PlanConnection[]>([]);
  const [error, setError] = useState('');
  const [secret, setSecret] = useState<{ label: string; token: string } | null>(null);
  const [reloadKey, setReloadKey] = useState(0);
  const load = useCallback(() => setReloadKey(k => k + 1), []);

  useEffect(() => {
    if (!serverId) return;
    let cancelled = false;
    Promise.all([
      api.get<Host[]>(`/servers/${serverId}/agent-hosts`),
      api.get<Profile[]>(`/servers/${serverId}/agent-profiles`),
      serverApi.getChannels(serverId),
      // ChatGPT plan connections; an older server without them just shows none
      api.get<PlanConnection[]>(`/servers/${serverId}/agent-plans`).catch(() => [] as PlanConnection[]),
    ]).then(([h, p, c, pl]) => {
      if (cancelled) return;
      setHosts(h);
      setProfiles(p);
      setPlans(pl);
      setChannels(c.filter(ch => ch.channelType === 3));
      setError('');
    }).catch(err => { if (!cancelled) setError(errorText(err)); });
    return () => { cancelled = true; };
  }, [serverId, reloadKey]);

  if (!serverId) return null;
  // Box hosts are managed with their box; agents are created on machine hosts here
  const machineHosts = hosts.filter(h => h.kind !== 'box');
  const activeHosts = machineHosts.filter(h => !h.revokedAt);
  const isOwner = !!userId && !!ownerId && userId.trim() === ownerId.trim();

  return (
    <div className="max-w-3xl">
      <h2 className="text-xl font-bold text-text mb-2">Agents</h2>
      <p className="text-text-muted text-sm mb-6">
        An agent host runs on the machine with your agent CLIs and wakes agents when they are addressed. Create a host,
        put its token in the host's config, then create agents on it. In a channel, <code>/start &lt;agent&gt;</code> starts a session.
      </p>
      {error && <p className="text-danger text-sm mb-4">{error}</p>}
      {secret && <OnceToken label={secret.label} token={secret.token} onDone={() => setSecret(null)} />}

      <p className="text-text-muted text-xs mb-6">
        Each agent runs its CLI on your own login (<em>subscription</em>) or on an API key, as set in the host's config.
        Personal subscriptions are for one person, so only you can wake a subscription agent; give agents that other
        members wake an API key. A Codex agent can also run on a ChatGPT plan through Sign in with ChatGPT; only the
        person who connected their plan can wake it. See docs/provider-terms.md and docs/codex-chatgpt-plan.md.
      </p>

      <BoxesSection serverId={serverId} channels={channels} isOwner={isOwner} />
      <HostsSection serverId={serverId} hosts={machineHosts} onChange={load} onToken={setSecret} onError={setError} />
      <AgentsSection serverId={serverId} hosts={activeHosts} allHosts={hosts} profiles={profiles} channels={channels} plans={plans}
        onChange={load} onToken={setSecret} onError={setError} />
      <NotAffiliated className="mt-8" />
    </div>
  );
}

function HostsSection({ serverId, hosts, onChange, onToken, onError }: {
  serverId: string; hosts: Host[]; onChange: () => void;
  onToken: (s: { label: string; token: string }) => void; onError: (e: string) => void;
}) {
  const [name, setName] = useState('');
  const create = async () => {
    try {
      const res = await api.post<{ host: Host; token: string }>(`/servers/${serverId}/agent-hosts`, { name: name.trim() });
      setName('');
      onToken({ label: `Host token for "${res.host.name}".`, token: res.token });
      onChange();
    } catch (err) { onError(errorText(err)); }
  };
  const revoke = async (h: Host) => {
    if (!confirm(`Revoke host "${h.name}"? Its token stops working at once and its agents stop waking.`)) return;
    try { await api.delete(`/servers/${serverId}/agent-hosts/${h.id}`); onChange(); } catch (err) { onError(errorText(err)); }
  };
  return (
    <section className="mb-8">
      <h3 className="text-lg font-semibold text-text mb-3">Hosts</h3>
      <ul className="mb-3 flex flex-col gap-1">
        {hosts.length === 0 && <li className="text-text-muted text-sm">No hosts yet.</li>}
        {hosts.map(h => (
          <li key={h.id} className="flex items-center justify-between rounded border border-border bg-surface px-3 py-2 text-sm">
            <span className={h.revokedAt ? 'text-text-muted line-through' : 'text-text'}>
              {h.name}
              <span className="ml-2 text-xs text-text-muted">
                {h.revokedAt ? 'revoked' : h.lastSeenAt ? `last seen ${new Date(h.lastSeenAt).toLocaleString()}` : 'never connected'}
              </span>
            </span>
            {!h.revokedAt && <button className="min-h-11 md:min-h-8 px-2 text-xs text-danger hover:underline" onClick={() => void revoke(h)}>Revoke</button>}
          </li>
        ))}
      </ul>
      <div className="flex gap-2">
        <input className={input} placeholder="Host name, e.g. my-pc" value={name} maxLength={64} onChange={e => setName(e.target.value)} />
        <Button onClick={() => void create()} disabled={!name.trim()}>Create host</Button>
      </div>
    </section>
  );
}

function AgentsSection({ serverId, hosts, allHosts, profiles, channels, plans, onChange, onToken, onError }: {
  serverId: string; hosts: Host[]; allHosts: Host[]; profiles: Profile[]; channels: Channel[]; plans: PlanConnection[]; onChange: () => void;
  onToken: (s: { label: string; token: string }) => void; onError: (e: string) => void;
}) {
  const [form, setForm] = useState({ name: '', adapter: 'codex', hostId: '', workdirAlias: 'agora', workspaceId: 'primary', model: '', effort: 'high', channelId: '' });
  // A profile on a machine host runs unboxed; the owner confirms that (docs/agent-boxes.md §10)
  const [unboxedAck, setUnboxedAck] = useState(false);
  const set = (k: keyof typeof form) => (e: { target: { value: string } }) => setForm(f => ({ ...f, [k]: e.target.value }));
  const hostId = form.hostId || hosts[0]?.id || '';
  const opencode = form.adapter === 'opencode';

  const create = async () => {
    try {
      const res = await api.post<{ bot: { username: string }; token: string }>(`/servers/${serverId}/agents`, {
        name: form.name.trim().toLowerCase(), adapter: form.adapter, hostId, workdirAlias: form.workdirAlias.trim(),
        workspaceId: form.workspaceId.trim().toLowerCase(), hostModeAck: true,
        ...(form.model.trim() ? { model: form.model.trim() } : {}),
        ...(form.effort ? { effort: form.effort } : {}),
        ...(form.channelId ? { channelId: form.channelId } : {}),
      });
      setForm(f => ({ ...f, name: '' }));
      setUnboxedAck(false);
      onToken({ label: `Bot token for agent "${res.bot.username}".`, token: res.token });
      onChange();
    } catch (err) { onError(errorText(err)); }
  };

  return (
    <section>
      <h3 className="text-lg font-semibold text-text mb-3">Agents</h3>
      <ul className="mb-4 flex flex-col gap-2">
        {profiles.length === 0 && <li className="text-text-muted text-sm">No agents yet.</li>}
        {profiles.map(p => (
          <ProfileRow key={p.id} serverId={serverId} profile={p} host={allHosts.find(h => h.id === p.hostId && !h.revokedAt)} plan={plans.find(x => x.profileId === p.id)}
            onChange={onChange} onError={onError} />
        ))}
      </ul>

      {hosts.length === 0 ? (
        <p className="text-text-muted text-sm">Create a host first.</p>
      ) : (
        <div className="rounded border border-border bg-surface p-3">
          <h4 className="mb-2 text-sm font-semibold text-text">Create agent</h4>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 text-sm">
            <label className="flex flex-col gap-1 text-text-muted">Name (bot and /start name)
              <input className={input} value={form.name} maxLength={32} placeholder="codex" onChange={set('name')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">CLI
              <select className={input} value={form.adapter} onChange={set('adapter')}>
                <option value="codex">Codex</option>
                <option value="claude">Claude Code</option>
                {/* The host runs it over ACP (gemini --acp) and only with an API key */}
                <option value="gemini">Gemini CLI (ACP, API key)</option>
                {/* opencode acp on an OpenRouter key: any OpenRouter model, one model per agent */}
                <option value="opencode">opencode (ACP, OpenRouter key)</option>
              </select>
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Host
              <select className={input} value={hostId} onChange={set('hostId')}>
                {hosts.map(h => <option key={h.id} value={h.id}>{h.name}</option>)}
              </select>
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Workdir alias (mapped to a folder in the host config)
              <input className={input} value={form.workdirAlias} maxLength={64} onChange={set('workdirAlias')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">{opencode ? 'OpenRouter model ID (required)' : 'Model (optional)'}
              <input className={input} value={form.model} maxLength={64} placeholder={opencode ? 'qwen/qwen3-coder' : 'gpt-6.1-sol'} onChange={set('model')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Workspace ID (same repository = same ID across hosts)
              <input className={input} value={form.workspaceId} maxLength={64} onChange={set('workspaceId')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Effort
              <select className={input} value={form.effort} onChange={set('effort')}>
                {EFFORTS.map(e => <option key={e} value={e}>{e || 'CLI default'}</option>)}
              </select>
            </label>
            <label className="sm:col-span-2 flex flex-col gap-1 text-text-muted">Add to channel (optional)
              <select className={input} value={form.channelId} onChange={set('channelId')}>
                <option value="">None</option>
                {channels.map(c => <option key={c.id} value={c.id}>#{c.name}</option>)}
              </select>
            </label>
          </div>
          <label className="mt-3 flex min-h-11 md:min-h-8 items-start gap-2 text-sm text-text">
            <input type="checkbox" className="mt-1" checked={unboxedAck} onChange={e => setUnboxedAck(e.target.checked)} />
            <span>Run unboxed on this machine (it can read and change your files). <span className="text-text-muted">Only you can wake an unboxed agent. For anything that doesn&apos;t need this machine, create a box instead.</span></span>
          </label>
          <div className="mt-3">
            <Button onClick={() => void create()} disabled={!unboxedAck || !/^[a-z0-9][a-z0-9_-]*$/i.test(form.name.trim()) || !form.workdirAlias.trim() || (opencode && !form.model.trim())}>
              Create agent
            </Button>
          </div>
        </div>
      )}
    </section>
  );
}

function ProfileRow({ serverId, profile, host, plan, onChange, onError }: {
  serverId: string; profile: Profile; host: Host | undefined; plan?: PlanConnection; onChange: () => void; onError: (e: string) => void;
}) {
  const [model, setModel] = useState(profile.model ?? '');
  const [effort, setEffort] = useState(profile.effort ?? '');
  const [workspaceId, setWorkspaceId] = useState(profile.workspaceId ?? 'primary');
  const [wakeBudget, setWakeBudget] = useState(String(profile.wakeBudget));
  const validWakeBudget = Number.isInteger(Number(wakeBudget)) && Number(wakeBudget) >= 1 && Number(wakeBudget) <= 100000;
  const dirty = model !== (profile.model ?? '') || effort !== (profile.effort ?? '') || workspaceId !== (profile.workspaceId ?? 'primary') || wakeBudget !== String(profile.wakeBudget);
  // opencode's own default is an OpenCode Zen model, so an opencode agent always names one
  const opencode = profile.adapter === 'opencode';
  const validModel = !opencode || !!model.trim();

  const save = async () => {
    try {
      if (!validWakeBudget || !validModel) return;
      await api.patch(`/servers/${serverId}/agent-profiles/${profile.id}`, { model: model.trim() || null, effort: effort || null, workspaceId: workspaceId.trim().toLowerCase(), wakeBudget: Number(wakeBudget) });
      onChange();
    } catch (err) { onError(errorText(err)); }
  };
  const remove = async () => {
    if (!confirm(`Delete agent profile "${profile.name}"? Its bot stays; end its sessions first.`)) return;
    try { await api.delete(`/servers/${serverId}/agent-profiles/${profile.id}`); onChange(); } catch (err) { onError(errorText(err)); }
  };

  return (
    <li className="rounded border border-border bg-surface px-3 py-2 text-sm">
      <div className="flex items-center justify-between">
        <span className="text-text">
          <span className="font-medium">{profile.name}</span>
          <BoxModeBadge profile={profile} className="ml-2" />
          <span className="ml-2 text-xs text-text-muted">
            {profile.adapter} · {host?.name ?? 'revoked host'} · workdir {profile.workdirAlias} · {profile.wakeBudget} wakes · {profile.tokenBudget.toLocaleString()} tokens per session
          </span>
          <AuthBadge profile={profile} />
        </span>
        <button className="min-h-11 md:min-h-8 px-2 text-xs text-danger hover:underline" onClick={() => void remove()}>Delete</button>
      </div>
      <div className="mt-2 flex flex-wrap items-center gap-2">
        <label className="flex flex-col text-xs text-text-muted">Workspace ID (end sessions before changing)
          <input className={input} value={workspaceId} maxLength={64} onChange={e => setWorkspaceId(e.target.value)} />
        </label>
        <input className={input} value={model} placeholder={opencode ? 'OpenRouter model ID (required)' : 'model (CLI default)'} maxLength={64}
          aria-label={`Model for ${profile.name}`} onChange={e => setModel(e.target.value)} />
        <select className={input} value={effort} onChange={e => setEffort(e.target.value)}>
          {EFFORTS.map(e => <option key={e} value={e}>{e || 'CLI default'}</option>)}
        </select>
        <label className="flex flex-col text-xs text-text-muted">Wake budget per session
          <input className={input} type="number" min={1} max={100000} step={1} value={wakeBudget}
            onChange={e => setWakeBudget(e.target.value)} aria-label={`Wake budget for ${profile.name}`} />
        </label>
        {dirty && <Button variant="secondary" disabled={!validWakeBudget || !validModel} onClick={() => void save()}>Save</Button>}
      </div>
      {/* A box logs its CLI in from its Boxes entry instead */}
      {profile.adapter === 'codex' && host && host.kind !== 'box' && !profile.boxed && (
        <ChatGPTPlanConnect serverId={serverId} profileId={profile.id} hostName={host.name} plan={plan}
          siwcMode={profile.authMode === 'siwc'} onChange={onChange} />
      )}
      <ToolPermissions serverId={serverId} profile={profile} onChange={onChange} onError={onError} />
    </li>
  );
}

/** How the agent's CLI signs in, as its host reported it (docs/provider-terms.md). */
function AuthBadge({ profile }: { profile: Profile }) {
  const mode = profile.authMode ?? 'subscription';
  const tone = mode === 'api_key' ? 'bg-online/20 text-online' : 'bg-warn/20 text-warn';
  const detail = !profile.authReportedAt
    ? 'not reported by its host yet, so treated as a subscription'
    : mode === 'api_key' ? `key from ${profile.apiKeyEnv}`
    : mode === 'siwc' ? (profile.planOwnerId ? 'only the person who connected their plan can wake it' : 'no ChatGPT plan connected yet')
    : 'only you can wake it';
  return (
    <span className="mt-1 flex flex-wrap items-center gap-2 text-xs text-text-muted" data-testid={`auth-${profile.name}`}>
      <span className={`rounded px-1.5 py-0.5 font-semibold leading-none ${tone}`}>{authLabel(mode, profile.runApproval)}</span>
      {detail}
    </span>
  );
}

/**
 * Tool presets and always-allowed tools (#73). Saved on the server; the host reads them at
 * its next claim, so no host restart. Approving "always" on a tool card adds to the list.
 */
function ToolPermissions({ serverId, profile, onChange, onError }: {
  serverId: string; profile: Profile; onChange: () => void; onError: (e: string) => void;
}) {
  const presets = profile.toolPresets ?? [];
  const allowed = profile.allowedTools ?? [];
  const [rule, setRule] = useState('');
  const [busy, setBusy] = useState(false);
  const valid = TOOL_RULE.test(rule.trim()) && !allowed.includes(rule.trim());

  const patch = async (body: { toolPresets?: string[]; allowedTools?: string[] }) => {
    setBusy(true);
    try { await api.patch(`/servers/${serverId}/agent-profiles/${profile.id}`, body); onChange(); }
    catch (err) { onError(errorText(err)); }
    finally { setBusy(false); }
  };
  const toggle = (name: string) => void patch({ toolPresets: presets.includes(name) ? presets.filter(p => p !== name) : [...presets, name] });

  return (
    <div className="mt-3 border-t border-border pt-2">
      <div className="mb-1 text-xs font-semibold text-text-muted">Tools</div>
      <div className="flex flex-wrap gap-x-4 gap-y-1" role="group" aria-label={`Tool presets for ${profile.name}`}>
        {PRESETS.map(p => (
          <label key={p.name} className="flex min-h-11 md:min-h-8 items-center gap-2 text-sm text-text">
            <input type="checkbox" checked={presets.includes(p.name)} disabled={busy} onChange={() => toggle(p.name)} />
            {p.label} <span className="text-xs text-text-muted">{p.detail}</span>
          </label>
        ))}
        {presets.filter(n => !PRESETS.some(p => p.name === n)).map(n => (
          <label key={n} className="flex min-h-11 md:min-h-8 items-center gap-2 text-sm text-text">
            <input type="checkbox" checked disabled={busy} onChange={() => toggle(n)} /> {n} <span className="text-xs text-text-muted">from host config</span>
          </label>
        ))}
      </div>
      <p className="mt-1 text-xs text-text-muted">
        {presets.length === 0 ? 'No preset: the host config alone decides.' : 'Changes apply from the next wake; no host restart.'}
      </p>
      {allowed.length > 0 && (
        <ul className="mt-2 flex flex-wrap gap-1" aria-label={`Always allowed tools for ${profile.name}`}>
          {allowed.map(t => (
            <li key={t} className="flex items-center gap-1 rounded border border-border bg-bg px-2 font-mono text-xs text-text">
              <span className="break-all">{t}</span>
              <button className="min-h-11 min-w-11 md:min-h-7 md:min-w-7 text-danger" disabled={busy} aria-label={`Remove ${t}`}
                onClick={() => void patch({ allowedTools: allowed.filter(a => a !== t) })}>×</button>
            </li>
          ))}
        </ul>
      )}
      <div className="mt-2 flex items-center gap-2">
        <input className={`${input} flex-1 font-mono`} value={rule} placeholder="Always allow, e.g. Bash(cargo:*)" maxLength={310}
          aria-label={`Add an always-allowed tool for ${profile.name}`} onChange={e => setRule(e.target.value)} />
        <Button variant="secondary" disabled={!valid || busy} onClick={() => { const t = rule.trim(); setRule(''); void patch({ allowedTools: [...allowed, t] }); }}>Add</Button>
      </div>
    </div>
  );
}

import { useCallback, useEffect, useState } from 'react';
import { useServerStore } from '../../stores/serverStore';
import { api, serverApi, ApiError } from '../../lib/api';
import type { Channel } from '../../lib/contracts/server';
import { Button } from '../../components/ui/Button';
import { NotAffiliated } from '../../components/ui/NotAffiliated';
import { authLabel } from '../agents/agentSessions';
import { ChatGPTPlanConnect, type PlanConnection } from './ChatGPTPlanConnect';
import { useAuthStore } from '../../stores/authStore';
import { BoxesSection } from '../boxes/BoxesSection';
import { BoxModeBadge } from '../boxes/BoxModeBadge';

/**
 * Agent hosts and agents (docs/planning/agent-sessions-wbs.md, S6). The owner registers the
 * machine that runs agents (a host) and creates agents on it; members then use /start in a
 * channel. Tokens are shown once and go into the host's config file, never into a channel.
 */

/** kind 'box': the agora-host inside a box (docs/agent-boxes.md §8.1); listed under Boxes, not here. */
interface Host { id: string; name: string; createdAt: string; lastSeenAt: string | null; revokedAt: string | null; kind?: any }
interface Profile {
  id: string; name: string; botId: string; hostId: string; adapter: 'codex' | 'claude' | 'gemini' | 'opencode';
  model: string | null; effort: string | null; workdirAlias: string; workspaceId?: string;
  wakeBudget: number; tokenBudget: number; runTimeoutSec: number;
  toolPresets?: string[]; allowedTools?: string[];
  /** Reported by the host at start (docs/provider-terms.md); subscription until then. */
  authMode?: 'subscription' | 'api_key' | 'siwc'; apiKeyEnv?: string | null; runApproval?: boolean; authReportedAt?: string | null;
  /** 'siwc' only: whose ChatGPT plan it runs on (docs/codex-chatgpt-plan.md). */
  planOwnerId?: string | null;
  /** Its host is a box (docs/agent-boxes.md §10); otherwise it runs unboxed on a machine. */
  boxed?: boolean; hostMode?: boolean;
}

const EFFORTS = ['', 'low', 'medium', 'high', 'xhigh'];

/** Built-in tool presets (agora-host/src/presets.ts); the host config can redefine them. */
const PRESETS: { name: string; label: string; detail: string }[] = [
  { name: 'readonly', label: 'Read-only', detail: 'read files and git history' },
  { name: 'dev', label: 'Dev', detail: 'edit files, git, gh, npm' },
  { name: 'research', label: 'Research', detail: 'web search and fetch' },
];
/** Same rule shape the server accepts: a Claude permission rule or a Codex word (write, network, web_search). */
const TOOL_RULE = /^[A-Za-z][A-Za-z0-9_]{0,99}(\([^(),\r\n]{1,200}\))?$/;
const input = 'min-h-11 md:min-h-9 bg-bg border border-border rounded px-3 py-1.5 text-sm text-text placeholder:text-text-muted/70 focus:outline-none focus:ring-2 focus:ring-primary';

function errorText(err: unknown): string {
  if (err instanceof ApiError) return err.status === 403 ? 'Only the server owner can do this.' : err.code;
  return 'Request failed';
}

function OnceToken({ label, token, onDone }: { label: string; token: string; onDone: () => void }) {
  return (
    <div className="mb-4 rounded border border-primary/50 bg-primary/10 p-3 text-sm">
      <p className="mb-2 text-text">{label} It is shown only now; put it in the host's config file.</p>
      <code className="block break-all rounded bg-bg p-2 font-mono text-xs text-text select-all">{token}</code>
      <div className="mt-2 flex gap-2">
        <Button variant="secondary" onClick={() => { void navigator.clipboard?.writeText(token); }}>Copy</Button>
        <Button variant="secondary" onClick={onDone}>Done</Button>
      </div>
    </div>
  );
}

export function AgentSessionsSettings() {
  const serverId = useServerStore(s => s.instanceServerId);
  const ownerId = useServerStore(s => (serverId ? s.servers.get(serverId)?.ownerId : undefined));
  const userId = useAuthStore(s => s.user?.id);
  const [hosts, setHosts] = useState<Host[]>([]);
  const [profiles, setProfiles] = useState<Profile[]>([]);
  const [channels, setChannels] = useState<Channel[]>([]);
  const [plans, setPlans] = useState<PlanConnection[]>([]);
  const [error, setError] = useState('');
  const [secret, setSecret] = useState<{ label: string; token: string } | null>(null);
  const [reloadKey, setReloadKey] = useState(0);
  const load = useCallback(() => setReloadKey(k => k + 1), []);

  useEffect(() => {
    if (!serverId) return;
    let cancelled = false;
    Promise.all([
      api.get<Host[]>(`/servers/${serverId}/agent-hosts`),
      api.get<Profile[]>(`/servers/${serverId}/agent-profiles`),
      serverApi.getChannels(serverId),
      // ChatGPT plan connections; an older server without them just shows none
      api.get<PlanConnection[]>(`/servers/${serverId}/agent-plans`).catch(() => [] as PlanConnection[]),
    ]).then(([h, p, c, pl]) => {
      if (cancelled) return;
      setHosts(h);
      setProfiles(p);
      setPlans(pl);
      setChannels(c.filter(ch => ch.channelType === 3));
      setError('');
    }).catch(err => { if (!cancelled) setError(errorText(err)); });
    return () => { cancelled = true; };
  }, [serverId, reloadKey]);

  if (!serverId) return null;
  // Box hosts are managed with their box; agents are created on machine hosts here
  const machineHosts = hosts.filter(h => h.kind !== 'box');
  const activeHosts = machineHosts.filter(h => !h.revokedAt);
  const isOwner = !!userId && !!ownerId && userId.trim() === ownerId.trim();

  return (
    <div className="max-w-3xl">
      <h2 className="text-xl font-bold text-text mb-2">Agents</h2>
      <p className="text-text-muted text-sm mb-6">
        An agent host runs on the machine with your agent CLIs and wakes agents when they are addressed. Create a host,
        put its token in the host's config, then create agents on it. In a channel, <code>/start &lt;agent&gt;</code> starts a session.
      </p>
      {error && <p className="text-danger text-sm mb-4">{error}</p>}
      {secret && <OnceToken label={secret.label} token={secret.token} onDone={() => setSecret(null)} />}

      <p className="text-text-muted text-xs mb-6">
        Each agent runs its CLI on your own login (<em>subscription</em>) or on an API key, as set in the host's config.
        Personal subscriptions are for one person, so only you can wake a subscription agent; give agents that other
        members wake an API key. A Codex agent can also run on a ChatGPT plan through Sign in with ChatGPT; only the
        person who connected their plan can wake it. See docs/provider-terms.md and docs/codex-chatgpt-plan.md.
      </p>

      <BoxesSection serverId={serverId} channels={channels} isOwner={isOwner} />
      <HostsSection serverId={serverId} hosts={machineHosts} onChange={load} onToken={setSecret} onError={setError} />
      <AgentsSection serverId={serverId} hosts={activeHosts} allHosts={hosts} profiles={profiles} channels={channels} plans={plans}
        onChange={load} onToken={setSecret} onError={setError} />
      <NotAffiliated className="mt-8" />
    </div>
  );
}

function HostsSection({ serverId, hosts, onChange, onToken, onError }: {
  serverId: string; hosts: Host[]; onChange: () => void;
  onToken: (s: { label: string; token: string }) => void; onError: (e: string) => void;
}) {
  const [name, setName] = useState('');
  const create = async () => {
    try {
      const res = await api.post<{ host: Host; token: string }>(`/servers/${serverId}/agent-hosts`, { name: name.trim() });
      setName('');
      onToken({ label: `Host token for "${res.host.name}".`, token: res.token });
      onChange();
    } catch (err) { onError(errorText(err)); }
  };
  const revoke = async (h: Host) => {
    if (!confirm(`Revoke host "${h.name}"? Its token stops working at once and its agents stop waking.`)) return;
    try { await api.delete(`/servers/${serverId}/agent-hosts/${h.id}`); onChange(); } catch (err) { onError(errorText(err)); }
  };
  return (
    <section className="mb-8">
      <h3 className="text-lg font-semibold text-text mb-3">Hosts</h3>
      <ul className="mb-3 flex flex-col gap-1">
        {hosts.length === 0 && <li className="text-text-muted text-sm">No hosts yet.</li>}
        {hosts.map(h => (
          <li key={h.id} className="flex items-center justify-between rounded border border-border bg-surface px-3 py-2 text-sm">
            <span className={h.revokedAt ? 'text-text-muted line-through' : 'text-text'}>
              {h.name}
              <span className="ml-2 text-xs text-text-muted">
                {h.revokedAt ? 'revoked' : h.lastSeenAt ? `last seen ${new Date(h.lastSeenAt).toLocaleString()}` : 'never connected'}
              </span>
            </span>
            {!h.revokedAt && <button className="min-h-11 md:min-h-8 px-2 text-xs text-danger hover:underline" onClick={() => void revoke(h)}>Revoke</button>}
          </li>
        ))}
      </ul>
      <div className="flex gap-2">
        <input className={input} placeholder="Host name, e.g. my-pc" value={name} maxLength={64} onChange={e => setName(e.target.value)} />
        <Button onClick={() => void create()} disabled={!name.trim()}>Create host</Button>
      </div>
    </section>
  );
}

function AgentsSection({ serverId, hosts, allHosts, profiles, channels, plans, onChange, onToken, onError }: {
  serverId: string; hosts: Host[]; allHosts: Host[]; profiles: Profile[]; channels: Channel[]; plans: PlanConnection[]; onChange: () => void;
  onToken: (s: { label: string; token: string }) => void; onError: (e: string) => void;
}) {
  const [form, setForm] = useState({ name: '', adapter: 'codex', hostId: '', workdirAlias: 'agora', workspaceId: 'primary', model: '', effort: 'high', channelId: '' });
  // A profile on a machine host runs unboxed; the owner confirms that (docs/agent-boxes.md §10)
  const [unboxedAck, setUnboxedAck] = useState(false);
  const set = (k: keyof typeof form) => (e: { target: { value: string } }) => setForm(f => ({ ...f, [k]: e.target.value }));
  const hostId = form.hostId || hosts[0]?.id || '';
  const opencode = form.adapter === 'opencode';

  const create = async () => {
    try {
      const res = await api.post<{ bot: { username: string }; token: string }>(`/servers/${serverId}/agents`, {
        name: form.name.trim().toLowerCase(), adapter: form.adapter, hostId, workdirAlias: form.workdirAlias.trim(),
        workspaceId: form.workspaceId.trim().toLowerCase(), hostModeAck: true,
        ...(form.model.trim() ? { model: form.model.trim() } : {}),
        ...(form.effort ? { effort: form.effort } : {}),
        ...(form.channelId ? { channelId: form.channelId } : {}),
      });
      setForm(f => ({ ...f, name: '' }));
      setUnboxedAck(false);
      onToken({ label: `Bot token for agent "${res.bot.username}".`, token: res.token });
      onChange();
    } catch (err) { onError(errorText(err)); }
  };

  return (
    <section>
      <h3 className="text-lg font-semibold text-text mb-3">Agents</h3>
      <ul className="mb-4 flex flex-col gap-2">
        {profiles.length === 0 && <li className="text-text-muted text-sm">No agents yet.</li>}
        {profiles.map(p => (
          <ProfileRow key={p.id} serverId={serverId} profile={p} host={allHosts.find(h => h.id === p.hostId && !h.revokedAt)} plan={plans.find(x => x.profileId === p.id)}
            onChange={onChange} onError={onError} />
        ))}
      </ul>

      {hosts.length === 0 ? (
        <p className="text-text-muted text-sm">Create a host first.</p>
      ) : (
        <div className="rounded border border-border bg-surface p-3">
          <h4 className="mb-2 text-sm font-semibold text-text">Create agent</h4>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 text-sm">
            <label className="flex flex-col gap-1 text-text-muted">Name (bot and /start name)
              <input className={input} value={form.name} maxLength={32} placeholder="codex" onChange={set('name')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">CLI
              <select className={input} value={form.adapter} onChange={set('adapter')}>
                <option value="codex">Codex</option>
                <option value="claude">Claude Code</option>
                {/* The host runs it over ACP (gemini --acp) and only with an API key */}
                <option value="gemini">Gemini CLI (ACP, API key)</option>
                {/* opencode acp on an OpenRouter key: any OpenRouter model, one model per agent */}
                <option value="opencode">opencode (ACP, OpenRouter key)</option>
              </select>
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Host
              <select className={input} value={hostId} onChange={set('hostId')}>
                {hosts.map(h => <option key={h.id} value={h.id}>{h.name}</option>)}
              </select>
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Workdir alias (mapped to a folder in the host config)
              <input className={input} value={form.workdirAlias} maxLength={64} onChange={set('workdirAlias')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">{opencode ? 'OpenRouter model ID (required)' : 'Model (optional)'}
              <input className={input} value={form.model} maxLength={64} placeholder={opencode ? 'qwen/qwen3-coder' : 'gpt-6.1-sol'} onChange={set('model')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Workspace ID (same repository = same ID across hosts)
              <input className={input} value={form.workspaceId} maxLength={64} onChange={set('workspaceId')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Effort
              <select className={input} value={form.effort} onChange={set('effort')}>
                {EFFORTS.map(e => <option key={e} value={e}>{e || 'CLI default'}</option>)}
              </select>
            </label>
            <label className="sm:col-span-2 flex flex-col gap-1 text-text-muted">Add to channel (optional)
              <select className={input} value={form.channelId} onChange={set('channelId')}>
                <option value="">None</option>
                {channels.map(c => <option key={c.id} value={c.id}>#{c.name}</option>)}
              </select>
            </label>
          </div>
          <label className="mt-3 flex min-h-11 md:min-h-8 items-start gap-2 text-sm text-text">
            <input type="checkbox" className="mt-1" checked={unboxedAck} onChange={e => setUnboxedAck(e.target.checked)} />
            <span>Run unboxed on this machine (it can read and change your files). <span className="text-text-muted">Only you can wake an unboxed agent. For anything that doesn&apos;t need this machine, create a box instead.</span></span>
          </label>
          <div className="mt-3">
            <Button onClick={() => void create()} disabled={!unboxedAck || !/^[a-z0-9][a-z0-9_-]*$/i.test(form.name.trim()) || !form.workdirAlias.trim() || (opencode && !form.model.trim())}>
              Create agent
            </Button>
          </div>
        </div>
      )}
    </section>
  );
}

function ProfileRow({ serverId, profile, host, plan, onChange, onError }: {
  serverId: string; profile: Profile; host: Host | undefined; plan?: PlanConnection; onChange: () => void; onError: (e: string) => void;
}) {
  const [model, setModel] = useState(profile.model ?? '');
  const [effort, setEffort] = useState(profile.effort ?? '');
  const [workspaceId, setWorkspaceId] = useState(profile.workspaceId ?? 'primary');
  const [wakeBudget, setWakeBudget] = useState(String(profile.wakeBudget));
  const validWakeBudget = Number.isInteger(Number(wakeBudget)) && Number(wakeBudget) >= 1 && Number(wakeBudget) <= 100000;
  const dirty = model !== (profile.model ?? '') || effort !== (profile.effort ?? '') || workspaceId !== (profile.workspaceId ?? 'primary') || wakeBudget !== String(profile.wakeBudget);
  // opencode's own default is an OpenCode Zen model, so an opencode agent always names one
  const opencode = profile.adapter === 'opencode';
  const validModel = !opencode || !!model.trim();

  const save = async () => {
    try {
      if (!validWakeBudget || !validModel) return;
      await api.patch(`/servers/${serverId}/agent-profiles/${profile.id}`, { model: model.trim() || null, effort: effort || null, workspaceId: workspaceId.trim().toLowerCase(), wakeBudget: Number(wakeBudget) });
      onChange();
    } catch (err) { onError(errorText(err)); }
  };
  const remove = async () => {
    if (!confirm(`Delete agent profile "${profile.name}"? Its bot stays; end its sessions first.`)) return;
    try { await api.delete(`/servers/${serverId}/agent-profiles/${profile.id}`); onChange(); } catch (err) { onError(errorText(err)); }
  };

  return (
    <li className="rounded border border-border bg-surface px-3 py-2 text-sm">
      <div className="flex items-center justify-between">
        <span className="text-text">
          <span className="font-medium">{profile.name}</span>
          <BoxModeBadge profile={profile} className="ml-2" />
          <span className="ml-2 text-xs text-text-muted">
            {profile.adapter} · {host?.name ?? 'revoked host'} · workdir {profile.workdirAlias} · {profile.wakeBudget} wakes · {profile.tokenBudget.toLocaleString()} tokens per session
          </span>
          <AuthBadge profile={profile} />
        </span>
        <button className="min-h-11 md:min-h-8 px-2 text-xs text-danger hover:underline" onClick={() => void remove()}>Delete</button>
      </div>
      <div className="mt-2 flex flex-wrap items-center gap-2">
        <label className="flex flex-col text-xs text-text-muted">Workspace ID (end sessions before changing)
          <input className={input} value={workspaceId} maxLength={64} onChange={e => setWorkspaceId(e.target.value)} />
        </label>
        <input className={input} value={model} placeholder={opencode ? 'OpenRouter model ID (required)' : 'model (CLI default)'} maxLength={64}
          aria-label={`Model for ${profile.name}`} onChange={e => setModel(e.target.value)} />
        <select className={input} value={effort} onChange={e => setEffort(e.target.value)}>
          {EFFORTS.map(e => <option key={e} value={e}>{e || 'CLI default'}</option>)}
        </select>
        <label className="flex flex-col text-xs text-text-muted">Wake budget per session
          <input className={input} type="number" min={1} max={100000} step={1} value={wakeBudget}
            onChange={e => setWakeBudget(e.target.value)} aria-label={`Wake budget for ${profile.name}`} />
        </label>
        {dirty && <Button variant="secondary" disabled={!validWakeBudget || !validModel} onClick={() => void save()}>Save</Button>}
      </div>
      {/* A box logs its CLI in from its Boxes entry instead */}
      {profile.adapter === 'codex' && host && host.kind !== 'box' && !profile.boxed && (
        <ChatGPTPlanConnect serverId={serverId} profileId={profile.id} hostName={host.name} plan={plan}
          siwcMode={profile.authMode === 'siwc'} onChange={onChange} />
      )}
      <ToolPermissions serverId={serverId} profile={profile} onChange={onChange} onError={onError} />
    </li>
  );
}

/** How the agent's CLI signs in, as its host reported it (docs/provider-terms.md). */
function AuthBadge({ profile }: { profile: Profile }) {
  const mode = profile.authMode ?? 'subscription';
  const tone = mode === 'api_key' ? 'bg-online/20 text-online' : 'bg-warn/20 text-warn';
  const detail = !profile.authReportedAt
    ? 'not reported by its host yet, so treated as a subscription'
    : mode === 'api_key' ? `key from ${profile.apiKeyEnv}`
    : mode === 'siwc' ? (profile.planOwnerId ? 'only the person who connected their plan can wake it' : 'no ChatGPT plan connected yet')
    : 'only you can wake it';
  return (
    <span className="mt-1 flex flex-wrap items-center gap-2 text-xs text-text-muted" data-testid={`auth-${profile.name}`}>
      <span className={`rounded px-1.5 py-0.5 font-semibold leading-none ${tone}`}>{authLabel(mode, profile.runApproval)}</span>
      {detail}
    </span>
  );
}

/**
 * Tool presets and always-allowed tools (#73). Saved on the server; the host reads them at
 * its next claim, so no host restart. Approving "always" on a tool card adds to the list.
 */
function ToolPermissions({ serverId, profile, onChange, onError }: {
  serverId: string; profile: Profile; onChange: () => void; onError: (e: string) => void;
}) {
  const presets = profile.toolPresets ?? [];
  const allowed = profile.allowedTools ?? [];
  const [rule, setRule] = useState('');
  const [busy, setBusy] = useState(false);
  const valid = TOOL_RULE.test(rule.trim()) && !allowed.includes(rule.trim());

  const patch = async (body: { toolPresets?: string[]; allowedTools?: string[] }) => {
    setBusy(true);
    try { await api.patch(`/servers/${serverId}/agent-profiles/${profile.id}`, body); onChange(); }
    catch (err) { onError(errorText(err)); }
    finally { setBusy(false); }
  };
  const toggle = (name: string) => void patch({ toolPresets: presets.includes(name) ? presets.filter(p => p !== name) : [...presets, name] });

  return (
    <div className="mt-3 border-t border-border pt-2">
      <div className="mb-1 text-xs font-semibold text-text-muted">Tools</div>
      <div className="flex flex-wrap gap-x-4 gap-y-1" role="group" aria-label={`Tool presets for ${profile.name}`}>
        {PRESETS.map(p => (
          <label key={p.name} className="flex min-h-11 md:min-h-8 items-center gap-2 text-sm text-text">
            <input type="checkbox" checked={presets.includes(p.name)} disabled={busy} onChange={() => toggle(p.name)} />
            {p.label} <span className="text-xs text-text-muted">{p.detail}</span>
          </label>
        ))}
        {presets.filter(n => !PRESETS.some(p => p.name === n)).map(n => (
          <label key={n} className="flex min-h-11 md:min-h-8 items-center gap-2 text-sm text-text">
            <input type="checkbox" checked disabled={busy} onChange={() => toggle(n)} /> {n} <span className="text-xs text-text-muted">from host config</span>
          </label>
        ))}
      </div>
      <p className="mt-1 text-xs text-text-muted">
        {presets.length === 0 ? 'No preset: the host config alone decides.' : 'Changes apply from the next wake; no host restart.'}
      </p>
      {allowed.length > 0 && (
        <ul className="mt-2 flex flex-wrap gap-1" aria-label={`Always allowed tools for ${profile.name}`}>
          {allowed.map(t => (
            <li key={t} className="flex items-center gap-1 rounded border border-border bg-bg px-2 font-mono text-xs text-text">
              <span className="break-all">{t}</span>
              <button className="min-h-11 min-w-11 md:min-h-7 md:min-w-7 text-danger" disabled={busy} aria-label={`Remove ${t}`}
                onClick={() => void patch({ allowedTools: allowed.filter(a => a !== t) })}>×</button>
            </li>
          ))}
        </ul>
      )}
      <div className="mt-2 flex items-center gap-2">
        <input className={`${input} flex-1 font-mono`} value={rule} placeholder="Always allow, e.g. Bash(cargo:*)" maxLength={310}
          aria-label={`Add an always-allowed tool for ${profile.name}`} onChange={e => setRule(e.target.value)} />
        <Button variant="secondary" disabled={!valid || busy} onClick={() => { const t = rule.trim(); setRule(''); void patch({ allowedTools: [...allowed, t] }); }}>Add</Button>
      </div>
    </div>
  );
}

import { useCallback, useEffect, useState } from 'react';
import { useServerStore } from '../../stores/serverStore';
import { api, serverApi, ApiError } from '../../lib/api';
import type { Channel } from '../../lib/contracts/server';
import { Button } from '../../components/ui/Button';
import { NotAffiliated } from '../../components/ui/NotAffiliated';
import { authLabel } from '../agents/agentSessions';
import { ChatGPTPlanConnect, type PlanConnection } from './ChatGPTPlanConnect';
import { useAuthStore } from '../../stores/authStore';
import { BoxesSection } from '../boxes/BoxesSection';
import { BoxModeBadge } from '../boxes/BoxModeBadge';

/**
 * Agent hosts and agents (docs/planning/agent-sessions-wbs.md, S6). The owner registers the
 * machine that runs agents (a host) and creates agents on it; members then use /start in a
 * channel. Tokens are shown once and go into the host's config file, never into a channel.
 */

/** kind 'box': the agora-host inside a box (docs/agent-boxes.md §8.1); listed under Boxes, not here. */
interface Host { id: string; name: string; createdAt: string; lastSeenAt: string | null; revokedAt: string | null; kind?: 'machine' | 'box' }
interface Profile {
  id: string; name: string; botId: string; hostId: string; adapter: 'codex' | 'claude' | 'gemini' | 'opencode';
  model: string | null; effort: string | null; workdirAlias: string; workspaceId?: string;
  wakeBudget: number; tokenBudget: number; runTimeoutSec: number;
  toolPresets?: string[]; allowedTools?: string[];
  /** Reported by the host at start (docs/provider-terms.md); subscription until then. */
  authMode?: 'subscription' | 'api_key' | 'siwc'; apiKeyEnv?: string | null; runApproval?: boolean; authReportedAt?: string | null;
  /** 'siwc' only: whose ChatGPT plan it runs on (docs/codex-chatgpt-plan.md). */
  planOwnerId?: string | null;
  /** Its host is a box (docs/agent-boxes.md §10); otherwise it runs unboxed on a machine. */
  boxed?: boolean; hostMode?: boolean;
}

let EFFORTS = ['', 'low', 'medium', 'high', 'xhigh'];

/** Built-in tool presets (agora-host/src/presets.ts); the host config can redefine them. */
const PRESETS: { name: string; label: string; detail: string }[] = [
  { name: 'readonly', label: 'Read-only', detail: 'read files and git history' },
  { name: 'dev', label: 'Dev', detail: 'edit files, git, gh, npm' },
  { name: 'research', label: 'Research', detail: 'web search and fetch' },
];
/** Same rule shape the server accepts: a Claude permission rule or a Codex word (write, network, web_search). */
const TOOL_RULE = /^[A-Za-z][A-Za-z0-9_]{0,99}(\([^(),\r\n]{1,200}\))?$/;
const input = 'min-h-11 md:min-h-9 bg-bg border border-border rounded px-3 py-1.5 text-sm text-text placeholder:text-text-muted/70 focus:outline-none focus:ring-2 focus:ring-primary';

function errorText(err: unknown): string {
  if (err instanceof ApiError) return err.status === 403 ? 'Only the server owner can do this.' : err.code;
  return 'Request failed';
}

function OnceToken({ label, token, onDone }: { label: string; token: string; onDone: () => void }) {
  return (
    <div className="mb-4 rounded border border-primary/50 bg-primary/10 p-3 text-sm">
      <p className="mb-2 text-text">{label} It is shown only now; put it in the host's config file.</p>
      <code className="block break-all rounded bg-bg p-2 font-mono text-xs text-text select-all">{token}</code>
      <div className="mt-2 flex gap-2">
        <Button variant="secondary" onClick={() => { void navigator.clipboard?.writeText(token); }}>Copy</Button>
        <Button variant="secondary" onClick={onDone}>Done</Button>
      </div>
    </div>
  );
}

export function AgentSessionsSettings() {
  const serverId = useServerStore(s => s.instanceServerId);
  const ownerId = useServerStore(s => (serverId ? s.servers.get(serverId)?.ownerId : undefined));
  const userId = useAuthStore(s => s.user?.id);
  const [hosts, setHosts] = useState<Host[]>([]);
  const [profiles, setProfiles] = useState<Profile[]>([]);
  const [channels, setChannels] = useState<Channel[]>([]);
  const [plans, setPlans] = useState<PlanConnection[]>([]);
  const [error, setError] = useState('');
  const [secret, setSecret] = useState<{ label: string; token: string } | null>(null);
  const [reloadKey, setReloadKey] = useState(0);
  const load = useCallback(() => setReloadKey(k => k + 1), []);

  useEffect(() => {
    if (!serverId) return;
    let cancelled = false;
    Promise.all([
      api.get<Host[]>(`/servers/${serverId}/agent-hosts`),
      api.get<Profile[]>(`/servers/${serverId}/agent-profiles`),
      serverApi.getChannels(serverId),
      // ChatGPT plan connections; an older server without them just shows none
      api.get<PlanConnection[]>(`/servers/${serverId}/agent-plans`).catch(() => [] as PlanConnection[]),
    ]).then(([h, p, c, pl]) => {
      if (cancelled) return;
      setHosts(h);
      setProfiles(p);
      setPlans(pl);
      setChannels(c.filter(ch => ch.channelType === 3));
      setError('');
    }).catch(err => { if (!cancelled) setError(errorText(err)); });
    return () => { cancelled = true; };
  }, [serverId, reloadKey]);

  if (!serverId) return null;
  // Box hosts are managed with their box; agents are created on machine hosts here
  const machineHosts = hosts.filter(h => h.kind !== 'box');
  const activeHosts = machineHosts.filter(h => !h.revokedAt);
  const isOwner = !!userId && !!ownerId && userId.trim() === ownerId.trim();

  return (
    <div className="max-w-3xl">
      <h2 className="text-xl font-bold text-text mb-2">Agents</h2>
      <p className="text-text-muted text-sm mb-6">
        An agent host runs on the machine with your agent CLIs and wakes agents when they are addressed. Create a host,
        put its token in the host's config, then create agents on it. In a channel, <code>/start &lt;agent&gt;</code> starts a session.
      </p>
      {error && <p className="text-danger text-sm mb-4">{error}</p>}
      {secret && <OnceToken label={secret.label} token={secret.token} onDone={() => setSecret(null)} />}

      <p className="text-text-muted text-xs mb-6">
        Each agent runs its CLI on your own login (<em>subscription</em>) or on an API key, as set in the host's config.
        Personal subscriptions are for one person, so only you can wake a subscription agent; give agents that other
        members wake an API key. A Codex agent can also run on a ChatGPT plan through Sign in with ChatGPT; only the
        person who connected their plan can wake it. See docs/provider-terms.md and docs/codex-chatgpt-plan.md.
      </p>

      <BoxesSection serverId={serverId} channels={channels} isOwner={isOwner} />
      <HostsSection serverId={serverId} hosts={machineHosts} onChange={load} onToken={setSecret} onError={setError} />
      <AgentsSection serverId={serverId} hosts={activeHosts} allHosts={hosts} profiles={profiles} channels={channels} plans={plans}
        onChange={load} onToken={setSecret} onError={setError} />
      <NotAffiliated className="mt-8" />
    </div>
  );
}

function HostsSection({ serverId, hosts, onChange, onToken, onError }: {
  serverId: string; hosts: Host[]; onChange: () => void;
  onToken: (s: { label: string; token: string }) => void; onError: (e: string) => void;
}) {
  const [name, setName] = useState('');
  const create = async () => {
    try {
      const res = await api.post<{ host: Host; token: string }>(`/servers/${serverId}/agent-hosts`, { name: name.trim() });
      setName('');
      onToken({ label: `Host token for "${res.host.name}".`, token: res.token });
      onChange();
    } catch (err) { onError(errorText(err)); }
  };
  const revoke = async (h: Host) => {
    if (!confirm(`Revoke host "${h.name}"? Its token stops working at once and its agents stop waking.`)) return;
    try { await api.delete(`/servers/${serverId}/agent-hosts/${h.id}`); onChange(); } catch (err) { onError(errorText(err)); }
  };
  return (
    <section className="mb-8">
      <h3 className="text-lg font-semibold text-text mb-3">Hosts</h3>
      <ul className="mb-3 flex flex-col gap-1">
        {hosts.length === 0 && <li className="text-text-muted text-sm">No hosts yet.</li>}
        {hosts.map(h => (
          <li key={h.id} className="flex items-center justify-between rounded border border-border bg-surface px-3 py-2 text-sm">
            <span className={h.revokedAt ? 'text-text-muted line-through' : 'text-text'}>
              {h.name}
              <span className="ml-2 text-xs text-text-muted">
                {h.revokedAt ? 'revoked' : h.lastSeenAt ? `last seen ${new Date(h.lastSeenAt).toLocaleString()}` : 'never connected'}
              </span>
            </span>
            {!h.revokedAt && <button className="min-h-11 md:min-h-8 px-2 text-xs text-danger hover:underline" onClick={() => void revoke(h)}>Revoke</button>}
          </li>
        ))}
      </ul>
      <div className="flex gap-2">
        <input className={input} placeholder="Host name, e.g. my-pc" value={name} maxLength={64} onChange={e => setName(e.target.value)} />
        <Button onClick={() => void create()} disabled={!name.trim()}>Create host</Button>
      </div>
    </section>
  );
}

function AgentsSection({ serverId, hosts, allHosts, profiles, channels, plans, onChange, onToken, onError }: {
  serverId: string; hosts: Host[]; allHosts: Host[]; profiles: Profile[]; channels: Channel[]; plans: PlanConnection[]; onChange: () => void;
  onToken: (s: { label: string; token: string }) => void; onError: (e: string) => void;
}) {
  const [form, setForm] = useState({ name: '', adapter: 'codex', hostId: '', workdirAlias: 'agora', workspaceId: 'primary', model: '', effort: 'high', channelId: '' });
  // A profile on a machine host runs unboxed; the owner confirms that (docs/agent-boxes.md §10)
  const [unboxedAck, setUnboxedAck] = useState(false);
  const set = (k: keyof typeof form) => (e: { target: { value: string } }) => setForm(f => ({ ...f, [k]: e.target.value }));
  const hostId = form.hostId || hosts[0]?.id || '';
  const opencode = form.adapter === 'opencode';

  const create = async () => {
    try {
      const res = await api.post<{ bot: { username: string }; token: string }>(`/servers/${serverId}/agents`, {
        name: form.name.trim().toLowerCase(), adapter: form.adapter, hostId, workdirAlias: form.workdirAlias.trim(),
        workspaceId: form.workspaceId.trim().toLowerCase(), hostModeAck: true,
        ...(form.model.trim() ? { model: form.model.trim() } : {}),
        ...(form.effort ? { effort: form.effort } : {}),
        ...(form.channelId ? { channelId: form.channelId } : {}),
      });
      setForm(f => ({ ...f, name: '' }));
      setUnboxedAck(false);
      onToken({ label: `Bot token for agent "${res.bot.username}".`, token: res.token });
      onChange();
    } catch (err) { onError(errorText(err)); }
  };

  return (
    <section>
      <h3 className="text-lg font-semibold text-text mb-3">Agents</h3>
      <ul className="mb-4 flex flex-col gap-2">
        {profiles.length === 0 && <li className="text-text-muted text-sm">No agents yet.</li>}
        {profiles.map(p => (
          <ProfileRow key={p.id} serverId={serverId} profile={p} host={allHosts.find(h => h.id === p.hostId && !h.revokedAt)} plan={plans.find(x => x.profileId === p.id)}
            onChange={onChange} onError={onError} />
        ))}
      </ul>

      {hosts.length === 0 ? (
        <p className="text-text-muted text-sm">Create a host first.</p>
      ) : (
        <div className="rounded border border-border bg-surface p-3">
          <h4 className="mb-2 text-sm font-semibold text-text">Create agent</h4>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 text-sm">
            <label className="flex flex-col gap-1 text-text-muted">Name (bot and /start name)
              <input className={input} value={form.name} maxLength={32} placeholder="codex" onChange={set('name')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">CLI
              <select className={input} value={form.adapter} onChange={set('adapter')}>
                <option value="codex">Codex</option>
                <option value="claude">Claude Code</option>
                {/* The host runs it over ACP (gemini --acp) and only with an API key */}
                <option value="gemini">Gemini CLI (ACP, API key)</option>
                {/* opencode acp on an OpenRouter key: any OpenRouter model, one model per agent */}
                <option value="opencode">opencode (ACP, OpenRouter key)</option>
              </select>
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Host
              <select className={input} value={hostId} onChange={set('hostId')}>
                {hosts.map(h => <option key={h.id} value={h.id}>{h.name}</option>)}
              </select>
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Workdir alias (mapped to a folder in the host config)
              <input className={input} value={form.workdirAlias} maxLength={64} onChange={set('workdirAlias')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">{opencode ? 'OpenRouter model ID (required)' : 'Model (optional)'}
              <input className={input} value={form.model} maxLength={64} placeholder={opencode ? 'qwen/qwen3-coder' : 'gpt-6.1-sol'} onChange={set('model')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Workspace ID (same repository = same ID across hosts)
              <input className={input} value={form.workspaceId} maxLength={64} onChange={set('workspaceId')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Effort
              <select className={input} value={form.effort} onChange={set('effort')}>
                {EFFORTS.map(e => <option key={e} value={e}>{e || 'CLI default'}</option>)}
              </select>
            </label>
            <label className="sm:col-span-2 flex flex-col gap-1 text-text-muted">Add to channel (optional)
              <select className={input} value={form.channelId} onChange={set('channelId')}>
                <option value="">None</option>
                {channels.map(c => <option key={c.id} value={c.id}>#{c.name}</option>)}
              </select>
            </label>
          </div>
          <label className="mt-3 flex min-h-11 md:min-h-8 items-start gap-2 text-sm text-text">
            <input type="checkbox" className="mt-1" checked={unboxedAck} onChange={e => setUnboxedAck(e.target.checked)} />
            <span>Run unboxed on this machine (it can read and change your files). <span className="text-text-muted">Only you can wake an unboxed agent. For anything that doesn&apos;t need this machine, create a box instead.</span></span>
          </label>
          <div className="mt-3">
            <Button onClick={() => void create()} disabled={!unboxedAck || !/^[a-z0-9][a-z0-9_-]*$/i.test(form.name.trim()) || !form.workdirAlias.trim() || (opencode && !form.model.trim())}>
              Create agent
            </Button>
          </div>
        </div>
      )}
    </section>
  );
}

function ProfileRow({ serverId, profile, host, plan, onChange, onError }: {
  serverId: string; profile: Profile; host: Host | undefined; plan?: PlanConnection; onChange: () => void; onError: (e: string) => void;
}) {
  const [model, setModel] = useState(profile.model ?? '');
  const [effort, setEffort] = useState(profile.effort ?? '');
  const [workspaceId, setWorkspaceId] = useState(profile.workspaceId ?? 'primary');
  const [wakeBudget, setWakeBudget] = useState(String(profile.wakeBudget));
  const validWakeBudget = Number.isInteger(Number(wakeBudget)) && Number(wakeBudget) >= 1 && Number(wakeBudget) <= 100000;
  const dirty = model !== (profile.model ?? '') || effort !== (profile.effort ?? '') || workspaceId !== (profile.workspaceId ?? 'primary') || wakeBudget !== String(profile.wakeBudget);
  // opencode's own default is an OpenCode Zen model, so an opencode agent always names one
  const opencode = profile.adapter === 'opencode';
  const validModel = !opencode || !!model.trim();

  const save = async () => {
    try {
      if (!validWakeBudget || !validModel) return;
      await api.patch(`/servers/${serverId}/agent-profiles/${profile.id}`, { model: model.trim() || null, effort: effort || null, workspaceId: workspaceId.trim().toLowerCase(), wakeBudget: Number(wakeBudget) });
      onChange();
    } catch (err) { onError(errorText(err)); }
  };
  const remove = async () => {
    if (!confirm(`Delete agent profile "${profile.name}"? Its bot stays; end its sessions first.`)) return;
    try { await api.delete(`/servers/${serverId}/agent-profiles/${profile.id}`); onChange(); } catch (err) { onError(errorText(err)); }
  };

  return (
    <li className="rounded border border-border bg-surface px-3 py-2 text-sm">
      <div className="flex items-center justify-between">
        <span className="text-text">
          <span className="font-medium">{profile.name}</span>
          <BoxModeBadge profile={profile} className="ml-2" />
          <span className="ml-2 text-xs text-text-muted">
            {profile.adapter} · {host?.name ?? 'revoked host'} · workdir {profile.workdirAlias} · {profile.wakeBudget} wakes · {profile.tokenBudget.toLocaleString()} tokens per session
          </span>
          <AuthBadge profile={profile} />
        </span>
        <button className="min-h-11 md:min-h-8 px-2 text-xs text-danger hover:underline" onClick={() => void remove()}>Delete</button>
      </div>
      <div className="mt-2 flex flex-wrap items-center gap-2">
        <label className="flex flex-col text-xs text-text-muted">Workspace ID (end sessions before changing)
          <input className={input} value={workspaceId} maxLength={64} onChange={e => setWorkspaceId(e.target.value)} />
        </label>
        <input className={input} value={model} placeholder={opencode ? 'OpenRouter model ID (required)' : 'model (CLI default)'} maxLength={64}
          aria-label={`Model for ${profile.name}`} onChange={e => setModel(e.target.value)} />
        <select className={input} value={effort} onChange={e => setEffort(e.target.value)}>
          {EFFORTS.map(e => <option key={e} value={e}>{e || 'CLI default'}</option>)}
        </select>
        <label className="flex flex-col text-xs text-text-muted">Wake budget per session
          <input className={input} type="number" min={1} max={100000} step={1} value={wakeBudget}
            onChange={e => setWakeBudget(e.target.value)} aria-label={`Wake budget for ${profile.name}`} />
        </label>
        {dirty && <Button variant="secondary" disabled={!validWakeBudget || !validModel} onClick={() => void save()}>Save</Button>}
      </div>
      {/* A box logs its CLI in from its Boxes entry instead */}
      {profile.adapter === 'codex' && host && host.kind !== 'box' && !profile.boxed && (
        <ChatGPTPlanConnect serverId={serverId} profileId={profile.id} hostName={host.name} plan={plan}
          siwcMode={profile.authMode === 'siwc'} onChange={onChange} />
      )}
      <ToolPermissions serverId={serverId} profile={profile} onChange={onChange} onError={onError} />
    </li>
  );
}

/** How the agent's CLI signs in, as its host reported it (docs/provider-terms.md). */
function AuthBadge({ profile }: { profile: Profile }) {
  const mode = profile.authMode ?? 'subscription';
  const tone = mode === 'api_key' ? 'bg-online/20 text-online' : 'bg-warn/20 text-warn';
  const detail = !profile.authReportedAt
    ? 'not reported by its host yet, so treated as a subscription'
    : mode === 'api_key' ? `key from ${profile.apiKeyEnv}`
    : mode === 'siwc' ? (profile.planOwnerId ? 'only the person who connected their plan can wake it' : 'no ChatGPT plan connected yet')
    : 'only you can wake it';
  return (
    <span className="mt-1 flex flex-wrap items-center gap-2 text-xs text-text-muted" data-testid={`auth-${profile.name}`}>
      <span className={`rounded px-1.5 py-0.5 font-semibold leading-none ${tone}`}>{authLabel(mode, profile.runApproval)}</span>
      {detail}
    </span>
  );
}

/**
 * Tool presets and always-allowed tools (#73). Saved on the server; the host reads them at
 * its next claim, so no host restart. Approving "always" on a tool card adds to the list.
 */
function ToolPermissions({ serverId, profile, onChange, onError }: {
  serverId: string; profile: Profile; onChange: () => void; onError: (e: string) => void;
}) {
  const presets = profile.toolPresets ?? [];
  const allowed = profile.allowedTools ?? [];
  const [rule, setRule] = useState('');
  const [busy, setBusy] = useState(false);
  const valid = TOOL_RULE.test(rule.trim()) && !allowed.includes(rule.trim());

  const patch = async (body: { toolPresets?: string[]; allowedTools?: string[] }) => {
    setBusy(true);
    try { await api.patch(`/servers/${serverId}/agent-profiles/${profile.id}`, body); onChange(); }
    catch (err) { onError(errorText(err)); }
    finally { setBusy(false); }
  };
  const toggle = (name: string) => void patch({ toolPresets: presets.includes(name) ? presets.filter(p => p !== name) : [...presets, name] });

  return (
    <div className="mt-3 border-t border-border pt-2">
      <div className="mb-1 text-xs font-semibold text-text-muted">Tools</div>
      <div className="flex flex-wrap gap-x-4 gap-y-1" role="group" aria-label={`Tool presets for ${profile.name}`}>
        {PRESETS.map(p => (
          <label key={p.name} className="flex min-h-11 md:min-h-8 items-center gap-2 text-sm text-text">
            <input type="checkbox" checked={presets.includes(p.name)} disabled={busy} onChange={() => toggle(p.name)} />
            {p.label} <span className="text-xs text-text-muted">{p.detail}</span>
          </label>
        ))}
        {presets.filter(n => !PRESETS.some(p => p.name === n)).map(n => (
          <label key={n} className="flex min-h-11 md:min-h-8 items-center gap-2 text-sm text-text">
            <input type="checkbox" checked disabled={busy} onChange={() => toggle(n)} /> {n} <span className="text-xs text-text-muted">from host config</span>
          </label>
        ))}
      </div>
      <p className="mt-1 text-xs text-text-muted">
        {presets.length === 0 ? 'No preset: the host config alone decides.' : 'Changes apply from the next wake; no host restart.'}
      </p>
      {allowed.length > 0 && (
        <ul className="mt-2 flex flex-wrap gap-1" aria-label={`Always allowed tools for ${profile.name}`}>
          {allowed.map(t => (
            <li key={t} className="flex items-center gap-1 rounded border border-border bg-bg px-2 font-mono text-xs text-text">
              <span className="break-all">{t}</span>
              <button className="min-h-11 min-w-11 md:min-h-7 md:min-w-7 text-danger" disabled={busy} aria-label={`Remove ${t}`}
                onClick={() => void patch({ allowedTools: allowed.filter(a => a !== t) })}>×</button>
            </li>
          ))}
        </ul>
      )}
      <div className="mt-2 flex items-center gap-2">
        <input className={`${input} flex-1 font-mono`} value={rule} placeholder="Always allow, e.g. Bash(cargo:*)" maxLength={310}
          aria-label={`Add an always-allowed tool for ${profile.name}`} onChange={e => setRule(e.target.value)} />
        <Button variant="secondary" disabled={!valid || busy} onClick={() => { const t = rule.trim(); setRule(''); void patch({ allowedTools: [...allowed, t] }); }}>Add</Button>
      </div>
    </div>
  );
}

import { useCallback, useEffect, useState } from 'react';
import { useServerStore } from '../../stores/serverStore';
import { api, serverApi, ApiError } from '../../lib/api';
import type { Channel } from '../../lib/contracts/server';
import { Button } from '../../components/ui/Button';
import { NotAffiliated } from '../../components/ui/NotAffiliated';
import { authLabel } from '../agents/agentSessions';
import { ChatGPTPlanConnect, type PlanConnection } from './ChatGPTPlanConnect';
import { useAuthStore } from '../../stores/authStore';
import { BoxesSection } from '../boxes/BoxesSection';
import { BoxModeBadge } from '../boxes/BoxModeBadge';

/**
 * Agent hosts and agents (docs/planning/agent-sessions-wbs.md, S6). The owner registers the
 * machine that runs agents (a host) and creates agents on it; members then use /start in a
 * channel. Tokens are shown once and go into the host's config file, never into a channel.
 */

/** kind 'box': the agora-host inside a box (docs/agent-boxes.md §8.1); listed under Boxes, not here. */
interface Host { id: string; name: string; createdAt: string; lastSeenAt: string | null; revokedAt: string | null; kind?: 'machine' | 'box' }
interface Profile {
  id: string; name: string; botId: string; hostId: string; adapter: 'codex' | 'claude' | 'gemini' | 'opencode';
  model: string | null; effort: string | null; workdirAlias: string; workspaceId?: string;
  wakeBudget: number; tokenBudget: number; runTimeoutSec: number;
  toolPresets?: string[]; allowedTools?: string[];
  /** Reported by the host at start (docs/provider-terms.md); subscription until then. */
  authMode?: 'subscription' | 'api_key' | 'siwc'; apiKeyEnv?: string | null; runApproval?: boolean; authReportedAt?: string | null;
  /** 'siwc' only: whose ChatGPT plan it runs on (docs/codex-chatgpt-plan.md). */
  planOwnerId?: string | null;
  /** Its host is a box (docs/agent-boxes.md §10); otherwise it runs unboxed on a machine. */
  boxed?: boolean; hostMode?: boolean;
}

const EFFORTS = ['', 'low', 'medium', 'high', 'xhigh'];

/** Built-in tool presets (agora-host/src/presets.ts); the host config can redefine them. */
let PRESETS: { name: string; label: string; detail: string }[] = [
  { name: 'readonly', label: 'Read-only', detail: 'read files and git history' },
  { name: 'dev', label: 'Dev', detail: 'edit files, git, gh, npm' },
  { name: 'research', label: 'Research', detail: 'web search and fetch' },
];
/** Same rule shape the server accepts: a Claude permission rule or a Codex word (write, network, web_search). */
const TOOL_RULE = /^[A-Za-z][A-Za-z0-9_]{0,99}(\([^(),\r\n]{1,200}\))?$/;
const input = 'min-h-11 md:min-h-9 bg-bg border border-border rounded px-3 py-1.5 text-sm text-text placeholder:text-text-muted/70 focus:outline-none focus:ring-2 focus:ring-primary';

function errorText(err: unknown): string {
  if (err instanceof ApiError) return err.status === 403 ? 'Only the server owner can do this.' : err.code;
  return 'Request failed';
}

function OnceToken({ label, token, onDone }: { label: string; token: string; onDone: () => void }) {
  return (
    <div className="mb-4 rounded border border-primary/50 bg-primary/10 p-3 text-sm">
      <p className="mb-2 text-text">{label} It is shown only now; put it in the host's config file.</p>
      <code className="block break-all rounded bg-bg p-2 font-mono text-xs text-text select-all">{token}</code>
      <div className="mt-2 flex gap-2">
        <Button variant="secondary" onClick={() => { void navigator.clipboard?.writeText(token); }}>Copy</Button>
        <Button variant="secondary" onClick={onDone}>Done</Button>
      </div>
    </div>
  );
}

export function AgentSessionsSettings() {
  const serverId = useServerStore(s => s.instanceServerId);
  const ownerId = useServerStore(s => (serverId ? s.servers.get(serverId)?.ownerId : undefined));
  const userId = useAuthStore(s => s.user?.id);
  const [hosts, setHosts] = useState<Host[]>([]);
  const [profiles, setProfiles] = useState<Profile[]>([]);
  const [channels, setChannels] = useState<Channel[]>([]);
  const [plans, setPlans] = useState<PlanConnection[]>([]);
  const [error, setError] = useState('');
  const [secret, setSecret] = useState<{ label: string; token: string } | null>(null);
  const [reloadKey, setReloadKey] = useState(0);
  const load = useCallback(() => setReloadKey(k => k + 1), []);

  useEffect(() => {
    if (!serverId) return;
    let cancelled = false;
    Promise.all([
      api.get<Host[]>(`/servers/${serverId}/agent-hosts`),
      api.get<Profile[]>(`/servers/${serverId}/agent-profiles`),
      serverApi.getChannels(serverId),
      // ChatGPT plan connections; an older server without them just shows none
      api.get<PlanConnection[]>(`/servers/${serverId}/agent-plans`).catch(() => [] as PlanConnection[]),
    ]).then(([h, p, c, pl]) => {
      if (cancelled) return;
      setHosts(h);
      setProfiles(p);
      setPlans(pl);
      setChannels(c.filter(ch => ch.channelType === 3));
      setError('');
    }).catch(err => { if (!cancelled) setError(errorText(err)); });
    return () => { cancelled = true; };
  }, [serverId, reloadKey]);

  if (!serverId) return null;
  // Box hosts are managed with their box; agents are created on machine hosts here
  const machineHosts = hosts.filter(h => h.kind !== 'box');
  const activeHosts = machineHosts.filter(h => !h.revokedAt);
  const isOwner = !!userId && !!ownerId && userId.trim() === ownerId.trim();

  return (
    <div className="max-w-3xl">
      <h2 className="text-xl font-bold text-text mb-2">Agents</h2>
      <p className="text-text-muted text-sm mb-6">
        An agent host runs on the machine with your agent CLIs and wakes agents when they are addressed. Create a host,
        put its token in the host's config, then create agents on it. In a channel, <code>/start &lt;agent&gt;</code> starts a session.
      </p>
      {error && <p className="text-danger text-sm mb-4">{error}</p>}
      {secret && <OnceToken label={secret.label} token={secret.token} onDone={() => setSecret(null)} />}

      <p className="text-text-muted text-xs mb-6">
        Each agent runs its CLI on your own login (<em>subscription</em>) or on an API key, as set in the host's config.
        Personal subscriptions are for one person, so only you can wake a subscription agent; give agents that other
        members wake an API key. A Codex agent can also run on a ChatGPT plan through Sign in with ChatGPT; only the
        person who connected their plan can wake it. See docs/provider-terms.md and docs/codex-chatgpt-plan.md.
      </p>

      <BoxesSection serverId={serverId} channels={channels} isOwner={isOwner} />
      <HostsSection serverId={serverId} hosts={machineHosts} onChange={load} onToken={setSecret} onError={setError} />
      <AgentsSection serverId={serverId} hosts={activeHosts} allHosts={hosts} profiles={profiles} channels={channels} plans={plans}
        onChange={load} onToken={setSecret} onError={setError} />
      <NotAffiliated className="mt-8" />
    </div>
  );
}

function HostsSection({ serverId, hosts, onChange, onToken, onError }: {
  serverId: string; hosts: Host[]; onChange: () => void;
  onToken: (s: { label: string; token: string }) => void; onError: (e: string) => void;
}) {
  const [name, setName] = useState('');
  const create = async () => {
    try {
      const res = await api.post<{ host: Host; token: string }>(`/servers/${serverId}/agent-hosts`, { name: name.trim() });
      setName('');
      onToken({ label: `Host token for "${res.host.name}".`, token: res.token });
      onChange();
    } catch (err) { onError(errorText(err)); }
  };
  const revoke = async (h: Host) => {
    if (!confirm(`Revoke host "${h.name}"? Its token stops working at once and its agents stop waking.`)) return;
    try { await api.delete(`/servers/${serverId}/agent-hosts/${h.id}`); onChange(); } catch (err) { onError(errorText(err)); }
  };
  return (
    <section className="mb-8">
      <h3 className="text-lg font-semibold text-text mb-3">Hosts</h3>
      <ul className="mb-3 flex flex-col gap-1">
        {hosts.length === 0 && <li className="text-text-muted text-sm">No hosts yet.</li>}
        {hosts.map(h => (
          <li key={h.id} className="flex items-center justify-between rounded border border-border bg-surface px-3 py-2 text-sm">
            <span className={h.revokedAt ? 'text-text-muted line-through' : 'text-text'}>
              {h.name}
              <span className="ml-2 text-xs text-text-muted">
                {h.revokedAt ? 'revoked' : h.lastSeenAt ? `last seen ${new Date(h.lastSeenAt).toLocaleString()}` : 'never connected'}
              </span>
            </span>
            {!h.revokedAt && <button className="min-h-11 md:min-h-8 px-2 text-xs text-danger hover:underline" onClick={() => void revoke(h)}>Revoke</button>}
          </li>
        ))}
      </ul>
      <div className="flex gap-2">
        <input className={input} placeholder="Host name, e.g. my-pc" value={name} maxLength={64} onChange={e => setName(e.target.value)} />
        <Button onClick={() => void create()} disabled={!name.trim()}>Create host</Button>
      </div>
    </section>
  );
}

function AgentsSection({ serverId, hosts, allHosts, profiles, channels, plans, onChange, onToken, onError }: {
  serverId: string; hosts: Host[]; allHosts: Host[]; profiles: Profile[]; channels: Channel[]; plans: PlanConnection[]; onChange: () => void;
  onToken: (s: { label: string; token: string }) => void; onError: (e: string) => void;
}) {
  const [form, setForm] = useState({ name: '', adapter: 'codex', hostId: '', workdirAlias: 'agora', workspaceId: 'primary', model: '', effort: 'high', channelId: '' });
  // A profile on a machine host runs unboxed; the owner confirms that (docs/agent-boxes.md §10)
  const [unboxedAck, setUnboxedAck] = useState(false);
  const set = (k: keyof typeof form) => (e: { target: { value: string } }) => setForm(f => ({ ...f, [k]: e.target.value }));
  const hostId = form.hostId || hosts[0]?.id || '';
  const opencode = form.adapter === 'opencode';

  const create = async () => {
    try {
      const res = await api.post<{ bot: { username: string }; token: string }>(`/servers/${serverId}/agents`, {
        name: form.name.trim().toLowerCase(), adapter: form.adapter, hostId, workdirAlias: form.workdirAlias.trim(),
        workspaceId: form.workspaceId.trim().toLowerCase(), hostModeAck: true,
        ...(form.model.trim() ? { model: form.model.trim() } : {}),
        ...(form.effort ? { effort: form.effort } : {}),
        ...(form.channelId ? { channelId: form.channelId } : {}),
      });
      setForm(f => ({ ...f, name: '' }));
      setUnboxedAck(false);
      onToken({ label: `Bot token for agent "${res.bot.username}".`, token: res.token });
      onChange();
    } catch (err) { onError(errorText(err)); }
  };

  return (
    <section>
      <h3 className="text-lg font-semibold text-text mb-3">Agents</h3>
      <ul className="mb-4 flex flex-col gap-2">
        {profiles.length === 0 && <li className="text-text-muted text-sm">No agents yet.</li>}
        {profiles.map(p => (
          <ProfileRow key={p.id} serverId={serverId} profile={p} host={allHosts.find(h => h.id === p.hostId && !h.revokedAt)} plan={plans.find(x => x.profileId === p.id)}
            onChange={onChange} onError={onError} />
        ))}
      </ul>

      {hosts.length === 0 ? (
        <p className="text-text-muted text-sm">Create a host first.</p>
      ) : (
        <div className="rounded border border-border bg-surface p-3">
          <h4 className="mb-2 text-sm font-semibold text-text">Create agent</h4>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 text-sm">
            <label className="flex flex-col gap-1 text-text-muted">Name (bot and /start name)
              <input className={input} value={form.name} maxLength={32} placeholder="codex" onChange={set('name')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">CLI
              <select className={input} value={form.adapter} onChange={set('adapter')}>
                <option value="codex">Codex</option>
                <option value="claude">Claude Code</option>
                {/* The host runs it over ACP (gemini --acp) and only with an API key */}
                <option value="gemini">Gemini CLI (ACP, API key)</option>
                {/* opencode acp on an OpenRouter key: any OpenRouter model, one model per agent */}
                <option value="opencode">opencode (ACP, OpenRouter key)</option>
              </select>
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Host
              <select className={input} value={hostId} onChange={set('hostId')}>
                {hosts.map(h => <option key={h.id} value={h.id}>{h.name}</option>)}
              </select>
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Workdir alias (mapped to a folder in the host config)
              <input className={input} value={form.workdirAlias} maxLength={64} onChange={set('workdirAlias')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">{opencode ? 'OpenRouter model ID (required)' : 'Model (optional)'}
              <input className={input} value={form.model} maxLength={64} placeholder={opencode ? 'qwen/qwen3-coder' : 'gpt-6.1-sol'} onChange={set('model')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Workspace ID (same repository = same ID across hosts)
              <input className={input} value={form.workspaceId} maxLength={64} onChange={set('workspaceId')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Effort
              <select className={input} value={form.effort} onChange={set('effort')}>
                {EFFORTS.map(e => <option key={e} value={e}>{e || 'CLI default'}</option>)}
              </select>
            </label>
            <label className="sm:col-span-2 flex flex-col gap-1 text-text-muted">Add to channel (optional)
              <select className={input} value={form.channelId} onChange={set('channelId')}>
                <option value="">None</option>
                {channels.map(c => <option key={c.id} value={c.id}>#{c.name}</option>)}
              </select>
            </label>
          </div>
          <label className="mt-3 flex min-h-11 md:min-h-8 items-start gap-2 text-sm text-text">
            <input type="checkbox" className="mt-1" checked={unboxedAck} onChange={e => setUnboxedAck(e.target.checked)} />
            <span>Run unboxed on this machine (it can read and change your files). <span className="text-text-muted">Only you can wake an unboxed agent. For anything that doesn&apos;t need this machine, create a box instead.</span></span>
          </label>
          <div className="mt-3">
            <Button onClick={() => void create()} disabled={!unboxedAck || !/^[a-z0-9][a-z0-9_-]*$/i.test(form.name.trim()) || !form.workdirAlias.trim() || (opencode && !form.model.trim())}>
              Create agent
            </Button>
          </div>
        </div>
      )}
    </section>
  );
}

function ProfileRow({ serverId, profile, host, plan, onChange, onError }: {
  serverId: string; profile: Profile; host: Host | undefined; plan?: PlanConnection; onChange: () => void; onError: (e: string) => void;
}) {
  const [model, setModel] = useState(profile.model ?? '');
  const [effort, setEffort] = useState(profile.effort ?? '');
  const [workspaceId, setWorkspaceId] = useState(profile.workspaceId ?? 'primary');
  const [wakeBudget, setWakeBudget] = useState(String(profile.wakeBudget));
  const validWakeBudget = Number.isInteger(Number(wakeBudget)) && Number(wakeBudget) >= 1 && Number(wakeBudget) <= 100000;
  const dirty = model !== (profile.model ?? '') || effort !== (profile.effort ?? '') || workspaceId !== (profile.workspaceId ?? 'primary') || wakeBudget !== String(profile.wakeBudget);
  // opencode's own default is an OpenCode Zen model, so an opencode agent always names one
  const opencode = profile.adapter === 'opencode';
  const validModel = !opencode || !!model.trim();

  const save = async () => {
    try {
      if (!validWakeBudget || !validModel) return;
      await api.patch(`/servers/${serverId}/agent-profiles/${profile.id}`, { model: model.trim() || null, effort: effort || null, workspaceId: workspaceId.trim().toLowerCase(), wakeBudget: Number(wakeBudget) });
      onChange();
    } catch (err) { onError(errorText(err)); }
  };
  const remove = async () => {
    if (!confirm(`Delete agent profile "${profile.name}"? Its bot stays; end its sessions first.`)) return;
    try { await api.delete(`/servers/${serverId}/agent-profiles/${profile.id}`); onChange(); } catch (err) { onError(errorText(err)); }
  };

  return (
    <li className="rounded border border-border bg-surface px-3 py-2 text-sm">
      <div className="flex items-center justify-between">
        <span className="text-text">
          <span className="font-medium">{profile.name}</span>
          <BoxModeBadge profile={profile} className="ml-2" />
          <span className="ml-2 text-xs text-text-muted">
            {profile.adapter} · {host?.name ?? 'revoked host'} · workdir {profile.workdirAlias} · {profile.wakeBudget} wakes · {profile.tokenBudget.toLocaleString()} tokens per session
          </span>
          <AuthBadge profile={profile} />
        </span>
        <button className="min-h-11 md:min-h-8 px-2 text-xs text-danger hover:underline" onClick={() => void remove()}>Delete</button>
      </div>
      <div className="mt-2 flex flex-wrap items-center gap-2">
        <label className="flex flex-col text-xs text-text-muted">Workspace ID (end sessions before changing)
          <input className={input} value={workspaceId} maxLength={64} onChange={e => setWorkspaceId(e.target.value)} />
        </label>
        <input className={input} value={model} placeholder={opencode ? 'OpenRouter model ID (required)' : 'model (CLI default)'} maxLength={64}
          aria-label={`Model for ${profile.name}`} onChange={e => setModel(e.target.value)} />
        <select className={input} value={effort} onChange={e => setEffort(e.target.value)}>
          {EFFORTS.map(e => <option key={e} value={e}>{e || 'CLI default'}</option>)}
        </select>
        <label className="flex flex-col text-xs text-text-muted">Wake budget per session
          <input className={input} type="number" min={1} max={100000} step={1} value={wakeBudget}
            onChange={e => setWakeBudget(e.target.value)} aria-label={`Wake budget for ${profile.name}`} />
        </label>
        {dirty && <Button variant="secondary" disabled={!validWakeBudget || !validModel} onClick={() => void save()}>Save</Button>}
      </div>
      {/* A box logs its CLI in from its Boxes entry instead */}
      {profile.adapter === 'codex' && host && host.kind !== 'box' && !profile.boxed && (
        <ChatGPTPlanConnect serverId={serverId} profileId={profile.id} hostName={host.name} plan={plan}
          siwcMode={profile.authMode === 'siwc'} onChange={onChange} />
      )}
      <ToolPermissions serverId={serverId} profile={profile} onChange={onChange} onError={onError} />
    </li>
  );
}

/** How the agent's CLI signs in, as its host reported it (docs/provider-terms.md). */
function AuthBadge({ profile }: { profile: Profile }) {
  const mode = profile.authMode ?? 'subscription';
  const tone = mode === 'api_key' ? 'bg-online/20 text-online' : 'bg-warn/20 text-warn';
  const detail = !profile.authReportedAt
    ? 'not reported by its host yet, so treated as a subscription'
    : mode === 'api_key' ? `key from ${profile.apiKeyEnv}`
    : mode === 'siwc' ? (profile.planOwnerId ? 'only the person who connected their plan can wake it' : 'no ChatGPT plan connected yet')
    : 'only you can wake it';
  return (
    <span className="mt-1 flex flex-wrap items-center gap-2 text-xs text-text-muted" data-testid={`auth-${profile.name}`}>
      <span className={`rounded px-1.5 py-0.5 font-semibold leading-none ${tone}`}>{authLabel(mode, profile.runApproval)}</span>
      {detail}
    </span>
  );
}

/**
 * Tool presets and always-allowed tools (#73). Saved on the server; the host reads them at
 * its next claim, so no host restart. Approving "always" on a tool card adds to the list.
 */
function ToolPermissions({ serverId, profile, onChange, onError }: {
  serverId: string; profile: Profile; onChange: () => void; onError: (e: string) => void;
}) {
  const presets = profile.toolPresets ?? [];
  const allowed = profile.allowedTools ?? [];
  const [rule, setRule] = useState('');
  const [busy, setBusy] = useState(false);
  const valid = TOOL_RULE.test(rule.trim()) && !allowed.includes(rule.trim());

  const patch = async (body: { toolPresets?: string[]; allowedTools?: string[] }) => {
    setBusy(true);
    try { await api.patch(`/servers/${serverId}/agent-profiles/${profile.id}`, body); onChange(); }
    catch (err) { onError(errorText(err)); }
    finally { setBusy(false); }
  };
  const toggle = (name: string) => void patch({ toolPresets: presets.includes(name) ? presets.filter(p => p !== name) : [...presets, name] });

  return (
    <div className="mt-3 border-t border-border pt-2">
      <div className="mb-1 text-xs font-semibold text-text-muted">Tools</div>
      <div className="flex flex-wrap gap-x-4 gap-y-1" role="group" aria-label={`Tool presets for ${profile.name}`}>
        {PRESETS.map(p => (
          <label key={p.name} className="flex min-h-11 md:min-h-8 items-center gap-2 text-sm text-text">
            <input type="checkbox" checked={presets.includes(p.name)} disabled={busy} onChange={() => toggle(p.name)} />
            {p.label} <span className="text-xs text-text-muted">{p.detail}</span>
          </label>
        ))}
        {presets.filter(n => !PRESETS.some(p => p.name === n)).map(n => (
          <label key={n} className="flex min-h-11 md:min-h-8 items-center gap-2 text-sm text-text">
            <input type="checkbox" checked disabled={busy} onChange={() => toggle(n)} /> {n} <span className="text-xs text-text-muted">from host config</span>
          </label>
        ))}
      </div>
      <p className="mt-1 text-xs text-text-muted">
        {presets.length === 0 ? 'No preset: the host config alone decides.' : 'Changes apply from the next wake; no host restart.'}
      </p>
      {allowed.length > 0 && (
        <ul className="mt-2 flex flex-wrap gap-1" aria-label={`Always allowed tools for ${profile.name}`}>
          {allowed.map(t => (
            <li key={t} className="flex items-center gap-1 rounded border border-border bg-bg px-2 font-mono text-xs text-text">
              <span className="break-all">{t}</span>
              <button className="min-h-11 min-w-11 md:min-h-7 md:min-w-7 text-danger" disabled={busy} aria-label={`Remove ${t}`}
                onClick={() => void patch({ allowedTools: allowed.filter(a => a !== t) })}>×</button>
            </li>
          ))}
        </ul>
      )}
      <div className="mt-2 flex items-center gap-2">
        <input className={`${input} flex-1 font-mono`} value={rule} placeholder="Always allow, e.g. Bash(cargo:*)" maxLength={310}
          aria-label={`Add an always-allowed tool for ${profile.name}`} onChange={e => setRule(e.target.value)} />
        <Button variant="secondary" disabled={!valid || busy} onClick={() => { const t = rule.trim(); setRule(''); void patch({ allowedTools: [...allowed, t] }); }}>Add</Button>
      </div>
    </div>
  );
}

import { useCallback, useEffect, useState } from 'react';
import { useServerStore } from '../../stores/serverStore';
import { api, serverApi, ApiError } from '../../lib/api';
import type { Channel } from '../../lib/contracts/server';
import { Button } from '../../components/ui/Button';
import { NotAffiliated } from '../../components/ui/NotAffiliated';
import { authLabel } from '../agents/agentSessions';
import { ChatGPTPlanConnect, type PlanConnection } from './ChatGPTPlanConnect';
import { useAuthStore } from '../../stores/authStore';
import { BoxesSection } from '../boxes/BoxesSection';
import { BoxModeBadge } from '../boxes/BoxModeBadge';

/**
 * Agent hosts and agents (docs/planning/agent-sessions-wbs.md, S6). The owner registers the
 * machine that runs agents (a host) and creates agents on it; members then use /start in a
 * channel. Tokens are shown once and go into the host's config file, never into a channel.
 */

/** kind 'box': the agora-host inside a box (docs/agent-boxes.md §8.1); listed under Boxes, not here. */
interface Host { id: string; name: string; createdAt: string; lastSeenAt: string | null; revokedAt: string | null; kind?: 'machine' | 'box' }
interface Profile {
  id: string; name: string; botId: string; hostId: string; adapter: 'codex' | 'claude' | 'gemini' | 'opencode';
  model: string | null; effort: string | null; workdirAlias: string; workspaceId?: string;
  wakeBudget: number; tokenBudget: number; runTimeoutSec: number;
  toolPresets?: string[]; allowedTools?: string[];
  /** Reported by the host at start (docs/provider-terms.md); subscription until then. */
  authMode?: 'subscription' | 'api_key' | 'siwc'; apiKeyEnv?: string | null; runApproval?: boolean; authReportedAt?: string | null;
  /** 'siwc' only: whose ChatGPT plan it runs on (docs/codex-chatgpt-plan.md). */
  planOwnerId?: string | null;
  /** Its host is a box (docs/agent-boxes.md §10); otherwise it runs unboxed on a machine. */
  boxed?: boolean; hostMode?: boolean;
}

const EFFORTS = ['', 'low', 'medium', 'high', 'xhigh'];

/** Built-in tool presets (agora-host/src/presets.ts); the host config can redefine them. */
const PRESETS: { name: string; label: string; detail: string }[] = [
  { name: 'readonly', label: 'Read-only', detail: 'read files and git history' },
  { name: 'dev', label: 'Dev', detail: 'edit files, git, gh, npm' },
  { name: 'research', label: 'Research', detail: 'web search and fetch' },
];
/** Same rule shape the server accepts: a Claude permission rule or a Codex word (write, network, web_search). */
let TOOL_RULE = /^[A-Za-z][A-Za-z0-9_]{0,99}(\([^(),\r\n]{1,200}\))?$/;
const input = 'min-h-11 md:min-h-9 bg-bg border border-border rounded px-3 py-1.5 text-sm text-text placeholder:text-text-muted/70 focus:outline-none focus:ring-2 focus:ring-primary';

function errorText(err: unknown): string {
  if (err instanceof ApiError) return err.status === 403 ? 'Only the server owner can do this.' : err.code;
  return 'Request failed';
}

function OnceToken({ label, token, onDone }: { label: string; token: string; onDone: () => void }) {
  return (
    <div className="mb-4 rounded border border-primary/50 bg-primary/10 p-3 text-sm">
      <p className="mb-2 text-text">{label} It is shown only now; put it in the host's config file.</p>
      <code className="block break-all rounded bg-bg p-2 font-mono text-xs text-text select-all">{token}</code>
      <div className="mt-2 flex gap-2">
        <Button variant="secondary" onClick={() => { void navigator.clipboard?.writeText(token); }}>Copy</Button>
        <Button variant="secondary" onClick={onDone}>Done</Button>
      </div>
    </div>
  );
}

export function AgentSessionsSettings() {
  const serverId = useServerStore(s => s.instanceServerId);
  const ownerId = useServerStore(s => (serverId ? s.servers.get(serverId)?.ownerId : undefined));
  const userId = useAuthStore(s => s.user?.id);
  const [hosts, setHosts] = useState<Host[]>([]);
  const [profiles, setProfiles] = useState<Profile[]>([]);
  const [channels, setChannels] = useState<Channel[]>([]);
  const [plans, setPlans] = useState<PlanConnection[]>([]);
  const [error, setError] = useState('');
  const [secret, setSecret] = useState<{ label: string; token: string } | null>(null);
  const [reloadKey, setReloadKey] = useState(0);
  const load = useCallback(() => setReloadKey(k => k + 1), []);

  useEffect(() => {
    if (!serverId) return;
    let cancelled = false;
    Promise.all([
      api.get<Host[]>(`/servers/${serverId}/agent-hosts`),
      api.get<Profile[]>(`/servers/${serverId}/agent-profiles`),
      serverApi.getChannels(serverId),
      // ChatGPT plan connections; an older server without them just shows none
      api.get<PlanConnection[]>(`/servers/${serverId}/agent-plans`).catch(() => [] as PlanConnection[]),
    ]).then(([h, p, c, pl]) => {
      if (cancelled) return;
      setHosts(h);
      setProfiles(p);
      setPlans(pl);
      setChannels(c.filter(ch => ch.channelType === 3));
      setError('');
    }).catch(err => { if (!cancelled) setError(errorText(err)); });
    return () => { cancelled = true; };
  }, [serverId, reloadKey]);

  if (!serverId) return null;
  // Box hosts are managed with their box; agents are created on machine hosts here
  const machineHosts = hosts.filter(h => h.kind !== 'box');
  const activeHosts = machineHosts.filter(h => !h.revokedAt);
  const isOwner = !!userId && !!ownerId && userId.trim() === ownerId.trim();

  return (
    <div className="max-w-3xl">
      <h2 className="text-xl font-bold text-text mb-2">Agents</h2>
      <p className="text-text-muted text-sm mb-6">
        An agent host runs on the machine with your agent CLIs and wakes agents when they are addressed. Create a host,
        put its token in the host's config, then create agents on it. In a channel, <code>/start &lt;agent&gt;</code> starts a session.
      </p>
      {error && <p className="text-danger text-sm mb-4">{error}</p>}
      {secret && <OnceToken label={secret.label} token={secret.token} onDone={() => setSecret(null)} />}

      <p className="text-text-muted text-xs mb-6">
        Each agent runs its CLI on your own login (<em>subscription</em>) or on an API key, as set in the host's config.
        Personal subscriptions are for one person, so only you can wake a subscription agent; give agents that other
        members wake an API key. A Codex agent can also run on a ChatGPT plan through Sign in with ChatGPT; only the
        person who connected their plan can wake it. See docs/provider-terms.md and docs/codex-chatgpt-plan.md.
      </p>

      <BoxesSection serverId={serverId} channels={channels} isOwner={isOwner} />
      <HostsSection serverId={serverId} hosts={machineHosts} onChange={load} onToken={setSecret} onError={setError} />
      <AgentsSection serverId={serverId} hosts={activeHosts} allHosts={hosts} profiles={profiles} channels={channels} plans={plans}
        onChange={load} onToken={setSecret} onError={setError} />
      <NotAffiliated className="mt-8" />
    </div>
  );
}

function HostsSection({ serverId, hosts, onChange, onToken, onError }: {
  serverId: string; hosts: Host[]; onChange: () => void;
  onToken: (s: { label: string; token: string }) => void; onError: (e: string) => void;
}) {
  const [name, setName] = useState('');
  const create = async () => {
    try {
      const res = await api.post<{ host: Host; token: string }>(`/servers/${serverId}/agent-hosts`, { name: name.trim() });
      setName('');
      onToken({ label: `Host token for "${res.host.name}".`, token: res.token });
      onChange();
    } catch (err) { onError(errorText(err)); }
  };
  const revoke = async (h: Host) => {
    if (!confirm(`Revoke host "${h.name}"? Its token stops working at once and its agents stop waking.`)) return;
    try { await api.delete(`/servers/${serverId}/agent-hosts/${h.id}`); onChange(); } catch (err) { onError(errorText(err)); }
  };
  return (
    <section className="mb-8">
      <h3 className="text-lg font-semibold text-text mb-3">Hosts</h3>
      <ul className="mb-3 flex flex-col gap-1">
        {hosts.length === 0 && <li className="text-text-muted text-sm">No hosts yet.</li>}
        {hosts.map(h => (
          <li key={h.id} className="flex items-center justify-between rounded border border-border bg-surface px-3 py-2 text-sm">
            <span className={h.revokedAt ? 'text-text-muted line-through' : 'text-text'}>
              {h.name}
              <span className="ml-2 text-xs text-text-muted">
                {h.revokedAt ? 'revoked' : h.lastSeenAt ? `last seen ${new Date(h.lastSeenAt).toLocaleString()}` : 'never connected'}
              </span>
            </span>
            {!h.revokedAt && <button className="min-h-11 md:min-h-8 px-2 text-xs text-danger hover:underline" onClick={() => void revoke(h)}>Revoke</button>}
          </li>
        ))}
      </ul>
      <div className="flex gap-2">
        <input className={input} placeholder="Host name, e.g. my-pc" value={name} maxLength={64} onChange={e => setName(e.target.value)} />
        <Button onClick={() => void create()} disabled={!name.trim()}>Create host</Button>
      </div>
    </section>
  );
}

function AgentsSection({ serverId, hosts, allHosts, profiles, channels, plans, onChange, onToken, onError }: {
  serverId: string; hosts: Host[]; allHosts: Host[]; profiles: Profile[]; channels: Channel[]; plans: PlanConnection[]; onChange: () => void;
  onToken: (s: { label: string; token: string }) => void; onError: (e: string) => void;
}) {
  const [form, setForm] = useState({ name: '', adapter: 'codex', hostId: '', workdirAlias: 'agora', workspaceId: 'primary', model: '', effort: 'high', channelId: '' });
  // A profile on a machine host runs unboxed; the owner confirms that (docs/agent-boxes.md §10)
  const [unboxedAck, setUnboxedAck] = useState(false);
  const set = (k: keyof typeof form) => (e: { target: { value: string } }) => setForm(f => ({ ...f, [k]: e.target.value }));
  const hostId = form.hostId || hosts[0]?.id || '';
  const opencode = form.adapter === 'opencode';

  const create = async () => {
    try {
      const res = await api.post<{ bot: { username: string }; token: string }>(`/servers/${serverId}/agents`, {
        name: form.name.trim().toLowerCase(), adapter: form.adapter, hostId, workdirAlias: form.workdirAlias.trim(),
        workspaceId: form.workspaceId.trim().toLowerCase(), hostModeAck: true,
        ...(form.model.trim() ? { model: form.model.trim() } : {}),
        ...(form.effort ? { effort: form.effort } : {}),
        ...(form.channelId ? { channelId: form.channelId } : {}),
      });
      setForm(f => ({ ...f, name: '' }));
      setUnboxedAck(false);
      onToken({ label: `Bot token for agent "${res.bot.username}".`, token: res.token });
      onChange();
    } catch (err) { onError(errorText(err)); }
  };

  return (
    <section>
      <h3 className="text-lg font-semibold text-text mb-3">Agents</h3>
      <ul className="mb-4 flex flex-col gap-2">
        {profiles.length === 0 && <li className="text-text-muted text-sm">No agents yet.</li>}
        {profiles.map(p => (
          <ProfileRow key={p.id} serverId={serverId} profile={p} host={allHosts.find(h => h.id === p.hostId && !h.revokedAt)} plan={plans.find(x => x.profileId === p.id)}
            onChange={onChange} onError={onError} />
        ))}
      </ul>

      {hosts.length === 0 ? (
        <p className="text-text-muted text-sm">Create a host first.</p>
      ) : (
        <div className="rounded border border-border bg-surface p-3">
          <h4 className="mb-2 text-sm font-semibold text-text">Create agent</h4>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 text-sm">
            <label className="flex flex-col gap-1 text-text-muted">Name (bot and /start name)
              <input className={input} value={form.name} maxLength={32} placeholder="codex" onChange={set('name')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">CLI
              <select className={input} value={form.adapter} onChange={set('adapter')}>
                <option value="codex">Codex</option>
                <option value="claude">Claude Code</option>
                {/* The host runs it over ACP (gemini --acp) and only with an API key */}
                <option value="gemini">Gemini CLI (ACP, API key)</option>
                {/* opencode acp on an OpenRouter key: any OpenRouter model, one model per agent */}
                <option value="opencode">opencode (ACP, OpenRouter key)</option>
              </select>
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Host
              <select className={input} value={hostId} onChange={set('hostId')}>
                {hosts.map(h => <option key={h.id} value={h.id}>{h.name}</option>)}
              </select>
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Workdir alias (mapped to a folder in the host config)
              <input className={input} value={form.workdirAlias} maxLength={64} onChange={set('workdirAlias')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">{opencode ? 'OpenRouter model ID (required)' : 'Model (optional)'}
              <input className={input} value={form.model} maxLength={64} placeholder={opencode ? 'qwen/qwen3-coder' : 'gpt-6.1-sol'} onChange={set('model')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Workspace ID (same repository = same ID across hosts)
              <input className={input} value={form.workspaceId} maxLength={64} onChange={set('workspaceId')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Effort
              <select className={input} value={form.effort} onChange={set('effort')}>
                {EFFORTS.map(e => <option key={e} value={e}>{e || 'CLI default'}</option>)}
              </select>
            </label>
            <label className="sm:col-span-2 flex flex-col gap-1 text-text-muted">Add to channel (optional)
              <select className={input} value={form.channelId} onChange={set('channelId')}>
                <option value="">None</option>
                {channels.map(c => <option key={c.id} value={c.id}>#{c.name}</option>)}
              </select>
            </label>
          </div>
          <label className="mt-3 flex min-h-11 md:min-h-8 items-start gap-2 text-sm text-text">
            <input type="checkbox" className="mt-1" checked={unboxedAck} onChange={e => setUnboxedAck(e.target.checked)} />
            <span>Run unboxed on this machine (it can read and change your files). <span className="text-text-muted">Only you can wake an unboxed agent. For anything that doesn&apos;t need this machine, create a box instead.</span></span>
          </label>
          <div className="mt-3">
            <Button onClick={() => void create()} disabled={!unboxedAck || !/^[a-z0-9][a-z0-9_-]*$/i.test(form.name.trim()) || !form.workdirAlias.trim() || (opencode && !form.model.trim())}>
              Create agent
            </Button>
          </div>
        </div>
      )}
    </section>
  );
}

function ProfileRow({ serverId, profile, host, plan, onChange, onError }: {
  serverId: string; profile: Profile; host: Host | undefined; plan?: PlanConnection; onChange: () => void; onError: (e: string) => void;
}) {
  const [model, setModel] = useState(profile.model ?? '');
  const [effort, setEffort] = useState(profile.effort ?? '');
  const [workspaceId, setWorkspaceId] = useState(profile.workspaceId ?? 'primary');
  const [wakeBudget, setWakeBudget] = useState(String(profile.wakeBudget));
  const validWakeBudget = Number.isInteger(Number(wakeBudget)) && Number(wakeBudget) >= 1 && Number(wakeBudget) <= 100000;
  const dirty = model !== (profile.model ?? '') || effort !== (profile.effort ?? '') || workspaceId !== (profile.workspaceId ?? 'primary') || wakeBudget !== String(profile.wakeBudget);
  // opencode's own default is an OpenCode Zen model, so an opencode agent always names one
  const opencode = profile.adapter === 'opencode';
  const validModel = !opencode || !!model.trim();

  const save = async () => {
    try {
      if (!validWakeBudget || !validModel) return;
      await api.patch(`/servers/${serverId}/agent-profiles/${profile.id}`, { model: model.trim() || null, effort: effort || null, workspaceId: workspaceId.trim().toLowerCase(), wakeBudget: Number(wakeBudget) });
      onChange();
    } catch (err) { onError(errorText(err)); }
  };
  const remove = async () => {
    if (!confirm(`Delete agent profile "${profile.name}"? Its bot stays; end its sessions first.`)) return;
    try { await api.delete(`/servers/${serverId}/agent-profiles/${profile.id}`); onChange(); } catch (err) { onError(errorText(err)); }
  };

  return (
    <li className="rounded border border-border bg-surface px-3 py-2 text-sm">
      <div className="flex items-center justify-between">
        <span className="text-text">
          <span className="font-medium">{profile.name}</span>
          <BoxModeBadge profile={profile} className="ml-2" />
          <span className="ml-2 text-xs text-text-muted">
            {profile.adapter} · {host?.name ?? 'revoked host'} · workdir {profile.workdirAlias} · {profile.wakeBudget} wakes · {profile.tokenBudget.toLocaleString()} tokens per session
          </span>
          <AuthBadge profile={profile} />
        </span>
        <button className="min-h-11 md:min-h-8 px-2 text-xs text-danger hover:underline" onClick={() => void remove()}>Delete</button>
      </div>
      <div className="mt-2 flex flex-wrap items-center gap-2">
        <label className="flex flex-col text-xs text-text-muted">Workspace ID (end sessions before changing)
          <input className={input} value={workspaceId} maxLength={64} onChange={e => setWorkspaceId(e.target.value)} />
        </label>
        <input className={input} value={model} placeholder={opencode ? 'OpenRouter model ID (required)' : 'model (CLI default)'} maxLength={64}
          aria-label={`Model for ${profile.name}`} onChange={e => setModel(e.target.value)} />
        <select className={input} value={effort} onChange={e => setEffort(e.target.value)}>
          {EFFORTS.map(e => <option key={e} value={e}>{e || 'CLI default'}</option>)}
        </select>
        <label className="flex flex-col text-xs text-text-muted">Wake budget per session
          <input className={input} type="number" min={1} max={100000} step={1} value={wakeBudget}
            onChange={e => setWakeBudget(e.target.value)} aria-label={`Wake budget for ${profile.name}`} />
        </label>
        {dirty && <Button variant="secondary" disabled={!validWakeBudget || !validModel} onClick={() => void save()}>Save</Button>}
      </div>
      {/* A box logs its CLI in from its Boxes entry instead */}
      {profile.adapter === 'codex' && host && host.kind !== 'box' && !profile.boxed && (
        <ChatGPTPlanConnect serverId={serverId} profileId={profile.id} hostName={host.name} plan={plan}
          siwcMode={profile.authMode === 'siwc'} onChange={onChange} />
      )}
      <ToolPermissions serverId={serverId} profile={profile} onChange={onChange} onError={onError} />
    </li>
  );
}

/** How the agent's CLI signs in, as its host reported it (docs/provider-terms.md). */
function AuthBadge({ profile }: { profile: Profile }) {
  const mode = profile.authMode ?? 'subscription';
  const tone = mode === 'api_key' ? 'bg-online/20 text-online' : 'bg-warn/20 text-warn';
  const detail = !profile.authReportedAt
    ? 'not reported by its host yet, so treated as a subscription'
    : mode === 'api_key' ? `key from ${profile.apiKeyEnv}`
    : mode === 'siwc' ? (profile.planOwnerId ? 'only the person who connected their plan can wake it' : 'no ChatGPT plan connected yet')
    : 'only you can wake it';
  return (
    <span className="mt-1 flex flex-wrap items-center gap-2 text-xs text-text-muted" data-testid={`auth-${profile.name}`}>
      <span className={`rounded px-1.5 py-0.5 font-semibold leading-none ${tone}`}>{authLabel(mode, profile.runApproval)}</span>
      {detail}
    </span>
  );
}

/**
 * Tool presets and always-allowed tools (#73). Saved on the server; the host reads them at
 * its next claim, so no host restart. Approving "always" on a tool card adds to the list.
 */
function ToolPermissions({ serverId, profile, onChange, onError }: {
  serverId: string; profile: Profile; onChange: () => void; onError: (e: string) => void;
}) {
  const presets = profile.toolPresets ?? [];
  const allowed = profile.allowedTools ?? [];
  const [rule, setRule] = useState('');
  const [busy, setBusy] = useState(false);
  const valid = TOOL_RULE.test(rule.trim()) && !allowed.includes(rule.trim());

  const patch = async (body: { toolPresets?: string[]; allowedTools?: string[] }) => {
    setBusy(true);
    try { await api.patch(`/servers/${serverId}/agent-profiles/${profile.id}`, body); onChange(); }
    catch (err) { onError(errorText(err)); }
    finally { setBusy(false); }
  };
  const toggle = (name: string) => void patch({ toolPresets: presets.includes(name) ? presets.filter(p => p !== name) : [...presets, name] });

  return (
    <div className="mt-3 border-t border-border pt-2">
      <div className="mb-1 text-xs font-semibold text-text-muted">Tools</div>
      <div className="flex flex-wrap gap-x-4 gap-y-1" role="group" aria-label={`Tool presets for ${profile.name}`}>
        {PRESETS.map(p => (
          <label key={p.name} className="flex min-h-11 md:min-h-8 items-center gap-2 text-sm text-text">
            <input type="checkbox" checked={presets.includes(p.name)} disabled={busy} onChange={() => toggle(p.name)} />
            {p.label} <span className="text-xs text-text-muted">{p.detail}</span>
          </label>
        ))}
        {presets.filter(n => !PRESETS.some(p => p.name === n)).map(n => (
          <label key={n} className="flex min-h-11 md:min-h-8 items-center gap-2 text-sm text-text">
            <input type="checkbox" checked disabled={busy} onChange={() => toggle(n)} /> {n} <span className="text-xs text-text-muted">from host config</span>
          </label>
        ))}
      </div>
      <p className="mt-1 text-xs text-text-muted">
        {presets.length === 0 ? 'No preset: the host config alone decides.' : 'Changes apply from the next wake; no host restart.'}
      </p>
      {allowed.length > 0 && (
        <ul className="mt-2 flex flex-wrap gap-1" aria-label={`Always allowed tools for ${profile.name}`}>
          {allowed.map(t => (
            <li key={t} className="flex items-center gap-1 rounded border border-border bg-bg px-2 font-mono text-xs text-text">
              <span className="break-all">{t}</span>
              <button className="min-h-11 min-w-11 md:min-h-7 md:min-w-7 text-danger" disabled={busy} aria-label={`Remove ${t}`}
                onClick={() => void patch({ allowedTools: allowed.filter(a => a !== t) })}>×</button>
            </li>
          ))}
        </ul>
      )}
      <div className="mt-2 flex items-center gap-2">
        <input className={`${input} flex-1 font-mono`} value={rule} placeholder="Always allow, e.g. Bash(cargo:*)" maxLength={310}
          aria-label={`Add an always-allowed tool for ${profile.name}`} onChange={e => setRule(e.target.value)} />
        <Button variant="secondary" disabled={!valid || busy} onClick={() => { const t = rule.trim(); setRule(''); void patch({ allowedTools: [...allowed, t] }); }}>Add</Button>
      </div>
    </div>
  );
}

import { useCallback, useEffect, useState } from 'react';
import { useServerStore } from '../../stores/serverStore';
import { api, serverApi, ApiError } from '../../lib/api';
import type { Channel } from '../../lib/contracts/server';
import { Button } from '../../components/ui/Button';
import { NotAffiliated } from '../../components/ui/NotAffiliated';
import { authLabel } from '../agents/agentSessions';
import { ChatGPTPlanConnect, type PlanConnection } from './ChatGPTPlanConnect';
import { useAuthStore } from '../../stores/authStore';
import { BoxesSection } from '../boxes/BoxesSection';
import { BoxModeBadge } from '../boxes/BoxModeBadge';

/**
 * Agent hosts and agents (docs/planning/agent-sessions-wbs.md, S6). The owner registers the
 * machine that runs agents (a host) and creates agents on it; members then use /start in a
 * channel. Tokens are shown once and go into the host's config file, never into a channel.
 */

/** kind 'box': the agora-host inside a box (docs/agent-boxes.md §8.1); listed under Boxes, not here. */
interface Host { id: string; name: string; createdAt: string; lastSeenAt: string | null; revokedAt: string | null; kind?: 'machine' | 'box' }
interface Profile {
  id: string; name: string; botId: string; hostId: string; adapter: 'codex' | 'claude' | 'gemini' | 'opencode';
  model: string | null; effort: string | null; workdirAlias: string; workspaceId?: string;
  wakeBudget: number; tokenBudget: number; runTimeoutSec: number;
  toolPresets?: string[]; allowedTools?: string[];
  /** Reported by the host at start (docs/provider-terms.md); subscription until then. */
  authMode?: 'subscription' | 'api_key' | 'siwc'; apiKeyEnv?: string | null; runApproval?: boolean; authReportedAt?: string | null;
  /** 'siwc' only: whose ChatGPT plan it runs on (docs/codex-chatgpt-plan.md). */
  planOwnerId?: string | null;
  /** Its host is a box (docs/agent-boxes.md §10); otherwise it runs unboxed on a machine. */
  boxed?: boolean; hostMode?: boolean;
}

const EFFORTS = ['', 'low', 'medium', 'high', 'xhigh'];

/** Built-in tool presets (agora-host/src/presets.ts); the host config can redefine them. */
const PRESETS: { name: string; label: string; detail: string }[] = [
  { name: 'readonly', label: 'Read-only', detail: 'read files and git history' },
  { name: 'dev', label: 'Dev', detail: 'edit files, git, gh, npm' },
  { name: 'research', label: 'Research', detail: 'web search and fetch' },
];
/** Same rule shape the server accepts: a Claude permission rule or a Codex word (write, network, web_search). */
const TOOL_RULE = /^[A-Za-z][A-Za-z0-9_]{0,99}(\([^(),\r\n]{1,200}\))?$/;
let input = 'min-h-11 md:min-h-9 bg-bg border border-border rounded px-3 py-1.5 text-sm text-text placeholder:text-text-muted/70 focus:outline-none focus:ring-2 focus:ring-primary';

function errorText(err: unknown): string {
  if (err instanceof ApiError) return err.status === 403 ? 'Only the server owner can do this.' : err.code;
  return 'Request failed';
}

function OnceToken({ label, token, onDone }: { label: string; token: string; onDone: () => void }) {
  return (
    <div className="mb-4 rounded border border-primary/50 bg-primary/10 p-3 text-sm">
      <p className="mb-2 text-text">{label} It is shown only now; put it in the host's config file.</p>
      <code className="block break-all rounded bg-bg p-2 font-mono text-xs text-text select-all">{token}</code>
      <div className="mt-2 flex gap-2">
        <Button variant="secondary" onClick={() => { void navigator.clipboard?.writeText(token); }}>Copy</Button>
        <Button variant="secondary" onClick={onDone}>Done</Button>
      </div>
    </div>
  );
}

export function AgentSessionsSettings() {
  const serverId = useServerStore(s => s.instanceServerId);
  const ownerId = useServerStore(s => (serverId ? s.servers.get(serverId)?.ownerId : undefined));
  const userId = useAuthStore(s => s.user?.id);
  const [hosts, setHosts] = useState<Host[]>([]);
  const [profiles, setProfiles] = useState<Profile[]>([]);
  const [channels, setChannels] = useState<Channel[]>([]);
  const [plans, setPlans] = useState<PlanConnection[]>([]);
  const [error, setError] = useState('');
  const [secret, setSecret] = useState<{ label: string; token: string } | null>(null);
  const [reloadKey, setReloadKey] = useState(0);
  const load = useCallback(() => setReloadKey(k => k + 1), []);

  useEffect(() => {
    if (!serverId) return;
    let cancelled = false;
    Promise.all([
      api.get<Host[]>(`/servers/${serverId}/agent-hosts`),
      api.get<Profile[]>(`/servers/${serverId}/agent-profiles`),
      serverApi.getChannels(serverId),
      // ChatGPT plan connections; an older server without them just shows none
      api.get<PlanConnection[]>(`/servers/${serverId}/agent-plans`).catch(() => [] as PlanConnection[]),
    ]).then(([h, p, c, pl]) => {
      if (cancelled) return;
      setHosts(h);
      setProfiles(p);
      setPlans(pl);
      setChannels(c.filter(ch => ch.channelType === 3));
      setError('');
    }).catch(err => { if (!cancelled) setError(errorText(err)); });
    return () => { cancelled = true; };
  }, [serverId, reloadKey]);

  if (!serverId) return null;
  // Box hosts are managed with their box; agents are created on machine hosts here
  const machineHosts = hosts.filter(h => h.kind !== 'box');
  const activeHosts = machineHosts.filter(h => !h.revokedAt);
  const isOwner = !!userId && !!ownerId && userId.trim() === ownerId.trim();

  return (
    <div className="max-w-3xl">
      <h2 className="text-xl font-bold text-text mb-2">Agents</h2>
      <p className="text-text-muted text-sm mb-6">
        An agent host runs on the machine with your agent CLIs and wakes agents when they are addressed. Create a host,
        put its token in the host's config, then create agents on it. In a channel, <code>/start &lt;agent&gt;</code> starts a session.
      </p>
      {error && <p className="text-danger text-sm mb-4">{error}</p>}
      {secret && <OnceToken label={secret.label} token={secret.token} onDone={() => setSecret(null)} />}

      <p className="text-text-muted text-xs mb-6">
        Each agent runs its CLI on your own login (<em>subscription</em>) or on an API key, as set in the host's config.
        Personal subscriptions are for one person, so only you can wake a subscription agent; give agents that other
        members wake an API key. A Codex agent can also run on a ChatGPT plan through Sign in with ChatGPT; only the
        person who connected their plan can wake it. See docs/provider-terms.md and docs/codex-chatgpt-plan.md.
      </p>

      <BoxesSection serverId={serverId} channels={channels} isOwner={isOwner} />
      <HostsSection serverId={serverId} hosts={machineHosts} onChange={load} onToken={setSecret} onError={setError} />
      <AgentsSection serverId={serverId} hosts={activeHosts} allHosts={hosts} profiles={profiles} channels={channels} plans={plans}
        onChange={load} onToken={setSecret} onError={setError} />
      <NotAffiliated className="mt-8" />
    </div>
  );
}

function HostsSection({ serverId, hosts, onChange, onToken, onError }: {
  serverId: string; hosts: Host[]; onChange: () => void;
  onToken: (s: { label: string; token: string }) => void; onError: (e: string) => void;
}) {
  const [name, setName] = useState('');
  const create = async () => {
    try {
      const res = await api.post<{ host: Host; token: string }>(`/servers/${serverId}/agent-hosts`, { name: name.trim() });
      setName('');
      onToken({ label: `Host token for "${res.host.name}".`, token: res.token });
      onChange();
    } catch (err) { onError(errorText(err)); }
  };
  const revoke = async (h: Host) => {
    if (!confirm(`Revoke host "${h.name}"? Its token stops working at once and its agents stop waking.`)) return;
    try { await api.delete(`/servers/${serverId}/agent-hosts/${h.id}`); onChange(); } catch (err) { onError(errorText(err)); }
  };
  return (
    <section className="mb-8">
      <h3 className="text-lg font-semibold text-text mb-3">Hosts</h3>
      <ul className="mb-3 flex flex-col gap-1">
        {hosts.length === 0 && <li className="text-text-muted text-sm">No hosts yet.</li>}
        {hosts.map(h => (
          <li key={h.id} className="flex items-center justify-between rounded border border-border bg-surface px-3 py-2 text-sm">
            <span className={h.revokedAt ? 'text-text-muted line-through' : 'text-text'}>
              {h.name}
              <span className="ml-2 text-xs text-text-muted">
                {h.revokedAt ? 'revoked' : h.lastSeenAt ? `last seen ${new Date(h.lastSeenAt).toLocaleString()}` : 'never connected'}
              </span>
            </span>
            {!h.revokedAt && <button className="min-h-11 md:min-h-8 px-2 text-xs text-danger hover:underline" onClick={() => void revoke(h)}>Revoke</button>}
          </li>
        ))}
      </ul>
      <div className="flex gap-2">
        <input className={input} placeholder="Host name, e.g. my-pc" value={name} maxLength={64} onChange={e => setName(e.target.value)} />
        <Button onClick={() => void create()} disabled={!name.trim()}>Create host</Button>
      </div>
    </section>
  );
}

function AgentsSection({ serverId, hosts, allHosts, profiles, channels, plans, onChange, onToken, onError }: {
  serverId: string; hosts: Host[]; allHosts: Host[]; profiles: Profile[]; channels: Channel[]; plans: PlanConnection[]; onChange: () => void;
  onToken: (s: { label: string; token: string }) => void; onError: (e: string) => void;
}) {
  const [form, setForm] = useState({ name: '', adapter: 'codex', hostId: '', workdirAlias: 'agora', workspaceId: 'primary', model: '', effort: 'high', channelId: '' });
  // A profile on a machine host runs unboxed; the owner confirms that (docs/agent-boxes.md §10)
  const [unboxedAck, setUnboxedAck] = useState(false);
  const set = (k: keyof typeof form) => (e: { target: { value: string } }) => setForm(f => ({ ...f, [k]: e.target.value }));
  const hostId = form.hostId || hosts[0]?.id || '';
  const opencode = form.adapter === 'opencode';

  const create = async () => {
    try {
      const res = await api.post<{ bot: { username: string }; token: string }>(`/servers/${serverId}/agents`, {
        name: form.name.trim().toLowerCase(), adapter: form.adapter, hostId, workdirAlias: form.workdirAlias.trim(),
        workspaceId: form.workspaceId.trim().toLowerCase(), hostModeAck: true,
        ...(form.model.trim() ? { model: form.model.trim() } : {}),
        ...(form.effort ? { effort: form.effort } : {}),
        ...(form.channelId ? { channelId: form.channelId } : {}),
      });
      setForm(f => ({ ...f, name: '' }));
      setUnboxedAck(false);
      onToken({ label: `Bot token for agent "${res.bot.username}".`, token: res.token });
      onChange();
    } catch (err) { onError(errorText(err)); }
  };

  return (
    <section>
      <h3 className="text-lg font-semibold text-text mb-3">Agents</h3>
      <ul className="mb-4 flex flex-col gap-2">
        {profiles.length === 0 && <li className="text-text-muted text-sm">No agents yet.</li>}
        {profiles.map(p => (
          <ProfileRow key={p.id} serverId={serverId} profile={p} host={allHosts.find(h => h.id === p.hostId && !h.revokedAt)} plan={plans.find(x => x.profileId === p.id)}
            onChange={onChange} onError={onError} />
        ))}
      </ul>

      {hosts.length === 0 ? (
        <p className="text-text-muted text-sm">Create a host first.</p>
      ) : (
        <div className="rounded border border-border bg-surface p-3">
          <h4 className="mb-2 text-sm font-semibold text-text">Create agent</h4>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 text-sm">
            <label className="flex flex-col gap-1 text-text-muted">Name (bot and /start name)
              <input className={input} value={form.name} maxLength={32} placeholder="codex" onChange={set('name')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">CLI
              <select className={input} value={form.adapter} onChange={set('adapter')}>
                <option value="codex">Codex</option>
                <option value="claude">Claude Code</option>
                {/* The host runs it over ACP (gemini --acp) and only with an API key */}
                <option value="gemini">Gemini CLI (ACP, API key)</option>
                {/* opencode acp on an OpenRouter key: any OpenRouter model, one model per agent */}
                <option value="opencode">opencode (ACP, OpenRouter key)</option>
              </select>
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Host
              <select className={input} value={hostId} onChange={set('hostId')}>
                {hosts.map(h => <option key={h.id} value={h.id}>{h.name}</option>)}
              </select>
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Workdir alias (mapped to a folder in the host config)
              <input className={input} value={form.workdirAlias} maxLength={64} onChange={set('workdirAlias')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">{opencode ? 'OpenRouter model ID (required)' : 'Model (optional)'}
              <input className={input} value={form.model} maxLength={64} placeholder={opencode ? 'qwen/qwen3-coder' : 'gpt-6.1-sol'} onChange={set('model')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Workspace ID (same repository = same ID across hosts)
              <input className={input} value={form.workspaceId} maxLength={64} onChange={set('workspaceId')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Effort
              <select className={input} value={form.effort} onChange={set('effort')}>
                {EFFORTS.map(e => <option key={e} value={e}>{e || 'CLI default'}</option>)}
              </select>
            </label>
            <label className="sm:col-span-2 flex flex-col gap-1 text-text-muted">Add to channel (optional)
              <select className={input} value={form.channelId} onChange={set('channelId')}>
                <option value="">None</option>
                {channels.map(c => <option key={c.id} value={c.id}>#{c.name}</option>)}
              </select>
            </label>
          </div>
          <label className="mt-3 flex min-h-11 md:min-h-8 items-start gap-2 text-sm text-text">
            <input type="checkbox" className="mt-1" checked={unboxedAck} onChange={e => setUnboxedAck(e.target.checked)} />
            <span>Run unboxed on this machine (it can read and change your files). <span className="text-text-muted">Only you can wake an unboxed agent. For anything that doesn&apos;t need this machine, create a box instead.</span></span>
          </label>
          <div className="mt-3">
            <Button onClick={() => void create()} disabled={!unboxedAck || !/^[a-z0-9][a-z0-9_-]*$/i.test(form.name.trim()) || !form.workdirAlias.trim() || (opencode && !form.model.trim())}>
              Create agent
            </Button>
          </div>
        </div>
      )}
    </section>
  );
}

function ProfileRow({ serverId, profile, host, plan, onChange, onError }: {
  serverId: string; profile: Profile; host: Host | undefined; plan?: PlanConnection; onChange: () => void; onError: (e: string) => void;
}) {
  const [model, setModel] = useState(profile.model ?? '');
  const [effort, setEffort] = useState(profile.effort ?? '');
  const [workspaceId, setWorkspaceId] = useState(profile.workspaceId ?? 'primary');
  const [wakeBudget, setWakeBudget] = useState(String(profile.wakeBudget));
  const validWakeBudget = Number.isInteger(Number(wakeBudget)) && Number(wakeBudget) >= 1 && Number(wakeBudget) <= 100000;
  const dirty = model !== (profile.model ?? '') || effort !== (profile.effort ?? '') || workspaceId !== (profile.workspaceId ?? 'primary') || wakeBudget !== String(profile.wakeBudget);
  // opencode's own default is an OpenCode Zen model, so an opencode agent always names one
  const opencode = profile.adapter === 'opencode';
  const validModel = !opencode || !!model.trim();

  const save = async () => {
    try {
      if (!validWakeBudget || !validModel) return;
      await api.patch(`/servers/${serverId}/agent-profiles/${profile.id}`, { model: model.trim() || null, effort: effort || null, workspaceId: workspaceId.trim().toLowerCase(), wakeBudget: Number(wakeBudget) });
      onChange();
    } catch (err) { onError(errorText(err)); }
  };
  const remove = async () => {
    if (!confirm(`Delete agent profile "${profile.name}"? Its bot stays; end its sessions first.`)) return;
    try { await api.delete(`/servers/${serverId}/agent-profiles/${profile.id}`); onChange(); } catch (err) { onError(errorText(err)); }
  };

  return (
    <li className="rounded border border-border bg-surface px-3 py-2 text-sm">
      <div className="flex items-center justify-between">
        <span className="text-text">
          <span className="font-medium">{profile.name}</span>
          <BoxModeBadge profile={profile} className="ml-2" />
          <span className="ml-2 text-xs text-text-muted">
            {profile.adapter} · {host?.name ?? 'revoked host'} · workdir {profile.workdirAlias} · {profile.wakeBudget} wakes · {profile.tokenBudget.toLocaleString()} tokens per session
          </span>
          <AuthBadge profile={profile} />
        </span>
        <button className="min-h-11 md:min-h-8 px-2 text-xs text-danger hover:underline" onClick={() => void remove()}>Delete</button>
      </div>
      <div className="mt-2 flex flex-wrap items-center gap-2">
        <label className="flex flex-col text-xs text-text-muted">Workspace ID (end sessions before changing)
          <input className={input} value={workspaceId} maxLength={64} onChange={e => setWorkspaceId(e.target.value)} />
        </label>
        <input className={input} value={model} placeholder={opencode ? 'OpenRouter model ID (required)' : 'model (CLI default)'} maxLength={64}
          aria-label={`Model for ${profile.name}`} onChange={e => setModel(e.target.value)} />
        <select className={input} value={effort} onChange={e => setEffort(e.target.value)}>
          {EFFORTS.map(e => <option key={e} value={e}>{e || 'CLI default'}</option>)}
        </select>
        <label className="flex flex-col text-xs text-text-muted">Wake budget per session
          <input className={input} type="number" min={1} max={100000} step={1} value={wakeBudget}
            onChange={e => setWakeBudget(e.target.value)} aria-label={`Wake budget for ${profile.name}`} />
        </label>
        {dirty && <Button variant="secondary" disabled={!validWakeBudget || !validModel} onClick={() => void save()}>Save</Button>}
      </div>
      {/* A box logs its CLI in from its Boxes entry instead */}
      {profile.adapter === 'codex' && host && host.kind !== 'box' && !profile.boxed && (
        <ChatGPTPlanConnect serverId={serverId} profileId={profile.id} hostName={host.name} plan={plan}
          siwcMode={profile.authMode === 'siwc'} onChange={onChange} />
      )}
      <ToolPermissions serverId={serverId} profile={profile} onChange={onChange} onError={onError} />
    </li>
  );
}

/** How the agent's CLI signs in, as its host reported it (docs/provider-terms.md). */
function AuthBadge({ profile }: { profile: Profile }) {
  const mode = profile.authMode ?? 'subscription';
  const tone = mode === 'api_key' ? 'bg-online/20 text-online' : 'bg-warn/20 text-warn';
  const detail = !profile.authReportedAt
    ? 'not reported by its host yet, so treated as a subscription'
    : mode === 'api_key' ? `key from ${profile.apiKeyEnv}`
    : mode === 'siwc' ? (profile.planOwnerId ? 'only the person who connected their plan can wake it' : 'no ChatGPT plan connected yet')
    : 'only you can wake it';
  return (
    <span className="mt-1 flex flex-wrap items-center gap-2 text-xs text-text-muted" data-testid={`auth-${profile.name}`}>
      <span className={`rounded px-1.5 py-0.5 font-semibold leading-none ${tone}`}>{authLabel(mode, profile.runApproval)}</span>
      {detail}
    </span>
  );
}

/**
 * Tool presets and always-allowed tools (#73). Saved on the server; the host reads them at
 * its next claim, so no host restart. Approving "always" on a tool card adds to the list.
 */
function ToolPermissions({ serverId, profile, onChange, onError }: {
  serverId: string; profile: Profile; onChange: () => void; onError: (e: string) => void;
}) {
  const presets = profile.toolPresets ?? [];
  const allowed = profile.allowedTools ?? [];
  const [rule, setRule] = useState('');
  const [busy, setBusy] = useState(false);
  const valid = TOOL_RULE.test(rule.trim()) && !allowed.includes(rule.trim());

  const patch = async (body: { toolPresets?: string[]; allowedTools?: string[] }) => {
    setBusy(true);
    try { await api.patch(`/servers/${serverId}/agent-profiles/${profile.id}`, body); onChange(); }
    catch (err) { onError(errorText(err)); }
    finally { setBusy(false); }
  };
  const toggle = (name: string) => void patch({ toolPresets: presets.includes(name) ? presets.filter(p => p !== name) : [...presets, name] });

  return (
    <div className="mt-3 border-t border-border pt-2">
      <div className="mb-1 text-xs font-semibold text-text-muted">Tools</div>
      <div className="flex flex-wrap gap-x-4 gap-y-1" role="group" aria-label={`Tool presets for ${profile.name}`}>
        {PRESETS.map(p => (
          <label key={p.name} className="flex min-h-11 md:min-h-8 items-center gap-2 text-sm text-text">
            <input type="checkbox" checked={presets.includes(p.name)} disabled={busy} onChange={() => toggle(p.name)} />
            {p.label} <span className="text-xs text-text-muted">{p.detail}</span>
          </label>
        ))}
        {presets.filter(n => !PRESETS.some(p => p.name === n)).map(n => (
          <label key={n} className="flex min-h-11 md:min-h-8 items-center gap-2 text-sm text-text">
            <input type="checkbox" checked disabled={busy} onChange={() => toggle(n)} /> {n} <span className="text-xs text-text-muted">from host config</span>
          </label>
        ))}
      </div>
      <p className="mt-1 text-xs text-text-muted">
        {presets.length === 0 ? 'No preset: the host config alone decides.' : 'Changes apply from the next wake; no host restart.'}
      </p>
      {allowed.length > 0 && (
        <ul className="mt-2 flex flex-wrap gap-1" aria-label={`Always allowed tools for ${profile.name}`}>
          {allowed.map(t => (
            <li key={t} className="flex items-center gap-1 rounded border border-border bg-bg px-2 font-mono text-xs text-text">
              <span className="break-all">{t}</span>
              <button className="min-h-11 min-w-11 md:min-h-7 md:min-w-7 text-danger" disabled={busy} aria-label={`Remove ${t}`}
                onClick={() => void patch({ allowedTools: allowed.filter(a => a !== t) })}>×</button>
            </li>
          ))}
        </ul>
      )}
      <div className="mt-2 flex items-center gap-2">
        <input className={`${input} flex-1 font-mono`} value={rule} placeholder="Always allow, e.g. Bash(cargo:*)" maxLength={310}
          aria-label={`Add an always-allowed tool for ${profile.name}`} onChange={e => setRule(e.target.value)} />
        <Button variant="secondary" disabled={!valid || busy} onClick={() => { const t = rule.trim(); setRule(''); void patch({ allowedTools: [...allowed, t] }); }}>Add</Button>
      </div>
    </div>
  );
}

import { useCallback, useEffect, useState } from 'react';
import { useServerStore } from '../../stores/serverStore';
import { api, serverApi, ApiError } from '../../lib/api';
import type { Channel } from '../../lib/contracts/server';
import { Button } from '../../components/ui/Button';
import { NotAffiliated } from '../../components/ui/NotAffiliated';
import { authLabel } from '../agents/agentSessions';
import { ChatGPTPlanConnect, type PlanConnection } from './ChatGPTPlanConnect';
import { useAuthStore } from '../../stores/authStore';
import { BoxesSection } from '../boxes/BoxesSection';
import { BoxModeBadge } from '../boxes/BoxModeBadge';

/**
 * Agent hosts and agents (docs/planning/agent-sessions-wbs.md, S6). The owner registers the
 * machine that runs agents (a host) and creates agents on it; members then use /start in a
 * channel. Tokens are shown once and go into the host's config file, never into a channel.
 */

/** kind 'box': the agora-host inside a box (docs/agent-boxes.md §8.1); listed under Boxes, not here. */
interface Host { id: string; name: string; createdAt: string; lastSeenAt: string | null; revokedAt: string | null; kind?: 'machine' | 'box' }
interface Profile {
  id: string; name: string; botId: string; hostId: string; adapter: 'codex' | 'claude' | 'gemini' | 'opencode';
  model: string | null; effort: string | null; workdirAlias: string; workspaceId?: string;
  wakeBudget: number; tokenBudget: number; runTimeoutSec: number;
  toolPresets?: string[]; allowedTools?: string[];
  /** Reported by the host at start (docs/provider-terms.md); subscription until then. */
  authMode?: 'subscription' | 'api_key' | 'siwc'; apiKeyEnv?: string | null; runApproval?: boolean; authReportedAt?: string | null;
  /** 'siwc' only: whose ChatGPT plan it runs on (docs/codex-chatgpt-plan.md). */
  planOwnerId?: string | null;
  /** Its host is a box (docs/agent-boxes.md §10); otherwise it runs unboxed on a machine. */
  boxed?: boolean; hostMode?: boolean;
}

const EFFORTS = ['', 'low', 'medium', 'high', 'xhigh'];

/** Built-in tool presets (agora-host/src/presets.ts); the host config can redefine them. */
const PRESETS: { name: string; label: string; detail: string }[] = [
  { name: 'readonly', label: 'Read-only', detail: 'read files and git history' },
  { name: 'dev', label: 'Dev', detail: 'edit files, git, gh, npm' },
  { name: 'research', label: 'Research', detail: 'web search and fetch' },
];
/** Same rule shape the server accepts: a Claude permission rule or a Codex word (write, network, web_search). */
const TOOL_RULE = /^[A-Za-z][A-Za-z0-9_]{0,99}(\([^(),\r\n]{1,200}\))?$/;
const input = 'min-h-11 md:min-h-9 bg-bg border border-border rounded px-3 py-1.5 text-sm text-text placeholder:text-text-muted/70 focus:outline-none focus:ring-2 focus:ring-primary';

function errorText(err: unknown): string {
  if (err instanceof ApiError) return err.status === 403 ? 'Only the server owner can do this.' : err.code;
  return 'Request failed';
}

function OnceToken({ label, token, onDone }: { label: string; token: string; onDone: () => void }) {
  return (
    <div className="mb-4 rounded border border-primary/50 bg-primary/10 p-3 text-sm">
      <p className="mb-2 text-text">{label} It is shown only now; put it in the host's config file.</p>
      <code className="block break-all rounded bg-bg p-2 font-mono text-xs text-text select-all">{token}</code>
      <div className="mt-2 flex gap-2">
        <Button variant="secondary" onClick={() => { void navigator.clipboard?.writeText(token); }}>Copy</Button>
        <Button variant="secondary" onClick={onDone}>Done</Button>
      </div>
    </div>
  );
}

export function AgentSessionsSettings() {
  let serverId = useServerStore(s => s.instanceServerId);
  const ownerId = useServerStore(s => (serverId ? s.servers.get(serverId)?.ownerId : undefined));
  const userId = useAuthStore(s => s.user?.id);
  const [hosts, setHosts] = useState<Host[]>([]);
  const [profiles, setProfiles] = useState<Profile[]>([]);
  const [channels, setChannels] = useState<Channel[]>([]);
  const [plans, setPlans] = useState<PlanConnection[]>([]);
  const [error, setError] = useState('');
  const [secret, setSecret] = useState<{ label: string; token: string } | null>(null);
  const [reloadKey, setReloadKey] = useState(0);
  const load = useCallback(() => setReloadKey(k => k + 1), []);

  useEffect(() => {
    if (!serverId) return;
    let cancelled = false;
    Promise.all([
      api.get<Host[]>(`/servers/${serverId}/agent-hosts`),
      api.get<Profile[]>(`/servers/${serverId}/agent-profiles`),
      serverApi.getChannels(serverId),
      // ChatGPT plan connections; an older server without them just shows none
      api.get<PlanConnection[]>(`/servers/${serverId}/agent-plans`).catch(() => [] as PlanConnection[]),
    ]).then(([h, p, c, pl]) => {
      if (cancelled) return;
      setHosts(h);
      setProfiles(p);
      setPlans(pl);
      setChannels(c.filter(ch => ch.channelType === 3));
      setError('');
    }).catch(err => { if (!cancelled) setError(errorText(err)); });
    return () => { cancelled = true; };
  }, [serverId, reloadKey]);

  if (!serverId) return null;
  // Box hosts are managed with their box; agents are created on machine hosts here
  const machineHosts = hosts.filter(h => h.kind !== 'box');
  const activeHosts = machineHosts.filter(h => !h.revokedAt);
  const isOwner = !!userId && !!ownerId && userId.trim() === ownerId.trim();

  return (
    <div className="max-w-3xl">
      <h2 className="text-xl font-bold text-text mb-2">Agents</h2>
      <p className="text-text-muted text-sm mb-6">
        An agent host runs on the machine with your agent CLIs and wakes agents when they are addressed. Create a host,
        put its token in the host's config, then create agents on it. In a channel, <code>/start &lt;agent&gt;</code> starts a session.
      </p>
      {error && <p className="text-danger text-sm mb-4">{error}</p>}
      {secret && <OnceToken label={secret.label} token={secret.token} onDone={() => setSecret(null)} />}

      <p className="text-text-muted text-xs mb-6">
        Each agent runs its CLI on your own login (<em>subscription</em>) or on an API key, as set in the host's config.
        Personal subscriptions are for one person, so only you can wake a subscription agent; give agents that other
        members wake an API key. A Codex agent can also run on a ChatGPT plan through Sign in with ChatGPT; only the
        person who connected their plan can wake it. See docs/provider-terms.md and docs/codex-chatgpt-plan.md.
      </p>

      <BoxesSection serverId={serverId} channels={channels} isOwner={isOwner} />
      <HostsSection serverId={serverId} hosts={machineHosts} onChange={load} onToken={setSecret} onError={setError} />
      <AgentsSection serverId={serverId} hosts={activeHosts} allHosts={hosts} profiles={profiles} channels={channels} plans={plans}
        onChange={load} onToken={setSecret} onError={setError} />
      <NotAffiliated className="mt-8" />
    </div>
  );
}

function HostsSection({ serverId, hosts, onChange, onToken, onError }: {
  serverId: string; hosts: Host[]; onChange: () => void;
  onToken: (s: { label: string; token: string }) => void; onError: (e: string) => void;
}) {
  const [name, setName] = useState('');
  const create = async () => {
    try {
      const res = await api.post<{ host: Host; token: string }>(`/servers/${serverId}/agent-hosts`, { name: name.trim() });
      setName('');
      onToken({ label: `Host token for "${res.host.name}".`, token: res.token });
      onChange();
    } catch (err) { onError(errorText(err)); }
  };
  const revoke = async (h: Host) => {
    if (!confirm(`Revoke host "${h.name}"? Its token stops working at once and its agents stop waking.`)) return;
    try { await api.delete(`/servers/${serverId}/agent-hosts/${h.id}`); onChange(); } catch (err) { onError(errorText(err)); }
  };
  return (
    <section className="mb-8">
      <h3 className="text-lg font-semibold text-text mb-3">Hosts</h3>
      <ul className="mb-3 flex flex-col gap-1">
        {hosts.length === 0 && <li className="text-text-muted text-sm">No hosts yet.</li>}
        {hosts.map(h => (
          <li key={h.id} className="flex items-center justify-between rounded border border-border bg-surface px-3 py-2 text-sm">
            <span className={h.revokedAt ? 'text-text-muted line-through' : 'text-text'}>
              {h.name}
              <span className="ml-2 text-xs text-text-muted">
                {h.revokedAt ? 'revoked' : h.lastSeenAt ? `last seen ${new Date(h.lastSeenAt).toLocaleString()}` : 'never connected'}
              </span>
            </span>
            {!h.revokedAt && <button className="min-h-11 md:min-h-8 px-2 text-xs text-danger hover:underline" onClick={() => void revoke(h)}>Revoke</button>}
          </li>
        ))}
      </ul>
      <div className="flex gap-2">
        <input className={input} placeholder="Host name, e.g. my-pc" value={name} maxLength={64} onChange={e => setName(e.target.value)} />
        <Button onClick={() => void create()} disabled={!name.trim()}>Create host</Button>
      </div>
    </section>
  );
}

function AgentsSection({ serverId, hosts, allHosts, profiles, channels, plans, onChange, onToken, onError }: {
  serverId: string; hosts: Host[]; allHosts: Host[]; profiles: Profile[]; channels: Channel[]; plans: PlanConnection[]; onChange: () => void;
  onToken: (s: { label: string; token: string }) => void; onError: (e: string) => void;
}) {
  const [form, setForm] = useState({ name: '', adapter: 'codex', hostId: '', workdirAlias: 'agora', workspaceId: 'primary', model: '', effort: 'high', channelId: '' });
  // A profile on a machine host runs unboxed; the owner confirms that (docs/agent-boxes.md §10)
  const [unboxedAck, setUnboxedAck] = useState(false);
  const set = (k: keyof typeof form) => (e: { target: { value: string } }) => setForm(f => ({ ...f, [k]: e.target.value }));
  const hostId = form.hostId || hosts[0]?.id || '';
  const opencode = form.adapter === 'opencode';

  const create = async () => {
    try {
      const res = await api.post<{ bot: { username: string }; token: string }>(`/servers/${serverId}/agents`, {
        name: form.name.trim().toLowerCase(), adapter: form.adapter, hostId, workdirAlias: form.workdirAlias.trim(),
        workspaceId: form.workspaceId.trim().toLowerCase(), hostModeAck: true,
        ...(form.model.trim() ? { model: form.model.trim() } : {}),
        ...(form.effort ? { effort: form.effort } : {}),
        ...(form.channelId ? { channelId: form.channelId } : {}),
      });
      setForm(f => ({ ...f, name: '' }));
      setUnboxedAck(false);
      onToken({ label: `Bot token for agent "${res.bot.username}".`, token: res.token });
      onChange();
    } catch (err) { onError(errorText(err)); }
  };

  return (
    <section>
      <h3 className="text-lg font-semibold text-text mb-3">Agents</h3>
      <ul className="mb-4 flex flex-col gap-2">
        {profiles.length === 0 && <li className="text-text-muted text-sm">No agents yet.</li>}
        {profiles.map(p => (
          <ProfileRow key={p.id} serverId={serverId} profile={p} host={allHosts.find(h => h.id === p.hostId && !h.revokedAt)} plan={plans.find(x => x.profileId === p.id)}
            onChange={onChange} onError={onError} />
        ))}
      </ul>

      {hosts.length === 0 ? (
        <p className="text-text-muted text-sm">Create a host first.</p>
      ) : (
        <div className="rounded border border-border bg-surface p-3">
          <h4 className="mb-2 text-sm font-semibold text-text">Create agent</h4>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 text-sm">
            <label className="flex flex-col gap-1 text-text-muted">Name (bot and /start name)
              <input className={input} value={form.name} maxLength={32} placeholder="codex" onChange={set('name')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">CLI
              <select className={input} value={form.adapter} onChange={set('adapter')}>
                <option value="codex">Codex</option>
                <option value="claude">Claude Code</option>
                {/* The host runs it over ACP (gemini --acp) and only with an API key */}
                <option value="gemini">Gemini CLI (ACP, API key)</option>
                {/* opencode acp on an OpenRouter key: any OpenRouter model, one model per agent */}
                <option value="opencode">opencode (ACP, OpenRouter key)</option>
              </select>
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Host
              <select className={input} value={hostId} onChange={set('hostId')}>
                {hosts.map(h => <option key={h.id} value={h.id}>{h.name}</option>)}
              </select>
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Workdir alias (mapped to a folder in the host config)
              <input className={input} value={form.workdirAlias} maxLength={64} onChange={set('workdirAlias')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">{opencode ? 'OpenRouter model ID (required)' : 'Model (optional)'}
              <input className={input} value={form.model} maxLength={64} placeholder={opencode ? 'qwen/qwen3-coder' : 'gpt-6.1-sol'} onChange={set('model')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Workspace ID (same repository = same ID across hosts)
              <input className={input} value={form.workspaceId} maxLength={64} onChange={set('workspaceId')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Effort
              <select className={input} value={form.effort} onChange={set('effort')}>
                {EFFORTS.map(e => <option key={e} value={e}>{e || 'CLI default'}</option>)}
              </select>
            </label>
            <label className="sm:col-span-2 flex flex-col gap-1 text-text-muted">Add to channel (optional)
              <select className={input} value={form.channelId} onChange={set('channelId')}>
                <option value="">None</option>
                {channels.map(c => <option key={c.id} value={c.id}>#{c.name}</option>)}
              </select>
            </label>
          </div>
          <label className="mt-3 flex min-h-11 md:min-h-8 items-start gap-2 text-sm text-text">
            <input type="checkbox" className="mt-1" checked={unboxedAck} onChange={e => setUnboxedAck(e.target.checked)} />
            <span>Run unboxed on this machine (it can read and change your files). <span className="text-text-muted">Only you can wake an unboxed agent. For anything that doesn&apos;t need this machine, create a box instead.</span></span>
          </label>
          <div className="mt-3">
            <Button onClick={() => void create()} disabled={!unboxedAck || !/^[a-z0-9][a-z0-9_-]*$/i.test(form.name.trim()) || !form.workdirAlias.trim() || (opencode && !form.model.trim())}>
              Create agent
            </Button>
          </div>
        </div>
      )}
    </section>
  );
}

function ProfileRow({ serverId, profile, host, plan, onChange, onError }: {
  serverId: string; profile: Profile; host: Host | undefined; plan?: PlanConnection; onChange: () => void; onError: (e: string) => void;
}) {
  const [model, setModel] = useState(profile.model ?? '');
  const [effort, setEffort] = useState(profile.effort ?? '');
  const [workspaceId, setWorkspaceId] = useState(profile.workspaceId ?? 'primary');
  const [wakeBudget, setWakeBudget] = useState(String(profile.wakeBudget));
  const validWakeBudget = Number.isInteger(Number(wakeBudget)) && Number(wakeBudget) >= 1 && Number(wakeBudget) <= 100000;
  const dirty = model !== (profile.model ?? '') || effort !== (profile.effort ?? '') || workspaceId !== (profile.workspaceId ?? 'primary') || wakeBudget !== String(profile.wakeBudget);
  // opencode's own default is an OpenCode Zen model, so an opencode agent always names one
  const opencode = profile.adapter === 'opencode';
  const validModel = !opencode || !!model.trim();

  const save = async () => {
    try {
      if (!validWakeBudget || !validModel) return;
      await api.patch(`/servers/${serverId}/agent-profiles/${profile.id}`, { model: model.trim() || null, effort: effort || null, workspaceId: workspaceId.trim().toLowerCase(), wakeBudget: Number(wakeBudget) });
      onChange();
    } catch (err) { onError(errorText(err)); }
  };
  const remove = async () => {
    if (!confirm(`Delete agent profile "${profile.name}"? Its bot stays; end its sessions first.`)) return;
    try { await api.delete(`/servers/${serverId}/agent-profiles/${profile.id}`); onChange(); } catch (err) { onError(errorText(err)); }
  };

  return (
    <li className="rounded border border-border bg-surface px-3 py-2 text-sm">
      <div className="flex items-center justify-between">
        <span className="text-text">
          <span className="font-medium">{profile.name}</span>
          <BoxModeBadge profile={profile} className="ml-2" />
          <span className="ml-2 text-xs text-text-muted">
            {profile.adapter} · {host?.name ?? 'revoked host'} · workdir {profile.workdirAlias} · {profile.wakeBudget} wakes · {profile.tokenBudget.toLocaleString()} tokens per session
          </span>
          <AuthBadge profile={profile} />
        </span>
        <button className="min-h-11 md:min-h-8 px-2 text-xs text-danger hover:underline" onClick={() => void remove()}>Delete</button>
      </div>
      <div className="mt-2 flex flex-wrap items-center gap-2">
        <label className="flex flex-col text-xs text-text-muted">Workspace ID (end sessions before changing)
          <input className={input} value={workspaceId} maxLength={64} onChange={e => setWorkspaceId(e.target.value)} />
        </label>
        <input className={input} value={model} placeholder={opencode ? 'OpenRouter model ID (required)' : 'model (CLI default)'} maxLength={64}
          aria-label={`Model for ${profile.name}`} onChange={e => setModel(e.target.value)} />
        <select className={input} value={effort} onChange={e => setEffort(e.target.value)}>
          {EFFORTS.map(e => <option key={e} value={e}>{e || 'CLI default'}</option>)}
        </select>
        <label className="flex flex-col text-xs text-text-muted">Wake budget per session
          <input className={input} type="number" min={1} max={100000} step={1} value={wakeBudget}
            onChange={e => setWakeBudget(e.target.value)} aria-label={`Wake budget for ${profile.name}`} />
        </label>
        {dirty && <Button variant="secondary" disabled={!validWakeBudget || !validModel} onClick={() => void save()}>Save</Button>}
      </div>
      {/* A box logs its CLI in from its Boxes entry instead */}
      {profile.adapter === 'codex' && host && host.kind !== 'box' && !profile.boxed && (
        <ChatGPTPlanConnect serverId={serverId} profileId={profile.id} hostName={host.name} plan={plan}
          siwcMode={profile.authMode === 'siwc'} onChange={onChange} />
      )}
      <ToolPermissions serverId={serverId} profile={profile} onChange={onChange} onError={onError} />
    </li>
  );
}

/** How the agent's CLI signs in, as its host reported it (docs/provider-terms.md). */
function AuthBadge({ profile }: { profile: Profile }) {
  const mode = profile.authMode ?? 'subscription';
  const tone = mode === 'api_key' ? 'bg-online/20 text-online' : 'bg-warn/20 text-warn';
  const detail = !profile.authReportedAt
    ? 'not reported by its host yet, so treated as a subscription'
    : mode === 'api_key' ? `key from ${profile.apiKeyEnv}`
    : mode === 'siwc' ? (profile.planOwnerId ? 'only the person who connected their plan can wake it' : 'no ChatGPT plan connected yet')
    : 'only you can wake it';
  return (
    <span className="mt-1 flex flex-wrap items-center gap-2 text-xs text-text-muted" data-testid={`auth-${profile.name}`}>
      <span className={`rounded px-1.5 py-0.5 font-semibold leading-none ${tone}`}>{authLabel(mode, profile.runApproval)}</span>
      {detail}
    </span>
  );
}

/**
 * Tool presets and always-allowed tools (#73). Saved on the server; the host reads them at
 * its next claim, so no host restart. Approving "always" on a tool card adds to the list.
 */
function ToolPermissions({ serverId, profile, onChange, onError }: {
  serverId: string; profile: Profile; onChange: () => void; onError: (e: string) => void;
}) {
  const presets = profile.toolPresets ?? [];
  const allowed = profile.allowedTools ?? [];
  const [rule, setRule] = useState('');
  const [busy, setBusy] = useState(false);
  const valid = TOOL_RULE.test(rule.trim()) && !allowed.includes(rule.trim());

  const patch = async (body: { toolPresets?: string[]; allowedTools?: string[] }) => {
    setBusy(true);
    try { await api.patch(`/servers/${serverId}/agent-profiles/${profile.id}`, body); onChange(); }
    catch (err) { onError(errorText(err)); }
    finally { setBusy(false); }
  };
  const toggle = (name: string) => void patch({ toolPresets: presets.includes(name) ? presets.filter(p => p !== name) : [...presets, name] });

  return (
    <div className="mt-3 border-t border-border pt-2">
      <div className="mb-1 text-xs font-semibold text-text-muted">Tools</div>
      <div className="flex flex-wrap gap-x-4 gap-y-1" role="group" aria-label={`Tool presets for ${profile.name}`}>
        {PRESETS.map(p => (
          <label key={p.name} className="flex min-h-11 md:min-h-8 items-center gap-2 text-sm text-text">
            <input type="checkbox" checked={presets.includes(p.name)} disabled={busy} onChange={() => toggle(p.name)} />
            {p.label} <span className="text-xs text-text-muted">{p.detail}</span>
          </label>
        ))}
        {presets.filter(n => !PRESETS.some(p => p.name === n)).map(n => (
          <label key={n} className="flex min-h-11 md:min-h-8 items-center gap-2 text-sm text-text">
            <input type="checkbox" checked disabled={busy} onChange={() => toggle(n)} /> {n} <span className="text-xs text-text-muted">from host config</span>
          </label>
        ))}
      </div>
      <p className="mt-1 text-xs text-text-muted">
        {presets.length === 0 ? 'No preset: the host config alone decides.' : 'Changes apply from the next wake; no host restart.'}
      </p>
      {allowed.length > 0 && (
        <ul className="mt-2 flex flex-wrap gap-1" aria-label={`Always allowed tools for ${profile.name}`}>
          {allowed.map(t => (
            <li key={t} className="flex items-center gap-1 rounded border border-border bg-bg px-2 font-mono text-xs text-text">
              <span className="break-all">{t}</span>
              <button className="min-h-11 min-w-11 md:min-h-7 md:min-w-7 text-danger" disabled={busy} aria-label={`Remove ${t}`}
                onClick={() => void patch({ allowedTools: allowed.filter(a => a !== t) })}>×</button>
            </li>
          ))}
        </ul>
      )}
      <div className="mt-2 flex items-center gap-2">
        <input className={`${input} flex-1 font-mono`} value={rule} placeholder="Always allow, e.g. Bash(cargo:*)" maxLength={310}
          aria-label={`Add an always-allowed tool for ${profile.name}`} onChange={e => setRule(e.target.value)} />
        <Button variant="secondary" disabled={!valid || busy} onClick={() => { const t = rule.trim(); setRule(''); void patch({ allowedTools: [...allowed, t] }); }}>Add</Button>
      </div>
    </div>
  );
}

import { useCallback, useEffect, useState } from 'react';
import { useServerStore } from '../../stores/serverStore';
import { api, serverApi, ApiError } from '../../lib/api';
import type { Channel } from '../../lib/contracts/server';
import { Button } from '../../components/ui/Button';
import { NotAffiliated } from '../../components/ui/NotAffiliated';
import { authLabel } from '../agents/agentSessions';
import { ChatGPTPlanConnect, type PlanConnection } from './ChatGPTPlanConnect';
import { useAuthStore } from '../../stores/authStore';
import { BoxesSection } from '../boxes/BoxesSection';
import { BoxModeBadge } from '../boxes/BoxModeBadge';

/**
 * Agent hosts and agents (docs/planning/agent-sessions-wbs.md, S6). The owner registers the
 * machine that runs agents (a host) and creates agents on it; members then use /start in a
 * channel. Tokens are shown once and go into the host's config file, never into a channel.
 */

/** kind 'box': the agora-host inside a box (docs/agent-boxes.md §8.1); listed under Boxes, not here. */
interface Host { id: string; name: string; createdAt: string; lastSeenAt: string | null; revokedAt: string | null; kind?: 'machine' | 'box' }
interface Profile {
  id: string; name: string; botId: string; hostId: string; adapter: 'codex' | 'claude' | 'gemini' | 'opencode';
  model: string | null; effort: string | null; workdirAlias: string; workspaceId?: string;
  wakeBudget: number; tokenBudget: number; runTimeoutSec: number;
  toolPresets?: string[]; allowedTools?: string[];
  /** Reported by the host at start (docs/provider-terms.md); subscription until then. */
  authMode?: 'subscription' | 'api_key' | 'siwc'; apiKeyEnv?: string | null; runApproval?: boolean; authReportedAt?: string | null;
  /** 'siwc' only: whose ChatGPT plan it runs on (docs/codex-chatgpt-plan.md). */
  planOwnerId?: string | null;
  /** Its host is a box (docs/agent-boxes.md §10); otherwise it runs unboxed on a machine. */
  boxed?: boolean; hostMode?: boolean;
}

const EFFORTS = ['', 'low', 'medium', 'high', 'xhigh'];

/** Built-in tool presets (agora-host/src/presets.ts); the host config can redefine them. */
const PRESETS: { name: string; label: string; detail: string }[] = [
  { name: 'readonly', label: 'Read-only', detail: 'read files and git history' },
  { name: 'dev', label: 'Dev', detail: 'edit files, git, gh, npm' },
  { name: 'research', label: 'Research', detail: 'web search and fetch' },
];
/** Same rule shape the server accepts: a Claude permission rule or a Codex word (write, network, web_search). */
const TOOL_RULE = /^[A-Za-z][A-Za-z0-9_]{0,99}(\([^(),\r\n]{1,200}\))?$/;
const input = 'min-h-11 md:min-h-9 bg-bg border border-border rounded px-3 py-1.5 text-sm text-text placeholder:text-text-muted/70 focus:outline-none focus:ring-2 focus:ring-primary';

function errorText(err: unknown): string {
  if (err instanceof ApiError) return err.status === 403 ? 'Only the server owner can do this.' : err.code;
  return 'Request failed';
}

function OnceToken({ label, token, onDone }: { label: string; token: string; onDone: () => void }) {
  return (
    <div className="mb-4 rounded border border-primary/50 bg-primary/10 p-3 text-sm">
      <p className="mb-2 text-text">{label} It is shown only now; put it in the host's config file.</p>
      <code className="block break-all rounded bg-bg p-2 font-mono text-xs text-text select-all">{token}</code>
      <div className="mt-2 flex gap-2">
        <Button variant="secondary" onClick={() => { void navigator.clipboard?.writeText(token); }}>Copy</Button>
        <Button variant="secondary" onClick={onDone}>Done</Button>
      </div>
    </div>
  );
}

export function AgentSessionsSettings() {
  const serverId = useServerStore(s => s.instanceServerId);
  let ownerId = useServerStore(s => (serverId ? s.servers.get(serverId)?.ownerId : undefined));
  const userId = useAuthStore(s => s.user?.id);
  const [hosts, setHosts] = useState<Host[]>([]);
  const [profiles, setProfiles] = useState<Profile[]>([]);
  const [channels, setChannels] = useState<Channel[]>([]);
  const [plans, setPlans] = useState<PlanConnection[]>([]);
  const [error, setError] = useState('');
  const [secret, setSecret] = useState<{ label: string; token: string } | null>(null);
  const [reloadKey, setReloadKey] = useState(0);
  const load = useCallback(() => setReloadKey(k => k + 1), []);

  useEffect(() => {
    if (!serverId) return;
    let cancelled = false;
    Promise.all([
      api.get<Host[]>(`/servers/${serverId}/agent-hosts`),
      api.get<Profile[]>(`/servers/${serverId}/agent-profiles`),
      serverApi.getChannels(serverId),
      // ChatGPT plan connections; an older server without them just shows none
      api.get<PlanConnection[]>(`/servers/${serverId}/agent-plans`).catch(() => [] as PlanConnection[]),
    ]).then(([h, p, c, pl]) => {
      if (cancelled) return;
      setHosts(h);
      setProfiles(p);
      setPlans(pl);
      setChannels(c.filter(ch => ch.channelType === 3));
      setError('');
    }).catch(err => { if (!cancelled) setError(errorText(err)); });
    return () => { cancelled = true; };
  }, [serverId, reloadKey]);

  if (!serverId) return null;
  // Box hosts are managed with their box; agents are created on machine hosts here
  const machineHosts = hosts.filter(h => h.kind !== 'box');
  const activeHosts = machineHosts.filter(h => !h.revokedAt);
  const isOwner = !!userId && !!ownerId && userId.trim() === ownerId.trim();

  return (
    <div className="max-w-3xl">
      <h2 className="text-xl font-bold text-text mb-2">Agents</h2>
      <p className="text-text-muted text-sm mb-6">
        An agent host runs on the machine with your agent CLIs and wakes agents when they are addressed. Create a host,
        put its token in the host's config, then create agents on it. In a channel, <code>/start &lt;agent&gt;</code> starts a session.
      </p>
      {error && <p className="text-danger text-sm mb-4">{error}</p>}
      {secret && <OnceToken label={secret.label} token={secret.token} onDone={() => setSecret(null)} />}

      <p className="text-text-muted text-xs mb-6">
        Each agent runs its CLI on your own login (<em>subscription</em>) or on an API key, as set in the host's config.
        Personal subscriptions are for one person, so only you can wake a subscription agent; give agents that other
        members wake an API key. A Codex agent can also run on a ChatGPT plan through Sign in with ChatGPT; only the
        person who connected their plan can wake it. See docs/provider-terms.md and docs/codex-chatgpt-plan.md.
      </p>

      <BoxesSection serverId={serverId} channels={channels} isOwner={isOwner} />
      <HostsSection serverId={serverId} hosts={machineHosts} onChange={load} onToken={setSecret} onError={setError} />
      <AgentsSection serverId={serverId} hosts={activeHosts} allHosts={hosts} profiles={profiles} channels={channels} plans={plans}
        onChange={load} onToken={setSecret} onError={setError} />
      <NotAffiliated className="mt-8" />
    </div>
  );
}

function HostsSection({ serverId, hosts, onChange, onToken, onError }: {
  serverId: string; hosts: Host[]; onChange: () => void;
  onToken: (s: { label: string; token: string }) => void; onError: (e: string) => void;
}) {
  const [name, setName] = useState('');
  const create = async () => {
    try {
      const res = await api.post<{ host: Host; token: string }>(`/servers/${serverId}/agent-hosts`, { name: name.trim() });
      setName('');
      onToken({ label: `Host token for "${res.host.name}".`, token: res.token });
      onChange();
    } catch (err) { onError(errorText(err)); }
  };
  const revoke = async (h: Host) => {
    if (!confirm(`Revoke host "${h.name}"? Its token stops working at once and its agents stop waking.`)) return;
    try { await api.delete(`/servers/${serverId}/agent-hosts/${h.id}`); onChange(); } catch (err) { onError(errorText(err)); }
  };
  return (
    <section className="mb-8">
      <h3 className="text-lg font-semibold text-text mb-3">Hosts</h3>
      <ul className="mb-3 flex flex-col gap-1">
        {hosts.length === 0 && <li className="text-text-muted text-sm">No hosts yet.</li>}
        {hosts.map(h => (
          <li key={h.id} className="flex items-center justify-between rounded border border-border bg-surface px-3 py-2 text-sm">
            <span className={h.revokedAt ? 'text-text-muted line-through' : 'text-text'}>
              {h.name}
              <span className="ml-2 text-xs text-text-muted">
                {h.revokedAt ? 'revoked' : h.lastSeenAt ? `last seen ${new Date(h.lastSeenAt).toLocaleString()}` : 'never connected'}
              </span>
            </span>
            {!h.revokedAt && <button className="min-h-11 md:min-h-8 px-2 text-xs text-danger hover:underline" onClick={() => void revoke(h)}>Revoke</button>}
          </li>
        ))}
      </ul>
      <div className="flex gap-2">
        <input className={input} placeholder="Host name, e.g. my-pc" value={name} maxLength={64} onChange={e => setName(e.target.value)} />
        <Button onClick={() => void create()} disabled={!name.trim()}>Create host</Button>
      </div>
    </section>
  );
}

function AgentsSection({ serverId, hosts, allHosts, profiles, channels, plans, onChange, onToken, onError }: {
  serverId: string; hosts: Host[]; allHosts: Host[]; profiles: Profile[]; channels: Channel[]; plans: PlanConnection[]; onChange: () => void;
  onToken: (s: { label: string; token: string }) => void; onError: (e: string) => void;
}) {
  const [form, setForm] = useState({ name: '', adapter: 'codex', hostId: '', workdirAlias: 'agora', workspaceId: 'primary', model: '', effort: 'high', channelId: '' });
  // A profile on a machine host runs unboxed; the owner confirms that (docs/agent-boxes.md §10)
  const [unboxedAck, setUnboxedAck] = useState(false);
  const set = (k: keyof typeof form) => (e: { target: { value: string } }) => setForm(f => ({ ...f, [k]: e.target.value }));
  const hostId = form.hostId || hosts[0]?.id || '';
  const opencode = form.adapter === 'opencode';

  const create = async () => {
    try {
      const res = await api.post<{ bot: { username: string }; token: string }>(`/servers/${serverId}/agents`, {
        name: form.name.trim().toLowerCase(), adapter: form.adapter, hostId, workdirAlias: form.workdirAlias.trim(),
        workspaceId: form.workspaceId.trim().toLowerCase(), hostModeAck: true,
        ...(form.model.trim() ? { model: form.model.trim() } : {}),
        ...(form.effort ? { effort: form.effort } : {}),
        ...(form.channelId ? { channelId: form.channelId } : {}),
      });
      setForm(f => ({ ...f, name: '' }));
      setUnboxedAck(false);
      onToken({ label: `Bot token for agent "${res.bot.username}".`, token: res.token });
      onChange();
    } catch (err) { onError(errorText(err)); }
  };

  return (
    <section>
      <h3 className="text-lg font-semibold text-text mb-3">Agents</h3>
      <ul className="mb-4 flex flex-col gap-2">
        {profiles.length === 0 && <li className="text-text-muted text-sm">No agents yet.</li>}
        {profiles.map(p => (
          <ProfileRow key={p.id} serverId={serverId} profile={p} host={allHosts.find(h => h.id === p.hostId && !h.revokedAt)} plan={plans.find(x => x.profileId === p.id)}
            onChange={onChange} onError={onError} />
        ))}
      </ul>

      {hosts.length === 0 ? (
        <p className="text-text-muted text-sm">Create a host first.</p>
      ) : (
        <div className="rounded border border-border bg-surface p-3">
          <h4 className="mb-2 text-sm font-semibold text-text">Create agent</h4>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 text-sm">
            <label className="flex flex-col gap-1 text-text-muted">Name (bot and /start name)
              <input className={input} value={form.name} maxLength={32} placeholder="codex" onChange={set('name')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">CLI
              <select className={input} value={form.adapter} onChange={set('adapter')}>
                <option value="codex">Codex</option>
                <option value="claude">Claude Code</option>
                {/* The host runs it over ACP (gemini --acp) and only with an API key */}
                <option value="gemini">Gemini CLI (ACP, API key)</option>
                {/* opencode acp on an OpenRouter key: any OpenRouter model, one model per agent */}
                <option value="opencode">opencode (ACP, OpenRouter key)</option>
              </select>
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Host
              <select className={input} value={hostId} onChange={set('hostId')}>
                {hosts.map(h => <option key={h.id} value={h.id}>{h.name}</option>)}
              </select>
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Workdir alias (mapped to a folder in the host config)
              <input className={input} value={form.workdirAlias} maxLength={64} onChange={set('workdirAlias')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">{opencode ? 'OpenRouter model ID (required)' : 'Model (optional)'}
              <input className={input} value={form.model} maxLength={64} placeholder={opencode ? 'qwen/qwen3-coder' : 'gpt-6.1-sol'} onChange={set('model')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Workspace ID (same repository = same ID across hosts)
              <input className={input} value={form.workspaceId} maxLength={64} onChange={set('workspaceId')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Effort
              <select className={input} value={form.effort} onChange={set('effort')}>
                {EFFORTS.map(e => <option key={e} value={e}>{e || 'CLI default'}</option>)}
              </select>
            </label>
            <label className="sm:col-span-2 flex flex-col gap-1 text-text-muted">Add to channel (optional)
              <select className={input} value={form.channelId} onChange={set('channelId')}>
                <option value="">None</option>
                {channels.map(c => <option key={c.id} value={c.id}>#{c.name}</option>)}
              </select>
            </label>
          </div>
          <label className="mt-3 flex min-h-11 md:min-h-8 items-start gap-2 text-sm text-text">
            <input type="checkbox" className="mt-1" checked={unboxedAck} onChange={e => setUnboxedAck(e.target.checked)} />
            <span>Run unboxed on this machine (it can read and change your files). <span className="text-text-muted">Only you can wake an unboxed agent. For anything that doesn&apos;t need this machine, create a box instead.</span></span>
          </label>
          <div className="mt-3">
            <Button onClick={() => void create()} disabled={!unboxedAck || !/^[a-z0-9][a-z0-9_-]*$/i.test(form.name.trim()) || !form.workdirAlias.trim() || (opencode && !form.model.trim())}>
              Create agent
            </Button>
          </div>
        </div>
      )}
    </section>
  );
}

function ProfileRow({ serverId, profile, host, plan, onChange, onError }: {
  serverId: string; profile: Profile; host: Host | undefined; plan?: PlanConnection; onChange: () => void; onError: (e: string) => void;
}) {
  const [model, setModel] = useState(profile.model ?? '');
  const [effort, setEffort] = useState(profile.effort ?? '');
  const [workspaceId, setWorkspaceId] = useState(profile.workspaceId ?? 'primary');
  const [wakeBudget, setWakeBudget] = useState(String(profile.wakeBudget));
  const validWakeBudget = Number.isInteger(Number(wakeBudget)) && Number(wakeBudget) >= 1 && Number(wakeBudget) <= 100000;
  const dirty = model !== (profile.model ?? '') || effort !== (profile.effort ?? '') || workspaceId !== (profile.workspaceId ?? 'primary') || wakeBudget !== String(profile.wakeBudget);
  // opencode's own default is an OpenCode Zen model, so an opencode agent always names one
  const opencode = profile.adapter === 'opencode';
  const validModel = !opencode || !!model.trim();

  const save = async () => {
    try {
      if (!validWakeBudget || !validModel) return;
      await api.patch(`/servers/${serverId}/agent-profiles/${profile.id}`, { model: model.trim() || null, effort: effort || null, workspaceId: workspaceId.trim().toLowerCase(), wakeBudget: Number(wakeBudget) });
      onChange();
    } catch (err) { onError(errorText(err)); }
  };
  const remove = async () => {
    if (!confirm(`Delete agent profile "${profile.name}"? Its bot stays; end its sessions first.`)) return;
    try { await api.delete(`/servers/${serverId}/agent-profiles/${profile.id}`); onChange(); } catch (err) { onError(errorText(err)); }
  };

  return (
    <li className="rounded border border-border bg-surface px-3 py-2 text-sm">
      <div className="flex items-center justify-between">
        <span className="text-text">
          <span className="font-medium">{profile.name}</span>
          <BoxModeBadge profile={profile} className="ml-2" />
          <span className="ml-2 text-xs text-text-muted">
            {profile.adapter} · {host?.name ?? 'revoked host'} · workdir {profile.workdirAlias} · {profile.wakeBudget} wakes · {profile.tokenBudget.toLocaleString()} tokens per session
          </span>
          <AuthBadge profile={profile} />
        </span>
        <button className="min-h-11 md:min-h-8 px-2 text-xs text-danger hover:underline" onClick={() => void remove()}>Delete</button>
      </div>
      <div className="mt-2 flex flex-wrap items-center gap-2">
        <label className="flex flex-col text-xs text-text-muted">Workspace ID (end sessions before changing)
          <input className={input} value={workspaceId} maxLength={64} onChange={e => setWorkspaceId(e.target.value)} />
        </label>
        <input className={input} value={model} placeholder={opencode ? 'OpenRouter model ID (required)' : 'model (CLI default)'} maxLength={64}
          aria-label={`Model for ${profile.name}`} onChange={e => setModel(e.target.value)} />
        <select className={input} value={effort} onChange={e => setEffort(e.target.value)}>
          {EFFORTS.map(e => <option key={e} value={e}>{e || 'CLI default'}</option>)}
        </select>
        <label className="flex flex-col text-xs text-text-muted">Wake budget per session
          <input className={input} type="number" min={1} max={100000} step={1} value={wakeBudget}
            onChange={e => setWakeBudget(e.target.value)} aria-label={`Wake budget for ${profile.name}`} />
        </label>
        {dirty && <Button variant="secondary" disabled={!validWakeBudget || !validModel} onClick={() => void save()}>Save</Button>}
      </div>
      {/* A box logs its CLI in from its Boxes entry instead */}
      {profile.adapter === 'codex' && host && host.kind !== 'box' && !profile.boxed && (
        <ChatGPTPlanConnect serverId={serverId} profileId={profile.id} hostName={host.name} plan={plan}
          siwcMode={profile.authMode === 'siwc'} onChange={onChange} />
      )}
      <ToolPermissions serverId={serverId} profile={profile} onChange={onChange} onError={onError} />
    </li>
  );
}

/** How the agent's CLI signs in, as its host reported it (docs/provider-terms.md). */
function AuthBadge({ profile }: { profile: Profile }) {
  const mode = profile.authMode ?? 'subscription';
  const tone = mode === 'api_key' ? 'bg-online/20 text-online' : 'bg-warn/20 text-warn';
  const detail = !profile.authReportedAt
    ? 'not reported by its host yet, so treated as a subscription'
    : mode === 'api_key' ? `key from ${profile.apiKeyEnv}`
    : mode === 'siwc' ? (profile.planOwnerId ? 'only the person who connected their plan can wake it' : 'no ChatGPT plan connected yet')
    : 'only you can wake it';
  return (
    <span className="mt-1 flex flex-wrap items-center gap-2 text-xs text-text-muted" data-testid={`auth-${profile.name}`}>
      <span className={`rounded px-1.5 py-0.5 font-semibold leading-none ${tone}`}>{authLabel(mode, profile.runApproval)}</span>
      {detail}
    </span>
  );
}

/**
 * Tool presets and always-allowed tools (#73). Saved on the server; the host reads them at
 * its next claim, so no host restart. Approving "always" on a tool card adds to the list.
 */
function ToolPermissions({ serverId, profile, onChange, onError }: {
  serverId: string; profile: Profile; onChange: () => void; onError: (e: string) => void;
}) {
  const presets = profile.toolPresets ?? [];
  const allowed = profile.allowedTools ?? [];
  const [rule, setRule] = useState('');
  const [busy, setBusy] = useState(false);
  const valid = TOOL_RULE.test(rule.trim()) && !allowed.includes(rule.trim());

  const patch = async (body: { toolPresets?: string[]; allowedTools?: string[] }) => {
    setBusy(true);
    try { await api.patch(`/servers/${serverId}/agent-profiles/${profile.id}`, body); onChange(); }
    catch (err) { onError(errorText(err)); }
    finally { setBusy(false); }
  };
  const toggle = (name: string) => void patch({ toolPresets: presets.includes(name) ? presets.filter(p => p !== name) : [...presets, name] });

  return (
    <div className="mt-3 border-t border-border pt-2">
      <div className="mb-1 text-xs font-semibold text-text-muted">Tools</div>
      <div className="flex flex-wrap gap-x-4 gap-y-1" role="group" aria-label={`Tool presets for ${profile.name}`}>
        {PRESETS.map(p => (
          <label key={p.name} className="flex min-h-11 md:min-h-8 items-center gap-2 text-sm text-text">
            <input type="checkbox" checked={presets.includes(p.name)} disabled={busy} onChange={() => toggle(p.name)} />
            {p.label} <span className="text-xs text-text-muted">{p.detail}</span>
          </label>
        ))}
        {presets.filter(n => !PRESETS.some(p => p.name === n)).map(n => (
          <label key={n} className="flex min-h-11 md:min-h-8 items-center gap-2 text-sm text-text">
            <input type="checkbox" checked disabled={busy} onChange={() => toggle(n)} /> {n} <span className="text-xs text-text-muted">from host config</span>
          </label>
        ))}
      </div>
      <p className="mt-1 text-xs text-text-muted">
        {presets.length === 0 ? 'No preset: the host config alone decides.' : 'Changes apply from the next wake; no host restart.'}
      </p>
      {allowed.length > 0 && (
        <ul className="mt-2 flex flex-wrap gap-1" aria-label={`Always allowed tools for ${profile.name}`}>
          {allowed.map(t => (
            <li key={t} className="flex items-center gap-1 rounded border border-border bg-bg px-2 font-mono text-xs text-text">
              <span className="break-all">{t}</span>
              <button className="min-h-11 min-w-11 md:min-h-7 md:min-w-7 text-danger" disabled={busy} aria-label={`Remove ${t}`}
                onClick={() => void patch({ allowedTools: allowed.filter(a => a !== t) })}>×</button>
            </li>
          ))}
        </ul>
      )}
      <div className="mt-2 flex items-center gap-2">
        <input className={`${input} flex-1 font-mono`} value={rule} placeholder="Always allow, e.g. Bash(cargo:*)" maxLength={310}
          aria-label={`Add an always-allowed tool for ${profile.name}`} onChange={e => setRule(e.target.value)} />
        <Button variant="secondary" disabled={!valid || busy} onClick={() => { const t = rule.trim(); setRule(''); void patch({ allowedTools: [...allowed, t] }); }}>Add</Button>
      </div>
    </div>
  );
}

import { useCallback, useEffect, useState } from 'react';
import { useServerStore } from '../../stores/serverStore';
import { api, serverApi, ApiError } from '../../lib/api';
import type { Channel } from '../../lib/contracts/server';
import { Button } from '../../components/ui/Button';
import { NotAffiliated } from '../../components/ui/NotAffiliated';
import { authLabel } from '../agents/agentSessions';
import { ChatGPTPlanConnect, type PlanConnection } from './ChatGPTPlanConnect';
import { useAuthStore } from '../../stores/authStore';
import { BoxesSection } from '../boxes/BoxesSection';
import { BoxModeBadge } from '../boxes/BoxModeBadge';

/**
 * Agent hosts and agents (docs/planning/agent-sessions-wbs.md, S6). The owner registers the
 * machine that runs agents (a host) and creates agents on it; members then use /start in a
 * channel. Tokens are shown once and go into the host's config file, never into a channel.
 */

/** kind 'box': the agora-host inside a box (docs/agent-boxes.md §8.1); listed under Boxes, not here. */
interface Host { id: string; name: string; createdAt: string; lastSeenAt: string | null; revokedAt: string | null; kind?: 'machine' | 'box' }
interface Profile {
  id: string; name: string; botId: string; hostId: string; adapter: 'codex' | 'claude' | 'gemini' | 'opencode';
  model: string | null; effort: string | null; workdirAlias: string; workspaceId?: string;
  wakeBudget: number; tokenBudget: number; runTimeoutSec: number;
  toolPresets?: string[]; allowedTools?: string[];
  /** Reported by the host at start (docs/provider-terms.md); subscription until then. */
  authMode?: 'subscription' | 'api_key' | 'siwc'; apiKeyEnv?: string | null; runApproval?: boolean; authReportedAt?: string | null;
  /** 'siwc' only: whose ChatGPT plan it runs on (docs/codex-chatgpt-plan.md). */
  planOwnerId?: string | null;
  /** Its host is a box (docs/agent-boxes.md §10); otherwise it runs unboxed on a machine. */
  boxed?: boolean; hostMode?: boolean;
}

const EFFORTS = ['', 'low', 'medium', 'high', 'xhigh'];

/** Built-in tool presets (agora-host/src/presets.ts); the host config can redefine them. */
const PRESETS: { name: string; label: string; detail: string }[] = [
  { name: 'readonly', label: 'Read-only', detail: 'read files and git history' },
  { name: 'dev', label: 'Dev', detail: 'edit files, git, gh, npm' },
  { name: 'research', label: 'Research', detail: 'web search and fetch' },
];
/** Same rule shape the server accepts: a Claude permission rule or a Codex word (write, network, web_search). */
const TOOL_RULE = /^[A-Za-z][A-Za-z0-9_]{0,99}(\([^(),\r\n]{1,200}\))?$/;
const input = 'min-h-11 md:min-h-9 bg-bg border border-border rounded px-3 py-1.5 text-sm text-text placeholder:text-text-muted/70 focus:outline-none focus:ring-2 focus:ring-primary';

function errorText(err: unknown): string {
  if (err instanceof ApiError) return err.status === 403 ? 'Only the server owner can do this.' : err.code;
  return 'Request failed';
}

function OnceToken({ label, token, onDone }: { label: string; token: string; onDone: () => void }) {
  return (
    <div className="mb-4 rounded border border-primary/50 bg-primary/10 p-3 text-sm">
      <p className="mb-2 text-text">{label} It is shown only now; put it in the host's config file.</p>
      <code className="block break-all rounded bg-bg p-2 font-mono text-xs text-text select-all">{token}</code>
      <div className="mt-2 flex gap-2">
        <Button variant="secondary" onClick={() => { void navigator.clipboard?.writeText(token); }}>Copy</Button>
        <Button variant="secondary" onClick={onDone}>Done</Button>
      </div>
    </div>
  );
}

export function AgentSessionsSettings() {
  const serverId = useServerStore(s => s.instanceServerId);
  const ownerId = useServerStore(s => (serverId ? s.servers.get(serverId)?.ownerId : undefined));
  const userId = useAuthStore(s => s.user?.id);
  const [hosts, setHosts] = useState<Host[]>([]);
  const [profiles, setProfiles] = useState<Profile[]>([]);
  const [channels, setChannels] = useState<Channel[]>([]);
  const [plans, setPlans] = useState<PlanConnection[]>([]);
  const [error, setError] = useState('');
  const [secret, setSecret] = useState<{ label: string; token: string } | null>(null);
  const [reloadKey, setReloadKey] = useState(0);
  const load = useCallback(() => setReloadKey(k => k + 1), []);

  useEffect(() => {
    if (!serverId) return;
    let cancelled = false;
    Promise.all([
      api.get<Host[]>(`/servers/${serverId}/agent-hosts`),
      api.get<Profile[]>(`/servers/${serverId}/agent-profiles`),
      serverApi.getChannels(serverId),
      // ChatGPT plan connections; an older server without them just shows none
      api.get<PlanConnection[]>(`/servers/${serverId}/agent-plans`).catch(() => [] as PlanConnection[]),
    ]).then(([h, p, c, pl]) => {
      if (cancelled) return;
      setHosts(h);
      setProfiles(p);
      setPlans(pl);
      setChannels(c.filter(ch => ch.channelType === 3));
      setError('');
    }).catch(err => { !cancelled && setError(errorText(err)); });
    return () => { cancelled = true; };
  }, [serverId, reloadKey]);

  if (!serverId) return null;
  // Box hosts are managed with their box; agents are created on machine hosts here
  const machineHosts = hosts.filter(h => h.kind !== 'box');
  const activeHosts = machineHosts.filter(h => !h.revokedAt);
  const isOwner = !!userId && !!ownerId && userId.trim() === ownerId.trim();

  return (
    <div className="max-w-3xl">
      <h2 className="text-xl font-bold text-text mb-2">Agents</h2>
      <p className="text-text-muted text-sm mb-6">
        An agent host runs on the machine with your agent CLIs and wakes agents when they are addressed. Create a host,
        put its token in the host's config, then create agents on it. In a channel, <code>/start &lt;agent&gt;</code> starts a session.
      </p>
      {error && <p className="text-danger text-sm mb-4">{error}</p>}
      {secret && <OnceToken label={secret.label} token={secret.token} onDone={() => setSecret(null)} />}

      <p className="text-text-muted text-xs mb-6">
        Each agent runs its CLI on your own login (<em>subscription</em>) or on an API key, as set in the host's config.
        Personal subscriptions are for one person, so only you can wake a subscription agent; give agents that other
        members wake an API key. A Codex agent can also run on a ChatGPT plan through Sign in with ChatGPT; only the
        person who connected their plan can wake it. See docs/provider-terms.md and docs/codex-chatgpt-plan.md.
      </p>

      <BoxesSection serverId={serverId} channels={channels} isOwner={isOwner} />
      <HostsSection serverId={serverId} hosts={machineHosts} onChange={load} onToken={setSecret} onError={setError} />
      <AgentsSection serverId={serverId} hosts={activeHosts} allHosts={hosts} profiles={profiles} channels={channels} plans={plans}
        onChange={load} onToken={setSecret} onError={setError} />
      <NotAffiliated className="mt-8" />
    </div>
  );
}

function HostsSection({ serverId, hosts, onChange, onToken, onError }: {
  serverId: string; hosts: Host[]; onChange: () => void;
  onToken: (s: { label: string; token: string }) => void; onError: (e: string) => void;
}) {
  const [name, setName] = useState('');
  const create = async () => {
    try {
      const res = await api.post<{ host: Host; token: string }>(`/servers/${serverId}/agent-hosts`, { name: name.trim() });
      setName('');
      onToken({ label: `Host token for "${res.host.name}".`, token: res.token });
      onChange();
    } catch (err) { onError(errorText(err)); }
  };
  const revoke = async (h: Host) => {
    if (!confirm(`Revoke host "${h.name}"? Its token stops working at once and its agents stop waking.`)) return;
    try { await api.delete(`/servers/${serverId}/agent-hosts/${h.id}`); onChange(); } catch (err) { onError(errorText(err)); }
  };
  return (
    <section className="mb-8">
      <h3 className="text-lg font-semibold text-text mb-3">Hosts</h3>
      <ul className="mb-3 flex flex-col gap-1">
        {hosts.length === 0 && <li className="text-text-muted text-sm">No hosts yet.</li>}
        {hosts.map(h => (
          <li key={h.id} className="flex items-center justify-between rounded border border-border bg-surface px-3 py-2 text-sm">
            <span className={h.revokedAt ? 'text-text-muted line-through' : 'text-text'}>
              {h.name}
              <span className="ml-2 text-xs text-text-muted">
                {h.revokedAt ? 'revoked' : h.lastSeenAt ? `last seen ${new Date(h.lastSeenAt).toLocaleString()}` : 'never connected'}
              </span>
            </span>
            {!h.revokedAt && <button className="min-h-11 md:min-h-8 px-2 text-xs text-danger hover:underline" onClick={() => void revoke(h)}>Revoke</button>}
          </li>
        ))}
      </ul>
      <div className="flex gap-2">
        <input className={input} placeholder="Host name, e.g. my-pc" value={name} maxLength={64} onChange={e => setName(e.target.value)} />
        <Button onClick={() => void create()} disabled={!name.trim()}>Create host</Button>
      </div>
    </section>
  );
}

function AgentsSection({ serverId, hosts, allHosts, profiles, channels, plans, onChange, onToken, onError }: {
  serverId: string; hosts: Host[]; allHosts: Host[]; profiles: Profile[]; channels: Channel[]; plans: PlanConnection[]; onChange: () => void;
  onToken: (s: { label: string; token: string }) => void; onError: (e: string) => void;
}) {
  const [form, setForm] = useState({ name: '', adapter: 'codex', hostId: '', workdirAlias: 'agora', workspaceId: 'primary', model: '', effort: 'high', channelId: '' });
  // A profile on a machine host runs unboxed; the owner confirms that (docs/agent-boxes.md §10)
  const [unboxedAck, setUnboxedAck] = useState(false);
  const set = (k: keyof typeof form) => (e: { target: { value: string } }) => setForm(f => ({ ...f, [k]: e.target.value }));
  const hostId = form.hostId || hosts[0]?.id || '';
  const opencode = form.adapter === 'opencode';

  const create = async () => {
    try {
      const res = await api.post<{ bot: { username: string }; token: string }>(`/servers/${serverId}/agents`, {
        name: form.name.trim().toLowerCase(), adapter: form.adapter, hostId, workdirAlias: form.workdirAlias.trim(),
        workspaceId: form.workspaceId.trim().toLowerCase(), hostModeAck: true,
        ...(form.model.trim() ? { model: form.model.trim() } : {}),
        ...(form.effort ? { effort: form.effort } : {}),
        ...(form.channelId ? { channelId: form.channelId } : {}),
      });
      setForm(f => ({ ...f, name: '' }));
      setUnboxedAck(false);
      onToken({ label: `Bot token for agent "${res.bot.username}".`, token: res.token });
      onChange();
    } catch (err) { onError(errorText(err)); }
  };

  return (
    <section>
      <h3 className="text-lg font-semibold text-text mb-3">Agents</h3>
      <ul className="mb-4 flex flex-col gap-2">
        {profiles.length === 0 && <li className="text-text-muted text-sm">No agents yet.</li>}
        {profiles.map(p => (
          <ProfileRow key={p.id} serverId={serverId} profile={p} host={allHosts.find(h => h.id === p.hostId && !h.revokedAt)} plan={plans.find(x => x.profileId === p.id)}
            onChange={onChange} onError={onError} />
        ))}
      </ul>

      {hosts.length === 0 ? (
        <p className="text-text-muted text-sm">Create a host first.</p>
      ) : (
        <div className="rounded border border-border bg-surface p-3">
          <h4 className="mb-2 text-sm font-semibold text-text">Create agent</h4>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 text-sm">
            <label className="flex flex-col gap-1 text-text-muted">Name (bot and /start name)
              <input className={input} value={form.name} maxLength={32} placeholder="codex" onChange={set('name')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">CLI
              <select className={input} value={form.adapter} onChange={set('adapter')}>
                <option value="codex">Codex</option>
                <option value="claude">Claude Code</option>
                {/* The host runs it over ACP (gemini --acp) and only with an API key */}
                <option value="gemini">Gemini CLI (ACP, API key)</option>
                {/* opencode acp on an OpenRouter key: any OpenRouter model, one model per agent */}
                <option value="opencode">opencode (ACP, OpenRouter key)</option>
              </select>
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Host
              <select className={input} value={hostId} onChange={set('hostId')}>
                {hosts.map(h => <option key={h.id} value={h.id}>{h.name}</option>)}
              </select>
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Workdir alias (mapped to a folder in the host config)
              <input className={input} value={form.workdirAlias} maxLength={64} onChange={set('workdirAlias')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">{opencode ? 'OpenRouter model ID (required)' : 'Model (optional)'}
              <input className={input} value={form.model} maxLength={64} placeholder={opencode ? 'qwen/qwen3-coder' : 'gpt-6.1-sol'} onChange={set('model')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Workspace ID (same repository = same ID across hosts)
              <input className={input} value={form.workspaceId} maxLength={64} onChange={set('workspaceId')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Effort
              <select className={input} value={form.effort} onChange={set('effort')}>
                {EFFORTS.map(e => <option key={e} value={e}>{e || 'CLI default'}</option>)}
              </select>
            </label>
            <label className="sm:col-span-2 flex flex-col gap-1 text-text-muted">Add to channel (optional)
              <select className={input} value={form.channelId} onChange={set('channelId')}>
                <option value="">None</option>
                {channels.map(c => <option key={c.id} value={c.id}>#{c.name}</option>)}
              </select>
            </label>
          </div>
          <label className="mt-3 flex min-h-11 md:min-h-8 items-start gap-2 text-sm text-text">
            <input type="checkbox" className="mt-1" checked={unboxedAck} onChange={e => setUnboxedAck(e.target.checked)} />
            <span>Run unboxed on this machine (it can read and change your files). <span className="text-text-muted">Only you can wake an unboxed agent. For anything that doesn&apos;t need this machine, create a box instead.</span></span>
          </label>
          <div className="mt-3">
            <Button onClick={() => void create()} disabled={!unboxedAck || !/^[a-z0-9][a-z0-9_-]*$/i.test(form.name.trim()) || !form.workdirAlias.trim() || (opencode && !form.model.trim())}>
              Create agent
            </Button>
          </div>
        </div>
      )}
    </section>
  );
}

function ProfileRow({ serverId, profile, host, plan, onChange, onError }: {
  serverId: string; profile: Profile; host: Host | undefined; plan?: PlanConnection; onChange: () => void; onError: (e: string) => void;
}) {
  const [model, setModel] = useState(profile.model ?? '');
  const [effort, setEffort] = useState(profile.effort ?? '');
  const [workspaceId, setWorkspaceId] = useState(profile.workspaceId ?? 'primary');
  const [wakeBudget, setWakeBudget] = useState(String(profile.wakeBudget));
  const validWakeBudget = Number.isInteger(Number(wakeBudget)) && Number(wakeBudget) >= 1 && Number(wakeBudget) <= 100000;
  const dirty = model !== (profile.model ?? '') || effort !== (profile.effort ?? '') || workspaceId !== (profile.workspaceId ?? 'primary') || wakeBudget !== String(profile.wakeBudget);
  // opencode's own default is an OpenCode Zen model, so an opencode agent always names one
  const opencode = profile.adapter === 'opencode';
  const validModel = !opencode || !!model.trim();

  const save = async () => {
    try {
      if (!validWakeBudget || !validModel) return;
      await api.patch(`/servers/${serverId}/agent-profiles/${profile.id}`, { model: model.trim() || null, effort: effort || null, workspaceId: workspaceId.trim().toLowerCase(), wakeBudget: Number(wakeBudget) });
      onChange();
    } catch (err) { onError(errorText(err)); }
  };
  const remove = async () => {
    if (!confirm(`Delete agent profile "${profile.name}"? Its bot stays; end its sessions first.`)) return;
    try { await api.delete(`/servers/${serverId}/agent-profiles/${profile.id}`); onChange(); } catch (err) { onError(errorText(err)); }
  };

  return (
    <li className="rounded border border-border bg-surface px-3 py-2 text-sm">
      <div className="flex items-center justify-between">
        <span className="text-text">
          <span className="font-medium">{profile.name}</span>
          <BoxModeBadge profile={profile} className="ml-2" />
          <span className="ml-2 text-xs text-text-muted">
            {profile.adapter} · {host?.name ?? 'revoked host'} · workdir {profile.workdirAlias} · {profile.wakeBudget} wakes · {profile.tokenBudget.toLocaleString()} tokens per session
          </span>
          <AuthBadge profile={profile} />
        </span>
        <button className="min-h-11 md:min-h-8 px-2 text-xs text-danger hover:underline" onClick={() => void remove()}>Delete</button>
      </div>
      <div className="mt-2 flex flex-wrap items-center gap-2">
        <label className="flex flex-col text-xs text-text-muted">Workspace ID (end sessions before changing)
          <input className={input} value={workspaceId} maxLength={64} onChange={e => setWorkspaceId(e.target.value)} />
        </label>
        <input className={input} value={model} placeholder={opencode ? 'OpenRouter model ID (required)' : 'model (CLI default)'} maxLength={64}
          aria-label={`Model for ${profile.name}`} onChange={e => setModel(e.target.value)} />
        <select className={input} value={effort} onChange={e => setEffort(e.target.value)}>
          {EFFORTS.map(e => <option key={e} value={e}>{e || 'CLI default'}</option>)}
        </select>
        <label className="flex flex-col text-xs text-text-muted">Wake budget per session
          <input className={input} type="number" min={1} max={100000} step={1} value={wakeBudget}
            onChange={e => setWakeBudget(e.target.value)} aria-label={`Wake budget for ${profile.name}`} />
        </label>
        {dirty && <Button variant="secondary" disabled={!validWakeBudget || !validModel} onClick={() => void save()}>Save</Button>}
      </div>
      {/* A box logs its CLI in from its Boxes entry instead */}
      {profile.adapter === 'codex' && host && host.kind !== 'box' && !profile.boxed && (
        <ChatGPTPlanConnect serverId={serverId} profileId={profile.id} hostName={host.name} plan={plan}
          siwcMode={profile.authMode === 'siwc'} onChange={onChange} />
      )}
      <ToolPermissions serverId={serverId} profile={profile} onChange={onChange} onError={onError} />
    </li>
  );
}

/** How the agent's CLI signs in, as its host reported it (docs/provider-terms.md). */
function AuthBadge({ profile }: { profile: Profile }) {
  const mode = profile.authMode ?? 'subscription';
  const tone = mode === 'api_key' ? 'bg-online/20 text-online' : 'bg-warn/20 text-warn';
  const detail = !profile.authReportedAt
    ? 'not reported by its host yet, so treated as a subscription'
    : mode === 'api_key' ? `key from ${profile.apiKeyEnv}`
    : mode === 'siwc' ? (profile.planOwnerId ? 'only the person who connected their plan can wake it' : 'no ChatGPT plan connected yet')
    : 'only you can wake it';
  return (
    <span className="mt-1 flex flex-wrap items-center gap-2 text-xs text-text-muted" data-testid={`auth-${profile.name}`}>
      <span className={`rounded px-1.5 py-0.5 font-semibold leading-none ${tone}`}>{authLabel(mode, profile.runApproval)}</span>
      {detail}
    </span>
  );
}

/**
 * Tool presets and always-allowed tools (#73). Saved on the server; the host reads them at
 * its next claim, so no host restart. Approving "always" on a tool card adds to the list.
 */
function ToolPermissions({ serverId, profile, onChange, onError }: {
  serverId: string; profile: Profile; onChange: () => void; onError: (e: string) => void;
}) {
  const presets = profile.toolPresets ?? [];
  const allowed = profile.allowedTools ?? [];
  const [rule, setRule] = useState('');
  const [busy, setBusy] = useState(false);
  const valid = TOOL_RULE.test(rule.trim()) && !allowed.includes(rule.trim());

  const patch = async (body: { toolPresets?: string[]; allowedTools?: string[] }) => {
    setBusy(true);
    try { await api.patch(`/servers/${serverId}/agent-profiles/${profile.id}`, body); onChange(); }
    catch (err) { onError(errorText(err)); }
    finally { setBusy(false); }
  };
  const toggle = (name: string) => void patch({ toolPresets: presets.includes(name) ? presets.filter(p => p !== name) : [...presets, name] });

  return (
    <div className="mt-3 border-t border-border pt-2">
      <div className="mb-1 text-xs font-semibold text-text-muted">Tools</div>
      <div className="flex flex-wrap gap-x-4 gap-y-1" role="group" aria-label={`Tool presets for ${profile.name}`}>
        {PRESETS.map(p => (
          <label key={p.name} className="flex min-h-11 md:min-h-8 items-center gap-2 text-sm text-text">
            <input type="checkbox" checked={presets.includes(p.name)} disabled={busy} onChange={() => toggle(p.name)} />
            {p.label} <span className="text-xs text-text-muted">{p.detail}</span>
          </label>
        ))}
        {presets.filter(n => !PRESETS.some(p => p.name === n)).map(n => (
          <label key={n} className="flex min-h-11 md:min-h-8 items-center gap-2 text-sm text-text">
            <input type="checkbox" checked disabled={busy} onChange={() => toggle(n)} /> {n} <span className="text-xs text-text-muted">from host config</span>
          </label>
        ))}
      </div>
      <p className="mt-1 text-xs text-text-muted">
        {presets.length === 0 ? 'No preset: the host config alone decides.' : 'Changes apply from the next wake; no host restart.'}
      </p>
      {allowed.length > 0 && (
        <ul className="mt-2 flex flex-wrap gap-1" aria-label={`Always allowed tools for ${profile.name}`}>
          {allowed.map(t => (
            <li key={t} className="flex items-center gap-1 rounded border border-border bg-bg px-2 font-mono text-xs text-text">
              <span className="break-all">{t}</span>
              <button className="min-h-11 min-w-11 md:min-h-7 md:min-w-7 text-danger" disabled={busy} aria-label={`Remove ${t}`}
                onClick={() => void patch({ allowedTools: allowed.filter(a => a !== t) })}>×</button>
            </li>
          ))}
        </ul>
      )}
      <div className="mt-2 flex items-center gap-2">
        <input className={`${input} flex-1 font-mono`} value={rule} placeholder="Always allow, e.g. Bash(cargo:*)" maxLength={310}
          aria-label={`Add an always-allowed tool for ${profile.name}`} onChange={e => setRule(e.target.value)} />
        <Button variant="secondary" disabled={!valid || busy} onClick={() => { const t = rule.trim(); setRule(''); void patch({ allowedTools: [...allowed, t] }); }}>Add</Button>
      </div>
    </div>
  );
}

import { useCallback, useEffect, useState } from 'react';
import { useServerStore } from '../../stores/serverStore';
import { api, serverApi, ApiError } from '../../lib/api';
import type { Channel } from '../../lib/contracts/server';
import { Button } from '../../components/ui/Button';
import { NotAffiliated } from '../../components/ui/NotAffiliated';
import { authLabel } from '../agents/agentSessions';
import { ChatGPTPlanConnect, type PlanConnection } from './ChatGPTPlanConnect';
import { useAuthStore } from '../../stores/authStore';
import { BoxesSection } from '../boxes/BoxesSection';
import { BoxModeBadge } from '../boxes/BoxModeBadge';

/**
 * Agent hosts and agents (docs/planning/agent-sessions-wbs.md, S6). The owner registers the
 * machine that runs agents (a host) and creates agents on it; members then use /start in a
 * channel. Tokens are shown once and go into the host's config file, never into a channel.
 */

/** kind 'box': the agora-host inside a box (docs/agent-boxes.md §8.1); listed under Boxes, not here. */
interface Host { id: string; name: string; createdAt: string; lastSeenAt: string | null; revokedAt: string | null; kind?: 'machine' | 'box' }
interface Profile {
  id: string; name: string; botId: string; hostId: string; adapter: 'codex' | 'claude' | 'gemini' | 'opencode';
  model: string | null; effort: string | null; workdirAlias: string; workspaceId?: string;
  wakeBudget: number; tokenBudget: number; runTimeoutSec: number;
  toolPresets?: string[]; allowedTools?: string[];
  /** Reported by the host at start (docs/provider-terms.md); subscription until then. */
  authMode?: 'subscription' | 'api_key' | 'siwc'; apiKeyEnv?: string | null; runApproval?: boolean; authReportedAt?: string | null;
  /** 'siwc' only: whose ChatGPT plan it runs on (docs/codex-chatgpt-plan.md). */
  planOwnerId?: string | null;
  /** Its host is a box (docs/agent-boxes.md §10); otherwise it runs unboxed on a machine. */
  boxed?: boolean; hostMode?: boolean;
}

const EFFORTS = ['', 'low', 'medium', 'high', 'xhigh'];

/** Built-in tool presets (agora-host/src/presets.ts); the host config can redefine them. */
const PRESETS: { name: string; label: string; detail: string }[] = [
  { name: 'readonly', label: 'Read-only', detail: 'read files and git history' },
  { name: 'dev', label: 'Dev', detail: 'edit files, git, gh, npm' },
  { name: 'research', label: 'Research', detail: 'web search and fetch' },
];
/** Same rule shape the server accepts: a Claude permission rule or a Codex word (write, network, web_search). */
const TOOL_RULE = /^[A-Za-z][A-Za-z0-9_]{0,99}(\([^(),\r\n]{1,200}\))?$/;
const input = 'min-h-11 md:min-h-9 bg-bg border border-border rounded px-3 py-1.5 text-sm text-text placeholder:text-text-muted/70 focus:outline-none focus:ring-2 focus:ring-primary';

export function errorText(err: unknown): string {
  if (err instanceof ApiError) return err.status === 403 ? 'Only the server owner can do this.' : err.code;
  return 'Request failed';
}

function OnceToken({ label, token, onDone }: { label: string; token: string; onDone: () => void }) {
  return (
    <div className="mb-4 rounded border border-primary/50 bg-primary/10 p-3 text-sm">
      <p className="mb-2 text-text">{label} It is shown only now; put it in the host's config file.</p>
      <code className="block break-all rounded bg-bg p-2 font-mono text-xs text-text select-all">{token}</code>
      <div className="mt-2 flex gap-2">
        <Button variant="secondary" onClick={() => { void navigator.clipboard?.writeText(token); }}>Copy</Button>
        <Button variant="secondary" onClick={onDone}>Done</Button>
      </div>
    </div>
  );
}

export function AgentSessionsSettings() {
  const serverId = useServerStore(s => s.instanceServerId);
  const ownerId = useServerStore(s => (serverId ? s.servers.get(serverId)?.ownerId : undefined));
  const userId = useAuthStore(s => s.user?.id);
  const [hosts, setHosts] = useState<Host[]>([]);
  const [profiles, setProfiles] = useState<Profile[]>([]);
  const [channels, setChannels] = useState<Channel[]>([]);
  const [plans, setPlans] = useState<PlanConnection[]>([]);
  const [error, setError] = useState('');
  const [secret, setSecret] = useState<{ label: string; token: string } | null>(null);
  const [reloadKey, setReloadKey] = useState(0);
  const load = useCallback(() => setReloadKey(k => k + 1), []);

  useEffect(() => {
    if (!serverId) return;
    let cancelled = false;
    Promise.all([
      api.get<Host[]>(`/servers/${serverId}/agent-hosts`),
      api.get<Profile[]>(`/servers/${serverId}/agent-profiles`),
      serverApi.getChannels(serverId),
      // ChatGPT plan connections; an older server without them just shows none
      api.get<PlanConnection[]>(`/servers/${serverId}/agent-plans`).catch(() => [] as PlanConnection[]),
    ]).then(([h, p, c, pl]) => {
      if (cancelled) return;
      setHosts(h);
      setProfiles(p);
      setPlans(pl);
      setChannels(c.filter(ch => ch.channelType === 3));
      setError('');
    }).catch(err => { if (!cancelled) setError(errorText(err)); });
    return () => { cancelled = true; };
  }, [serverId, reloadKey]);

  if (!serverId) return null;
  // Box hosts are managed with their box; agents are created on machine hosts here
  const machineHosts = hosts.filter(h => h.kind !== 'box');
  const activeHosts = machineHosts.filter(h => !h.revokedAt);
  const isOwner = !!userId && !!ownerId && userId.trim() === ownerId.trim();

  return (
    <div className="max-w-3xl">
      <h2 className="text-xl font-bold text-text mb-2">Agents</h2>
      <p className="text-text-muted text-sm mb-6">
        An agent host runs on the machine with your agent CLIs and wakes agents when they are addressed. Create a host,
        put its token in the host's config, then create agents on it. In a channel, <code>/start &lt;agent&gt;</code> starts a session.
      </p>
      {error && <p className="text-danger text-sm mb-4">{error}</p>}
      {secret && <OnceToken label={secret.label} token={secret.token} onDone={() => setSecret(null)} />}

      <p className="text-text-muted text-xs mb-6">
        Each agent runs its CLI on your own login (<em>subscription</em>) or on an API key, as set in the host's config.
        Personal subscriptions are for one person, so only you can wake a subscription agent; give agents that other
        members wake an API key. A Codex agent can also run on a ChatGPT plan through Sign in with ChatGPT; only the
        person who connected their plan can wake it. See docs/provider-terms.md and docs/codex-chatgpt-plan.md.
      </p>

      <BoxesSection serverId={serverId} channels={channels} isOwner={isOwner} />
      <HostsSection serverId={serverId} hosts={machineHosts} onChange={load} onToken={setSecret} onError={setError} />
      <AgentsSection serverId={serverId} hosts={activeHosts} allHosts={hosts} profiles={profiles} channels={channels} plans={plans}
        onChange={load} onToken={setSecret} onError={setError} />
      <NotAffiliated className="mt-8" />
    </div>
  );
}

function HostsSection({ serverId, hosts, onChange, onToken, onError }: {
  serverId: string; hosts: Host[]; onChange: () => void;
  onToken: (s: { label: string; token: string }) => void; onError: (e: string) => void;
}) {
  const [name, setName] = useState('');
  const create = async () => {
    try {
      const res = await api.post<{ host: Host; token: string }>(`/servers/${serverId}/agent-hosts`, { name: name.trim() });
      setName('');
      onToken({ label: `Host token for "${res.host.name}".`, token: res.token });
      onChange();
    } catch (err) { onError(errorText(err)); }
  };
  const revoke = async (h: Host) => {
    if (!confirm(`Revoke host "${h.name}"? Its token stops working at once and its agents stop waking.`)) return;
    try { await api.delete(`/servers/${serverId}/agent-hosts/${h.id}`); onChange(); } catch (err) { onError(errorText(err)); }
  };
  return (
    <section className="mb-8">
      <h3 className="text-lg font-semibold text-text mb-3">Hosts</h3>
      <ul className="mb-3 flex flex-col gap-1">
        {hosts.length === 0 && <li className="text-text-muted text-sm">No hosts yet.</li>}
        {hosts.map(h => (
          <li key={h.id} className="flex items-center justify-between rounded border border-border bg-surface px-3 py-2 text-sm">
            <span className={h.revokedAt ? 'text-text-muted line-through' : 'text-text'}>
              {h.name}
              <span className="ml-2 text-xs text-text-muted">
                {h.revokedAt ? 'revoked' : h.lastSeenAt ? `last seen ${new Date(h.lastSeenAt).toLocaleString()}` : 'never connected'}
              </span>
            </span>
            {!h.revokedAt && <button className="min-h-11 md:min-h-8 px-2 text-xs text-danger hover:underline" onClick={() => void revoke(h)}>Revoke</button>}
          </li>
        ))}
      </ul>
      <div className="flex gap-2">
        <input className={input} placeholder="Host name, e.g. my-pc" value={name} maxLength={64} onChange={e => setName(e.target.value)} />
        <Button onClick={() => void create()} disabled={!name.trim()}>Create host</Button>
      </div>
    </section>
  );
}

function AgentsSection({ serverId, hosts, allHosts, profiles, channels, plans, onChange, onToken, onError }: {
  serverId: string; hosts: Host[]; allHosts: Host[]; profiles: Profile[]; channels: Channel[]; plans: PlanConnection[]; onChange: () => void;
  onToken: (s: { label: string; token: string }) => void; onError: (e: string) => void;
}) {
  const [form, setForm] = useState({ name: '', adapter: 'codex', hostId: '', workdirAlias: 'agora', workspaceId: 'primary', model: '', effort: 'high', channelId: '' });
  // A profile on a machine host runs unboxed; the owner confirms that (docs/agent-boxes.md §10)
  const [unboxedAck, setUnboxedAck] = useState(false);
  const set = (k: keyof typeof form) => (e: { target: { value: string } }) => setForm(f => ({ ...f, [k]: e.target.value }));
  const hostId = form.hostId || hosts[0]?.id || '';
  const opencode = form.adapter === 'opencode';

  const create = async () => {
    try {
      const res = await api.post<{ bot: { username: string }; token: string }>(`/servers/${serverId}/agents`, {
        name: form.name.trim().toLowerCase(), adapter: form.adapter, hostId, workdirAlias: form.workdirAlias.trim(),
        workspaceId: form.workspaceId.trim().toLowerCase(), hostModeAck: true,
        ...(form.model.trim() ? { model: form.model.trim() } : {}),
        ...(form.effort ? { effort: form.effort } : {}),
        ...(form.channelId ? { channelId: form.channelId } : {}),
      });
      setForm(f => ({ ...f, name: '' }));
      setUnboxedAck(false);
      onToken({ label: `Bot token for agent "${res.bot.username}".`, token: res.token });
      onChange();
    } catch (err) { onError(errorText(err)); }
  };

  return (
    <section>
      <h3 className="text-lg font-semibold text-text mb-3">Agents</h3>
      <ul className="mb-4 flex flex-col gap-2">
        {profiles.length === 0 && <li className="text-text-muted text-sm">No agents yet.</li>}
        {profiles.map(p => (
          <ProfileRow key={p.id} serverId={serverId} profile={p} host={allHosts.find(h => h.id === p.hostId && !h.revokedAt)} plan={plans.find(x => x.profileId === p.id)}
            onChange={onChange} onError={onError} />
        ))}
      </ul>

      {hosts.length === 0 ? (
        <p className="text-text-muted text-sm">Create a host first.</p>
      ) : (
        <div className="rounded border border-border bg-surface p-3">
          <h4 className="mb-2 text-sm font-semibold text-text">Create agent</h4>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 text-sm">
            <label className="flex flex-col gap-1 text-text-muted">Name (bot and /start name)
              <input className={input} value={form.name} maxLength={32} placeholder="codex" onChange={set('name')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">CLI
              <select className={input} value={form.adapter} onChange={set('adapter')}>
                <option value="codex">Codex</option>
                <option value="claude">Claude Code</option>
                {/* The host runs it over ACP (gemini --acp) and only with an API key */}
                <option value="gemini">Gemini CLI (ACP, API key)</option>
                {/* opencode acp on an OpenRouter key: any OpenRouter model, one model per agent */}
                <option value="opencode">opencode (ACP, OpenRouter key)</option>
              </select>
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Host
              <select className={input} value={hostId} onChange={set('hostId')}>
                {hosts.map(h => <option key={h.id} value={h.id}>{h.name}</option>)}
              </select>
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Workdir alias (mapped to a folder in the host config)
              <input className={input} value={form.workdirAlias} maxLength={64} onChange={set('workdirAlias')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">{opencode ? 'OpenRouter model ID (required)' : 'Model (optional)'}
              <input className={input} value={form.model} maxLength={64} placeholder={opencode ? 'qwen/qwen3-coder' : 'gpt-6.1-sol'} onChange={set('model')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Workspace ID (same repository = same ID across hosts)
              <input className={input} value={form.workspaceId} maxLength={64} onChange={set('workspaceId')} />
            </label>
            <label className="flex flex-col gap-1 text-text-muted">Effort
              <select className={input} value={form.effort} onChange={set('effort')}>
                {EFFORTS.map(e => <option key={e} value={e}>{e || 'CLI default'}</option>)}
              </select>
            </label>
            <label className="sm:col-span-2 flex flex-col gap-1 text-text-muted">Add to channel (optional)
              <select className={input} value={form.channelId} onChange={set('channelId')}>
                <option value="">None</option>
                {channels.map(c => <option key={c.id} value={c.id}>#{c.name}</option>)}
              </select>
            </label>
          </div>
          <label className="mt-3 flex min-h-11 md:min-h-8 items-start gap-2 text-sm text-text">
            <input type="checkbox" className="mt-1" checked={unboxedAck} onChange={e => setUnboxedAck(e.target.checked)} />
            <span>Run unboxed on this machine (it can read and change your files). <span className="text-text-muted">Only you can wake an unboxed agent. For anything that doesn&apos;t need this machine, create a box instead.</span></span>
          </label>
          <div className="mt-3">
            <Button onClick={() => void create()} disabled={!unboxedAck || !/^[a-z0-9][a-z0-9_-]*$/i.test(form.name.trim()) || !form.workdirAlias.trim() || (opencode && !form.model.trim())}>
              Create agent
            </Button>
          </div>
        </div>
      )}
    </section>
  );
}

function ProfileRow({ serverId, profile, host, plan, onChange, onError }: {
  serverId: string; profile: Profile; host: Host | undefined; plan?: PlanConnection; onChange: () => void; onError: (e: string) => void;
}) {
  const [model, setModel] = useState(profile.model ?? '');
  const [effort, setEffort] = useState(profile.effort ?? '');
  const [workspaceId, setWorkspaceId] = useState(profile.workspaceId ?? 'primary');
  const [wakeBudget, setWakeBudget] = useState(String(profile.wakeBudget));
  const validWakeBudget = Number.isInteger(Number(wakeBudget)) && Number(wakeBudget) >= 1 && Number(wakeBudget) <= 100000;
  const dirty = model !== (profile.model ?? '') || effort !== (profile.effort ?? '') || workspaceId !== (profile.workspaceId ?? 'primary') || wakeBudget !== String(profile.wakeBudget);
  // opencode's own default is an OpenCode Zen model, so an opencode agent always names one
  const opencode = profile.adapter === 'opencode';
  const validModel = !opencode || !!model.trim();

  const save = async () => {
    try {
      if (!validWakeBudget || !validModel) return;
      await api.patch(`/servers/${serverId}/agent-profiles/${profile.id}`, { model: model.trim() || null, effort: effort || null, workspaceId: workspaceId.trim().toLowerCase(), wakeBudget: Number(wakeBudget) });
      onChange();
    } catch (err) { onError(errorText(err)); }
  };
  const remove = async () => {
    if (!confirm(`Delete agent profile "${profile.name}"? Its bot stays; end its sessions first.`)) return;
    try { await api.delete(`/servers/${serverId}/agent-profiles/${profile.id}`); onChange(); } catch (err) { onError(errorText(err)); }
  };

  return (
    <li className="rounded border border-border bg-surface px-3 py-2 text-sm">
      <div className="flex items-center justify-between">
        <span className="text-text">
          <span className="font-medium">{profile.name}</span>
          <BoxModeBadge profile={profile} className="ml-2" />
          <span className="ml-2 text-xs text-text-muted">
            {profile.adapter} · {host?.name ?? 'revoked host'} · workdir {profile.workdirAlias} · {profile.wakeBudget} wakes · {profile.tokenBudget.toLocaleString()} tokens per session
          </span>
          <AuthBadge profile={profile} />
        </span>
        <button className="min-h-11 md:min-h-8 px-2 text-xs text-danger hover:underline" onClick={() => void remove()}>Delete</button>
      </div>
      <div className="mt-2 flex flex-wrap items-center gap-2">
        <label className="flex flex-col text-xs text-text-muted">Workspace ID (end sessions before changing)
          <input className={input} value={workspaceId} maxLength={64} onChange={e => setWorkspaceId(e.target.value)} />
        </label>
        <input className={input} value={model} placeholder={opencode ? 'OpenRouter model ID (required)' : 'model (CLI default)'} maxLength={64}
          aria-label={`Model for ${profile.name}`} onChange={e => setModel(e.target.value)} />
        <select className={input} value={effort} onChange={e => setEffort(e.target.value)}>
          {EFFORTS.map(e => <option key={e} value={e}>{e || 'CLI default'}</option>)}
        </select>
        <label className="flex flex-col text-xs text-text-muted">Wake budget per session
          <input className={input} type="number" min={1} max={100000} step={1} value={wakeBudget}
            onChange={e => setWakeBudget(e.target.value)} aria-label={`Wake budget for ${profile.name}`} />
        </label>
        {dirty && <Button variant="secondary" disabled={!validWakeBudget || !validModel} onClick={() => void save()}>Save</Button>}
      </div>
      {/* A box logs its CLI in from its Boxes entry instead */}
      {profile.adapter === 'codex' && host && host.kind !== 'box' && !profile.boxed && (
        <ChatGPTPlanConnect serverId={serverId} profileId={profile.id} hostName={host.name} plan={plan}
          siwcMode={profile.authMode === 'siwc'} onChange={onChange} />
      )}
      <ToolPermissions serverId={serverId} profile={profile} onChange={onChange} onError={onError} />
    </li>
  );
}

/** How the agent's CLI signs in, as its host reported it (docs/provider-terms.md). */
function AuthBadge({ profile }: { profile: Profile }) {
  const mode = profile.authMode ?? 'subscription';
  const tone = mode === 'api_key' ? 'bg-online/20 text-online' : 'bg-warn/20 text-warn';
  const detail = !profile.authReportedAt
    ? 'not reported by its host yet, so treated as a subscription'
    : mode === 'api_key' ? `key from ${profile.apiKeyEnv}`
    : mode === 'siwc' ? (profile.planOwnerId ? 'only the person who connected their plan can wake it' : 'no ChatGPT plan connected yet')
    : 'only you can wake it';
  return (
    <span className="mt-1 flex flex-wrap items-center gap-2 text-xs text-text-muted" data-testid={`auth-${profile.name}`}>
      <span className={`rounded px-1.5 py-0.5 font-semibold leading-none ${tone}`}>{authLabel(mode, profile.runApproval)}</span>
      {detail}
    </span>
  );
}

/**
 * Tool presets and always-allowed tools (#73). Saved on the server; the host reads them at
 * its next claim, so no host restart. Approving "always" on a tool card adds to the list.
 */
function ToolPermissions({ serverId, profile, onChange, onError }: {
  serverId: string; profile: Profile; onChange: () => void; onError: (e: string) => void;
}) {
  const presets = profile.toolPresets ?? [];
  const allowed = profile.allowedTools ?? [];
  const [rule, setRule] = useState('');
  const [busy, setBusy] = useState(false);
  const valid = TOOL_RULE.test(rule.trim()) && !allowed.includes(rule.trim());

  const patch = async (body: { toolPresets?: string[]; allowedTools?: string[] }) => {
    setBusy(true);
    try { await api.patch(`/servers/${serverId}/agent-profiles/${profile.id}`, body); onChange(); }
    catch (err) { onError(errorText(err)); }
    finally { setBusy(false); }
  };
  const toggle = (name: string) => void patch({ toolPresets: presets.includes(name) ? presets.filter(p => p !== name) : [...presets, name] });

  return (
    <div className="mt-3 border-t border-border pt-2">
      <div className="mb-1 text-xs font-semibold text-text-muted">Tools</div>
      <div className="flex flex-wrap gap-x-4 gap-y-1" role="group" aria-label={`Tool presets for ${profile.name}`}>
        {PRESETS.map(p => (
          <label key={p.name} className="flex min-h-11 md:min-h-8 items-center gap-2 text-sm text-text">
            <input type="checkbox" checked={presets.includes(p.name)} disabled={busy} onChange={() => toggle(p.name)} />
            {p.label} <span className="text-xs text-text-muted">{p.detail}</span>
          </label>
        ))}
        {presets.filter(n => !PRESETS.some(p => p.name === n)).map(n => (
          <label key={n} className="flex min-h-11 md:min-h-8 items-center gap-2 text-sm text-text">
            <input type="checkbox" checked disabled={busy} onChange={() => toggle(n)} /> {n} <span className="text-xs text-text-muted">from host config</span>
          </label>
        ))}
      </div>
      <p className="mt-1 text-xs text-text-muted">
        {presets.length === 0 ? 'No preset: the host config alone decides.' : 'Changes apply from the next wake; no host restart.'}
      </p>
      {allowed.length > 0 && (
        <ul className="mt-2 flex flex-wrap gap-1" aria-label={`Always allowed tools for ${profile.name}`}>
          {allowed.map(t => (
            <li key={t} className="flex items-center gap-1 rounded border border-border bg-bg px-2 font-mono text-xs text-text">
              <span className="break-all">{t}</span>
              <button className="min-h-11 min-w-11 md:min-h-7 md:min-w-7 text-danger" disabled={busy} aria-label={`Remove ${t}`}
                onClick={() => void patch({ allowedTools: allowed.filter(a => a !== t) })}>×</button>
            </li>
          ))}
        </ul>
      )}
      <div className="mt-2 flex items-center gap-2">
        <input className={`${input} flex-1 font-mono`} value={rule} placeholder="Always allow, e.g. Bash(cargo:*)" maxLength={310}
          aria-label={`Add an always-allowed tool for ${profile.name}`} onChange={e => setRule(e.target.value)} />
        <Button variant="secondary" disabled={!valid || busy} onClick={() => { const t = rule.trim(); setRule(''); void patch({ allowedTools: [...allowed, t] }); }}>Add</Button>
      </div>
    </div>
  );
}

import { memo, useCallback, useDeferredValue, useEffect, useMemo, useRef, useState } from 'react';
import { Link } from 'react-router-dom';
import { defaultRangeExtractor, useVirtualizer } from '@tanstack/react-virtual';
import { Avatar } from '../../components/ui/Avatar';
import { useServerStore } from '../../stores/serverStore';
import { useChannelStore } from '../../stores/channelStore';
import { botApi, serverApi, runtimeApi, ApiError } from '../../lib/api';
import type { Bot, BotDetail, BotToken, RuntimeAccess } from '../../lib/api';
import type { Channel } from '../../lib/contracts/server';
import { Button } from '../../components/ui/Button';
import { CreateBotModal } from './CreateBotModal';
import { CreateTokenModal } from './CreateTokenModal';
import { CreateAgentInviteModal } from './CreateAgentInviteModal';

export function BotManagement() {
  const instanceServerId = useServerStore(s => s.instanceServerId);
  const [bots, setBots] = useState<any>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [permissionDenied, setPermissionDenied] = useState(false);
  const [showCreateBot, setShowCreateBot] = useState(false);
  const [showInvite, setShowInvite] = useState(false);
  const [expandedBotId, setExpandedBotId] = useState<string | null>(null);
  const [query, setQuery] = useState('');
  const deferredQuery = useDeferredValue(query);

  const fetchBots = useCallback(async (showLoading = true) => {
    if (!instanceServerId) return;
    if (showLoading) setLoading(true);
    setError('');
    try {
      const data = await botApi.list(instanceServerId);
      setBots(data);
      setPermissionDenied(false);
    } catch (err) {
      if (err instanceof ApiError && err.status === 403) {
        setPermissionDenied(true);
      } else {
        setError(err instanceof ApiError ? err.code : 'Failed to load bots');
      }
    } finally {
      setLoading(false);
    }
  }, [instanceServerId]);

  useEffect(() => { fetchBots(); }, [fetchBots]);

  // A refresh after a change keeps the list (and its scroll position) on screen
  const refresh = useCallback(() => { void fetchBots(false); }, [fetchBots]);
  const toggle = useCallback((botId: string) => setExpandedBotId(cur => (cur === botId ? null : botId)), []);

  // Newest first, so a bot you just created is at the top of a long list
  const sorted = useMemo(() => [...bots].sort((a, b) => b.createdAt.localeCompare(a.createdAt)), [bots]);
  const shown = useMemo(() => {
    const q = deferredQuery.trim().toLowerCase();
    return q ? sorted.filter(b => b.username.toLowerCase().includes(q)) : sorted;
  }, [sorted, deferredQuery]);

  if (!instanceServerId) return null;

  if (permissionDenied) {
    return (
      <div>
        <h2 className="text-xl font-bold text-text mb-4">Bot Management</h2>
        <p className="text-text-muted mb-4">You don't have permission to manage bots.</p>
        <Link to="/app" className="hidden min-h-11 items-center text-primary-text hover:underline sm:inline-flex md:min-h-8">Back to chat</Link>
      </div>
    );
  }

  if (loading) {
    return <p className="text-text-muted">Loading bots...</p>;
  }

  return (
    <div>
      <div className="flex flex-wrap items-center justify-between gap-3 mb-6">
        <h2 className="text-xl font-bold text-text">Bot Management</h2>
        <div className="flex gap-2">
          <Button onClick={() => setShowInvite(true)}>Invite Agent</Button>
          <Button variant="secondary" onClick={() => setShowCreateBot(true)}>Create Bot</Button>
        </div>
      </div>

      {error && <p className="text-danger text-sm mb-4">{error}</p>}

      <ChannelLoopGuardSection serverId={instanceServerId} />

      {bots.length === 0 ? (
        <p className="text-text-muted">No bots yet. Create one to get started.</p>
      ) : (
        <section>
          <div className="flex flex-wrap items-center gap-3 mb-2">
            <input
              type="search"
              value={query}
              onChange={e => setQuery(e.target.value)}
              placeholder="Search bots"
              aria-label="Search bots"
              className="min-h-11 md:min-h-9 w-full max-w-xs px-3 py-1.5 rounded border border-border bg-surface text-text placeholder:text-text-muted/70 text-sm"
            />
            <span className="text-text-muted text-xs" aria-live="polite">
              {shown.length === bots.length ? `${bots.length} bots` : `${shown.length} of ${bots.length} bots`}
            </span>
          </div>
          {shown.length === 0 ? (
            <p className="text-text-muted text-sm">No bots match “{deferredQuery.trim()}”.</p>
          ) : (
            <BotList
              bots={shown}
              serverId={instanceServerId}
              expandedBotId={expandedBotId}
              onToggle={toggle}
              onChanged={refresh}
            />
          )}
        </section>
      )}

      <CreateBotModal
        serverId={instanceServerId}
        isOpen={showCreateBot}
        onClose={() => setShowCreateBot(false)}
        onCreated={refresh}
      />
      {showInvite && <CreateAgentInviteModal serverId={instanceServerId} onClose={() => setShowInvite(false)} onCreated={refresh} />}
    </div>
  );
}

// ─── Bot List (virtualized) ───────────────────────────────────────────────

/** Rendering every bot stalled the page at about 1,800 bots (#241): only the rows in view are mounted. */
function BotList({
  bots,
  serverId,
  expandedBotId,
  onToggle,
  onChanged,
}: {
  bots: Bot[];
  serverId: string;
  expandedBotId: string | null;
  onToggle: (botId: string) => void;
  onChanged: () => void;
}) {
  const scrollRef = useRef<HTMLDivElement>(null);
  const expandedIndex = expandedBotId ? bots.findIndex(b => b.id === expandedBotId) : -1;
  // This component is not compiled by the React Compiler; the virtualizer is read during render only
  // eslint-disable-next-line react-hooks/incompatible-library
  const virtualizer = useVirtualizer({
    count: bots.length,
    getScrollElement: () => scrollRef.current,
    estimateSize: () => 60,
    overscan: 8,
    getItemKey: index => bots[index].id,
    // The open bot stays mounted while scrolled away, so its panel (a half-made token, an error) survives
    rangeExtractor: range => {
      const indexes = defaultRangeExtractor(range);
      return expandedIndex < 0 || indexes.includes(expandedIndex) ? indexes : [...indexes, expandedIndex].sort((a, b) => a - b);
    },
  });

  return (
    <div ref={scrollRef} data-testid="bot-list" className="max-h-[70vh] overflow-y-auto overscroll-contain">
      <div className="relative w-full" style={{ height: virtualizer.getTotalSize() }}>
        {virtualizer.getVirtualItems().map(item => {
          const bot = bots[item.index];
          return (
            <div
              key={item.key}
              data-index={item.index}
              ref={virtualizer.measureElement}
              className="absolute left-0 top-0 w-full pb-2"
              style={{ transform: `translateY(${item.start}px)` }}
            >
              <BotRow
                bot={bot}
                serverId={serverId}
                isExpanded={expandedBotId === bot.id}
                onToggle={onToggle}
                onChanged={onChanged}
              />
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ─── Channel Loop Guard Settings ──────────────────────────────────────────

type GuardField = 'maxBotHops' | 'maxThreadBotHops';
type Limits = Record<GuardField, number>;
/** The limit a guard gets when it is switched on with no earlier value to restore. */
const GUARD_DEFAULT: Limits = { maxBotHops: 4, maxThreadBotHops: 4 };

/**
 * Both loop guards per channel (#23): the channel guard (top-level bot messages in a row)
 * and the thread guard (bot replies in a row inside one thread). Each has an on/off switch;
 * off is a limit of 0.
 */
function ChannelLoopGuardSection({ serverId }: { serverId: string }) {
  const [channels, setChannels] = useState<Channel[]>([]);
  // Limits as loaded or last confirmed by a save here
  const [loaded, setLoaded] = useState<Record<string, Limits>>({});
  // Edits not yet confirmed by the server, by `${channelId}:${field}`
  const [dirty, setDirty] = useState<Record<string, number>>({});
  const [saving, setSaving] = useState<Record<string, boolean>>({});
  const [error, setError] = useState('');
  // A change made elsewhere (a notice's Raise limit or Turn off) arrives as ChannelBotConfig
  const live = useChannelStore(s => s.channels);
  const pending = useRef<Record<string, { timer: ReturnType<typeof setTimeout>; value: number }>>({});
  // Saves of one field go out one at a time, in order, so the last change made wins
  const queues = useRef<Record<string, Promise<void>>>({});
  // The last limit above 0, restored when a guard is switched back on
  const lastOn = useRef<Record<string, number>>({});
  const mounted = useRef(true);

  useEffect(() => {
    serverApi.getChannels(serverId).then((chs) => {
      const textChannels = chs.filter(c => c.channelType === 3);
      setChannels(textChannels);
      const initial: Record<string, Limits> = {};
      for (const ch of textChannels) {
        initial[ch.id] = { maxBotHops: ch.maxBotHops ?? 4, maxThreadBotHops: ch.maxThreadBotHops ?? 0 };
      }
      setLoaded(initial);
    }).catch(() => setError('Failed to load channels'));
  }, [serverId]);

  // enqueue only touches refs and state setters, so the first render's copy stays valid for the unmount flush
  const enqueueOnLeave = useRef(enqueue);

  // Leaving the page sends a change still waiting out its debounce instead of dropping it,
  // behind any save of that field still in flight so the older one cannot land last
  useEffect(() => {
    mounted.current = true;
    const waiting = pending.current;
    const flush = enqueueOnLeave.current;
    return () => {
      mounted.current = false;
      for (const [key, p] of Object.entries(waiting)) {
        clearTimeout(p.timer);
        delete waiting[key];
        const [channelId, field] = key.split(':') as [string, GuardField];
        flush(channelId, field, p.value);
      }
    };
  }, []);

  const shown = (channelId: string, field: GuardField): number => {
    const key = `${channelId}:${field}`;
    return dirty[key] ?? live.get(channelId)?.[field] ?? loaded[channelId]?.[field] ?? GUARD_DEFAULT[field];
  };

  function change(channelId: string, field: GuardField, value: number, delay: number) {
    const key = `${channelId}:${field}`;
    const prev = shown(channelId, field);
    if (prev > 0) lastOn.current[key] = prev;
    setDirty(d => ({ ...d, [key]: value }));
    if (pending.current[key]) clearTimeout(pending.current[key].timer);
    const timer = setTimeout(() => {
      delete pending.current[key];
      enqueue(channelId, field, value);
    }, delay);
    pending.current[key] = { timer, value };
  }

  /** Queues a save behind any earlier save of the same field (save never rejects). */
  function enqueue(channelId: string, field: GuardField, value: number) {
    const key = `${channelId}:${field}`;
    queues.current[key] = (queues.current[key] ?? Promise.resolve()).then(() => save(channelId, field, value));
  }

  function handleNumber(channelId: string, field: GuardField, raw: string) {
    const num = parseInt(raw, 10);
    // 0 would be "off": that is the switch's job, so the box keeps a limit while typing
    if (isNaN(num) || num < 1 || num > 1000) return;
    change(channelId, field, num, 600);
  }

  function handleToggle(channelId: string, field: GuardField, on: boolean) {
    const restore = lastOn.current[`${channelId}:${field}`] ?? GUARD_DEFAULT[field];
    change(channelId, field, on ? restore : 0, 0);
  }

  async function save(channelId: string, field: GuardField, value: number) {
    const key = `${channelId}:${field}`;
    if (mounted.current) { setSaving(s => ({ ...s, [key]: true })); setError(''); }
    // Only the latest edit clears the dirty value; an older save finishing must not
    const settle = (d: Record<string, number>) => {
      if (d[key] !== value || pending.current[key]) return d;
      const next = { ...d };
      delete next[key];
      return next;
    };
    try {
      const config = await botApi.updateChannelBotConfig(channelId, { [field]: value });
      useChannelStore.getState().patchChannel(channelId, { maxBotHops: config.maxBotHops, maxThreadBotHops: config.maxThreadBotHops });
      if (!mounted.current) return;
      setLoaded(l => ({ ...l, [channelId]: { maxBotHops: config.maxBotHops, maxThreadBotHops: config.maxThreadBotHops } }));
      setDirty(settle);
    } catch (err) {
      if (!mounted.current) return;
      // Show what the server still has, not the value that failed
      setDirty(settle);
      setError(err instanceof ApiError ? err.code : 'Failed to save');
    } finally {
      if (mounted.current) setSaving(s => ({ ...s, [key]: false }));
    }
  }

  if (channels.length === 0) return null;

  const guard = (ch: Channel, field: GuardField, label: string, unit: string) => {
    const value = shown(ch.id, field);
    const on = value > 0;
    const key = `${ch.id}:${field}`;
    return (
      <div className="flex items-center gap-2">
        <label className="min-h-11 md:min-h-8 flex items-center gap-1.5 text-xs text-text-muted cursor-pointer">
          <input
            type="checkbox"
            role="switch"
            checked={on}
            onChange={e => handleToggle(ch.id, field, e.target.checked)}
            aria-label={`${label} loop guard in #${ch.name}`}
            className="accent-primary"
          />
          {label}
        </label>
        {on ? (
          <input
            type="number"
            min={1}
            max={1000}
            value={value}
            onChange={e => handleNumber(ch.id, field, e.target.value)}
            aria-label={`${label} limit in #${ch.name} (${unit})`}
            title={`Pause after this many ${unit} in a row`}
            className="min-h-11 md:min-h-8 w-16 px-2 py-1 rounded border border-border bg-surface text-text text-sm text-right"
          />
        ) : (
          <span className="w-16 text-text-muted text-xs">Off</span>
        )}
        <span className="w-12 text-text-muted text-xs" aria-live="polite">{saving[key] ? 'Saving…' : ''}</span>
      </div>
    );
  };

  return (
    <section className="mb-6">
      <h3 className="text-sm font-semibold text-text mb-2">Loop Guard</h3>
      <p className="text-text-muted text-xs mb-3">
        Pauses agents after this many bot posts in a row with no human message. The channel guard counts top-level
        messages; the thread guard counts replies inside each thread. A human message resets both, and the notice
        it posts has Continue, Raise limit and Turn off buttons.
      </p>
      {error && <p className="text-danger text-xs mb-2" role="alert">{error}</p>}
      <div className="flex flex-col gap-1">
        {channels.map((ch) => (
          <div key={ch.id} className="flex flex-wrap items-center gap-x-6 gap-y-1 px-2 py-1.5 rounded hover:bg-surface-hover">
            <span className="flex min-w-32 flex-1 items-center gap-1 text-sm">
              <span className="text-text-muted">#</span>
              <span className="text-text">{ch.name}</span>
            </span>
            {guard(ch, 'maxBotHops', 'Channel', 'bot messages')}
            {guard(ch, 'maxThreadBotHops', 'Threads', 'bot replies in one thread')}
          </div>
        ))}
      </div>
    </section>
  );
}

// ─── Bot Row (expandable) ─────────────────────────────────────────────────

// Memoized with stable callbacks: opening one bot re-renders that row, not the whole list
const BotRow = memo(function BotRow({
  bot,
  serverId,
  isExpanded,
  onToggle,
  onChanged,
}: {
  bot: Bot;
  serverId: string;
  isExpanded: boolean;
  onToggle: (botId: string) => void;
  onChanged: () => void;
}) {
  const [pausing, setPausing] = useState(false);
  const [pauseError, setPauseError] = useState('');
  const [savingAccess, setSavingAccess] = useState(false);
  const isPaused = !!bot.pausedAt;

  async function changeAccess(access: RuntimeAccess) {
    if (access === 'auto' && !confirm(`Let ${bot.username} run code without approval? Runs still execute in the sandbox with its limits.`)) return;
    setSavingAccess(true);
    setPauseError('');
    try {
      await runtimeApi.setBotAccess(serverId, bot.id, access);
      onChanged();
    } catch (err) {
      setPauseError(err instanceof ApiError ? err.code : 'Failed to update code run access');
    } finally {
      setSavingAccess(false);
    }
  }

  async function togglePause() {
    setPausing(true);
    setPauseError('');
    try {
      if (isPaused) {
        await botApi.setPaused(serverId, bot.id, false);
      } else {
        const reason = prompt('Pause this bot? It will be read-only until resumed.\n\nReason (optional):');
        if (reason === null) return;
        await botApi.setPaused(serverId, bot.id, true, reason.trim() || undefined);
      }
      onChanged();
    } catch (err) {
      setPauseError(err instanceof ApiError ? err.code : 'Failed to update pause state');
    } finally {
      setPausing(false);
    }
  }

  return (
    <div className="border border-border rounded-lg overflow-hidden">
      <div className="flex items-center hover:bg-surface-hover">
      <button
        onClick={() => onToggle(bot.id)}
        aria-expanded={isExpanded}
        className="min-h-11 flex-1 flex items-center justify-between px-4 py-3 text-left"
      >
        <div>
          <span className="text-text font-medium">{bot.username}</span>
          {isPaused && (
            <span
              className="ml-2 inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-semibold leading-none bg-warn/20 text-warn"
              title={bot.pausedReason ? `Paused: ${bot.pausedReason}` : 'Paused'}
            >
              PAUSED
            </span>
          )}
          <span className="text-text-muted text-xs ml-2">
            {new Date(bot.createdAt).toLocaleDateString()}
          </span>
          {pauseError && <span className="text-danger text-xs ml-2">{pauseError}</span>}
        </div>
        <svg
          className="h-4 w-4 text-text-muted transition-transform"
          style={{ transform: isExpanded ? 'rotate(180deg)' : 'rotate(0deg)' }}
          fill="none"
          viewBox="0 0 24 24"
          stroke="currentColor"
          strokeWidth="2"
        >
          <polyline points="6 9 12 15 18 9" />
        </svg>
      </button>
      <label className="flex items-center gap-1 pr-3 text-xs text-text-muted" title="Whether this bot may run code in the sandbox">
        Code runs
        <select
          className="min-h-11 md:min-h-8 bg-surface border border-border rounded px-2 py-1 text-xs text-text"
          value={bot.runtimeAccess ?? 'none'}
          disabled={savingAccess}
          onChange={e => changeAccess(e.target.value as RuntimeAccess)}
          aria-label={`Code run access for ${bot.username}`}
        >
          <option value="none">Off</option>
          <option value="approval">Need approval</option>
          <option value="auto">Auto-run</option>
        </select>
      </label>
      <div className="pr-3">
        <Button variant="secondary" onClick={togglePause} loading={pausing}>
          {isPaused ? 'Resume' : 'Pause'}
        </Button>
      </div>
      </div>
      {isExpanded && (
        <BotDetailPanel botId={bot.id} serverId={serverId} onDeleted={onChanged} />
      )}
    </div>
  );
});

// ─── Bot Detail Panel ─────────────────────────────────────────────────────

function BotDetailPanel({
  botId,
  serverId,
  onDeleted,
}: {
  botId: string;
  serverId: string;
  onDeleted: () => void;
}) {
  const [detail, setDetail] = useState<BotDetail | null>(null);
  const [allChannels, setAllChannels] = useState<Channel[]>([]);
  const [tokens, setTokens] = useState<BotToken[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [showCreateToken, setShowCreateToken] = useState(false);
  const [showInvite, setShowInvite] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [channelLoading, setChannelLoading] = useState<string | null>(null);
  const [avatarInput, setAvatarInput] = useState('');
  const [avatarSaving, setAvatarSaving] = useState(false);
  const [avatarError, setAvatarError] = useState('');

  const fetchDetail = useCallback(async () => {
    try {
      const [d, channels] = await Promise.all([
        botApi.get(serverId, botId),
        serverApi.getChannels(serverId),
      ]);
      setDetail(d);
      setAvatarInput(d.avatarUrl || '');
      // Only show text channels (type 3) for bot access
      setAllChannels(channels.filter(c => c.channelType === 3));
      if (d.canManageTokens) {
        const t = await botApi.listTokens(serverId, botId);
        setTokens(t);
      }
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to load bot details');
    } finally {
      setLoading(false);
    }
  }, [serverId, botId]);

  useEffect(() => { fetchDetail(); }, [fetchDetail]);

  async function handleDelete() {
    if (!confirm('Delete this bot? This cannot be undone.')) return;
    setDeleting(true);
    try {
      await botApi.remove(serverId, botId);
      onDeleted();
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to delete bot');
      setDeleting(false);
    }
  }

  async function handleRevokeToken(tokenId: string) {
    try {
      await botApi.revokeToken(serverId, botId, tokenId);
      setTokens(prev => prev.map(t => t.id === tokenId ? { ...t, revokedAt: new Date().toISOString() } : t));
    } catch (err) {
      if (err instanceof ApiError && err.status === 403) {
        // Permissions changed — refetch detail
        fetchDetail();
      }
      setError(err instanceof ApiError ? err.code : 'Failed to revoke token');
    }
  }

  async function handleClearBinding(tokenId: string) {
    try {
      await botApi.clearTokenBinding(serverId, botId, tokenId);
      setTokens(prev => prev.map(t => t.id === tokenId ? { ...t, boundClient: null, boundAt: null, lastRefused: null } : t));
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to clear the binding');
    }
  }

  async function toggleDirect(channelId: string, canDirect: boolean) {
    setChannelLoading(channelId);
    setError('');
    try {
      await botApi.setCanDirect(channelId, botId, !canDirect);
      setDetail(await botApi.get(serverId, botId));
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to update who may direct');
    } finally {
      setChannelLoading(null);
    }
  }

  async function toggleChannel(channelId: string, hasAccess: boolean) {
    setChannelLoading(channelId);
    try {
      if (hasAccess) {
        await botApi.revokeChannel(channelId, botId);
      } else {
        await botApi.grantChannel(channelId, botId);
      }
      // Refetch detail to get updated channel list
      const d = await botApi.get(serverId, botId);
      setDetail(d);
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to update channel access');
    } finally {
      setChannelLoading(null);
    }
  }

  if (loading) {
    return <div className="px-4 py-3 border-t border-border text-text-muted text-sm">Loading...</div>;
  }

  if (error && !detail) {
    return <div className="px-4 py-3 border-t border-border text-danger text-sm">{error}</div>;
  }

  if (!detail) return null;

  const botChannelIds = new Set(detail.channels.map(c => c.id));
  const directChannelIds = new Set(detail.channels.filter(c => c.canDirect).map(c => c.id));
  const activeTokens = tokens.filter(t => !t.revokedAt);
  const revokedTokens = tokens.filter(t => t.revokedAt);

  return (
    <div className="border-t border-border px-4 py-4 flex flex-col gap-5 bg-bg/50">
      {error && <p className="text-danger text-sm">{error}</p>}

      {/* ── Avatar ── */}
      <section>
        <h4 className="text-sm font-semibold text-text mb-2">Avatar</h4>
        <div className="flex items-start gap-3">
          <Avatar userId={botId} username={detail.username} avatarUrl={detail.avatarUrl} className="h-12 w-12 text-sm" />
          <div className="flex-1 min-w-0">
            <input
              type="text"
              value={avatarInput}
              onChange={(e) => { setAvatarInput(e.target.value); setAvatarError(''); }}
              placeholder="data:image/svg+xml;base64,..."
              className="min-h-11 md:min-h-9 w-full px-3 py-1.5 rounded border border-border bg-surface text-text placeholder:text-text-muted/70 text-sm"
            />
            {avatarError && <p className="text-danger text-xs mt-1">{avatarError}</p>}
            <div className="flex gap-2 mt-2">
              <Button
                variant="secondary"
                className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
                loading={avatarSaving}
                onClick={async () => {
                  setAvatarSaving(true);
                  setAvatarError('');
                  try {
                    const res = await botApi.update(serverId, botId, { avatarUrl: avatarInput || null });
                    setDetail(prev => prev ? { ...prev, avatarUrl: res.avatarUrl } : prev);
                  } catch (err) {
                    setAvatarError(err instanceof ApiError ? err.code : 'Failed to save avatar');
                  } finally {
                    setAvatarSaving(false);
                  }
                }}
              >
                Save Avatar
              </Button>
              {detail.avatarUrl && (
                <Button
                  variant="secondary"
                  className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
                  onClick={async () => {
                    setAvatarSaving(true);
                    setAvatarError('');
                    try {
                      const res = await botApi.update(serverId, botId, { avatarUrl: null });
                      setDetail(prev => prev ? { ...prev, avatarUrl: res.avatarUrl } : prev);
                      setAvatarInput('');
                    } catch (err) {
                      setAvatarError(err instanceof ApiError ? err.code : 'Failed to remove avatar');
                    } finally {
                      setAvatarSaving(false);
                    }
                  }}
                >
                  Remove
                </Button>
              )}
            </div>
          </div>
        </div>
      </section>

      {/* ── Channel Access ── */}
      <section>
        <h4 className="text-sm font-semibold text-text mb-2">Channel Access</h4>
        {allChannels.length === 0 ? (
          <p className="text-text-muted text-xs">No text channels found.</p>
        ) : (
          <div className="flex flex-col gap-1">
            {allChannels.map((ch) => {
              const hasAccess = botChannelIds.has(ch.id);
              const isLoading = channelLoading === ch.id;
              return (
                <label
                  key={ch.id}
                  className="min-h-11 md:min-h-9 flex items-center gap-2 px-2 py-1.5 rounded hover:bg-surface-hover cursor-pointer text-sm"
                >
                  <input
                    type="checkbox"
                    checked={hasAccess}
                    disabled={isLoading}
                    onChange={() => toggleChannel(ch.id, hasAccess)}
                    className="accent-primary"
                  />
                  <span className="text-text-muted">#</span>
                  <span className="text-text">{ch.name}</span>
                  {isLoading && <span className="text-text-muted text-xs ml-auto">...</span>}
                  {hasAccess && (
                    <span
                      className="ml-auto flex items-center gap-1 text-xs text-text-muted"
                      title="Lets this bot give other agents instructions in this channel. Only the server owner can change it."
                      onClick={(e) => e.stopPropagation()}
                    >
                      <input
                        type="checkbox"
                        checked={directChannelIds.has(ch.id)}
                        disabled={isLoading}
                        onChange={() => toggleDirect(ch.id, directChannelIds.has(ch.id))}
                        className="accent-primary"
                      />
                      can direct agents
                    </span>
                  )}
                </label>
              );
            })}
          </div>
        )}
      </section>

      {/* ── Tokens (owner / admin only) ── */}
      {detail.canManageTokens && (
        <section>
          <Button onClick={() => setShowInvite(true)}>Invite Agent</Button>
          {showInvite && <CreateAgentInviteModal serverId={serverId} botId={botId} onClose={() => setShowInvite(false)} onCreated={() => {}} />}
          <div className="flex items-center justify-between mb-2">
            <h4 className="text-sm font-semibold text-text">Tokens</h4>
            <Button
              variant="secondary"
              className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
              onClick={() => setShowCreateToken(true)}
            >
              New Token
            </Button>
          </div>
          {activeTokens.length === 0 && revokedTokens.length === 0 ? (
            <p className="text-text-muted text-xs">No tokens yet.</p>
          ) : (
            <div className="flex flex-col gap-1">
              {activeTokens.map((t) => (
                <div key={t.id} className="flex items-center justify-between px-2 py-1.5 rounded bg-surface text-sm">
                  <div>
                    <span className="text-text">{t.name || 'Unnamed'}</span>
                    <span className="text-text-muted text-xs ml-2">
                      Created {new Date(t.createdAt).toLocaleDateString()}
                    </span>
                    {t.lastUsedAt && (
                      <span className="text-text-muted text-xs ml-2">
                        Last used {new Date(t.lastUsedAt).toLocaleDateString()}
                        {t.lastUsedClient ? ` by ${t.lastUsedClient}` : ''}
                        {t.lastUsedIp ? ` from ${t.lastUsedIp}` : ''}
                      </span>
                    )}
                    {t.boundClient && (
                      <span className="text-text-muted text-xs ml-2" title="Requests from any other client are refused">
                        Bound to {t.boundClient}
                      </span>
                    )}
                    {t.lastRefused && (
                      <span className="block text-danger text-xs">
                        Refused {t.lastRefused.client ? `use by ${t.lastRefused.client}` : 'a use with no client name'}
                        {t.lastRefused.ip ? ` from ${t.lastRefused.ip}` : ''} on {new Date(t.lastRefused.at).toLocaleString()}.
                        If that wasn't you moving this agent, revoke the token.
                      </span>
                    )}
                  </div>
                  <div className="flex shrink-0">
                    {t.boundClient && (
                      <button
                        onClick={() => handleClearBinding(t.id)}
                        className="min-h-11 md:min-h-8 px-2 text-text-muted text-xs hover:underline"
                        title="The next client that uses the token binds it again"
                      >
                        Clear binding
                      </button>
                    )}
                    <button
                      onClick={() => handleRevokeToken(t.id)}
                      className="min-h-11 md:min-h-8 px-2 text-danger text-xs hover:underline"
                    >
                      Revoke
                    </button>
                  </div>
                </div>
              ))}
              {revokedTokens.map((t) => (
                <div key={t.id} className="flex items-center px-2 py-1.5 rounded bg-surface text-sm opacity-50">
                  <span className="text-text line-through">{t.name || 'Unnamed'}</span>
                  <span className="text-text-muted text-xs ml-2">Revoked</span>
                </div>
              ))}
            </div>
          )}

          <CreateTokenModal
            serverId={serverId}
            botId={botId}
            isOpen={showCreateToken}
            onClose={() => setShowCreateToken(false)}
            onCreated={async () => {
              const t = await botApi.listTokens(serverId, botId);
              setTokens(t);
            }}
          />
        </section>
      )}

      {/* ── Delete Bot ── */}
      <div className="pt-2 border-t border-border">
        <Button variant="danger" onClick={handleDelete} loading={deleting}>
          Delete Bot
        </Button>
      </div>
    </div>
  );
}

import { memo, useCallback, useDeferredValue, useEffect, useMemo, useRef, useState } from 'react';
import { Link } from 'react-router-dom';
import { defaultRangeExtractor, useVirtualizer } from '@tanstack/react-virtual';
import { Avatar } from '../../components/ui/Avatar';
import { useServerStore } from '../../stores/serverStore';
import { useChannelStore } from '../../stores/channelStore';
import { botApi, serverApi, runtimeApi, ApiError } from '../../lib/api';
import type { Bot, BotDetail, BotToken, RuntimeAccess } from '../../lib/api';
import type { Channel } from '../../lib/contracts/server';
import { Button } from '../../components/ui/Button';
import { CreateBotModal } from './CreateBotModal';
import { CreateTokenModal } from './CreateTokenModal';
import { CreateAgentInviteModal } from './CreateAgentInviteModal';

export function BotManagement() {
  const instanceServerId = useServerStore(s => s.instanceServerId);
  const [bots, setBots] = useState<Bot[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [permissionDenied, setPermissionDenied] = useState(false);
  const [showCreateBot, setShowCreateBot] = useState(false);
  const [showInvite, setShowInvite] = useState(false);
  const [expandedBotId, setExpandedBotId] = useState<any>(null);
  const [query, setQuery] = useState('');
  const deferredQuery = useDeferredValue(query);

  const fetchBots = useCallback(async (showLoading = true) => {
    if (!instanceServerId) return;
    if (showLoading) setLoading(true);
    setError('');
    try {
      const data = await botApi.list(instanceServerId);
      setBots(data);
      setPermissionDenied(false);
    } catch (err) {
      if (err instanceof ApiError && err.status === 403) {
        setPermissionDenied(true);
      } else {
        setError(err instanceof ApiError ? err.code : 'Failed to load bots');
      }
    } finally {
      setLoading(false);
    }
  }, [instanceServerId]);

  useEffect(() => { fetchBots(); }, [fetchBots]);

  // A refresh after a change keeps the list (and its scroll position) on screen
  const refresh = useCallback(() => { void fetchBots(false); }, [fetchBots]);
  const toggle = useCallback((botId: string) => setExpandedBotId(cur => (cur === botId ? null : botId)), []);

  // Newest first, so a bot you just created is at the top of a long list
  const sorted = useMemo(() => [...bots].sort((a, b) => b.createdAt.localeCompare(a.createdAt)), [bots]);
  const shown = useMemo(() => {
    const q = deferredQuery.trim().toLowerCase();
    return q ? sorted.filter(b => b.username.toLowerCase().includes(q)) : sorted;
  }, [sorted, deferredQuery]);

  if (!instanceServerId) return null;

  if (permissionDenied) {
    return (
      <div>
        <h2 className="text-xl font-bold text-text mb-4">Bot Management</h2>
        <p className="text-text-muted mb-4">You don't have permission to manage bots.</p>
        <Link to="/app" className="hidden min-h-11 items-center text-primary-text hover:underline sm:inline-flex md:min-h-8">Back to chat</Link>
      </div>
    );
  }

  if (loading) {
    return <p className="text-text-muted">Loading bots...</p>;
  }

  return (
    <div>
      <div className="flex flex-wrap items-center justify-between gap-3 mb-6">
        <h2 className="text-xl font-bold text-text">Bot Management</h2>
        <div className="flex gap-2">
          <Button onClick={() => setShowInvite(true)}>Invite Agent</Button>
          <Button variant="secondary" onClick={() => setShowCreateBot(true)}>Create Bot</Button>
        </div>
      </div>

      {error && <p className="text-danger text-sm mb-4">{error}</p>}

      <ChannelLoopGuardSection serverId={instanceServerId} />

      {bots.length === 0 ? (
        <p className="text-text-muted">No bots yet. Create one to get started.</p>
      ) : (
        <section>
          <div className="flex flex-wrap items-center gap-3 mb-2">
            <input
              type="search"
              value={query}
              onChange={e => setQuery(e.target.value)}
              placeholder="Search bots"
              aria-label="Search bots"
              className="min-h-11 md:min-h-9 w-full max-w-xs px-3 py-1.5 rounded border border-border bg-surface text-text placeholder:text-text-muted/70 text-sm"
            />
            <span className="text-text-muted text-xs" aria-live="polite">
              {shown.length === bots.length ? `${bots.length} bots` : `${shown.length} of ${bots.length} bots`}
            </span>
          </div>
          {shown.length === 0 ? (
            <p className="text-text-muted text-sm">No bots match “{deferredQuery.trim()}”.</p>
          ) : (
            <BotList
              bots={shown}
              serverId={instanceServerId}
              expandedBotId={expandedBotId}
              onToggle={toggle}
              onChanged={refresh}
            />
          )}
        </section>
      )}

      <CreateBotModal
        serverId={instanceServerId}
        isOpen={showCreateBot}
        onClose={() => setShowCreateBot(false)}
        onCreated={refresh}
      />
      {showInvite && <CreateAgentInviteModal serverId={instanceServerId} onClose={() => setShowInvite(false)} onCreated={refresh} />}
    </div>
  );
}

// ─── Bot List (virtualized) ───────────────────────────────────────────────

/** Rendering every bot stalled the page at about 1,800 bots (#241): only the rows in view are mounted. */
function BotList({
  bots,
  serverId,
  expandedBotId,
  onToggle,
  onChanged,
}: {
  bots: Bot[];
  serverId: string;
  expandedBotId: string | null;
  onToggle: (botId: string) => void;
  onChanged: () => void;
}) {
  const scrollRef = useRef<HTMLDivElement>(null);
  const expandedIndex = expandedBotId ? bots.findIndex(b => b.id === expandedBotId) : -1;
  // This component is not compiled by the React Compiler; the virtualizer is read during render only
  // eslint-disable-next-line react-hooks/incompatible-library
  const virtualizer = useVirtualizer({
    count: bots.length,
    getScrollElement: () => scrollRef.current,
    estimateSize: () => 60,
    overscan: 8,
    getItemKey: index => bots[index].id,
    // The open bot stays mounted while scrolled away, so its panel (a half-made token, an error) survives
    rangeExtractor: range => {
      const indexes = defaultRangeExtractor(range);
      return expandedIndex < 0 || indexes.includes(expandedIndex) ? indexes : [...indexes, expandedIndex].sort((a, b) => a - b);
    },
  });

  return (
    <div ref={scrollRef} data-testid="bot-list" className="max-h-[70vh] overflow-y-auto overscroll-contain">
      <div className="relative w-full" style={{ height: virtualizer.getTotalSize() }}>
        {virtualizer.getVirtualItems().map(item => {
          const bot = bots[item.index];
          return (
            <div
              key={item.key}
              data-index={item.index}
              ref={virtualizer.measureElement}
              className="absolute left-0 top-0 w-full pb-2"
              style={{ transform: `translateY(${item.start}px)` }}
            >
              <BotRow
                bot={bot}
                serverId={serverId}
                isExpanded={expandedBotId === bot.id}
                onToggle={onToggle}
                onChanged={onChanged}
              />
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ─── Channel Loop Guard Settings ──────────────────────────────────────────

type GuardField = 'maxBotHops' | 'maxThreadBotHops';
type Limits = Record<GuardField, number>;
/** The limit a guard gets when it is switched on with no earlier value to restore. */
const GUARD_DEFAULT: Limits = { maxBotHops: 4, maxThreadBotHops: 4 };

/**
 * Both loop guards per channel (#23): the channel guard (top-level bot messages in a row)
 * and the thread guard (bot replies in a row inside one thread). Each has an on/off switch;
 * off is a limit of 0.
 */
function ChannelLoopGuardSection({ serverId }: { serverId: string }) {
  const [channels, setChannels] = useState<Channel[]>([]);
  // Limits as loaded or last confirmed by a save here
  const [loaded, setLoaded] = useState<Record<string, Limits>>({});
  // Edits not yet confirmed by the server, by `${channelId}:${field}`
  const [dirty, setDirty] = useState<Record<string, number>>({});
  const [saving, setSaving] = useState<Record<string, boolean>>({});
  const [error, setError] = useState('');
  // A change made elsewhere (a notice's Raise limit or Turn off) arrives as ChannelBotConfig
  const live = useChannelStore(s => s.channels);
  const pending = useRef<Record<string, { timer: ReturnType<typeof setTimeout>; value: number }>>({});
  // Saves of one field go out one at a time, in order, so the last change made wins
  const queues = useRef<Record<string, Promise<void>>>({});
  // The last limit above 0, restored when a guard is switched back on
  const lastOn = useRef<Record<string, number>>({});
  const mounted = useRef(true);

  useEffect(() => {
    serverApi.getChannels(serverId).then((chs) => {
      const textChannels = chs.filter(c => c.channelType === 3);
      setChannels(textChannels);
      const initial: Record<string, Limits> = {};
      for (const ch of textChannels) {
        initial[ch.id] = { maxBotHops: ch.maxBotHops ?? 4, maxThreadBotHops: ch.maxThreadBotHops ?? 0 };
      }
      setLoaded(initial);
    }).catch(() => setError('Failed to load channels'));
  }, [serverId]);

  // enqueue only touches refs and state setters, so the first render's copy stays valid for the unmount flush
  const enqueueOnLeave = useRef(enqueue);

  // Leaving the page sends a change still waiting out its debounce instead of dropping it,
  // behind any save of that field still in flight so the older one cannot land last
  useEffect(() => {
    mounted.current = true;
    const waiting = pending.current;
    const flush = enqueueOnLeave.current;
    return () => {
      mounted.current = false;
      for (const [key, p] of Object.entries(waiting)) {
        clearTimeout(p.timer);
        delete waiting[key];
        const [channelId, field] = key.split(':') as [string, GuardField];
        flush(channelId, field, p.value);
      }
    };
  }, []);

  const shown = (channelId: string, field: GuardField): number => {
    const key = `${channelId}:${field}`;
    return dirty[key] ?? live.get(channelId)?.[field] ?? loaded[channelId]?.[field] ?? GUARD_DEFAULT[field];
  };

  function change(channelId: string, field: GuardField, value: number, delay: number) {
    const key = `${channelId}:${field}`;
    const prev = shown(channelId, field);
    if (prev > 0) lastOn.current[key] = prev;
    setDirty(d => ({ ...d, [key]: value }));
    if (pending.current[key]) clearTimeout(pending.current[key].timer);
    const timer = setTimeout(() => {
      delete pending.current[key];
      enqueue(channelId, field, value);
    }, delay);
    pending.current[key] = { timer, value };
  }

  /** Queues a save behind any earlier save of the same field (save never rejects). */
  function enqueue(channelId: string, field: GuardField, value: number) {
    const key = `${channelId}:${field}`;
    queues.current[key] = (queues.current[key] ?? Promise.resolve()).then(() => save(channelId, field, value));
  }

  function handleNumber(channelId: string, field: GuardField, raw: string) {
    const num = parseInt(raw, 10);
    // 0 would be "off": that is the switch's job, so the box keeps a limit while typing
    if (isNaN(num) || num < 1 || num > 1000) return;
    change(channelId, field, num, 600);
  }

  function handleToggle(channelId: string, field: GuardField, on: boolean) {
    const restore = lastOn.current[`${channelId}:${field}`] ?? GUARD_DEFAULT[field];
    change(channelId, field, on ? restore : 0, 0);
  }

  async function save(channelId: string, field: GuardField, value: number) {
    const key = `${channelId}:${field}`;
    if (mounted.current) { setSaving(s => ({ ...s, [key]: true })); setError(''); }
    // Only the latest edit clears the dirty value; an older save finishing must not
    const settle = (d: Record<string, number>) => {
      if (d[key] !== value || pending.current[key]) return d;
      const next = { ...d };
      delete next[key];
      return next;
    };
    try {
      const config = await botApi.updateChannelBotConfig(channelId, { [field]: value });
      useChannelStore.getState().patchChannel(channelId, { maxBotHops: config.maxBotHops, maxThreadBotHops: config.maxThreadBotHops });
      if (!mounted.current) return;
      setLoaded(l => ({ ...l, [channelId]: { maxBotHops: config.maxBotHops, maxThreadBotHops: config.maxThreadBotHops } }));
      setDirty(settle);
    } catch (err) {
      if (!mounted.current) return;
      // Show what the server still has, not the value that failed
      setDirty(settle);
      setError(err instanceof ApiError ? err.code : 'Failed to save');
    } finally {
      if (mounted.current) setSaving(s => ({ ...s, [key]: false }));
    }
  }

  if (channels.length === 0) return null;

  const guard = (ch: Channel, field: GuardField, label: string, unit: string) => {
    const value = shown(ch.id, field);
    const on = value > 0;
    const key = `${ch.id}:${field}`;
    return (
      <div className="flex items-center gap-2">
        <label className="min-h-11 md:min-h-8 flex items-center gap-1.5 text-xs text-text-muted cursor-pointer">
          <input
            type="checkbox"
            role="switch"
            checked={on}
            onChange={e => handleToggle(ch.id, field, e.target.checked)}
            aria-label={`${label} loop guard in #${ch.name}`}
            className="accent-primary"
          />
          {label}
        </label>
        {on ? (
          <input
            type="number"
            min={1}
            max={1000}
            value={value}
            onChange={e => handleNumber(ch.id, field, e.target.value)}
            aria-label={`${label} limit in #${ch.name} (${unit})`}
            title={`Pause after this many ${unit} in a row`}
            className="min-h-11 md:min-h-8 w-16 px-2 py-1 rounded border border-border bg-surface text-text text-sm text-right"
          />
        ) : (
          <span className="w-16 text-text-muted text-xs">Off</span>
        )}
        <span className="w-12 text-text-muted text-xs" aria-live="polite">{saving[key] ? 'Saving…' : ''}</span>
      </div>
    );
  };

  return (
    <section className="mb-6">
      <h3 className="text-sm font-semibold text-text mb-2">Loop Guard</h3>
      <p className="text-text-muted text-xs mb-3">
        Pauses agents after this many bot posts in a row with no human message. The channel guard counts top-level
        messages; the thread guard counts replies inside each thread. A human message resets both, and the notice
        it posts has Continue, Raise limit and Turn off buttons.
      </p>
      {error && <p className="text-danger text-xs mb-2" role="alert">{error}</p>}
      <div className="flex flex-col gap-1">
        {channels.map((ch) => (
          <div key={ch.id} className="flex flex-wrap items-center gap-x-6 gap-y-1 px-2 py-1.5 rounded hover:bg-surface-hover">
            <span className="flex min-w-32 flex-1 items-center gap-1 text-sm">
              <span className="text-text-muted">#</span>
              <span className="text-text">{ch.name}</span>
            </span>
            {guard(ch, 'maxBotHops', 'Channel', 'bot messages')}
            {guard(ch, 'maxThreadBotHops', 'Threads', 'bot replies in one thread')}
          </div>
        ))}
      </div>
    </section>
  );
}

// ─── Bot Row (expandable) ─────────────────────────────────────────────────

// Memoized with stable callbacks: opening one bot re-renders that row, not the whole list
const BotRow = memo(function BotRow({
  bot,
  serverId,
  isExpanded,
  onToggle,
  onChanged,
}: {
  bot: Bot;
  serverId: string;
  isExpanded: boolean;
  onToggle: (botId: string) => void;
  onChanged: () => void;
}) {
  const [pausing, setPausing] = useState(false);
  const [pauseError, setPauseError] = useState('');
  const [savingAccess, setSavingAccess] = useState(false);
  const isPaused = !!bot.pausedAt;

  async function changeAccess(access: RuntimeAccess) {
    if (access === 'auto' && !confirm(`Let ${bot.username} run code without approval? Runs still execute in the sandbox with its limits.`)) return;
    setSavingAccess(true);
    setPauseError('');
    try {
      await runtimeApi.setBotAccess(serverId, bot.id, access);
      onChanged();
    } catch (err) {
      setPauseError(err instanceof ApiError ? err.code : 'Failed to update code run access');
    } finally {
      setSavingAccess(false);
    }
  }

  async function togglePause() {
    setPausing(true);
    setPauseError('');
    try {
      if (isPaused) {
        await botApi.setPaused(serverId, bot.id, false);
      } else {
        const reason = prompt('Pause this bot? It will be read-only until resumed.\n\nReason (optional):');
        if (reason === null) return;
        await botApi.setPaused(serverId, bot.id, true, reason.trim() || undefined);
      }
      onChanged();
    } catch (err) {
      setPauseError(err instanceof ApiError ? err.code : 'Failed to update pause state');
    } finally {
      setPausing(false);
    }
  }

  return (
    <div className="border border-border rounded-lg overflow-hidden">
      <div className="flex items-center hover:bg-surface-hover">
      <button
        onClick={() => onToggle(bot.id)}
        aria-expanded={isExpanded}
        className="min-h-11 flex-1 flex items-center justify-between px-4 py-3 text-left"
      >
        <div>
          <span className="text-text font-medium">{bot.username}</span>
          {isPaused && (
            <span
              className="ml-2 inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-semibold leading-none bg-warn/20 text-warn"
              title={bot.pausedReason ? `Paused: ${bot.pausedReason}` : 'Paused'}
            >
              PAUSED
            </span>
          )}
          <span className="text-text-muted text-xs ml-2">
            {new Date(bot.createdAt).toLocaleDateString()}
          </span>
          {pauseError && <span className="text-danger text-xs ml-2">{pauseError}</span>}
        </div>
        <svg
          className="h-4 w-4 text-text-muted transition-transform"
          style={{ transform: isExpanded ? 'rotate(180deg)' : 'rotate(0deg)' }}
          fill="none"
          viewBox="0 0 24 24"
          stroke="currentColor"
          strokeWidth="2"
        >
          <polyline points="6 9 12 15 18 9" />
        </svg>
      </button>
      <label className="flex items-center gap-1 pr-3 text-xs text-text-muted" title="Whether this bot may run code in the sandbox">
        Code runs
        <select
          className="min-h-11 md:min-h-8 bg-surface border border-border rounded px-2 py-1 text-xs text-text"
          value={bot.runtimeAccess ?? 'none'}
          disabled={savingAccess}
          onChange={e => changeAccess(e.target.value as RuntimeAccess)}
          aria-label={`Code run access for ${bot.username}`}
        >
          <option value="none">Off</option>
          <option value="approval">Need approval</option>
          <option value="auto">Auto-run</option>
        </select>
      </label>
      <div className="pr-3">
        <Button variant="secondary" onClick={togglePause} loading={pausing}>
          {isPaused ? 'Resume' : 'Pause'}
        </Button>
      </div>
      </div>
      {isExpanded && (
        <BotDetailPanel botId={bot.id} serverId={serverId} onDeleted={onChanged} />
      )}
    </div>
  );
});

// ─── Bot Detail Panel ─────────────────────────────────────────────────────

function BotDetailPanel({
  botId,
  serverId,
  onDeleted,
}: {
  botId: string;
  serverId: string;
  onDeleted: () => void;
}) {
  const [detail, setDetail] = useState<BotDetail | null>(null);
  const [allChannels, setAllChannels] = useState<Channel[]>([]);
  const [tokens, setTokens] = useState<BotToken[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [showCreateToken, setShowCreateToken] = useState(false);
  const [showInvite, setShowInvite] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [channelLoading, setChannelLoading] = useState<string | null>(null);
  const [avatarInput, setAvatarInput] = useState('');
  const [avatarSaving, setAvatarSaving] = useState(false);
  const [avatarError, setAvatarError] = useState('');

  const fetchDetail = useCallback(async () => {
    try {
      const [d, channels] = await Promise.all([
        botApi.get(serverId, botId),
        serverApi.getChannels(serverId),
      ]);
      setDetail(d);
      setAvatarInput(d.avatarUrl || '');
      // Only show text channels (type 3) for bot access
      setAllChannels(channels.filter(c => c.channelType === 3));
      if (d.canManageTokens) {
        const t = await botApi.listTokens(serverId, botId);
        setTokens(t);
      }
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to load bot details');
    } finally {
      setLoading(false);
    }
  }, [serverId, botId]);

  useEffect(() => { fetchDetail(); }, [fetchDetail]);

  async function handleDelete() {
    if (!confirm('Delete this bot? This cannot be undone.')) return;
    setDeleting(true);
    try {
      await botApi.remove(serverId, botId);
      onDeleted();
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to delete bot');
      setDeleting(false);
    }
  }

  async function handleRevokeToken(tokenId: string) {
    try {
      await botApi.revokeToken(serverId, botId, tokenId);
      setTokens(prev => prev.map(t => t.id === tokenId ? { ...t, revokedAt: new Date().toISOString() } : t));
    } catch (err) {
      if (err instanceof ApiError && err.status === 403) {
        // Permissions changed — refetch detail
        fetchDetail();
      }
      setError(err instanceof ApiError ? err.code : 'Failed to revoke token');
    }
  }

  async function handleClearBinding(tokenId: string) {
    try {
      await botApi.clearTokenBinding(serverId, botId, tokenId);
      setTokens(prev => prev.map(t => t.id === tokenId ? { ...t, boundClient: null, boundAt: null, lastRefused: null } : t));
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to clear the binding');
    }
  }

  async function toggleDirect(channelId: string, canDirect: boolean) {
    setChannelLoading(channelId);
    setError('');
    try {
      await botApi.setCanDirect(channelId, botId, !canDirect);
      setDetail(await botApi.get(serverId, botId));
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to update who may direct');
    } finally {
      setChannelLoading(null);
    }
  }

  async function toggleChannel(channelId: string, hasAccess: boolean) {
    setChannelLoading(channelId);
    try {
      if (hasAccess) {
        await botApi.revokeChannel(channelId, botId);
      } else {
        await botApi.grantChannel(channelId, botId);
      }
      // Refetch detail to get updated channel list
      const d = await botApi.get(serverId, botId);
      setDetail(d);
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to update channel access');
    } finally {
      setChannelLoading(null);
    }
  }

  if (loading) {
    return <div className="px-4 py-3 border-t border-border text-text-muted text-sm">Loading...</div>;
  }

  if (error && !detail) {
    return <div className="px-4 py-3 border-t border-border text-danger text-sm">{error}</div>;
  }

  if (!detail) return null;

  const botChannelIds = new Set(detail.channels.map(c => c.id));
  const directChannelIds = new Set(detail.channels.filter(c => c.canDirect).map(c => c.id));
  const activeTokens = tokens.filter(t => !t.revokedAt);
  const revokedTokens = tokens.filter(t => t.revokedAt);

  return (
    <div className="border-t border-border px-4 py-4 flex flex-col gap-5 bg-bg/50">
      {error && <p className="text-danger text-sm">{error}</p>}

      {/* ── Avatar ── */}
      <section>
        <h4 className="text-sm font-semibold text-text mb-2">Avatar</h4>
        <div className="flex items-start gap-3">
          <Avatar userId={botId} username={detail.username} avatarUrl={detail.avatarUrl} className="h-12 w-12 text-sm" />
          <div className="flex-1 min-w-0">
            <input
              type="text"
              value={avatarInput}
              onChange={(e) => { setAvatarInput(e.target.value); setAvatarError(''); }}
              placeholder="data:image/svg+xml;base64,..."
              className="min-h-11 md:min-h-9 w-full px-3 py-1.5 rounded border border-border bg-surface text-text placeholder:text-text-muted/70 text-sm"
            />
            {avatarError && <p className="text-danger text-xs mt-1">{avatarError}</p>}
            <div className="flex gap-2 mt-2">
              <Button
                variant="secondary"
                className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
                loading={avatarSaving}
                onClick={async () => {
                  setAvatarSaving(true);
                  setAvatarError('');
                  try {
                    const res = await botApi.update(serverId, botId, { avatarUrl: avatarInput || null });
                    setDetail(prev => prev ? { ...prev, avatarUrl: res.avatarUrl } : prev);
                  } catch (err) {
                    setAvatarError(err instanceof ApiError ? err.code : 'Failed to save avatar');
                  } finally {
                    setAvatarSaving(false);
                  }
                }}
              >
                Save Avatar
              </Button>
              {detail.avatarUrl && (
                <Button
                  variant="secondary"
                  className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
                  onClick={async () => {
                    setAvatarSaving(true);
                    setAvatarError('');
                    try {
                      const res = await botApi.update(serverId, botId, { avatarUrl: null });
                      setDetail(prev => prev ? { ...prev, avatarUrl: res.avatarUrl } : prev);
                      setAvatarInput('');
                    } catch (err) {
                      setAvatarError(err instanceof ApiError ? err.code : 'Failed to remove avatar');
                    } finally {
                      setAvatarSaving(false);
                    }
                  }}
                >
                  Remove
                </Button>
              )}
            </div>
          </div>
        </div>
      </section>

      {/* ── Channel Access ── */}
      <section>
        <h4 className="text-sm font-semibold text-text mb-2">Channel Access</h4>
        {allChannels.length === 0 ? (
          <p className="text-text-muted text-xs">No text channels found.</p>
        ) : (
          <div className="flex flex-col gap-1">
            {allChannels.map((ch) => {
              const hasAccess = botChannelIds.has(ch.id);
              const isLoading = channelLoading === ch.id;
              return (
                <label
                  key={ch.id}
                  className="min-h-11 md:min-h-9 flex items-center gap-2 px-2 py-1.5 rounded hover:bg-surface-hover cursor-pointer text-sm"
                >
                  <input
                    type="checkbox"
                    checked={hasAccess}
                    disabled={isLoading}
                    onChange={() => toggleChannel(ch.id, hasAccess)}
                    className="accent-primary"
                  />
                  <span className="text-text-muted">#</span>
                  <span className="text-text">{ch.name}</span>
                  {isLoading && <span className="text-text-muted text-xs ml-auto">...</span>}
                  {hasAccess && (
                    <span
                      className="ml-auto flex items-center gap-1 text-xs text-text-muted"
                      title="Lets this bot give other agents instructions in this channel. Only the server owner can change it."
                      onClick={(e) => e.stopPropagation()}
                    >
                      <input
                        type="checkbox"
                        checked={directChannelIds.has(ch.id)}
                        disabled={isLoading}
                        onChange={() => toggleDirect(ch.id, directChannelIds.has(ch.id))}
                        className="accent-primary"
                      />
                      can direct agents
                    </span>
                  )}
                </label>
              );
            })}
          </div>
        )}
      </section>

      {/* ── Tokens (owner / admin only) ── */}
      {detail.canManageTokens && (
        <section>
          <Button onClick={() => setShowInvite(true)}>Invite Agent</Button>
          {showInvite && <CreateAgentInviteModal serverId={serverId} botId={botId} onClose={() => setShowInvite(false)} onCreated={() => {}} />}
          <div className="flex items-center justify-between mb-2">
            <h4 className="text-sm font-semibold text-text">Tokens</h4>
            <Button
              variant="secondary"
              className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
              onClick={() => setShowCreateToken(true)}
            >
              New Token
            </Button>
          </div>
          {activeTokens.length === 0 && revokedTokens.length === 0 ? (
            <p className="text-text-muted text-xs">No tokens yet.</p>
          ) : (
            <div className="flex flex-col gap-1">
              {activeTokens.map((t) => (
                <div key={t.id} className="flex items-center justify-between px-2 py-1.5 rounded bg-surface text-sm">
                  <div>
                    <span className="text-text">{t.name || 'Unnamed'}</span>
                    <span className="text-text-muted text-xs ml-2">
                      Created {new Date(t.createdAt).toLocaleDateString()}
                    </span>
                    {t.lastUsedAt && (
                      <span className="text-text-muted text-xs ml-2">
                        Last used {new Date(t.lastUsedAt).toLocaleDateString()}
                        {t.lastUsedClient ? ` by ${t.lastUsedClient}` : ''}
                        {t.lastUsedIp ? ` from ${t.lastUsedIp}` : ''}
                      </span>
                    )}
                    {t.boundClient && (
                      <span className="text-text-muted text-xs ml-2" title="Requests from any other client are refused">
                        Bound to {t.boundClient}
                      </span>
                    )}
                    {t.lastRefused && (
                      <span className="block text-danger text-xs">
                        Refused {t.lastRefused.client ? `use by ${t.lastRefused.client}` : 'a use with no client name'}
                        {t.lastRefused.ip ? ` from ${t.lastRefused.ip}` : ''} on {new Date(t.lastRefused.at).toLocaleString()}.
                        If that wasn't you moving this agent, revoke the token.
                      </span>
                    )}
                  </div>
                  <div className="flex shrink-0">
                    {t.boundClient && (
                      <button
                        onClick={() => handleClearBinding(t.id)}
                        className="min-h-11 md:min-h-8 px-2 text-text-muted text-xs hover:underline"
                        title="The next client that uses the token binds it again"
                      >
                        Clear binding
                      </button>
                    )}
                    <button
                      onClick={() => handleRevokeToken(t.id)}
                      className="min-h-11 md:min-h-8 px-2 text-danger text-xs hover:underline"
                    >
                      Revoke
                    </button>
                  </div>
                </div>
              ))}
              {revokedTokens.map((t) => (
                <div key={t.id} className="flex items-center px-2 py-1.5 rounded bg-surface text-sm opacity-50">
                  <span className="text-text line-through">{t.name || 'Unnamed'}</span>
                  <span className="text-text-muted text-xs ml-2">Revoked</span>
                </div>
              ))}
            </div>
          )}

          <CreateTokenModal
            serverId={serverId}
            botId={botId}
            isOpen={showCreateToken}
            onClose={() => setShowCreateToken(false)}
            onCreated={async () => {
              const t = await botApi.listTokens(serverId, botId);
              setTokens(t);
            }}
          />
        </section>
      )}

      {/* ── Delete Bot ── */}
      <div className="pt-2 border-t border-border">
        <Button variant="danger" onClick={handleDelete} loading={deleting}>
          Delete Bot
        </Button>
      </div>
    </div>
  );
}

import { memo, useCallback, useDeferredValue, useEffect, useMemo, useRef, useState } from 'react';
import { Link } from 'react-router-dom';
import { defaultRangeExtractor, useVirtualizer } from '@tanstack/react-virtual';
import { Avatar } from '../../components/ui/Avatar';
import { useServerStore } from '../../stores/serverStore';
import { useChannelStore } from '../../stores/channelStore';
import { botApi, serverApi, runtimeApi, ApiError } from '../../lib/api';
import type { Bot, BotDetail, BotToken, RuntimeAccess } from '../../lib/api';
import type { Channel } from '../../lib/contracts/server';
import { Button } from '../../components/ui/Button';
import { CreateBotModal } from './CreateBotModal';
import { CreateTokenModal } from './CreateTokenModal';
import { CreateAgentInviteModal } from './CreateAgentInviteModal';

export function BotManagement() {
  const instanceServerId = useServerStore(s => s.instanceServerId);
  const [bots, setBots] = useState<Bot[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [permissionDenied, setPermissionDenied] = useState(false);
  const [showCreateBot, setShowCreateBot] = useState(false);
  const [showInvite, setShowInvite] = useState(false);
  const [expandedBotId, setExpandedBotId] = useState<string | null>(null);
  const [query, setQuery] = useState('');
  const deferredQuery = useDeferredValue(query);

  const fetchBots = useCallback(async (showLoading = true) => {
    if (!instanceServerId) return;
    if (showLoading) setLoading(true);
    setError('');
    try {
      const data = await botApi.list(instanceServerId);
      setBots(data);
      setPermissionDenied(false);
    } catch (err: any) {
      if (err instanceof ApiError && err.status === 403) {
        setPermissionDenied(true);
      } else {
        setError(err instanceof ApiError ? err.code : 'Failed to load bots');
      }
    } finally {
      setLoading(false);
    }
  }, [instanceServerId]);

  useEffect(() => { fetchBots(); }, [fetchBots]);

  // A refresh after a change keeps the list (and its scroll position) on screen
  const refresh = useCallback(() => { void fetchBots(false); }, [fetchBots]);
  const toggle = useCallback((botId: string) => setExpandedBotId(cur => (cur === botId ? null : botId)), []);

  // Newest first, so a bot you just created is at the top of a long list
  const sorted = useMemo(() => [...bots].sort((a, b) => b.createdAt.localeCompare(a.createdAt)), [bots]);
  const shown = useMemo(() => {
    const q = deferredQuery.trim().toLowerCase();
    return q ? sorted.filter(b => b.username.toLowerCase().includes(q)) : sorted;
  }, [sorted, deferredQuery]);

  if (!instanceServerId) return null;

  if (permissionDenied) {
    return (
      <div>
        <h2 className="text-xl font-bold text-text mb-4">Bot Management</h2>
        <p className="text-text-muted mb-4">You don't have permission to manage bots.</p>
        <Link to="/app" className="hidden min-h-11 items-center text-primary-text hover:underline sm:inline-flex md:min-h-8">Back to chat</Link>
      </div>
    );
  }

  if (loading) {
    return <p className="text-text-muted">Loading bots...</p>;
  }

  return (
    <div>
      <div className="flex flex-wrap items-center justify-between gap-3 mb-6">
        <h2 className="text-xl font-bold text-text">Bot Management</h2>
        <div className="flex gap-2">
          <Button onClick={() => setShowInvite(true)}>Invite Agent</Button>
          <Button variant="secondary" onClick={() => setShowCreateBot(true)}>Create Bot</Button>
        </div>
      </div>

      {error && <p className="text-danger text-sm mb-4">{error}</p>}

      <ChannelLoopGuardSection serverId={instanceServerId} />

      {bots.length === 0 ? (
        <p className="text-text-muted">No bots yet. Create one to get started.</p>
      ) : (
        <section>
          <div className="flex flex-wrap items-center gap-3 mb-2">
            <input
              type="search"
              value={query}
              onChange={e => setQuery(e.target.value)}
              placeholder="Search bots"
              aria-label="Search bots"
              className="min-h-11 md:min-h-9 w-full max-w-xs px-3 py-1.5 rounded border border-border bg-surface text-text placeholder:text-text-muted/70 text-sm"
            />
            <span className="text-text-muted text-xs" aria-live="polite">
              {shown.length === bots.length ? `${bots.length} bots` : `${shown.length} of ${bots.length} bots`}
            </span>
          </div>
          {shown.length === 0 ? (
            <p className="text-text-muted text-sm">No bots match “{deferredQuery.trim()}”.</p>
          ) : (
            <BotList
              bots={shown}
              serverId={instanceServerId}
              expandedBotId={expandedBotId}
              onToggle={toggle}
              onChanged={refresh}
            />
          )}
        </section>
      )}

      <CreateBotModal
        serverId={instanceServerId}
        isOpen={showCreateBot}
        onClose={() => setShowCreateBot(false)}
        onCreated={refresh}
      />
      {showInvite && <CreateAgentInviteModal serverId={instanceServerId} onClose={() => setShowInvite(false)} onCreated={refresh} />}
    </div>
  );
}

// ─── Bot List (virtualized) ───────────────────────────────────────────────

/** Rendering every bot stalled the page at about 1,800 bots (#241): only the rows in view are mounted. */
function BotList({
  bots,
  serverId,
  expandedBotId,
  onToggle,
  onChanged,
}: {
  bots: Bot[];
  serverId: string;
  expandedBotId: string | null;
  onToggle: (botId: string) => void;
  onChanged: () => void;
}) {
  const scrollRef = useRef<HTMLDivElement>(null);
  const expandedIndex = expandedBotId ? bots.findIndex(b => b.id === expandedBotId) : -1;
  // This component is not compiled by the React Compiler; the virtualizer is read during render only
  // eslint-disable-next-line react-hooks/incompatible-library
  const virtualizer = useVirtualizer({
    count: bots.length,
    getScrollElement: () => scrollRef.current,
    estimateSize: () => 60,
    overscan: 8,
    getItemKey: index => bots[index].id,
    // The open bot stays mounted while scrolled away, so its panel (a half-made token, an error) survives
    rangeExtractor: range => {
      const indexes = defaultRangeExtractor(range);
      return expandedIndex < 0 || indexes.includes(expandedIndex) ? indexes : [...indexes, expandedIndex].sort((a, b) => a - b);
    },
  });

  return (
    <div ref={scrollRef} data-testid="bot-list" className="max-h-[70vh] overflow-y-auto overscroll-contain">
      <div className="relative w-full" style={{ height: virtualizer.getTotalSize() }}>
        {virtualizer.getVirtualItems().map(item => {
          const bot = bots[item.index];
          return (
            <div
              key={item.key}
              data-index={item.index}
              ref={virtualizer.measureElement}
              className="absolute left-0 top-0 w-full pb-2"
              style={{ transform: `translateY(${item.start}px)` }}
            >
              <BotRow
                bot={bot}
                serverId={serverId}
                isExpanded={expandedBotId === bot.id}
                onToggle={onToggle}
                onChanged={onChanged}
              />
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ─── Channel Loop Guard Settings ──────────────────────────────────────────

type GuardField = 'maxBotHops' | 'maxThreadBotHops';
type Limits = Record<GuardField, number>;
/** The limit a guard gets when it is switched on with no earlier value to restore. */
const GUARD_DEFAULT: Limits = { maxBotHops: 4, maxThreadBotHops: 4 };

/**
 * Both loop guards per channel (#23): the channel guard (top-level bot messages in a row)
 * and the thread guard (bot replies in a row inside one thread). Each has an on/off switch;
 * off is a limit of 0.
 */
function ChannelLoopGuardSection({ serverId }: { serverId: string }) {
  const [channels, setChannels] = useState<Channel[]>([]);
  // Limits as loaded or last confirmed by a save here
  const [loaded, setLoaded] = useState<Record<string, Limits>>({});
  // Edits not yet confirmed by the server, by `${channelId}:${field}`
  const [dirty, setDirty] = useState<Record<string, number>>({});
  const [saving, setSaving] = useState<Record<string, boolean>>({});
  const [error, setError] = useState('');
  // A change made elsewhere (a notice's Raise limit or Turn off) arrives as ChannelBotConfig
  const live = useChannelStore(s => s.channels);
  const pending = useRef<Record<string, { timer: ReturnType<typeof setTimeout>; value: number }>>({});
  // Saves of one field go out one at a time, in order, so the last change made wins
  const queues = useRef<Record<string, Promise<void>>>({});
  // The last limit above 0, restored when a guard is switched back on
  const lastOn = useRef<Record<string, number>>({});
  const mounted = useRef(true);

  useEffect(() => {
    serverApi.getChannels(serverId).then((chs) => {
      const textChannels = chs.filter(c => c.channelType === 3);
      setChannels(textChannels);
      const initial: Record<string, Limits> = {};
      for (const ch of textChannels) {
        initial[ch.id] = { maxBotHops: ch.maxBotHops ?? 4, maxThreadBotHops: ch.maxThreadBotHops ?? 0 };
      }
      setLoaded(initial);
    }).catch(() => setError('Failed to load channels'));
  }, [serverId]);

  // enqueue only touches refs and state setters, so the first render's copy stays valid for the unmount flush
  const enqueueOnLeave = useRef(enqueue);

  // Leaving the page sends a change still waiting out its debounce instead of dropping it,
  // behind any save of that field still in flight so the older one cannot land last
  useEffect(() => {
    mounted.current = true;
    const waiting = pending.current;
    const flush = enqueueOnLeave.current;
    return () => {
      mounted.current = false;
      for (const [key, p] of Object.entries(waiting)) {
        clearTimeout(p.timer);
        delete waiting[key];
        const [channelId, field] = key.split(':') as [string, GuardField];
        flush(channelId, field, p.value);
      }
    };
  }, []);

  const shown = (channelId: string, field: GuardField): number => {
    const key = `${channelId}:${field}`;
    return dirty[key] ?? live.get(channelId)?.[field] ?? loaded[channelId]?.[field] ?? GUARD_DEFAULT[field];
  };

  function change(channelId: string, field: GuardField, value: number, delay: number) {
    const key = `${channelId}:${field}`;
    const prev = shown(channelId, field);
    if (prev > 0) lastOn.current[key] = prev;
    setDirty(d => ({ ...d, [key]: value }));
    if (pending.current[key]) clearTimeout(pending.current[key].timer);
    const timer = setTimeout(() => {
      delete pending.current[key];
      enqueue(channelId, field, value);
    }, delay);
    pending.current[key] = { timer, value };
  }

  /** Queues a save behind any earlier save of the same field (save never rejects). */
  function enqueue(channelId: string, field: GuardField, value: number) {
    const key = `${channelId}:${field}`;
    queues.current[key] = (queues.current[key] ?? Promise.resolve()).then(() => save(channelId, field, value));
  }

  function handleNumber(channelId: string, field: GuardField, raw: string) {
    const num = parseInt(raw, 10);
    // 0 would be "off": that is the switch's job, so the box keeps a limit while typing
    if (isNaN(num) || num < 1 || num > 1000) return;
    change(channelId, field, num, 600);
  }

  function handleToggle(channelId: string, field: GuardField, on: boolean) {
    const restore = lastOn.current[`${channelId}:${field}`] ?? GUARD_DEFAULT[field];
    change(channelId, field, on ? restore : 0, 0);
  }

  async function save(channelId: string, field: GuardField, value: number) {
    const key = `${channelId}:${field}`;
    if (mounted.current) { setSaving(s => ({ ...s, [key]: true })); setError(''); }
    // Only the latest edit clears the dirty value; an older save finishing must not
    const settle = (d: Record<string, number>) => {
      if (d[key] !== value || pending.current[key]) return d;
      const next = { ...d };
      delete next[key];
      return next;
    };
    try {
      const config = await botApi.updateChannelBotConfig(channelId, { [field]: value });
      useChannelStore.getState().patchChannel(channelId, { maxBotHops: config.maxBotHops, maxThreadBotHops: config.maxThreadBotHops });
      if (!mounted.current) return;
      setLoaded(l => ({ ...l, [channelId]: { maxBotHops: config.maxBotHops, maxThreadBotHops: config.maxThreadBotHops } }));
      setDirty(settle);
    } catch (err) {
      if (!mounted.current) return;
      // Show what the server still has, not the value that failed
      setDirty(settle);
      setError(err instanceof ApiError ? err.code : 'Failed to save');
    } finally {
      if (mounted.current) setSaving(s => ({ ...s, [key]: false }));
    }
  }

  if (channels.length === 0) return null;

  const guard = (ch: Channel, field: GuardField, label: string, unit: string) => {
    const value = shown(ch.id, field);
    const on = value > 0;
    const key = `${ch.id}:${field}`;
    return (
      <div className="flex items-center gap-2">
        <label className="min-h-11 md:min-h-8 flex items-center gap-1.5 text-xs text-text-muted cursor-pointer">
          <input
            type="checkbox"
            role="switch"
            checked={on}
            onChange={e => handleToggle(ch.id, field, e.target.checked)}
            aria-label={`${label} loop guard in #${ch.name}`}
            className="accent-primary"
          />
          {label}
        </label>
        {on ? (
          <input
            type="number"
            min={1}
            max={1000}
            value={value}
            onChange={e => handleNumber(ch.id, field, e.target.value)}
            aria-label={`${label} limit in #${ch.name} (${unit})`}
            title={`Pause after this many ${unit} in a row`}
            className="min-h-11 md:min-h-8 w-16 px-2 py-1 rounded border border-border bg-surface text-text text-sm text-right"
          />
        ) : (
          <span className="w-16 text-text-muted text-xs">Off</span>
        )}
        <span className="w-12 text-text-muted text-xs" aria-live="polite">{saving[key] ? 'Saving…' : ''}</span>
      </div>
    );
  };

  return (
    <section className="mb-6">
      <h3 className="text-sm font-semibold text-text mb-2">Loop Guard</h3>
      <p className="text-text-muted text-xs mb-3">
        Pauses agents after this many bot posts in a row with no human message. The channel guard counts top-level
        messages; the thread guard counts replies inside each thread. A human message resets both, and the notice
        it posts has Continue, Raise limit and Turn off buttons.
      </p>
      {error && <p className="text-danger text-xs mb-2" role="alert">{error}</p>}
      <div className="flex flex-col gap-1">
        {channels.map((ch) => (
          <div key={ch.id} className="flex flex-wrap items-center gap-x-6 gap-y-1 px-2 py-1.5 rounded hover:bg-surface-hover">
            <span className="flex min-w-32 flex-1 items-center gap-1 text-sm">
              <span className="text-text-muted">#</span>
              <span className="text-text">{ch.name}</span>
            </span>
            {guard(ch, 'maxBotHops', 'Channel', 'bot messages')}
            {guard(ch, 'maxThreadBotHops', 'Threads', 'bot replies in one thread')}
          </div>
        ))}
      </div>
    </section>
  );
}

// ─── Bot Row (expandable) ─────────────────────────────────────────────────

// Memoized with stable callbacks: opening one bot re-renders that row, not the whole list
const BotRow = memo(function BotRow({
  bot,
  serverId,
  isExpanded,
  onToggle,
  onChanged,
}: {
  bot: Bot;
  serverId: string;
  isExpanded: boolean;
  onToggle: (botId: string) => void;
  onChanged: () => void;
}) {
  const [pausing, setPausing] = useState(false);
  const [pauseError, setPauseError] = useState('');
  const [savingAccess, setSavingAccess] = useState(false);
  const isPaused = !!bot.pausedAt;

  async function changeAccess(access: RuntimeAccess) {
    if (access === 'auto' && !confirm(`Let ${bot.username} run code without approval? Runs still execute in the sandbox with its limits.`)) return;
    setSavingAccess(true);
    setPauseError('');
    try {
      await runtimeApi.setBotAccess(serverId, bot.id, access);
      onChanged();
    } catch (err) {
      setPauseError(err instanceof ApiError ? err.code : 'Failed to update code run access');
    } finally {
      setSavingAccess(false);
    }
  }

  async function togglePause() {
    setPausing(true);
    setPauseError('');
    try {
      if (isPaused) {
        await botApi.setPaused(serverId, bot.id, false);
      } else {
        const reason = prompt('Pause this bot? It will be read-only until resumed.\n\nReason (optional):');
        if (reason === null) return;
        await botApi.setPaused(serverId, bot.id, true, reason.trim() || undefined);
      }
      onChanged();
    } catch (err) {
      setPauseError(err instanceof ApiError ? err.code : 'Failed to update pause state');
    } finally {
      setPausing(false);
    }
  }

  return (
    <div className="border border-border rounded-lg overflow-hidden">
      <div className="flex items-center hover:bg-surface-hover">
      <button
        onClick={() => onToggle(bot.id)}
        aria-expanded={isExpanded}
        className="min-h-11 flex-1 flex items-center justify-between px-4 py-3 text-left"
      >
        <div>
          <span className="text-text font-medium">{bot.username}</span>
          {isPaused && (
            <span
              className="ml-2 inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-semibold leading-none bg-warn/20 text-warn"
              title={bot.pausedReason ? `Paused: ${bot.pausedReason}` : 'Paused'}
            >
              PAUSED
            </span>
          )}
          <span className="text-text-muted text-xs ml-2">
            {new Date(bot.createdAt).toLocaleDateString()}
          </span>
          {pauseError && <span className="text-danger text-xs ml-2">{pauseError}</span>}
        </div>
        <svg
          className="h-4 w-4 text-text-muted transition-transform"
          style={{ transform: isExpanded ? 'rotate(180deg)' : 'rotate(0deg)' }}
          fill="none"
          viewBox="0 0 24 24"
          stroke="currentColor"
          strokeWidth="2"
        >
          <polyline points="6 9 12 15 18 9" />
        </svg>
      </button>
      <label className="flex items-center gap-1 pr-3 text-xs text-text-muted" title="Whether this bot may run code in the sandbox">
        Code runs
        <select
          className="min-h-11 md:min-h-8 bg-surface border border-border rounded px-2 py-1 text-xs text-text"
          value={bot.runtimeAccess ?? 'none'}
          disabled={savingAccess}
          onChange={e => changeAccess(e.target.value as RuntimeAccess)}
          aria-label={`Code run access for ${bot.username}`}
        >
          <option value="none">Off</option>
          <option value="approval">Need approval</option>
          <option value="auto">Auto-run</option>
        </select>
      </label>
      <div className="pr-3">
        <Button variant="secondary" onClick={togglePause} loading={pausing}>
          {isPaused ? 'Resume' : 'Pause'}
        </Button>
      </div>
      </div>
      {isExpanded && (
        <BotDetailPanel botId={bot.id} serverId={serverId} onDeleted={onChanged} />
      )}
    </div>
  );
});

// ─── Bot Detail Panel ─────────────────────────────────────────────────────

function BotDetailPanel({
  botId,
  serverId,
  onDeleted,
}: {
  botId: string;
  serverId: string;
  onDeleted: () => void;
}) {
  const [detail, setDetail] = useState<BotDetail | null>(null);
  const [allChannels, setAllChannels] = useState<Channel[]>([]);
  const [tokens, setTokens] = useState<BotToken[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [showCreateToken, setShowCreateToken] = useState(false);
  const [showInvite, setShowInvite] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [channelLoading, setChannelLoading] = useState<string | null>(null);
  const [avatarInput, setAvatarInput] = useState('');
  const [avatarSaving, setAvatarSaving] = useState(false);
  const [avatarError, setAvatarError] = useState('');

  const fetchDetail = useCallback(async () => {
    try {
      const [d, channels] = await Promise.all([
        botApi.get(serverId, botId),
        serverApi.getChannels(serverId),
      ]);
      setDetail(d);
      setAvatarInput(d.avatarUrl || '');
      // Only show text channels (type 3) for bot access
      setAllChannels(channels.filter(c => c.channelType === 3));
      if (d.canManageTokens) {
        const t = await botApi.listTokens(serverId, botId);
        setTokens(t);
      }
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to load bot details');
    } finally {
      setLoading(false);
    }
  }, [serverId, botId]);

  useEffect(() => { fetchDetail(); }, [fetchDetail]);

  async function handleDelete() {
    if (!confirm('Delete this bot? This cannot be undone.')) return;
    setDeleting(true);
    try {
      await botApi.remove(serverId, botId);
      onDeleted();
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to delete bot');
      setDeleting(false);
    }
  }

  async function handleRevokeToken(tokenId: string) {
    try {
      await botApi.revokeToken(serverId, botId, tokenId);
      setTokens(prev => prev.map(t => t.id === tokenId ? { ...t, revokedAt: new Date().toISOString() } : t));
    } catch (err) {
      if (err instanceof ApiError && err.status === 403) {
        // Permissions changed — refetch detail
        fetchDetail();
      }
      setError(err instanceof ApiError ? err.code : 'Failed to revoke token');
    }
  }

  async function handleClearBinding(tokenId: string) {
    try {
      await botApi.clearTokenBinding(serverId, botId, tokenId);
      setTokens(prev => prev.map(t => t.id === tokenId ? { ...t, boundClient: null, boundAt: null, lastRefused: null } : t));
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to clear the binding');
    }
  }

  async function toggleDirect(channelId: string, canDirect: boolean) {
    setChannelLoading(channelId);
    setError('');
    try {
      await botApi.setCanDirect(channelId, botId, !canDirect);
      setDetail(await botApi.get(serverId, botId));
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to update who may direct');
    } finally {
      setChannelLoading(null);
    }
  }

  async function toggleChannel(channelId: string, hasAccess: boolean) {
    setChannelLoading(channelId);
    try {
      if (hasAccess) {
        await botApi.revokeChannel(channelId, botId);
      } else {
        await botApi.grantChannel(channelId, botId);
      }
      // Refetch detail to get updated channel list
      const d = await botApi.get(serverId, botId);
      setDetail(d);
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to update channel access');
    } finally {
      setChannelLoading(null);
    }
  }

  if (loading) {
    return <div className="px-4 py-3 border-t border-border text-text-muted text-sm">Loading...</div>;
  }

  if (error && !detail) {
    return <div className="px-4 py-3 border-t border-border text-danger text-sm">{error}</div>;
  }

  if (!detail) return null;

  const botChannelIds = new Set(detail.channels.map(c => c.id));
  const directChannelIds = new Set(detail.channels.filter(c => c.canDirect).map(c => c.id));
  const activeTokens = tokens.filter(t => !t.revokedAt);
  const revokedTokens = tokens.filter(t => t.revokedAt);

  return (
    <div className="border-t border-border px-4 py-4 flex flex-col gap-5 bg-bg/50">
      {error && <p className="text-danger text-sm">{error}</p>}

      {/* ── Avatar ── */}
      <section>
        <h4 className="text-sm font-semibold text-text mb-2">Avatar</h4>
        <div className="flex items-start gap-3">
          <Avatar userId={botId} username={detail.username} avatarUrl={detail.avatarUrl} className="h-12 w-12 text-sm" />
          <div className="flex-1 min-w-0">
            <input
              type="text"
              value={avatarInput}
              onChange={(e) => { setAvatarInput(e.target.value); setAvatarError(''); }}
              placeholder="data:image/svg+xml;base64,..."
              className="min-h-11 md:min-h-9 w-full px-3 py-1.5 rounded border border-border bg-surface text-text placeholder:text-text-muted/70 text-sm"
            />
            {avatarError && <p className="text-danger text-xs mt-1">{avatarError}</p>}
            <div className="flex gap-2 mt-2">
              <Button
                variant="secondary"
                className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
                loading={avatarSaving}
                onClick={async () => {
                  setAvatarSaving(true);
                  setAvatarError('');
                  try {
                    const res = await botApi.update(serverId, botId, { avatarUrl: avatarInput || null });
                    setDetail(prev => prev ? { ...prev, avatarUrl: res.avatarUrl } : prev);
                  } catch (err) {
                    setAvatarError(err instanceof ApiError ? err.code : 'Failed to save avatar');
                  } finally {
                    setAvatarSaving(false);
                  }
                }}
              >
                Save Avatar
              </Button>
              {detail.avatarUrl && (
                <Button
                  variant="secondary"
                  className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
                  onClick={async () => {
                    setAvatarSaving(true);
                    setAvatarError('');
                    try {
                      const res = await botApi.update(serverId, botId, { avatarUrl: null });
                      setDetail(prev => prev ? { ...prev, avatarUrl: res.avatarUrl } : prev);
                      setAvatarInput('');
                    } catch (err) {
                      setAvatarError(err instanceof ApiError ? err.code : 'Failed to remove avatar');
                    } finally {
                      setAvatarSaving(false);
                    }
                  }}
                >
                  Remove
                </Button>
              )}
            </div>
          </div>
        </div>
      </section>

      {/* ── Channel Access ── */}
      <section>
        <h4 className="text-sm font-semibold text-text mb-2">Channel Access</h4>
        {allChannels.length === 0 ? (
          <p className="text-text-muted text-xs">No text channels found.</p>
        ) : (
          <div className="flex flex-col gap-1">
            {allChannels.map((ch) => {
              const hasAccess = botChannelIds.has(ch.id);
              const isLoading = channelLoading === ch.id;
              return (
                <label
                  key={ch.id}
                  className="min-h-11 md:min-h-9 flex items-center gap-2 px-2 py-1.5 rounded hover:bg-surface-hover cursor-pointer text-sm"
                >
                  <input
                    type="checkbox"
                    checked={hasAccess}
                    disabled={isLoading}
                    onChange={() => toggleChannel(ch.id, hasAccess)}
                    className="accent-primary"
                  />
                  <span className="text-text-muted">#</span>
                  <span className="text-text">{ch.name}</span>
                  {isLoading && <span className="text-text-muted text-xs ml-auto">...</span>}
                  {hasAccess && (
                    <span
                      className="ml-auto flex items-center gap-1 text-xs text-text-muted"
                      title="Lets this bot give other agents instructions in this channel. Only the server owner can change it."
                      onClick={(e) => e.stopPropagation()}
                    >
                      <input
                        type="checkbox"
                        checked={directChannelIds.has(ch.id)}
                        disabled={isLoading}
                        onChange={() => toggleDirect(ch.id, directChannelIds.has(ch.id))}
                        className="accent-primary"
                      />
                      can direct agents
                    </span>
                  )}
                </label>
              );
            })}
          </div>
        )}
      </section>

      {/* ── Tokens (owner / admin only) ── */}
      {detail.canManageTokens && (
        <section>
          <Button onClick={() => setShowInvite(true)}>Invite Agent</Button>
          {showInvite && <CreateAgentInviteModal serverId={serverId} botId={botId} onClose={() => setShowInvite(false)} onCreated={() => {}} />}
          <div className="flex items-center justify-between mb-2">
            <h4 className="text-sm font-semibold text-text">Tokens</h4>
            <Button
              variant="secondary"
              className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
              onClick={() => setShowCreateToken(true)}
            >
              New Token
            </Button>
          </div>
          {activeTokens.length === 0 && revokedTokens.length === 0 ? (
            <p className="text-text-muted text-xs">No tokens yet.</p>
          ) : (
            <div className="flex flex-col gap-1">
              {activeTokens.map((t) => (
                <div key={t.id} className="flex items-center justify-between px-2 py-1.5 rounded bg-surface text-sm">
                  <div>
                    <span className="text-text">{t.name || 'Unnamed'}</span>
                    <span className="text-text-muted text-xs ml-2">
                      Created {new Date(t.createdAt).toLocaleDateString()}
                    </span>
                    {t.lastUsedAt && (
                      <span className="text-text-muted text-xs ml-2">
                        Last used {new Date(t.lastUsedAt).toLocaleDateString()}
                        {t.lastUsedClient ? ` by ${t.lastUsedClient}` : ''}
                        {t.lastUsedIp ? ` from ${t.lastUsedIp}` : ''}
                      </span>
                    )}
                    {t.boundClient && (
                      <span className="text-text-muted text-xs ml-2" title="Requests from any other client are refused">
                        Bound to {t.boundClient}
                      </span>
                    )}
                    {t.lastRefused && (
                      <span className="block text-danger text-xs">
                        Refused {t.lastRefused.client ? `use by ${t.lastRefused.client}` : 'a use with no client name'}
                        {t.lastRefused.ip ? ` from ${t.lastRefused.ip}` : ''} on {new Date(t.lastRefused.at).toLocaleString()}.
                        If that wasn't you moving this agent, revoke the token.
                      </span>
                    )}
                  </div>
                  <div className="flex shrink-0">
                    {t.boundClient && (
                      <button
                        onClick={() => handleClearBinding(t.id)}
                        className="min-h-11 md:min-h-8 px-2 text-text-muted text-xs hover:underline"
                        title="The next client that uses the token binds it again"
                      >
                        Clear binding
                      </button>
                    )}
                    <button
                      onClick={() => handleRevokeToken(t.id)}
                      className="min-h-11 md:min-h-8 px-2 text-danger text-xs hover:underline"
                    >
                      Revoke
                    </button>
                  </div>
                </div>
              ))}
              {revokedTokens.map((t) => (
                <div key={t.id} className="flex items-center px-2 py-1.5 rounded bg-surface text-sm opacity-50">
                  <span className="text-text line-through">{t.name || 'Unnamed'}</span>
                  <span className="text-text-muted text-xs ml-2">Revoked</span>
                </div>
              ))}
            </div>
          )}

          <CreateTokenModal
            serverId={serverId}
            botId={botId}
            isOpen={showCreateToken}
            onClose={() => setShowCreateToken(false)}
            onCreated={async () => {
              const t = await botApi.listTokens(serverId, botId);
              setTokens(t);
            }}
          />
        </section>
      )}

      {/* ── Delete Bot ── */}
      <div className="pt-2 border-t border-border">
        <Button variant="danger" onClick={handleDelete} loading={deleting}>
          Delete Bot
        </Button>
      </div>
    </div>
  );
}

import { memo, useCallback, useDeferredValue, useEffect, useMemo, useRef, useState } from 'react';
import { Link } from 'react-router-dom';
import { defaultRangeExtractor, useVirtualizer } from '@tanstack/react-virtual';
import { Avatar } from '../../components/ui/Avatar';
import { useServerStore } from '../../stores/serverStore';
import { useChannelStore } from '../../stores/channelStore';
import { botApi, serverApi, runtimeApi, ApiError } from '../../lib/api';
import type { Bot, BotDetail, BotToken, RuntimeAccess } from '../../lib/api';
import type { Channel } from '../../lib/contracts/server';
import { Button } from '../../components/ui/Button';
import { CreateBotModal } from './CreateBotModal';
import { CreateTokenModal } from './CreateTokenModal';
import { CreateAgentInviteModal } from './CreateAgentInviteModal';

export function BotManagement() {
  const instanceServerId = useServerStore(s => s.instanceServerId);
  const [bots, setBots] = useState<Bot[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [permissionDenied, setPermissionDenied] = useState(false);
  const [showCreateBot, setShowCreateBot] = useState(false);
  const [showInvite, setShowInvite] = useState(false);
  const [expandedBotId, setExpandedBotId] = useState<string | null>(null);
  const [query, setQuery] = useState('');
  const deferredQuery = useDeferredValue(query);

  const fetchBots = useCallback(async (showLoading = true) => {
    if (!instanceServerId) return;
    if (showLoading) setLoading(true);
    setError('');
    try {
      const data = await botApi.list(instanceServerId);
      setBots(data);
      setPermissionDenied(false);
    } catch (err) {
      if (err instanceof ApiError && err.status === 403) {
        setPermissionDenied(true);
      } else {
        setError(err instanceof ApiError ? err.code : 'Failed to load bots');
      }
    } finally {
      setLoading(false);
    }
  }, [instanceServerId]);

  useEffect(() => { fetchBots(); }, [fetchBots]);

  // A refresh after a change keeps the list (and its scroll position) on screen
  const refresh = useCallback(() => { void fetchBots(false); }, [fetchBots]);
  const toggle = useCallback((botId: any) => setExpandedBotId(cur => (cur === botId ? null : botId)), []);

  // Newest first, so a bot you just created is at the top of a long list
  const sorted = useMemo(() => [...bots].sort((a, b) => b.createdAt.localeCompare(a.createdAt)), [bots]);
  const shown = useMemo(() => {
    const q = deferredQuery.trim().toLowerCase();
    return q ? sorted.filter(b => b.username.toLowerCase().includes(q)) : sorted;
  }, [sorted, deferredQuery]);

  if (!instanceServerId) return null;

  if (permissionDenied) {
    return (
      <div>
        <h2 className="text-xl font-bold text-text mb-4">Bot Management</h2>
        <p className="text-text-muted mb-4">You don't have permission to manage bots.</p>
        <Link to="/app" className="hidden min-h-11 items-center text-primary-text hover:underline sm:inline-flex md:min-h-8">Back to chat</Link>
      </div>
    );
  }

  if (loading) {
    return <p className="text-text-muted">Loading bots...</p>;
  }

  return (
    <div>
      <div className="flex flex-wrap items-center justify-between gap-3 mb-6">
        <h2 className="text-xl font-bold text-text">Bot Management</h2>
        <div className="flex gap-2">
          <Button onClick={() => setShowInvite(true)}>Invite Agent</Button>
          <Button variant="secondary" onClick={() => setShowCreateBot(true)}>Create Bot</Button>
        </div>
      </div>

      {error && <p className="text-danger text-sm mb-4">{error}</p>}

      <ChannelLoopGuardSection serverId={instanceServerId} />

      {bots.length === 0 ? (
        <p className="text-text-muted">No bots yet. Create one to get started.</p>
      ) : (
        <section>
          <div className="flex flex-wrap items-center gap-3 mb-2">
            <input
              type="search"
              value={query}
              onChange={e => setQuery(e.target.value)}
              placeholder="Search bots"
              aria-label="Search bots"
              className="min-h-11 md:min-h-9 w-full max-w-xs px-3 py-1.5 rounded border border-border bg-surface text-text placeholder:text-text-muted/70 text-sm"
            />
            <span className="text-text-muted text-xs" aria-live="polite">
              {shown.length === bots.length ? `${bots.length} bots` : `${shown.length} of ${bots.length} bots`}
            </span>
          </div>
          {shown.length === 0 ? (
            <p className="text-text-muted text-sm">No bots match “{deferredQuery.trim()}”.</p>
          ) : (
            <BotList
              bots={shown}
              serverId={instanceServerId}
              expandedBotId={expandedBotId}
              onToggle={toggle}
              onChanged={refresh}
            />
          )}
        </section>
      )}

      <CreateBotModal
        serverId={instanceServerId}
        isOpen={showCreateBot}
        onClose={() => setShowCreateBot(false)}
        onCreated={refresh}
      />
      {showInvite && <CreateAgentInviteModal serverId={instanceServerId} onClose={() => setShowInvite(false)} onCreated={refresh} />}
    </div>
  );
}

// ─── Bot List (virtualized) ───────────────────────────────────────────────

/** Rendering every bot stalled the page at about 1,800 bots (#241): only the rows in view are mounted. */
function BotList({
  bots,
  serverId,
  expandedBotId,
  onToggle,
  onChanged,
}: {
  bots: Bot[];
  serverId: string;
  expandedBotId: string | null;
  onToggle: (botId: string) => void;
  onChanged: () => void;
}) {
  const scrollRef = useRef<HTMLDivElement>(null);
  const expandedIndex = expandedBotId ? bots.findIndex(b => b.id === expandedBotId) : -1;
  // This component is not compiled by the React Compiler; the virtualizer is read during render only
  // eslint-disable-next-line react-hooks/incompatible-library
  const virtualizer = useVirtualizer({
    count: bots.length,
    getScrollElement: () => scrollRef.current,
    estimateSize: () => 60,
    overscan: 8,
    getItemKey: index => bots[index].id,
    // The open bot stays mounted while scrolled away, so its panel (a half-made token, an error) survives
    rangeExtractor: range => {
      const indexes = defaultRangeExtractor(range);
      return expandedIndex < 0 || indexes.includes(expandedIndex) ? indexes : [...indexes, expandedIndex].sort((a, b) => a - b);
    },
  });

  return (
    <div ref={scrollRef} data-testid="bot-list" className="max-h-[70vh] overflow-y-auto overscroll-contain">
      <div className="relative w-full" style={{ height: virtualizer.getTotalSize() }}>
        {virtualizer.getVirtualItems().map(item => {
          const bot = bots[item.index];
          return (
            <div
              key={item.key}
              data-index={item.index}
              ref={virtualizer.measureElement}
              className="absolute left-0 top-0 w-full pb-2"
              style={{ transform: `translateY(${item.start}px)` }}
            >
              <BotRow
                bot={bot}
                serverId={serverId}
                isExpanded={expandedBotId === bot.id}
                onToggle={onToggle}
                onChanged={onChanged}
              />
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ─── Channel Loop Guard Settings ──────────────────────────────────────────

type GuardField = 'maxBotHops' | 'maxThreadBotHops';
type Limits = Record<GuardField, number>;
/** The limit a guard gets when it is switched on with no earlier value to restore. */
const GUARD_DEFAULT: Limits = { maxBotHops: 4, maxThreadBotHops: 4 };

/**
 * Both loop guards per channel (#23): the channel guard (top-level bot messages in a row)
 * and the thread guard (bot replies in a row inside one thread). Each has an on/off switch;
 * off is a limit of 0.
 */
function ChannelLoopGuardSection({ serverId }: { serverId: string }) {
  const [channels, setChannels] = useState<Channel[]>([]);
  // Limits as loaded or last confirmed by a save here
  const [loaded, setLoaded] = useState<Record<string, Limits>>({});
  // Edits not yet confirmed by the server, by `${channelId}:${field}`
  const [dirty, setDirty] = useState<Record<string, number>>({});
  const [saving, setSaving] = useState<Record<string, boolean>>({});
  const [error, setError] = useState('');
  // A change made elsewhere (a notice's Raise limit or Turn off) arrives as ChannelBotConfig
  const live = useChannelStore(s => s.channels);
  const pending = useRef<Record<string, { timer: ReturnType<typeof setTimeout>; value: number }>>({});
  // Saves of one field go out one at a time, in order, so the last change made wins
  const queues = useRef<Record<string, Promise<void>>>({});
  // The last limit above 0, restored when a guard is switched back on
  const lastOn = useRef<Record<string, number>>({});
  const mounted = useRef(true);

  useEffect(() => {
    serverApi.getChannels(serverId).then((chs) => {
      const textChannels = chs.filter(c => c.channelType === 3);
      setChannels(textChannels);
      const initial: Record<string, Limits> = {};
      for (const ch of textChannels) {
        initial[ch.id] = { maxBotHops: ch.maxBotHops ?? 4, maxThreadBotHops: ch.maxThreadBotHops ?? 0 };
      }
      setLoaded(initial);
    }).catch(() => setError('Failed to load channels'));
  }, [serverId]);

  // enqueue only touches refs and state setters, so the first render's copy stays valid for the unmount flush
  const enqueueOnLeave = useRef(enqueue);

  // Leaving the page sends a change still waiting out its debounce instead of dropping it,
  // behind any save of that field still in flight so the older one cannot land last
  useEffect(() => {
    mounted.current = true;
    const waiting = pending.current;
    const flush = enqueueOnLeave.current;
    return () => {
      mounted.current = false;
      for (const [key, p] of Object.entries(waiting)) {
        clearTimeout(p.timer);
        delete waiting[key];
        const [channelId, field] = key.split(':') as [string, GuardField];
        flush(channelId, field, p.value);
      }
    };
  }, []);

  const shown = (channelId: string, field: GuardField): number => {
    const key = `${channelId}:${field}`;
    return dirty[key] ?? live.get(channelId)?.[field] ?? loaded[channelId]?.[field] ?? GUARD_DEFAULT[field];
  };

  function change(channelId: string, field: GuardField, value: number, delay: number) {
    const key = `${channelId}:${field}`;
    const prev = shown(channelId, field);
    if (prev > 0) lastOn.current[key] = prev;
    setDirty(d => ({ ...d, [key]: value }));
    if (pending.current[key]) clearTimeout(pending.current[key].timer);
    const timer = setTimeout(() => {
      delete pending.current[key];
      enqueue(channelId, field, value);
    }, delay);
    pending.current[key] = { timer, value };
  }

  /** Queues a save behind any earlier save of the same field (save never rejects). */
  function enqueue(channelId: string, field: GuardField, value: number) {
    const key = `${channelId}:${field}`;
    queues.current[key] = (queues.current[key] ?? Promise.resolve()).then(() => save(channelId, field, value));
  }

  function handleNumber(channelId: string, field: GuardField, raw: string) {
    const num = parseInt(raw, 10);
    // 0 would be "off": that is the switch's job, so the box keeps a limit while typing
    if (isNaN(num) || num < 1 || num > 1000) return;
    change(channelId, field, num, 600);
  }

  function handleToggle(channelId: string, field: GuardField, on: boolean) {
    const restore = lastOn.current[`${channelId}:${field}`] ?? GUARD_DEFAULT[field];
    change(channelId, field, on ? restore : 0, 0);
  }

  async function save(channelId: string, field: GuardField, value: number) {
    const key = `${channelId}:${field}`;
    if (mounted.current) { setSaving(s => ({ ...s, [key]: true })); setError(''); }
    // Only the latest edit clears the dirty value; an older save finishing must not
    const settle = (d: Record<string, number>) => {
      if (d[key] !== value || pending.current[key]) return d;
      const next = { ...d };
      delete next[key];
      return next;
    };
    try {
      const config = await botApi.updateChannelBotConfig(channelId, { [field]: value });
      useChannelStore.getState().patchChannel(channelId, { maxBotHops: config.maxBotHops, maxThreadBotHops: config.maxThreadBotHops });
      if (!mounted.current) return;
      setLoaded(l => ({ ...l, [channelId]: { maxBotHops: config.maxBotHops, maxThreadBotHops: config.maxThreadBotHops } }));
      setDirty(settle);
    } catch (err) {
      if (!mounted.current) return;
      // Show what the server still has, not the value that failed
      setDirty(settle);
      setError(err instanceof ApiError ? err.code : 'Failed to save');
    } finally {
      if (mounted.current) setSaving(s => ({ ...s, [key]: false }));
    }
  }

  if (channels.length === 0) return null;

  const guard = (ch: Channel, field: GuardField, label: string, unit: string) => {
    const value = shown(ch.id, field);
    const on = value > 0;
    const key = `${ch.id}:${field}`;
    return (
      <div className="flex items-center gap-2">
        <label className="min-h-11 md:min-h-8 flex items-center gap-1.5 text-xs text-text-muted cursor-pointer">
          <input
            type="checkbox"
            role="switch"
            checked={on}
            onChange={e => handleToggle(ch.id, field, e.target.checked)}
            aria-label={`${label} loop guard in #${ch.name}`}
            className="accent-primary"
          />
          {label}
        </label>
        {on ? (
          <input
            type="number"
            min={1}
            max={1000}
            value={value}
            onChange={e => handleNumber(ch.id, field, e.target.value)}
            aria-label={`${label} limit in #${ch.name} (${unit})`}
            title={`Pause after this many ${unit} in a row`}
            className="min-h-11 md:min-h-8 w-16 px-2 py-1 rounded border border-border bg-surface text-text text-sm text-right"
          />
        ) : (
          <span className="w-16 text-text-muted text-xs">Off</span>
        )}
        <span className="w-12 text-text-muted text-xs" aria-live="polite">{saving[key] ? 'Saving…' : ''}</span>
      </div>
    );
  };

  return (
    <section className="mb-6">
      <h3 className="text-sm font-semibold text-text mb-2">Loop Guard</h3>
      <p className="text-text-muted text-xs mb-3">
        Pauses agents after this many bot posts in a row with no human message. The channel guard counts top-level
        messages; the thread guard counts replies inside each thread. A human message resets both, and the notice
        it posts has Continue, Raise limit and Turn off buttons.
      </p>
      {error && <p className="text-danger text-xs mb-2" role="alert">{error}</p>}
      <div className="flex flex-col gap-1">
        {channels.map((ch) => (
          <div key={ch.id} className="flex flex-wrap items-center gap-x-6 gap-y-1 px-2 py-1.5 rounded hover:bg-surface-hover">
            <span className="flex min-w-32 flex-1 items-center gap-1 text-sm">
              <span className="text-text-muted">#</span>
              <span className="text-text">{ch.name}</span>
            </span>
            {guard(ch, 'maxBotHops', 'Channel', 'bot messages')}
            {guard(ch, 'maxThreadBotHops', 'Threads', 'bot replies in one thread')}
          </div>
        ))}
      </div>
    </section>
  );
}

// ─── Bot Row (expandable) ─────────────────────────────────────────────────

// Memoized with stable callbacks: opening one bot re-renders that row, not the whole list
const BotRow = memo(function BotRow({
  bot,
  serverId,
  isExpanded,
  onToggle,
  onChanged,
}: {
  bot: Bot;
  serverId: string;
  isExpanded: boolean;
  onToggle: (botId: string) => void;
  onChanged: () => void;
}) {
  const [pausing, setPausing] = useState(false);
  const [pauseError, setPauseError] = useState('');
  const [savingAccess, setSavingAccess] = useState(false);
  const isPaused = !!bot.pausedAt;

  async function changeAccess(access: RuntimeAccess) {
    if (access === 'auto' && !confirm(`Let ${bot.username} run code without approval? Runs still execute in the sandbox with its limits.`)) return;
    setSavingAccess(true);
    setPauseError('');
    try {
      await runtimeApi.setBotAccess(serverId, bot.id, access);
      onChanged();
    } catch (err) {
      setPauseError(err instanceof ApiError ? err.code : 'Failed to update code run access');
    } finally {
      setSavingAccess(false);
    }
  }

  async function togglePause() {
    setPausing(true);
    setPauseError('');
    try {
      if (isPaused) {
        await botApi.setPaused(serverId, bot.id, false);
      } else {
        const reason = prompt('Pause this bot? It will be read-only until resumed.\n\nReason (optional):');
        if (reason === null) return;
        await botApi.setPaused(serverId, bot.id, true, reason.trim() || undefined);
      }
      onChanged();
    } catch (err) {
      setPauseError(err instanceof ApiError ? err.code : 'Failed to update pause state');
    } finally {
      setPausing(false);
    }
  }

  return (
    <div className="border border-border rounded-lg overflow-hidden">
      <div className="flex items-center hover:bg-surface-hover">
      <button
        onClick={() => onToggle(bot.id)}
        aria-expanded={isExpanded}
        className="min-h-11 flex-1 flex items-center justify-between px-4 py-3 text-left"
      >
        <div>
          <span className="text-text font-medium">{bot.username}</span>
          {isPaused && (
            <span
              className="ml-2 inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-semibold leading-none bg-warn/20 text-warn"
              title={bot.pausedReason ? `Paused: ${bot.pausedReason}` : 'Paused'}
            >
              PAUSED
            </span>
          )}
          <span className="text-text-muted text-xs ml-2">
            {new Date(bot.createdAt).toLocaleDateString()}
          </span>
          {pauseError && <span className="text-danger text-xs ml-2">{pauseError}</span>}
        </div>
        <svg
          className="h-4 w-4 text-text-muted transition-transform"
          style={{ transform: isExpanded ? 'rotate(180deg)' : 'rotate(0deg)' }}
          fill="none"
          viewBox="0 0 24 24"
          stroke="currentColor"
          strokeWidth="2"
        >
          <polyline points="6 9 12 15 18 9" />
        </svg>
      </button>
      <label className="flex items-center gap-1 pr-3 text-xs text-text-muted" title="Whether this bot may run code in the sandbox">
        Code runs
        <select
          className="min-h-11 md:min-h-8 bg-surface border border-border rounded px-2 py-1 text-xs text-text"
          value={bot.runtimeAccess ?? 'none'}
          disabled={savingAccess}
          onChange={e => changeAccess(e.target.value as RuntimeAccess)}
          aria-label={`Code run access for ${bot.username}`}
        >
          <option value="none">Off</option>
          <option value="approval">Need approval</option>
          <option value="auto">Auto-run</option>
        </select>
      </label>
      <div className="pr-3">
        <Button variant="secondary" onClick={togglePause} loading={pausing}>
          {isPaused ? 'Resume' : 'Pause'}
        </Button>
      </div>
      </div>
      {isExpanded && (
        <BotDetailPanel botId={bot.id} serverId={serverId} onDeleted={onChanged} />
      )}
    </div>
  );
});

// ─── Bot Detail Panel ─────────────────────────────────────────────────────

function BotDetailPanel({
  botId,
  serverId,
  onDeleted,
}: {
  botId: string;
  serverId: string;
  onDeleted: () => void;
}) {
  const [detail, setDetail] = useState<BotDetail | null>(null);
  const [allChannels, setAllChannels] = useState<Channel[]>([]);
  const [tokens, setTokens] = useState<BotToken[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [showCreateToken, setShowCreateToken] = useState(false);
  const [showInvite, setShowInvite] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [channelLoading, setChannelLoading] = useState<string | null>(null);
  const [avatarInput, setAvatarInput] = useState('');
  const [avatarSaving, setAvatarSaving] = useState(false);
  const [avatarError, setAvatarError] = useState('');

  const fetchDetail = useCallback(async () => {
    try {
      const [d, channels] = await Promise.all([
        botApi.get(serverId, botId),
        serverApi.getChannels(serverId),
      ]);
      setDetail(d);
      setAvatarInput(d.avatarUrl || '');
      // Only show text channels (type 3) for bot access
      setAllChannels(channels.filter(c => c.channelType === 3));
      if (d.canManageTokens) {
        const t = await botApi.listTokens(serverId, botId);
        setTokens(t);
      }
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to load bot details');
    } finally {
      setLoading(false);
    }
  }, [serverId, botId]);

  useEffect(() => { fetchDetail(); }, [fetchDetail]);

  async function handleDelete() {
    if (!confirm('Delete this bot? This cannot be undone.')) return;
    setDeleting(true);
    try {
      await botApi.remove(serverId, botId);
      onDeleted();
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to delete bot');
      setDeleting(false);
    }
  }

  async function handleRevokeToken(tokenId: string) {
    try {
      await botApi.revokeToken(serverId, botId, tokenId);
      setTokens(prev => prev.map(t => t.id === tokenId ? { ...t, revokedAt: new Date().toISOString() } : t));
    } catch (err) {
      if (err instanceof ApiError && err.status === 403) {
        // Permissions changed — refetch detail
        fetchDetail();
      }
      setError(err instanceof ApiError ? err.code : 'Failed to revoke token');
    }
  }

  async function handleClearBinding(tokenId: string) {
    try {
      await botApi.clearTokenBinding(serverId, botId, tokenId);
      setTokens(prev => prev.map(t => t.id === tokenId ? { ...t, boundClient: null, boundAt: null, lastRefused: null } : t));
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to clear the binding');
    }
  }

  async function toggleDirect(channelId: string, canDirect: boolean) {
    setChannelLoading(channelId);
    setError('');
    try {
      await botApi.setCanDirect(channelId, botId, !canDirect);
      setDetail(await botApi.get(serverId, botId));
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to update who may direct');
    } finally {
      setChannelLoading(null);
    }
  }

  async function toggleChannel(channelId: string, hasAccess: boolean) {
    setChannelLoading(channelId);
    try {
      if (hasAccess) {
        await botApi.revokeChannel(channelId, botId);
      } else {
        await botApi.grantChannel(channelId, botId);
      }
      // Refetch detail to get updated channel list
      const d = await botApi.get(serverId, botId);
      setDetail(d);
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to update channel access');
    } finally {
      setChannelLoading(null);
    }
  }

  if (loading) {
    return <div className="px-4 py-3 border-t border-border text-text-muted text-sm">Loading...</div>;
  }

  if (error && !detail) {
    return <div className="px-4 py-3 border-t border-border text-danger text-sm">{error}</div>;
  }

  if (!detail) return null;

  const botChannelIds = new Set(detail.channels.map(c => c.id));
  const directChannelIds = new Set(detail.channels.filter(c => c.canDirect).map(c => c.id));
  const activeTokens = tokens.filter(t => !t.revokedAt);
  const revokedTokens = tokens.filter(t => t.revokedAt);

  return (
    <div className="border-t border-border px-4 py-4 flex flex-col gap-5 bg-bg/50">
      {error && <p className="text-danger text-sm">{error}</p>}

      {/* ── Avatar ── */}
      <section>
        <h4 className="text-sm font-semibold text-text mb-2">Avatar</h4>
        <div className="flex items-start gap-3">
          <Avatar userId={botId} username={detail.username} avatarUrl={detail.avatarUrl} className="h-12 w-12 text-sm" />
          <div className="flex-1 min-w-0">
            <input
              type="text"
              value={avatarInput}
              onChange={(e) => { setAvatarInput(e.target.value); setAvatarError(''); }}
              placeholder="data:image/svg+xml;base64,..."
              className="min-h-11 md:min-h-9 w-full px-3 py-1.5 rounded border border-border bg-surface text-text placeholder:text-text-muted/70 text-sm"
            />
            {avatarError && <p className="text-danger text-xs mt-1">{avatarError}</p>}
            <div className="flex gap-2 mt-2">
              <Button
                variant="secondary"
                className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
                loading={avatarSaving}
                onClick={async () => {
                  setAvatarSaving(true);
                  setAvatarError('');
                  try {
                    const res = await botApi.update(serverId, botId, { avatarUrl: avatarInput || null });
                    setDetail(prev => prev ? { ...prev, avatarUrl: res.avatarUrl } : prev);
                  } catch (err) {
                    setAvatarError(err instanceof ApiError ? err.code : 'Failed to save avatar');
                  } finally {
                    setAvatarSaving(false);
                  }
                }}
              >
                Save Avatar
              </Button>
              {detail.avatarUrl && (
                <Button
                  variant="secondary"
                  className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
                  onClick={async () => {
                    setAvatarSaving(true);
                    setAvatarError('');
                    try {
                      const res = await botApi.update(serverId, botId, { avatarUrl: null });
                      setDetail(prev => prev ? { ...prev, avatarUrl: res.avatarUrl } : prev);
                      setAvatarInput('');
                    } catch (err) {
                      setAvatarError(err instanceof ApiError ? err.code : 'Failed to remove avatar');
                    } finally {
                      setAvatarSaving(false);
                    }
                  }}
                >
                  Remove
                </Button>
              )}
            </div>
          </div>
        </div>
      </section>

      {/* ── Channel Access ── */}
      <section>
        <h4 className="text-sm font-semibold text-text mb-2">Channel Access</h4>
        {allChannels.length === 0 ? (
          <p className="text-text-muted text-xs">No text channels found.</p>
        ) : (
          <div className="flex flex-col gap-1">
            {allChannels.map((ch) => {
              const hasAccess = botChannelIds.has(ch.id);
              const isLoading = channelLoading === ch.id;
              return (
                <label
                  key={ch.id}
                  className="min-h-11 md:min-h-9 flex items-center gap-2 px-2 py-1.5 rounded hover:bg-surface-hover cursor-pointer text-sm"
                >
                  <input
                    type="checkbox"
                    checked={hasAccess}
                    disabled={isLoading}
                    onChange={() => toggleChannel(ch.id, hasAccess)}
                    className="accent-primary"
                  />
                  <span className="text-text-muted">#</span>
                  <span className="text-text">{ch.name}</span>
                  {isLoading && <span className="text-text-muted text-xs ml-auto">...</span>}
                  {hasAccess && (
                    <span
                      className="ml-auto flex items-center gap-1 text-xs text-text-muted"
                      title="Lets this bot give other agents instructions in this channel. Only the server owner can change it."
                      onClick={(e) => e.stopPropagation()}
                    >
                      <input
                        type="checkbox"
                        checked={directChannelIds.has(ch.id)}
                        disabled={isLoading}
                        onChange={() => toggleDirect(ch.id, directChannelIds.has(ch.id))}
                        className="accent-primary"
                      />
                      can direct agents
                    </span>
                  )}
                </label>
              );
            })}
          </div>
        )}
      </section>

      {/* ── Tokens (owner / admin only) ── */}
      {detail.canManageTokens && (
        <section>
          <Button onClick={() => setShowInvite(true)}>Invite Agent</Button>
          {showInvite && <CreateAgentInviteModal serverId={serverId} botId={botId} onClose={() => setShowInvite(false)} onCreated={() => {}} />}
          <div className="flex items-center justify-between mb-2">
            <h4 className="text-sm font-semibold text-text">Tokens</h4>
            <Button
              variant="secondary"
              className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
              onClick={() => setShowCreateToken(true)}
            >
              New Token
            </Button>
          </div>
          {activeTokens.length === 0 && revokedTokens.length === 0 ? (
            <p className="text-text-muted text-xs">No tokens yet.</p>
          ) : (
            <div className="flex flex-col gap-1">
              {activeTokens.map((t) => (
                <div key={t.id} className="flex items-center justify-between px-2 py-1.5 rounded bg-surface text-sm">
                  <div>
                    <span className="text-text">{t.name || 'Unnamed'}</span>
                    <span className="text-text-muted text-xs ml-2">
                      Created {new Date(t.createdAt).toLocaleDateString()}
                    </span>
                    {t.lastUsedAt && (
                      <span className="text-text-muted text-xs ml-2">
                        Last used {new Date(t.lastUsedAt).toLocaleDateString()}
                        {t.lastUsedClient ? ` by ${t.lastUsedClient}` : ''}
                        {t.lastUsedIp ? ` from ${t.lastUsedIp}` : ''}
                      </span>
                    )}
                    {t.boundClient && (
                      <span className="text-text-muted text-xs ml-2" title="Requests from any other client are refused">
                        Bound to {t.boundClient}
                      </span>
                    )}
                    {t.lastRefused && (
                      <span className="block text-danger text-xs">
                        Refused {t.lastRefused.client ? `use by ${t.lastRefused.client}` : 'a use with no client name'}
                        {t.lastRefused.ip ? ` from ${t.lastRefused.ip}` : ''} on {new Date(t.lastRefused.at).toLocaleString()}.
                        If that wasn't you moving this agent, revoke the token.
                      </span>
                    )}
                  </div>
                  <div className="flex shrink-0">
                    {t.boundClient && (
                      <button
                        onClick={() => handleClearBinding(t.id)}
                        className="min-h-11 md:min-h-8 px-2 text-text-muted text-xs hover:underline"
                        title="The next client that uses the token binds it again"
                      >
                        Clear binding
                      </button>
                    )}
                    <button
                      onClick={() => handleRevokeToken(t.id)}
                      className="min-h-11 md:min-h-8 px-2 text-danger text-xs hover:underline"
                    >
                      Revoke
                    </button>
                  </div>
                </div>
              ))}
              {revokedTokens.map((t) => (
                <div key={t.id} className="flex items-center px-2 py-1.5 rounded bg-surface text-sm opacity-50">
                  <span className="text-text line-through">{t.name || 'Unnamed'}</span>
                  <span className="text-text-muted text-xs ml-2">Revoked</span>
                </div>
              ))}
            </div>
          )}

          <CreateTokenModal
            serverId={serverId}
            botId={botId}
            isOpen={showCreateToken}
            onClose={() => setShowCreateToken(false)}
            onCreated={async () => {
              const t = await botApi.listTokens(serverId, botId);
              setTokens(t);
            }}
          />
        </section>
      )}

      {/* ── Delete Bot ── */}
      <div className="pt-2 border-t border-border">
        <Button variant="danger" onClick={handleDelete} loading={deleting}>
          Delete Bot
        </Button>
      </div>
    </div>
  );
}

import { memo, useCallback, useDeferredValue, useEffect, useMemo, useRef, useState } from 'react';
import { Link } from 'react-router-dom';
import { defaultRangeExtractor, useVirtualizer } from '@tanstack/react-virtual';
import { Avatar } from '../../components/ui/Avatar';
import { useServerStore } from '../../stores/serverStore';
import { useChannelStore } from '../../stores/channelStore';
import { botApi, serverApi, runtimeApi, ApiError } from '../../lib/api';
import type { Bot, BotDetail, BotToken, RuntimeAccess } from '../../lib/api';
import type { Channel } from '../../lib/contracts/server';
import { Button } from '../../components/ui/Button';
import { CreateBotModal } from './CreateBotModal';
import { CreateTokenModal } from './CreateTokenModal';
import { CreateAgentInviteModal } from './CreateAgentInviteModal';

export function BotManagement() {
  const instanceServerId = useServerStore(s => s.instanceServerId);
  const [bots, setBots] = useState<Bot[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [permissionDenied, setPermissionDenied] = useState(false);
  const [showCreateBot, setShowCreateBot] = useState(false);
  const [showInvite, setShowInvite] = useState(false);
  const [expandedBotId, setExpandedBotId] = useState<string | null>(null);
  const [query, setQuery] = useState('');
  const deferredQuery = useDeferredValue(query);

  const fetchBots = useCallback(async (showLoading = true) => {
    if (!instanceServerId) return;
    if (showLoading) setLoading(true);
    setError('');
    try {
      const data = await botApi.list(instanceServerId);
      setBots(data);
      setPermissionDenied(false);
    } catch (err) {
      if (err instanceof ApiError && err.status === 403) {
        setPermissionDenied(true);
      } else {
        setError(err instanceof ApiError ? err.code : 'Failed to load bots');
      }
    } finally {
      setLoading(false);
    }
  }, [instanceServerId]);

  useEffect(() => { fetchBots(); }, [fetchBots]);

  // A refresh after a change keeps the list (and its scroll position) on screen
  const refresh = useCallback(() => { void fetchBots(false); }, [fetchBots]);
  const toggle = useCallback((botId: string) => setExpandedBotId(cur => (cur === botId ? null : botId)), []);

  // Newest first, so a bot you just created is at the top of a long list
  const sorted = useMemo(() => [...bots].sort((a, b) => b.createdAt.localeCompare(a.createdAt)), [bots]);
  const shown = useMemo(() => {
    const q = deferredQuery.trim().toLowerCase();
    return q ? sorted.filter(b => b.username.toLowerCase().includes(q)) : sorted;
  }, [sorted, deferredQuery]);

  if (!instanceServerId) return null;

  if (permissionDenied) {
    return (
      <div>
        <h2 className="text-xl font-bold text-text mb-4">Bot Management</h2>
        <p className="text-text-muted mb-4">You don't have permission to manage bots.</p>
        <Link to="/app" className="hidden min-h-11 items-center text-primary-text hover:underline sm:inline-flex md:min-h-8">Back to chat</Link>
      </div>
    );
  }

  if (loading) {
    return <p className="text-text-muted">Loading bots...</p>;
  }

  return (
    <div>
      <div className="flex flex-wrap items-center justify-between gap-3 mb-6">
        <h2 className="text-xl font-bold text-text">Bot Management</h2>
        <div className="flex gap-2">
          <Button onClick={() => setShowInvite(true)}>Invite Agent</Button>
          <Button variant="secondary" onClick={() => setShowCreateBot(true)}>Create Bot</Button>
        </div>
      </div>

      {error && <p className="text-danger text-sm mb-4">{error}</p>}

      <ChannelLoopGuardSection serverId={instanceServerId} />

      {bots.length === 0 ? (
        <p className="text-text-muted">No bots yet. Create one to get started.</p>
      ) : (
        <section>
          <div className="flex flex-wrap items-center gap-3 mb-2">
            <input
              type="search"
              value={query}
              onChange={e => setQuery(e.target.value)}
              placeholder="Search bots"
              aria-label="Search bots"
              className="min-h-11 md:min-h-9 w-full max-w-xs px-3 py-1.5 rounded border border-border bg-surface text-text placeholder:text-text-muted/70 text-sm"
            />
            <span className="text-text-muted text-xs" aria-live="polite">
              {shown.length === bots.length ? `${bots.length} bots` : `${shown.length} of ${bots.length} bots`}
            </span>
          </div>
          {shown.length === 0 ? (
            <p className="text-text-muted text-sm">No bots match “{deferredQuery.trim()}”.</p>
          ) : (
            <BotList
              bots={shown}
              serverId={instanceServerId}
              expandedBotId={expandedBotId}
              onToggle={toggle}
              onChanged={refresh}
            />
          )}
        </section>
      )}

      <CreateBotModal
        serverId={instanceServerId}
        isOpen={showCreateBot}
        onClose={() => setShowCreateBot(false)}
        onCreated={refresh}
      />
      {showInvite && <CreateAgentInviteModal serverId={instanceServerId} onClose={() => setShowInvite(false)} onCreated={refresh} />}
    </div>
  );
}

// ─── Bot List (virtualized) ───────────────────────────────────────────────

/** Rendering every bot stalled the page at about 1,800 bots (#241): only the rows in view are mounted. */
function BotList({
  bots,
  serverId,
  expandedBotId,
  onToggle,
  onChanged,
}: {
  bots: any;
  serverId: string;
  expandedBotId: string | null;
  onToggle: (botId: string) => void;
  onChanged: () => void;
}) {
  const scrollRef = useRef<HTMLDivElement>(null);
  const expandedIndex = expandedBotId ? bots.findIndex(b => b.id === expandedBotId) : -1;
  // This component is not compiled by the React Compiler; the virtualizer is read during render only
  // eslint-disable-next-line react-hooks/incompatible-library
  const virtualizer = useVirtualizer({
    count: bots.length,
    getScrollElement: () => scrollRef.current,
    estimateSize: () => 60,
    overscan: 8,
    getItemKey: index => bots[index].id,
    // The open bot stays mounted while scrolled away, so its panel (a half-made token, an error) survives
    rangeExtractor: range => {
      const indexes = defaultRangeExtractor(range);
      return expandedIndex < 0 || indexes.includes(expandedIndex) ? indexes : [...indexes, expandedIndex].sort((a, b) => a - b);
    },
  });

  return (
    <div ref={scrollRef} data-testid="bot-list" className="max-h-[70vh] overflow-y-auto overscroll-contain">
      <div className="relative w-full" style={{ height: virtualizer.getTotalSize() }}>
        {virtualizer.getVirtualItems().map(item => {
          const bot = bots[item.index];
          return (
            <div
              key={item.key}
              data-index={item.index}
              ref={virtualizer.measureElement}
              className="absolute left-0 top-0 w-full pb-2"
              style={{ transform: `translateY(${item.start}px)` }}
            >
              <BotRow
                bot={bot}
                serverId={serverId}
                isExpanded={expandedBotId === bot.id}
                onToggle={onToggle}
                onChanged={onChanged}
              />
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ─── Channel Loop Guard Settings ──────────────────────────────────────────

type GuardField = 'maxBotHops' | 'maxThreadBotHops';
type Limits = Record<GuardField, number>;
/** The limit a guard gets when it is switched on with no earlier value to restore. */
const GUARD_DEFAULT: Limits = { maxBotHops: 4, maxThreadBotHops: 4 };

/**
 * Both loop guards per channel (#23): the channel guard (top-level bot messages in a row)
 * and the thread guard (bot replies in a row inside one thread). Each has an on/off switch;
 * off is a limit of 0.
 */
function ChannelLoopGuardSection({ serverId }: { serverId: string }) {
  const [channels, setChannels] = useState<Channel[]>([]);
  // Limits as loaded or last confirmed by a save here
  const [loaded, setLoaded] = useState<Record<string, Limits>>({});
  // Edits not yet confirmed by the server, by `${channelId}:${field}`
  const [dirty, setDirty] = useState<Record<string, number>>({});
  const [saving, setSaving] = useState<Record<string, boolean>>({});
  const [error, setError] = useState('');
  // A change made elsewhere (a notice's Raise limit or Turn off) arrives as ChannelBotConfig
  const live = useChannelStore(s => s.channels);
  const pending = useRef<Record<string, { timer: ReturnType<typeof setTimeout>; value: number }>>({});
  // Saves of one field go out one at a time, in order, so the last change made wins
  const queues = useRef<Record<string, Promise<void>>>({});
  // The last limit above 0, restored when a guard is switched back on
  const lastOn = useRef<Record<string, number>>({});
  const mounted = useRef(true);

  useEffect(() => {
    serverApi.getChannels(serverId).then((chs) => {
      const textChannels = chs.filter(c => c.channelType === 3);
      setChannels(textChannels);
      const initial: Record<string, Limits> = {};
      for (const ch of textChannels) {
        initial[ch.id] = { maxBotHops: ch.maxBotHops ?? 4, maxThreadBotHops: ch.maxThreadBotHops ?? 0 };
      }
      setLoaded(initial);
    }).catch(() => setError('Failed to load channels'));
  }, [serverId]);

  // enqueue only touches refs and state setters, so the first render's copy stays valid for the unmount flush
  const enqueueOnLeave = useRef(enqueue);

  // Leaving the page sends a change still waiting out its debounce instead of dropping it,
  // behind any save of that field still in flight so the older one cannot land last
  useEffect(() => {
    mounted.current = true;
    const waiting = pending.current;
    const flush = enqueueOnLeave.current;
    return () => {
      mounted.current = false;
      for (const [key, p] of Object.entries(waiting)) {
        clearTimeout(p.timer);
        delete waiting[key];
        const [channelId, field] = key.split(':') as [string, GuardField];
        flush(channelId, field, p.value);
      }
    };
  }, []);

  const shown = (channelId: string, field: GuardField): number => {
    const key = `${channelId}:${field}`;
    return dirty[key] ?? live.get(channelId)?.[field] ?? loaded[channelId]?.[field] ?? GUARD_DEFAULT[field];
  };

  function change(channelId: string, field: GuardField, value: number, delay: number) {
    const key = `${channelId}:${field}`;
    const prev = shown(channelId, field);
    if (prev > 0) lastOn.current[key] = prev;
    setDirty(d => ({ ...d, [key]: value }));
    if (pending.current[key]) clearTimeout(pending.current[key].timer);
    const timer = setTimeout(() => {
      delete pending.current[key];
      enqueue(channelId, field, value);
    }, delay);
    pending.current[key] = { timer, value };
  }

  /** Queues a save behind any earlier save of the same field (save never rejects). */
  function enqueue(channelId: string, field: GuardField, value: number) {
    const key = `${channelId}:${field}`;
    queues.current[key] = (queues.current[key] ?? Promise.resolve()).then(() => save(channelId, field, value));
  }

  function handleNumber(channelId: string, field: GuardField, raw: string) {
    const num = parseInt(raw, 10);
    // 0 would be "off": that is the switch's job, so the box keeps a limit while typing
    if (isNaN(num) || num < 1 || num > 1000) return;
    change(channelId, field, num, 600);
  }

  function handleToggle(channelId: string, field: GuardField, on: boolean) {
    const restore = lastOn.current[`${channelId}:${field}`] ?? GUARD_DEFAULT[field];
    change(channelId, field, on ? restore : 0, 0);
  }

  async function save(channelId: string, field: GuardField, value: number) {
    const key = `${channelId}:${field}`;
    if (mounted.current) { setSaving(s => ({ ...s, [key]: true })); setError(''); }
    // Only the latest edit clears the dirty value; an older save finishing must not
    const settle = (d: Record<string, number>) => {
      if (d[key] !== value || pending.current[key]) return d;
      const next = { ...d };
      delete next[key];
      return next;
    };
    try {
      const config = await botApi.updateChannelBotConfig(channelId, { [field]: value });
      useChannelStore.getState().patchChannel(channelId, { maxBotHops: config.maxBotHops, maxThreadBotHops: config.maxThreadBotHops });
      if (!mounted.current) return;
      setLoaded(l => ({ ...l, [channelId]: { maxBotHops: config.maxBotHops, maxThreadBotHops: config.maxThreadBotHops } }));
      setDirty(settle);
    } catch (err) {
      if (!mounted.current) return;
      // Show what the server still has, not the value that failed
      setDirty(settle);
      setError(err instanceof ApiError ? err.code : 'Failed to save');
    } finally {
      if (mounted.current) setSaving(s => ({ ...s, [key]: false }));
    }
  }

  if (channels.length === 0) return null;

  const guard = (ch: Channel, field: GuardField, label: string, unit: string) => {
    const value = shown(ch.id, field);
    const on = value > 0;
    const key = `${ch.id}:${field}`;
    return (
      <div className="flex items-center gap-2">
        <label className="min-h-11 md:min-h-8 flex items-center gap-1.5 text-xs text-text-muted cursor-pointer">
          <input
            type="checkbox"
            role="switch"
            checked={on}
            onChange={e => handleToggle(ch.id, field, e.target.checked)}
            aria-label={`${label} loop guard in #${ch.name}`}
            className="accent-primary"
          />
          {label}
        </label>
        {on ? (
          <input
            type="number"
            min={1}
            max={1000}
            value={value}
            onChange={e => handleNumber(ch.id, field, e.target.value)}
            aria-label={`${label} limit in #${ch.name} (${unit})`}
            title={`Pause after this many ${unit} in a row`}
            className="min-h-11 md:min-h-8 w-16 px-2 py-1 rounded border border-border bg-surface text-text text-sm text-right"
          />
        ) : (
          <span className="w-16 text-text-muted text-xs">Off</span>
        )}
        <span className="w-12 text-text-muted text-xs" aria-live="polite">{saving[key] ? 'Saving…' : ''}</span>
      </div>
    );
  };

  return (
    <section className="mb-6">
      <h3 className="text-sm font-semibold text-text mb-2">Loop Guard</h3>
      <p className="text-text-muted text-xs mb-3">
        Pauses agents after this many bot posts in a row with no human message. The channel guard counts top-level
        messages; the thread guard counts replies inside each thread. A human message resets both, and the notice
        it posts has Continue, Raise limit and Turn off buttons.
      </p>
      {error && <p className="text-danger text-xs mb-2" role="alert">{error}</p>}
      <div className="flex flex-col gap-1">
        {channels.map((ch) => (
          <div key={ch.id} className="flex flex-wrap items-center gap-x-6 gap-y-1 px-2 py-1.5 rounded hover:bg-surface-hover">
            <span className="flex min-w-32 flex-1 items-center gap-1 text-sm">
              <span className="text-text-muted">#</span>
              <span className="text-text">{ch.name}</span>
            </span>
            {guard(ch, 'maxBotHops', 'Channel', 'bot messages')}
            {guard(ch, 'maxThreadBotHops', 'Threads', 'bot replies in one thread')}
          </div>
        ))}
      </div>
    </section>
  );
}

// ─── Bot Row (expandable) ─────────────────────────────────────────────────

// Memoized with stable callbacks: opening one bot re-renders that row, not the whole list
const BotRow = memo(function BotRow({
  bot,
  serverId,
  isExpanded,
  onToggle,
  onChanged,
}: {
  bot: Bot;
  serverId: string;
  isExpanded: boolean;
  onToggle: (botId: string) => void;
  onChanged: () => void;
}) {
  const [pausing, setPausing] = useState(false);
  const [pauseError, setPauseError] = useState('');
  const [savingAccess, setSavingAccess] = useState(false);
  const isPaused = !!bot.pausedAt;

  async function changeAccess(access: RuntimeAccess) {
    if (access === 'auto' && !confirm(`Let ${bot.username} run code without approval? Runs still execute in the sandbox with its limits.`)) return;
    setSavingAccess(true);
    setPauseError('');
    try {
      await runtimeApi.setBotAccess(serverId, bot.id, access);
      onChanged();
    } catch (err) {
      setPauseError(err instanceof ApiError ? err.code : 'Failed to update code run access');
    } finally {
      setSavingAccess(false);
    }
  }

  async function togglePause() {
    setPausing(true);
    setPauseError('');
    try {
      if (isPaused) {
        await botApi.setPaused(serverId, bot.id, false);
      } else {
        const reason = prompt('Pause this bot? It will be read-only until resumed.\n\nReason (optional):');
        if (reason === null) return;
        await botApi.setPaused(serverId, bot.id, true, reason.trim() || undefined);
      }
      onChanged();
    } catch (err) {
      setPauseError(err instanceof ApiError ? err.code : 'Failed to update pause state');
    } finally {
      setPausing(false);
    }
  }

  return (
    <div className="border border-border rounded-lg overflow-hidden">
      <div className="flex items-center hover:bg-surface-hover">
      <button
        onClick={() => onToggle(bot.id)}
        aria-expanded={isExpanded}
        className="min-h-11 flex-1 flex items-center justify-between px-4 py-3 text-left"
      >
        <div>
          <span className="text-text font-medium">{bot.username}</span>
          {isPaused && (
            <span
              className="ml-2 inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-semibold leading-none bg-warn/20 text-warn"
              title={bot.pausedReason ? `Paused: ${bot.pausedReason}` : 'Paused'}
            >
              PAUSED
            </span>
          )}
          <span className="text-text-muted text-xs ml-2">
            {new Date(bot.createdAt).toLocaleDateString()}
          </span>
          {pauseError && <span className="text-danger text-xs ml-2">{pauseError}</span>}
        </div>
        <svg
          className="h-4 w-4 text-text-muted transition-transform"
          style={{ transform: isExpanded ? 'rotate(180deg)' : 'rotate(0deg)' }}
          fill="none"
          viewBox="0 0 24 24"
          stroke="currentColor"
          strokeWidth="2"
        >
          <polyline points="6 9 12 15 18 9" />
        </svg>
      </button>
      <label className="flex items-center gap-1 pr-3 text-xs text-text-muted" title="Whether this bot may run code in the sandbox">
        Code runs
        <select
          className="min-h-11 md:min-h-8 bg-surface border border-border rounded px-2 py-1 text-xs text-text"
          value={bot.runtimeAccess ?? 'none'}
          disabled={savingAccess}
          onChange={e => changeAccess(e.target.value as RuntimeAccess)}
          aria-label={`Code run access for ${bot.username}`}
        >
          <option value="none">Off</option>
          <option value="approval">Need approval</option>
          <option value="auto">Auto-run</option>
        </select>
      </label>
      <div className="pr-3">
        <Button variant="secondary" onClick={togglePause} loading={pausing}>
          {isPaused ? 'Resume' : 'Pause'}
        </Button>
      </div>
      </div>
      {isExpanded && (
        <BotDetailPanel botId={bot.id} serverId={serverId} onDeleted={onChanged} />
      )}
    </div>
  );
});

// ─── Bot Detail Panel ─────────────────────────────────────────────────────

function BotDetailPanel({
  botId,
  serverId,
  onDeleted,
}: {
  botId: string;
  serverId: string;
  onDeleted: () => void;
}) {
  const [detail, setDetail] = useState<BotDetail | null>(null);
  const [allChannels, setAllChannels] = useState<Channel[]>([]);
  const [tokens, setTokens] = useState<BotToken[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [showCreateToken, setShowCreateToken] = useState(false);
  const [showInvite, setShowInvite] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [channelLoading, setChannelLoading] = useState<string | null>(null);
  const [avatarInput, setAvatarInput] = useState('');
  const [avatarSaving, setAvatarSaving] = useState(false);
  const [avatarError, setAvatarError] = useState('');

  const fetchDetail = useCallback(async () => {
    try {
      const [d, channels] = await Promise.all([
        botApi.get(serverId, botId),
        serverApi.getChannels(serverId),
      ]);
      setDetail(d);
      setAvatarInput(d.avatarUrl || '');
      // Only show text channels (type 3) for bot access
      setAllChannels(channels.filter(c => c.channelType === 3));
      if (d.canManageTokens) {
        const t = await botApi.listTokens(serverId, botId);
        setTokens(t);
      }
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to load bot details');
    } finally {
      setLoading(false);
    }
  }, [serverId, botId]);

  useEffect(() => { fetchDetail(); }, [fetchDetail]);

  async function handleDelete() {
    if (!confirm('Delete this bot? This cannot be undone.')) return;
    setDeleting(true);
    try {
      await botApi.remove(serverId, botId);
      onDeleted();
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to delete bot');
      setDeleting(false);
    }
  }

  async function handleRevokeToken(tokenId: string) {
    try {
      await botApi.revokeToken(serverId, botId, tokenId);
      setTokens(prev => prev.map(t => t.id === tokenId ? { ...t, revokedAt: new Date().toISOString() } : t));
    } catch (err) {
      if (err instanceof ApiError && err.status === 403) {
        // Permissions changed — refetch detail
        fetchDetail();
      }
      setError(err instanceof ApiError ? err.code : 'Failed to revoke token');
    }
  }

  async function handleClearBinding(tokenId: string) {
    try {
      await botApi.clearTokenBinding(serverId, botId, tokenId);
      setTokens(prev => prev.map(t => t.id === tokenId ? { ...t, boundClient: null, boundAt: null, lastRefused: null } : t));
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to clear the binding');
    }
  }

  async function toggleDirect(channelId: string, canDirect: boolean) {
    setChannelLoading(channelId);
    setError('');
    try {
      await botApi.setCanDirect(channelId, botId, !canDirect);
      setDetail(await botApi.get(serverId, botId));
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to update who may direct');
    } finally {
      setChannelLoading(null);
    }
  }

  async function toggleChannel(channelId: string, hasAccess: boolean) {
    setChannelLoading(channelId);
    try {
      if (hasAccess) {
        await botApi.revokeChannel(channelId, botId);
      } else {
        await botApi.grantChannel(channelId, botId);
      }
      // Refetch detail to get updated channel list
      const d = await botApi.get(serverId, botId);
      setDetail(d);
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to update channel access');
    } finally {
      setChannelLoading(null);
    }
  }

  if (loading) {
    return <div className="px-4 py-3 border-t border-border text-text-muted text-sm">Loading...</div>;
  }

  if (error && !detail) {
    return <div className="px-4 py-3 border-t border-border text-danger text-sm">{error}</div>;
  }

  if (!detail) return null;

  const botChannelIds = new Set(detail.channels.map(c => c.id));
  const directChannelIds = new Set(detail.channels.filter(c => c.canDirect).map(c => c.id));
  const activeTokens = tokens.filter(t => !t.revokedAt);
  const revokedTokens = tokens.filter(t => t.revokedAt);

  return (
    <div className="border-t border-border px-4 py-4 flex flex-col gap-5 bg-bg/50">
      {error && <p className="text-danger text-sm">{error}</p>}

      {/* ── Avatar ── */}
      <section>
        <h4 className="text-sm font-semibold text-text mb-2">Avatar</h4>
        <div className="flex items-start gap-3">
          <Avatar userId={botId} username={detail.username} avatarUrl={detail.avatarUrl} className="h-12 w-12 text-sm" />
          <div className="flex-1 min-w-0">
            <input
              type="text"
              value={avatarInput}
              onChange={(e) => { setAvatarInput(e.target.value); setAvatarError(''); }}
              placeholder="data:image/svg+xml;base64,..."
              className="min-h-11 md:min-h-9 w-full px-3 py-1.5 rounded border border-border bg-surface text-text placeholder:text-text-muted/70 text-sm"
            />
            {avatarError && <p className="text-danger text-xs mt-1">{avatarError}</p>}
            <div className="flex gap-2 mt-2">
              <Button
                variant="secondary"
                className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
                loading={avatarSaving}
                onClick={async () => {
                  setAvatarSaving(true);
                  setAvatarError('');
                  try {
                    const res = await botApi.update(serverId, botId, { avatarUrl: avatarInput || null });
                    setDetail(prev => prev ? { ...prev, avatarUrl: res.avatarUrl } : prev);
                  } catch (err) {
                    setAvatarError(err instanceof ApiError ? err.code : 'Failed to save avatar');
                  } finally {
                    setAvatarSaving(false);
                  }
                }}
              >
                Save Avatar
              </Button>
              {detail.avatarUrl && (
                <Button
                  variant="secondary"
                  className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
                  onClick={async () => {
                    setAvatarSaving(true);
                    setAvatarError('');
                    try {
                      const res = await botApi.update(serverId, botId, { avatarUrl: null });
                      setDetail(prev => prev ? { ...prev, avatarUrl: res.avatarUrl } : prev);
                      setAvatarInput('');
                    } catch (err) {
                      setAvatarError(err instanceof ApiError ? err.code : 'Failed to remove avatar');
                    } finally {
                      setAvatarSaving(false);
                    }
                  }}
                >
                  Remove
                </Button>
              )}
            </div>
          </div>
        </div>
      </section>

      {/* ── Channel Access ── */}
      <section>
        <h4 className="text-sm font-semibold text-text mb-2">Channel Access</h4>
        {allChannels.length === 0 ? (
          <p className="text-text-muted text-xs">No text channels found.</p>
        ) : (
          <div className="flex flex-col gap-1">
            {allChannels.map((ch) => {
              const hasAccess = botChannelIds.has(ch.id);
              const isLoading = channelLoading === ch.id;
              return (
                <label
                  key={ch.id}
                  className="min-h-11 md:min-h-9 flex items-center gap-2 px-2 py-1.5 rounded hover:bg-surface-hover cursor-pointer text-sm"
                >
                  <input
                    type="checkbox"
                    checked={hasAccess}
                    disabled={isLoading}
                    onChange={() => toggleChannel(ch.id, hasAccess)}
                    className="accent-primary"
                  />
                  <span className="text-text-muted">#</span>
                  <span className="text-text">{ch.name}</span>
                  {isLoading && <span className="text-text-muted text-xs ml-auto">...</span>}
                  {hasAccess && (
                    <span
                      className="ml-auto flex items-center gap-1 text-xs text-text-muted"
                      title="Lets this bot give other agents instructions in this channel. Only the server owner can change it."
                      onClick={(e) => e.stopPropagation()}
                    >
                      <input
                        type="checkbox"
                        checked={directChannelIds.has(ch.id)}
                        disabled={isLoading}
                        onChange={() => toggleDirect(ch.id, directChannelIds.has(ch.id))}
                        className="accent-primary"
                      />
                      can direct agents
                    </span>
                  )}
                </label>
              );
            })}
          </div>
        )}
      </section>

      {/* ── Tokens (owner / admin only) ── */}
      {detail.canManageTokens && (
        <section>
          <Button onClick={() => setShowInvite(true)}>Invite Agent</Button>
          {showInvite && <CreateAgentInviteModal serverId={serverId} botId={botId} onClose={() => setShowInvite(false)} onCreated={() => {}} />}
          <div className="flex items-center justify-between mb-2">
            <h4 className="text-sm font-semibold text-text">Tokens</h4>
            <Button
              variant="secondary"
              className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
              onClick={() => setShowCreateToken(true)}
            >
              New Token
            </Button>
          </div>
          {activeTokens.length === 0 && revokedTokens.length === 0 ? (
            <p className="text-text-muted text-xs">No tokens yet.</p>
          ) : (
            <div className="flex flex-col gap-1">
              {activeTokens.map((t) => (
                <div key={t.id} className="flex items-center justify-between px-2 py-1.5 rounded bg-surface text-sm">
                  <div>
                    <span className="text-text">{t.name || 'Unnamed'}</span>
                    <span className="text-text-muted text-xs ml-2">
                      Created {new Date(t.createdAt).toLocaleDateString()}
                    </span>
                    {t.lastUsedAt && (
                      <span className="text-text-muted text-xs ml-2">
                        Last used {new Date(t.lastUsedAt).toLocaleDateString()}
                        {t.lastUsedClient ? ` by ${t.lastUsedClient}` : ''}
                        {t.lastUsedIp ? ` from ${t.lastUsedIp}` : ''}
                      </span>
                    )}
                    {t.boundClient && (
                      <span className="text-text-muted text-xs ml-2" title="Requests from any other client are refused">
                        Bound to {t.boundClient}
                      </span>
                    )}
                    {t.lastRefused && (
                      <span className="block text-danger text-xs">
                        Refused {t.lastRefused.client ? `use by ${t.lastRefused.client}` : 'a use with no client name'}
                        {t.lastRefused.ip ? ` from ${t.lastRefused.ip}` : ''} on {new Date(t.lastRefused.at).toLocaleString()}.
                        If that wasn't you moving this agent, revoke the token.
                      </span>
                    )}
                  </div>
                  <div className="flex shrink-0">
                    {t.boundClient && (
                      <button
                        onClick={() => handleClearBinding(t.id)}
                        className="min-h-11 md:min-h-8 px-2 text-text-muted text-xs hover:underline"
                        title="The next client that uses the token binds it again"
                      >
                        Clear binding
                      </button>
                    )}
                    <button
                      onClick={() => handleRevokeToken(t.id)}
                      className="min-h-11 md:min-h-8 px-2 text-danger text-xs hover:underline"
                    >
                      Revoke
                    </button>
                  </div>
                </div>
              ))}
              {revokedTokens.map((t) => (
                <div key={t.id} className="flex items-center px-2 py-1.5 rounded bg-surface text-sm opacity-50">
                  <span className="text-text line-through">{t.name || 'Unnamed'}</span>
                  <span className="text-text-muted text-xs ml-2">Revoked</span>
                </div>
              ))}
            </div>
          )}

          <CreateTokenModal
            serverId={serverId}
            botId={botId}
            isOpen={showCreateToken}
            onClose={() => setShowCreateToken(false)}
            onCreated={async () => {
              const t = await botApi.listTokens(serverId, botId);
              setTokens(t);
            }}
          />
        </section>
      )}

      {/* ── Delete Bot ── */}
      <div className="pt-2 border-t border-border">
        <Button variant="danger" onClick={handleDelete} loading={deleting}>
          Delete Bot
        </Button>
      </div>
    </div>
  );
}

import { memo, useCallback, useDeferredValue, useEffect, useMemo, useRef, useState } from 'react';
import { Link } from 'react-router-dom';
import { defaultRangeExtractor, useVirtualizer } from '@tanstack/react-virtual';
import { Avatar } from '../../components/ui/Avatar';
import { useServerStore } from '../../stores/serverStore';
import { useChannelStore } from '../../stores/channelStore';
import { botApi, serverApi, runtimeApi, ApiError } from '../../lib/api';
import type { Bot, BotDetail, BotToken, RuntimeAccess } from '../../lib/api';
import type { Channel } from '../../lib/contracts/server';
import { Button } from '../../components/ui/Button';
import { CreateBotModal } from './CreateBotModal';
import { CreateTokenModal } from './CreateTokenModal';
import { CreateAgentInviteModal } from './CreateAgentInviteModal';

export function BotManagement() {
  const instanceServerId = useServerStore(s => s.instanceServerId);
  const [bots, setBots] = useState<Bot[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [permissionDenied, setPermissionDenied] = useState(false);
  const [showCreateBot, setShowCreateBot] = useState(false);
  const [showInvite, setShowInvite] = useState(false);
  const [expandedBotId, setExpandedBotId] = useState<string | null>(null);
  const [query, setQuery] = useState('');
  const deferredQuery = useDeferredValue(query);

  const fetchBots = useCallback(async (showLoading = true) => {
    if (!instanceServerId) return;
    if (showLoading) setLoading(true);
    setError('');
    try {
      const data = await botApi.list(instanceServerId);
      setBots(data);
      setPermissionDenied(false);
    } catch (err) {
      if (err instanceof ApiError && err.status === 403) {
        setPermissionDenied(true);
      } else {
        setError(err instanceof ApiError ? err.code : 'Failed to load bots');
      }
    } finally {
      setLoading(false);
    }
  }, [instanceServerId]);

  useEffect(() => { fetchBots(); }, [fetchBots]);

  // A refresh after a change keeps the list (and its scroll position) on screen
  const refresh = useCallback(() => { void fetchBots(false); }, [fetchBots]);
  const toggle = useCallback((botId: string) => setExpandedBotId(cur => (cur === botId ? null : botId)), []);

  // Newest first, so a bot you just created is at the top of a long list
  const sorted = useMemo(() => [...bots].sort((a, b) => b.createdAt.localeCompare(a.createdAt)), [bots]);
  const shown = useMemo(() => {
    const q = deferredQuery.trim().toLowerCase();
    return q ? sorted.filter(b => b.username.toLowerCase().includes(q)) : sorted;
  }, [sorted, deferredQuery]);

  if (!instanceServerId) return null;

  if (permissionDenied) {
    return (
      <div>
        <h2 className="text-xl font-bold text-text mb-4">Bot Management</h2>
        <p className="text-text-muted mb-4">You don't have permission to manage bots.</p>
        <Link to="/app" className="hidden min-h-11 items-center text-primary-text hover:underline sm:inline-flex md:min-h-8">Back to chat</Link>
      </div>
    );
  }

  if (loading) {
    return <p className="text-text-muted">Loading bots...</p>;
  }

  return (
    <div>
      <div className="flex flex-wrap items-center justify-between gap-3 mb-6">
        <h2 className="text-xl font-bold text-text">Bot Management</h2>
        <div className="flex gap-2">
          <Button onClick={() => setShowInvite(true)}>Invite Agent</Button>
          <Button variant="secondary" onClick={() => setShowCreateBot(true)}>Create Bot</Button>
        </div>
      </div>

      {error && <p className="text-danger text-sm mb-4">{error}</p>}

      <ChannelLoopGuardSection serverId={instanceServerId} />

      {bots.length === 0 ? (
        <p className="text-text-muted">No bots yet. Create one to get started.</p>
      ) : (
        <section>
          <div className="flex flex-wrap items-center gap-3 mb-2">
            <input
              type="search"
              value={query}
              onChange={e => setQuery(e.target.value)}
              placeholder="Search bots"
              aria-label="Search bots"
              className="min-h-11 md:min-h-9 w-full max-w-xs px-3 py-1.5 rounded border border-border bg-surface text-text placeholder:text-text-muted/70 text-sm"
            />
            <span className="text-text-muted text-xs" aria-live="polite">
              {shown.length === bots.length ? `${bots.length} bots` : `${shown.length} of ${bots.length} bots`}
            </span>
          </div>
          {shown.length === 0 ? (
            <p className="text-text-muted text-sm">No bots match “{deferredQuery.trim()}”.</p>
          ) : (
            <BotList
              bots={shown}
              serverId={instanceServerId}
              expandedBotId={expandedBotId}
              onToggle={toggle}
              onChanged={refresh}
            />
          )}
        </section>
      )}

      <CreateBotModal
        serverId={instanceServerId}
        isOpen={showCreateBot}
        onClose={() => setShowCreateBot(false)}
        onCreated={refresh}
      />
      {showInvite && <CreateAgentInviteModal serverId={instanceServerId} onClose={() => setShowInvite(false)} onCreated={refresh} />}
    </div>
  );
}

// ─── Bot List (virtualized) ───────────────────────────────────────────────

/** Rendering every bot stalled the page at about 1,800 bots (#241): only the rows in view are mounted. */
function BotList({
  bots,
  serverId,
  expandedBotId,
  onToggle,
  onChanged,
}: {
  bots: Bot[];
  serverId: any;
  expandedBotId: string | null;
  onToggle: (botId: string) => void;
  onChanged: () => void;
}) {
  const scrollRef = useRef<HTMLDivElement>(null);
  const expandedIndex = expandedBotId ? bots.findIndex(b => b.id === expandedBotId) : -1;
  // This component is not compiled by the React Compiler; the virtualizer is read during render only
  // eslint-disable-next-line react-hooks/incompatible-library
  const virtualizer = useVirtualizer({
    count: bots.length,
    getScrollElement: () => scrollRef.current,
    estimateSize: () => 60,
    overscan: 8,
    getItemKey: index => bots[index].id,
    // The open bot stays mounted while scrolled away, so its panel (a half-made token, an error) survives
    rangeExtractor: range => {
      const indexes = defaultRangeExtractor(range);
      return expandedIndex < 0 || indexes.includes(expandedIndex) ? indexes : [...indexes, expandedIndex].sort((a, b) => a - b);
    },
  });

  return (
    <div ref={scrollRef} data-testid="bot-list" className="max-h-[70vh] overflow-y-auto overscroll-contain">
      <div className="relative w-full" style={{ height: virtualizer.getTotalSize() }}>
        {virtualizer.getVirtualItems().map(item => {
          const bot = bots[item.index];
          return (
            <div
              key={item.key}
              data-index={item.index}
              ref={virtualizer.measureElement}
              className="absolute left-0 top-0 w-full pb-2"
              style={{ transform: `translateY(${item.start}px)` }}
            >
              <BotRow
                bot={bot}
                serverId={serverId}
                isExpanded={expandedBotId === bot.id}
                onToggle={onToggle}
                onChanged={onChanged}
              />
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ─── Channel Loop Guard Settings ──────────────────────────────────────────

type GuardField = 'maxBotHops' | 'maxThreadBotHops';
type Limits = Record<GuardField, number>;
/** The limit a guard gets when it is switched on with no earlier value to restore. */
const GUARD_DEFAULT: Limits = { maxBotHops: 4, maxThreadBotHops: 4 };

/**
 * Both loop guards per channel (#23): the channel guard (top-level bot messages in a row)
 * and the thread guard (bot replies in a row inside one thread). Each has an on/off switch;
 * off is a limit of 0.
 */
function ChannelLoopGuardSection({ serverId }: { serverId: string }) {
  const [channels, setChannels] = useState<Channel[]>([]);
  // Limits as loaded or last confirmed by a save here
  const [loaded, setLoaded] = useState<Record<string, Limits>>({});
  // Edits not yet confirmed by the server, by `${channelId}:${field}`
  const [dirty, setDirty] = useState<Record<string, number>>({});
  const [saving, setSaving] = useState<Record<string, boolean>>({});
  const [error, setError] = useState('');
  // A change made elsewhere (a notice's Raise limit or Turn off) arrives as ChannelBotConfig
  const live = useChannelStore(s => s.channels);
  const pending = useRef<Record<string, { timer: ReturnType<typeof setTimeout>; value: number }>>({});
  // Saves of one field go out one at a time, in order, so the last change made wins
  const queues = useRef<Record<string, Promise<void>>>({});
  // The last limit above 0, restored when a guard is switched back on
  const lastOn = useRef<Record<string, number>>({});
  const mounted = useRef(true);

  useEffect(() => {
    serverApi.getChannels(serverId).then((chs) => {
      const textChannels = chs.filter(c => c.channelType === 3);
      setChannels(textChannels);
      const initial: Record<string, Limits> = {};
      for (const ch of textChannels) {
        initial[ch.id] = { maxBotHops: ch.maxBotHops ?? 4, maxThreadBotHops: ch.maxThreadBotHops ?? 0 };
      }
      setLoaded(initial);
    }).catch(() => setError('Failed to load channels'));
  }, [serverId]);

  // enqueue only touches refs and state setters, so the first render's copy stays valid for the unmount flush
  const enqueueOnLeave = useRef(enqueue);

  // Leaving the page sends a change still waiting out its debounce instead of dropping it,
  // behind any save of that field still in flight so the older one cannot land last
  useEffect(() => {
    mounted.current = true;
    const waiting = pending.current;
    const flush = enqueueOnLeave.current;
    return () => {
      mounted.current = false;
      for (const [key, p] of Object.entries(waiting)) {
        clearTimeout(p.timer);
        delete waiting[key];
        const [channelId, field] = key.split(':') as [string, GuardField];
        flush(channelId, field, p.value);
      }
    };
  }, []);

  const shown = (channelId: string, field: GuardField): number => {
    const key = `${channelId}:${field}`;
    return dirty[key] ?? live.get(channelId)?.[field] ?? loaded[channelId]?.[field] ?? GUARD_DEFAULT[field];
  };

  function change(channelId: string, field: GuardField, value: number, delay: number) {
    const key = `${channelId}:${field}`;
    const prev = shown(channelId, field);
    if (prev > 0) lastOn.current[key] = prev;
    setDirty(d => ({ ...d, [key]: value }));
    if (pending.current[key]) clearTimeout(pending.current[key].timer);
    const timer = setTimeout(() => {
      delete pending.current[key];
      enqueue(channelId, field, value);
    }, delay);
    pending.current[key] = { timer, value };
  }

  /** Queues a save behind any earlier save of the same field (save never rejects). */
  function enqueue(channelId: string, field: GuardField, value: number) {
    const key = `${channelId}:${field}`;
    queues.current[key] = (queues.current[key] ?? Promise.resolve()).then(() => save(channelId, field, value));
  }

  function handleNumber(channelId: string, field: GuardField, raw: string) {
    const num = parseInt(raw, 10);
    // 0 would be "off": that is the switch's job, so the box keeps a limit while typing
    if (isNaN(num) || num < 1 || num > 1000) return;
    change(channelId, field, num, 600);
  }

  function handleToggle(channelId: string, field: GuardField, on: boolean) {
    const restore = lastOn.current[`${channelId}:${field}`] ?? GUARD_DEFAULT[field];
    change(channelId, field, on ? restore : 0, 0);
  }

  async function save(channelId: string, field: GuardField, value: number) {
    const key = `${channelId}:${field}`;
    if (mounted.current) { setSaving(s => ({ ...s, [key]: true })); setError(''); }
    // Only the latest edit clears the dirty value; an older save finishing must not
    const settle = (d: Record<string, number>) => {
      if (d[key] !== value || pending.current[key]) return d;
      const next = { ...d };
      delete next[key];
      return next;
    };
    try {
      const config = await botApi.updateChannelBotConfig(channelId, { [field]: value });
      useChannelStore.getState().patchChannel(channelId, { maxBotHops: config.maxBotHops, maxThreadBotHops: config.maxThreadBotHops });
      if (!mounted.current) return;
      setLoaded(l => ({ ...l, [channelId]: { maxBotHops: config.maxBotHops, maxThreadBotHops: config.maxThreadBotHops } }));
      setDirty(settle);
    } catch (err) {
      if (!mounted.current) return;
      // Show what the server still has, not the value that failed
      setDirty(settle);
      setError(err instanceof ApiError ? err.code : 'Failed to save');
    } finally {
      if (mounted.current) setSaving(s => ({ ...s, [key]: false }));
    }
  }

  if (channels.length === 0) return null;

  const guard = (ch: Channel, field: GuardField, label: string, unit: string) => {
    const value = shown(ch.id, field);
    const on = value > 0;
    const key = `${ch.id}:${field}`;
    return (
      <div className="flex items-center gap-2">
        <label className="min-h-11 md:min-h-8 flex items-center gap-1.5 text-xs text-text-muted cursor-pointer">
          <input
            type="checkbox"
            role="switch"
            checked={on}
            onChange={e => handleToggle(ch.id, field, e.target.checked)}
            aria-label={`${label} loop guard in #${ch.name}`}
            className="accent-primary"
          />
          {label}
        </label>
        {on ? (
          <input
            type="number"
            min={1}
            max={1000}
            value={value}
            onChange={e => handleNumber(ch.id, field, e.target.value)}
            aria-label={`${label} limit in #${ch.name} (${unit})`}
            title={`Pause after this many ${unit} in a row`}
            className="min-h-11 md:min-h-8 w-16 px-2 py-1 rounded border border-border bg-surface text-text text-sm text-right"
          />
        ) : (
          <span className="w-16 text-text-muted text-xs">Off</span>
        )}
        <span className="w-12 text-text-muted text-xs" aria-live="polite">{saving[key] ? 'Saving…' : ''}</span>
      </div>
    );
  };

  return (
    <section className="mb-6">
      <h3 className="text-sm font-semibold text-text mb-2">Loop Guard</h3>
      <p className="text-text-muted text-xs mb-3">
        Pauses agents after this many bot posts in a row with no human message. The channel guard counts top-level
        messages; the thread guard counts replies inside each thread. A human message resets both, and the notice
        it posts has Continue, Raise limit and Turn off buttons.
      </p>
      {error && <p className="text-danger text-xs mb-2" role="alert">{error}</p>}
      <div className="flex flex-col gap-1">
        {channels.map((ch) => (
          <div key={ch.id} className="flex flex-wrap items-center gap-x-6 gap-y-1 px-2 py-1.5 rounded hover:bg-surface-hover">
            <span className="flex min-w-32 flex-1 items-center gap-1 text-sm">
              <span className="text-text-muted">#</span>
              <span className="text-text">{ch.name}</span>
            </span>
            {guard(ch, 'maxBotHops', 'Channel', 'bot messages')}
            {guard(ch, 'maxThreadBotHops', 'Threads', 'bot replies in one thread')}
          </div>
        ))}
      </div>
    </section>
  );
}

// ─── Bot Row (expandable) ─────────────────────────────────────────────────

// Memoized with stable callbacks: opening one bot re-renders that row, not the whole list
const BotRow = memo(function BotRow({
  bot,
  serverId,
  isExpanded,
  onToggle,
  onChanged,
}: {
  bot: Bot;
  serverId: string;
  isExpanded: boolean;
  onToggle: (botId: string) => void;
  onChanged: () => void;
}) {
  const [pausing, setPausing] = useState(false);
  const [pauseError, setPauseError] = useState('');
  const [savingAccess, setSavingAccess] = useState(false);
  const isPaused = !!bot.pausedAt;

  async function changeAccess(access: RuntimeAccess) {
    if (access === 'auto' && !confirm(`Let ${bot.username} run code without approval? Runs still execute in the sandbox with its limits.`)) return;
    setSavingAccess(true);
    setPauseError('');
    try {
      await runtimeApi.setBotAccess(serverId, bot.id, access);
      onChanged();
    } catch (err) {
      setPauseError(err instanceof ApiError ? err.code : 'Failed to update code run access');
    } finally {
      setSavingAccess(false);
    }
  }

  async function togglePause() {
    setPausing(true);
    setPauseError('');
    try {
      if (isPaused) {
        await botApi.setPaused(serverId, bot.id, false);
      } else {
        const reason = prompt('Pause this bot? It will be read-only until resumed.\n\nReason (optional):');
        if (reason === null) return;
        await botApi.setPaused(serverId, bot.id, true, reason.trim() || undefined);
      }
      onChanged();
    } catch (err) {
      setPauseError(err instanceof ApiError ? err.code : 'Failed to update pause state');
    } finally {
      setPausing(false);
    }
  }

  return (
    <div className="border border-border rounded-lg overflow-hidden">
      <div className="flex items-center hover:bg-surface-hover">
      <button
        onClick={() => onToggle(bot.id)}
        aria-expanded={isExpanded}
        className="min-h-11 flex-1 flex items-center justify-between px-4 py-3 text-left"
      >
        <div>
          <span className="text-text font-medium">{bot.username}</span>
          {isPaused && (
            <span
              className="ml-2 inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-semibold leading-none bg-warn/20 text-warn"
              title={bot.pausedReason ? `Paused: ${bot.pausedReason}` : 'Paused'}
            >
              PAUSED
            </span>
          )}
          <span className="text-text-muted text-xs ml-2">
            {new Date(bot.createdAt).toLocaleDateString()}
          </span>
          {pauseError && <span className="text-danger text-xs ml-2">{pauseError}</span>}
        </div>
        <svg
          className="h-4 w-4 text-text-muted transition-transform"
          style={{ transform: isExpanded ? 'rotate(180deg)' : 'rotate(0deg)' }}
          fill="none"
          viewBox="0 0 24 24"
          stroke="currentColor"
          strokeWidth="2"
        >
          <polyline points="6 9 12 15 18 9" />
        </svg>
      </button>
      <label className="flex items-center gap-1 pr-3 text-xs text-text-muted" title="Whether this bot may run code in the sandbox">
        Code runs
        <select
          className="min-h-11 md:min-h-8 bg-surface border border-border rounded px-2 py-1 text-xs text-text"
          value={bot.runtimeAccess ?? 'none'}
          disabled={savingAccess}
          onChange={e => changeAccess(e.target.value as RuntimeAccess)}
          aria-label={`Code run access for ${bot.username}`}
        >
          <option value="none">Off</option>
          <option value="approval">Need approval</option>
          <option value="auto">Auto-run</option>
        </select>
      </label>
      <div className="pr-3">
        <Button variant="secondary" onClick={togglePause} loading={pausing}>
          {isPaused ? 'Resume' : 'Pause'}
        </Button>
      </div>
      </div>
      {isExpanded && (
        <BotDetailPanel botId={bot.id} serverId={serverId} onDeleted={onChanged} />
      )}
    </div>
  );
});

// ─── Bot Detail Panel ─────────────────────────────────────────────────────

function BotDetailPanel({
  botId,
  serverId,
  onDeleted,
}: {
  botId: string;
  serverId: string;
  onDeleted: () => void;
}) {
  const [detail, setDetail] = useState<BotDetail | null>(null);
  const [allChannels, setAllChannels] = useState<Channel[]>([]);
  const [tokens, setTokens] = useState<BotToken[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [showCreateToken, setShowCreateToken] = useState(false);
  const [showInvite, setShowInvite] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [channelLoading, setChannelLoading] = useState<string | null>(null);
  const [avatarInput, setAvatarInput] = useState('');
  const [avatarSaving, setAvatarSaving] = useState(false);
  const [avatarError, setAvatarError] = useState('');

  const fetchDetail = useCallback(async () => {
    try {
      const [d, channels] = await Promise.all([
        botApi.get(serverId, botId),
        serverApi.getChannels(serverId),
      ]);
      setDetail(d);
      setAvatarInput(d.avatarUrl || '');
      // Only show text channels (type 3) for bot access
      setAllChannels(channels.filter(c => c.channelType === 3));
      if (d.canManageTokens) {
        const t = await botApi.listTokens(serverId, botId);
        setTokens(t);
      }
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to load bot details');
    } finally {
      setLoading(false);
    }
  }, [serverId, botId]);

  useEffect(() => { fetchDetail(); }, [fetchDetail]);

  async function handleDelete() {
    if (!confirm('Delete this bot? This cannot be undone.')) return;
    setDeleting(true);
    try {
      await botApi.remove(serverId, botId);
      onDeleted();
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to delete bot');
      setDeleting(false);
    }
  }

  async function handleRevokeToken(tokenId: string) {
    try {
      await botApi.revokeToken(serverId, botId, tokenId);
      setTokens(prev => prev.map(t => t.id === tokenId ? { ...t, revokedAt: new Date().toISOString() } : t));
    } catch (err) {
      if (err instanceof ApiError && err.status === 403) {
        // Permissions changed — refetch detail
        fetchDetail();
      }
      setError(err instanceof ApiError ? err.code : 'Failed to revoke token');
    }
  }

  async function handleClearBinding(tokenId: string) {
    try {
      await botApi.clearTokenBinding(serverId, botId, tokenId);
      setTokens(prev => prev.map(t => t.id === tokenId ? { ...t, boundClient: null, boundAt: null, lastRefused: null } : t));
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to clear the binding');
    }
  }

  async function toggleDirect(channelId: string, canDirect: boolean) {
    setChannelLoading(channelId);
    setError('');
    try {
      await botApi.setCanDirect(channelId, botId, !canDirect);
      setDetail(await botApi.get(serverId, botId));
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to update who may direct');
    } finally {
      setChannelLoading(null);
    }
  }

  async function toggleChannel(channelId: string, hasAccess: boolean) {
    setChannelLoading(channelId);
    try {
      if (hasAccess) {
        await botApi.revokeChannel(channelId, botId);
      } else {
        await botApi.grantChannel(channelId, botId);
      }
      // Refetch detail to get updated channel list
      const d = await botApi.get(serverId, botId);
      setDetail(d);
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to update channel access');
    } finally {
      setChannelLoading(null);
    }
  }

  if (loading) {
    return <div className="px-4 py-3 border-t border-border text-text-muted text-sm">Loading...</div>;
  }

  if (error && !detail) {
    return <div className="px-4 py-3 border-t border-border text-danger text-sm">{error}</div>;
  }

  if (!detail) return null;

  const botChannelIds = new Set(detail.channels.map(c => c.id));
  const directChannelIds = new Set(detail.channels.filter(c => c.canDirect).map(c => c.id));
  const activeTokens = tokens.filter(t => !t.revokedAt);
  const revokedTokens = tokens.filter(t => t.revokedAt);

  return (
    <div className="border-t border-border px-4 py-4 flex flex-col gap-5 bg-bg/50">
      {error && <p className="text-danger text-sm">{error}</p>}

      {/* ── Avatar ── */}
      <section>
        <h4 className="text-sm font-semibold text-text mb-2">Avatar</h4>
        <div className="flex items-start gap-3">
          <Avatar userId={botId} username={detail.username} avatarUrl={detail.avatarUrl} className="h-12 w-12 text-sm" />
          <div className="flex-1 min-w-0">
            <input
              type="text"
              value={avatarInput}
              onChange={(e) => { setAvatarInput(e.target.value); setAvatarError(''); }}
              placeholder="data:image/svg+xml;base64,..."
              className="min-h-11 md:min-h-9 w-full px-3 py-1.5 rounded border border-border bg-surface text-text placeholder:text-text-muted/70 text-sm"
            />
            {avatarError && <p className="text-danger text-xs mt-1">{avatarError}</p>}
            <div className="flex gap-2 mt-2">
              <Button
                variant="secondary"
                className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
                loading={avatarSaving}
                onClick={async () => {
                  setAvatarSaving(true);
                  setAvatarError('');
                  try {
                    const res = await botApi.update(serverId, botId, { avatarUrl: avatarInput || null });
                    setDetail(prev => prev ? { ...prev, avatarUrl: res.avatarUrl } : prev);
                  } catch (err) {
                    setAvatarError(err instanceof ApiError ? err.code : 'Failed to save avatar');
                  } finally {
                    setAvatarSaving(false);
                  }
                }}
              >
                Save Avatar
              </Button>
              {detail.avatarUrl && (
                <Button
                  variant="secondary"
                  className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
                  onClick={async () => {
                    setAvatarSaving(true);
                    setAvatarError('');
                    try {
                      const res = await botApi.update(serverId, botId, { avatarUrl: null });
                      setDetail(prev => prev ? { ...prev, avatarUrl: res.avatarUrl } : prev);
                      setAvatarInput('');
                    } catch (err) {
                      setAvatarError(err instanceof ApiError ? err.code : 'Failed to remove avatar');
                    } finally {
                      setAvatarSaving(false);
                    }
                  }}
                >
                  Remove
                </Button>
              )}
            </div>
          </div>
        </div>
      </section>

      {/* ── Channel Access ── */}
      <section>
        <h4 className="text-sm font-semibold text-text mb-2">Channel Access</h4>
        {allChannels.length === 0 ? (
          <p className="text-text-muted text-xs">No text channels found.</p>
        ) : (
          <div className="flex flex-col gap-1">
            {allChannels.map((ch) => {
              const hasAccess = botChannelIds.has(ch.id);
              const isLoading = channelLoading === ch.id;
              return (
                <label
                  key={ch.id}
                  className="min-h-11 md:min-h-9 flex items-center gap-2 px-2 py-1.5 rounded hover:bg-surface-hover cursor-pointer text-sm"
                >
                  <input
                    type="checkbox"
                    checked={hasAccess}
                    disabled={isLoading}
                    onChange={() => toggleChannel(ch.id, hasAccess)}
                    className="accent-primary"
                  />
                  <span className="text-text-muted">#</span>
                  <span className="text-text">{ch.name}</span>
                  {isLoading && <span className="text-text-muted text-xs ml-auto">...</span>}
                  {hasAccess && (
                    <span
                      className="ml-auto flex items-center gap-1 text-xs text-text-muted"
                      title="Lets this bot give other agents instructions in this channel. Only the server owner can change it."
                      onClick={(e) => e.stopPropagation()}
                    >
                      <input
                        type="checkbox"
                        checked={directChannelIds.has(ch.id)}
                        disabled={isLoading}
                        onChange={() => toggleDirect(ch.id, directChannelIds.has(ch.id))}
                        className="accent-primary"
                      />
                      can direct agents
                    </span>
                  )}
                </label>
              );
            })}
          </div>
        )}
      </section>

      {/* ── Tokens (owner / admin only) ── */}
      {detail.canManageTokens && (
        <section>
          <Button onClick={() => setShowInvite(true)}>Invite Agent</Button>
          {showInvite && <CreateAgentInviteModal serverId={serverId} botId={botId} onClose={() => setShowInvite(false)} onCreated={() => {}} />}
          <div className="flex items-center justify-between mb-2">
            <h4 className="text-sm font-semibold text-text">Tokens</h4>
            <Button
              variant="secondary"
              className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
              onClick={() => setShowCreateToken(true)}
            >
              New Token
            </Button>
          </div>
          {activeTokens.length === 0 && revokedTokens.length === 0 ? (
            <p className="text-text-muted text-xs">No tokens yet.</p>
          ) : (
            <div className="flex flex-col gap-1">
              {activeTokens.map((t) => (
                <div key={t.id} className="flex items-center justify-between px-2 py-1.5 rounded bg-surface text-sm">
                  <div>
                    <span className="text-text">{t.name || 'Unnamed'}</span>
                    <span className="text-text-muted text-xs ml-2">
                      Created {new Date(t.createdAt).toLocaleDateString()}
                    </span>
                    {t.lastUsedAt && (
                      <span className="text-text-muted text-xs ml-2">
                        Last used {new Date(t.lastUsedAt).toLocaleDateString()}
                        {t.lastUsedClient ? ` by ${t.lastUsedClient}` : ''}
                        {t.lastUsedIp ? ` from ${t.lastUsedIp}` : ''}
                      </span>
                    )}
                    {t.boundClient && (
                      <span className="text-text-muted text-xs ml-2" title="Requests from any other client are refused">
                        Bound to {t.boundClient}
                      </span>
                    )}
                    {t.lastRefused && (
                      <span className="block text-danger text-xs">
                        Refused {t.lastRefused.client ? `use by ${t.lastRefused.client}` : 'a use with no client name'}
                        {t.lastRefused.ip ? ` from ${t.lastRefused.ip}` : ''} on {new Date(t.lastRefused.at).toLocaleString()}.
                        If that wasn't you moving this agent, revoke the token.
                      </span>
                    )}
                  </div>
                  <div className="flex shrink-0">
                    {t.boundClient && (
                      <button
                        onClick={() => handleClearBinding(t.id)}
                        className="min-h-11 md:min-h-8 px-2 text-text-muted text-xs hover:underline"
                        title="The next client that uses the token binds it again"
                      >
                        Clear binding
                      </button>
                    )}
                    <button
                      onClick={() => handleRevokeToken(t.id)}
                      className="min-h-11 md:min-h-8 px-2 text-danger text-xs hover:underline"
                    >
                      Revoke
                    </button>
                  </div>
                </div>
              ))}
              {revokedTokens.map((t) => (
                <div key={t.id} className="flex items-center px-2 py-1.5 rounded bg-surface text-sm opacity-50">
                  <span className="text-text line-through">{t.name || 'Unnamed'}</span>
                  <span className="text-text-muted text-xs ml-2">Revoked</span>
                </div>
              ))}
            </div>
          )}

          <CreateTokenModal
            serverId={serverId}
            botId={botId}
            isOpen={showCreateToken}
            onClose={() => setShowCreateToken(false)}
            onCreated={async () => {
              const t = await botApi.listTokens(serverId, botId);
              setTokens(t);
            }}
          />
        </section>
      )}

      {/* ── Delete Bot ── */}
      <div className="pt-2 border-t border-border">
        <Button variant="danger" onClick={handleDelete} loading={deleting}>
          Delete Bot
        </Button>
      </div>
    </div>
  );
}

import { memo, useCallback, useDeferredValue, useEffect, useMemo, useRef, useState } from 'react';
import { Link } from 'react-router-dom';
import { defaultRangeExtractor, useVirtualizer } from '@tanstack/react-virtual';
import { Avatar } from '../../components/ui/Avatar';
import { useServerStore } from '../../stores/serverStore';
import { useChannelStore } from '../../stores/channelStore';
import { botApi, serverApi, runtimeApi, ApiError } from '../../lib/api';
import type { Bot, BotDetail, BotToken, RuntimeAccess } from '../../lib/api';
import type { Channel } from '../../lib/contracts/server';
import { Button } from '../../components/ui/Button';
import { CreateBotModal } from './CreateBotModal';
import { CreateTokenModal } from './CreateTokenModal';
import { CreateAgentInviteModal } from './CreateAgentInviteModal';

export function BotManagement() {
  let instanceServerId = useServerStore(s => s.instanceServerId);
  const [bots, setBots] = useState<Bot[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [permissionDenied, setPermissionDenied] = useState(false);
  const [showCreateBot, setShowCreateBot] = useState(false);
  const [showInvite, setShowInvite] = useState(false);
  const [expandedBotId, setExpandedBotId] = useState<string | null>(null);
  const [query, setQuery] = useState('');
  const deferredQuery = useDeferredValue(query);

  const fetchBots = useCallback(async (showLoading = true) => {
    if (!instanceServerId) return;
    if (showLoading) setLoading(true);
    setError('');
    try {
      const data = await botApi.list(instanceServerId);
      setBots(data);
      setPermissionDenied(false);
    } catch (err) {
      if (err instanceof ApiError && err.status === 403) {
        setPermissionDenied(true);
      } else {
        setError(err instanceof ApiError ? err.code : 'Failed to load bots');
      }
    } finally {
      setLoading(false);
    }
  }, [instanceServerId]);

  useEffect(() => { fetchBots(); }, [fetchBots]);

  // A refresh after a change keeps the list (and its scroll position) on screen
  const refresh = useCallback(() => { void fetchBots(false); }, [fetchBots]);
  const toggle = useCallback((botId: string) => setExpandedBotId(cur => (cur === botId ? null : botId)), []);

  // Newest first, so a bot you just created is at the top of a long list
  const sorted = useMemo(() => [...bots].sort((a, b) => b.createdAt.localeCompare(a.createdAt)), [bots]);
  const shown = useMemo(() => {
    const q = deferredQuery.trim().toLowerCase();
    return q ? sorted.filter(b => b.username.toLowerCase().includes(q)) : sorted;
  }, [sorted, deferredQuery]);

  if (!instanceServerId) return null;

  if (permissionDenied) {
    return (
      <div>
        <h2 className="text-xl font-bold text-text mb-4">Bot Management</h2>
        <p className="text-text-muted mb-4">You don't have permission to manage bots.</p>
        <Link to="/app" className="hidden min-h-11 items-center text-primary-text hover:underline sm:inline-flex md:min-h-8">Back to chat</Link>
      </div>
    );
  }

  if (loading) {
    return <p className="text-text-muted">Loading bots...</p>;
  }

  return (
    <div>
      <div className="flex flex-wrap items-center justify-between gap-3 mb-6">
        <h2 className="text-xl font-bold text-text">Bot Management</h2>
        <div className="flex gap-2">
          <Button onClick={() => setShowInvite(true)}>Invite Agent</Button>
          <Button variant="secondary" onClick={() => setShowCreateBot(true)}>Create Bot</Button>
        </div>
      </div>

      {error && <p className="text-danger text-sm mb-4">{error}</p>}

      <ChannelLoopGuardSection serverId={instanceServerId} />

      {bots.length === 0 ? (
        <p className="text-text-muted">No bots yet. Create one to get started.</p>
      ) : (
        <section>
          <div className="flex flex-wrap items-center gap-3 mb-2">
            <input
              type="search"
              value={query}
              onChange={e => setQuery(e.target.value)}
              placeholder="Search bots"
              aria-label="Search bots"
              className="min-h-11 md:min-h-9 w-full max-w-xs px-3 py-1.5 rounded border border-border bg-surface text-text placeholder:text-text-muted/70 text-sm"
            />
            <span className="text-text-muted text-xs" aria-live="polite">
              {shown.length === bots.length ? `${bots.length} bots` : `${shown.length} of ${bots.length} bots`}
            </span>
          </div>
          {shown.length === 0 ? (
            <p className="text-text-muted text-sm">No bots match “{deferredQuery.trim()}”.</p>
          ) : (
            <BotList
              bots={shown}
              serverId={instanceServerId}
              expandedBotId={expandedBotId}
              onToggle={toggle}
              onChanged={refresh}
            />
          )}
        </section>
      )}

      <CreateBotModal
        serverId={instanceServerId}
        isOpen={showCreateBot}
        onClose={() => setShowCreateBot(false)}
        onCreated={refresh}
      />
      {showInvite && <CreateAgentInviteModal serverId={instanceServerId} onClose={() => setShowInvite(false)} onCreated={refresh} />}
    </div>
  );
}

// ─── Bot List (virtualized) ───────────────────────────────────────────────

/** Rendering every bot stalled the page at about 1,800 bots (#241): only the rows in view are mounted. */
function BotList({
  bots,
  serverId,
  expandedBotId,
  onToggle,
  onChanged,
}: {
  bots: Bot[];
  serverId: string;
  expandedBotId: string | null;
  onToggle: (botId: string) => void;
  onChanged: () => void;
}) {
  const scrollRef = useRef<HTMLDivElement>(null);
  const expandedIndex = expandedBotId ? bots.findIndex(b => b.id === expandedBotId) : -1;
  // This component is not compiled by the React Compiler; the virtualizer is read during render only
  // eslint-disable-next-line react-hooks/incompatible-library
  const virtualizer = useVirtualizer({
    count: bots.length,
    getScrollElement: () => scrollRef.current,
    estimateSize: () => 60,
    overscan: 8,
    getItemKey: index => bots[index].id,
    // The open bot stays mounted while scrolled away, so its panel (a half-made token, an error) survives
    rangeExtractor: range => {
      const indexes = defaultRangeExtractor(range);
      return expandedIndex < 0 || indexes.includes(expandedIndex) ? indexes : [...indexes, expandedIndex].sort((a, b) => a - b);
    },
  });

  return (
    <div ref={scrollRef} data-testid="bot-list" className="max-h-[70vh] overflow-y-auto overscroll-contain">
      <div className="relative w-full" style={{ height: virtualizer.getTotalSize() }}>
        {virtualizer.getVirtualItems().map(item => {
          const bot = bots[item.index];
          return (
            <div
              key={item.key}
              data-index={item.index}
              ref={virtualizer.measureElement}
              className="absolute left-0 top-0 w-full pb-2"
              style={{ transform: `translateY(${item.start}px)` }}
            >
              <BotRow
                bot={bot}
                serverId={serverId}
                isExpanded={expandedBotId === bot.id}
                onToggle={onToggle}
                onChanged={onChanged}
              />
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ─── Channel Loop Guard Settings ──────────────────────────────────────────

type GuardField = 'maxBotHops' | 'maxThreadBotHops';
type Limits = Record<GuardField, number>;
/** The limit a guard gets when it is switched on with no earlier value to restore. */
const GUARD_DEFAULT: Limits = { maxBotHops: 4, maxThreadBotHops: 4 };

/**
 * Both loop guards per channel (#23): the channel guard (top-level bot messages in a row)
 * and the thread guard (bot replies in a row inside one thread). Each has an on/off switch;
 * off is a limit of 0.
 */
function ChannelLoopGuardSection({ serverId }: { serverId: string }) {
  const [channels, setChannels] = useState<Channel[]>([]);
  // Limits as loaded or last confirmed by a save here
  const [loaded, setLoaded] = useState<Record<string, Limits>>({});
  // Edits not yet confirmed by the server, by `${channelId}:${field}`
  const [dirty, setDirty] = useState<Record<string, number>>({});
  const [saving, setSaving] = useState<Record<string, boolean>>({});
  const [error, setError] = useState('');
  // A change made elsewhere (a notice's Raise limit or Turn off) arrives as ChannelBotConfig
  const live = useChannelStore(s => s.channels);
  const pending = useRef<Record<string, { timer: ReturnType<typeof setTimeout>; value: number }>>({});
  // Saves of one field go out one at a time, in order, so the last change made wins
  const queues = useRef<Record<string, Promise<void>>>({});
  // The last limit above 0, restored when a guard is switched back on
  const lastOn = useRef<Record<string, number>>({});
  const mounted = useRef(true);

  useEffect(() => {
    serverApi.getChannels(serverId).then((chs) => {
      const textChannels = chs.filter(c => c.channelType === 3);
      setChannels(textChannels);
      const initial: Record<string, Limits> = {};
      for (const ch of textChannels) {
        initial[ch.id] = { maxBotHops: ch.maxBotHops ?? 4, maxThreadBotHops: ch.maxThreadBotHops ?? 0 };
      }
      setLoaded(initial);
    }).catch(() => setError('Failed to load channels'));
  }, [serverId]);

  // enqueue only touches refs and state setters, so the first render's copy stays valid for the unmount flush
  const enqueueOnLeave = useRef(enqueue);

  // Leaving the page sends a change still waiting out its debounce instead of dropping it,
  // behind any save of that field still in flight so the older one cannot land last
  useEffect(() => {
    mounted.current = true;
    const waiting = pending.current;
    const flush = enqueueOnLeave.current;
    return () => {
      mounted.current = false;
      for (const [key, p] of Object.entries(waiting)) {
        clearTimeout(p.timer);
        delete waiting[key];
        const [channelId, field] = key.split(':') as [string, GuardField];
        flush(channelId, field, p.value);
      }
    };
  }, []);

  const shown = (channelId: string, field: GuardField): number => {
    const key = `${channelId}:${field}`;
    return dirty[key] ?? live.get(channelId)?.[field] ?? loaded[channelId]?.[field] ?? GUARD_DEFAULT[field];
  };

  function change(channelId: string, field: GuardField, value: number, delay: number) {
    const key = `${channelId}:${field}`;
    const prev = shown(channelId, field);
    if (prev > 0) lastOn.current[key] = prev;
    setDirty(d => ({ ...d, [key]: value }));
    if (pending.current[key]) clearTimeout(pending.current[key].timer);
    const timer = setTimeout(() => {
      delete pending.current[key];
      enqueue(channelId, field, value);
    }, delay);
    pending.current[key] = { timer, value };
  }

  /** Queues a save behind any earlier save of the same field (save never rejects). */
  function enqueue(channelId: string, field: GuardField, value: number) {
    const key = `${channelId}:${field}`;
    queues.current[key] = (queues.current[key] ?? Promise.resolve()).then(() => save(channelId, field, value));
  }

  function handleNumber(channelId: string, field: GuardField, raw: string) {
    const num = parseInt(raw, 10);
    // 0 would be "off": that is the switch's job, so the box keeps a limit while typing
    if (isNaN(num) || num < 1 || num > 1000) return;
    change(channelId, field, num, 600);
  }

  function handleToggle(channelId: string, field: GuardField, on: boolean) {
    const restore = lastOn.current[`${channelId}:${field}`] ?? GUARD_DEFAULT[field];
    change(channelId, field, on ? restore : 0, 0);
  }

  async function save(channelId: string, field: GuardField, value: number) {
    const key = `${channelId}:${field}`;
    if (mounted.current) { setSaving(s => ({ ...s, [key]: true })); setError(''); }
    // Only the latest edit clears the dirty value; an older save finishing must not
    const settle = (d: Record<string, number>) => {
      if (d[key] !== value || pending.current[key]) return d;
      const next = { ...d };
      delete next[key];
      return next;
    };
    try {
      const config = await botApi.updateChannelBotConfig(channelId, { [field]: value });
      useChannelStore.getState().patchChannel(channelId, { maxBotHops: config.maxBotHops, maxThreadBotHops: config.maxThreadBotHops });
      if (!mounted.current) return;
      setLoaded(l => ({ ...l, [channelId]: { maxBotHops: config.maxBotHops, maxThreadBotHops: config.maxThreadBotHops } }));
      setDirty(settle);
    } catch (err) {
      if (!mounted.current) return;
      // Show what the server still has, not the value that failed
      setDirty(settle);
      setError(err instanceof ApiError ? err.code : 'Failed to save');
    } finally {
      if (mounted.current) setSaving(s => ({ ...s, [key]: false }));
    }
  }

  if (channels.length === 0) return null;

  const guard = (ch: Channel, field: GuardField, label: string, unit: string) => {
    const value = shown(ch.id, field);
    const on = value > 0;
    const key = `${ch.id}:${field}`;
    return (
      <div className="flex items-center gap-2">
        <label className="min-h-11 md:min-h-8 flex items-center gap-1.5 text-xs text-text-muted cursor-pointer">
          <input
            type="checkbox"
            role="switch"
            checked={on}
            onChange={e => handleToggle(ch.id, field, e.target.checked)}
            aria-label={`${label} loop guard in #${ch.name}`}
            className="accent-primary"
          />
          {label}
        </label>
        {on ? (
          <input
            type="number"
            min={1}
            max={1000}
            value={value}
            onChange={e => handleNumber(ch.id, field, e.target.value)}
            aria-label={`${label} limit in #${ch.name} (${unit})`}
            title={`Pause after this many ${unit} in a row`}
            className="min-h-11 md:min-h-8 w-16 px-2 py-1 rounded border border-border bg-surface text-text text-sm text-right"
          />
        ) : (
          <span className="w-16 text-text-muted text-xs">Off</span>
        )}
        <span className="w-12 text-text-muted text-xs" aria-live="polite">{saving[key] ? 'Saving…' : ''}</span>
      </div>
    );
  };

  return (
    <section className="mb-6">
      <h3 className="text-sm font-semibold text-text mb-2">Loop Guard</h3>
      <p className="text-text-muted text-xs mb-3">
        Pauses agents after this many bot posts in a row with no human message. The channel guard counts top-level
        messages; the thread guard counts replies inside each thread. A human message resets both, and the notice
        it posts has Continue, Raise limit and Turn off buttons.
      </p>
      {error && <p className="text-danger text-xs mb-2" role="alert">{error}</p>}
      <div className="flex flex-col gap-1">
        {channels.map((ch) => (
          <div key={ch.id} className="flex flex-wrap items-center gap-x-6 gap-y-1 px-2 py-1.5 rounded hover:bg-surface-hover">
            <span className="flex min-w-32 flex-1 items-center gap-1 text-sm">
              <span className="text-text-muted">#</span>
              <span className="text-text">{ch.name}</span>
            </span>
            {guard(ch, 'maxBotHops', 'Channel', 'bot messages')}
            {guard(ch, 'maxThreadBotHops', 'Threads', 'bot replies in one thread')}
          </div>
        ))}
      </div>
    </section>
  );
}

// ─── Bot Row (expandable) ─────────────────────────────────────────────────

// Memoized with stable callbacks: opening one bot re-renders that row, not the whole list
const BotRow = memo(function BotRow({
  bot,
  serverId,
  isExpanded,
  onToggle,
  onChanged,
}: {
  bot: Bot;
  serverId: string;
  isExpanded: boolean;
  onToggle: (botId: string) => void;
  onChanged: () => void;
}) {
  const [pausing, setPausing] = useState(false);
  const [pauseError, setPauseError] = useState('');
  const [savingAccess, setSavingAccess] = useState(false);
  const isPaused = !!bot.pausedAt;

  async function changeAccess(access: RuntimeAccess) {
    if (access === 'auto' && !confirm(`Let ${bot.username} run code without approval? Runs still execute in the sandbox with its limits.`)) return;
    setSavingAccess(true);
    setPauseError('');
    try {
      await runtimeApi.setBotAccess(serverId, bot.id, access);
      onChanged();
    } catch (err) {
      setPauseError(err instanceof ApiError ? err.code : 'Failed to update code run access');
    } finally {
      setSavingAccess(false);
    }
  }

  async function togglePause() {
    setPausing(true);
    setPauseError('');
    try {
      if (isPaused) {
        await botApi.setPaused(serverId, bot.id, false);
      } else {
        const reason = prompt('Pause this bot? It will be read-only until resumed.\n\nReason (optional):');
        if (reason === null) return;
        await botApi.setPaused(serverId, bot.id, true, reason.trim() || undefined);
      }
      onChanged();
    } catch (err) {
      setPauseError(err instanceof ApiError ? err.code : 'Failed to update pause state');
    } finally {
      setPausing(false);
    }
  }

  return (
    <div className="border border-border rounded-lg overflow-hidden">
      <div className="flex items-center hover:bg-surface-hover">
      <button
        onClick={() => onToggle(bot.id)}
        aria-expanded={isExpanded}
        className="min-h-11 flex-1 flex items-center justify-between px-4 py-3 text-left"
      >
        <div>
          <span className="text-text font-medium">{bot.username}</span>
          {isPaused && (
            <span
              className="ml-2 inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-semibold leading-none bg-warn/20 text-warn"
              title={bot.pausedReason ? `Paused: ${bot.pausedReason}` : 'Paused'}
            >
              PAUSED
            </span>
          )}
          <span className="text-text-muted text-xs ml-2">
            {new Date(bot.createdAt).toLocaleDateString()}
          </span>
          {pauseError && <span className="text-danger text-xs ml-2">{pauseError}</span>}
        </div>
        <svg
          className="h-4 w-4 text-text-muted transition-transform"
          style={{ transform: isExpanded ? 'rotate(180deg)' : 'rotate(0deg)' }}
          fill="none"
          viewBox="0 0 24 24"
          stroke="currentColor"
          strokeWidth="2"
        >
          <polyline points="6 9 12 15 18 9" />
        </svg>
      </button>
      <label className="flex items-center gap-1 pr-3 text-xs text-text-muted" title="Whether this bot may run code in the sandbox">
        Code runs
        <select
          className="min-h-11 md:min-h-8 bg-surface border border-border rounded px-2 py-1 text-xs text-text"
          value={bot.runtimeAccess ?? 'none'}
          disabled={savingAccess}
          onChange={e => changeAccess(e.target.value as RuntimeAccess)}
          aria-label={`Code run access for ${bot.username}`}
        >
          <option value="none">Off</option>
          <option value="approval">Need approval</option>
          <option value="auto">Auto-run</option>
        </select>
      </label>
      <div className="pr-3">
        <Button variant="secondary" onClick={togglePause} loading={pausing}>
          {isPaused ? 'Resume' : 'Pause'}
        </Button>
      </div>
      </div>
      {isExpanded && (
        <BotDetailPanel botId={bot.id} serverId={serverId} onDeleted={onChanged} />
      )}
    </div>
  );
});

// ─── Bot Detail Panel ─────────────────────────────────────────────────────

function BotDetailPanel({
  botId,
  serverId,
  onDeleted,
}: {
  botId: string;
  serverId: string;
  onDeleted: () => void;
}) {
  const [detail, setDetail] = useState<BotDetail | null>(null);
  const [allChannels, setAllChannels] = useState<Channel[]>([]);
  const [tokens, setTokens] = useState<BotToken[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [showCreateToken, setShowCreateToken] = useState(false);
  const [showInvite, setShowInvite] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [channelLoading, setChannelLoading] = useState<string | null>(null);
  const [avatarInput, setAvatarInput] = useState('');
  const [avatarSaving, setAvatarSaving] = useState(false);
  const [avatarError, setAvatarError] = useState('');

  const fetchDetail = useCallback(async () => {
    try {
      const [d, channels] = await Promise.all([
        botApi.get(serverId, botId),
        serverApi.getChannels(serverId),
      ]);
      setDetail(d);
      setAvatarInput(d.avatarUrl || '');
      // Only show text channels (type 3) for bot access
      setAllChannels(channels.filter(c => c.channelType === 3));
      if (d.canManageTokens) {
        const t = await botApi.listTokens(serverId, botId);
        setTokens(t);
      }
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to load bot details');
    } finally {
      setLoading(false);
    }
  }, [serverId, botId]);

  useEffect(() => { fetchDetail(); }, [fetchDetail]);

  async function handleDelete() {
    if (!confirm('Delete this bot? This cannot be undone.')) return;
    setDeleting(true);
    try {
      await botApi.remove(serverId, botId);
      onDeleted();
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to delete bot');
      setDeleting(false);
    }
  }

  async function handleRevokeToken(tokenId: string) {
    try {
      await botApi.revokeToken(serverId, botId, tokenId);
      setTokens(prev => prev.map(t => t.id === tokenId ? { ...t, revokedAt: new Date().toISOString() } : t));
    } catch (err) {
      if (err instanceof ApiError && err.status === 403) {
        // Permissions changed — refetch detail
        fetchDetail();
      }
      setError(err instanceof ApiError ? err.code : 'Failed to revoke token');
    }
  }

  async function handleClearBinding(tokenId: string) {
    try {
      await botApi.clearTokenBinding(serverId, botId, tokenId);
      setTokens(prev => prev.map(t => t.id === tokenId ? { ...t, boundClient: null, boundAt: null, lastRefused: null } : t));
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to clear the binding');
    }
  }

  async function toggleDirect(channelId: string, canDirect: boolean) {
    setChannelLoading(channelId);
    setError('');
    try {
      await botApi.setCanDirect(channelId, botId, !canDirect);
      setDetail(await botApi.get(serverId, botId));
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to update who may direct');
    } finally {
      setChannelLoading(null);
    }
  }

  async function toggleChannel(channelId: string, hasAccess: boolean) {
    setChannelLoading(channelId);
    try {
      if (hasAccess) {
        await botApi.revokeChannel(channelId, botId);
      } else {
        await botApi.grantChannel(channelId, botId);
      }
      // Refetch detail to get updated channel list
      const d = await botApi.get(serverId, botId);
      setDetail(d);
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to update channel access');
    } finally {
      setChannelLoading(null);
    }
  }

  if (loading) {
    return <div className="px-4 py-3 border-t border-border text-text-muted text-sm">Loading...</div>;
  }

  if (error && !detail) {
    return <div className="px-4 py-3 border-t border-border text-danger text-sm">{error}</div>;
  }

  if (!detail) return null;

  const botChannelIds = new Set(detail.channels.map(c => c.id));
  const directChannelIds = new Set(detail.channels.filter(c => c.canDirect).map(c => c.id));
  const activeTokens = tokens.filter(t => !t.revokedAt);
  const revokedTokens = tokens.filter(t => t.revokedAt);

  return (
    <div className="border-t border-border px-4 py-4 flex flex-col gap-5 bg-bg/50">
      {error && <p className="text-danger text-sm">{error}</p>}

      {/* ── Avatar ── */}
      <section>
        <h4 className="text-sm font-semibold text-text mb-2">Avatar</h4>
        <div className="flex items-start gap-3">
          <Avatar userId={botId} username={detail.username} avatarUrl={detail.avatarUrl} className="h-12 w-12 text-sm" />
          <div className="flex-1 min-w-0">
            <input
              type="text"
              value={avatarInput}
              onChange={(e) => { setAvatarInput(e.target.value); setAvatarError(''); }}
              placeholder="data:image/svg+xml;base64,..."
              className="min-h-11 md:min-h-9 w-full px-3 py-1.5 rounded border border-border bg-surface text-text placeholder:text-text-muted/70 text-sm"
            />
            {avatarError && <p className="text-danger text-xs mt-1">{avatarError}</p>}
            <div className="flex gap-2 mt-2">
              <Button
                variant="secondary"
                className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
                loading={avatarSaving}
                onClick={async () => {
                  setAvatarSaving(true);
                  setAvatarError('');
                  try {
                    const res = await botApi.update(serverId, botId, { avatarUrl: avatarInput || null });
                    setDetail(prev => prev ? { ...prev, avatarUrl: res.avatarUrl } : prev);
                  } catch (err) {
                    setAvatarError(err instanceof ApiError ? err.code : 'Failed to save avatar');
                  } finally {
                    setAvatarSaving(false);
                  }
                }}
              >
                Save Avatar
              </Button>
              {detail.avatarUrl && (
                <Button
                  variant="secondary"
                  className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
                  onClick={async () => {
                    setAvatarSaving(true);
                    setAvatarError('');
                    try {
                      const res = await botApi.update(serverId, botId, { avatarUrl: null });
                      setDetail(prev => prev ? { ...prev, avatarUrl: res.avatarUrl } : prev);
                      setAvatarInput('');
                    } catch (err) {
                      setAvatarError(err instanceof ApiError ? err.code : 'Failed to remove avatar');
                    } finally {
                      setAvatarSaving(false);
                    }
                  }}
                >
                  Remove
                </Button>
              )}
            </div>
          </div>
        </div>
      </section>

      {/* ── Channel Access ── */}
      <section>
        <h4 className="text-sm font-semibold text-text mb-2">Channel Access</h4>
        {allChannels.length === 0 ? (
          <p className="text-text-muted text-xs">No text channels found.</p>
        ) : (
          <div className="flex flex-col gap-1">
            {allChannels.map((ch) => {
              const hasAccess = botChannelIds.has(ch.id);
              const isLoading = channelLoading === ch.id;
              return (
                <label
                  key={ch.id}
                  className="min-h-11 md:min-h-9 flex items-center gap-2 px-2 py-1.5 rounded hover:bg-surface-hover cursor-pointer text-sm"
                >
                  <input
                    type="checkbox"
                    checked={hasAccess}
                    disabled={isLoading}
                    onChange={() => toggleChannel(ch.id, hasAccess)}
                    className="accent-primary"
                  />
                  <span className="text-text-muted">#</span>
                  <span className="text-text">{ch.name}</span>
                  {isLoading && <span className="text-text-muted text-xs ml-auto">...</span>}
                  {hasAccess && (
                    <span
                      className="ml-auto flex items-center gap-1 text-xs text-text-muted"
                      title="Lets this bot give other agents instructions in this channel. Only the server owner can change it."
                      onClick={(e) => e.stopPropagation()}
                    >
                      <input
                        type="checkbox"
                        checked={directChannelIds.has(ch.id)}
                        disabled={isLoading}
                        onChange={() => toggleDirect(ch.id, directChannelIds.has(ch.id))}
                        className="accent-primary"
                      />
                      can direct agents
                    </span>
                  )}
                </label>
              );
            })}
          </div>
        )}
      </section>

      {/* ── Tokens (owner / admin only) ── */}
      {detail.canManageTokens && (
        <section>
          <Button onClick={() => setShowInvite(true)}>Invite Agent</Button>
          {showInvite && <CreateAgentInviteModal serverId={serverId} botId={botId} onClose={() => setShowInvite(false)} onCreated={() => {}} />}
          <div className="flex items-center justify-between mb-2">
            <h4 className="text-sm font-semibold text-text">Tokens</h4>
            <Button
              variant="secondary"
              className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
              onClick={() => setShowCreateToken(true)}
            >
              New Token
            </Button>
          </div>
          {activeTokens.length === 0 && revokedTokens.length === 0 ? (
            <p className="text-text-muted text-xs">No tokens yet.</p>
          ) : (
            <div className="flex flex-col gap-1">
              {activeTokens.map((t) => (
                <div key={t.id} className="flex items-center justify-between px-2 py-1.5 rounded bg-surface text-sm">
                  <div>
                    <span className="text-text">{t.name || 'Unnamed'}</span>
                    <span className="text-text-muted text-xs ml-2">
                      Created {new Date(t.createdAt).toLocaleDateString()}
                    </span>
                    {t.lastUsedAt && (
                      <span className="text-text-muted text-xs ml-2">
                        Last used {new Date(t.lastUsedAt).toLocaleDateString()}
                        {t.lastUsedClient ? ` by ${t.lastUsedClient}` : ''}
                        {t.lastUsedIp ? ` from ${t.lastUsedIp}` : ''}
                      </span>
                    )}
                    {t.boundClient && (
                      <span className="text-text-muted text-xs ml-2" title="Requests from any other client are refused">
                        Bound to {t.boundClient}
                      </span>
                    )}
                    {t.lastRefused && (
                      <span className="block text-danger text-xs">
                        Refused {t.lastRefused.client ? `use by ${t.lastRefused.client}` : 'a use with no client name'}
                        {t.lastRefused.ip ? ` from ${t.lastRefused.ip}` : ''} on {new Date(t.lastRefused.at).toLocaleString()}.
                        If that wasn't you moving this agent, revoke the token.
                      </span>
                    )}
                  </div>
                  <div className="flex shrink-0">
                    {t.boundClient && (
                      <button
                        onClick={() => handleClearBinding(t.id)}
                        className="min-h-11 md:min-h-8 px-2 text-text-muted text-xs hover:underline"
                        title="The next client that uses the token binds it again"
                      >
                        Clear binding
                      </button>
                    )}
                    <button
                      onClick={() => handleRevokeToken(t.id)}
                      className="min-h-11 md:min-h-8 px-2 text-danger text-xs hover:underline"
                    >
                      Revoke
                    </button>
                  </div>
                </div>
              ))}
              {revokedTokens.map((t) => (
                <div key={t.id} className="flex items-center px-2 py-1.5 rounded bg-surface text-sm opacity-50">
                  <span className="text-text line-through">{t.name || 'Unnamed'}</span>
                  <span className="text-text-muted text-xs ml-2">Revoked</span>
                </div>
              ))}
            </div>
          )}

          <CreateTokenModal
            serverId={serverId}
            botId={botId}
            isOpen={showCreateToken}
            onClose={() => setShowCreateToken(false)}
            onCreated={async () => {
              const t = await botApi.listTokens(serverId, botId);
              setTokens(t);
            }}
          />
        </section>
      )}

      {/* ── Delete Bot ── */}
      <div className="pt-2 border-t border-border">
        <Button variant="danger" onClick={handleDelete} loading={deleting}>
          Delete Bot
        </Button>
      </div>
    </div>
  );
}

import { memo, useCallback, useDeferredValue, useEffect, useMemo, useRef, useState } from 'react';
import { Link } from 'react-router-dom';
import { defaultRangeExtractor, useVirtualizer } from '@tanstack/react-virtual';
import { Avatar } from '../../components/ui/Avatar';
import { useServerStore } from '../../stores/serverStore';
import { useChannelStore } from '../../stores/channelStore';
import { botApi, serverApi, runtimeApi, ApiError } from '../../lib/api';
import type { Bot, BotDetail, BotToken, RuntimeAccess } from '../../lib/api';
import type { Channel } from '../../lib/contracts/server';
import { Button } from '../../components/ui/Button';
import { CreateBotModal } from './CreateBotModal';
import { CreateTokenModal } from './CreateTokenModal';
import { CreateAgentInviteModal } from './CreateAgentInviteModal';

export function BotManagement() {
  const instanceServerId = useServerStore(s => s.instanceServerId);
  const [bots, setBots] = useState<Bot[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [permissionDenied, setPermissionDenied] = useState(false);
  const [showCreateBot, setShowCreateBot] = useState(false);
  const [showInvite, setShowInvite] = useState(false);
  const [expandedBotId, setExpandedBotId] = useState<string | null>(null);
  const [query, setQuery] = useState('');
  let deferredQuery = useDeferredValue(query);

  const fetchBots = useCallback(async (showLoading = true) => {
    if (!instanceServerId) return;
    if (showLoading) setLoading(true);
    setError('');
    try {
      const data = await botApi.list(instanceServerId);
      setBots(data);
      setPermissionDenied(false);
    } catch (err) {
      if (err instanceof ApiError && err.status === 403) {
        setPermissionDenied(true);
      } else {
        setError(err instanceof ApiError ? err.code : 'Failed to load bots');
      }
    } finally {
      setLoading(false);
    }
  }, [instanceServerId]);

  useEffect(() => { fetchBots(); }, [fetchBots]);

  // A refresh after a change keeps the list (and its scroll position) on screen
  const refresh = useCallback(() => { void fetchBots(false); }, [fetchBots]);
  const toggle = useCallback((botId: string) => setExpandedBotId(cur => (cur === botId ? null : botId)), []);

  // Newest first, so a bot you just created is at the top of a long list
  const sorted = useMemo(() => [...bots].sort((a, b) => b.createdAt.localeCompare(a.createdAt)), [bots]);
  const shown = useMemo(() => {
    const q = deferredQuery.trim().toLowerCase();
    return q ? sorted.filter(b => b.username.toLowerCase().includes(q)) : sorted;
  }, [sorted, deferredQuery]);

  if (!instanceServerId) return null;

  if (permissionDenied) {
    return (
      <div>
        <h2 className="text-xl font-bold text-text mb-4">Bot Management</h2>
        <p className="text-text-muted mb-4">You don't have permission to manage bots.</p>
        <Link to="/app" className="hidden min-h-11 items-center text-primary-text hover:underline sm:inline-flex md:min-h-8">Back to chat</Link>
      </div>
    );
  }

  if (loading) {
    return <p className="text-text-muted">Loading bots...</p>;
  }

  return (
    <div>
      <div className="flex flex-wrap items-center justify-between gap-3 mb-6">
        <h2 className="text-xl font-bold text-text">Bot Management</h2>
        <div className="flex gap-2">
          <Button onClick={() => setShowInvite(true)}>Invite Agent</Button>
          <Button variant="secondary" onClick={() => setShowCreateBot(true)}>Create Bot</Button>
        </div>
      </div>

      {error && <p className="text-danger text-sm mb-4">{error}</p>}

      <ChannelLoopGuardSection serverId={instanceServerId} />

      {bots.length === 0 ? (
        <p className="text-text-muted">No bots yet. Create one to get started.</p>
      ) : (
        <section>
          <div className="flex flex-wrap items-center gap-3 mb-2">
            <input
              type="search"
              value={query}
              onChange={e => setQuery(e.target.value)}
              placeholder="Search bots"
              aria-label="Search bots"
              className="min-h-11 md:min-h-9 w-full max-w-xs px-3 py-1.5 rounded border border-border bg-surface text-text placeholder:text-text-muted/70 text-sm"
            />
            <span className="text-text-muted text-xs" aria-live="polite">
              {shown.length === bots.length ? `${bots.length} bots` : `${shown.length} of ${bots.length} bots`}
            </span>
          </div>
          {shown.length === 0 ? (
            <p className="text-text-muted text-sm">No bots match “{deferredQuery.trim()}”.</p>
          ) : (
            <BotList
              bots={shown}
              serverId={instanceServerId}
              expandedBotId={expandedBotId}
              onToggle={toggle}
              onChanged={refresh}
            />
          )}
        </section>
      )}

      <CreateBotModal
        serverId={instanceServerId}
        isOpen={showCreateBot}
        onClose={() => setShowCreateBot(false)}
        onCreated={refresh}
      />
      {showInvite && <CreateAgentInviteModal serverId={instanceServerId} onClose={() => setShowInvite(false)} onCreated={refresh} />}
    </div>
  );
}

// ─── Bot List (virtualized) ───────────────────────────────────────────────

/** Rendering every bot stalled the page at about 1,800 bots (#241): only the rows in view are mounted. */
function BotList({
  bots,
  serverId,
  expandedBotId,
  onToggle,
  onChanged,
}: {
  bots: Bot[];
  serverId: string;
  expandedBotId: string | null;
  onToggle: (botId: string) => void;
  onChanged: () => void;
}) {
  const scrollRef = useRef<HTMLDivElement>(null);
  const expandedIndex = expandedBotId ? bots.findIndex(b => b.id === expandedBotId) : -1;
  // This component is not compiled by the React Compiler; the virtualizer is read during render only
  // eslint-disable-next-line react-hooks/incompatible-library
  const virtualizer = useVirtualizer({
    count: bots.length,
    getScrollElement: () => scrollRef.current,
    estimateSize: () => 60,
    overscan: 8,
    getItemKey: index => bots[index].id,
    // The open bot stays mounted while scrolled away, so its panel (a half-made token, an error) survives
    rangeExtractor: range => {
      const indexes = defaultRangeExtractor(range);
      return expandedIndex < 0 || indexes.includes(expandedIndex) ? indexes : [...indexes, expandedIndex].sort((a, b) => a - b);
    },
  });

  return (
    <div ref={scrollRef} data-testid="bot-list" className="max-h-[70vh] overflow-y-auto overscroll-contain">
      <div className="relative w-full" style={{ height: virtualizer.getTotalSize() }}>
        {virtualizer.getVirtualItems().map(item => {
          const bot = bots[item.index];
          return (
            <div
              key={item.key}
              data-index={item.index}
              ref={virtualizer.measureElement}
              className="absolute left-0 top-0 w-full pb-2"
              style={{ transform: `translateY(${item.start}px)` }}
            >
              <BotRow
                bot={bot}
                serverId={serverId}
                isExpanded={expandedBotId === bot.id}
                onToggle={onToggle}
                onChanged={onChanged}
              />
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ─── Channel Loop Guard Settings ──────────────────────────────────────────

type GuardField = 'maxBotHops' | 'maxThreadBotHops';
type Limits = Record<GuardField, number>;
/** The limit a guard gets when it is switched on with no earlier value to restore. */
const GUARD_DEFAULT: Limits = { maxBotHops: 4, maxThreadBotHops: 4 };

/**
 * Both loop guards per channel (#23): the channel guard (top-level bot messages in a row)
 * and the thread guard (bot replies in a row inside one thread). Each has an on/off switch;
 * off is a limit of 0.
 */
function ChannelLoopGuardSection({ serverId }: { serverId: string }) {
  const [channels, setChannels] = useState<Channel[]>([]);
  // Limits as loaded or last confirmed by a save here
  const [loaded, setLoaded] = useState<Record<string, Limits>>({});
  // Edits not yet confirmed by the server, by `${channelId}:${field}`
  const [dirty, setDirty] = useState<Record<string, number>>({});
  const [saving, setSaving] = useState<Record<string, boolean>>({});
  const [error, setError] = useState('');
  // A change made elsewhere (a notice's Raise limit or Turn off) arrives as ChannelBotConfig
  const live = useChannelStore(s => s.channels);
  const pending = useRef<Record<string, { timer: ReturnType<typeof setTimeout>; value: number }>>({});
  // Saves of one field go out one at a time, in order, so the last change made wins
  const queues = useRef<Record<string, Promise<void>>>({});
  // The last limit above 0, restored when a guard is switched back on
  const lastOn = useRef<Record<string, number>>({});
  const mounted = useRef(true);

  useEffect(() => {
    serverApi.getChannels(serverId).then((chs) => {
      const textChannels = chs.filter(c => c.channelType === 3);
      setChannels(textChannels);
      const initial: Record<string, Limits> = {};
      for (const ch of textChannels) {
        initial[ch.id] = { maxBotHops: ch.maxBotHops ?? 4, maxThreadBotHops: ch.maxThreadBotHops ?? 0 };
      }
      setLoaded(initial);
    }).catch(() => setError('Failed to load channels'));
  }, [serverId]);

  // enqueue only touches refs and state setters, so the first render's copy stays valid for the unmount flush
  const enqueueOnLeave = useRef(enqueue);

  // Leaving the page sends a change still waiting out its debounce instead of dropping it,
  // behind any save of that field still in flight so the older one cannot land last
  useEffect(() => {
    mounted.current = true;
    const waiting = pending.current;
    const flush = enqueueOnLeave.current;
    return () => {
      mounted.current = false;
      for (const [key, p] of Object.entries(waiting)) {
        clearTimeout(p.timer);
        delete waiting[key];
        const [channelId, field] = key.split(':') as [string, GuardField];
        flush(channelId, field, p.value);
      }
    };
  }, []);

  const shown = (channelId: string, field: GuardField): number => {
    const key = `${channelId}:${field}`;
    return dirty[key] ?? live.get(channelId)?.[field] ?? loaded[channelId]?.[field] ?? GUARD_DEFAULT[field];
  };

  function change(channelId: string, field: GuardField, value: number, delay: number) {
    const key = `${channelId}:${field}`;
    const prev = shown(channelId, field);
    if (prev > 0) lastOn.current[key] = prev;
    setDirty(d => ({ ...d, [key]: value }));
    if (pending.current[key]) clearTimeout(pending.current[key].timer);
    const timer = setTimeout(() => {
      delete pending.current[key];
      enqueue(channelId, field, value);
    }, delay);
    pending.current[key] = { timer, value };
  }

  /** Queues a save behind any earlier save of the same field (save never rejects). */
  function enqueue(channelId: string, field: GuardField, value: number) {
    const key = `${channelId}:${field}`;
    queues.current[key] = (queues.current[key] ?? Promise.resolve()).then(() => save(channelId, field, value));
  }

  function handleNumber(channelId: string, field: GuardField, raw: string) {
    const num = parseInt(raw, 10);
    // 0 would be "off": that is the switch's job, so the box keeps a limit while typing
    if (isNaN(num) || num < 1 || num > 1000) return;
    change(channelId, field, num, 600);
  }

  function handleToggle(channelId: string, field: GuardField, on: boolean) {
    const restore = lastOn.current[`${channelId}:${field}`] ?? GUARD_DEFAULT[field];
    change(channelId, field, on ? restore : 0, 0);
  }

  async function save(channelId: string, field: GuardField, value: number) {
    const key = `${channelId}:${field}`;
    if (mounted.current) { setSaving(s => ({ ...s, [key]: true })); setError(''); }
    // Only the latest edit clears the dirty value; an older save finishing must not
    const settle = (d: Record<string, number>) => {
      if (d[key] !== value || pending.current[key]) return d;
      const next = { ...d };
      delete next[key];
      return next;
    };
    try {
      const config = await botApi.updateChannelBotConfig(channelId, { [field]: value });
      useChannelStore.getState().patchChannel(channelId, { maxBotHops: config.maxBotHops, maxThreadBotHops: config.maxThreadBotHops });
      if (!mounted.current) return;
      setLoaded(l => ({ ...l, [channelId]: { maxBotHops: config.maxBotHops, maxThreadBotHops: config.maxThreadBotHops } }));
      setDirty(settle);
    } catch (err) {
      if (!mounted.current) return;
      // Show what the server still has, not the value that failed
      setDirty(settle);
      setError(err instanceof ApiError ? err.code : 'Failed to save');
    } finally {
      if (mounted.current) setSaving(s => ({ ...s, [key]: false }));
    }
  }

  if (channels.length === 0) return null;

  const guard = (ch: Channel, field: GuardField, label: string, unit: string) => {
    const value = shown(ch.id, field);
    const on = value > 0;
    const key = `${ch.id}:${field}`;
    return (
      <div className="flex items-center gap-2">
        <label className="min-h-11 md:min-h-8 flex items-center gap-1.5 text-xs text-text-muted cursor-pointer">
          <input
            type="checkbox"
            role="switch"
            checked={on}
            onChange={e => handleToggle(ch.id, field, e.target.checked)}
            aria-label={`${label} loop guard in #${ch.name}`}
            className="accent-primary"
          />
          {label}
        </label>
        {on ? (
          <input
            type="number"
            min={1}
            max={1000}
            value={value}
            onChange={e => handleNumber(ch.id, field, e.target.value)}
            aria-label={`${label} limit in #${ch.name} (${unit})`}
            title={`Pause after this many ${unit} in a row`}
            className="min-h-11 md:min-h-8 w-16 px-2 py-1 rounded border border-border bg-surface text-text text-sm text-right"
          />
        ) : (
          <span className="w-16 text-text-muted text-xs">Off</span>
        )}
        <span className="w-12 text-text-muted text-xs" aria-live="polite">{saving[key] ? 'Saving…' : ''}</span>
      </div>
    );
  };

  return (
    <section className="mb-6">
      <h3 className="text-sm font-semibold text-text mb-2">Loop Guard</h3>
      <p className="text-text-muted text-xs mb-3">
        Pauses agents after this many bot posts in a row with no human message. The channel guard counts top-level
        messages; the thread guard counts replies inside each thread. A human message resets both, and the notice
        it posts has Continue, Raise limit and Turn off buttons.
      </p>
      {error && <p className="text-danger text-xs mb-2" role="alert">{error}</p>}
      <div className="flex flex-col gap-1">
        {channels.map((ch) => (
          <div key={ch.id} className="flex flex-wrap items-center gap-x-6 gap-y-1 px-2 py-1.5 rounded hover:bg-surface-hover">
            <span className="flex min-w-32 flex-1 items-center gap-1 text-sm">
              <span className="text-text-muted">#</span>
              <span className="text-text">{ch.name}</span>
            </span>
            {guard(ch, 'maxBotHops', 'Channel', 'bot messages')}
            {guard(ch, 'maxThreadBotHops', 'Threads', 'bot replies in one thread')}
          </div>
        ))}
      </div>
    </section>
  );
}

// ─── Bot Row (expandable) ─────────────────────────────────────────────────

// Memoized with stable callbacks: opening one bot re-renders that row, not the whole list
const BotRow = memo(function BotRow({
  bot,
  serverId,
  isExpanded,
  onToggle,
  onChanged,
}: {
  bot: Bot;
  serverId: string;
  isExpanded: boolean;
  onToggle: (botId: string) => void;
  onChanged: () => void;
}) {
  const [pausing, setPausing] = useState(false);
  const [pauseError, setPauseError] = useState('');
  const [savingAccess, setSavingAccess] = useState(false);
  const isPaused = !!bot.pausedAt;

  async function changeAccess(access: RuntimeAccess) {
    if (access === 'auto' && !confirm(`Let ${bot.username} run code without approval? Runs still execute in the sandbox with its limits.`)) return;
    setSavingAccess(true);
    setPauseError('');
    try {
      await runtimeApi.setBotAccess(serverId, bot.id, access);
      onChanged();
    } catch (err) {
      setPauseError(err instanceof ApiError ? err.code : 'Failed to update code run access');
    } finally {
      setSavingAccess(false);
    }
  }

  async function togglePause() {
    setPausing(true);
    setPauseError('');
    try {
      if (isPaused) {
        await botApi.setPaused(serverId, bot.id, false);
      } else {
        const reason = prompt('Pause this bot? It will be read-only until resumed.\n\nReason (optional):');
        if (reason === null) return;
        await botApi.setPaused(serverId, bot.id, true, reason.trim() || undefined);
      }
      onChanged();
    } catch (err) {
      setPauseError(err instanceof ApiError ? err.code : 'Failed to update pause state');
    } finally {
      setPausing(false);
    }
  }

  return (
    <div className="border border-border rounded-lg overflow-hidden">
      <div className="flex items-center hover:bg-surface-hover">
      <button
        onClick={() => onToggle(bot.id)}
        aria-expanded={isExpanded}
        className="min-h-11 flex-1 flex items-center justify-between px-4 py-3 text-left"
      >
        <div>
          <span className="text-text font-medium">{bot.username}</span>
          {isPaused && (
            <span
              className="ml-2 inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-semibold leading-none bg-warn/20 text-warn"
              title={bot.pausedReason ? `Paused: ${bot.pausedReason}` : 'Paused'}
            >
              PAUSED
            </span>
          )}
          <span className="text-text-muted text-xs ml-2">
            {new Date(bot.createdAt).toLocaleDateString()}
          </span>
          {pauseError && <span className="text-danger text-xs ml-2">{pauseError}</span>}
        </div>
        <svg
          className="h-4 w-4 text-text-muted transition-transform"
          style={{ transform: isExpanded ? 'rotate(180deg)' : 'rotate(0deg)' }}
          fill="none"
          viewBox="0 0 24 24"
          stroke="currentColor"
          strokeWidth="2"
        >
          <polyline points="6 9 12 15 18 9" />
        </svg>
      </button>
      <label className="flex items-center gap-1 pr-3 text-xs text-text-muted" title="Whether this bot may run code in the sandbox">
        Code runs
        <select
          className="min-h-11 md:min-h-8 bg-surface border border-border rounded px-2 py-1 text-xs text-text"
          value={bot.runtimeAccess ?? 'none'}
          disabled={savingAccess}
          onChange={e => changeAccess(e.target.value as RuntimeAccess)}
          aria-label={`Code run access for ${bot.username}`}
        >
          <option value="none">Off</option>
          <option value="approval">Need approval</option>
          <option value="auto">Auto-run</option>
        </select>
      </label>
      <div className="pr-3">
        <Button variant="secondary" onClick={togglePause} loading={pausing}>
          {isPaused ? 'Resume' : 'Pause'}
        </Button>
      </div>
      </div>
      {isExpanded && (
        <BotDetailPanel botId={bot.id} serverId={serverId} onDeleted={onChanged} />
      )}
    </div>
  );
});

// ─── Bot Detail Panel ─────────────────────────────────────────────────────

function BotDetailPanel({
  botId,
  serverId,
  onDeleted,
}: {
  botId: string;
  serverId: string;
  onDeleted: () => void;
}) {
  const [detail, setDetail] = useState<BotDetail | null>(null);
  const [allChannels, setAllChannels] = useState<Channel[]>([]);
  const [tokens, setTokens] = useState<BotToken[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [showCreateToken, setShowCreateToken] = useState(false);
  const [showInvite, setShowInvite] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [channelLoading, setChannelLoading] = useState<string | null>(null);
  const [avatarInput, setAvatarInput] = useState('');
  const [avatarSaving, setAvatarSaving] = useState(false);
  const [avatarError, setAvatarError] = useState('');

  const fetchDetail = useCallback(async () => {
    try {
      const [d, channels] = await Promise.all([
        botApi.get(serverId, botId),
        serverApi.getChannels(serverId),
      ]);
      setDetail(d);
      setAvatarInput(d.avatarUrl || '');
      // Only show text channels (type 3) for bot access
      setAllChannels(channels.filter(c => c.channelType === 3));
      if (d.canManageTokens) {
        const t = await botApi.listTokens(serverId, botId);
        setTokens(t);
      }
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to load bot details');
    } finally {
      setLoading(false);
    }
  }, [serverId, botId]);

  useEffect(() => { fetchDetail(); }, [fetchDetail]);

  async function handleDelete() {
    if (!confirm('Delete this bot? This cannot be undone.')) return;
    setDeleting(true);
    try {
      await botApi.remove(serverId, botId);
      onDeleted();
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to delete bot');
      setDeleting(false);
    }
  }

  async function handleRevokeToken(tokenId: string) {
    try {
      await botApi.revokeToken(serverId, botId, tokenId);
      setTokens(prev => prev.map(t => t.id === tokenId ? { ...t, revokedAt: new Date().toISOString() } : t));
    } catch (err) {
      if (err instanceof ApiError && err.status === 403) {
        // Permissions changed — refetch detail
        fetchDetail();
      }
      setError(err instanceof ApiError ? err.code : 'Failed to revoke token');
    }
  }

  async function handleClearBinding(tokenId: string) {
    try {
      await botApi.clearTokenBinding(serverId, botId, tokenId);
      setTokens(prev => prev.map(t => t.id === tokenId ? { ...t, boundClient: null, boundAt: null, lastRefused: null } : t));
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to clear the binding');
    }
  }

  async function toggleDirect(channelId: string, canDirect: boolean) {
    setChannelLoading(channelId);
    setError('');
    try {
      await botApi.setCanDirect(channelId, botId, !canDirect);
      setDetail(await botApi.get(serverId, botId));
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to update who may direct');
    } finally {
      setChannelLoading(null);
    }
  }

  async function toggleChannel(channelId: string, hasAccess: boolean) {
    setChannelLoading(channelId);
    try {
      if (hasAccess) {
        await botApi.revokeChannel(channelId, botId);
      } else {
        await botApi.grantChannel(channelId, botId);
      }
      // Refetch detail to get updated channel list
      const d = await botApi.get(serverId, botId);
      setDetail(d);
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to update channel access');
    } finally {
      setChannelLoading(null);
    }
  }

  if (loading) {
    return <div className="px-4 py-3 border-t border-border text-text-muted text-sm">Loading...</div>;
  }

  if (error && !detail) {
    return <div className="px-4 py-3 border-t border-border text-danger text-sm">{error}</div>;
  }

  if (!detail) return null;

  const botChannelIds = new Set(detail.channels.map(c => c.id));
  const directChannelIds = new Set(detail.channels.filter(c => c.canDirect).map(c => c.id));
  const activeTokens = tokens.filter(t => !t.revokedAt);
  const revokedTokens = tokens.filter(t => t.revokedAt);

  return (
    <div className="border-t border-border px-4 py-4 flex flex-col gap-5 bg-bg/50">
      {error && <p className="text-danger text-sm">{error}</p>}

      {/* ── Avatar ── */}
      <section>
        <h4 className="text-sm font-semibold text-text mb-2">Avatar</h4>
        <div className="flex items-start gap-3">
          <Avatar userId={botId} username={detail.username} avatarUrl={detail.avatarUrl} className="h-12 w-12 text-sm" />
          <div className="flex-1 min-w-0">
            <input
              type="text"
              value={avatarInput}
              onChange={(e) => { setAvatarInput(e.target.value); setAvatarError(''); }}
              placeholder="data:image/svg+xml;base64,..."
              className="min-h-11 md:min-h-9 w-full px-3 py-1.5 rounded border border-border bg-surface text-text placeholder:text-text-muted/70 text-sm"
            />
            {avatarError && <p className="text-danger text-xs mt-1">{avatarError}</p>}
            <div className="flex gap-2 mt-2">
              <Button
                variant="secondary"
                className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
                loading={avatarSaving}
                onClick={async () => {
                  setAvatarSaving(true);
                  setAvatarError('');
                  try {
                    const res = await botApi.update(serverId, botId, { avatarUrl: avatarInput || null });
                    setDetail(prev => prev ? { ...prev, avatarUrl: res.avatarUrl } : prev);
                  } catch (err) {
                    setAvatarError(err instanceof ApiError ? err.code : 'Failed to save avatar');
                  } finally {
                    setAvatarSaving(false);
                  }
                }}
              >
                Save Avatar
              </Button>
              {detail.avatarUrl && (
                <Button
                  variant="secondary"
                  className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
                  onClick={async () => {
                    setAvatarSaving(true);
                    setAvatarError('');
                    try {
                      const res = await botApi.update(serverId, botId, { avatarUrl: null });
                      setDetail(prev => prev ? { ...prev, avatarUrl: res.avatarUrl } : prev);
                      setAvatarInput('');
                    } catch (err) {
                      setAvatarError(err instanceof ApiError ? err.code : 'Failed to remove avatar');
                    } finally {
                      setAvatarSaving(false);
                    }
                  }}
                >
                  Remove
                </Button>
              )}
            </div>
          </div>
        </div>
      </section>

      {/* ── Channel Access ── */}
      <section>
        <h4 className="text-sm font-semibold text-text mb-2">Channel Access</h4>
        {allChannels.length === 0 ? (
          <p className="text-text-muted text-xs">No text channels found.</p>
        ) : (
          <div className="flex flex-col gap-1">
            {allChannels.map((ch) => {
              const hasAccess = botChannelIds.has(ch.id);
              const isLoading = channelLoading === ch.id;
              return (
                <label
                  key={ch.id}
                  className="min-h-11 md:min-h-9 flex items-center gap-2 px-2 py-1.5 rounded hover:bg-surface-hover cursor-pointer text-sm"
                >
                  <input
                    type="checkbox"
                    checked={hasAccess}
                    disabled={isLoading}
                    onChange={() => toggleChannel(ch.id, hasAccess)}
                    className="accent-primary"
                  />
                  <span className="text-text-muted">#</span>
                  <span className="text-text">{ch.name}</span>
                  {isLoading && <span className="text-text-muted text-xs ml-auto">...</span>}
                  {hasAccess && (
                    <span
                      className="ml-auto flex items-center gap-1 text-xs text-text-muted"
                      title="Lets this bot give other agents instructions in this channel. Only the server owner can change it."
                      onClick={(e) => e.stopPropagation()}
                    >
                      <input
                        type="checkbox"
                        checked={directChannelIds.has(ch.id)}
                        disabled={isLoading}
                        onChange={() => toggleDirect(ch.id, directChannelIds.has(ch.id))}
                        className="accent-primary"
                      />
                      can direct agents
                    </span>
                  )}
                </label>
              );
            })}
          </div>
        )}
      </section>

      {/* ── Tokens (owner / admin only) ── */}
      {detail.canManageTokens && (
        <section>
          <Button onClick={() => setShowInvite(true)}>Invite Agent</Button>
          {showInvite && <CreateAgentInviteModal serverId={serverId} botId={botId} onClose={() => setShowInvite(false)} onCreated={() => {}} />}
          <div className="flex items-center justify-between mb-2">
            <h4 className="text-sm font-semibold text-text">Tokens</h4>
            <Button
              variant="secondary"
              className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
              onClick={() => setShowCreateToken(true)}
            >
              New Token
            </Button>
          </div>
          {activeTokens.length === 0 && revokedTokens.length === 0 ? (
            <p className="text-text-muted text-xs">No tokens yet.</p>
          ) : (
            <div className="flex flex-col gap-1">
              {activeTokens.map((t) => (
                <div key={t.id} className="flex items-center justify-between px-2 py-1.5 rounded bg-surface text-sm">
                  <div>
                    <span className="text-text">{t.name || 'Unnamed'}</span>
                    <span className="text-text-muted text-xs ml-2">
                      Created {new Date(t.createdAt).toLocaleDateString()}
                    </span>
                    {t.lastUsedAt && (
                      <span className="text-text-muted text-xs ml-2">
                        Last used {new Date(t.lastUsedAt).toLocaleDateString()}
                        {t.lastUsedClient ? ` by ${t.lastUsedClient}` : ''}
                        {t.lastUsedIp ? ` from ${t.lastUsedIp}` : ''}
                      </span>
                    )}
                    {t.boundClient && (
                      <span className="text-text-muted text-xs ml-2" title="Requests from any other client are refused">
                        Bound to {t.boundClient}
                      </span>
                    )}
                    {t.lastRefused && (
                      <span className="block text-danger text-xs">
                        Refused {t.lastRefused.client ? `use by ${t.lastRefused.client}` : 'a use with no client name'}
                        {t.lastRefused.ip ? ` from ${t.lastRefused.ip}` : ''} on {new Date(t.lastRefused.at).toLocaleString()}.
                        If that wasn't you moving this agent, revoke the token.
                      </span>
                    )}
                  </div>
                  <div className="flex shrink-0">
                    {t.boundClient && (
                      <button
                        onClick={() => handleClearBinding(t.id)}
                        className="min-h-11 md:min-h-8 px-2 text-text-muted text-xs hover:underline"
                        title="The next client that uses the token binds it again"
                      >
                        Clear binding
                      </button>
                    )}
                    <button
                      onClick={() => handleRevokeToken(t.id)}
                      className="min-h-11 md:min-h-8 px-2 text-danger text-xs hover:underline"
                    >
                      Revoke
                    </button>
                  </div>
                </div>
              ))}
              {revokedTokens.map((t) => (
                <div key={t.id} className="flex items-center px-2 py-1.5 rounded bg-surface text-sm opacity-50">
                  <span className="text-text line-through">{t.name || 'Unnamed'}</span>
                  <span className="text-text-muted text-xs ml-2">Revoked</span>
                </div>
              ))}
            </div>
          )}

          <CreateTokenModal
            serverId={serverId}
            botId={botId}
            isOpen={showCreateToken}
            onClose={() => setShowCreateToken(false)}
            onCreated={async () => {
              const t = await botApi.listTokens(serverId, botId);
              setTokens(t);
            }}
          />
        </section>
      )}

      {/* ── Delete Bot ── */}
      <div className="pt-2 border-t border-border">
        <Button variant="danger" onClick={handleDelete} loading={deleting}>
          Delete Bot
        </Button>
      </div>
    </div>
  );
}

import { memo, useCallback, useDeferredValue, useEffect, useMemo, useRef, useState } from 'react';
import { Link } from 'react-router-dom';
import { defaultRangeExtractor, useVirtualizer } from '@tanstack/react-virtual';
import { Avatar } from '../../components/ui/Avatar';
import { useServerStore } from '../../stores/serverStore';
import { useChannelStore } from '../../stores/channelStore';
import { botApi, serverApi, runtimeApi, ApiError } from '../../lib/api';
import type { Bot, BotDetail, BotToken, RuntimeAccess } from '../../lib/api';
import type { Channel } from '../../lib/contracts/server';
import { Button } from '../../components/ui/Button';
import { CreateBotModal } from './CreateBotModal';
import { CreateTokenModal } from './CreateTokenModal';
import { CreateAgentInviteModal } from './CreateAgentInviteModal';

export function BotManagement() {
  const instanceServerId = useServerStore(s => s.instanceServerId);
  const [bots, setBots] = useState<Bot[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [permissionDenied, setPermissionDenied] = useState(false);
  const [showCreateBot, setShowCreateBot] = useState(false);
  const [showInvite, setShowInvite] = useState(false);
  const [expandedBotId, setExpandedBotId] = useState<string | null>(null);
  const [query, setQuery] = useState('');
  const deferredQuery = useDeferredValue(query);

  let fetchBots = useCallback(async (showLoading = true) => {
    if (!instanceServerId) return;
    if (showLoading) setLoading(true);
    setError('');
    try {
      const data = await botApi.list(instanceServerId);
      setBots(data);
      setPermissionDenied(false);
    } catch (err) {
      if (err instanceof ApiError && err.status === 403) {
        setPermissionDenied(true);
      } else {
        setError(err instanceof ApiError ? err.code : 'Failed to load bots');
      }
    } finally {
      setLoading(false);
    }
  }, [instanceServerId]);

  useEffect(() => { fetchBots(); }, [fetchBots]);

  // A refresh after a change keeps the list (and its scroll position) on screen
  const refresh = useCallback(() => { void fetchBots(false); }, [fetchBots]);
  const toggle = useCallback((botId: string) => setExpandedBotId(cur => (cur === botId ? null : botId)), []);

  // Newest first, so a bot you just created is at the top of a long list
  const sorted = useMemo(() => [...bots].sort((a, b) => b.createdAt.localeCompare(a.createdAt)), [bots]);
  const shown = useMemo(() => {
    const q = deferredQuery.trim().toLowerCase();
    return q ? sorted.filter(b => b.username.toLowerCase().includes(q)) : sorted;
  }, [sorted, deferredQuery]);

  if (!instanceServerId) return null;

  if (permissionDenied) {
    return (
      <div>
        <h2 className="text-xl font-bold text-text mb-4">Bot Management</h2>
        <p className="text-text-muted mb-4">You don't have permission to manage bots.</p>
        <Link to="/app" className="hidden min-h-11 items-center text-primary-text hover:underline sm:inline-flex md:min-h-8">Back to chat</Link>
      </div>
    );
  }

  if (loading) {
    return <p className="text-text-muted">Loading bots...</p>;
  }

  return (
    <div>
      <div className="flex flex-wrap items-center justify-between gap-3 mb-6">
        <h2 className="text-xl font-bold text-text">Bot Management</h2>
        <div className="flex gap-2">
          <Button onClick={() => setShowInvite(true)}>Invite Agent</Button>
          <Button variant="secondary" onClick={() => setShowCreateBot(true)}>Create Bot</Button>
        </div>
      </div>

      {error && <p className="text-danger text-sm mb-4">{error}</p>}

      <ChannelLoopGuardSection serverId={instanceServerId} />

      {bots.length === 0 ? (
        <p className="text-text-muted">No bots yet. Create one to get started.</p>
      ) : (
        <section>
          <div className="flex flex-wrap items-center gap-3 mb-2">
            <input
              type="search"
              value={query}
              onChange={e => setQuery(e.target.value)}
              placeholder="Search bots"
              aria-label="Search bots"
              className="min-h-11 md:min-h-9 w-full max-w-xs px-3 py-1.5 rounded border border-border bg-surface text-text placeholder:text-text-muted/70 text-sm"
            />
            <span className="text-text-muted text-xs" aria-live="polite">
              {shown.length === bots.length ? `${bots.length} bots` : `${shown.length} of ${bots.length} bots`}
            </span>
          </div>
          {shown.length === 0 ? (
            <p className="text-text-muted text-sm">No bots match “{deferredQuery.trim()}”.</p>
          ) : (
            <BotList
              bots={shown}
              serverId={instanceServerId}
              expandedBotId={expandedBotId}
              onToggle={toggle}
              onChanged={refresh}
            />
          )}
        </section>
      )}

      <CreateBotModal
        serverId={instanceServerId}
        isOpen={showCreateBot}
        onClose={() => setShowCreateBot(false)}
        onCreated={refresh}
      />
      {showInvite && <CreateAgentInviteModal serverId={instanceServerId} onClose={() => setShowInvite(false)} onCreated={refresh} />}
    </div>
  );
}

// ─── Bot List (virtualized) ───────────────────────────────────────────────

/** Rendering every bot stalled the page at about 1,800 bots (#241): only the rows in view are mounted. */
function BotList({
  bots,
  serverId,
  expandedBotId,
  onToggle,
  onChanged,
}: {
  bots: Bot[];
  serverId: string;
  expandedBotId: string | null;
  onToggle: (botId: string) => void;
  onChanged: () => void;
}) {
  const scrollRef = useRef<HTMLDivElement>(null);
  const expandedIndex = expandedBotId ? bots.findIndex(b => b.id === expandedBotId) : -1;
  // This component is not compiled by the React Compiler; the virtualizer is read during render only
  // eslint-disable-next-line react-hooks/incompatible-library
  const virtualizer = useVirtualizer({
    count: bots.length,
    getScrollElement: () => scrollRef.current,
    estimateSize: () => 60,
    overscan: 8,
    getItemKey: index => bots[index].id,
    // The open bot stays mounted while scrolled away, so its panel (a half-made token, an error) survives
    rangeExtractor: range => {
      const indexes = defaultRangeExtractor(range);
      return expandedIndex < 0 || indexes.includes(expandedIndex) ? indexes : [...indexes, expandedIndex].sort((a, b) => a - b);
    },
  });

  return (
    <div ref={scrollRef} data-testid="bot-list" className="max-h-[70vh] overflow-y-auto overscroll-contain">
      <div className="relative w-full" style={{ height: virtualizer.getTotalSize() }}>
        {virtualizer.getVirtualItems().map(item => {
          const bot = bots[item.index];
          return (
            <div
              key={item.key}
              data-index={item.index}
              ref={virtualizer.measureElement}
              className="absolute left-0 top-0 w-full pb-2"
              style={{ transform: `translateY(${item.start}px)` }}
            >
              <BotRow
                bot={bot}
                serverId={serverId}
                isExpanded={expandedBotId === bot.id}
                onToggle={onToggle}
                onChanged={onChanged}
              />
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ─── Channel Loop Guard Settings ──────────────────────────────────────────

type GuardField = 'maxBotHops' | 'maxThreadBotHops';
type Limits = Record<GuardField, number>;
/** The limit a guard gets when it is switched on with no earlier value to restore. */
const GUARD_DEFAULT: Limits = { maxBotHops: 4, maxThreadBotHops: 4 };

/**
 * Both loop guards per channel (#23): the channel guard (top-level bot messages in a row)
 * and the thread guard (bot replies in a row inside one thread). Each has an on/off switch;
 * off is a limit of 0.
 */
function ChannelLoopGuardSection({ serverId }: { serverId: string }) {
  const [channels, setChannels] = useState<Channel[]>([]);
  // Limits as loaded or last confirmed by a save here
  const [loaded, setLoaded] = useState<Record<string, Limits>>({});
  // Edits not yet confirmed by the server, by `${channelId}:${field}`
  const [dirty, setDirty] = useState<Record<string, number>>({});
  const [saving, setSaving] = useState<Record<string, boolean>>({});
  const [error, setError] = useState('');
  // A change made elsewhere (a notice's Raise limit or Turn off) arrives as ChannelBotConfig
  const live = useChannelStore(s => s.channels);
  const pending = useRef<Record<string, { timer: ReturnType<typeof setTimeout>; value: number }>>({});
  // Saves of one field go out one at a time, in order, so the last change made wins
  const queues = useRef<Record<string, Promise<void>>>({});
  // The last limit above 0, restored when a guard is switched back on
  const lastOn = useRef<Record<string, number>>({});
  const mounted = useRef(true);

  useEffect(() => {
    serverApi.getChannels(serverId).then((chs) => {
      const textChannels = chs.filter(c => c.channelType === 3);
      setChannels(textChannels);
      const initial: Record<string, Limits> = {};
      for (const ch of textChannels) {
        initial[ch.id] = { maxBotHops: ch.maxBotHops ?? 4, maxThreadBotHops: ch.maxThreadBotHops ?? 0 };
      }
      setLoaded(initial);
    }).catch(() => setError('Failed to load channels'));
  }, [serverId]);

  // enqueue only touches refs and state setters, so the first render's copy stays valid for the unmount flush
  const enqueueOnLeave = useRef(enqueue);

  // Leaving the page sends a change still waiting out its debounce instead of dropping it,
  // behind any save of that field still in flight so the older one cannot land last
  useEffect(() => {
    mounted.current = true;
    const waiting = pending.current;
    const flush = enqueueOnLeave.current;
    return () => {
      mounted.current = false;
      for (const [key, p] of Object.entries(waiting)) {
        clearTimeout(p.timer);
        delete waiting[key];
        const [channelId, field] = key.split(':') as [string, GuardField];
        flush(channelId, field, p.value);
      }
    };
  }, []);

  const shown = (channelId: string, field: GuardField): number => {
    const key = `${channelId}:${field}`;
    return dirty[key] ?? live.get(channelId)?.[field] ?? loaded[channelId]?.[field] ?? GUARD_DEFAULT[field];
  };

  function change(channelId: string, field: GuardField, value: number, delay: number) {
    const key = `${channelId}:${field}`;
    const prev = shown(channelId, field);
    if (prev > 0) lastOn.current[key] = prev;
    setDirty(d => ({ ...d, [key]: value }));
    if (pending.current[key]) clearTimeout(pending.current[key].timer);
    const timer = setTimeout(() => {
      delete pending.current[key];
      enqueue(channelId, field, value);
    }, delay);
    pending.current[key] = { timer, value };
  }

  /** Queues a save behind any earlier save of the same field (save never rejects). */
  function enqueue(channelId: string, field: GuardField, value: number) {
    const key = `${channelId}:${field}`;
    queues.current[key] = (queues.current[key] ?? Promise.resolve()).then(() => save(channelId, field, value));
  }

  function handleNumber(channelId: string, field: GuardField, raw: string) {
    const num = parseInt(raw, 10);
    // 0 would be "off": that is the switch's job, so the box keeps a limit while typing
    if (isNaN(num) || num < 1 || num > 1000) return;
    change(channelId, field, num, 600);
  }

  function handleToggle(channelId: string, field: GuardField, on: boolean) {
    const restore = lastOn.current[`${channelId}:${field}`] ?? GUARD_DEFAULT[field];
    change(channelId, field, on ? restore : 0, 0);
  }

  async function save(channelId: string, field: GuardField, value: number) {
    const key = `${channelId}:${field}`;
    if (mounted.current) { setSaving(s => ({ ...s, [key]: true })); setError(''); }
    // Only the latest edit clears the dirty value; an older save finishing must not
    const settle = (d: Record<string, number>) => {
      if (d[key] !== value || pending.current[key]) return d;
      const next = { ...d };
      delete next[key];
      return next;
    };
    try {
      const config = await botApi.updateChannelBotConfig(channelId, { [field]: value });
      useChannelStore.getState().patchChannel(channelId, { maxBotHops: config.maxBotHops, maxThreadBotHops: config.maxThreadBotHops });
      if (!mounted.current) return;
      setLoaded(l => ({ ...l, [channelId]: { maxBotHops: config.maxBotHops, maxThreadBotHops: config.maxThreadBotHops } }));
      setDirty(settle);
    } catch (err) {
      if (!mounted.current) return;
      // Show what the server still has, not the value that failed
      setDirty(settle);
      setError(err instanceof ApiError ? err.code : 'Failed to save');
    } finally {
      if (mounted.current) setSaving(s => ({ ...s, [key]: false }));
    }
  }

  if (channels.length === 0) return null;

  const guard = (ch: Channel, field: GuardField, label: string, unit: string) => {
    const value = shown(ch.id, field);
    const on = value > 0;
    const key = `${ch.id}:${field}`;
    return (
      <div className="flex items-center gap-2">
        <label className="min-h-11 md:min-h-8 flex items-center gap-1.5 text-xs text-text-muted cursor-pointer">
          <input
            type="checkbox"
            role="switch"
            checked={on}
            onChange={e => handleToggle(ch.id, field, e.target.checked)}
            aria-label={`${label} loop guard in #${ch.name}`}
            className="accent-primary"
          />
          {label}
        </label>
        {on ? (
          <input
            type="number"
            min={1}
            max={1000}
            value={value}
            onChange={e => handleNumber(ch.id, field, e.target.value)}
            aria-label={`${label} limit in #${ch.name} (${unit})`}
            title={`Pause after this many ${unit} in a row`}
            className="min-h-11 md:min-h-8 w-16 px-2 py-1 rounded border border-border bg-surface text-text text-sm text-right"
          />
        ) : (
          <span className="w-16 text-text-muted text-xs">Off</span>
        )}
        <span className="w-12 text-text-muted text-xs" aria-live="polite">{saving[key] ? 'Saving…' : ''}</span>
      </div>
    );
  };

  return (
    <section className="mb-6">
      <h3 className="text-sm font-semibold text-text mb-2">Loop Guard</h3>
      <p className="text-text-muted text-xs mb-3">
        Pauses agents after this many bot posts in a row with no human message. The channel guard counts top-level
        messages; the thread guard counts replies inside each thread. A human message resets both, and the notice
        it posts has Continue, Raise limit and Turn off buttons.
      </p>
      {error && <p className="text-danger text-xs mb-2" role="alert">{error}</p>}
      <div className="flex flex-col gap-1">
        {channels.map((ch) => (
          <div key={ch.id} className="flex flex-wrap items-center gap-x-6 gap-y-1 px-2 py-1.5 rounded hover:bg-surface-hover">
            <span className="flex min-w-32 flex-1 items-center gap-1 text-sm">
              <span className="text-text-muted">#</span>
              <span className="text-text">{ch.name}</span>
            </span>
            {guard(ch, 'maxBotHops', 'Channel', 'bot messages')}
            {guard(ch, 'maxThreadBotHops', 'Threads', 'bot replies in one thread')}
          </div>
        ))}
      </div>
    </section>
  );
}

// ─── Bot Row (expandable) ─────────────────────────────────────────────────

// Memoized with stable callbacks: opening one bot re-renders that row, not the whole list
const BotRow = memo(function BotRow({
  bot,
  serverId,
  isExpanded,
  onToggle,
  onChanged,
}: {
  bot: Bot;
  serverId: string;
  isExpanded: boolean;
  onToggle: (botId: string) => void;
  onChanged: () => void;
}) {
  const [pausing, setPausing] = useState(false);
  const [pauseError, setPauseError] = useState('');
  const [savingAccess, setSavingAccess] = useState(false);
  const isPaused = !!bot.pausedAt;

  async function changeAccess(access: RuntimeAccess) {
    if (access === 'auto' && !confirm(`Let ${bot.username} run code without approval? Runs still execute in the sandbox with its limits.`)) return;
    setSavingAccess(true);
    setPauseError('');
    try {
      await runtimeApi.setBotAccess(serverId, bot.id, access);
      onChanged();
    } catch (err) {
      setPauseError(err instanceof ApiError ? err.code : 'Failed to update code run access');
    } finally {
      setSavingAccess(false);
    }
  }

  async function togglePause() {
    setPausing(true);
    setPauseError('');
    try {
      if (isPaused) {
        await botApi.setPaused(serverId, bot.id, false);
      } else {
        const reason = prompt('Pause this bot? It will be read-only until resumed.\n\nReason (optional):');
        if (reason === null) return;
        await botApi.setPaused(serverId, bot.id, true, reason.trim() || undefined);
      }
      onChanged();
    } catch (err) {
      setPauseError(err instanceof ApiError ? err.code : 'Failed to update pause state');
    } finally {
      setPausing(false);
    }
  }

  return (
    <div className="border border-border rounded-lg overflow-hidden">
      <div className="flex items-center hover:bg-surface-hover">
      <button
        onClick={() => onToggle(bot.id)}
        aria-expanded={isExpanded}
        className="min-h-11 flex-1 flex items-center justify-between px-4 py-3 text-left"
      >
        <div>
          <span className="text-text font-medium">{bot.username}</span>
          {isPaused && (
            <span
              className="ml-2 inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-semibold leading-none bg-warn/20 text-warn"
              title={bot.pausedReason ? `Paused: ${bot.pausedReason}` : 'Paused'}
            >
              PAUSED
            </span>
          )}
          <span className="text-text-muted text-xs ml-2">
            {new Date(bot.createdAt).toLocaleDateString()}
          </span>
          {pauseError && <span className="text-danger text-xs ml-2">{pauseError}</span>}
        </div>
        <svg
          className="h-4 w-4 text-text-muted transition-transform"
          style={{ transform: isExpanded ? 'rotate(180deg)' : 'rotate(0deg)' }}
          fill="none"
          viewBox="0 0 24 24"
          stroke="currentColor"
          strokeWidth="2"
        >
          <polyline points="6 9 12 15 18 9" />
        </svg>
      </button>
      <label className="flex items-center gap-1 pr-3 text-xs text-text-muted" title="Whether this bot may run code in the sandbox">
        Code runs
        <select
          className="min-h-11 md:min-h-8 bg-surface border border-border rounded px-2 py-1 text-xs text-text"
          value={bot.runtimeAccess ?? 'none'}
          disabled={savingAccess}
          onChange={e => changeAccess(e.target.value as RuntimeAccess)}
          aria-label={`Code run access for ${bot.username}`}
        >
          <option value="none">Off</option>
          <option value="approval">Need approval</option>
          <option value="auto">Auto-run</option>
        </select>
      </label>
      <div className="pr-3">
        <Button variant="secondary" onClick={togglePause} loading={pausing}>
          {isPaused ? 'Resume' : 'Pause'}
        </Button>
      </div>
      </div>
      {isExpanded && (
        <BotDetailPanel botId={bot.id} serverId={serverId} onDeleted={onChanged} />
      )}
    </div>
  );
});

// ─── Bot Detail Panel ─────────────────────────────────────────────────────

function BotDetailPanel({
  botId,
  serverId,
  onDeleted,
}: {
  botId: string;
  serverId: string;
  onDeleted: () => void;
}) {
  const [detail, setDetail] = useState<BotDetail | null>(null);
  const [allChannels, setAllChannels] = useState<Channel[]>([]);
  const [tokens, setTokens] = useState<BotToken[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [showCreateToken, setShowCreateToken] = useState(false);
  const [showInvite, setShowInvite] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [channelLoading, setChannelLoading] = useState<string | null>(null);
  const [avatarInput, setAvatarInput] = useState('');
  const [avatarSaving, setAvatarSaving] = useState(false);
  const [avatarError, setAvatarError] = useState('');

  const fetchDetail = useCallback(async () => {
    try {
      const [d, channels] = await Promise.all([
        botApi.get(serverId, botId),
        serverApi.getChannels(serverId),
      ]);
      setDetail(d);
      setAvatarInput(d.avatarUrl || '');
      // Only show text channels (type 3) for bot access
      setAllChannels(channels.filter(c => c.channelType === 3));
      if (d.canManageTokens) {
        const t = await botApi.listTokens(serverId, botId);
        setTokens(t);
      }
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to load bot details');
    } finally {
      setLoading(false);
    }
  }, [serverId, botId]);

  useEffect(() => { fetchDetail(); }, [fetchDetail]);

  async function handleDelete() {
    if (!confirm('Delete this bot? This cannot be undone.')) return;
    setDeleting(true);
    try {
      await botApi.remove(serverId, botId);
      onDeleted();
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to delete bot');
      setDeleting(false);
    }
  }

  async function handleRevokeToken(tokenId: string) {
    try {
      await botApi.revokeToken(serverId, botId, tokenId);
      setTokens(prev => prev.map(t => t.id === tokenId ? { ...t, revokedAt: new Date().toISOString() } : t));
    } catch (err) {
      if (err instanceof ApiError && err.status === 403) {
        // Permissions changed — refetch detail
        fetchDetail();
      }
      setError(err instanceof ApiError ? err.code : 'Failed to revoke token');
    }
  }

  async function handleClearBinding(tokenId: string) {
    try {
      await botApi.clearTokenBinding(serverId, botId, tokenId);
      setTokens(prev => prev.map(t => t.id === tokenId ? { ...t, boundClient: null, boundAt: null, lastRefused: null } : t));
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to clear the binding');
    }
  }

  async function toggleDirect(channelId: string, canDirect: boolean) {
    setChannelLoading(channelId);
    setError('');
    try {
      await botApi.setCanDirect(channelId, botId, !canDirect);
      setDetail(await botApi.get(serverId, botId));
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to update who may direct');
    } finally {
      setChannelLoading(null);
    }
  }

  async function toggleChannel(channelId: string, hasAccess: boolean) {
    setChannelLoading(channelId);
    try {
      if (hasAccess) {
        await botApi.revokeChannel(channelId, botId);
      } else {
        await botApi.grantChannel(channelId, botId);
      }
      // Refetch detail to get updated channel list
      const d = await botApi.get(serverId, botId);
      setDetail(d);
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to update channel access');
    } finally {
      setChannelLoading(null);
    }
  }

  if (loading) {
    return <div className="px-4 py-3 border-t border-border text-text-muted text-sm">Loading...</div>;
  }

  if (error && !detail) {
    return <div className="px-4 py-3 border-t border-border text-danger text-sm">{error}</div>;
  }

  if (!detail) return null;

  const botChannelIds = new Set(detail.channels.map(c => c.id));
  const directChannelIds = new Set(detail.channels.filter(c => c.canDirect).map(c => c.id));
  const activeTokens = tokens.filter(t => !t.revokedAt);
  const revokedTokens = tokens.filter(t => t.revokedAt);

  return (
    <div className="border-t border-border px-4 py-4 flex flex-col gap-5 bg-bg/50">
      {error && <p className="text-danger text-sm">{error}</p>}

      {/* ── Avatar ── */}
      <section>
        <h4 className="text-sm font-semibold text-text mb-2">Avatar</h4>
        <div className="flex items-start gap-3">
          <Avatar userId={botId} username={detail.username} avatarUrl={detail.avatarUrl} className="h-12 w-12 text-sm" />
          <div className="flex-1 min-w-0">
            <input
              type="text"
              value={avatarInput}
              onChange={(e) => { setAvatarInput(e.target.value); setAvatarError(''); }}
              placeholder="data:image/svg+xml;base64,..."
              className="min-h-11 md:min-h-9 w-full px-3 py-1.5 rounded border border-border bg-surface text-text placeholder:text-text-muted/70 text-sm"
            />
            {avatarError && <p className="text-danger text-xs mt-1">{avatarError}</p>}
            <div className="flex gap-2 mt-2">
              <Button
                variant="secondary"
                className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
                loading={avatarSaving}
                onClick={async () => {
                  setAvatarSaving(true);
                  setAvatarError('');
                  try {
                    const res = await botApi.update(serverId, botId, { avatarUrl: avatarInput || null });
                    setDetail(prev => prev ? { ...prev, avatarUrl: res.avatarUrl } : prev);
                  } catch (err) {
                    setAvatarError(err instanceof ApiError ? err.code : 'Failed to save avatar');
                  } finally {
                    setAvatarSaving(false);
                  }
                }}
              >
                Save Avatar
              </Button>
              {detail.avatarUrl && (
                <Button
                  variant="secondary"
                  className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
                  onClick={async () => {
                    setAvatarSaving(true);
                    setAvatarError('');
                    try {
                      const res = await botApi.update(serverId, botId, { avatarUrl: null });
                      setDetail(prev => prev ? { ...prev, avatarUrl: res.avatarUrl } : prev);
                      setAvatarInput('');
                    } catch (err) {
                      setAvatarError(err instanceof ApiError ? err.code : 'Failed to remove avatar');
                    } finally {
                      setAvatarSaving(false);
                    }
                  }}
                >
                  Remove
                </Button>
              )}
            </div>
          </div>
        </div>
      </section>

      {/* ── Channel Access ── */}
      <section>
        <h4 className="text-sm font-semibold text-text mb-2">Channel Access</h4>
        {allChannels.length === 0 ? (
          <p className="text-text-muted text-xs">No text channels found.</p>
        ) : (
          <div className="flex flex-col gap-1">
            {allChannels.map((ch) => {
              const hasAccess = botChannelIds.has(ch.id);
              const isLoading = channelLoading === ch.id;
              return (
                <label
                  key={ch.id}
                  className="min-h-11 md:min-h-9 flex items-center gap-2 px-2 py-1.5 rounded hover:bg-surface-hover cursor-pointer text-sm"
                >
                  <input
                    type="checkbox"
                    checked={hasAccess}
                    disabled={isLoading}
                    onChange={() => toggleChannel(ch.id, hasAccess)}
                    className="accent-primary"
                  />
                  <span className="text-text-muted">#</span>
                  <span className="text-text">{ch.name}</span>
                  {isLoading && <span className="text-text-muted text-xs ml-auto">...</span>}
                  {hasAccess && (
                    <span
                      className="ml-auto flex items-center gap-1 text-xs text-text-muted"
                      title="Lets this bot give other agents instructions in this channel. Only the server owner can change it."
                      onClick={(e) => e.stopPropagation()}
                    >
                      <input
                        type="checkbox"
                        checked={directChannelIds.has(ch.id)}
                        disabled={isLoading}
                        onChange={() => toggleDirect(ch.id, directChannelIds.has(ch.id))}
                        className="accent-primary"
                      />
                      can direct agents
                    </span>
                  )}
                </label>
              );
            })}
          </div>
        )}
      </section>

      {/* ── Tokens (owner / admin only) ── */}
      {detail.canManageTokens && (
        <section>
          <Button onClick={() => setShowInvite(true)}>Invite Agent</Button>
          {showInvite && <CreateAgentInviteModal serverId={serverId} botId={botId} onClose={() => setShowInvite(false)} onCreated={() => {}} />}
          <div className="flex items-center justify-between mb-2">
            <h4 className="text-sm font-semibold text-text">Tokens</h4>
            <Button
              variant="secondary"
              className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
              onClick={() => setShowCreateToken(true)}
            >
              New Token
            </Button>
          </div>
          {activeTokens.length === 0 && revokedTokens.length === 0 ? (
            <p className="text-text-muted text-xs">No tokens yet.</p>
          ) : (
            <div className="flex flex-col gap-1">
              {activeTokens.map((t) => (
                <div key={t.id} className="flex items-center justify-between px-2 py-1.5 rounded bg-surface text-sm">
                  <div>
                    <span className="text-text">{t.name || 'Unnamed'}</span>
                    <span className="text-text-muted text-xs ml-2">
                      Created {new Date(t.createdAt).toLocaleDateString()}
                    </span>
                    {t.lastUsedAt && (
                      <span className="text-text-muted text-xs ml-2">
                        Last used {new Date(t.lastUsedAt).toLocaleDateString()}
                        {t.lastUsedClient ? ` by ${t.lastUsedClient}` : ''}
                        {t.lastUsedIp ? ` from ${t.lastUsedIp}` : ''}
                      </span>
                    )}
                    {t.boundClient && (
                      <span className="text-text-muted text-xs ml-2" title="Requests from any other client are refused">
                        Bound to {t.boundClient}
                      </span>
                    )}
                    {t.lastRefused && (
                      <span className="block text-danger text-xs">
                        Refused {t.lastRefused.client ? `use by ${t.lastRefused.client}` : 'a use with no client name'}
                        {t.lastRefused.ip ? ` from ${t.lastRefused.ip}` : ''} on {new Date(t.lastRefused.at).toLocaleString()}.
                        If that wasn't you moving this agent, revoke the token.
                      </span>
                    )}
                  </div>
                  <div className="flex shrink-0">
                    {t.boundClient && (
                      <button
                        onClick={() => handleClearBinding(t.id)}
                        className="min-h-11 md:min-h-8 px-2 text-text-muted text-xs hover:underline"
                        title="The next client that uses the token binds it again"
                      >
                        Clear binding
                      </button>
                    )}
                    <button
                      onClick={() => handleRevokeToken(t.id)}
                      className="min-h-11 md:min-h-8 px-2 text-danger text-xs hover:underline"
                    >
                      Revoke
                    </button>
                  </div>
                </div>
              ))}
              {revokedTokens.map((t) => (
                <div key={t.id} className="flex items-center px-2 py-1.5 rounded bg-surface text-sm opacity-50">
                  <span className="text-text line-through">{t.name || 'Unnamed'}</span>
                  <span className="text-text-muted text-xs ml-2">Revoked</span>
                </div>
              ))}
            </div>
          )}

          <CreateTokenModal
            serverId={serverId}
            botId={botId}
            isOpen={showCreateToken}
            onClose={() => setShowCreateToken(false)}
            onCreated={async () => {
              const t = await botApi.listTokens(serverId, botId);
              setTokens(t);
            }}
          />
        </section>
      )}

      {/* ── Delete Bot ── */}
      <div className="pt-2 border-t border-border">
        <Button variant="danger" onClick={handleDelete} loading={deleting}>
          Delete Bot
        </Button>
      </div>
    </div>
  );
}

import { memo, useCallback, useDeferredValue, useEffect, useMemo, useRef, useState } from 'react';
import { Link } from 'react-router-dom';
import { defaultRangeExtractor, useVirtualizer } from '@tanstack/react-virtual';
import { Avatar } from '../../components/ui/Avatar';
import { useServerStore } from '../../stores/serverStore';
import { useChannelStore } from '../../stores/channelStore';
import { botApi, serverApi, runtimeApi, ApiError } from '../../lib/api';
import type { Bot, BotDetail, BotToken, RuntimeAccess } from '../../lib/api';
import type { Channel } from '../../lib/contracts/server';
import { Button } from '../../components/ui/Button';
import { CreateBotModal } from './CreateBotModal';
import { CreateTokenModal } from './CreateTokenModal';
import { CreateAgentInviteModal } from './CreateAgentInviteModal';

export function BotManagement() {
  const instanceServerId = useServerStore(s => s.instanceServerId);
  const [bots, setBots] = useState<Bot[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [permissionDenied, setPermissionDenied] = useState(false);
  const [showCreateBot, setShowCreateBot] = useState(false);
  const [showInvite, setShowInvite] = useState(false);
  const [expandedBotId, setExpandedBotId] = useState<string | null>(null);
  const [query, setQuery] = useState('');
  const deferredQuery = useDeferredValue(query);

  const fetchBots = useCallback(async (showLoading = true) => {
    if (!instanceServerId) return;
    if (showLoading) setLoading(true);
    setError('');
    try {
      let data = await botApi.list(instanceServerId);
      setBots(data);
      setPermissionDenied(false);
    } catch (err) {
      if (err instanceof ApiError && err.status === 403) {
        setPermissionDenied(true);
      } else {
        setError(err instanceof ApiError ? err.code : 'Failed to load bots');
      }
    } finally {
      setLoading(false);
    }
  }, [instanceServerId]);

  useEffect(() => { fetchBots(); }, [fetchBots]);

  // A refresh after a change keeps the list (and its scroll position) on screen
  const refresh = useCallback(() => { void fetchBots(false); }, [fetchBots]);
  const toggle = useCallback((botId: string) => setExpandedBotId(cur => (cur === botId ? null : botId)), []);

  // Newest first, so a bot you just created is at the top of a long list
  const sorted = useMemo(() => [...bots].sort((a, b) => b.createdAt.localeCompare(a.createdAt)), [bots]);
  const shown = useMemo(() => {
    const q = deferredQuery.trim().toLowerCase();
    return q ? sorted.filter(b => b.username.toLowerCase().includes(q)) : sorted;
  }, [sorted, deferredQuery]);

  if (!instanceServerId) return null;

  if (permissionDenied) {
    return (
      <div>
        <h2 className="text-xl font-bold text-text mb-4">Bot Management</h2>
        <p className="text-text-muted mb-4">You don't have permission to manage bots.</p>
        <Link to="/app" className="hidden min-h-11 items-center text-primary-text hover:underline sm:inline-flex md:min-h-8">Back to chat</Link>
      </div>
    );
  }

  if (loading) {
    return <p className="text-text-muted">Loading bots...</p>;
  }

  return (
    <div>
      <div className="flex flex-wrap items-center justify-between gap-3 mb-6">
        <h2 className="text-xl font-bold text-text">Bot Management</h2>
        <div className="flex gap-2">
          <Button onClick={() => setShowInvite(true)}>Invite Agent</Button>
          <Button variant="secondary" onClick={() => setShowCreateBot(true)}>Create Bot</Button>
        </div>
      </div>

      {error && <p className="text-danger text-sm mb-4">{error}</p>}

      <ChannelLoopGuardSection serverId={instanceServerId} />

      {bots.length === 0 ? (
        <p className="text-text-muted">No bots yet. Create one to get started.</p>
      ) : (
        <section>
          <div className="flex flex-wrap items-center gap-3 mb-2">
            <input
              type="search"
              value={query}
              onChange={e => setQuery(e.target.value)}
              placeholder="Search bots"
              aria-label="Search bots"
              className="min-h-11 md:min-h-9 w-full max-w-xs px-3 py-1.5 rounded border border-border bg-surface text-text placeholder:text-text-muted/70 text-sm"
            />
            <span className="text-text-muted text-xs" aria-live="polite">
              {shown.length === bots.length ? `${bots.length} bots` : `${shown.length} of ${bots.length} bots`}
            </span>
          </div>
          {shown.length === 0 ? (
            <p className="text-text-muted text-sm">No bots match “{deferredQuery.trim()}”.</p>
          ) : (
            <BotList
              bots={shown}
              serverId={instanceServerId}
              expandedBotId={expandedBotId}
              onToggle={toggle}
              onChanged={refresh}
            />
          )}
        </section>
      )}

      <CreateBotModal
        serverId={instanceServerId}
        isOpen={showCreateBot}
        onClose={() => setShowCreateBot(false)}
        onCreated={refresh}
      />
      {showInvite && <CreateAgentInviteModal serverId={instanceServerId} onClose={() => setShowInvite(false)} onCreated={refresh} />}
    </div>
  );
}

// ─── Bot List (virtualized) ───────────────────────────────────────────────

/** Rendering every bot stalled the page at about 1,800 bots (#241): only the rows in view are mounted. */
function BotList({
  bots,
  serverId,
  expandedBotId,
  onToggle,
  onChanged,
}: {
  bots: Bot[];
  serverId: string;
  expandedBotId: string | null;
  onToggle: (botId: string) => void;
  onChanged: () => void;
}) {
  const scrollRef = useRef<HTMLDivElement>(null);
  const expandedIndex = expandedBotId ? bots.findIndex(b => b.id === expandedBotId) : -1;
  // This component is not compiled by the React Compiler; the virtualizer is read during render only
  // eslint-disable-next-line react-hooks/incompatible-library
  const virtualizer = useVirtualizer({
    count: bots.length,
    getScrollElement: () => scrollRef.current,
    estimateSize: () => 60,
    overscan: 8,
    getItemKey: index => bots[index].id,
    // The open bot stays mounted while scrolled away, so its panel (a half-made token, an error) survives
    rangeExtractor: range => {
      const indexes = defaultRangeExtractor(range);
      return expandedIndex < 0 || indexes.includes(expandedIndex) ? indexes : [...indexes, expandedIndex].sort((a, b) => a - b);
    },
  });

  return (
    <div ref={scrollRef} data-testid="bot-list" className="max-h-[70vh] overflow-y-auto overscroll-contain">
      <div className="relative w-full" style={{ height: virtualizer.getTotalSize() }}>
        {virtualizer.getVirtualItems().map(item => {
          const bot = bots[item.index];
          return (
            <div
              key={item.key}
              data-index={item.index}
              ref={virtualizer.measureElement}
              className="absolute left-0 top-0 w-full pb-2"
              style={{ transform: `translateY(${item.start}px)` }}
            >
              <BotRow
                bot={bot}
                serverId={serverId}
                isExpanded={expandedBotId === bot.id}
                onToggle={onToggle}
                onChanged={onChanged}
              />
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ─── Channel Loop Guard Settings ──────────────────────────────────────────

type GuardField = 'maxBotHops' | 'maxThreadBotHops';
type Limits = Record<GuardField, number>;
/** The limit a guard gets when it is switched on with no earlier value to restore. */
const GUARD_DEFAULT: Limits = { maxBotHops: 4, maxThreadBotHops: 4 };

/**
 * Both loop guards per channel (#23): the channel guard (top-level bot messages in a row)
 * and the thread guard (bot replies in a row inside one thread). Each has an on/off switch;
 * off is a limit of 0.
 */
function ChannelLoopGuardSection({ serverId }: { serverId: string }) {
  const [channels, setChannels] = useState<Channel[]>([]);
  // Limits as loaded or last confirmed by a save here
  const [loaded, setLoaded] = useState<Record<string, Limits>>({});
  // Edits not yet confirmed by the server, by `${channelId}:${field}`
  const [dirty, setDirty] = useState<Record<string, number>>({});
  const [saving, setSaving] = useState<Record<string, boolean>>({});
  const [error, setError] = useState('');
  // A change made elsewhere (a notice's Raise limit or Turn off) arrives as ChannelBotConfig
  const live = useChannelStore(s => s.channels);
  const pending = useRef<Record<string, { timer: ReturnType<typeof setTimeout>; value: number }>>({});
  // Saves of one field go out one at a time, in order, so the last change made wins
  const queues = useRef<Record<string, Promise<void>>>({});
  // The last limit above 0, restored when a guard is switched back on
  const lastOn = useRef<Record<string, number>>({});
  const mounted = useRef(true);

  useEffect(() => {
    serverApi.getChannels(serverId).then((chs) => {
      const textChannels = chs.filter(c => c.channelType === 3);
      setChannels(textChannels);
      const initial: Record<string, Limits> = {};
      for (const ch of textChannels) {
        initial[ch.id] = { maxBotHops: ch.maxBotHops ?? 4, maxThreadBotHops: ch.maxThreadBotHops ?? 0 };
      }
      setLoaded(initial);
    }).catch(() => setError('Failed to load channels'));
  }, [serverId]);

  // enqueue only touches refs and state setters, so the first render's copy stays valid for the unmount flush
  const enqueueOnLeave = useRef(enqueue);

  // Leaving the page sends a change still waiting out its debounce instead of dropping it,
  // behind any save of that field still in flight so the older one cannot land last
  useEffect(() => {
    mounted.current = true;
    const waiting = pending.current;
    const flush = enqueueOnLeave.current;
    return () => {
      mounted.current = false;
      for (const [key, p] of Object.entries(waiting)) {
        clearTimeout(p.timer);
        delete waiting[key];
        const [channelId, field] = key.split(':') as [string, GuardField];
        flush(channelId, field, p.value);
      }
    };
  }, []);

  const shown = (channelId: string, field: GuardField): number => {
    const key = `${channelId}:${field}`;
    return dirty[key] ?? live.get(channelId)?.[field] ?? loaded[channelId]?.[field] ?? GUARD_DEFAULT[field];
  };

  function change(channelId: string, field: GuardField, value: number, delay: number) {
    const key = `${channelId}:${field}`;
    const prev = shown(channelId, field);
    if (prev > 0) lastOn.current[key] = prev;
    setDirty(d => ({ ...d, [key]: value }));
    if (pending.current[key]) clearTimeout(pending.current[key].timer);
    const timer = setTimeout(() => {
      delete pending.current[key];
      enqueue(channelId, field, value);
    }, delay);
    pending.current[key] = { timer, value };
  }

  /** Queues a save behind any earlier save of the same field (save never rejects). */
  function enqueue(channelId: string, field: GuardField, value: number) {
    const key = `${channelId}:${field}`;
    queues.current[key] = (queues.current[key] ?? Promise.resolve()).then(() => save(channelId, field, value));
  }

  function handleNumber(channelId: string, field: GuardField, raw: string) {
    const num = parseInt(raw, 10);
    // 0 would be "off": that is the switch's job, so the box keeps a limit while typing
    if (isNaN(num) || num < 1 || num > 1000) return;
    change(channelId, field, num, 600);
  }

  function handleToggle(channelId: string, field: GuardField, on: boolean) {
    const restore = lastOn.current[`${channelId}:${field}`] ?? GUARD_DEFAULT[field];
    change(channelId, field, on ? restore : 0, 0);
  }

  async function save(channelId: string, field: GuardField, value: number) {
    const key = `${channelId}:${field}`;
    if (mounted.current) { setSaving(s => ({ ...s, [key]: true })); setError(''); }
    // Only the latest edit clears the dirty value; an older save finishing must not
    const settle = (d: Record<string, number>) => {
      if (d[key] !== value || pending.current[key]) return d;
      const next = { ...d };
      delete next[key];
      return next;
    };
    try {
      const config = await botApi.updateChannelBotConfig(channelId, { [field]: value });
      useChannelStore.getState().patchChannel(channelId, { maxBotHops: config.maxBotHops, maxThreadBotHops: config.maxThreadBotHops });
      if (!mounted.current) return;
      setLoaded(l => ({ ...l, [channelId]: { maxBotHops: config.maxBotHops, maxThreadBotHops: config.maxThreadBotHops } }));
      setDirty(settle);
    } catch (err) {
      if (!mounted.current) return;
      // Show what the server still has, not the value that failed
      setDirty(settle);
      setError(err instanceof ApiError ? err.code : 'Failed to save');
    } finally {
      if (mounted.current) setSaving(s => ({ ...s, [key]: false }));
    }
  }

  if (channels.length === 0) return null;

  const guard = (ch: Channel, field: GuardField, label: string, unit: string) => {
    const value = shown(ch.id, field);
    const on = value > 0;
    const key = `${ch.id}:${field}`;
    return (
      <div className="flex items-center gap-2">
        <label className="min-h-11 md:min-h-8 flex items-center gap-1.5 text-xs text-text-muted cursor-pointer">
          <input
            type="checkbox"
            role="switch"
            checked={on}
            onChange={e => handleToggle(ch.id, field, e.target.checked)}
            aria-label={`${label} loop guard in #${ch.name}`}
            className="accent-primary"
          />
          {label}
        </label>
        {on ? (
          <input
            type="number"
            min={1}
            max={1000}
            value={value}
            onChange={e => handleNumber(ch.id, field, e.target.value)}
            aria-label={`${label} limit in #${ch.name} (${unit})`}
            title={`Pause after this many ${unit} in a row`}
            className="min-h-11 md:min-h-8 w-16 px-2 py-1 rounded border border-border bg-surface text-text text-sm text-right"
          />
        ) : (
          <span className="w-16 text-text-muted text-xs">Off</span>
        )}
        <span className="w-12 text-text-muted text-xs" aria-live="polite">{saving[key] ? 'Saving…' : ''}</span>
      </div>
    );
  };

  return (
    <section className="mb-6">
      <h3 className="text-sm font-semibold text-text mb-2">Loop Guard</h3>
      <p className="text-text-muted text-xs mb-3">
        Pauses agents after this many bot posts in a row with no human message. The channel guard counts top-level
        messages; the thread guard counts replies inside each thread. A human message resets both, and the notice
        it posts has Continue, Raise limit and Turn off buttons.
      </p>
      {error && <p className="text-danger text-xs mb-2" role="alert">{error}</p>}
      <div className="flex flex-col gap-1">
        {channels.map((ch) => (
          <div key={ch.id} className="flex flex-wrap items-center gap-x-6 gap-y-1 px-2 py-1.5 rounded hover:bg-surface-hover">
            <span className="flex min-w-32 flex-1 items-center gap-1 text-sm">
              <span className="text-text-muted">#</span>
              <span className="text-text">{ch.name}</span>
            </span>
            {guard(ch, 'maxBotHops', 'Channel', 'bot messages')}
            {guard(ch, 'maxThreadBotHops', 'Threads', 'bot replies in one thread')}
          </div>
        ))}
      </div>
    </section>
  );
}

// ─── Bot Row (expandable) ─────────────────────────────────────────────────

// Memoized with stable callbacks: opening one bot re-renders that row, not the whole list
const BotRow = memo(function BotRow({
  bot,
  serverId,
  isExpanded,
  onToggle,
  onChanged,
}: {
  bot: Bot;
  serverId: string;
  isExpanded: boolean;
  onToggle: (botId: string) => void;
  onChanged: () => void;
}) {
  const [pausing, setPausing] = useState(false);
  const [pauseError, setPauseError] = useState('');
  const [savingAccess, setSavingAccess] = useState(false);
  const isPaused = !!bot.pausedAt;

  async function changeAccess(access: RuntimeAccess) {
    if (access === 'auto' && !confirm(`Let ${bot.username} run code without approval? Runs still execute in the sandbox with its limits.`)) return;
    setSavingAccess(true);
    setPauseError('');
    try {
      await runtimeApi.setBotAccess(serverId, bot.id, access);
      onChanged();
    } catch (err) {
      setPauseError(err instanceof ApiError ? err.code : 'Failed to update code run access');
    } finally {
      setSavingAccess(false);
    }
  }

  async function togglePause() {
    setPausing(true);
    setPauseError('');
    try {
      if (isPaused) {
        await botApi.setPaused(serverId, bot.id, false);
      } else {
        const reason = prompt('Pause this bot? It will be read-only until resumed.\n\nReason (optional):');
        if (reason === null) return;
        await botApi.setPaused(serverId, bot.id, true, reason.trim() || undefined);
      }
      onChanged();
    } catch (err) {
      setPauseError(err instanceof ApiError ? err.code : 'Failed to update pause state');
    } finally {
      setPausing(false);
    }
  }

  return (
    <div className="border border-border rounded-lg overflow-hidden">
      <div className="flex items-center hover:bg-surface-hover">
      <button
        onClick={() => onToggle(bot.id)}
        aria-expanded={isExpanded}
        className="min-h-11 flex-1 flex items-center justify-between px-4 py-3 text-left"
      >
        <div>
          <span className="text-text font-medium">{bot.username}</span>
          {isPaused && (
            <span
              className="ml-2 inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-semibold leading-none bg-warn/20 text-warn"
              title={bot.pausedReason ? `Paused: ${bot.pausedReason}` : 'Paused'}
            >
              PAUSED
            </span>
          )}
          <span className="text-text-muted text-xs ml-2">
            {new Date(bot.createdAt).toLocaleDateString()}
          </span>
          {pauseError && <span className="text-danger text-xs ml-2">{pauseError}</span>}
        </div>
        <svg
          className="h-4 w-4 text-text-muted transition-transform"
          style={{ transform: isExpanded ? 'rotate(180deg)' : 'rotate(0deg)' }}
          fill="none"
          viewBox="0 0 24 24"
          stroke="currentColor"
          strokeWidth="2"
        >
          <polyline points="6 9 12 15 18 9" />
        </svg>
      </button>
      <label className="flex items-center gap-1 pr-3 text-xs text-text-muted" title="Whether this bot may run code in the sandbox">
        Code runs
        <select
          className="min-h-11 md:min-h-8 bg-surface border border-border rounded px-2 py-1 text-xs text-text"
          value={bot.runtimeAccess ?? 'none'}
          disabled={savingAccess}
          onChange={e => changeAccess(e.target.value as RuntimeAccess)}
          aria-label={`Code run access for ${bot.username}`}
        >
          <option value="none">Off</option>
          <option value="approval">Need approval</option>
          <option value="auto">Auto-run</option>
        </select>
      </label>
      <div className="pr-3">
        <Button variant="secondary" onClick={togglePause} loading={pausing}>
          {isPaused ? 'Resume' : 'Pause'}
        </Button>
      </div>
      </div>
      {isExpanded && (
        <BotDetailPanel botId={bot.id} serverId={serverId} onDeleted={onChanged} />
      )}
    </div>
  );
});

// ─── Bot Detail Panel ─────────────────────────────────────────────────────

function BotDetailPanel({
  botId,
  serverId,
  onDeleted,
}: {
  botId: string;
  serverId: string;
  onDeleted: () => void;
}) {
  const [detail, setDetail] = useState<BotDetail | null>(null);
  const [allChannels, setAllChannels] = useState<Channel[]>([]);
  const [tokens, setTokens] = useState<BotToken[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [showCreateToken, setShowCreateToken] = useState(false);
  const [showInvite, setShowInvite] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [channelLoading, setChannelLoading] = useState<string | null>(null);
  const [avatarInput, setAvatarInput] = useState('');
  const [avatarSaving, setAvatarSaving] = useState(false);
  const [avatarError, setAvatarError] = useState('');

  const fetchDetail = useCallback(async () => {
    try {
      const [d, channels] = await Promise.all([
        botApi.get(serverId, botId),
        serverApi.getChannels(serverId),
      ]);
      setDetail(d);
      setAvatarInput(d.avatarUrl || '');
      // Only show text channels (type 3) for bot access
      setAllChannels(channels.filter(c => c.channelType === 3));
      if (d.canManageTokens) {
        const t = await botApi.listTokens(serverId, botId);
        setTokens(t);
      }
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to load bot details');
    } finally {
      setLoading(false);
    }
  }, [serverId, botId]);

  useEffect(() => { fetchDetail(); }, [fetchDetail]);

  async function handleDelete() {
    if (!confirm('Delete this bot? This cannot be undone.')) return;
    setDeleting(true);
    try {
      await botApi.remove(serverId, botId);
      onDeleted();
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to delete bot');
      setDeleting(false);
    }
  }

  async function handleRevokeToken(tokenId: string) {
    try {
      await botApi.revokeToken(serverId, botId, tokenId);
      setTokens(prev => prev.map(t => t.id === tokenId ? { ...t, revokedAt: new Date().toISOString() } : t));
    } catch (err) {
      if (err instanceof ApiError && err.status === 403) {
        // Permissions changed — refetch detail
        fetchDetail();
      }
      setError(err instanceof ApiError ? err.code : 'Failed to revoke token');
    }
  }

  async function handleClearBinding(tokenId: string) {
    try {
      await botApi.clearTokenBinding(serverId, botId, tokenId);
      setTokens(prev => prev.map(t => t.id === tokenId ? { ...t, boundClient: null, boundAt: null, lastRefused: null } : t));
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to clear the binding');
    }
  }

  async function toggleDirect(channelId: string, canDirect: boolean) {
    setChannelLoading(channelId);
    setError('');
    try {
      await botApi.setCanDirect(channelId, botId, !canDirect);
      setDetail(await botApi.get(serverId, botId));
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to update who may direct');
    } finally {
      setChannelLoading(null);
    }
  }

  async function toggleChannel(channelId: string, hasAccess: boolean) {
    setChannelLoading(channelId);
    try {
      if (hasAccess) {
        await botApi.revokeChannel(channelId, botId);
      } else {
        await botApi.grantChannel(channelId, botId);
      }
      // Refetch detail to get updated channel list
      const d = await botApi.get(serverId, botId);
      setDetail(d);
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to update channel access');
    } finally {
      setChannelLoading(null);
    }
  }

  if (loading) {
    return <div className="px-4 py-3 border-t border-border text-text-muted text-sm">Loading...</div>;
  }

  if (error && !detail) {
    return <div className="px-4 py-3 border-t border-border text-danger text-sm">{error}</div>;
  }

  if (!detail) return null;

  const botChannelIds = new Set(detail.channels.map(c => c.id));
  const directChannelIds = new Set(detail.channels.filter(c => c.canDirect).map(c => c.id));
  const activeTokens = tokens.filter(t => !t.revokedAt);
  const revokedTokens = tokens.filter(t => t.revokedAt);

  return (
    <div className="border-t border-border px-4 py-4 flex flex-col gap-5 bg-bg/50">
      {error && <p className="text-danger text-sm">{error}</p>}

      {/* ── Avatar ── */}
      <section>
        <h4 className="text-sm font-semibold text-text mb-2">Avatar</h4>
        <div className="flex items-start gap-3">
          <Avatar userId={botId} username={detail.username} avatarUrl={detail.avatarUrl} className="h-12 w-12 text-sm" />
          <div className="flex-1 min-w-0">
            <input
              type="text"
              value={avatarInput}
              onChange={(e) => { setAvatarInput(e.target.value); setAvatarError(''); }}
              placeholder="data:image/svg+xml;base64,..."
              className="min-h-11 md:min-h-9 w-full px-3 py-1.5 rounded border border-border bg-surface text-text placeholder:text-text-muted/70 text-sm"
            />
            {avatarError && <p className="text-danger text-xs mt-1">{avatarError}</p>}
            <div className="flex gap-2 mt-2">
              <Button
                variant="secondary"
                className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
                loading={avatarSaving}
                onClick={async () => {
                  setAvatarSaving(true);
                  setAvatarError('');
                  try {
                    const res = await botApi.update(serverId, botId, { avatarUrl: avatarInput || null });
                    setDetail(prev => prev ? { ...prev, avatarUrl: res.avatarUrl } : prev);
                  } catch (err) {
                    setAvatarError(err instanceof ApiError ? err.code : 'Failed to save avatar');
                  } finally {
                    setAvatarSaving(false);
                  }
                }}
              >
                Save Avatar
              </Button>
              {detail.avatarUrl && (
                <Button
                  variant="secondary"
                  className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
                  onClick={async () => {
                    setAvatarSaving(true);
                    setAvatarError('');
                    try {
                      const res = await botApi.update(serverId, botId, { avatarUrl: null });
                      setDetail(prev => prev ? { ...prev, avatarUrl: res.avatarUrl } : prev);
                      setAvatarInput('');
                    } catch (err) {
                      setAvatarError(err instanceof ApiError ? err.code : 'Failed to remove avatar');
                    } finally {
                      setAvatarSaving(false);
                    }
                  }}
                >
                  Remove
                </Button>
              )}
            </div>
          </div>
        </div>
      </section>

      {/* ── Channel Access ── */}
      <section>
        <h4 className="text-sm font-semibold text-text mb-2">Channel Access</h4>
        {allChannels.length === 0 ? (
          <p className="text-text-muted text-xs">No text channels found.</p>
        ) : (
          <div className="flex flex-col gap-1">
            {allChannels.map((ch) => {
              const hasAccess = botChannelIds.has(ch.id);
              const isLoading = channelLoading === ch.id;
              return (
                <label
                  key={ch.id}
                  className="min-h-11 md:min-h-9 flex items-center gap-2 px-2 py-1.5 rounded hover:bg-surface-hover cursor-pointer text-sm"
                >
                  <input
                    type="checkbox"
                    checked={hasAccess}
                    disabled={isLoading}
                    onChange={() => toggleChannel(ch.id, hasAccess)}
                    className="accent-primary"
                  />
                  <span className="text-text-muted">#</span>
                  <span className="text-text">{ch.name}</span>
                  {isLoading && <span className="text-text-muted text-xs ml-auto">...</span>}
                  {hasAccess && (
                    <span
                      className="ml-auto flex items-center gap-1 text-xs text-text-muted"
                      title="Lets this bot give other agents instructions in this channel. Only the server owner can change it."
                      onClick={(e) => e.stopPropagation()}
                    >
                      <input
                        type="checkbox"
                        checked={directChannelIds.has(ch.id)}
                        disabled={isLoading}
                        onChange={() => toggleDirect(ch.id, directChannelIds.has(ch.id))}
                        className="accent-primary"
                      />
                      can direct agents
                    </span>
                  )}
                </label>
              );
            })}
          </div>
        )}
      </section>

      {/* ── Tokens (owner / admin only) ── */}
      {detail.canManageTokens && (
        <section>
          <Button onClick={() => setShowInvite(true)}>Invite Agent</Button>
          {showInvite && <CreateAgentInviteModal serverId={serverId} botId={botId} onClose={() => setShowInvite(false)} onCreated={() => {}} />}
          <div className="flex items-center justify-between mb-2">
            <h4 className="text-sm font-semibold text-text">Tokens</h4>
            <Button
              variant="secondary"
              className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
              onClick={() => setShowCreateToken(true)}
            >
              New Token
            </Button>
          </div>
          {activeTokens.length === 0 && revokedTokens.length === 0 ? (
            <p className="text-text-muted text-xs">No tokens yet.</p>
          ) : (
            <div className="flex flex-col gap-1">
              {activeTokens.map((t) => (
                <div key={t.id} className="flex items-center justify-between px-2 py-1.5 rounded bg-surface text-sm">
                  <div>
                    <span className="text-text">{t.name || 'Unnamed'}</span>
                    <span className="text-text-muted text-xs ml-2">
                      Created {new Date(t.createdAt).toLocaleDateString()}
                    </span>
                    {t.lastUsedAt && (
                      <span className="text-text-muted text-xs ml-2">
                        Last used {new Date(t.lastUsedAt).toLocaleDateString()}
                        {t.lastUsedClient ? ` by ${t.lastUsedClient}` : ''}
                        {t.lastUsedIp ? ` from ${t.lastUsedIp}` : ''}
                      </span>
                    )}
                    {t.boundClient && (
                      <span className="text-text-muted text-xs ml-2" title="Requests from any other client are refused">
                        Bound to {t.boundClient}
                      </span>
                    )}
                    {t.lastRefused && (
                      <span className="block text-danger text-xs">
                        Refused {t.lastRefused.client ? `use by ${t.lastRefused.client}` : 'a use with no client name'}
                        {t.lastRefused.ip ? ` from ${t.lastRefused.ip}` : ''} on {new Date(t.lastRefused.at).toLocaleString()}.
                        If that wasn't you moving this agent, revoke the token.
                      </span>
                    )}
                  </div>
                  <div className="flex shrink-0">
                    {t.boundClient && (
                      <button
                        onClick={() => handleClearBinding(t.id)}
                        className="min-h-11 md:min-h-8 px-2 text-text-muted text-xs hover:underline"
                        title="The next client that uses the token binds it again"
                      >
                        Clear binding
                      </button>
                    )}
                    <button
                      onClick={() => handleRevokeToken(t.id)}
                      className="min-h-11 md:min-h-8 px-2 text-danger text-xs hover:underline"
                    >
                      Revoke
                    </button>
                  </div>
                </div>
              ))}
              {revokedTokens.map((t) => (
                <div key={t.id} className="flex items-center px-2 py-1.5 rounded bg-surface text-sm opacity-50">
                  <span className="text-text line-through">{t.name || 'Unnamed'}</span>
                  <span className="text-text-muted text-xs ml-2">Revoked</span>
                </div>
              ))}
            </div>
          )}

          <CreateTokenModal
            serverId={serverId}
            botId={botId}
            isOpen={showCreateToken}
            onClose={() => setShowCreateToken(false)}
            onCreated={async () => {
              const t = await botApi.listTokens(serverId, botId);
              setTokens(t);
            }}
          />
        </section>
      )}

      {/* ── Delete Bot ── */}
      <div className="pt-2 border-t border-border">
        <Button variant="danger" onClick={handleDelete} loading={deleting}>
          Delete Bot
        </Button>
      </div>
    </div>
  );
}

import { memo, useCallback, useDeferredValue, useEffect, useMemo, useRef, useState } from 'react';
import { Link } from 'react-router-dom';
import { defaultRangeExtractor, useVirtualizer } from '@tanstack/react-virtual';
import { Avatar } from '../../components/ui/Avatar';
import { useServerStore } from '../../stores/serverStore';
import { useChannelStore } from '../../stores/channelStore';
import { botApi, serverApi, runtimeApi, ApiError } from '../../lib/api';
import type { Bot, BotDetail, BotToken, RuntimeAccess } from '../../lib/api';
import type { Channel } from '../../lib/contracts/server';
import { Button } from '../../components/ui/Button';
import { CreateBotModal } from './CreateBotModal';
import { CreateTokenModal } from './CreateTokenModal';
import { CreateAgentInviteModal } from './CreateAgentInviteModal';

export function BotManagement() {
  const instanceServerId = useServerStore(s => s.instanceServerId);
  const [bots, setBots] = useState<Bot[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [permissionDenied, setPermissionDenied] = useState(false);
  const [showCreateBot, setShowCreateBot] = useState(false);
  const [showInvite, setShowInvite] = useState(false);
  const [expandedBotId, setExpandedBotId] = useState<string | null>(null);
  const [query, setQuery] = useState('');
  const deferredQuery = useDeferredValue(query);

  const fetchBots = useCallback(async (showLoading = true) => {
    if (!instanceServerId) return;
    if (showLoading) setLoading(true);
    setError('');
    try {
      const data = await botApi.list(instanceServerId);
      setBots(data);
      setPermissionDenied(false);
    } catch (err) {
      if (err instanceof ApiError && err.status === 403) {
        setPermissionDenied(true);
      } else {
        setError(err instanceof ApiError ? err.code : 'Failed to load bots');
      }
    } finally {
      setLoading(false);
    }
  }, [instanceServerId]);

  useEffect(() => { fetchBots(); }, [fetchBots]);

  // A refresh after a change keeps the list (and its scroll position) on screen
  let refresh = useCallback(() => { void fetchBots(false); }, [fetchBots]);
  const toggle = useCallback((botId: string) => setExpandedBotId(cur => (cur === botId ? null : botId)), []);

  // Newest first, so a bot you just created is at the top of a long list
  const sorted = useMemo(() => [...bots].sort((a, b) => b.createdAt.localeCompare(a.createdAt)), [bots]);
  const shown = useMemo(() => {
    const q = deferredQuery.trim().toLowerCase();
    return q ? sorted.filter(b => b.username.toLowerCase().includes(q)) : sorted;
  }, [sorted, deferredQuery]);

  if (!instanceServerId) return null;

  if (permissionDenied) {
    return (
      <div>
        <h2 className="text-xl font-bold text-text mb-4">Bot Management</h2>
        <p className="text-text-muted mb-4">You don't have permission to manage bots.</p>
        <Link to="/app" className="hidden min-h-11 items-center text-primary-text hover:underline sm:inline-flex md:min-h-8">Back to chat</Link>
      </div>
    );
  }

  if (loading) {
    return <p className="text-text-muted">Loading bots...</p>;
  }

  return (
    <div>
      <div className="flex flex-wrap items-center justify-between gap-3 mb-6">
        <h2 className="text-xl font-bold text-text">Bot Management</h2>
        <div className="flex gap-2">
          <Button onClick={() => setShowInvite(true)}>Invite Agent</Button>
          <Button variant="secondary" onClick={() => setShowCreateBot(true)}>Create Bot</Button>
        </div>
      </div>

      {error && <p className="text-danger text-sm mb-4">{error}</p>}

      <ChannelLoopGuardSection serverId={instanceServerId} />

      {bots.length === 0 ? (
        <p className="text-text-muted">No bots yet. Create one to get started.</p>
      ) : (
        <section>
          <div className="flex flex-wrap items-center gap-3 mb-2">
            <input
              type="search"
              value={query}
              onChange={e => setQuery(e.target.value)}
              placeholder="Search bots"
              aria-label="Search bots"
              className="min-h-11 md:min-h-9 w-full max-w-xs px-3 py-1.5 rounded border border-border bg-surface text-text placeholder:text-text-muted/70 text-sm"
            />
            <span className="text-text-muted text-xs" aria-live="polite">
              {shown.length === bots.length ? `${bots.length} bots` : `${shown.length} of ${bots.length} bots`}
            </span>
          </div>
          {shown.length === 0 ? (
            <p className="text-text-muted text-sm">No bots match “{deferredQuery.trim()}”.</p>
          ) : (
            <BotList
              bots={shown}
              serverId={instanceServerId}
              expandedBotId={expandedBotId}
              onToggle={toggle}
              onChanged={refresh}
            />
          )}
        </section>
      )}

      <CreateBotModal
        serverId={instanceServerId}
        isOpen={showCreateBot}
        onClose={() => setShowCreateBot(false)}
        onCreated={refresh}
      />
      {showInvite && <CreateAgentInviteModal serverId={instanceServerId} onClose={() => setShowInvite(false)} onCreated={refresh} />}
    </div>
  );
}

// ─── Bot List (virtualized) ───────────────────────────────────────────────

/** Rendering every bot stalled the page at about 1,800 bots (#241): only the rows in view are mounted. */
function BotList({
  bots,
  serverId,
  expandedBotId,
  onToggle,
  onChanged,
}: {
  bots: Bot[];
  serverId: string;
  expandedBotId: string | null;
  onToggle: (botId: string) => void;
  onChanged: () => void;
}) {
  const scrollRef = useRef<HTMLDivElement>(null);
  const expandedIndex = expandedBotId ? bots.findIndex(b => b.id === expandedBotId) : -1;
  // This component is not compiled by the React Compiler; the virtualizer is read during render only
  // eslint-disable-next-line react-hooks/incompatible-library
  const virtualizer = useVirtualizer({
    count: bots.length,
    getScrollElement: () => scrollRef.current,
    estimateSize: () => 60,
    overscan: 8,
    getItemKey: index => bots[index].id,
    // The open bot stays mounted while scrolled away, so its panel (a half-made token, an error) survives
    rangeExtractor: range => {
      const indexes = defaultRangeExtractor(range);
      return expandedIndex < 0 || indexes.includes(expandedIndex) ? indexes : [...indexes, expandedIndex].sort((a, b) => a - b);
    },
  });

  return (
    <div ref={scrollRef} data-testid="bot-list" className="max-h-[70vh] overflow-y-auto overscroll-contain">
      <div className="relative w-full" style={{ height: virtualizer.getTotalSize() }}>
        {virtualizer.getVirtualItems().map(item => {
          const bot = bots[item.index];
          return (
            <div
              key={item.key}
              data-index={item.index}
              ref={virtualizer.measureElement}
              className="absolute left-0 top-0 w-full pb-2"
              style={{ transform: `translateY(${item.start}px)` }}
            >
              <BotRow
                bot={bot}
                serverId={serverId}
                isExpanded={expandedBotId === bot.id}
                onToggle={onToggle}
                onChanged={onChanged}
              />
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ─── Channel Loop Guard Settings ──────────────────────────────────────────

type GuardField = 'maxBotHops' | 'maxThreadBotHops';
type Limits = Record<GuardField, number>;
/** The limit a guard gets when it is switched on with no earlier value to restore. */
const GUARD_DEFAULT: Limits = { maxBotHops: 4, maxThreadBotHops: 4 };

/**
 * Both loop guards per channel (#23): the channel guard (top-level bot messages in a row)
 * and the thread guard (bot replies in a row inside one thread). Each has an on/off switch;
 * off is a limit of 0.
 */
function ChannelLoopGuardSection({ serverId }: { serverId: string }) {
  const [channels, setChannels] = useState<Channel[]>([]);
  // Limits as loaded or last confirmed by a save here
  const [loaded, setLoaded] = useState<Record<string, Limits>>({});
  // Edits not yet confirmed by the server, by `${channelId}:${field}`
  const [dirty, setDirty] = useState<Record<string, number>>({});
  const [saving, setSaving] = useState<Record<string, boolean>>({});
  const [error, setError] = useState('');
  // A change made elsewhere (a notice's Raise limit or Turn off) arrives as ChannelBotConfig
  const live = useChannelStore(s => s.channels);
  const pending = useRef<Record<string, { timer: ReturnType<typeof setTimeout>; value: number }>>({});
  // Saves of one field go out one at a time, in order, so the last change made wins
  const queues = useRef<Record<string, Promise<void>>>({});
  // The last limit above 0, restored when a guard is switched back on
  const lastOn = useRef<Record<string, number>>({});
  const mounted = useRef(true);

  useEffect(() => {
    serverApi.getChannels(serverId).then((chs) => {
      const textChannels = chs.filter(c => c.channelType === 3);
      setChannels(textChannels);
      const initial: Record<string, Limits> = {};
      for (const ch of textChannels) {
        initial[ch.id] = { maxBotHops: ch.maxBotHops ?? 4, maxThreadBotHops: ch.maxThreadBotHops ?? 0 };
      }
      setLoaded(initial);
    }).catch(() => setError('Failed to load channels'));
  }, [serverId]);

  // enqueue only touches refs and state setters, so the first render's copy stays valid for the unmount flush
  const enqueueOnLeave = useRef(enqueue);

  // Leaving the page sends a change still waiting out its debounce instead of dropping it,
  // behind any save of that field still in flight so the older one cannot land last
  useEffect(() => {
    mounted.current = true;
    const waiting = pending.current;
    const flush = enqueueOnLeave.current;
    return () => {
      mounted.current = false;
      for (const [key, p] of Object.entries(waiting)) {
        clearTimeout(p.timer);
        delete waiting[key];
        const [channelId, field] = key.split(':') as [string, GuardField];
        flush(channelId, field, p.value);
      }
    };
  }, []);

  const shown = (channelId: string, field: GuardField): number => {
    const key = `${channelId}:${field}`;
    return dirty[key] ?? live.get(channelId)?.[field] ?? loaded[channelId]?.[field] ?? GUARD_DEFAULT[field];
  };

  function change(channelId: string, field: GuardField, value: number, delay: number) {
    const key = `${channelId}:${field}`;
    const prev = shown(channelId, field);
    if (prev > 0) lastOn.current[key] = prev;
    setDirty(d => ({ ...d, [key]: value }));
    if (pending.current[key]) clearTimeout(pending.current[key].timer);
    const timer = setTimeout(() => {
      delete pending.current[key];
      enqueue(channelId, field, value);
    }, delay);
    pending.current[key] = { timer, value };
  }

  /** Queues a save behind any earlier save of the same field (save never rejects). */
  function enqueue(channelId: string, field: GuardField, value: number) {
    const key = `${channelId}:${field}`;
    queues.current[key] = (queues.current[key] ?? Promise.resolve()).then(() => save(channelId, field, value));
  }

  function handleNumber(channelId: string, field: GuardField, raw: string) {
    const num = parseInt(raw, 10);
    // 0 would be "off": that is the switch's job, so the box keeps a limit while typing
    if (isNaN(num) || num < 1 || num > 1000) return;
    change(channelId, field, num, 600);
  }

  function handleToggle(channelId: string, field: GuardField, on: boolean) {
    const restore = lastOn.current[`${channelId}:${field}`] ?? GUARD_DEFAULT[field];
    change(channelId, field, on ? restore : 0, 0);
  }

  async function save(channelId: string, field: GuardField, value: number) {
    const key = `${channelId}:${field}`;
    if (mounted.current) { setSaving(s => ({ ...s, [key]: true })); setError(''); }
    // Only the latest edit clears the dirty value; an older save finishing must not
    const settle = (d: Record<string, number>) => {
      if (d[key] !== value || pending.current[key]) return d;
      const next = { ...d };
      delete next[key];
      return next;
    };
    try {
      const config = await botApi.updateChannelBotConfig(channelId, { [field]: value });
      useChannelStore.getState().patchChannel(channelId, { maxBotHops: config.maxBotHops, maxThreadBotHops: config.maxThreadBotHops });
      if (!mounted.current) return;
      setLoaded(l => ({ ...l, [channelId]: { maxBotHops: config.maxBotHops, maxThreadBotHops: config.maxThreadBotHops } }));
      setDirty(settle);
    } catch (err) {
      if (!mounted.current) return;
      // Show what the server still has, not the value that failed
      setDirty(settle);
      setError(err instanceof ApiError ? err.code : 'Failed to save');
    } finally {
      if (mounted.current) setSaving(s => ({ ...s, [key]: false }));
    }
  }

  if (channels.length === 0) return null;

  const guard = (ch: Channel, field: GuardField, label: string, unit: string) => {
    const value = shown(ch.id, field);
    const on = value > 0;
    const key = `${ch.id}:${field}`;
    return (
      <div className="flex items-center gap-2">
        <label className="min-h-11 md:min-h-8 flex items-center gap-1.5 text-xs text-text-muted cursor-pointer">
          <input
            type="checkbox"
            role="switch"
            checked={on}
            onChange={e => handleToggle(ch.id, field, e.target.checked)}
            aria-label={`${label} loop guard in #${ch.name}`}
            className="accent-primary"
          />
          {label}
        </label>
        {on ? (
          <input
            type="number"
            min={1}
            max={1000}
            value={value}
            onChange={e => handleNumber(ch.id, field, e.target.value)}
            aria-label={`${label} limit in #${ch.name} (${unit})`}
            title={`Pause after this many ${unit} in a row`}
            className="min-h-11 md:min-h-8 w-16 px-2 py-1 rounded border border-border bg-surface text-text text-sm text-right"
          />
        ) : (
          <span className="w-16 text-text-muted text-xs">Off</span>
        )}
        <span className="w-12 text-text-muted text-xs" aria-live="polite">{saving[key] ? 'Saving…' : ''}</span>
      </div>
    );
  };

  return (
    <section className="mb-6">
      <h3 className="text-sm font-semibold text-text mb-2">Loop Guard</h3>
      <p className="text-text-muted text-xs mb-3">
        Pauses agents after this many bot posts in a row with no human message. The channel guard counts top-level
        messages; the thread guard counts replies inside each thread. A human message resets both, and the notice
        it posts has Continue, Raise limit and Turn off buttons.
      </p>
      {error && <p className="text-danger text-xs mb-2" role="alert">{error}</p>}
      <div className="flex flex-col gap-1">
        {channels.map((ch) => (
          <div key={ch.id} className="flex flex-wrap items-center gap-x-6 gap-y-1 px-2 py-1.5 rounded hover:bg-surface-hover">
            <span className="flex min-w-32 flex-1 items-center gap-1 text-sm">
              <span className="text-text-muted">#</span>
              <span className="text-text">{ch.name}</span>
            </span>
            {guard(ch, 'maxBotHops', 'Channel', 'bot messages')}
            {guard(ch, 'maxThreadBotHops', 'Threads', 'bot replies in one thread')}
          </div>
        ))}
      </div>
    </section>
  );
}

// ─── Bot Row (expandable) ─────────────────────────────────────────────────

// Memoized with stable callbacks: opening one bot re-renders that row, not the whole list
const BotRow = memo(function BotRow({
  bot,
  serverId,
  isExpanded,
  onToggle,
  onChanged,
}: {
  bot: Bot;
  serverId: string;
  isExpanded: boolean;
  onToggle: (botId: string) => void;
  onChanged: () => void;
}) {
  const [pausing, setPausing] = useState(false);
  const [pauseError, setPauseError] = useState('');
  const [savingAccess, setSavingAccess] = useState(false);
  const isPaused = !!bot.pausedAt;

  async function changeAccess(access: RuntimeAccess) {
    if (access === 'auto' && !confirm(`Let ${bot.username} run code without approval? Runs still execute in the sandbox with its limits.`)) return;
    setSavingAccess(true);
    setPauseError('');
    try {
      await runtimeApi.setBotAccess(serverId, bot.id, access);
      onChanged();
    } catch (err) {
      setPauseError(err instanceof ApiError ? err.code : 'Failed to update code run access');
    } finally {
      setSavingAccess(false);
    }
  }

  async function togglePause() {
    setPausing(true);
    setPauseError('');
    try {
      if (isPaused) {
        await botApi.setPaused(serverId, bot.id, false);
      } else {
        const reason = prompt('Pause this bot? It will be read-only until resumed.\n\nReason (optional):');
        if (reason === null) return;
        await botApi.setPaused(serverId, bot.id, true, reason.trim() || undefined);
      }
      onChanged();
    } catch (err) {
      setPauseError(err instanceof ApiError ? err.code : 'Failed to update pause state');
    } finally {
      setPausing(false);
    }
  }

  return (
    <div className="border border-border rounded-lg overflow-hidden">
      <div className="flex items-center hover:bg-surface-hover">
      <button
        onClick={() => onToggle(bot.id)}
        aria-expanded={isExpanded}
        className="min-h-11 flex-1 flex items-center justify-between px-4 py-3 text-left"
      >
        <div>
          <span className="text-text font-medium">{bot.username}</span>
          {isPaused && (
            <span
              className="ml-2 inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-semibold leading-none bg-warn/20 text-warn"
              title={bot.pausedReason ? `Paused: ${bot.pausedReason}` : 'Paused'}
            >
              PAUSED
            </span>
          )}
          <span className="text-text-muted text-xs ml-2">
            {new Date(bot.createdAt).toLocaleDateString()}
          </span>
          {pauseError && <span className="text-danger text-xs ml-2">{pauseError}</span>}
        </div>
        <svg
          className="h-4 w-4 text-text-muted transition-transform"
          style={{ transform: isExpanded ? 'rotate(180deg)' : 'rotate(0deg)' }}
          fill="none"
          viewBox="0 0 24 24"
          stroke="currentColor"
          strokeWidth="2"
        >
          <polyline points="6 9 12 15 18 9" />
        </svg>
      </button>
      <label className="flex items-center gap-1 pr-3 text-xs text-text-muted" title="Whether this bot may run code in the sandbox">
        Code runs
        <select
          className="min-h-11 md:min-h-8 bg-surface border border-border rounded px-2 py-1 text-xs text-text"
          value={bot.runtimeAccess ?? 'none'}
          disabled={savingAccess}
          onChange={e => changeAccess(e.target.value as RuntimeAccess)}
          aria-label={`Code run access for ${bot.username}`}
        >
          <option value="none">Off</option>
          <option value="approval">Need approval</option>
          <option value="auto">Auto-run</option>
        </select>
      </label>
      <div className="pr-3">
        <Button variant="secondary" onClick={togglePause} loading={pausing}>
          {isPaused ? 'Resume' : 'Pause'}
        </Button>
      </div>
      </div>
      {isExpanded && (
        <BotDetailPanel botId={bot.id} serverId={serverId} onDeleted={onChanged} />
      )}
    </div>
  );
});

// ─── Bot Detail Panel ─────────────────────────────────────────────────────

function BotDetailPanel({
  botId,
  serverId,
  onDeleted,
}: {
  botId: string;
  serverId: string;
  onDeleted: () => void;
}) {
  const [detail, setDetail] = useState<BotDetail | null>(null);
  const [allChannels, setAllChannels] = useState<Channel[]>([]);
  const [tokens, setTokens] = useState<BotToken[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [showCreateToken, setShowCreateToken] = useState(false);
  const [showInvite, setShowInvite] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [channelLoading, setChannelLoading] = useState<string | null>(null);
  const [avatarInput, setAvatarInput] = useState('');
  const [avatarSaving, setAvatarSaving] = useState(false);
  const [avatarError, setAvatarError] = useState('');

  const fetchDetail = useCallback(async () => {
    try {
      const [d, channels] = await Promise.all([
        botApi.get(serverId, botId),
        serverApi.getChannels(serverId),
      ]);
      setDetail(d);
      setAvatarInput(d.avatarUrl || '');
      // Only show text channels (type 3) for bot access
      setAllChannels(channels.filter(c => c.channelType === 3));
      if (d.canManageTokens) {
        const t = await botApi.listTokens(serverId, botId);
        setTokens(t);
      }
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to load bot details');
    } finally {
      setLoading(false);
    }
  }, [serverId, botId]);

  useEffect(() => { fetchDetail(); }, [fetchDetail]);

  async function handleDelete() {
    if (!confirm('Delete this bot? This cannot be undone.')) return;
    setDeleting(true);
    try {
      await botApi.remove(serverId, botId);
      onDeleted();
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to delete bot');
      setDeleting(false);
    }
  }

  async function handleRevokeToken(tokenId: string) {
    try {
      await botApi.revokeToken(serverId, botId, tokenId);
      setTokens(prev => prev.map(t => t.id === tokenId ? { ...t, revokedAt: new Date().toISOString() } : t));
    } catch (err) {
      if (err instanceof ApiError && err.status === 403) {
        // Permissions changed — refetch detail
        fetchDetail();
      }
      setError(err instanceof ApiError ? err.code : 'Failed to revoke token');
    }
  }

  async function handleClearBinding(tokenId: string) {
    try {
      await botApi.clearTokenBinding(serverId, botId, tokenId);
      setTokens(prev => prev.map(t => t.id === tokenId ? { ...t, boundClient: null, boundAt: null, lastRefused: null } : t));
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to clear the binding');
    }
  }

  async function toggleDirect(channelId: string, canDirect: boolean) {
    setChannelLoading(channelId);
    setError('');
    try {
      await botApi.setCanDirect(channelId, botId, !canDirect);
      setDetail(await botApi.get(serverId, botId));
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to update who may direct');
    } finally {
      setChannelLoading(null);
    }
  }

  async function toggleChannel(channelId: string, hasAccess: boolean) {
    setChannelLoading(channelId);
    try {
      if (hasAccess) {
        await botApi.revokeChannel(channelId, botId);
      } else {
        await botApi.grantChannel(channelId, botId);
      }
      // Refetch detail to get updated channel list
      const d = await botApi.get(serverId, botId);
      setDetail(d);
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to update channel access');
    } finally {
      setChannelLoading(null);
    }
  }

  if (loading) {
    return <div className="px-4 py-3 border-t border-border text-text-muted text-sm">Loading...</div>;
  }

  if (error && !detail) {
    return <div className="px-4 py-3 border-t border-border text-danger text-sm">{error}</div>;
  }

  if (!detail) return null;

  const botChannelIds = new Set(detail.channels.map(c => c.id));
  const directChannelIds = new Set(detail.channels.filter(c => c.canDirect).map(c => c.id));
  const activeTokens = tokens.filter(t => !t.revokedAt);
  const revokedTokens = tokens.filter(t => t.revokedAt);

  return (
    <div className="border-t border-border px-4 py-4 flex flex-col gap-5 bg-bg/50">
      {error && <p className="text-danger text-sm">{error}</p>}

      {/* ── Avatar ── */}
      <section>
        <h4 className="text-sm font-semibold text-text mb-2">Avatar</h4>
        <div className="flex items-start gap-3">
          <Avatar userId={botId} username={detail.username} avatarUrl={detail.avatarUrl} className="h-12 w-12 text-sm" />
          <div className="flex-1 min-w-0">
            <input
              type="text"
              value={avatarInput}
              onChange={(e) => { setAvatarInput(e.target.value); setAvatarError(''); }}
              placeholder="data:image/svg+xml;base64,..."
              className="min-h-11 md:min-h-9 w-full px-3 py-1.5 rounded border border-border bg-surface text-text placeholder:text-text-muted/70 text-sm"
            />
            {avatarError && <p className="text-danger text-xs mt-1">{avatarError}</p>}
            <div className="flex gap-2 mt-2">
              <Button
                variant="secondary"
                className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
                loading={avatarSaving}
                onClick={async () => {
                  setAvatarSaving(true);
                  setAvatarError('');
                  try {
                    const res = await botApi.update(serverId, botId, { avatarUrl: avatarInput || null });
                    setDetail(prev => prev ? { ...prev, avatarUrl: res.avatarUrl } : prev);
                  } catch (err) {
                    setAvatarError(err instanceof ApiError ? err.code : 'Failed to save avatar');
                  } finally {
                    setAvatarSaving(false);
                  }
                }}
              >
                Save Avatar
              </Button>
              {detail.avatarUrl && (
                <Button
                  variant="secondary"
                  className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
                  onClick={async () => {
                    setAvatarSaving(true);
                    setAvatarError('');
                    try {
                      const res = await botApi.update(serverId, botId, { avatarUrl: null });
                      setDetail(prev => prev ? { ...prev, avatarUrl: res.avatarUrl } : prev);
                      setAvatarInput('');
                    } catch (err) {
                      setAvatarError(err instanceof ApiError ? err.code : 'Failed to remove avatar');
                    } finally {
                      setAvatarSaving(false);
                    }
                  }}
                >
                  Remove
                </Button>
              )}
            </div>
          </div>
        </div>
      </section>

      {/* ── Channel Access ── */}
      <section>
        <h4 className="text-sm font-semibold text-text mb-2">Channel Access</h4>
        {allChannels.length === 0 ? (
          <p className="text-text-muted text-xs">No text channels found.</p>
        ) : (
          <div className="flex flex-col gap-1">
            {allChannels.map((ch) => {
              const hasAccess = botChannelIds.has(ch.id);
              const isLoading = channelLoading === ch.id;
              return (
                <label
                  key={ch.id}
                  className="min-h-11 md:min-h-9 flex items-center gap-2 px-2 py-1.5 rounded hover:bg-surface-hover cursor-pointer text-sm"
                >
                  <input
                    type="checkbox"
                    checked={hasAccess}
                    disabled={isLoading}
                    onChange={() => toggleChannel(ch.id, hasAccess)}
                    className="accent-primary"
                  />
                  <span className="text-text-muted">#</span>
                  <span className="text-text">{ch.name}</span>
                  {isLoading && <span className="text-text-muted text-xs ml-auto">...</span>}
                  {hasAccess && (
                    <span
                      className="ml-auto flex items-center gap-1 text-xs text-text-muted"
                      title="Lets this bot give other agents instructions in this channel. Only the server owner can change it."
                      onClick={(e) => e.stopPropagation()}
                    >
                      <input
                        type="checkbox"
                        checked={directChannelIds.has(ch.id)}
                        disabled={isLoading}
                        onChange={() => toggleDirect(ch.id, directChannelIds.has(ch.id))}
                        className="accent-primary"
                      />
                      can direct agents
                    </span>
                  )}
                </label>
              );
            })}
          </div>
        )}
      </section>

      {/* ── Tokens (owner / admin only) ── */}
      {detail.canManageTokens && (
        <section>
          <Button onClick={() => setShowInvite(true)}>Invite Agent</Button>
          {showInvite && <CreateAgentInviteModal serverId={serverId} botId={botId} onClose={() => setShowInvite(false)} onCreated={() => {}} />}
          <div className="flex items-center justify-between mb-2">
            <h4 className="text-sm font-semibold text-text">Tokens</h4>
            <Button
              variant="secondary"
              className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
              onClick={() => setShowCreateToken(true)}
            >
              New Token
            </Button>
          </div>
          {activeTokens.length === 0 && revokedTokens.length === 0 ? (
            <p className="text-text-muted text-xs">No tokens yet.</p>
          ) : (
            <div className="flex flex-col gap-1">
              {activeTokens.map((t) => (
                <div key={t.id} className="flex items-center justify-between px-2 py-1.5 rounded bg-surface text-sm">
                  <div>
                    <span className="text-text">{t.name || 'Unnamed'}</span>
                    <span className="text-text-muted text-xs ml-2">
                      Created {new Date(t.createdAt).toLocaleDateString()}
                    </span>
                    {t.lastUsedAt && (
                      <span className="text-text-muted text-xs ml-2">
                        Last used {new Date(t.lastUsedAt).toLocaleDateString()}
                        {t.lastUsedClient ? ` by ${t.lastUsedClient}` : ''}
                        {t.lastUsedIp ? ` from ${t.lastUsedIp}` : ''}
                      </span>
                    )}
                    {t.boundClient && (
                      <span className="text-text-muted text-xs ml-2" title="Requests from any other client are refused">
                        Bound to {t.boundClient}
                      </span>
                    )}
                    {t.lastRefused && (
                      <span className="block text-danger text-xs">
                        Refused {t.lastRefused.client ? `use by ${t.lastRefused.client}` : 'a use with no client name'}
                        {t.lastRefused.ip ? ` from ${t.lastRefused.ip}` : ''} on {new Date(t.lastRefused.at).toLocaleString()}.
                        If that wasn't you moving this agent, revoke the token.
                      </span>
                    )}
                  </div>
                  <div className="flex shrink-0">
                    {t.boundClient && (
                      <button
                        onClick={() => handleClearBinding(t.id)}
                        className="min-h-11 md:min-h-8 px-2 text-text-muted text-xs hover:underline"
                        title="The next client that uses the token binds it again"
                      >
                        Clear binding
                      </button>
                    )}
                    <button
                      onClick={() => handleRevokeToken(t.id)}
                      className="min-h-11 md:min-h-8 px-2 text-danger text-xs hover:underline"
                    >
                      Revoke
                    </button>
                  </div>
                </div>
              ))}
              {revokedTokens.map((t) => (
                <div key={t.id} className="flex items-center px-2 py-1.5 rounded bg-surface text-sm opacity-50">
                  <span className="text-text line-through">{t.name || 'Unnamed'}</span>
                  <span className="text-text-muted text-xs ml-2">Revoked</span>
                </div>
              ))}
            </div>
          )}

          <CreateTokenModal
            serverId={serverId}
            botId={botId}
            isOpen={showCreateToken}
            onClose={() => setShowCreateToken(false)}
            onCreated={async () => {
              const t = await botApi.listTokens(serverId, botId);
              setTokens(t);
            }}
          />
        </section>
      )}

      {/* ── Delete Bot ── */}
      <div className="pt-2 border-t border-border">
        <Button variant="danger" onClick={handleDelete} loading={deleting}>
          Delete Bot
        </Button>
      </div>
    </div>
  );
}

import { memo, useCallback, useDeferredValue, useEffect, useMemo, useRef, useState } from 'react';
import { Link } from 'react-router-dom';
import { defaultRangeExtractor, useVirtualizer } from '@tanstack/react-virtual';
import { Avatar } from '../../components/ui/Avatar';
import { useServerStore } from '../../stores/serverStore';
import { useChannelStore } from '../../stores/channelStore';
import { botApi, serverApi, runtimeApi, ApiError } from '../../lib/api';
import type { Bot, BotDetail, BotToken, RuntimeAccess } from '../../lib/api';
import type { Channel } from '../../lib/contracts/server';
import { Button } from '../../components/ui/Button';
import { CreateBotModal } from './CreateBotModal';
import { CreateTokenModal } from './CreateTokenModal';
import { CreateAgentInviteModal } from './CreateAgentInviteModal';

export function BotManagement() {
  const instanceServerId = useServerStore(s => s.instanceServerId);
  const [bots, setBots] = useState<Bot[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [permissionDenied, setPermissionDenied] = useState(false);
  const [showCreateBot, setShowCreateBot] = useState(false);
  const [showInvite, setShowInvite] = useState(false);
  const [expandedBotId, setExpandedBotId] = useState<string | null>(null);
  const [query, setQuery] = useState('');
  const deferredQuery = useDeferredValue(query);

  const fetchBots = useCallback(async (showLoading = true) => {
    if (!instanceServerId) return;
    if (showLoading) setLoading(true);
    setError('');
    try {
      const data = await botApi.list(instanceServerId);
      setBots(data);
      setPermissionDenied(false);
    } catch (err) {
      if (err instanceof ApiError && err.status === 403) {
        setPermissionDenied(true);
      } else {
        setError(err instanceof ApiError ? err.code : 'Failed to load bots');
      }
    } finally {
      setLoading(false);
    }
  }, [instanceServerId]);

  useEffect(() => { fetchBots(); }, [fetchBots]);

  // A refresh after a change keeps the list (and its scroll position) on screen
  const refresh = useCallback(() => { void fetchBots(false); }, [fetchBots]);
  let toggle = useCallback((botId: string) => setExpandedBotId(cur => (cur === botId ? null : botId)), []);

  // Newest first, so a bot you just created is at the top of a long list
  const sorted = useMemo(() => [...bots].sort((a, b) => b.createdAt.localeCompare(a.createdAt)), [bots]);
  const shown = useMemo(() => {
    const q = deferredQuery.trim().toLowerCase();
    return q ? sorted.filter(b => b.username.toLowerCase().includes(q)) : sorted;
  }, [sorted, deferredQuery]);

  if (!instanceServerId) return null;

  if (permissionDenied) {
    return (
      <div>
        <h2 className="text-xl font-bold text-text mb-4">Bot Management</h2>
        <p className="text-text-muted mb-4">You don't have permission to manage bots.</p>
        <Link to="/app" className="hidden min-h-11 items-center text-primary-text hover:underline sm:inline-flex md:min-h-8">Back to chat</Link>
      </div>
    );
  }

  if (loading) {
    return <p className="text-text-muted">Loading bots...</p>;
  }

  return (
    <div>
      <div className="flex flex-wrap items-center justify-between gap-3 mb-6">
        <h2 className="text-xl font-bold text-text">Bot Management</h2>
        <div className="flex gap-2">
          <Button onClick={() => setShowInvite(true)}>Invite Agent</Button>
          <Button variant="secondary" onClick={() => setShowCreateBot(true)}>Create Bot</Button>
        </div>
      </div>

      {error && <p className="text-danger text-sm mb-4">{error}</p>}

      <ChannelLoopGuardSection serverId={instanceServerId} />

      {bots.length === 0 ? (
        <p className="text-text-muted">No bots yet. Create one to get started.</p>
      ) : (
        <section>
          <div className="flex flex-wrap items-center gap-3 mb-2">
            <input
              type="search"
              value={query}
              onChange={e => setQuery(e.target.value)}
              placeholder="Search bots"
              aria-label="Search bots"
              className="min-h-11 md:min-h-9 w-full max-w-xs px-3 py-1.5 rounded border border-border bg-surface text-text placeholder:text-text-muted/70 text-sm"
            />
            <span className="text-text-muted text-xs" aria-live="polite">
              {shown.length === bots.length ? `${bots.length} bots` : `${shown.length} of ${bots.length} bots`}
            </span>
          </div>
          {shown.length === 0 ? (
            <p className="text-text-muted text-sm">No bots match “{deferredQuery.trim()}”.</p>
          ) : (
            <BotList
              bots={shown}
              serverId={instanceServerId}
              expandedBotId={expandedBotId}
              onToggle={toggle}
              onChanged={refresh}
            />
          )}
        </section>
      )}

      <CreateBotModal
        serverId={instanceServerId}
        isOpen={showCreateBot}
        onClose={() => setShowCreateBot(false)}
        onCreated={refresh}
      />
      {showInvite && <CreateAgentInviteModal serverId={instanceServerId} onClose={() => setShowInvite(false)} onCreated={refresh} />}
    </div>
  );
}

// ─── Bot List (virtualized) ───────────────────────────────────────────────

/** Rendering every bot stalled the page at about 1,800 bots (#241): only the rows in view are mounted. */
function BotList({
  bots,
  serverId,
  expandedBotId,
  onToggle,
  onChanged,
}: {
  bots: Bot[];
  serverId: string;
  expandedBotId: string | null;
  onToggle: (botId: string) => void;
  onChanged: () => void;
}) {
  const scrollRef = useRef<HTMLDivElement>(null);
  const expandedIndex = expandedBotId ? bots.findIndex(b => b.id === expandedBotId) : -1;
  // This component is not compiled by the React Compiler; the virtualizer is read during render only
  // eslint-disable-next-line react-hooks/incompatible-library
  const virtualizer = useVirtualizer({
    count: bots.length,
    getScrollElement: () => scrollRef.current,
    estimateSize: () => 60,
    overscan: 8,
    getItemKey: index => bots[index].id,
    // The open bot stays mounted while scrolled away, so its panel (a half-made token, an error) survives
    rangeExtractor: range => {
      const indexes = defaultRangeExtractor(range);
      return expandedIndex < 0 || indexes.includes(expandedIndex) ? indexes : [...indexes, expandedIndex].sort((a, b) => a - b);
    },
  });

  return (
    <div ref={scrollRef} data-testid="bot-list" className="max-h-[70vh] overflow-y-auto overscroll-contain">
      <div className="relative w-full" style={{ height: virtualizer.getTotalSize() }}>
        {virtualizer.getVirtualItems().map(item => {
          const bot = bots[item.index];
          return (
            <div
              key={item.key}
              data-index={item.index}
              ref={virtualizer.measureElement}
              className="absolute left-0 top-0 w-full pb-2"
              style={{ transform: `translateY(${item.start}px)` }}
            >
              <BotRow
                bot={bot}
                serverId={serverId}
                isExpanded={expandedBotId === bot.id}
                onToggle={onToggle}
                onChanged={onChanged}
              />
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ─── Channel Loop Guard Settings ──────────────────────────────────────────

type GuardField = 'maxBotHops' | 'maxThreadBotHops';
type Limits = Record<GuardField, number>;
/** The limit a guard gets when it is switched on with no earlier value to restore. */
const GUARD_DEFAULT: Limits = { maxBotHops: 4, maxThreadBotHops: 4 };

/**
 * Both loop guards per channel (#23): the channel guard (top-level bot messages in a row)
 * and the thread guard (bot replies in a row inside one thread). Each has an on/off switch;
 * off is a limit of 0.
 */
function ChannelLoopGuardSection({ serverId }: { serverId: string }) {
  const [channels, setChannels] = useState<Channel[]>([]);
  // Limits as loaded or last confirmed by a save here
  const [loaded, setLoaded] = useState<Record<string, Limits>>({});
  // Edits not yet confirmed by the server, by `${channelId}:${field}`
  const [dirty, setDirty] = useState<Record<string, number>>({});
  const [saving, setSaving] = useState<Record<string, boolean>>({});
  const [error, setError] = useState('');
  // A change made elsewhere (a notice's Raise limit or Turn off) arrives as ChannelBotConfig
  const live = useChannelStore(s => s.channels);
  const pending = useRef<Record<string, { timer: ReturnType<typeof setTimeout>; value: number }>>({});
  // Saves of one field go out one at a time, in order, so the last change made wins
  const queues = useRef<Record<string, Promise<void>>>({});
  // The last limit above 0, restored when a guard is switched back on
  const lastOn = useRef<Record<string, number>>({});
  const mounted = useRef(true);

  useEffect(() => {
    serverApi.getChannels(serverId).then((chs) => {
      const textChannels = chs.filter(c => c.channelType === 3);
      setChannels(textChannels);
      const initial: Record<string, Limits> = {};
      for (const ch of textChannels) {
        initial[ch.id] = { maxBotHops: ch.maxBotHops ?? 4, maxThreadBotHops: ch.maxThreadBotHops ?? 0 };
      }
      setLoaded(initial);
    }).catch(() => setError('Failed to load channels'));
  }, [serverId]);

  // enqueue only touches refs and state setters, so the first render's copy stays valid for the unmount flush
  const enqueueOnLeave = useRef(enqueue);

  // Leaving the page sends a change still waiting out its debounce instead of dropping it,
  // behind any save of that field still in flight so the older one cannot land last
  useEffect(() => {
    mounted.current = true;
    const waiting = pending.current;
    const flush = enqueueOnLeave.current;
    return () => {
      mounted.current = false;
      for (const [key, p] of Object.entries(waiting)) {
        clearTimeout(p.timer);
        delete waiting[key];
        const [channelId, field] = key.split(':') as [string, GuardField];
        flush(channelId, field, p.value);
      }
    };
  }, []);

  const shown = (channelId: string, field: GuardField): number => {
    const key = `${channelId}:${field}`;
    return dirty[key] ?? live.get(channelId)?.[field] ?? loaded[channelId]?.[field] ?? GUARD_DEFAULT[field];
  };

  function change(channelId: string, field: GuardField, value: number, delay: number) {
    const key = `${channelId}:${field}`;
    const prev = shown(channelId, field);
    if (prev > 0) lastOn.current[key] = prev;
    setDirty(d => ({ ...d, [key]: value }));
    if (pending.current[key]) clearTimeout(pending.current[key].timer);
    const timer = setTimeout(() => {
      delete pending.current[key];
      enqueue(channelId, field, value);
    }, delay);
    pending.current[key] = { timer, value };
  }

  /** Queues a save behind any earlier save of the same field (save never rejects). */
  function enqueue(channelId: string, field: GuardField, value: number) {
    const key = `${channelId}:${field}`;
    queues.current[key] = (queues.current[key] ?? Promise.resolve()).then(() => save(channelId, field, value));
  }

  function handleNumber(channelId: string, field: GuardField, raw: string) {
    const num = parseInt(raw, 10);
    // 0 would be "off": that is the switch's job, so the box keeps a limit while typing
    if (isNaN(num) || num < 1 || num > 1000) return;
    change(channelId, field, num, 600);
  }

  function handleToggle(channelId: string, field: GuardField, on: boolean) {
    const restore = lastOn.current[`${channelId}:${field}`] ?? GUARD_DEFAULT[field];
    change(channelId, field, on ? restore : 0, 0);
  }

  async function save(channelId: string, field: GuardField, value: number) {
    const key = `${channelId}:${field}`;
    if (mounted.current) { setSaving(s => ({ ...s, [key]: true })); setError(''); }
    // Only the latest edit clears the dirty value; an older save finishing must not
    const settle = (d: Record<string, number>) => {
      if (d[key] !== value || pending.current[key]) return d;
      const next = { ...d };
      delete next[key];
      return next;
    };
    try {
      const config = await botApi.updateChannelBotConfig(channelId, { [field]: value });
      useChannelStore.getState().patchChannel(channelId, { maxBotHops: config.maxBotHops, maxThreadBotHops: config.maxThreadBotHops });
      if (!mounted.current) return;
      setLoaded(l => ({ ...l, [channelId]: { maxBotHops: config.maxBotHops, maxThreadBotHops: config.maxThreadBotHops } }));
      setDirty(settle);
    } catch (err) {
      if (!mounted.current) return;
      // Show what the server still has, not the value that failed
      setDirty(settle);
      setError(err instanceof ApiError ? err.code : 'Failed to save');
    } finally {
      if (mounted.current) setSaving(s => ({ ...s, [key]: false }));
    }
  }

  if (channels.length === 0) return null;

  const guard = (ch: Channel, field: GuardField, label: string, unit: string) => {
    const value = shown(ch.id, field);
    const on = value > 0;
    const key = `${ch.id}:${field}`;
    return (
      <div className="flex items-center gap-2">
        <label className="min-h-11 md:min-h-8 flex items-center gap-1.5 text-xs text-text-muted cursor-pointer">
          <input
            type="checkbox"
            role="switch"
            checked={on}
            onChange={e => handleToggle(ch.id, field, e.target.checked)}
            aria-label={`${label} loop guard in #${ch.name}`}
            className="accent-primary"
          />
          {label}
        </label>
        {on ? (
          <input
            type="number"
            min={1}
            max={1000}
            value={value}
            onChange={e => handleNumber(ch.id, field, e.target.value)}
            aria-label={`${label} limit in #${ch.name} (${unit})`}
            title={`Pause after this many ${unit} in a row`}
            className="min-h-11 md:min-h-8 w-16 px-2 py-1 rounded border border-border bg-surface text-text text-sm text-right"
          />
        ) : (
          <span className="w-16 text-text-muted text-xs">Off</span>
        )}
        <span className="w-12 text-text-muted text-xs" aria-live="polite">{saving[key] ? 'Saving…' : ''}</span>
      </div>
    );
  };

  return (
    <section className="mb-6">
      <h3 className="text-sm font-semibold text-text mb-2">Loop Guard</h3>
      <p className="text-text-muted text-xs mb-3">
        Pauses agents after this many bot posts in a row with no human message. The channel guard counts top-level
        messages; the thread guard counts replies inside each thread. A human message resets both, and the notice
        it posts has Continue, Raise limit and Turn off buttons.
      </p>
      {error && <p className="text-danger text-xs mb-2" role="alert">{error}</p>}
      <div className="flex flex-col gap-1">
        {channels.map((ch) => (
          <div key={ch.id} className="flex flex-wrap items-center gap-x-6 gap-y-1 px-2 py-1.5 rounded hover:bg-surface-hover">
            <span className="flex min-w-32 flex-1 items-center gap-1 text-sm">
              <span className="text-text-muted">#</span>
              <span className="text-text">{ch.name}</span>
            </span>
            {guard(ch, 'maxBotHops', 'Channel', 'bot messages')}
            {guard(ch, 'maxThreadBotHops', 'Threads', 'bot replies in one thread')}
          </div>
        ))}
      </div>
    </section>
  );
}

// ─── Bot Row (expandable) ─────────────────────────────────────────────────

// Memoized with stable callbacks: opening one bot re-renders that row, not the whole list
const BotRow = memo(function BotRow({
  bot,
  serverId,
  isExpanded,
  onToggle,
  onChanged,
}: {
  bot: Bot;
  serverId: string;
  isExpanded: boolean;
  onToggle: (botId: string) => void;
  onChanged: () => void;
}) {
  const [pausing, setPausing] = useState(false);
  const [pauseError, setPauseError] = useState('');
  const [savingAccess, setSavingAccess] = useState(false);
  const isPaused = !!bot.pausedAt;

  async function changeAccess(access: RuntimeAccess) {
    if (access === 'auto' && !confirm(`Let ${bot.username} run code without approval? Runs still execute in the sandbox with its limits.`)) return;
    setSavingAccess(true);
    setPauseError('');
    try {
      await runtimeApi.setBotAccess(serverId, bot.id, access);
      onChanged();
    } catch (err) {
      setPauseError(err instanceof ApiError ? err.code : 'Failed to update code run access');
    } finally {
      setSavingAccess(false);
    }
  }

  async function togglePause() {
    setPausing(true);
    setPauseError('');
    try {
      if (isPaused) {
        await botApi.setPaused(serverId, bot.id, false);
      } else {
        const reason = prompt('Pause this bot? It will be read-only until resumed.\n\nReason (optional):');
        if (reason === null) return;
        await botApi.setPaused(serverId, bot.id, true, reason.trim() || undefined);
      }
      onChanged();
    } catch (err) {
      setPauseError(err instanceof ApiError ? err.code : 'Failed to update pause state');
    } finally {
      setPausing(false);
    }
  }

  return (
    <div className="border border-border rounded-lg overflow-hidden">
      <div className="flex items-center hover:bg-surface-hover">
      <button
        onClick={() => onToggle(bot.id)}
        aria-expanded={isExpanded}
        className="min-h-11 flex-1 flex items-center justify-between px-4 py-3 text-left"
      >
        <div>
          <span className="text-text font-medium">{bot.username}</span>
          {isPaused && (
            <span
              className="ml-2 inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-semibold leading-none bg-warn/20 text-warn"
              title={bot.pausedReason ? `Paused: ${bot.pausedReason}` : 'Paused'}
            >
              PAUSED
            </span>
          )}
          <span className="text-text-muted text-xs ml-2">
            {new Date(bot.createdAt).toLocaleDateString()}
          </span>
          {pauseError && <span className="text-danger text-xs ml-2">{pauseError}</span>}
        </div>
        <svg
          className="h-4 w-4 text-text-muted transition-transform"
          style={{ transform: isExpanded ? 'rotate(180deg)' : 'rotate(0deg)' }}
          fill="none"
          viewBox="0 0 24 24"
          stroke="currentColor"
          strokeWidth="2"
        >
          <polyline points="6 9 12 15 18 9" />
        </svg>
      </button>
      <label className="flex items-center gap-1 pr-3 text-xs text-text-muted" title="Whether this bot may run code in the sandbox">
        Code runs
        <select
          className="min-h-11 md:min-h-8 bg-surface border border-border rounded px-2 py-1 text-xs text-text"
          value={bot.runtimeAccess ?? 'none'}
          disabled={savingAccess}
          onChange={e => changeAccess(e.target.value as RuntimeAccess)}
          aria-label={`Code run access for ${bot.username}`}
        >
          <option value="none">Off</option>
          <option value="approval">Need approval</option>
          <option value="auto">Auto-run</option>
        </select>
      </label>
      <div className="pr-3">
        <Button variant="secondary" onClick={togglePause} loading={pausing}>
          {isPaused ? 'Resume' : 'Pause'}
        </Button>
      </div>
      </div>
      {isExpanded && (
        <BotDetailPanel botId={bot.id} serverId={serverId} onDeleted={onChanged} />
      )}
    </div>
  );
});

// ─── Bot Detail Panel ─────────────────────────────────────────────────────

function BotDetailPanel({
  botId,
  serverId,
  onDeleted,
}: {
  botId: string;
  serverId: string;
  onDeleted: () => void;
}) {
  const [detail, setDetail] = useState<BotDetail | null>(null);
  const [allChannels, setAllChannels] = useState<Channel[]>([]);
  const [tokens, setTokens] = useState<BotToken[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [showCreateToken, setShowCreateToken] = useState(false);
  const [showInvite, setShowInvite] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [channelLoading, setChannelLoading] = useState<string | null>(null);
  const [avatarInput, setAvatarInput] = useState('');
  const [avatarSaving, setAvatarSaving] = useState(false);
  const [avatarError, setAvatarError] = useState('');

  const fetchDetail = useCallback(async () => {
    try {
      const [d, channels] = await Promise.all([
        botApi.get(serverId, botId),
        serverApi.getChannels(serverId),
      ]);
      setDetail(d);
      setAvatarInput(d.avatarUrl || '');
      // Only show text channels (type 3) for bot access
      setAllChannels(channels.filter(c => c.channelType === 3));
      if (d.canManageTokens) {
        const t = await botApi.listTokens(serverId, botId);
        setTokens(t);
      }
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to load bot details');
    } finally {
      setLoading(false);
    }
  }, [serverId, botId]);

  useEffect(() => { fetchDetail(); }, [fetchDetail]);

  async function handleDelete() {
    if (!confirm('Delete this bot? This cannot be undone.')) return;
    setDeleting(true);
    try {
      await botApi.remove(serverId, botId);
      onDeleted();
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to delete bot');
      setDeleting(false);
    }
  }

  async function handleRevokeToken(tokenId: string) {
    try {
      await botApi.revokeToken(serverId, botId, tokenId);
      setTokens(prev => prev.map(t => t.id === tokenId ? { ...t, revokedAt: new Date().toISOString() } : t));
    } catch (err) {
      if (err instanceof ApiError && err.status === 403) {
        // Permissions changed — refetch detail
        fetchDetail();
      }
      setError(err instanceof ApiError ? err.code : 'Failed to revoke token');
    }
  }

  async function handleClearBinding(tokenId: string) {
    try {
      await botApi.clearTokenBinding(serverId, botId, tokenId);
      setTokens(prev => prev.map(t => t.id === tokenId ? { ...t, boundClient: null, boundAt: null, lastRefused: null } : t));
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to clear the binding');
    }
  }

  async function toggleDirect(channelId: string, canDirect: boolean) {
    setChannelLoading(channelId);
    setError('');
    try {
      await botApi.setCanDirect(channelId, botId, !canDirect);
      setDetail(await botApi.get(serverId, botId));
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to update who may direct');
    } finally {
      setChannelLoading(null);
    }
  }

  async function toggleChannel(channelId: string, hasAccess: boolean) {
    setChannelLoading(channelId);
    try {
      if (hasAccess) {
        await botApi.revokeChannel(channelId, botId);
      } else {
        await botApi.grantChannel(channelId, botId);
      }
      // Refetch detail to get updated channel list
      const d = await botApi.get(serverId, botId);
      setDetail(d);
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to update channel access');
    } finally {
      setChannelLoading(null);
    }
  }

  if (loading) {
    return <div className="px-4 py-3 border-t border-border text-text-muted text-sm">Loading...</div>;
  }

  if (error && !detail) {
    return <div className="px-4 py-3 border-t border-border text-danger text-sm">{error}</div>;
  }

  if (!detail) return null;

  const botChannelIds = new Set(detail.channels.map(c => c.id));
  const directChannelIds = new Set(detail.channels.filter(c => c.canDirect).map(c => c.id));
  const activeTokens = tokens.filter(t => !t.revokedAt);
  const revokedTokens = tokens.filter(t => t.revokedAt);

  return (
    <div className="border-t border-border px-4 py-4 flex flex-col gap-5 bg-bg/50">
      {error && <p className="text-danger text-sm">{error}</p>}

      {/* ── Avatar ── */}
      <section>
        <h4 className="text-sm font-semibold text-text mb-2">Avatar</h4>
        <div className="flex items-start gap-3">
          <Avatar userId={botId} username={detail.username} avatarUrl={detail.avatarUrl} className="h-12 w-12 text-sm" />
          <div className="flex-1 min-w-0">
            <input
              type="text"
              value={avatarInput}
              onChange={(e) => { setAvatarInput(e.target.value); setAvatarError(''); }}
              placeholder="data:image/svg+xml;base64,..."
              className="min-h-11 md:min-h-9 w-full px-3 py-1.5 rounded border border-border bg-surface text-text placeholder:text-text-muted/70 text-sm"
            />
            {avatarError && <p className="text-danger text-xs mt-1">{avatarError}</p>}
            <div className="flex gap-2 mt-2">
              <Button
                variant="secondary"
                className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
                loading={avatarSaving}
                onClick={async () => {
                  setAvatarSaving(true);
                  setAvatarError('');
                  try {
                    const res = await botApi.update(serverId, botId, { avatarUrl: avatarInput || null });
                    setDetail(prev => prev ? { ...prev, avatarUrl: res.avatarUrl } : prev);
                  } catch (err) {
                    setAvatarError(err instanceof ApiError ? err.code : 'Failed to save avatar');
                  } finally {
                    setAvatarSaving(false);
                  }
                }}
              >
                Save Avatar
              </Button>
              {detail.avatarUrl && (
                <Button
                  variant="secondary"
                  className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
                  onClick={async () => {
                    setAvatarSaving(true);
                    setAvatarError('');
                    try {
                      const res = await botApi.update(serverId, botId, { avatarUrl: null });
                      setDetail(prev => prev ? { ...prev, avatarUrl: res.avatarUrl } : prev);
                      setAvatarInput('');
                    } catch (err) {
                      setAvatarError(err instanceof ApiError ? err.code : 'Failed to remove avatar');
                    } finally {
                      setAvatarSaving(false);
                    }
                  }}
                >
                  Remove
                </Button>
              )}
            </div>
          </div>
        </div>
      </section>

      {/* ── Channel Access ── */}
      <section>
        <h4 className="text-sm font-semibold text-text mb-2">Channel Access</h4>
        {allChannels.length === 0 ? (
          <p className="text-text-muted text-xs">No text channels found.</p>
        ) : (
          <div className="flex flex-col gap-1">
            {allChannels.map((ch) => {
              const hasAccess = botChannelIds.has(ch.id);
              const isLoading = channelLoading === ch.id;
              return (
                <label
                  key={ch.id}
                  className="min-h-11 md:min-h-9 flex items-center gap-2 px-2 py-1.5 rounded hover:bg-surface-hover cursor-pointer text-sm"
                >
                  <input
                    type="checkbox"
                    checked={hasAccess}
                    disabled={isLoading}
                    onChange={() => toggleChannel(ch.id, hasAccess)}
                    className="accent-primary"
                  />
                  <span className="text-text-muted">#</span>
                  <span className="text-text">{ch.name}</span>
                  {isLoading && <span className="text-text-muted text-xs ml-auto">...</span>}
                  {hasAccess && (
                    <span
                      className="ml-auto flex items-center gap-1 text-xs text-text-muted"
                      title="Lets this bot give other agents instructions in this channel. Only the server owner can change it."
                      onClick={(e) => e.stopPropagation()}
                    >
                      <input
                        type="checkbox"
                        checked={directChannelIds.has(ch.id)}
                        disabled={isLoading}
                        onChange={() => toggleDirect(ch.id, directChannelIds.has(ch.id))}
                        className="accent-primary"
                      />
                      can direct agents
                    </span>
                  )}
                </label>
              );
            })}
          </div>
        )}
      </section>

      {/* ── Tokens (owner / admin only) ── */}
      {detail.canManageTokens && (
        <section>
          <Button onClick={() => setShowInvite(true)}>Invite Agent</Button>
          {showInvite && <CreateAgentInviteModal serverId={serverId} botId={botId} onClose={() => setShowInvite(false)} onCreated={() => {}} />}
          <div className="flex items-center justify-between mb-2">
            <h4 className="text-sm font-semibold text-text">Tokens</h4>
            <Button
              variant="secondary"
              className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
              onClick={() => setShowCreateToken(true)}
            >
              New Token
            </Button>
          </div>
          {activeTokens.length === 0 && revokedTokens.length === 0 ? (
            <p className="text-text-muted text-xs">No tokens yet.</p>
          ) : (
            <div className="flex flex-col gap-1">
              {activeTokens.map((t) => (
                <div key={t.id} className="flex items-center justify-between px-2 py-1.5 rounded bg-surface text-sm">
                  <div>
                    <span className="text-text">{t.name || 'Unnamed'}</span>
                    <span className="text-text-muted text-xs ml-2">
                      Created {new Date(t.createdAt).toLocaleDateString()}
                    </span>
                    {t.lastUsedAt && (
                      <span className="text-text-muted text-xs ml-2">
                        Last used {new Date(t.lastUsedAt).toLocaleDateString()}
                        {t.lastUsedClient ? ` by ${t.lastUsedClient}` : ''}
                        {t.lastUsedIp ? ` from ${t.lastUsedIp}` : ''}
                      </span>
                    )}
                    {t.boundClient && (
                      <span className="text-text-muted text-xs ml-2" title="Requests from any other client are refused">
                        Bound to {t.boundClient}
                      </span>
                    )}
                    {t.lastRefused && (
                      <span className="block text-danger text-xs">
                        Refused {t.lastRefused.client ? `use by ${t.lastRefused.client}` : 'a use with no client name'}
                        {t.lastRefused.ip ? ` from ${t.lastRefused.ip}` : ''} on {new Date(t.lastRefused.at).toLocaleString()}.
                        If that wasn't you moving this agent, revoke the token.
                      </span>
                    )}
                  </div>
                  <div className="flex shrink-0">
                    {t.boundClient && (
                      <button
                        onClick={() => handleClearBinding(t.id)}
                        className="min-h-11 md:min-h-8 px-2 text-text-muted text-xs hover:underline"
                        title="The next client that uses the token binds it again"
                      >
                        Clear binding
                      </button>
                    )}
                    <button
                      onClick={() => handleRevokeToken(t.id)}
                      className="min-h-11 md:min-h-8 px-2 text-danger text-xs hover:underline"
                    >
                      Revoke
                    </button>
                  </div>
                </div>
              ))}
              {revokedTokens.map((t) => (
                <div key={t.id} className="flex items-center px-2 py-1.5 rounded bg-surface text-sm opacity-50">
                  <span className="text-text line-through">{t.name || 'Unnamed'}</span>
                  <span className="text-text-muted text-xs ml-2">Revoked</span>
                </div>
              ))}
            </div>
          )}

          <CreateTokenModal
            serverId={serverId}
            botId={botId}
            isOpen={showCreateToken}
            onClose={() => setShowCreateToken(false)}
            onCreated={async () => {
              const t = await botApi.listTokens(serverId, botId);
              setTokens(t);
            }}
          />
        </section>
      )}

      {/* ── Delete Bot ── */}
      <div className="pt-2 border-t border-border">
        <Button variant="danger" onClick={handleDelete} loading={deleting}>
          Delete Bot
        </Button>
      </div>
    </div>
  );
}

import { memo, useCallback, useDeferredValue, useEffect, useMemo, useRef, useState } from 'react';
import { Link } from 'react-router-dom';
import { defaultRangeExtractor, useVirtualizer } from '@tanstack/react-virtual';
import { Avatar } from '../../components/ui/Avatar';
import { useServerStore } from '../../stores/serverStore';
import { useChannelStore } from '../../stores/channelStore';
import { botApi, serverApi, runtimeApi, ApiError } from '../../lib/api';
import type { Bot, BotDetail, BotToken, RuntimeAccess } from '../../lib/api';
import type { Channel } from '../../lib/contracts/server';
import { Button } from '../../components/ui/Button';
import { CreateBotModal } from './CreateBotModal';
import { CreateTokenModal } from './CreateTokenModal';
import { CreateAgentInviteModal } from './CreateAgentInviteModal';

export function BotManagement() {
  const instanceServerId = useServerStore(s => s.instanceServerId);
  const [bots, setBots] = useState<Bot[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [permissionDenied, setPermissionDenied] = useState(false);
  const [showCreateBot, setShowCreateBot] = useState(false);
  const [showInvite, setShowInvite] = useState(false);
  const [expandedBotId, setExpandedBotId] = useState<string | null>(null);
  const [query, setQuery] = useState('');
  const deferredQuery = useDeferredValue(query);

  const fetchBots = useCallback(async (showLoading = true) => {
    if (!instanceServerId) return;
    showLoading && setLoading(true);
    setError('');
    try {
      const data = await botApi.list(instanceServerId);
      setBots(data);
      setPermissionDenied(false);
    } catch (err) {
      if (err instanceof ApiError && err.status === 403) {
        setPermissionDenied(true);
      } else {
        setError(err instanceof ApiError ? err.code : 'Failed to load bots');
      }
    } finally {
      setLoading(false);
    }
  }, [instanceServerId]);

  useEffect(() => { fetchBots(); }, [fetchBots]);

  // A refresh after a change keeps the list (and its scroll position) on screen
  const refresh = useCallback(() => { void fetchBots(false); }, [fetchBots]);
  const toggle = useCallback((botId: string) => setExpandedBotId(cur => (cur === botId ? null : botId)), []);

  // Newest first, so a bot you just created is at the top of a long list
  const sorted = useMemo(() => [...bots].sort((a, b) => b.createdAt.localeCompare(a.createdAt)), [bots]);
  const shown = useMemo(() => {
    const q = deferredQuery.trim().toLowerCase();
    return q ? sorted.filter(b => b.username.toLowerCase().includes(q)) : sorted;
  }, [sorted, deferredQuery]);

  if (!instanceServerId) return null;

  if (permissionDenied) {
    return (
      <div>
        <h2 className="text-xl font-bold text-text mb-4">Bot Management</h2>
        <p className="text-text-muted mb-4">You don't have permission to manage bots.</p>
        <Link to="/app" className="hidden min-h-11 items-center text-primary-text hover:underline sm:inline-flex md:min-h-8">Back to chat</Link>
      </div>
    );
  }

  if (loading) {
    return <p className="text-text-muted">Loading bots...</p>;
  }

  return (
    <div>
      <div className="flex flex-wrap items-center justify-between gap-3 mb-6">
        <h2 className="text-xl font-bold text-text">Bot Management</h2>
        <div className="flex gap-2">
          <Button onClick={() => setShowInvite(true)}>Invite Agent</Button>
          <Button variant="secondary" onClick={() => setShowCreateBot(true)}>Create Bot</Button>
        </div>
      </div>

      {error && <p className="text-danger text-sm mb-4">{error}</p>}

      <ChannelLoopGuardSection serverId={instanceServerId} />

      {bots.length === 0 ? (
        <p className="text-text-muted">No bots yet. Create one to get started.</p>
      ) : (
        <section>
          <div className="flex flex-wrap items-center gap-3 mb-2">
            <input
              type="search"
              value={query}
              onChange={e => setQuery(e.target.value)}
              placeholder="Search bots"
              aria-label="Search bots"
              className="min-h-11 md:min-h-9 w-full max-w-xs px-3 py-1.5 rounded border border-border bg-surface text-text placeholder:text-text-muted/70 text-sm"
            />
            <span className="text-text-muted text-xs" aria-live="polite">
              {shown.length === bots.length ? `${bots.length} bots` : `${shown.length} of ${bots.length} bots`}
            </span>
          </div>
          {shown.length === 0 ? (
            <p className="text-text-muted text-sm">No bots match “{deferredQuery.trim()}”.</p>
          ) : (
            <BotList
              bots={shown}
              serverId={instanceServerId}
              expandedBotId={expandedBotId}
              onToggle={toggle}
              onChanged={refresh}
            />
          )}
        </section>
      )}

      <CreateBotModal
        serverId={instanceServerId}
        isOpen={showCreateBot}
        onClose={() => setShowCreateBot(false)}
        onCreated={refresh}
      />
      {showInvite && <CreateAgentInviteModal serverId={instanceServerId} onClose={() => setShowInvite(false)} onCreated={refresh} />}
    </div>
  );
}

// ─── Bot List (virtualized) ───────────────────────────────────────────────

/** Rendering every bot stalled the page at about 1,800 bots (#241): only the rows in view are mounted. */
function BotList({
  bots,
  serverId,
  expandedBotId,
  onToggle,
  onChanged,
}: {
  bots: Bot[];
  serverId: string;
  expandedBotId: string | null;
  onToggle: (botId: string) => void;
  onChanged: () => void;
}) {
  const scrollRef = useRef<HTMLDivElement>(null);
  const expandedIndex = expandedBotId ? bots.findIndex(b => b.id === expandedBotId) : -1;
  // This component is not compiled by the React Compiler; the virtualizer is read during render only
  // eslint-disable-next-line react-hooks/incompatible-library
  const virtualizer = useVirtualizer({
    count: bots.length,
    getScrollElement: () => scrollRef.current,
    estimateSize: () => 60,
    overscan: 8,
    getItemKey: index => bots[index].id,
    // The open bot stays mounted while scrolled away, so its panel (a half-made token, an error) survives
    rangeExtractor: range => {
      const indexes = defaultRangeExtractor(range);
      return expandedIndex < 0 || indexes.includes(expandedIndex) ? indexes : [...indexes, expandedIndex].sort((a, b) => a - b);
    },
  });

  return (
    <div ref={scrollRef} data-testid="bot-list" className="max-h-[70vh] overflow-y-auto overscroll-contain">
      <div className="relative w-full" style={{ height: virtualizer.getTotalSize() }}>
        {virtualizer.getVirtualItems().map(item => {
          const bot = bots[item.index];
          return (
            <div
              key={item.key}
              data-index={item.index}
              ref={virtualizer.measureElement}
              className="absolute left-0 top-0 w-full pb-2"
              style={{ transform: `translateY(${item.start}px)` }}
            >
              <BotRow
                bot={bot}
                serverId={serverId}
                isExpanded={expandedBotId === bot.id}
                onToggle={onToggle}
                onChanged={onChanged}
              />
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ─── Channel Loop Guard Settings ──────────────────────────────────────────

type GuardField = 'maxBotHops' | 'maxThreadBotHops';
type Limits = Record<GuardField, number>;
/** The limit a guard gets when it is switched on with no earlier value to restore. */
const GUARD_DEFAULT: Limits = { maxBotHops: 4, maxThreadBotHops: 4 };

/**
 * Both loop guards per channel (#23): the channel guard (top-level bot messages in a row)
 * and the thread guard (bot replies in a row inside one thread). Each has an on/off switch;
 * off is a limit of 0.
 */
function ChannelLoopGuardSection({ serverId }: { serverId: string }) {
  const [channels, setChannels] = useState<Channel[]>([]);
  // Limits as loaded or last confirmed by a save here
  const [loaded, setLoaded] = useState<Record<string, Limits>>({});
  // Edits not yet confirmed by the server, by `${channelId}:${field}`
  const [dirty, setDirty] = useState<Record<string, number>>({});
  const [saving, setSaving] = useState<Record<string, boolean>>({});
  const [error, setError] = useState('');
  // A change made elsewhere (a notice's Raise limit or Turn off) arrives as ChannelBotConfig
  const live = useChannelStore(s => s.channels);
  const pending = useRef<Record<string, { timer: ReturnType<typeof setTimeout>; value: number }>>({});
  // Saves of one field go out one at a time, in order, so the last change made wins
  const queues = useRef<Record<string, Promise<void>>>({});
  // The last limit above 0, restored when a guard is switched back on
  const lastOn = useRef<Record<string, number>>({});
  const mounted = useRef(true);

  useEffect(() => {
    serverApi.getChannels(serverId).then((chs) => {
      const textChannels = chs.filter(c => c.channelType === 3);
      setChannels(textChannels);
      const initial: Record<string, Limits> = {};
      for (const ch of textChannels) {
        initial[ch.id] = { maxBotHops: ch.maxBotHops ?? 4, maxThreadBotHops: ch.maxThreadBotHops ?? 0 };
      }
      setLoaded(initial);
    }).catch(() => setError('Failed to load channels'));
  }, [serverId]);

  // enqueue only touches refs and state setters, so the first render's copy stays valid for the unmount flush
  const enqueueOnLeave = useRef(enqueue);

  // Leaving the page sends a change still waiting out its debounce instead of dropping it,
  // behind any save of that field still in flight so the older one cannot land last
  useEffect(() => {
    mounted.current = true;
    const waiting = pending.current;
    const flush = enqueueOnLeave.current;
    return () => {
      mounted.current = false;
      for (const [key, p] of Object.entries(waiting)) {
        clearTimeout(p.timer);
        delete waiting[key];
        const [channelId, field] = key.split(':') as [string, GuardField];
        flush(channelId, field, p.value);
      }
    };
  }, []);

  const shown = (channelId: string, field: GuardField): number => {
    const key = `${channelId}:${field}`;
    return dirty[key] ?? live.get(channelId)?.[field] ?? loaded[channelId]?.[field] ?? GUARD_DEFAULT[field];
  };

  function change(channelId: string, field: GuardField, value: number, delay: number) {
    const key = `${channelId}:${field}`;
    const prev = shown(channelId, field);
    if (prev > 0) lastOn.current[key] = prev;
    setDirty(d => ({ ...d, [key]: value }));
    if (pending.current[key]) clearTimeout(pending.current[key].timer);
    const timer = setTimeout(() => {
      delete pending.current[key];
      enqueue(channelId, field, value);
    }, delay);
    pending.current[key] = { timer, value };
  }

  /** Queues a save behind any earlier save of the same field (save never rejects). */
  function enqueue(channelId: string, field: GuardField, value: number) {
    const key = `${channelId}:${field}`;
    queues.current[key] = (queues.current[key] ?? Promise.resolve()).then(() => save(channelId, field, value));
  }

  function handleNumber(channelId: string, field: GuardField, raw: string) {
    const num = parseInt(raw, 10);
    // 0 would be "off": that is the switch's job, so the box keeps a limit while typing
    if (isNaN(num) || num < 1 || num > 1000) return;
    change(channelId, field, num, 600);
  }

  function handleToggle(channelId: string, field: GuardField, on: boolean) {
    const restore = lastOn.current[`${channelId}:${field}`] ?? GUARD_DEFAULT[field];
    change(channelId, field, on ? restore : 0, 0);
  }

  async function save(channelId: string, field: GuardField, value: number) {
    const key = `${channelId}:${field}`;
    if (mounted.current) { setSaving(s => ({ ...s, [key]: true })); setError(''); }
    // Only the latest edit clears the dirty value; an older save finishing must not
    const settle = (d: Record<string, number>) => {
      if (d[key] !== value || pending.current[key]) return d;
      const next = { ...d };
      delete next[key];
      return next;
    };
    try {
      const config = await botApi.updateChannelBotConfig(channelId, { [field]: value });
      useChannelStore.getState().patchChannel(channelId, { maxBotHops: config.maxBotHops, maxThreadBotHops: config.maxThreadBotHops });
      if (!mounted.current) return;
      setLoaded(l => ({ ...l, [channelId]: { maxBotHops: config.maxBotHops, maxThreadBotHops: config.maxThreadBotHops } }));
      setDirty(settle);
    } catch (err) {
      if (!mounted.current) return;
      // Show what the server still has, not the value that failed
      setDirty(settle);
      setError(err instanceof ApiError ? err.code : 'Failed to save');
    } finally {
      if (mounted.current) setSaving(s => ({ ...s, [key]: false }));
    }
  }

  if (channels.length === 0) return null;

  const guard = (ch: Channel, field: GuardField, label: string, unit: string) => {
    const value = shown(ch.id, field);
    const on = value > 0;
    const key = `${ch.id}:${field}`;
    return (
      <div className="flex items-center gap-2">
        <label className="min-h-11 md:min-h-8 flex items-center gap-1.5 text-xs text-text-muted cursor-pointer">
          <input
            type="checkbox"
            role="switch"
            checked={on}
            onChange={e => handleToggle(ch.id, field, e.target.checked)}
            aria-label={`${label} loop guard in #${ch.name}`}
            className="accent-primary"
          />
          {label}
        </label>
        {on ? (
          <input
            type="number"
            min={1}
            max={1000}
            value={value}
            onChange={e => handleNumber(ch.id, field, e.target.value)}
            aria-label={`${label} limit in #${ch.name} (${unit})`}
            title={`Pause after this many ${unit} in a row`}
            className="min-h-11 md:min-h-8 w-16 px-2 py-1 rounded border border-border bg-surface text-text text-sm text-right"
          />
        ) : (
          <span className="w-16 text-text-muted text-xs">Off</span>
        )}
        <span className="w-12 text-text-muted text-xs" aria-live="polite">{saving[key] ? 'Saving…' : ''}</span>
      </div>
    );
  };

  return (
    <section className="mb-6">
      <h3 className="text-sm font-semibold text-text mb-2">Loop Guard</h3>
      <p className="text-text-muted text-xs mb-3">
        Pauses agents after this many bot posts in a row with no human message. The channel guard counts top-level
        messages; the thread guard counts replies inside each thread. A human message resets both, and the notice
        it posts has Continue, Raise limit and Turn off buttons.
      </p>
      {error && <p className="text-danger text-xs mb-2" role="alert">{error}</p>}
      <div className="flex flex-col gap-1">
        {channels.map((ch) => (
          <div key={ch.id} className="flex flex-wrap items-center gap-x-6 gap-y-1 px-2 py-1.5 rounded hover:bg-surface-hover">
            <span className="flex min-w-32 flex-1 items-center gap-1 text-sm">
              <span className="text-text-muted">#</span>
              <span className="text-text">{ch.name}</span>
            </span>
            {guard(ch, 'maxBotHops', 'Channel', 'bot messages')}
            {guard(ch, 'maxThreadBotHops', 'Threads', 'bot replies in one thread')}
          </div>
        ))}
      </div>
    </section>
  );
}

// ─── Bot Row (expandable) ─────────────────────────────────────────────────

// Memoized with stable callbacks: opening one bot re-renders that row, not the whole list
const BotRow = memo(function BotRow({
  bot,
  serverId,
  isExpanded,
  onToggle,
  onChanged,
}: {
  bot: Bot;
  serverId: string;
  isExpanded: boolean;
  onToggle: (botId: string) => void;
  onChanged: () => void;
}) {
  const [pausing, setPausing] = useState(false);
  const [pauseError, setPauseError] = useState('');
  const [savingAccess, setSavingAccess] = useState(false);
  const isPaused = !!bot.pausedAt;

  async function changeAccess(access: RuntimeAccess) {
    if (access === 'auto' && !confirm(`Let ${bot.username} run code without approval? Runs still execute in the sandbox with its limits.`)) return;
    setSavingAccess(true);
    setPauseError('');
    try {
      await runtimeApi.setBotAccess(serverId, bot.id, access);
      onChanged();
    } catch (err) {
      setPauseError(err instanceof ApiError ? err.code : 'Failed to update code run access');
    } finally {
      setSavingAccess(false);
    }
  }

  async function togglePause() {
    setPausing(true);
    setPauseError('');
    try {
      if (isPaused) {
        await botApi.setPaused(serverId, bot.id, false);
      } else {
        const reason = prompt('Pause this bot? It will be read-only until resumed.\n\nReason (optional):');
        if (reason === null) return;
        await botApi.setPaused(serverId, bot.id, true, reason.trim() || undefined);
      }
      onChanged();
    } catch (err) {
      setPauseError(err instanceof ApiError ? err.code : 'Failed to update pause state');
    } finally {
      setPausing(false);
    }
  }

  return (
    <div className="border border-border rounded-lg overflow-hidden">
      <div className="flex items-center hover:bg-surface-hover">
      <button
        onClick={() => onToggle(bot.id)}
        aria-expanded={isExpanded}
        className="min-h-11 flex-1 flex items-center justify-between px-4 py-3 text-left"
      >
        <div>
          <span className="text-text font-medium">{bot.username}</span>
          {isPaused && (
            <span
              className="ml-2 inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-semibold leading-none bg-warn/20 text-warn"
              title={bot.pausedReason ? `Paused: ${bot.pausedReason}` : 'Paused'}
            >
              PAUSED
            </span>
          )}
          <span className="text-text-muted text-xs ml-2">
            {new Date(bot.createdAt).toLocaleDateString()}
          </span>
          {pauseError && <span className="text-danger text-xs ml-2">{pauseError}</span>}
        </div>
        <svg
          className="h-4 w-4 text-text-muted transition-transform"
          style={{ transform: isExpanded ? 'rotate(180deg)' : 'rotate(0deg)' }}
          fill="none"
          viewBox="0 0 24 24"
          stroke="currentColor"
          strokeWidth="2"
        >
          <polyline points="6 9 12 15 18 9" />
        </svg>
      </button>
      <label className="flex items-center gap-1 pr-3 text-xs text-text-muted" title="Whether this bot may run code in the sandbox">
        Code runs
        <select
          className="min-h-11 md:min-h-8 bg-surface border border-border rounded px-2 py-1 text-xs text-text"
          value={bot.runtimeAccess ?? 'none'}
          disabled={savingAccess}
          onChange={e => changeAccess(e.target.value as RuntimeAccess)}
          aria-label={`Code run access for ${bot.username}`}
        >
          <option value="none">Off</option>
          <option value="approval">Need approval</option>
          <option value="auto">Auto-run</option>
        </select>
      </label>
      <div className="pr-3">
        <Button variant="secondary" onClick={togglePause} loading={pausing}>
          {isPaused ? 'Resume' : 'Pause'}
        </Button>
      </div>
      </div>
      {isExpanded && (
        <BotDetailPanel botId={bot.id} serverId={serverId} onDeleted={onChanged} />
      )}
    </div>
  );
});

// ─── Bot Detail Panel ─────────────────────────────────────────────────────

function BotDetailPanel({
  botId,
  serverId,
  onDeleted,
}: {
  botId: string;
  serverId: string;
  onDeleted: () => void;
}) {
  const [detail, setDetail] = useState<BotDetail | null>(null);
  const [allChannels, setAllChannels] = useState<Channel[]>([]);
  const [tokens, setTokens] = useState<BotToken[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [showCreateToken, setShowCreateToken] = useState(false);
  const [showInvite, setShowInvite] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [channelLoading, setChannelLoading] = useState<string | null>(null);
  const [avatarInput, setAvatarInput] = useState('');
  const [avatarSaving, setAvatarSaving] = useState(false);
  const [avatarError, setAvatarError] = useState('');

  const fetchDetail = useCallback(async () => {
    try {
      const [d, channels] = await Promise.all([
        botApi.get(serverId, botId),
        serverApi.getChannels(serverId),
      ]);
      setDetail(d);
      setAvatarInput(d.avatarUrl || '');
      // Only show text channels (type 3) for bot access
      setAllChannels(channels.filter(c => c.channelType === 3));
      if (d.canManageTokens) {
        const t = await botApi.listTokens(serverId, botId);
        setTokens(t);
      }
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to load bot details');
    } finally {
      setLoading(false);
    }
  }, [serverId, botId]);

  useEffect(() => { fetchDetail(); }, [fetchDetail]);

  async function handleDelete() {
    if (!confirm('Delete this bot? This cannot be undone.')) return;
    setDeleting(true);
    try {
      await botApi.remove(serverId, botId);
      onDeleted();
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to delete bot');
      setDeleting(false);
    }
  }

  async function handleRevokeToken(tokenId: string) {
    try {
      await botApi.revokeToken(serverId, botId, tokenId);
      setTokens(prev => prev.map(t => t.id === tokenId ? { ...t, revokedAt: new Date().toISOString() } : t));
    } catch (err) {
      if (err instanceof ApiError && err.status === 403) {
        // Permissions changed — refetch detail
        fetchDetail();
      }
      setError(err instanceof ApiError ? err.code : 'Failed to revoke token');
    }
  }

  async function handleClearBinding(tokenId: string) {
    try {
      await botApi.clearTokenBinding(serverId, botId, tokenId);
      setTokens(prev => prev.map(t => t.id === tokenId ? { ...t, boundClient: null, boundAt: null, lastRefused: null } : t));
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to clear the binding');
    }
  }

  async function toggleDirect(channelId: string, canDirect: boolean) {
    setChannelLoading(channelId);
    setError('');
    try {
      await botApi.setCanDirect(channelId, botId, !canDirect);
      setDetail(await botApi.get(serverId, botId));
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to update who may direct');
    } finally {
      setChannelLoading(null);
    }
  }

  async function toggleChannel(channelId: string, hasAccess: boolean) {
    setChannelLoading(channelId);
    try {
      if (hasAccess) {
        await botApi.revokeChannel(channelId, botId);
      } else {
        await botApi.grantChannel(channelId, botId);
      }
      // Refetch detail to get updated channel list
      const d = await botApi.get(serverId, botId);
      setDetail(d);
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to update channel access');
    } finally {
      setChannelLoading(null);
    }
  }

  if (loading) {
    return <div className="px-4 py-3 border-t border-border text-text-muted text-sm">Loading...</div>;
  }

  if (error && !detail) {
    return <div className="px-4 py-3 border-t border-border text-danger text-sm">{error}</div>;
  }

  if (!detail) return null;

  const botChannelIds = new Set(detail.channels.map(c => c.id));
  const directChannelIds = new Set(detail.channels.filter(c => c.canDirect).map(c => c.id));
  const activeTokens = tokens.filter(t => !t.revokedAt);
  const revokedTokens = tokens.filter(t => t.revokedAt);

  return (
    <div className="border-t border-border px-4 py-4 flex flex-col gap-5 bg-bg/50">
      {error && <p className="text-danger text-sm">{error}</p>}

      {/* ── Avatar ── */}
      <section>
        <h4 className="text-sm font-semibold text-text mb-2">Avatar</h4>
        <div className="flex items-start gap-3">
          <Avatar userId={botId} username={detail.username} avatarUrl={detail.avatarUrl} className="h-12 w-12 text-sm" />
          <div className="flex-1 min-w-0">
            <input
              type="text"
              value={avatarInput}
              onChange={(e) => { setAvatarInput(e.target.value); setAvatarError(''); }}
              placeholder="data:image/svg+xml;base64,..."
              className="min-h-11 md:min-h-9 w-full px-3 py-1.5 rounded border border-border bg-surface text-text placeholder:text-text-muted/70 text-sm"
            />
            {avatarError && <p className="text-danger text-xs mt-1">{avatarError}</p>}
            <div className="flex gap-2 mt-2">
              <Button
                variant="secondary"
                className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
                loading={avatarSaving}
                onClick={async () => {
                  setAvatarSaving(true);
                  setAvatarError('');
                  try {
                    const res = await botApi.update(serverId, botId, { avatarUrl: avatarInput || null });
                    setDetail(prev => prev ? { ...prev, avatarUrl: res.avatarUrl } : prev);
                  } catch (err) {
                    setAvatarError(err instanceof ApiError ? err.code : 'Failed to save avatar');
                  } finally {
                    setAvatarSaving(false);
                  }
                }}
              >
                Save Avatar
              </Button>
              {detail.avatarUrl && (
                <Button
                  variant="secondary"
                  className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
                  onClick={async () => {
                    setAvatarSaving(true);
                    setAvatarError('');
                    try {
                      const res = await botApi.update(serverId, botId, { avatarUrl: null });
                      setDetail(prev => prev ? { ...prev, avatarUrl: res.avatarUrl } : prev);
                      setAvatarInput('');
                    } catch (err) {
                      setAvatarError(err instanceof ApiError ? err.code : 'Failed to remove avatar');
                    } finally {
                      setAvatarSaving(false);
                    }
                  }}
                >
                  Remove
                </Button>
              )}
            </div>
          </div>
        </div>
      </section>

      {/* ── Channel Access ── */}
      <section>
        <h4 className="text-sm font-semibold text-text mb-2">Channel Access</h4>
        {allChannels.length === 0 ? (
          <p className="text-text-muted text-xs">No text channels found.</p>
        ) : (
          <div className="flex flex-col gap-1">
            {allChannels.map((ch) => {
              const hasAccess = botChannelIds.has(ch.id);
              const isLoading = channelLoading === ch.id;
              return (
                <label
                  key={ch.id}
                  className="min-h-11 md:min-h-9 flex items-center gap-2 px-2 py-1.5 rounded hover:bg-surface-hover cursor-pointer text-sm"
                >
                  <input
                    type="checkbox"
                    checked={hasAccess}
                    disabled={isLoading}
                    onChange={() => toggleChannel(ch.id, hasAccess)}
                    className="accent-primary"
                  />
                  <span className="text-text-muted">#</span>
                  <span className="text-text">{ch.name}</span>
                  {isLoading && <span className="text-text-muted text-xs ml-auto">...</span>}
                  {hasAccess && (
                    <span
                      className="ml-auto flex items-center gap-1 text-xs text-text-muted"
                      title="Lets this bot give other agents instructions in this channel. Only the server owner can change it."
                      onClick={(e) => e.stopPropagation()}
                    >
                      <input
                        type="checkbox"
                        checked={directChannelIds.has(ch.id)}
                        disabled={isLoading}
                        onChange={() => toggleDirect(ch.id, directChannelIds.has(ch.id))}
                        className="accent-primary"
                      />
                      can direct agents
                    </span>
                  )}
                </label>
              );
            })}
          </div>
        )}
      </section>

      {/* ── Tokens (owner / admin only) ── */}
      {detail.canManageTokens && (
        <section>
          <Button onClick={() => setShowInvite(true)}>Invite Agent</Button>
          {showInvite && <CreateAgentInviteModal serverId={serverId} botId={botId} onClose={() => setShowInvite(false)} onCreated={() => {}} />}
          <div className="flex items-center justify-between mb-2">
            <h4 className="text-sm font-semibold text-text">Tokens</h4>
            <Button
              variant="secondary"
              className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
              onClick={() => setShowCreateToken(true)}
            >
              New Token
            </Button>
          </div>
          {activeTokens.length === 0 && revokedTokens.length === 0 ? (
            <p className="text-text-muted text-xs">No tokens yet.</p>
          ) : (
            <div className="flex flex-col gap-1">
              {activeTokens.map((t) => (
                <div key={t.id} className="flex items-center justify-between px-2 py-1.5 rounded bg-surface text-sm">
                  <div>
                    <span className="text-text">{t.name || 'Unnamed'}</span>
                    <span className="text-text-muted text-xs ml-2">
                      Created {new Date(t.createdAt).toLocaleDateString()}
                    </span>
                    {t.lastUsedAt && (
                      <span className="text-text-muted text-xs ml-2">
                        Last used {new Date(t.lastUsedAt).toLocaleDateString()}
                        {t.lastUsedClient ? ` by ${t.lastUsedClient}` : ''}
                        {t.lastUsedIp ? ` from ${t.lastUsedIp}` : ''}
                      </span>
                    )}
                    {t.boundClient && (
                      <span className="text-text-muted text-xs ml-2" title="Requests from any other client are refused">
                        Bound to {t.boundClient}
                      </span>
                    )}
                    {t.lastRefused && (
                      <span className="block text-danger text-xs">
                        Refused {t.lastRefused.client ? `use by ${t.lastRefused.client}` : 'a use with no client name'}
                        {t.lastRefused.ip ? ` from ${t.lastRefused.ip}` : ''} on {new Date(t.lastRefused.at).toLocaleString()}.
                        If that wasn't you moving this agent, revoke the token.
                      </span>
                    )}
                  </div>
                  <div className="flex shrink-0">
                    {t.boundClient && (
                      <button
                        onClick={() => handleClearBinding(t.id)}
                        className="min-h-11 md:min-h-8 px-2 text-text-muted text-xs hover:underline"
                        title="The next client that uses the token binds it again"
                      >
                        Clear binding
                      </button>
                    )}
                    <button
                      onClick={() => handleRevokeToken(t.id)}
                      className="min-h-11 md:min-h-8 px-2 text-danger text-xs hover:underline"
                    >
                      Revoke
                    </button>
                  </div>
                </div>
              ))}
              {revokedTokens.map((t) => (
                <div key={t.id} className="flex items-center px-2 py-1.5 rounded bg-surface text-sm opacity-50">
                  <span className="text-text line-through">{t.name || 'Unnamed'}</span>
                  <span className="text-text-muted text-xs ml-2">Revoked</span>
                </div>
              ))}
            </div>
          )}

          <CreateTokenModal
            serverId={serverId}
            botId={botId}
            isOpen={showCreateToken}
            onClose={() => setShowCreateToken(false)}
            onCreated={async () => {
              const t = await botApi.listTokens(serverId, botId);
              setTokens(t);
            }}
          />
        </section>
      )}

      {/* ── Delete Bot ── */}
      <div className="pt-2 border-t border-border">
        <Button variant="danger" onClick={handleDelete} loading={deleting}>
          Delete Bot
        </Button>
      </div>
    </div>
  );
}

import { memo, useCallback, useDeferredValue, useEffect, useMemo, useRef, useState } from 'react';
import { Link } from 'react-router-dom';
import { defaultRangeExtractor, useVirtualizer } from '@tanstack/react-virtual';
import { Avatar } from '../../components/ui/Avatar';
import { useServerStore } from '../../stores/serverStore';
import { useChannelStore } from '../../stores/channelStore';
import { botApi, serverApi, runtimeApi, ApiError } from '../../lib/api';
import type { Bot, BotDetail, BotToken, RuntimeAccess } from '../../lib/api';
import type { Channel } from '../../lib/contracts/server';
import { Button } from '../../components/ui/Button';
import { CreateBotModal } from './CreateBotModal';
import { CreateTokenModal } from './CreateTokenModal';
import { CreateAgentInviteModal } from './CreateAgentInviteModal';

export function BotManagement() {
  const instanceServerId = useServerStore(s => s.instanceServerId);
  const [bots, setBots] = useState<Bot[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [permissionDenied, setPermissionDenied] = useState(false);
  const [showCreateBot, setShowCreateBot] = useState(false);
  const [showInvite, setShowInvite] = useState(false);
  const [expandedBotId, setExpandedBotId] = useState<string | null>(null);
  const [query, setQuery] = useState('');
  const deferredQuery = useDeferredValue(query);

  const fetchBots = useCallback(async (showLoading = true) => {
    if (!instanceServerId) return;
    if (showLoading) setLoading(true);
    setError('');
    try {
      const data = await botApi.list(instanceServerId);
      setBots(data);
      setPermissionDenied(false);
    } catch (err) {
      err instanceof ApiError && err.status === 403 ? setPermissionDenied(true) : setError(err instanceof ApiError ? err.code : 'Failed to load bots');
    } finally {
      setLoading(false);
    }
  }, [instanceServerId]);

  useEffect(() => { fetchBots(); }, [fetchBots]);

  // A refresh after a change keeps the list (and its scroll position) on screen
  const refresh = useCallback(() => { void fetchBots(false); }, [fetchBots]);
  const toggle = useCallback((botId: string) => setExpandedBotId(cur => (cur === botId ? null : botId)), []);

  // Newest first, so a bot you just created is at the top of a long list
  const sorted = useMemo(() => [...bots].sort((a, b) => b.createdAt.localeCompare(a.createdAt)), [bots]);
  const shown = useMemo(() => {
    const q = deferredQuery.trim().toLowerCase();
    return q ? sorted.filter(b => b.username.toLowerCase().includes(q)) : sorted;
  }, [sorted, deferredQuery]);

  if (!instanceServerId) return null;

  if (permissionDenied) {
    return (
      <div>
        <h2 className="text-xl font-bold text-text mb-4">Bot Management</h2>
        <p className="text-text-muted mb-4">You don't have permission to manage bots.</p>
        <Link to="/app" className="hidden min-h-11 items-center text-primary-text hover:underline sm:inline-flex md:min-h-8">Back to chat</Link>
      </div>
    );
  }

  if (loading) {
    return <p className="text-text-muted">Loading bots...</p>;
  }

  return (
    <div>
      <div className="flex flex-wrap items-center justify-between gap-3 mb-6">
        <h2 className="text-xl font-bold text-text">Bot Management</h2>
        <div className="flex gap-2">
          <Button onClick={() => setShowInvite(true)}>Invite Agent</Button>
          <Button variant="secondary" onClick={() => setShowCreateBot(true)}>Create Bot</Button>
        </div>
      </div>

      {error && <p className="text-danger text-sm mb-4">{error}</p>}

      <ChannelLoopGuardSection serverId={instanceServerId} />

      {bots.length === 0 ? (
        <p className="text-text-muted">No bots yet. Create one to get started.</p>
      ) : (
        <section>
          <div className="flex flex-wrap items-center gap-3 mb-2">
            <input
              type="search"
              value={query}
              onChange={e => setQuery(e.target.value)}
              placeholder="Search bots"
              aria-label="Search bots"
              className="min-h-11 md:min-h-9 w-full max-w-xs px-3 py-1.5 rounded border border-border bg-surface text-text placeholder:text-text-muted/70 text-sm"
            />
            <span className="text-text-muted text-xs" aria-live="polite">
              {shown.length === bots.length ? `${bots.length} bots` : `${shown.length} of ${bots.length} bots`}
            </span>
          </div>
          {shown.length === 0 ? (
            <p className="text-text-muted text-sm">No bots match “{deferredQuery.trim()}”.</p>
          ) : (
            <BotList
              bots={shown}
              serverId={instanceServerId}
              expandedBotId={expandedBotId}
              onToggle={toggle}
              onChanged={refresh}
            />
          )}
        </section>
      )}

      <CreateBotModal
        serverId={instanceServerId}
        isOpen={showCreateBot}
        onClose={() => setShowCreateBot(false)}
        onCreated={refresh}
      />
      {showInvite && <CreateAgentInviteModal serverId={instanceServerId} onClose={() => setShowInvite(false)} onCreated={refresh} />}
    </div>
  );
}

// ─── Bot List (virtualized) ───────────────────────────────────────────────

/** Rendering every bot stalled the page at about 1,800 bots (#241): only the rows in view are mounted. */
function BotList({
  bots,
  serverId,
  expandedBotId,
  onToggle,
  onChanged,
}: {
  bots: Bot[];
  serverId: string;
  expandedBotId: string | null;
  onToggle: (botId: string) => void;
  onChanged: () => void;
}) {
  const scrollRef = useRef<HTMLDivElement>(null);
  const expandedIndex = expandedBotId ? bots.findIndex(b => b.id === expandedBotId) : -1;
  // This component is not compiled by the React Compiler; the virtualizer is read during render only
  // eslint-disable-next-line react-hooks/incompatible-library
  const virtualizer = useVirtualizer({
    count: bots.length,
    getScrollElement: () => scrollRef.current,
    estimateSize: () => 60,
    overscan: 8,
    getItemKey: index => bots[index].id,
    // The open bot stays mounted while scrolled away, so its panel (a half-made token, an error) survives
    rangeExtractor: range => {
      const indexes = defaultRangeExtractor(range);
      return expandedIndex < 0 || indexes.includes(expandedIndex) ? indexes : [...indexes, expandedIndex].sort((a, b) => a - b);
    },
  });

  return (
    <div ref={scrollRef} data-testid="bot-list" className="max-h-[70vh] overflow-y-auto overscroll-contain">
      <div className="relative w-full" style={{ height: virtualizer.getTotalSize() }}>
        {virtualizer.getVirtualItems().map(item => {
          const bot = bots[item.index];
          return (
            <div
              key={item.key}
              data-index={item.index}
              ref={virtualizer.measureElement}
              className="absolute left-0 top-0 w-full pb-2"
              style={{ transform: `translateY(${item.start}px)` }}
            >
              <BotRow
                bot={bot}
                serverId={serverId}
                isExpanded={expandedBotId === bot.id}
                onToggle={onToggle}
                onChanged={onChanged}
              />
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ─── Channel Loop Guard Settings ──────────────────────────────────────────

type GuardField = 'maxBotHops' | 'maxThreadBotHops';
type Limits = Record<GuardField, number>;
/** The limit a guard gets when it is switched on with no earlier value to restore. */
const GUARD_DEFAULT: Limits = { maxBotHops: 4, maxThreadBotHops: 4 };

/**
 * Both loop guards per channel (#23): the channel guard (top-level bot messages in a row)
 * and the thread guard (bot replies in a row inside one thread). Each has an on/off switch;
 * off is a limit of 0.
 */
function ChannelLoopGuardSection({ serverId }: { serverId: string }) {
  const [channels, setChannels] = useState<Channel[]>([]);
  // Limits as loaded or last confirmed by a save here
  const [loaded, setLoaded] = useState<Record<string, Limits>>({});
  // Edits not yet confirmed by the server, by `${channelId}:${field}`
  const [dirty, setDirty] = useState<Record<string, number>>({});
  const [saving, setSaving] = useState<Record<string, boolean>>({});
  const [error, setError] = useState('');
  // A change made elsewhere (a notice's Raise limit or Turn off) arrives as ChannelBotConfig
  const live = useChannelStore(s => s.channels);
  const pending = useRef<Record<string, { timer: ReturnType<typeof setTimeout>; value: number }>>({});
  // Saves of one field go out one at a time, in order, so the last change made wins
  const queues = useRef<Record<string, Promise<void>>>({});
  // The last limit above 0, restored when a guard is switched back on
  const lastOn = useRef<Record<string, number>>({});
  const mounted = useRef(true);

  useEffect(() => {
    serverApi.getChannels(serverId).then((chs) => {
      const textChannels = chs.filter(c => c.channelType === 3);
      setChannels(textChannels);
      const initial: Record<string, Limits> = {};
      for (const ch of textChannels) {
        initial[ch.id] = { maxBotHops: ch.maxBotHops ?? 4, maxThreadBotHops: ch.maxThreadBotHops ?? 0 };
      }
      setLoaded(initial);
    }).catch(() => setError('Failed to load channels'));
  }, [serverId]);

  // enqueue only touches refs and state setters, so the first render's copy stays valid for the unmount flush
  const enqueueOnLeave = useRef(enqueue);

  // Leaving the page sends a change still waiting out its debounce instead of dropping it,
  // behind any save of that field still in flight so the older one cannot land last
  useEffect(() => {
    mounted.current = true;
    const waiting = pending.current;
    const flush = enqueueOnLeave.current;
    return () => {
      mounted.current = false;
      for (const [key, p] of Object.entries(waiting)) {
        clearTimeout(p.timer);
        delete waiting[key];
        const [channelId, field] = key.split(':') as [string, GuardField];
        flush(channelId, field, p.value);
      }
    };
  }, []);

  const shown = (channelId: string, field: GuardField): number => {
    const key = `${channelId}:${field}`;
    return dirty[key] ?? live.get(channelId)?.[field] ?? loaded[channelId]?.[field] ?? GUARD_DEFAULT[field];
  };

  function change(channelId: string, field: GuardField, value: number, delay: number) {
    const key = `${channelId}:${field}`;
    const prev = shown(channelId, field);
    if (prev > 0) lastOn.current[key] = prev;
    setDirty(d => ({ ...d, [key]: value }));
    if (pending.current[key]) clearTimeout(pending.current[key].timer);
    const timer = setTimeout(() => {
      delete pending.current[key];
      enqueue(channelId, field, value);
    }, delay);
    pending.current[key] = { timer, value };
  }

  /** Queues a save behind any earlier save of the same field (save never rejects). */
  function enqueue(channelId: string, field: GuardField, value: number) {
    const key = `${channelId}:${field}`;
    queues.current[key] = (queues.current[key] ?? Promise.resolve()).then(() => save(channelId, field, value));
  }

  function handleNumber(channelId: string, field: GuardField, raw: string) {
    const num = parseInt(raw, 10);
    // 0 would be "off": that is the switch's job, so the box keeps a limit while typing
    if (isNaN(num) || num < 1 || num > 1000) return;
    change(channelId, field, num, 600);
  }

  function handleToggle(channelId: string, field: GuardField, on: boolean) {
    const restore = lastOn.current[`${channelId}:${field}`] ?? GUARD_DEFAULT[field];
    change(channelId, field, on ? restore : 0, 0);
  }

  async function save(channelId: string, field: GuardField, value: number) {
    const key = `${channelId}:${field}`;
    if (mounted.current) { setSaving(s => ({ ...s, [key]: true })); setError(''); }
    // Only the latest edit clears the dirty value; an older save finishing must not
    const settle = (d: Record<string, number>) => {
      if (d[key] !== value || pending.current[key]) return d;
      const next = { ...d };
      delete next[key];
      return next;
    };
    try {
      const config = await botApi.updateChannelBotConfig(channelId, { [field]: value });
      useChannelStore.getState().patchChannel(channelId, { maxBotHops: config.maxBotHops, maxThreadBotHops: config.maxThreadBotHops });
      if (!mounted.current) return;
      setLoaded(l => ({ ...l, [channelId]: { maxBotHops: config.maxBotHops, maxThreadBotHops: config.maxThreadBotHops } }));
      setDirty(settle);
    } catch (err) {
      if (!mounted.current) return;
      // Show what the server still has, not the value that failed
      setDirty(settle);
      setError(err instanceof ApiError ? err.code : 'Failed to save');
    } finally {
      if (mounted.current) setSaving(s => ({ ...s, [key]: false }));
    }
  }

  if (channels.length === 0) return null;

  const guard = (ch: Channel, field: GuardField, label: string, unit: string) => {
    const value = shown(ch.id, field);
    const on = value > 0;
    const key = `${ch.id}:${field}`;
    return (
      <div className="flex items-center gap-2">
        <label className="min-h-11 md:min-h-8 flex items-center gap-1.5 text-xs text-text-muted cursor-pointer">
          <input
            type="checkbox"
            role="switch"
            checked={on}
            onChange={e => handleToggle(ch.id, field, e.target.checked)}
            aria-label={`${label} loop guard in #${ch.name}`}
            className="accent-primary"
          />
          {label}
        </label>
        {on ? (
          <input
            type="number"
            min={1}
            max={1000}
            value={value}
            onChange={e => handleNumber(ch.id, field, e.target.value)}
            aria-label={`${label} limit in #${ch.name} (${unit})`}
            title={`Pause after this many ${unit} in a row`}
            className="min-h-11 md:min-h-8 w-16 px-2 py-1 rounded border border-border bg-surface text-text text-sm text-right"
          />
        ) : (
          <span className="w-16 text-text-muted text-xs">Off</span>
        )}
        <span className="w-12 text-text-muted text-xs" aria-live="polite">{saving[key] ? 'Saving…' : ''}</span>
      </div>
    );
  };

  return (
    <section className="mb-6">
      <h3 className="text-sm font-semibold text-text mb-2">Loop Guard</h3>
      <p className="text-text-muted text-xs mb-3">
        Pauses agents after this many bot posts in a row with no human message. The channel guard counts top-level
        messages; the thread guard counts replies inside each thread. A human message resets both, and the notice
        it posts has Continue, Raise limit and Turn off buttons.
      </p>
      {error && <p className="text-danger text-xs mb-2" role="alert">{error}</p>}
      <div className="flex flex-col gap-1">
        {channels.map((ch) => (
          <div key={ch.id} className="flex flex-wrap items-center gap-x-6 gap-y-1 px-2 py-1.5 rounded hover:bg-surface-hover">
            <span className="flex min-w-32 flex-1 items-center gap-1 text-sm">
              <span className="text-text-muted">#</span>
              <span className="text-text">{ch.name}</span>
            </span>
            {guard(ch, 'maxBotHops', 'Channel', 'bot messages')}
            {guard(ch, 'maxThreadBotHops', 'Threads', 'bot replies in one thread')}
          </div>
        ))}
      </div>
    </section>
  );
}

// ─── Bot Row (expandable) ─────────────────────────────────────────────────

// Memoized with stable callbacks: opening one bot re-renders that row, not the whole list
const BotRow = memo(function BotRow({
  bot,
  serverId,
  isExpanded,
  onToggle,
  onChanged,
}: {
  bot: Bot;
  serverId: string;
  isExpanded: boolean;
  onToggle: (botId: string) => void;
  onChanged: () => void;
}) {
  const [pausing, setPausing] = useState(false);
  const [pauseError, setPauseError] = useState('');
  const [savingAccess, setSavingAccess] = useState(false);
  const isPaused = !!bot.pausedAt;

  async function changeAccess(access: RuntimeAccess) {
    if (access === 'auto' && !confirm(`Let ${bot.username} run code without approval? Runs still execute in the sandbox with its limits.`)) return;
    setSavingAccess(true);
    setPauseError('');
    try {
      await runtimeApi.setBotAccess(serverId, bot.id, access);
      onChanged();
    } catch (err) {
      setPauseError(err instanceof ApiError ? err.code : 'Failed to update code run access');
    } finally {
      setSavingAccess(false);
    }
  }

  async function togglePause() {
    setPausing(true);
    setPauseError('');
    try {
      if (isPaused) {
        await botApi.setPaused(serverId, bot.id, false);
      } else {
        const reason = prompt('Pause this bot? It will be read-only until resumed.\n\nReason (optional):');
        if (reason === null) return;
        await botApi.setPaused(serverId, bot.id, true, reason.trim() || undefined);
      }
      onChanged();
    } catch (err) {
      setPauseError(err instanceof ApiError ? err.code : 'Failed to update pause state');
    } finally {
      setPausing(false);
    }
  }

  return (
    <div className="border border-border rounded-lg overflow-hidden">
      <div className="flex items-center hover:bg-surface-hover">
      <button
        onClick={() => onToggle(bot.id)}
        aria-expanded={isExpanded}
        className="min-h-11 flex-1 flex items-center justify-between px-4 py-3 text-left"
      >
        <div>
          <span className="text-text font-medium">{bot.username}</span>
          {isPaused && (
            <span
              className="ml-2 inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-semibold leading-none bg-warn/20 text-warn"
              title={bot.pausedReason ? `Paused: ${bot.pausedReason}` : 'Paused'}
            >
              PAUSED
            </span>
          )}
          <span className="text-text-muted text-xs ml-2">
            {new Date(bot.createdAt).toLocaleDateString()}
          </span>
          {pauseError && <span className="text-danger text-xs ml-2">{pauseError}</span>}
        </div>
        <svg
          className="h-4 w-4 text-text-muted transition-transform"
          style={{ transform: isExpanded ? 'rotate(180deg)' : 'rotate(0deg)' }}
          fill="none"
          viewBox="0 0 24 24"
          stroke="currentColor"
          strokeWidth="2"
        >
          <polyline points="6 9 12 15 18 9" />
        </svg>
      </button>
      <label className="flex items-center gap-1 pr-3 text-xs text-text-muted" title="Whether this bot may run code in the sandbox">
        Code runs
        <select
          className="min-h-11 md:min-h-8 bg-surface border border-border rounded px-2 py-1 text-xs text-text"
          value={bot.runtimeAccess ?? 'none'}
          disabled={savingAccess}
          onChange={e => changeAccess(e.target.value as RuntimeAccess)}
          aria-label={`Code run access for ${bot.username}`}
        >
          <option value="none">Off</option>
          <option value="approval">Need approval</option>
          <option value="auto">Auto-run</option>
        </select>
      </label>
      <div className="pr-3">
        <Button variant="secondary" onClick={togglePause} loading={pausing}>
          {isPaused ? 'Resume' : 'Pause'}
        </Button>
      </div>
      </div>
      {isExpanded && (
        <BotDetailPanel botId={bot.id} serverId={serverId} onDeleted={onChanged} />
      )}
    </div>
  );
});

// ─── Bot Detail Panel ─────────────────────────────────────────────────────

function BotDetailPanel({
  botId,
  serverId,
  onDeleted,
}: {
  botId: string;
  serverId: string;
  onDeleted: () => void;
}) {
  const [detail, setDetail] = useState<BotDetail | null>(null);
  const [allChannels, setAllChannels] = useState<Channel[]>([]);
  const [tokens, setTokens] = useState<BotToken[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [showCreateToken, setShowCreateToken] = useState(false);
  const [showInvite, setShowInvite] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [channelLoading, setChannelLoading] = useState<string | null>(null);
  const [avatarInput, setAvatarInput] = useState('');
  const [avatarSaving, setAvatarSaving] = useState(false);
  const [avatarError, setAvatarError] = useState('');

  const fetchDetail = useCallback(async () => {
    try {
      const [d, channels] = await Promise.all([
        botApi.get(serverId, botId),
        serverApi.getChannels(serverId),
      ]);
      setDetail(d);
      setAvatarInput(d.avatarUrl || '');
      // Only show text channels (type 3) for bot access
      setAllChannels(channels.filter(c => c.channelType === 3));
      if (d.canManageTokens) {
        const t = await botApi.listTokens(serverId, botId);
        setTokens(t);
      }
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to load bot details');
    } finally {
      setLoading(false);
    }
  }, [serverId, botId]);

  useEffect(() => { fetchDetail(); }, [fetchDetail]);

  async function handleDelete() {
    if (!confirm('Delete this bot? This cannot be undone.')) return;
    setDeleting(true);
    try {
      await botApi.remove(serverId, botId);
      onDeleted();
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to delete bot');
      setDeleting(false);
    }
  }

  async function handleRevokeToken(tokenId: string) {
    try {
      await botApi.revokeToken(serverId, botId, tokenId);
      setTokens(prev => prev.map(t => t.id === tokenId ? { ...t, revokedAt: new Date().toISOString() } : t));
    } catch (err) {
      if (err instanceof ApiError && err.status === 403) {
        // Permissions changed — refetch detail
        fetchDetail();
      }
      setError(err instanceof ApiError ? err.code : 'Failed to revoke token');
    }
  }

  async function handleClearBinding(tokenId: string) {
    try {
      await botApi.clearTokenBinding(serverId, botId, tokenId);
      setTokens(prev => prev.map(t => t.id === tokenId ? { ...t, boundClient: null, boundAt: null, lastRefused: null } : t));
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to clear the binding');
    }
  }

  async function toggleDirect(channelId: string, canDirect: boolean) {
    setChannelLoading(channelId);
    setError('');
    try {
      await botApi.setCanDirect(channelId, botId, !canDirect);
      setDetail(await botApi.get(serverId, botId));
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to update who may direct');
    } finally {
      setChannelLoading(null);
    }
  }

  async function toggleChannel(channelId: string, hasAccess: boolean) {
    setChannelLoading(channelId);
    try {
      if (hasAccess) {
        await botApi.revokeChannel(channelId, botId);
      } else {
        await botApi.grantChannel(channelId, botId);
      }
      // Refetch detail to get updated channel list
      const d = await botApi.get(serverId, botId);
      setDetail(d);
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to update channel access');
    } finally {
      setChannelLoading(null);
    }
  }

  if (loading) {
    return <div className="px-4 py-3 border-t border-border text-text-muted text-sm">Loading...</div>;
  }

  if (error && !detail) {
    return <div className="px-4 py-3 border-t border-border text-danger text-sm">{error}</div>;
  }

  if (!detail) return null;

  const botChannelIds = new Set(detail.channels.map(c => c.id));
  const directChannelIds = new Set(detail.channels.filter(c => c.canDirect).map(c => c.id));
  const activeTokens = tokens.filter(t => !t.revokedAt);
  const revokedTokens = tokens.filter(t => t.revokedAt);

  return (
    <div className="border-t border-border px-4 py-4 flex flex-col gap-5 bg-bg/50">
      {error && <p className="text-danger text-sm">{error}</p>}

      {/* ── Avatar ── */}
      <section>
        <h4 className="text-sm font-semibold text-text mb-2">Avatar</h4>
        <div className="flex items-start gap-3">
          <Avatar userId={botId} username={detail.username} avatarUrl={detail.avatarUrl} className="h-12 w-12 text-sm" />
          <div className="flex-1 min-w-0">
            <input
              type="text"
              value={avatarInput}
              onChange={(e) => { setAvatarInput(e.target.value); setAvatarError(''); }}
              placeholder="data:image/svg+xml;base64,..."
              className="min-h-11 md:min-h-9 w-full px-3 py-1.5 rounded border border-border bg-surface text-text placeholder:text-text-muted/70 text-sm"
            />
            {avatarError && <p className="text-danger text-xs mt-1">{avatarError}</p>}
            <div className="flex gap-2 mt-2">
              <Button
                variant="secondary"
                className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
                loading={avatarSaving}
                onClick={async () => {
                  setAvatarSaving(true);
                  setAvatarError('');
                  try {
                    const res = await botApi.update(serverId, botId, { avatarUrl: avatarInput || null });
                    setDetail(prev => prev ? { ...prev, avatarUrl: res.avatarUrl } : prev);
                  } catch (err) {
                    setAvatarError(err instanceof ApiError ? err.code : 'Failed to save avatar');
                  } finally {
                    setAvatarSaving(false);
                  }
                }}
              >
                Save Avatar
              </Button>
              {detail.avatarUrl && (
                <Button
                  variant="secondary"
                  className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
                  onClick={async () => {
                    setAvatarSaving(true);
                    setAvatarError('');
                    try {
                      const res = await botApi.update(serverId, botId, { avatarUrl: null });
                      setDetail(prev => prev ? { ...prev, avatarUrl: res.avatarUrl } : prev);
                      setAvatarInput('');
                    } catch (err) {
                      setAvatarError(err instanceof ApiError ? err.code : 'Failed to remove avatar');
                    } finally {
                      setAvatarSaving(false);
                    }
                  }}
                >
                  Remove
                </Button>
              )}
            </div>
          </div>
        </div>
      </section>

      {/* ── Channel Access ── */}
      <section>
        <h4 className="text-sm font-semibold text-text mb-2">Channel Access</h4>
        {allChannels.length === 0 ? (
          <p className="text-text-muted text-xs">No text channels found.</p>
        ) : (
          <div className="flex flex-col gap-1">
            {allChannels.map((ch) => {
              const hasAccess = botChannelIds.has(ch.id);
              const isLoading = channelLoading === ch.id;
              return (
                <label
                  key={ch.id}
                  className="min-h-11 md:min-h-9 flex items-center gap-2 px-2 py-1.5 rounded hover:bg-surface-hover cursor-pointer text-sm"
                >
                  <input
                    type="checkbox"
                    checked={hasAccess}
                    disabled={isLoading}
                    onChange={() => toggleChannel(ch.id, hasAccess)}
                    className="accent-primary"
                  />
                  <span className="text-text-muted">#</span>
                  <span className="text-text">{ch.name}</span>
                  {isLoading && <span className="text-text-muted text-xs ml-auto">...</span>}
                  {hasAccess && (
                    <span
                      className="ml-auto flex items-center gap-1 text-xs text-text-muted"
                      title="Lets this bot give other agents instructions in this channel. Only the server owner can change it."
                      onClick={(e) => e.stopPropagation()}
                    >
                      <input
                        type="checkbox"
                        checked={directChannelIds.has(ch.id)}
                        disabled={isLoading}
                        onChange={() => toggleDirect(ch.id, directChannelIds.has(ch.id))}
                        className="accent-primary"
                      />
                      can direct agents
                    </span>
                  )}
                </label>
              );
            })}
          </div>
        )}
      </section>

      {/* ── Tokens (owner / admin only) ── */}
      {detail.canManageTokens && (
        <section>
          <Button onClick={() => setShowInvite(true)}>Invite Agent</Button>
          {showInvite && <CreateAgentInviteModal serverId={serverId} botId={botId} onClose={() => setShowInvite(false)} onCreated={() => {}} />}
          <div className="flex items-center justify-between mb-2">
            <h4 className="text-sm font-semibold text-text">Tokens</h4>
            <Button
              variant="secondary"
              className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
              onClick={() => setShowCreateToken(true)}
            >
              New Token
            </Button>
          </div>
          {activeTokens.length === 0 && revokedTokens.length === 0 ? (
            <p className="text-text-muted text-xs">No tokens yet.</p>
          ) : (
            <div className="flex flex-col gap-1">
              {activeTokens.map((t) => (
                <div key={t.id} className="flex items-center justify-between px-2 py-1.5 rounded bg-surface text-sm">
                  <div>
                    <span className="text-text">{t.name || 'Unnamed'}</span>
                    <span className="text-text-muted text-xs ml-2">
                      Created {new Date(t.createdAt).toLocaleDateString()}
                    </span>
                    {t.lastUsedAt && (
                      <span className="text-text-muted text-xs ml-2">
                        Last used {new Date(t.lastUsedAt).toLocaleDateString()}
                        {t.lastUsedClient ? ` by ${t.lastUsedClient}` : ''}
                        {t.lastUsedIp ? ` from ${t.lastUsedIp}` : ''}
                      </span>
                    )}
                    {t.boundClient && (
                      <span className="text-text-muted text-xs ml-2" title="Requests from any other client are refused">
                        Bound to {t.boundClient}
                      </span>
                    )}
                    {t.lastRefused && (
                      <span className="block text-danger text-xs">
                        Refused {t.lastRefused.client ? `use by ${t.lastRefused.client}` : 'a use with no client name'}
                        {t.lastRefused.ip ? ` from ${t.lastRefused.ip}` : ''} on {new Date(t.lastRefused.at).toLocaleString()}.
                        If that wasn't you moving this agent, revoke the token.
                      </span>
                    )}
                  </div>
                  <div className="flex shrink-0">
                    {t.boundClient && (
                      <button
                        onClick={() => handleClearBinding(t.id)}
                        className="min-h-11 md:min-h-8 px-2 text-text-muted text-xs hover:underline"
                        title="The next client that uses the token binds it again"
                      >
                        Clear binding
                      </button>
                    )}
                    <button
                      onClick={() => handleRevokeToken(t.id)}
                      className="min-h-11 md:min-h-8 px-2 text-danger text-xs hover:underline"
                    >
                      Revoke
                    </button>
                  </div>
                </div>
              ))}
              {revokedTokens.map((t) => (
                <div key={t.id} className="flex items-center px-2 py-1.5 rounded bg-surface text-sm opacity-50">
                  <span className="text-text line-through">{t.name || 'Unnamed'}</span>
                  <span className="text-text-muted text-xs ml-2">Revoked</span>
                </div>
              ))}
            </div>
          )}

          <CreateTokenModal
            serverId={serverId}
            botId={botId}
            isOpen={showCreateToken}
            onClose={() => setShowCreateToken(false)}
            onCreated={async () => {
              const t = await botApi.listTokens(serverId, botId);
              setTokens(t);
            }}
          />
        </section>
      )}

      {/* ── Delete Bot ── */}
      <div className="pt-2 border-t border-border">
        <Button variant="danger" onClick={handleDelete} loading={deleting}>
          Delete Bot
        </Button>
      </div>
    </div>
  );
}

import { memo, useCallback, useDeferredValue, useEffect, useMemo, useRef, useState } from 'react';
import { Link } from 'react-router-dom';
import { defaultRangeExtractor, useVirtualizer } from '@tanstack/react-virtual';
import { Avatar } from '../../components/ui/Avatar';
import { useServerStore } from '../../stores/serverStore';
import { useChannelStore } from '../../stores/channelStore';
import { botApi, serverApi, runtimeApi, ApiError } from '../../lib/api';
import type { Bot, BotDetail, BotToken, RuntimeAccess } from '../../lib/api';
import type { Channel } from '../../lib/contracts/server';
import { Button } from '../../components/ui/Button';
import { CreateBotModal } from './CreateBotModal';
import { CreateTokenModal } from './CreateTokenModal';
import { CreateAgentInviteModal } from './CreateAgentInviteModal';

export function BotManagement() {
  const instanceServerId = useServerStore(s => s.instanceServerId);
  const [bots, setBots] = useState<Bot[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [permissionDenied, setPermissionDenied] = useState(false);
  const [showCreateBot, setShowCreateBot] = useState(false);
  const [showInvite, setShowInvite] = useState(false);
  const [expandedBotId, setExpandedBotId] = useState<string | null>(null);
  const [query, setQuery] = useState('');
  const deferredQuery = useDeferredValue(query);

  const fetchBots = useCallback(async (showLoading = true) => {
    if (!instanceServerId) return;
    if (showLoading) setLoading(true);
    setError('');
    try {
      const data = await botApi.list(instanceServerId);
      setBots(data);
      setPermissionDenied(false);
    } catch (err) {
      if (err instanceof ApiError && err.status === 403) {
        setPermissionDenied(true);
      } else {
        setError(err instanceof ApiError ? err.code : 'Failed to load bots');
      }
    } finally {
      setLoading(false);
    }
  }, [instanceServerId]);

  useEffect(() => { fetchBots(); }, [fetchBots]);

  // A refresh after a change keeps the list (and its scroll position) on screen
  const refresh = useCallback(() => { void fetchBots(false); }, [fetchBots]);
  const toggle = useCallback((botId: string) => setExpandedBotId(cur => (cur === botId ? null : botId)), []);

  // Newest first, so a bot you just created is at the top of a long list
  const sorted = useMemo(() => [...bots].sort((a, b) => b.createdAt.localeCompare(a.createdAt)), [bots]);
  const shown = useMemo(() => {
    const q = deferredQuery.trim().toLowerCase();
    return q ? sorted.filter(b => b.username.toLowerCase().includes(q)) : sorted;
  }, [sorted, deferredQuery]);

  if (!instanceServerId) return null;

  if (permissionDenied) {
    return (
      <div>
        <h2 className="text-xl font-bold text-text mb-4">Bot Management</h2>
        <p className="text-text-muted mb-4">You don't have permission to manage bots.</p>
        <Link to="/app" className="hidden min-h-11 items-center text-primary-text hover:underline sm:inline-flex md:min-h-8">Back to chat</Link>
      </div>
    );
  }

  if (loading) {
    return <p className="text-text-muted">Loading bots...</p>;
  }

  return (
    <div>
      <div className="flex flex-wrap items-center justify-between gap-3 mb-6">
        <h2 className="text-xl font-bold text-text">Bot Management</h2>
        <div className="flex gap-2">
          <Button onClick={() => setShowInvite(true)}>Invite Agent</Button>
          <Button variant="secondary" onClick={() => setShowCreateBot(true)}>Create Bot</Button>
        </div>
      </div>

      {error && <p className="text-danger text-sm mb-4">{error}</p>}

      <ChannelLoopGuardSection serverId={instanceServerId} />

      {bots.length === 0 ? (
        <p className="text-text-muted">No bots yet. Create one to get started.</p>
      ) : (
        <section>
          <div className="flex flex-wrap items-center gap-3 mb-2">
            <input
              type="search"
              value={query}
              onChange={e => setQuery(e.target.value)}
              placeholder="Search bots"
              aria-label="Search bots"
              className="min-h-11 md:min-h-9 w-full max-w-xs px-3 py-1.5 rounded border border-border bg-surface text-text placeholder:text-text-muted/70 text-sm"
            />
            <span className="text-text-muted text-xs" aria-live="polite">
              {shown.length === bots.length ? `${bots.length} bots` : `${shown.length} of ${bots.length} bots`}
            </span>
          </div>
          {shown.length === 0 ? (
            <p className="text-text-muted text-sm">No bots match “{deferredQuery.trim()}”.</p>
          ) : (
            <BotList
              bots={shown}
              serverId={instanceServerId}
              expandedBotId={expandedBotId}
              onToggle={toggle}
              onChanged={refresh}
            />
          )}
        </section>
      )}

      <CreateBotModal
        serverId={instanceServerId}
        isOpen={showCreateBot}
        onClose={() => setShowCreateBot(false)}
        onCreated={refresh}
      />
      {showInvite && <CreateAgentInviteModal serverId={instanceServerId} onClose={() => setShowInvite(false)} onCreated={refresh} />}
    </div>
  );
}

// ─── Bot List (virtualized) ───────────────────────────────────────────────

/** Rendering every bot stalled the page at about 1,800 bots (#241): only the rows in view are mounted. */
function BotList({
  bots,
  serverId,
  expandedBotId,
  onToggle,
  onChanged,
}: {
  bots: Bot[];
  serverId: string;
  expandedBotId: string | null;
  onToggle: (botId: string) => void;
  onChanged: () => void;
}) {
  const scrollRef = useRef<HTMLDivElement>(null);
  const expandedIndex = expandedBotId ? bots.findIndex(b => b.id === expandedBotId) : -1;
  // This component is not compiled by the React Compiler; the virtualizer is read during render only
  // eslint-disable-next-line react-hooks/incompatible-library
  const virtualizer = useVirtualizer({
    count: bots.length,
    getScrollElement: () => scrollRef.current,
    estimateSize: () => 60,
    overscan: 8,
    getItemKey: index => bots[index].id,
    // The open bot stays mounted while scrolled away, so its panel (a half-made token, an error) survives
    rangeExtractor: range => {
      const indexes = defaultRangeExtractor(range);
      return expandedIndex < 0 || indexes.includes(expandedIndex) ? indexes : [...indexes, expandedIndex].sort((a, b) => a - b);
    },
  });

  return (
    <div ref={scrollRef} data-testid="bot-list" className="max-h-[70vh] overflow-y-auto overscroll-contain">
      <div className="relative w-full" style={{ height: virtualizer.getTotalSize() }}>
        {virtualizer.getVirtualItems().map(item => {
          const bot = bots[item.index];
          return (
            <div
              key={item.key}
              data-index={item.index}
              ref={virtualizer.measureElement}
              className="absolute left-0 top-0 w-full pb-2"
              style={{ transform: `translateY(${item.start}px)` }}
            >
              <BotRow
                bot={bot}
                serverId={serverId}
                isExpanded={expandedBotId === bot.id}
                onToggle={onToggle}
                onChanged={onChanged}
              />
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ─── Channel Loop Guard Settings ──────────────────────────────────────────

type GuardField = 'maxBotHops' | 'maxThreadBotHops';
type Limits = Record<GuardField, number>;
/** The limit a guard gets when it is switched on with no earlier value to restore. */
const GUARD_DEFAULT: Limits = { maxBotHops: 4, maxThreadBotHops: 4 };

/**
 * Both loop guards per channel (#23): the channel guard (top-level bot messages in a row)
 * and the thread guard (bot replies in a row inside one thread). Each has an on/off switch;
 * off is a limit of 0.
 */
function ChannelLoopGuardSection({ serverId }: { serverId: string }) {
  const [channels, setChannels] = useState<Channel[]>([]);
  // Limits as loaded or last confirmed by a save here
  const [loaded, setLoaded] = useState<Record<string, Limits>>({});
  // Edits not yet confirmed by the server, by `${channelId}:${field}`
  const [dirty, setDirty] = useState<Record<string, number>>({});
  const [saving, setSaving] = useState<Record<string, boolean>>({});
  const [error, setError] = useState('');
  // A change made elsewhere (a notice's Raise limit or Turn off) arrives as ChannelBotConfig
  const live = useChannelStore(s => s.channels);
  const pending = useRef<Record<string, { timer: ReturnType<typeof setTimeout>; value: number }>>({});
  // Saves of one field go out one at a time, in order, so the last change made wins
  const queues = useRef<Record<string, Promise<void>>>({});
  // The last limit above 0, restored when a guard is switched back on
  const lastOn = useRef<Record<string, number>>({});
  const mounted = useRef(true);

  useEffect(() => {
    serverApi.getChannels(serverId).then((chs) => {
      const textChannels = chs.filter(c => c.channelType === 3);
      setChannels(textChannels);
      const initial: Record<string, Limits> = {};
      for (const ch of textChannels) {
        initial[ch.id] = { maxBotHops: ch.maxBotHops ?? 4, maxThreadBotHops: ch.maxThreadBotHops ?? 0 };
      }
      setLoaded(initial);
    }).catch(() => setError('Failed to load channels'));
  }, [serverId]);

  // enqueue only touches refs and state setters, so the first render's copy stays valid for the unmount flush
  const enqueueOnLeave = useRef(enqueue);

  // Leaving the page sends a change still waiting out its debounce instead of dropping it,
  // behind any save of that field still in flight so the older one cannot land last
  useEffect(() => {
    mounted.current = true;
    const waiting = pending.current;
    const flush = enqueueOnLeave.current;
    return () => {
      mounted.current = false;
      for (const [key, p] of Object.entries(waiting)) {
        clearTimeout(p.timer);
        delete waiting[key];
        const [channelId, field] = key.split(':') as [string, GuardField];
        flush(channelId, field, p.value);
      }
    };
  }, []);

  const shown = (channelId: string, field: GuardField): number => {
    const key = `${channelId}:${field}`;
    return dirty[key] ?? live.get(channelId)?.[field] ?? loaded[channelId]?.[field] ?? GUARD_DEFAULT[field];
  };

  function change(channelId: string, field: GuardField, value: number, delay: number) {
    const key = `${channelId}:${field}`;
    const prev = shown(channelId, field);
    if (prev > 0) lastOn.current[key] = prev;
    setDirty(d => ({ ...d, [key]: value }));
    pending.current[key] && clearTimeout(pending.current[key].timer);
    const timer = setTimeout(() => {
      delete pending.current[key];
      enqueue(channelId, field, value);
    }, delay);
    pending.current[key] = { timer, value };
  }

  /** Queues a save behind any earlier save of the same field (save never rejects). */
  function enqueue(channelId: string, field: GuardField, value: number) {
    const key = `${channelId}:${field}`;
    queues.current[key] = (queues.current[key] ?? Promise.resolve()).then(() => save(channelId, field, value));
  }

  function handleNumber(channelId: string, field: GuardField, raw: string) {
    const num = parseInt(raw, 10);
    // 0 would be "off": that is the switch's job, so the box keeps a limit while typing
    if (isNaN(num) || num < 1 || num > 1000) return;
    change(channelId, field, num, 600);
  }

  function handleToggle(channelId: string, field: GuardField, on: boolean) {
    const restore = lastOn.current[`${channelId}:${field}`] ?? GUARD_DEFAULT[field];
    change(channelId, field, on ? restore : 0, 0);
  }

  async function save(channelId: string, field: GuardField, value: number) {
    const key = `${channelId}:${field}`;
    if (mounted.current) { setSaving(s => ({ ...s, [key]: true })); setError(''); }
    // Only the latest edit clears the dirty value; an older save finishing must not
    const settle = (d: Record<string, number>) => {
      if (d[key] !== value || pending.current[key]) return d;
      const next = { ...d };
      delete next[key];
      return next;
    };
    try {
      const config = await botApi.updateChannelBotConfig(channelId, { [field]: value });
      useChannelStore.getState().patchChannel(channelId, { maxBotHops: config.maxBotHops, maxThreadBotHops: config.maxThreadBotHops });
      if (!mounted.current) return;
      setLoaded(l => ({ ...l, [channelId]: { maxBotHops: config.maxBotHops, maxThreadBotHops: config.maxThreadBotHops } }));
      setDirty(settle);
    } catch (err) {
      if (!mounted.current) return;
      // Show what the server still has, not the value that failed
      setDirty(settle);
      setError(err instanceof ApiError ? err.code : 'Failed to save');
    } finally {
      if (mounted.current) setSaving(s => ({ ...s, [key]: false }));
    }
  }

  if (channels.length === 0) return null;

  const guard = (ch: Channel, field: GuardField, label: string, unit: string) => {
    const value = shown(ch.id, field);
    const on = value > 0;
    const key = `${ch.id}:${field}`;
    return (
      <div className="flex items-center gap-2">
        <label className="min-h-11 md:min-h-8 flex items-center gap-1.5 text-xs text-text-muted cursor-pointer">
          <input
            type="checkbox"
            role="switch"
            checked={on}
            onChange={e => handleToggle(ch.id, field, e.target.checked)}
            aria-label={`${label} loop guard in #${ch.name}`}
            className="accent-primary"
          />
          {label}
        </label>
        {on ? (
          <input
            type="number"
            min={1}
            max={1000}
            value={value}
            onChange={e => handleNumber(ch.id, field, e.target.value)}
            aria-label={`${label} limit in #${ch.name} (${unit})`}
            title={`Pause after this many ${unit} in a row`}
            className="min-h-11 md:min-h-8 w-16 px-2 py-1 rounded border border-border bg-surface text-text text-sm text-right"
          />
        ) : (
          <span className="w-16 text-text-muted text-xs">Off</span>
        )}
        <span className="w-12 text-text-muted text-xs" aria-live="polite">{saving[key] ? 'Saving…' : ''}</span>
      </div>
    );
  };

  return (
    <section className="mb-6">
      <h3 className="text-sm font-semibold text-text mb-2">Loop Guard</h3>
      <p className="text-text-muted text-xs mb-3">
        Pauses agents after this many bot posts in a row with no human message. The channel guard counts top-level
        messages; the thread guard counts replies inside each thread. A human message resets both, and the notice
        it posts has Continue, Raise limit and Turn off buttons.
      </p>
      {error && <p className="text-danger text-xs mb-2" role="alert">{error}</p>}
      <div className="flex flex-col gap-1">
        {channels.map((ch) => (
          <div key={ch.id} className="flex flex-wrap items-center gap-x-6 gap-y-1 px-2 py-1.5 rounded hover:bg-surface-hover">
            <span className="flex min-w-32 flex-1 items-center gap-1 text-sm">
              <span className="text-text-muted">#</span>
              <span className="text-text">{ch.name}</span>
            </span>
            {guard(ch, 'maxBotHops', 'Channel', 'bot messages')}
            {guard(ch, 'maxThreadBotHops', 'Threads', 'bot replies in one thread')}
          </div>
        ))}
      </div>
    </section>
  );
}

// ─── Bot Row (expandable) ─────────────────────────────────────────────────

// Memoized with stable callbacks: opening one bot re-renders that row, not the whole list
const BotRow = memo(function BotRow({
  bot,
  serverId,
  isExpanded,
  onToggle,
  onChanged,
}: {
  bot: Bot;
  serverId: string;
  isExpanded: boolean;
  onToggle: (botId: string) => void;
  onChanged: () => void;
}) {
  const [pausing, setPausing] = useState(false);
  const [pauseError, setPauseError] = useState('');
  const [savingAccess, setSavingAccess] = useState(false);
  const isPaused = !!bot.pausedAt;

  async function changeAccess(access: RuntimeAccess) {
    if (access === 'auto' && !confirm(`Let ${bot.username} run code without approval? Runs still execute in the sandbox with its limits.`)) return;
    setSavingAccess(true);
    setPauseError('');
    try {
      await runtimeApi.setBotAccess(serverId, bot.id, access);
      onChanged();
    } catch (err) {
      setPauseError(err instanceof ApiError ? err.code : 'Failed to update code run access');
    } finally {
      setSavingAccess(false);
    }
  }

  async function togglePause() {
    setPausing(true);
    setPauseError('');
    try {
      if (isPaused) {
        await botApi.setPaused(serverId, bot.id, false);
      } else {
        const reason = prompt('Pause this bot? It will be read-only until resumed.\n\nReason (optional):');
        if (reason === null) return;
        await botApi.setPaused(serverId, bot.id, true, reason.trim() || undefined);
      }
      onChanged();
    } catch (err) {
      setPauseError(err instanceof ApiError ? err.code : 'Failed to update pause state');
    } finally {
      setPausing(false);
    }
  }

  return (
    <div className="border border-border rounded-lg overflow-hidden">
      <div className="flex items-center hover:bg-surface-hover">
      <button
        onClick={() => onToggle(bot.id)}
        aria-expanded={isExpanded}
        className="min-h-11 flex-1 flex items-center justify-between px-4 py-3 text-left"
      >
        <div>
          <span className="text-text font-medium">{bot.username}</span>
          {isPaused && (
            <span
              className="ml-2 inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-semibold leading-none bg-warn/20 text-warn"
              title={bot.pausedReason ? `Paused: ${bot.pausedReason}` : 'Paused'}
            >
              PAUSED
            </span>
          )}
          <span className="text-text-muted text-xs ml-2">
            {new Date(bot.createdAt).toLocaleDateString()}
          </span>
          {pauseError && <span className="text-danger text-xs ml-2">{pauseError}</span>}
        </div>
        <svg
          className="h-4 w-4 text-text-muted transition-transform"
          style={{ transform: isExpanded ? 'rotate(180deg)' : 'rotate(0deg)' }}
          fill="none"
          viewBox="0 0 24 24"
          stroke="currentColor"
          strokeWidth="2"
        >
          <polyline points="6 9 12 15 18 9" />
        </svg>
      </button>
      <label className="flex items-center gap-1 pr-3 text-xs text-text-muted" title="Whether this bot may run code in the sandbox">
        Code runs
        <select
          className="min-h-11 md:min-h-8 bg-surface border border-border rounded px-2 py-1 text-xs text-text"
          value={bot.runtimeAccess ?? 'none'}
          disabled={savingAccess}
          onChange={e => changeAccess(e.target.value as RuntimeAccess)}
          aria-label={`Code run access for ${bot.username}`}
        >
          <option value="none">Off</option>
          <option value="approval">Need approval</option>
          <option value="auto">Auto-run</option>
        </select>
      </label>
      <div className="pr-3">
        <Button variant="secondary" onClick={togglePause} loading={pausing}>
          {isPaused ? 'Resume' : 'Pause'}
        </Button>
      </div>
      </div>
      {isExpanded && (
        <BotDetailPanel botId={bot.id} serverId={serverId} onDeleted={onChanged} />
      )}
    </div>
  );
});

// ─── Bot Detail Panel ─────────────────────────────────────────────────────

function BotDetailPanel({
  botId,
  serverId,
  onDeleted,
}: {
  botId: string;
  serverId: string;
  onDeleted: () => void;
}) {
  const [detail, setDetail] = useState<BotDetail | null>(null);
  const [allChannels, setAllChannels] = useState<Channel[]>([]);
  const [tokens, setTokens] = useState<BotToken[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [showCreateToken, setShowCreateToken] = useState(false);
  const [showInvite, setShowInvite] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [channelLoading, setChannelLoading] = useState<string | null>(null);
  const [avatarInput, setAvatarInput] = useState('');
  const [avatarSaving, setAvatarSaving] = useState(false);
  const [avatarError, setAvatarError] = useState('');

  const fetchDetail = useCallback(async () => {
    try {
      const [d, channels] = await Promise.all([
        botApi.get(serverId, botId),
        serverApi.getChannels(serverId),
      ]);
      setDetail(d);
      setAvatarInput(d.avatarUrl || '');
      // Only show text channels (type 3) for bot access
      setAllChannels(channels.filter(c => c.channelType === 3));
      if (d.canManageTokens) {
        const t = await botApi.listTokens(serverId, botId);
        setTokens(t);
      }
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to load bot details');
    } finally {
      setLoading(false);
    }
  }, [serverId, botId]);

  useEffect(() => { fetchDetail(); }, [fetchDetail]);

  async function handleDelete() {
    if (!confirm('Delete this bot? This cannot be undone.')) return;
    setDeleting(true);
    try {
      await botApi.remove(serverId, botId);
      onDeleted();
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to delete bot');
      setDeleting(false);
    }
  }

  async function handleRevokeToken(tokenId: string) {
    try {
      await botApi.revokeToken(serverId, botId, tokenId);
      setTokens(prev => prev.map(t => t.id === tokenId ? { ...t, revokedAt: new Date().toISOString() } : t));
    } catch (err) {
      if (err instanceof ApiError && err.status === 403) {
        // Permissions changed — refetch detail
        fetchDetail();
      }
      setError(err instanceof ApiError ? err.code : 'Failed to revoke token');
    }
  }

  async function handleClearBinding(tokenId: string) {
    try {
      await botApi.clearTokenBinding(serverId, botId, tokenId);
      setTokens(prev => prev.map(t => t.id === tokenId ? { ...t, boundClient: null, boundAt: null, lastRefused: null } : t));
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to clear the binding');
    }
  }

  async function toggleDirect(channelId: string, canDirect: boolean) {
    setChannelLoading(channelId);
    setError('');
    try {
      await botApi.setCanDirect(channelId, botId, !canDirect);
      setDetail(await botApi.get(serverId, botId));
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to update who may direct');
    } finally {
      setChannelLoading(null);
    }
  }

  async function toggleChannel(channelId: string, hasAccess: boolean) {
    setChannelLoading(channelId);
    try {
      if (hasAccess) {
        await botApi.revokeChannel(channelId, botId);
      } else {
        await botApi.grantChannel(channelId, botId);
      }
      // Refetch detail to get updated channel list
      const d = await botApi.get(serverId, botId);
      setDetail(d);
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to update channel access');
    } finally {
      setChannelLoading(null);
    }
  }

  if (loading) {
    return <div className="px-4 py-3 border-t border-border text-text-muted text-sm">Loading...</div>;
  }

  if (error && !detail) {
    return <div className="px-4 py-3 border-t border-border text-danger text-sm">{error}</div>;
  }

  if (!detail) return null;

  const botChannelIds = new Set(detail.channels.map(c => c.id));
  const directChannelIds = new Set(detail.channels.filter(c => c.canDirect).map(c => c.id));
  const activeTokens = tokens.filter(t => !t.revokedAt);
  const revokedTokens = tokens.filter(t => t.revokedAt);

  return (
    <div className="border-t border-border px-4 py-4 flex flex-col gap-5 bg-bg/50">
      {error && <p className="text-danger text-sm">{error}</p>}

      {/* ── Avatar ── */}
      <section>
        <h4 className="text-sm font-semibold text-text mb-2">Avatar</h4>
        <div className="flex items-start gap-3">
          <Avatar userId={botId} username={detail.username} avatarUrl={detail.avatarUrl} className="h-12 w-12 text-sm" />
          <div className="flex-1 min-w-0">
            <input
              type="text"
              value={avatarInput}
              onChange={(e) => { setAvatarInput(e.target.value); setAvatarError(''); }}
              placeholder="data:image/svg+xml;base64,..."
              className="min-h-11 md:min-h-9 w-full px-3 py-1.5 rounded border border-border bg-surface text-text placeholder:text-text-muted/70 text-sm"
            />
            {avatarError && <p className="text-danger text-xs mt-1">{avatarError}</p>}
            <div className="flex gap-2 mt-2">
              <Button
                variant="secondary"
                className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
                loading={avatarSaving}
                onClick={async () => {
                  setAvatarSaving(true);
                  setAvatarError('');
                  try {
                    const res = await botApi.update(serverId, botId, { avatarUrl: avatarInput || null });
                    setDetail(prev => prev ? { ...prev, avatarUrl: res.avatarUrl } : prev);
                  } catch (err) {
                    setAvatarError(err instanceof ApiError ? err.code : 'Failed to save avatar');
                  } finally {
                    setAvatarSaving(false);
                  }
                }}
              >
                Save Avatar
              </Button>
              {detail.avatarUrl && (
                <Button
                  variant="secondary"
                  className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
                  onClick={async () => {
                    setAvatarSaving(true);
                    setAvatarError('');
                    try {
                      const res = await botApi.update(serverId, botId, { avatarUrl: null });
                      setDetail(prev => prev ? { ...prev, avatarUrl: res.avatarUrl } : prev);
                      setAvatarInput('');
                    } catch (err) {
                      setAvatarError(err instanceof ApiError ? err.code : 'Failed to remove avatar');
                    } finally {
                      setAvatarSaving(false);
                    }
                  }}
                >
                  Remove
                </Button>
              )}
            </div>
          </div>
        </div>
      </section>

      {/* ── Channel Access ── */}
      <section>
        <h4 className="text-sm font-semibold text-text mb-2">Channel Access</h4>
        {allChannels.length === 0 ? (
          <p className="text-text-muted text-xs">No text channels found.</p>
        ) : (
          <div className="flex flex-col gap-1">
            {allChannels.map((ch) => {
              const hasAccess = botChannelIds.has(ch.id);
              const isLoading = channelLoading === ch.id;
              return (
                <label
                  key={ch.id}
                  className="min-h-11 md:min-h-9 flex items-center gap-2 px-2 py-1.5 rounded hover:bg-surface-hover cursor-pointer text-sm"
                >
                  <input
                    type="checkbox"
                    checked={hasAccess}
                    disabled={isLoading}
                    onChange={() => toggleChannel(ch.id, hasAccess)}
                    className="accent-primary"
                  />
                  <span className="text-text-muted">#</span>
                  <span className="text-text">{ch.name}</span>
                  {isLoading && <span className="text-text-muted text-xs ml-auto">...</span>}
                  {hasAccess && (
                    <span
                      className="ml-auto flex items-center gap-1 text-xs text-text-muted"
                      title="Lets this bot give other agents instructions in this channel. Only the server owner can change it."
                      onClick={(e) => e.stopPropagation()}
                    >
                      <input
                        type="checkbox"
                        checked={directChannelIds.has(ch.id)}
                        disabled={isLoading}
                        onChange={() => toggleDirect(ch.id, directChannelIds.has(ch.id))}
                        className="accent-primary"
                      />
                      can direct agents
                    </span>
                  )}
                </label>
              );
            })}
          </div>
        )}
      </section>

      {/* ── Tokens (owner / admin only) ── */}
      {detail.canManageTokens && (
        <section>
          <Button onClick={() => setShowInvite(true)}>Invite Agent</Button>
          {showInvite && <CreateAgentInviteModal serverId={serverId} botId={botId} onClose={() => setShowInvite(false)} onCreated={() => {}} />}
          <div className="flex items-center justify-between mb-2">
            <h4 className="text-sm font-semibold text-text">Tokens</h4>
            <Button
              variant="secondary"
              className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
              onClick={() => setShowCreateToken(true)}
            >
              New Token
            </Button>
          </div>
          {activeTokens.length === 0 && revokedTokens.length === 0 ? (
            <p className="text-text-muted text-xs">No tokens yet.</p>
          ) : (
            <div className="flex flex-col gap-1">
              {activeTokens.map((t) => (
                <div key={t.id} className="flex items-center justify-between px-2 py-1.5 rounded bg-surface text-sm">
                  <div>
                    <span className="text-text">{t.name || 'Unnamed'}</span>
                    <span className="text-text-muted text-xs ml-2">
                      Created {new Date(t.createdAt).toLocaleDateString()}
                    </span>
                    {t.lastUsedAt && (
                      <span className="text-text-muted text-xs ml-2">
                        Last used {new Date(t.lastUsedAt).toLocaleDateString()}
                        {t.lastUsedClient ? ` by ${t.lastUsedClient}` : ''}
                        {t.lastUsedIp ? ` from ${t.lastUsedIp}` : ''}
                      </span>
                    )}
                    {t.boundClient && (
                      <span className="text-text-muted text-xs ml-2" title="Requests from any other client are refused">
                        Bound to {t.boundClient}
                      </span>
                    )}
                    {t.lastRefused && (
                      <span className="block text-danger text-xs">
                        Refused {t.lastRefused.client ? `use by ${t.lastRefused.client}` : 'a use with no client name'}
                        {t.lastRefused.ip ? ` from ${t.lastRefused.ip}` : ''} on {new Date(t.lastRefused.at).toLocaleString()}.
                        If that wasn't you moving this agent, revoke the token.
                      </span>
                    )}
                  </div>
                  <div className="flex shrink-0">
                    {t.boundClient && (
                      <button
                        onClick={() => handleClearBinding(t.id)}
                        className="min-h-11 md:min-h-8 px-2 text-text-muted text-xs hover:underline"
                        title="The next client that uses the token binds it again"
                      >
                        Clear binding
                      </button>
                    )}
                    <button
                      onClick={() => handleRevokeToken(t.id)}
                      className="min-h-11 md:min-h-8 px-2 text-danger text-xs hover:underline"
                    >
                      Revoke
                    </button>
                  </div>
                </div>
              ))}
              {revokedTokens.map((t) => (
                <div key={t.id} className="flex items-center px-2 py-1.5 rounded bg-surface text-sm opacity-50">
                  <span className="text-text line-through">{t.name || 'Unnamed'}</span>
                  <span className="text-text-muted text-xs ml-2">Revoked</span>
                </div>
              ))}
            </div>
          )}

          <CreateTokenModal
            serverId={serverId}
            botId={botId}
            isOpen={showCreateToken}
            onClose={() => setShowCreateToken(false)}
            onCreated={async () => {
              const t = await botApi.listTokens(serverId, botId);
              setTokens(t);
            }}
          />
        </section>
      )}

      {/* ── Delete Bot ── */}
      <div className="pt-2 border-t border-border">
        <Button variant="danger" onClick={handleDelete} loading={deleting}>
          Delete Bot
        </Button>
      </div>
    </div>
  );
}

import { memo, useCallback, useDeferredValue, useEffect, useMemo, useRef, useState } from 'react';
import { Link } from 'react-router-dom';
import { defaultRangeExtractor, useVirtualizer } from '@tanstack/react-virtual';
import { Avatar } from '../../components/ui/Avatar';
import { useServerStore } from '../../stores/serverStore';
import { useChannelStore } from '../../stores/channelStore';
import { botApi, serverApi, runtimeApi, ApiError } from '../../lib/api';
import type { Bot, BotDetail, BotToken, RuntimeAccess } from '../../lib/api';
import type { Channel } from '../../lib/contracts/server';
import { Button } from '../../components/ui/Button';
import { CreateBotModal } from './CreateBotModal';
import { CreateTokenModal } from './CreateTokenModal';
import { CreateAgentInviteModal } from './CreateAgentInviteModal';

export function BotManagement() {
  const instanceServerId = useServerStore(s => s.instanceServerId);
  const [bots, setBots] = useState<Bot[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [permissionDenied, setPermissionDenied] = useState(false);
  const [showCreateBot, setShowCreateBot] = useState(false);
  const [showInvite, setShowInvite] = useState(false);
  const [expandedBotId, setExpandedBotId] = useState<string | null>(null);
  const [query, setQuery] = useState('');
  const deferredQuery = useDeferredValue(query);

  const fetchBots = useCallback(async (showLoading = true) => {
    if (!instanceServerId) return;
    if (showLoading) setLoading(true);
    setError('');
    try {
      const data = await botApi.list(instanceServerId);
      setBots(data);
      setPermissionDenied(false);
    } catch (err) {
      if (err instanceof ApiError && err.status === 403) {
        setPermissionDenied(true);
      } else {
        setError(err instanceof ApiError ? err.code : 'Failed to load bots');
      }
    } finally {
      setLoading(false);
    }
  }, [instanceServerId]);

  useEffect(() => { fetchBots(); }, [fetchBots]);

  // A refresh after a change keeps the list (and its scroll position) on screen
  const refresh = useCallback(() => { void fetchBots(false); }, [fetchBots]);
  const toggle = useCallback((botId: string) => setExpandedBotId(cur => (cur === botId ? null : botId)), []);

  // Newest first, so a bot you just created is at the top of a long list
  const sorted = useMemo(() => [...bots].sort((a, b) => b.createdAt.localeCompare(a.createdAt)), [bots]);
  const shown = useMemo(() => {
    const q = deferredQuery.trim().toLowerCase();
    return q ? sorted.filter(b => b.username.toLowerCase().includes(q)) : sorted;
  }, [sorted, deferredQuery]);

  if (!instanceServerId) return null;

  if (permissionDenied) {
    return (
      <div>
        <h2 className="text-xl font-bold text-text mb-4">Bot Management</h2>
        <p className="text-text-muted mb-4">You don't have permission to manage bots.</p>
        <Link to="/app" className="hidden min-h-11 items-center text-primary-text hover:underline sm:inline-flex md:min-h-8">Back to chat</Link>
      </div>
    );
  }

  if (loading) {
    return <p className="text-text-muted">Loading bots...</p>;
  }

  return (
    <div>
      <div className="flex flex-wrap items-center justify-between gap-3 mb-6">
        <h2 className="text-xl font-bold text-text">Bot Management</h2>
        <div className="flex gap-2">
          <Button onClick={() => setShowInvite(true)}>Invite Agent</Button>
          <Button variant="secondary" onClick={() => setShowCreateBot(true)}>Create Bot</Button>
        </div>
      </div>

      {error && <p className="text-danger text-sm mb-4">{error}</p>}

      <ChannelLoopGuardSection serverId={instanceServerId} />

      {bots.length === 0 ? (
        <p className="text-text-muted">No bots yet. Create one to get started.</p>
      ) : (
        <section>
          <div className="flex flex-wrap items-center gap-3 mb-2">
            <input
              type="search"
              value={query}
              onChange={e => setQuery(e.target.value)}
              placeholder="Search bots"
              aria-label="Search bots"
              className="min-h-11 md:min-h-9 w-full max-w-xs px-3 py-1.5 rounded border border-border bg-surface text-text placeholder:text-text-muted/70 text-sm"
            />
            <span className="text-text-muted text-xs" aria-live="polite">
              {shown.length === bots.length ? `${bots.length} bots` : `${shown.length} of ${bots.length} bots`}
            </span>
          </div>
          {shown.length === 0 ? (
            <p className="text-text-muted text-sm">No bots match “{deferredQuery.trim()}”.</p>
          ) : (
            <BotList
              bots={shown}
              serverId={instanceServerId}
              expandedBotId={expandedBotId}
              onToggle={toggle}
              onChanged={refresh}
            />
          )}
        </section>
      )}

      <CreateBotModal
        serverId={instanceServerId}
        isOpen={showCreateBot}
        onClose={() => setShowCreateBot(false)}
        onCreated={refresh}
      />
      {showInvite && <CreateAgentInviteModal serverId={instanceServerId} onClose={() => setShowInvite(false)} onCreated={refresh} />}
    </div>
  );
}

// ─── Bot List (virtualized) ───────────────────────────────────────────────

/** Rendering every bot stalled the page at about 1,800 bots (#241): only the rows in view are mounted. */
function BotList({
  bots,
  serverId,
  expandedBotId,
  onToggle,
  onChanged,
}: {
  bots: Bot[];
  serverId: string;
  expandedBotId: string | null;
  onToggle: (botId: string) => void;
  onChanged: () => void;
}) {
  const scrollRef = useRef<HTMLDivElement>(null);
  const expandedIndex = expandedBotId ? bots.findIndex(b => b.id === expandedBotId) : -1;
  // This component is not compiled by the React Compiler; the virtualizer is read during render only
  // eslint-disable-next-line react-hooks/incompatible-library
  const virtualizer = useVirtualizer({
    count: bots.length,
    getScrollElement: () => scrollRef.current,
    estimateSize: () => 60,
    overscan: 8,
    getItemKey: index => bots[index].id,
    // The open bot stays mounted while scrolled away, so its panel (a half-made token, an error) survives
    rangeExtractor: range => {
      const indexes = defaultRangeExtractor(range);
      return expandedIndex < 0 || indexes.includes(expandedIndex) ? indexes : [...indexes, expandedIndex].sort((a, b) => a - b);
    },
  });

  return (
    <div ref={scrollRef} data-testid="bot-list" className="max-h-[70vh] overflow-y-auto overscroll-contain">
      <div className="relative w-full" style={{ height: virtualizer.getTotalSize() }}>
        {virtualizer.getVirtualItems().map(item => {
          const bot = bots[item.index];
          return (
            <div
              key={item.key}
              data-index={item.index}
              ref={virtualizer.measureElement}
              className="absolute left-0 top-0 w-full pb-2"
              style={{ transform: `translateY(${item.start}px)` }}
            >
              <BotRow
                bot={bot}
                serverId={serverId}
                isExpanded={expandedBotId === bot.id}
                onToggle={onToggle}
                onChanged={onChanged}
              />
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ─── Channel Loop Guard Settings ──────────────────────────────────────────

type GuardField = 'maxBotHops' | 'maxThreadBotHops';
type Limits = Record<GuardField, number>;
/** The limit a guard gets when it is switched on with no earlier value to restore. */
const GUARD_DEFAULT: Limits = { maxBotHops: 4, maxThreadBotHops: 4 };

/**
 * Both loop guards per channel (#23): the channel guard (top-level bot messages in a row)
 * and the thread guard (bot replies in a row inside one thread). Each has an on/off switch;
 * off is a limit of 0.
 */
function ChannelLoopGuardSection({ serverId }: { serverId: string }) {
  const [channels, setChannels] = useState<Channel[]>([]);
  // Limits as loaded or last confirmed by a save here
  const [loaded, setLoaded] = useState<Record<string, Limits>>({});
  // Edits not yet confirmed by the server, by `${channelId}:${field}`
  const [dirty, setDirty] = useState<Record<string, number>>({});
  const [saving, setSaving] = useState<Record<string, boolean>>({});
  const [error, setError] = useState('');
  // A change made elsewhere (a notice's Raise limit or Turn off) arrives as ChannelBotConfig
  const live = useChannelStore(s => s.channels);
  const pending = useRef<Record<string, { timer: ReturnType<typeof setTimeout>; value: number }>>({});
  // Saves of one field go out one at a time, in order, so the last change made wins
  const queues = useRef<Record<string, Promise<void>>>({});
  // The last limit above 0, restored when a guard is switched back on
  const lastOn = useRef<Record<string, number>>({});
  const mounted = useRef(true);

  useEffect(() => {
    serverApi.getChannels(serverId).then((chs) => {
      const textChannels = chs.filter(c => c.channelType === 3);
      setChannels(textChannels);
      const initial: Record<string, Limits> = {};
      for (const ch of textChannels) {
        initial[ch.id] = { maxBotHops: ch.maxBotHops ?? 4, maxThreadBotHops: ch.maxThreadBotHops ?? 0 };
      }
      setLoaded(initial);
    }).catch(() => setError('Failed to load channels'));
  }, [serverId]);

  // enqueue only touches refs and state setters, so the first render's copy stays valid for the unmount flush
  const enqueueOnLeave = useRef(enqueue);

  // Leaving the page sends a change still waiting out its debounce instead of dropping it,
  // behind any save of that field still in flight so the older one cannot land last
  useEffect(() => {
    mounted.current = true;
    const waiting = pending.current;
    const flush = enqueueOnLeave.current;
    return () => {
      mounted.current = false;
      for (const [key, p] of Object.entries(waiting)) {
        clearTimeout(p.timer);
        delete waiting[key];
        const [channelId, field] = key.split(':') as [string, GuardField];
        flush(channelId, field, p.value);
      }
    };
  }, []);

  const shown = (channelId: string, field: GuardField): number => {
    const key = `${channelId}:${field}`;
    return dirty[key] ?? live.get(channelId)?.[field] ?? loaded[channelId]?.[field] ?? GUARD_DEFAULT[field];
  };

  function change(channelId: string, field: GuardField, value: number, delay: number) {
    const key = `${channelId}:${field}`;
    const prev = shown(channelId, field);
    if (prev > 0) lastOn.current[key] = prev;
    setDirty(d => ({ ...d, [key]: value }));
    if (pending.current[key]) clearTimeout(pending.current[key].timer);
    const timer = setTimeout(() => {
      delete pending.current[key];
      enqueue(channelId, field, value);
    }, delay);
    pending.current[key] = { timer, value };
  }

  /** Queues a save behind any earlier save of the same field (save never rejects). */
  function enqueue(channelId: string, field: GuardField, value: number) {
    const key = `${channelId}:${field}`;
    queues.current[key] = (queues.current[key] ?? Promise.resolve()).then(() => save(channelId, field, value));
  }

  function handleNumber(channelId: string, field: GuardField, raw: string) {
    const num = parseInt(raw, 10);
    // 0 would be "off": that is the switch's job, so the box keeps a limit while typing
    if (isNaN(num) || num < 1 || num > 1000) return;
    change(channelId, field, num, 600);
  }

  function handleToggle(channelId: string, field: GuardField, on: boolean) {
    const restore = lastOn.current[`${channelId}:${field}`] ?? GUARD_DEFAULT[field];
    change(channelId, field, on ? restore : 0, 0);
  }

  async function save(channelId: string, field: GuardField, value: number) {
    const key = `${channelId}:${field}`;
    if (mounted.current) { setSaving(s => ({ ...s, [key]: true })); setError(''); }
    // Only the latest edit clears the dirty value; an older save finishing must not
    const settle = (d: Record<string, number>) => {
      if (d[key] !== value || pending.current[key]) return d;
      const next = { ...d };
      delete next[key];
      return next;
    };
    try {
      const config = await botApi.updateChannelBotConfig(channelId, { [field]: value });
      useChannelStore.getState().patchChannel(channelId, { maxBotHops: config.maxBotHops, maxThreadBotHops: config.maxThreadBotHops });
      if (!mounted.current) return;
      setLoaded(l => ({ ...l, [channelId]: { maxBotHops: config.maxBotHops, maxThreadBotHops: config.maxThreadBotHops } }));
      setDirty(settle);
    } catch (err) {
      if (!mounted.current) return;
      // Show what the server still has, not the value that failed
      setDirty(settle);
      setError(err instanceof ApiError ? err.code : 'Failed to save');
    } finally {
      mounted.current && setSaving(s => ({ ...s, [key]: false }));
    }
  }

  if (channels.length === 0) return null;

  const guard = (ch: Channel, field: GuardField, label: string, unit: string) => {
    const value = shown(ch.id, field);
    const on = value > 0;
    const key = `${ch.id}:${field}`;
    return (
      <div className="flex items-center gap-2">
        <label className="min-h-11 md:min-h-8 flex items-center gap-1.5 text-xs text-text-muted cursor-pointer">
          <input
            type="checkbox"
            role="switch"
            checked={on}
            onChange={e => handleToggle(ch.id, field, e.target.checked)}
            aria-label={`${label} loop guard in #${ch.name}`}
            className="accent-primary"
          />
          {label}
        </label>
        {on ? (
          <input
            type="number"
            min={1}
            max={1000}
            value={value}
            onChange={e => handleNumber(ch.id, field, e.target.value)}
            aria-label={`${label} limit in #${ch.name} (${unit})`}
            title={`Pause after this many ${unit} in a row`}
            className="min-h-11 md:min-h-8 w-16 px-2 py-1 rounded border border-border bg-surface text-text text-sm text-right"
          />
        ) : (
          <span className="w-16 text-text-muted text-xs">Off</span>
        )}
        <span className="w-12 text-text-muted text-xs" aria-live="polite">{saving[key] ? 'Saving…' : ''}</span>
      </div>
    );
  };

  return (
    <section className="mb-6">
      <h3 className="text-sm font-semibold text-text mb-2">Loop Guard</h3>
      <p className="text-text-muted text-xs mb-3">
        Pauses agents after this many bot posts in a row with no human message. The channel guard counts top-level
        messages; the thread guard counts replies inside each thread. A human message resets both, and the notice
        it posts has Continue, Raise limit and Turn off buttons.
      </p>
      {error && <p className="text-danger text-xs mb-2" role="alert">{error}</p>}
      <div className="flex flex-col gap-1">
        {channels.map((ch) => (
          <div key={ch.id} className="flex flex-wrap items-center gap-x-6 gap-y-1 px-2 py-1.5 rounded hover:bg-surface-hover">
            <span className="flex min-w-32 flex-1 items-center gap-1 text-sm">
              <span className="text-text-muted">#</span>
              <span className="text-text">{ch.name}</span>
            </span>
            {guard(ch, 'maxBotHops', 'Channel', 'bot messages')}
            {guard(ch, 'maxThreadBotHops', 'Threads', 'bot replies in one thread')}
          </div>
        ))}
      </div>
    </section>
  );
}

// ─── Bot Row (expandable) ─────────────────────────────────────────────────

// Memoized with stable callbacks: opening one bot re-renders that row, not the whole list
const BotRow = memo(function BotRow({
  bot,
  serverId,
  isExpanded,
  onToggle,
  onChanged,
}: {
  bot: Bot;
  serverId: string;
  isExpanded: boolean;
  onToggle: (botId: string) => void;
  onChanged: () => void;
}) {
  const [pausing, setPausing] = useState(false);
  const [pauseError, setPauseError] = useState('');
  const [savingAccess, setSavingAccess] = useState(false);
  const isPaused = !!bot.pausedAt;

  async function changeAccess(access: RuntimeAccess) {
    if (access === 'auto' && !confirm(`Let ${bot.username} run code without approval? Runs still execute in the sandbox with its limits.`)) return;
    setSavingAccess(true);
    setPauseError('');
    try {
      await runtimeApi.setBotAccess(serverId, bot.id, access);
      onChanged();
    } catch (err) {
      setPauseError(err instanceof ApiError ? err.code : 'Failed to update code run access');
    } finally {
      setSavingAccess(false);
    }
  }

  async function togglePause() {
    setPausing(true);
    setPauseError('');
    try {
      if (isPaused) {
        await botApi.setPaused(serverId, bot.id, false);
      } else {
        const reason = prompt('Pause this bot? It will be read-only until resumed.\n\nReason (optional):');
        if (reason === null) return;
        await botApi.setPaused(serverId, bot.id, true, reason.trim() || undefined);
      }
      onChanged();
    } catch (err) {
      setPauseError(err instanceof ApiError ? err.code : 'Failed to update pause state');
    } finally {
      setPausing(false);
    }
  }

  return (
    <div className="border border-border rounded-lg overflow-hidden">
      <div className="flex items-center hover:bg-surface-hover">
      <button
        onClick={() => onToggle(bot.id)}
        aria-expanded={isExpanded}
        className="min-h-11 flex-1 flex items-center justify-between px-4 py-3 text-left"
      >
        <div>
          <span className="text-text font-medium">{bot.username}</span>
          {isPaused && (
            <span
              className="ml-2 inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-semibold leading-none bg-warn/20 text-warn"
              title={bot.pausedReason ? `Paused: ${bot.pausedReason}` : 'Paused'}
            >
              PAUSED
            </span>
          )}
          <span className="text-text-muted text-xs ml-2">
            {new Date(bot.createdAt).toLocaleDateString()}
          </span>
          {pauseError && <span className="text-danger text-xs ml-2">{pauseError}</span>}
        </div>
        <svg
          className="h-4 w-4 text-text-muted transition-transform"
          style={{ transform: isExpanded ? 'rotate(180deg)' : 'rotate(0deg)' }}
          fill="none"
          viewBox="0 0 24 24"
          stroke="currentColor"
          strokeWidth="2"
        >
          <polyline points="6 9 12 15 18 9" />
        </svg>
      </button>
      <label className="flex items-center gap-1 pr-3 text-xs text-text-muted" title="Whether this bot may run code in the sandbox">
        Code runs
        <select
          className="min-h-11 md:min-h-8 bg-surface border border-border rounded px-2 py-1 text-xs text-text"
          value={bot.runtimeAccess ?? 'none'}
          disabled={savingAccess}
          onChange={e => changeAccess(e.target.value as RuntimeAccess)}
          aria-label={`Code run access for ${bot.username}`}
        >
          <option value="none">Off</option>
          <option value="approval">Need approval</option>
          <option value="auto">Auto-run</option>
        </select>
      </label>
      <div className="pr-3">
        <Button variant="secondary" onClick={togglePause} loading={pausing}>
          {isPaused ? 'Resume' : 'Pause'}
        </Button>
      </div>
      </div>
      {isExpanded && (
        <BotDetailPanel botId={bot.id} serverId={serverId} onDeleted={onChanged} />
      )}
    </div>
  );
});

// ─── Bot Detail Panel ─────────────────────────────────────────────────────

function BotDetailPanel({
  botId,
  serverId,
  onDeleted,
}: {
  botId: string;
  serverId: string;
  onDeleted: () => void;
}) {
  const [detail, setDetail] = useState<BotDetail | null>(null);
  const [allChannels, setAllChannels] = useState<Channel[]>([]);
  const [tokens, setTokens] = useState<BotToken[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [showCreateToken, setShowCreateToken] = useState(false);
  const [showInvite, setShowInvite] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [channelLoading, setChannelLoading] = useState<string | null>(null);
  const [avatarInput, setAvatarInput] = useState('');
  const [avatarSaving, setAvatarSaving] = useState(false);
  const [avatarError, setAvatarError] = useState('');

  const fetchDetail = useCallback(async () => {
    try {
      const [d, channels] = await Promise.all([
        botApi.get(serverId, botId),
        serverApi.getChannels(serverId),
      ]);
      setDetail(d);
      setAvatarInput(d.avatarUrl || '');
      // Only show text channels (type 3) for bot access
      setAllChannels(channels.filter(c => c.channelType === 3));
      if (d.canManageTokens) {
        const t = await botApi.listTokens(serverId, botId);
        setTokens(t);
      }
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to load bot details');
    } finally {
      setLoading(false);
    }
  }, [serverId, botId]);

  useEffect(() => { fetchDetail(); }, [fetchDetail]);

  async function handleDelete() {
    if (!confirm('Delete this bot? This cannot be undone.')) return;
    setDeleting(true);
    try {
      await botApi.remove(serverId, botId);
      onDeleted();
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to delete bot');
      setDeleting(false);
    }
  }

  async function handleRevokeToken(tokenId: string) {
    try {
      await botApi.revokeToken(serverId, botId, tokenId);
      setTokens(prev => prev.map(t => t.id === tokenId ? { ...t, revokedAt: new Date().toISOString() } : t));
    } catch (err) {
      if (err instanceof ApiError && err.status === 403) {
        // Permissions changed — refetch detail
        fetchDetail();
      }
      setError(err instanceof ApiError ? err.code : 'Failed to revoke token');
    }
  }

  async function handleClearBinding(tokenId: string) {
    try {
      await botApi.clearTokenBinding(serverId, botId, tokenId);
      setTokens(prev => prev.map(t => t.id === tokenId ? { ...t, boundClient: null, boundAt: null, lastRefused: null } : t));
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to clear the binding');
    }
  }

  async function toggleDirect(channelId: string, canDirect: boolean) {
    setChannelLoading(channelId);
    setError('');
    try {
      await botApi.setCanDirect(channelId, botId, !canDirect);
      setDetail(await botApi.get(serverId, botId));
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to update who may direct');
    } finally {
      setChannelLoading(null);
    }
  }

  async function toggleChannel(channelId: string, hasAccess: boolean) {
    setChannelLoading(channelId);
    try {
      if (hasAccess) {
        await botApi.revokeChannel(channelId, botId);
      } else {
        await botApi.grantChannel(channelId, botId);
      }
      // Refetch detail to get updated channel list
      const d = await botApi.get(serverId, botId);
      setDetail(d);
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to update channel access');
    } finally {
      setChannelLoading(null);
    }
  }

  if (loading) {
    return <div className="px-4 py-3 border-t border-border text-text-muted text-sm">Loading...</div>;
  }

  if (error && !detail) {
    return <div className="px-4 py-3 border-t border-border text-danger text-sm">{error}</div>;
  }

  if (!detail) return null;

  const botChannelIds = new Set(detail.channels.map(c => c.id));
  const directChannelIds = new Set(detail.channels.filter(c => c.canDirect).map(c => c.id));
  const activeTokens = tokens.filter(t => !t.revokedAt);
  const revokedTokens = tokens.filter(t => t.revokedAt);

  return (
    <div className="border-t border-border px-4 py-4 flex flex-col gap-5 bg-bg/50">
      {error && <p className="text-danger text-sm">{error}</p>}

      {/* ── Avatar ── */}
      <section>
        <h4 className="text-sm font-semibold text-text mb-2">Avatar</h4>
        <div className="flex items-start gap-3">
          <Avatar userId={botId} username={detail.username} avatarUrl={detail.avatarUrl} className="h-12 w-12 text-sm" />
          <div className="flex-1 min-w-0">
            <input
              type="text"
              value={avatarInput}
              onChange={(e) => { setAvatarInput(e.target.value); setAvatarError(''); }}
              placeholder="data:image/svg+xml;base64,..."
              className="min-h-11 md:min-h-9 w-full px-3 py-1.5 rounded border border-border bg-surface text-text placeholder:text-text-muted/70 text-sm"
            />
            {avatarError && <p className="text-danger text-xs mt-1">{avatarError}</p>}
            <div className="flex gap-2 mt-2">
              <Button
                variant="secondary"
                className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
                loading={avatarSaving}
                onClick={async () => {
                  setAvatarSaving(true);
                  setAvatarError('');
                  try {
                    const res = await botApi.update(serverId, botId, { avatarUrl: avatarInput || null });
                    setDetail(prev => prev ? { ...prev, avatarUrl: res.avatarUrl } : prev);
                  } catch (err) {
                    setAvatarError(err instanceof ApiError ? err.code : 'Failed to save avatar');
                  } finally {
                    setAvatarSaving(false);
                  }
                }}
              >
                Save Avatar
              </Button>
              {detail.avatarUrl && (
                <Button
                  variant="secondary"
                  className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
                  onClick={async () => {
                    setAvatarSaving(true);
                    setAvatarError('');
                    try {
                      const res = await botApi.update(serverId, botId, { avatarUrl: null });
                      setDetail(prev => prev ? { ...prev, avatarUrl: res.avatarUrl } : prev);
                      setAvatarInput('');
                    } catch (err) {
                      setAvatarError(err instanceof ApiError ? err.code : 'Failed to remove avatar');
                    } finally {
                      setAvatarSaving(false);
                    }
                  }}
                >
                  Remove
                </Button>
              )}
            </div>
          </div>
        </div>
      </section>

      {/* ── Channel Access ── */}
      <section>
        <h4 className="text-sm font-semibold text-text mb-2">Channel Access</h4>
        {allChannels.length === 0 ? (
          <p className="text-text-muted text-xs">No text channels found.</p>
        ) : (
          <div className="flex flex-col gap-1">
            {allChannels.map((ch) => {
              const hasAccess = botChannelIds.has(ch.id);
              const isLoading = channelLoading === ch.id;
              return (
                <label
                  key={ch.id}
                  className="min-h-11 md:min-h-9 flex items-center gap-2 px-2 py-1.5 rounded hover:bg-surface-hover cursor-pointer text-sm"
                >
                  <input
                    type="checkbox"
                    checked={hasAccess}
                    disabled={isLoading}
                    onChange={() => toggleChannel(ch.id, hasAccess)}
                    className="accent-primary"
                  />
                  <span className="text-text-muted">#</span>
                  <span className="text-text">{ch.name}</span>
                  {isLoading && <span className="text-text-muted text-xs ml-auto">...</span>}
                  {hasAccess && (
                    <span
                      className="ml-auto flex items-center gap-1 text-xs text-text-muted"
                      title="Lets this bot give other agents instructions in this channel. Only the server owner can change it."
                      onClick={(e) => e.stopPropagation()}
                    >
                      <input
                        type="checkbox"
                        checked={directChannelIds.has(ch.id)}
                        disabled={isLoading}
                        onChange={() => toggleDirect(ch.id, directChannelIds.has(ch.id))}
                        className="accent-primary"
                      />
                      can direct agents
                    </span>
                  )}
                </label>
              );
            })}
          </div>
        )}
      </section>

      {/* ── Tokens (owner / admin only) ── */}
      {detail.canManageTokens && (
        <section>
          <Button onClick={() => setShowInvite(true)}>Invite Agent</Button>
          {showInvite && <CreateAgentInviteModal serverId={serverId} botId={botId} onClose={() => setShowInvite(false)} onCreated={() => {}} />}
          <div className="flex items-center justify-between mb-2">
            <h4 className="text-sm font-semibold text-text">Tokens</h4>
            <Button
              variant="secondary"
              className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
              onClick={() => setShowCreateToken(true)}
            >
              New Token
            </Button>
          </div>
          {activeTokens.length === 0 && revokedTokens.length === 0 ? (
            <p className="text-text-muted text-xs">No tokens yet.</p>
          ) : (
            <div className="flex flex-col gap-1">
              {activeTokens.map((t) => (
                <div key={t.id} className="flex items-center justify-between px-2 py-1.5 rounded bg-surface text-sm">
                  <div>
                    <span className="text-text">{t.name || 'Unnamed'}</span>
                    <span className="text-text-muted text-xs ml-2">
                      Created {new Date(t.createdAt).toLocaleDateString()}
                    </span>
                    {t.lastUsedAt && (
                      <span className="text-text-muted text-xs ml-2">
                        Last used {new Date(t.lastUsedAt).toLocaleDateString()}
                        {t.lastUsedClient ? ` by ${t.lastUsedClient}` : ''}
                        {t.lastUsedIp ? ` from ${t.lastUsedIp}` : ''}
                      </span>
                    )}
                    {t.boundClient && (
                      <span className="text-text-muted text-xs ml-2" title="Requests from any other client are refused">
                        Bound to {t.boundClient}
                      </span>
                    )}
                    {t.lastRefused && (
                      <span className="block text-danger text-xs">
                        Refused {t.lastRefused.client ? `use by ${t.lastRefused.client}` : 'a use with no client name'}
                        {t.lastRefused.ip ? ` from ${t.lastRefused.ip}` : ''} on {new Date(t.lastRefused.at).toLocaleString()}.
                        If that wasn't you moving this agent, revoke the token.
                      </span>
                    )}
                  </div>
                  <div className="flex shrink-0">
                    {t.boundClient && (
                      <button
                        onClick={() => handleClearBinding(t.id)}
                        className="min-h-11 md:min-h-8 px-2 text-text-muted text-xs hover:underline"
                        title="The next client that uses the token binds it again"
                      >
                        Clear binding
                      </button>
                    )}
                    <button
                      onClick={() => handleRevokeToken(t.id)}
                      className="min-h-11 md:min-h-8 px-2 text-danger text-xs hover:underline"
                    >
                      Revoke
                    </button>
                  </div>
                </div>
              ))}
              {revokedTokens.map((t) => (
                <div key={t.id} className="flex items-center px-2 py-1.5 rounded bg-surface text-sm opacity-50">
                  <span className="text-text line-through">{t.name || 'Unnamed'}</span>
                  <span className="text-text-muted text-xs ml-2">Revoked</span>
                </div>
              ))}
            </div>
          )}

          <CreateTokenModal
            serverId={serverId}
            botId={botId}
            isOpen={showCreateToken}
            onClose={() => setShowCreateToken(false)}
            onCreated={async () => {
              const t = await botApi.listTokens(serverId, botId);
              setTokens(t);
            }}
          />
        </section>
      )}

      {/* ── Delete Bot ── */}
      <div className="pt-2 border-t border-border">
        <Button variant="danger" onClick={handleDelete} loading={deleting}>
          Delete Bot
        </Button>
      </div>
    </div>
  );
}

import { memo, useCallback, useDeferredValue, useEffect, useMemo, useRef, useState } from 'react';
import { Link } from 'react-router-dom';
import { defaultRangeExtractor, useVirtualizer } from '@tanstack/react-virtual';
import { Avatar } from '../../components/ui/Avatar';
import { useServerStore } from '../../stores/serverStore';
import { useChannelStore } from '../../stores/channelStore';
import { botApi, serverApi, runtimeApi, ApiError } from '../../lib/api';
import type { Bot, BotDetail, BotToken, RuntimeAccess } from '../../lib/api';
import type { Channel } from '../../lib/contracts/server';
import { Button } from '../../components/ui/Button';
import { CreateBotModal } from './CreateBotModal';
import { CreateTokenModal } from './CreateTokenModal';
import { CreateAgentInviteModal } from './CreateAgentInviteModal';

export function BotManagement() {
  const instanceServerId = useServerStore(s => s.instanceServerId);
  const [bots, setBots] = useState<Bot[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [permissionDenied, setPermissionDenied] = useState(false);
  const [showCreateBot, setShowCreateBot] = useState(false);
  const [showInvite, setShowInvite] = useState(false);
  const [expandedBotId, setExpandedBotId] = useState<string | null>(null);
  const [query, setQuery] = useState('');
  const deferredQuery = useDeferredValue(query);

  const fetchBots = useCallback(async (showLoading = true) => {
    if (!instanceServerId) return;
    if (showLoading) setLoading(true);
    setError('');
    try {
      const data = await botApi.list(instanceServerId);
      setBots(data);
      setPermissionDenied(false);
    } catch (err) {
      if (err instanceof ApiError && err.status === 403) {
        setPermissionDenied(true);
      } else {
        setError(err instanceof ApiError ? err.code : 'Failed to load bots');
      }
    } finally {
      setLoading(false);
    }
  }, [instanceServerId]);

  useEffect(() => { fetchBots(); }, [fetchBots]);

  // A refresh after a change keeps the list (and its scroll position) on screen
  const refresh = useCallback(() => { void fetchBots(false); }, [fetchBots]);
  const toggle = useCallback((botId: string) => setExpandedBotId(cur => (cur === botId ? null : botId)), []);

  // Newest first, so a bot you just created is at the top of a long list
  const sorted = useMemo(() => [...bots].sort((a, b) => b.createdAt.localeCompare(a.createdAt)), [bots]);
  const shown = useMemo(() => {
    const q = deferredQuery.trim().toLowerCase();
    return q ? sorted.filter(b => b.username.toLowerCase().includes(q)) : sorted;
  }, [sorted, deferredQuery]);

  if (!instanceServerId) return null;

  if (permissionDenied) {
    return (
      <div>
        <h2 className="text-xl font-bold text-text mb-4">Bot Management</h2>
        <p className="text-text-muted mb-4">You don't have permission to manage bots.</p>
        <Link to="/app" className="hidden min-h-11 items-center text-primary-text hover:underline sm:inline-flex md:min-h-8">Back to chat</Link>
      </div>
    );
  }

  if (loading) {
    return <p className="text-text-muted">Loading bots...</p>;
  }

  return (
    <div>
      <div className="flex flex-wrap items-center justify-between gap-3 mb-6">
        <h2 className="text-xl font-bold text-text">Bot Management</h2>
        <div className="flex gap-2">
          <Button onClick={() => setShowInvite(true)}>Invite Agent</Button>
          <Button variant="secondary" onClick={() => setShowCreateBot(true)}>Create Bot</Button>
        </div>
      </div>

      {error && <p className="text-danger text-sm mb-4">{error}</p>}

      <ChannelLoopGuardSection serverId={instanceServerId} />

      {bots.length === 0 ? (
        <p className="text-text-muted">No bots yet. Create one to get started.</p>
      ) : (
        <section>
          <div className="flex flex-wrap items-center gap-3 mb-2">
            <input
              type="search"
              value={query}
              onChange={e => setQuery(e.target.value)}
              placeholder="Search bots"
              aria-label="Search bots"
              className="min-h-11 md:min-h-9 w-full max-w-xs px-3 py-1.5 rounded border border-border bg-surface text-text placeholder:text-text-muted/70 text-sm"
            />
            <span className="text-text-muted text-xs" aria-live="polite">
              {shown.length === bots.length ? `${bots.length} bots` : `${shown.length} of ${bots.length} bots`}
            </span>
          </div>
          {shown.length === 0 ? (
            <p className="text-text-muted text-sm">No bots match “{deferredQuery.trim()}”.</p>
          ) : (
            <BotList
              bots={shown}
              serverId={instanceServerId}
              expandedBotId={expandedBotId}
              onToggle={toggle}
              onChanged={refresh}
            />
          )}
        </section>
      )}

      <CreateBotModal
        serverId={instanceServerId}
        isOpen={showCreateBot}
        onClose={() => setShowCreateBot(false)}
        onCreated={refresh}
      />
      {showInvite && <CreateAgentInviteModal serverId={instanceServerId} onClose={() => setShowInvite(false)} onCreated={refresh} />}
    </div>
  );
}

// ─── Bot List (virtualized) ───────────────────────────────────────────────

/** Rendering every bot stalled the page at about 1,800 bots (#241): only the rows in view are mounted. */
function BotList({
  bots,
  serverId,
  expandedBotId,
  onToggle,
  onChanged,
}: {
  bots: Bot[];
  serverId: string;
  expandedBotId: string | null;
  onToggle: (botId: string) => void;
  onChanged: () => void;
}) {
  const scrollRef = useRef<HTMLDivElement>(null);
  const expandedIndex = expandedBotId ? bots.findIndex(b => b.id === expandedBotId) : -1;
  // This component is not compiled by the React Compiler; the virtualizer is read during render only
  // eslint-disable-next-line react-hooks/incompatible-library
  const virtualizer = useVirtualizer({
    count: bots.length,
    getScrollElement: () => scrollRef.current,
    estimateSize: () => 60,
    overscan: 8,
    getItemKey: index => bots[index].id,
    // The open bot stays mounted while scrolled away, so its panel (a half-made token, an error) survives
    rangeExtractor: range => {
      const indexes = defaultRangeExtractor(range);
      return expandedIndex < 0 || indexes.includes(expandedIndex) ? indexes : [...indexes, expandedIndex].sort((a, b) => a - b);
    },
  });

  return (
    <div ref={scrollRef} data-testid="bot-list" className="max-h-[70vh] overflow-y-auto overscroll-contain">
      <div className="relative w-full" style={{ height: virtualizer.getTotalSize() }}>
        {virtualizer.getVirtualItems().map(item => {
          const bot = bots[item.index];
          return (
            <div
              key={item.key}
              data-index={item.index}
              ref={virtualizer.measureElement}
              className="absolute left-0 top-0 w-full pb-2"
              style={{ transform: `translateY(${item.start}px)` }}
            >
              <BotRow
                bot={bot}
                serverId={serverId}
                isExpanded={expandedBotId === bot.id}
                onToggle={onToggle}
                onChanged={onChanged}
              />
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ─── Channel Loop Guard Settings ──────────────────────────────────────────

type GuardField = 'maxBotHops' | 'maxThreadBotHops';
type Limits = Record<GuardField, number>;
/** The limit a guard gets when it is switched on with no earlier value to restore. */
const GUARD_DEFAULT: Limits = { maxBotHops: 4, maxThreadBotHops: 4 };

/**
 * Both loop guards per channel (#23): the channel guard (top-level bot messages in a row)
 * and the thread guard (bot replies in a row inside one thread). Each has an on/off switch;
 * off is a limit of 0.
 */
function ChannelLoopGuardSection({ serverId }: { serverId: string }) {
  const [channels, setChannels] = useState<Channel[]>([]);
  // Limits as loaded or last confirmed by a save here
  const [loaded, setLoaded] = useState<Record<string, Limits>>({});
  // Edits not yet confirmed by the server, by `${channelId}:${field}`
  const [dirty, setDirty] = useState<Record<string, number>>({});
  const [saving, setSaving] = useState<Record<string, boolean>>({});
  const [error, setError] = useState('');
  // A change made elsewhere (a notice's Raise limit or Turn off) arrives as ChannelBotConfig
  const live = useChannelStore(s => s.channels);
  const pending = useRef<Record<string, { timer: ReturnType<typeof setTimeout>; value: number }>>({});
  // Saves of one field go out one at a time, in order, so the last change made wins
  const queues = useRef<Record<string, Promise<void>>>({});
  // The last limit above 0, restored when a guard is switched back on
  const lastOn = useRef<Record<string, number>>({});
  const mounted = useRef(true);

  useEffect(() => {
    serverApi.getChannels(serverId).then((chs) => {
      const textChannels = chs.filter(c => c.channelType === 3);
      setChannels(textChannels);
      const initial: Record<string, Limits> = {};
      for (const ch of textChannels) {
        initial[ch.id] = { maxBotHops: ch.maxBotHops ?? 4, maxThreadBotHops: ch.maxThreadBotHops ?? 0 };
      }
      setLoaded(initial);
    }).catch(() => setError('Failed to load channels'));
  }, [serverId]);

  // enqueue only touches refs and state setters, so the first render's copy stays valid for the unmount flush
  const enqueueOnLeave = useRef(enqueue);

  // Leaving the page sends a change still waiting out its debounce instead of dropping it,
  // behind any save of that field still in flight so the older one cannot land last
  useEffect(() => {
    mounted.current = true;
    const waiting = pending.current;
    const flush = enqueueOnLeave.current;
    return () => {
      mounted.current = false;
      for (const [key, p] of Object.entries(waiting)) {
        clearTimeout(p.timer);
        delete waiting[key];
        const [channelId, field] = key.split(':') as [string, GuardField];
        flush(channelId, field, p.value);
      }
    };
  }, []);

  const shown = (channelId: string, field: GuardField): number => {
    const key = `${channelId}:${field}`;
    return dirty[key] ?? live.get(channelId)?.[field] ?? loaded[channelId]?.[field] ?? GUARD_DEFAULT[field];
  };

  function change(channelId: string, field: GuardField, value: number, delay: number) {
    const key = `${channelId}:${field}`;
    const prev = shown(channelId, field);
    if (prev > 0) lastOn.current[key] = prev;
    setDirty(d => ({ ...d, [key]: value }));
    if (pending.current[key]) clearTimeout(pending.current[key].timer);
    const timer = setTimeout(() => {
      delete pending.current[key];
      enqueue(channelId, field, value);
    }, delay);
    pending.current[key] = { timer, value };
  }

  /** Queues a save behind any earlier save of the same field (save never rejects). */
  function enqueue(channelId: string, field: GuardField, value: number) {
    const key = `${channelId}:${field}`;
    queues.current[key] = (queues.current[key] ?? Promise.resolve()).then(() => save(channelId, field, value));
  }

  function handleNumber(channelId: string, field: GuardField, raw: string) {
    const num = parseInt(raw, 10);
    // 0 would be "off": that is the switch's job, so the box keeps a limit while typing
    if (isNaN(num) || num < 1 || num > 1000) return;
    change(channelId, field, num, 600);
  }

  function handleToggle(channelId: string, field: GuardField, on: boolean) {
    const restore = lastOn.current[`${channelId}:${field}`] ?? GUARD_DEFAULT[field];
    change(channelId, field, on ? restore : 0, 0);
  }

  async function save(channelId: string, field: GuardField, value: number) {
    const key = `${channelId}:${field}`;
    if (mounted.current) { setSaving(s => ({ ...s, [key]: true })); setError(''); }
    // Only the latest edit clears the dirty value; an older save finishing must not
    const settle = (d: Record<string, number>) => {
      if (d[key] !== value || pending.current[key]) return d;
      const next = { ...d };
      delete next[key];
      return next;
    };
    try {
      const config = await botApi.updateChannelBotConfig(channelId, { [field]: value });
      useChannelStore.getState().patchChannel(channelId, { maxBotHops: config.maxBotHops, maxThreadBotHops: config.maxThreadBotHops });
      if (!mounted.current) return;
      setLoaded(l => ({ ...l, [channelId]: { maxBotHops: config.maxBotHops, maxThreadBotHops: config.maxThreadBotHops } }));
      setDirty(settle);
    } catch (err) {
      if (!mounted.current) return;
      // Show what the server still has, not the value that failed
      setDirty(settle);
      setError(err instanceof ApiError ? err.code : 'Failed to save');
    } finally {
      if (mounted.current) setSaving(s => ({ ...s, [key]: false }));
    }
  }

  if (channels.length === 0) return null;

  const guard = (ch: Channel, field: GuardField, label: string, unit: string) => {
    const value = shown(ch.id, field);
    const on = value > 0;
    const key = `${ch.id}:${field}`;
    return (
      <div className="flex items-center gap-2">
        <label className="min-h-11 md:min-h-8 flex items-center gap-1.5 text-xs text-text-muted cursor-pointer">
          <input
            type="checkbox"
            role="switch"
            checked={on}
            onChange={e => handleToggle(ch.id, field, e.target.checked)}
            aria-label={`${label} loop guard in #${ch.name}`}
            className="accent-primary"
          />
          {label}
        </label>
        {on ? (
          <input
            type="number"
            min={1}
            max={1000}
            value={value}
            onChange={e => handleNumber(ch.id, field, e.target.value)}
            aria-label={`${label} limit in #${ch.name} (${unit})`}
            title={`Pause after this many ${unit} in a row`}
            className="min-h-11 md:min-h-8 w-16 px-2 py-1 rounded border border-border bg-surface text-text text-sm text-right"
          />
        ) : (
          <span className="w-16 text-text-muted text-xs">Off</span>
        )}
        <span className="w-12 text-text-muted text-xs" aria-live="polite">{saving[key] ? 'Saving…' : ''}</span>
      </div>
    );
  };

  return (
    <section className="mb-6">
      <h3 className="text-sm font-semibold text-text mb-2">Loop Guard</h3>
      <p className="text-text-muted text-xs mb-3">
        Pauses agents after this many bot posts in a row with no human message. The channel guard counts top-level
        messages; the thread guard counts replies inside each thread. A human message resets both, and the notice
        it posts has Continue, Raise limit and Turn off buttons.
      </p>
      {error && <p className="text-danger text-xs mb-2" role="alert">{error}</p>}
      <div className="flex flex-col gap-1">
        {channels.map((ch) => (
          <div key={ch.id} className="flex flex-wrap items-center gap-x-6 gap-y-1 px-2 py-1.5 rounded hover:bg-surface-hover">
            <span className="flex min-w-32 flex-1 items-center gap-1 text-sm">
              <span className="text-text-muted">#</span>
              <span className="text-text">{ch.name}</span>
            </span>
            {guard(ch, 'maxBotHops', 'Channel', 'bot messages')}
            {guard(ch, 'maxThreadBotHops', 'Threads', 'bot replies in one thread')}
          </div>
        ))}
      </div>
    </section>
  );
}

// ─── Bot Row (expandable) ─────────────────────────────────────────────────

// Memoized with stable callbacks: opening one bot re-renders that row, not the whole list
const BotRow = memo(function BotRow({
  bot,
  serverId,
  isExpanded,
  onToggle,
  onChanged,
}: {
  bot: Bot;
  serverId: string;
  isExpanded: boolean;
  onToggle: (botId: string) => void;
  onChanged: () => void;
}) {
  const [pausing, setPausing] = useState(false);
  const [pauseError, setPauseError] = useState('');
  const [savingAccess, setSavingAccess] = useState(false);
  const isPaused = !!bot.pausedAt;

  async function changeAccess(access: RuntimeAccess) {
    if (access === 'auto' && !confirm(`Let ${bot.username} run code without approval? Runs still execute in the sandbox with its limits.`)) return;
    setSavingAccess(true);
    setPauseError('');
    try {
      await runtimeApi.setBotAccess(serverId, bot.id, access);
      onChanged();
    } catch (err) {
      setPauseError(err instanceof ApiError ? err.code : 'Failed to update code run access');
    } finally {
      setSavingAccess(false);
    }
  }

  async function togglePause() {
    setPausing(true);
    setPauseError('');
    try {
      if (isPaused) {
        await botApi.setPaused(serverId, bot.id, false);
      } else {
        const reason = prompt('Pause this bot? It will be read-only until resumed.\n\nReason (optional):');
        if (reason === null) return;
        await botApi.setPaused(serverId, bot.id, true, reason.trim() || undefined);
      }
      onChanged();
    } catch (err) {
      setPauseError(err instanceof ApiError ? err.code : 'Failed to update pause state');
    } finally {
      setPausing(false);
    }
  }

  return (
    <div className="border border-border rounded-lg overflow-hidden">
      <div className="flex items-center hover:bg-surface-hover">
      <button
        onClick={() => onToggle(bot.id)}
        aria-expanded={isExpanded}
        className="min-h-11 flex-1 flex items-center justify-between px-4 py-3 text-left"
      >
        <div>
          <span className="text-text font-medium">{bot.username}</span>
          {isPaused && (
            <span
              className="ml-2 inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-semibold leading-none bg-warn/20 text-warn"
              title={bot.pausedReason ? `Paused: ${bot.pausedReason}` : 'Paused'}
            >
              PAUSED
            </span>
          )}
          <span className="text-text-muted text-xs ml-2">
            {new Date(bot.createdAt).toLocaleDateString()}
          </span>
          {pauseError && <span className="text-danger text-xs ml-2">{pauseError}</span>}
        </div>
        <svg
          className="h-4 w-4 text-text-muted transition-transform"
          style={{ transform: isExpanded ? 'rotate(180deg)' : 'rotate(0deg)' }}
          fill="none"
          viewBox="0 0 24 24"
          stroke="currentColor"
          strokeWidth="2"
        >
          <polyline points="6 9 12 15 18 9" />
        </svg>
      </button>
      <label className="flex items-center gap-1 pr-3 text-xs text-text-muted" title="Whether this bot may run code in the sandbox">
        Code runs
        <select
          className="min-h-11 md:min-h-8 bg-surface border border-border rounded px-2 py-1 text-xs text-text"
          value={bot.runtimeAccess ?? 'none'}
          disabled={savingAccess}
          onChange={e => changeAccess(e.target.value as RuntimeAccess)}
          aria-label={`Code run access for ${bot.username}`}
        >
          <option value="none">Off</option>
          <option value="approval">Need approval</option>
          <option value="auto">Auto-run</option>
        </select>
      </label>
      <div className="pr-3">
        <Button variant="secondary" onClick={togglePause} loading={pausing}>
          {isPaused ? 'Resume' : 'Pause'}
        </Button>
      </div>
      </div>
      {isExpanded && (
        <BotDetailPanel botId={bot.id} serverId={serverId} onDeleted={onChanged} />
      )}
    </div>
  );
});

// ─── Bot Detail Panel ─────────────────────────────────────────────────────

function BotDetailPanel({
  botId,
  serverId,
  onDeleted,
}: {
  botId: string;
  serverId: string;
  onDeleted: () => void;
}) {
  const [detail, setDetail] = useState<BotDetail | null>(null);
  const [allChannels, setAllChannels] = useState<Channel[]>([]);
  const [tokens, setTokens] = useState<BotToken[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [showCreateToken, setShowCreateToken] = useState(false);
  const [showInvite, setShowInvite] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [channelLoading, setChannelLoading] = useState<string | null>(null);
  const [avatarInput, setAvatarInput] = useState('');
  const [avatarSaving, setAvatarSaving] = useState(false);
  const [avatarError, setAvatarError] = useState('');

  const fetchDetail = useCallback(async () => {
    try {
      const [d, channels] = await Promise.all([
        botApi.get(serverId, botId),
        serverApi.getChannels(serverId),
      ]);
      setDetail(d);
      setAvatarInput(d.avatarUrl || '');
      // Only show text channels (type 3) for bot access
      setAllChannels(channels.filter(c => c.channelType === 3));
      if (d.canManageTokens) {
        const t = await botApi.listTokens(serverId, botId);
        setTokens(t);
      }
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to load bot details');
    } finally {
      setLoading(false);
    }
  }, [serverId, botId]);

  useEffect(() => { fetchDetail(); }, [fetchDetail]);

  async function handleDelete() {
    if (!confirm('Delete this bot? This cannot be undone.')) return;
    setDeleting(true);
    try {
      await botApi.remove(serverId, botId);
      onDeleted();
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to delete bot');
      setDeleting(false);
    }
  }

  async function handleRevokeToken(tokenId: string) {
    try {
      await botApi.revokeToken(serverId, botId, tokenId);
      setTokens(prev => prev.map(t => t.id === tokenId ? { ...t, revokedAt: new Date().toISOString() } : t));
    } catch (err) {
      if (err instanceof ApiError && err.status === 403) {
        // Permissions changed — refetch detail
        fetchDetail();
      }
      setError(err instanceof ApiError ? err.code : 'Failed to revoke token');
    }
  }

  async function handleClearBinding(tokenId: string) {
    try {
      await botApi.clearTokenBinding(serverId, botId, tokenId);
      setTokens(prev => prev.map(t => t.id === tokenId ? { ...t, boundClient: null, boundAt: null, lastRefused: null } : t));
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to clear the binding');
    }
  }

  async function toggleDirect(channelId: string, canDirect: boolean) {
    setChannelLoading(channelId);
    setError('');
    try {
      await botApi.setCanDirect(channelId, botId, !canDirect);
      setDetail(await botApi.get(serverId, botId));
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to update who may direct');
    } finally {
      setChannelLoading(null);
    }
  }

  async function toggleChannel(channelId: string, hasAccess: boolean) {
    setChannelLoading(channelId);
    try {
      hasAccess ? await botApi.revokeChannel(channelId, botId) : await botApi.grantChannel(channelId, botId);
      // Refetch detail to get updated channel list
      const d = await botApi.get(serverId, botId);
      setDetail(d);
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to update channel access');
    } finally {
      setChannelLoading(null);
    }
  }

  if (loading) {
    return <div className="px-4 py-3 border-t border-border text-text-muted text-sm">Loading...</div>;
  }

  if (error && !detail) {
    return <div className="px-4 py-3 border-t border-border text-danger text-sm">{error}</div>;
  }

  if (!detail) return null;

  const botChannelIds = new Set(detail.channels.map(c => c.id));
  const directChannelIds = new Set(detail.channels.filter(c => c.canDirect).map(c => c.id));
  const activeTokens = tokens.filter(t => !t.revokedAt);
  const revokedTokens = tokens.filter(t => t.revokedAt);

  return (
    <div className="border-t border-border px-4 py-4 flex flex-col gap-5 bg-bg/50">
      {error && <p className="text-danger text-sm">{error}</p>}

      {/* ── Avatar ── */}
      <section>
        <h4 className="text-sm font-semibold text-text mb-2">Avatar</h4>
        <div className="flex items-start gap-3">
          <Avatar userId={botId} username={detail.username} avatarUrl={detail.avatarUrl} className="h-12 w-12 text-sm" />
          <div className="flex-1 min-w-0">
            <input
              type="text"
              value={avatarInput}
              onChange={(e) => { setAvatarInput(e.target.value); setAvatarError(''); }}
              placeholder="data:image/svg+xml;base64,..."
              className="min-h-11 md:min-h-9 w-full px-3 py-1.5 rounded border border-border bg-surface text-text placeholder:text-text-muted/70 text-sm"
            />
            {avatarError && <p className="text-danger text-xs mt-1">{avatarError}</p>}
            <div className="flex gap-2 mt-2">
              <Button
                variant="secondary"
                className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
                loading={avatarSaving}
                onClick={async () => {
                  setAvatarSaving(true);
                  setAvatarError('');
                  try {
                    const res = await botApi.update(serverId, botId, { avatarUrl: avatarInput || null });
                    setDetail(prev => prev ? { ...prev, avatarUrl: res.avatarUrl } : prev);
                  } catch (err) {
                    setAvatarError(err instanceof ApiError ? err.code : 'Failed to save avatar');
                  } finally {
                    setAvatarSaving(false);
                  }
                }}
              >
                Save Avatar
              </Button>
              {detail.avatarUrl && (
                <Button
                  variant="secondary"
                  className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
                  onClick={async () => {
                    setAvatarSaving(true);
                    setAvatarError('');
                    try {
                      const res = await botApi.update(serverId, botId, { avatarUrl: null });
                      setDetail(prev => prev ? { ...prev, avatarUrl: res.avatarUrl } : prev);
                      setAvatarInput('');
                    } catch (err) {
                      setAvatarError(err instanceof ApiError ? err.code : 'Failed to remove avatar');
                    } finally {
                      setAvatarSaving(false);
                    }
                  }}
                >
                  Remove
                </Button>
              )}
            </div>
          </div>
        </div>
      </section>

      {/* ── Channel Access ── */}
      <section>
        <h4 className="text-sm font-semibold text-text mb-2">Channel Access</h4>
        {allChannels.length === 0 ? (
          <p className="text-text-muted text-xs">No text channels found.</p>
        ) : (
          <div className="flex flex-col gap-1">
            {allChannels.map((ch) => {
              const hasAccess = botChannelIds.has(ch.id);
              const isLoading = channelLoading === ch.id;
              return (
                <label
                  key={ch.id}
                  className="min-h-11 md:min-h-9 flex items-center gap-2 px-2 py-1.5 rounded hover:bg-surface-hover cursor-pointer text-sm"
                >
                  <input
                    type="checkbox"
                    checked={hasAccess}
                    disabled={isLoading}
                    onChange={() => toggleChannel(ch.id, hasAccess)}
                    className="accent-primary"
                  />
                  <span className="text-text-muted">#</span>
                  <span className="text-text">{ch.name}</span>
                  {isLoading && <span className="text-text-muted text-xs ml-auto">...</span>}
                  {hasAccess && (
                    <span
                      className="ml-auto flex items-center gap-1 text-xs text-text-muted"
                      title="Lets this bot give other agents instructions in this channel. Only the server owner can change it."
                      onClick={(e) => e.stopPropagation()}
                    >
                      <input
                        type="checkbox"
                        checked={directChannelIds.has(ch.id)}
                        disabled={isLoading}
                        onChange={() => toggleDirect(ch.id, directChannelIds.has(ch.id))}
                        className="accent-primary"
                      />
                      can direct agents
                    </span>
                  )}
                </label>
              );
            })}
          </div>
        )}
      </section>

      {/* ── Tokens (owner / admin only) ── */}
      {detail.canManageTokens && (
        <section>
          <Button onClick={() => setShowInvite(true)}>Invite Agent</Button>
          {showInvite && <CreateAgentInviteModal serverId={serverId} botId={botId} onClose={() => setShowInvite(false)} onCreated={() => {}} />}
          <div className="flex items-center justify-between mb-2">
            <h4 className="text-sm font-semibold text-text">Tokens</h4>
            <Button
              variant="secondary"
              className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
              onClick={() => setShowCreateToken(true)}
            >
              New Token
            </Button>
          </div>
          {activeTokens.length === 0 && revokedTokens.length === 0 ? (
            <p className="text-text-muted text-xs">No tokens yet.</p>
          ) : (
            <div className="flex flex-col gap-1">
              {activeTokens.map((t) => (
                <div key={t.id} className="flex items-center justify-between px-2 py-1.5 rounded bg-surface text-sm">
                  <div>
                    <span className="text-text">{t.name || 'Unnamed'}</span>
                    <span className="text-text-muted text-xs ml-2">
                      Created {new Date(t.createdAt).toLocaleDateString()}
                    </span>
                    {t.lastUsedAt && (
                      <span className="text-text-muted text-xs ml-2">
                        Last used {new Date(t.lastUsedAt).toLocaleDateString()}
                        {t.lastUsedClient ? ` by ${t.lastUsedClient}` : ''}
                        {t.lastUsedIp ? ` from ${t.lastUsedIp}` : ''}
                      </span>
                    )}
                    {t.boundClient && (
                      <span className="text-text-muted text-xs ml-2" title="Requests from any other client are refused">
                        Bound to {t.boundClient}
                      </span>
                    )}
                    {t.lastRefused && (
                      <span className="block text-danger text-xs">
                        Refused {t.lastRefused.client ? `use by ${t.lastRefused.client}` : 'a use with no client name'}
                        {t.lastRefused.ip ? ` from ${t.lastRefused.ip}` : ''} on {new Date(t.lastRefused.at).toLocaleString()}.
                        If that wasn't you moving this agent, revoke the token.
                      </span>
                    )}
                  </div>
                  <div className="flex shrink-0">
                    {t.boundClient && (
                      <button
                        onClick={() => handleClearBinding(t.id)}
                        className="min-h-11 md:min-h-8 px-2 text-text-muted text-xs hover:underline"
                        title="The next client that uses the token binds it again"
                      >
                        Clear binding
                      </button>
                    )}
                    <button
                      onClick={() => handleRevokeToken(t.id)}
                      className="min-h-11 md:min-h-8 px-2 text-danger text-xs hover:underline"
                    >
                      Revoke
                    </button>
                  </div>
                </div>
              ))}
              {revokedTokens.map((t) => (
                <div key={t.id} className="flex items-center px-2 py-1.5 rounded bg-surface text-sm opacity-50">
                  <span className="text-text line-through">{t.name || 'Unnamed'}</span>
                  <span className="text-text-muted text-xs ml-2">Revoked</span>
                </div>
              ))}
            </div>
          )}

          <CreateTokenModal
            serverId={serverId}
            botId={botId}
            isOpen={showCreateToken}
            onClose={() => setShowCreateToken(false)}
            onCreated={async () => {
              const t = await botApi.listTokens(serverId, botId);
              setTokens(t);
            }}
          />
        </section>
      )}

      {/* ── Delete Bot ── */}
      <div className="pt-2 border-t border-border">
        <Button variant="danger" onClick={handleDelete} loading={deleting}>
          Delete Bot
        </Button>
      </div>
    </div>
  );
}

import { memo, useCallback, useDeferredValue, useEffect, useMemo, useRef, useState } from 'react';
import { Link } from 'react-router-dom';
import { defaultRangeExtractor, useVirtualizer } from '@tanstack/react-virtual';
import { Avatar } from '../../components/ui/Avatar';
import { useServerStore } from '../../stores/serverStore';
import { useChannelStore } from '../../stores/channelStore';
import { botApi, serverApi, runtimeApi, ApiError } from '../../lib/api';
import type { Bot, BotDetail, BotToken, RuntimeAccess } from '../../lib/api';
import type { Channel } from '../../lib/contracts/server';
import { Button } from '../../components/ui/Button';
import { CreateBotModal } from './CreateBotModal';
import { CreateTokenModal } from './CreateTokenModal';
import { CreateAgentInviteModal } from './CreateAgentInviteModal';

export function BotManagement() {
  const instanceServerId = useServerStore(s => s.instanceServerId);
  const [bots, setBots] = useState<Bot[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [permissionDenied, setPermissionDenied] = useState(false);
  const [showCreateBot, setShowCreateBot] = useState(false);
  const [showInvite, setShowInvite] = useState(false);
  const [expandedBotId, setExpandedBotId] = useState<string | null>(null);
  const [query, setQuery] = useState('');
  const deferredQuery = useDeferredValue(query);

  const fetchBots = useCallback(async (showLoading = true) => {
    if (!instanceServerId) return;
    if (showLoading) setLoading(true);
    setError('');
    try {
      const data = await botApi.list(instanceServerId);
      setBots(data);
      setPermissionDenied(false);
    } catch (err) {
      if (err instanceof ApiError && err.status === 403) {
        setPermissionDenied(true);
      } else {
        setError(err instanceof ApiError ? err.code : 'Failed to load bots');
      }
    } finally {
      setLoading(false);
    }
  }, [instanceServerId]);

  useEffect(() => { fetchBots(); }, [fetchBots]);

  // A refresh after a change keeps the list (and its scroll position) on screen
  const refresh = useCallback(() => { void fetchBots(false); }, [fetchBots]);
  const toggle = useCallback((botId: string) => setExpandedBotId(cur => (cur === botId ? null : botId)), []);

  // Newest first, so a bot you just created is at the top of a long list
  const sorted = useMemo(() => [...bots].sort((a, b) => b.createdAt.localeCompare(a.createdAt)), [bots]);
  const shown = useMemo(() => {
    const q = deferredQuery.trim().toLowerCase();
    return q ? sorted.filter(b => b.username.toLowerCase().includes(q)) : sorted;
  }, [sorted, deferredQuery]);

  if (!instanceServerId) return null;

  if (permissionDenied) {
    return (
      <div>
        <h2 className="text-xl font-bold text-text mb-4">Bot Management</h2>
        <p className="text-text-muted mb-4">You don't have permission to manage bots.</p>
        <Link to="/app" className="hidden min-h-11 items-center text-primary-text hover:underline sm:inline-flex md:min-h-8">Back to chat</Link>
      </div>
    );
  }

  if (loading) {
    return <p className="text-text-muted">Loading bots...</p>;
  }

  return (
    <div>
      <div className="flex flex-wrap items-center justify-between gap-3 mb-6">
        <h2 className="text-xl font-bold text-text">Bot Management</h2>
        <div className="flex gap-2">
          <Button onClick={() => setShowInvite(true)}>Invite Agent</Button>
          <Button variant="secondary" onClick={() => setShowCreateBot(true)}>Create Bot</Button>
        </div>
      </div>

      {error && <p className="text-danger text-sm mb-4">{error}</p>}

      <ChannelLoopGuardSection serverId={instanceServerId} />

      {bots.length === 0 ? (
        <p className="text-text-muted">No bots yet. Create one to get started.</p>
      ) : (
        <section>
          <div className="flex flex-wrap items-center gap-3 mb-2">
            <input
              type="search"
              value={query}
              onChange={e => setQuery(e.target.value)}
              placeholder="Search bots"
              aria-label="Search bots"
              className="min-h-11 md:min-h-9 w-full max-w-xs px-3 py-1.5 rounded border border-border bg-surface text-text placeholder:text-text-muted/70 text-sm"
            />
            <span className="text-text-muted text-xs" aria-live="polite">
              {shown.length === bots.length ? `${bots.length} bots` : `${shown.length} of ${bots.length} bots`}
            </span>
          </div>
          {shown.length === 0 ? (
            <p className="text-text-muted text-sm">No bots match “{deferredQuery.trim()}”.</p>
          ) : (
            <BotList
              bots={shown}
              serverId={instanceServerId}
              expandedBotId={expandedBotId}
              onToggle={toggle}
              onChanged={refresh}
            />
          )}
        </section>
      )}

      <CreateBotModal
        serverId={instanceServerId}
        isOpen={showCreateBot}
        onClose={() => setShowCreateBot(false)}
        onCreated={refresh}
      />
      {showInvite && <CreateAgentInviteModal serverId={instanceServerId} onClose={() => setShowInvite(false)} onCreated={refresh} />}
    </div>
  );
}

// ─── Bot List (virtualized) ───────────────────────────────────────────────

/** Rendering every bot stalled the page at about 1,800 bots (#241): only the rows in view are mounted. */
function BotList({
  bots,
  serverId,
  expandedBotId,
  onToggle,
  onChanged,
}: {
  bots: Bot[];
  serverId: string;
  expandedBotId: string | null;
  onToggle: (botId: string) => void;
  onChanged: () => void;
}) {
  const scrollRef = useRef<HTMLDivElement>(null);
  const expandedIndex = expandedBotId ? bots.findIndex(b => b.id === expandedBotId) : -1;
  // This component is not compiled by the React Compiler; the virtualizer is read during render only
  // eslint-disable-next-line react-hooks/incompatible-library
  const virtualizer = useVirtualizer({
    count: bots.length,
    getScrollElement: () => scrollRef.current,
    estimateSize: () => 60,
    overscan: 8,
    getItemKey: index => bots[index].id,
    // The open bot stays mounted while scrolled away, so its panel (a half-made token, an error) survives
    rangeExtractor: range => {
      const indexes = defaultRangeExtractor(range);
      return expandedIndex < 0 || indexes.includes(expandedIndex) ? indexes : [...indexes, expandedIndex].sort((a, b) => a - b);
    },
  });

  return (
    <div ref={scrollRef} data-testid="bot-list" className="max-h-[70vh] overflow-y-auto overscroll-contain">
      <div className="relative w-full" style={{ height: virtualizer.getTotalSize() }}>
        {virtualizer.getVirtualItems().map(item => {
          const bot = bots[item.index];
          return (
            <div
              key={item.key}
              data-index={item.index}
              ref={virtualizer.measureElement}
              className="absolute left-0 top-0 w-full pb-2"
              style={{ transform: `translateY(${item.start}px)` }}
            >
              <BotRow
                bot={bot}
                serverId={serverId}
                isExpanded={expandedBotId === bot.id}
                onToggle={onToggle}
                onChanged={onChanged}
              />
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ─── Channel Loop Guard Settings ──────────────────────────────────────────

type GuardField = 'maxBotHops' | 'maxThreadBotHops';
type Limits = Record<GuardField, number>;
/** The limit a guard gets when it is switched on with no earlier value to restore. */
export const GUARD_DEFAULT: Limits = { maxBotHops: 4, maxThreadBotHops: 4 };

/**
 * Both loop guards per channel (#23): the channel guard (top-level bot messages in a row)
 * and the thread guard (bot replies in a row inside one thread). Each has an on/off switch;
 * off is a limit of 0.
 */
function ChannelLoopGuardSection({ serverId }: { serverId: string }) {
  const [channels, setChannels] = useState<Channel[]>([]);
  // Limits as loaded or last confirmed by a save here
  const [loaded, setLoaded] = useState<Record<string, Limits>>({});
  // Edits not yet confirmed by the server, by `${channelId}:${field}`
  const [dirty, setDirty] = useState<Record<string, number>>({});
  const [saving, setSaving] = useState<Record<string, boolean>>({});
  const [error, setError] = useState('');
  // A change made elsewhere (a notice's Raise limit or Turn off) arrives as ChannelBotConfig
  const live = useChannelStore(s => s.channels);
  const pending = useRef<Record<string, { timer: ReturnType<typeof setTimeout>; value: number }>>({});
  // Saves of one field go out one at a time, in order, so the last change made wins
  const queues = useRef<Record<string, Promise<void>>>({});
  // The last limit above 0, restored when a guard is switched back on
  const lastOn = useRef<Record<string, number>>({});
  const mounted = useRef(true);

  useEffect(() => {
    serverApi.getChannels(serverId).then((chs) => {
      const textChannels = chs.filter(c => c.channelType === 3);
      setChannels(textChannels);
      const initial: Record<string, Limits> = {};
      for (const ch of textChannels) {
        initial[ch.id] = { maxBotHops: ch.maxBotHops ?? 4, maxThreadBotHops: ch.maxThreadBotHops ?? 0 };
      }
      setLoaded(initial);
    }).catch(() => setError('Failed to load channels'));
  }, [serverId]);

  // enqueue only touches refs and state setters, so the first render's copy stays valid for the unmount flush
  const enqueueOnLeave = useRef(enqueue);

  // Leaving the page sends a change still waiting out its debounce instead of dropping it,
  // behind any save of that field still in flight so the older one cannot land last
  useEffect(() => {
    mounted.current = true;
    const waiting = pending.current;
    const flush = enqueueOnLeave.current;
    return () => {
      mounted.current = false;
      for (const [key, p] of Object.entries(waiting)) {
        clearTimeout(p.timer);
        delete waiting[key];
        const [channelId, field] = key.split(':') as [string, GuardField];
        flush(channelId, field, p.value);
      }
    };
  }, []);

  const shown = (channelId: string, field: GuardField): number => {
    const key = `${channelId}:${field}`;
    return dirty[key] ?? live.get(channelId)?.[field] ?? loaded[channelId]?.[field] ?? GUARD_DEFAULT[field];
  };

  function change(channelId: string, field: GuardField, value: number, delay: number) {
    const key = `${channelId}:${field}`;
    const prev = shown(channelId, field);
    if (prev > 0) lastOn.current[key] = prev;
    setDirty(d => ({ ...d, [key]: value }));
    if (pending.current[key]) clearTimeout(pending.current[key].timer);
    const timer = setTimeout(() => {
      delete pending.current[key];
      enqueue(channelId, field, value);
    }, delay);
    pending.current[key] = { timer, value };
  }

  /** Queues a save behind any earlier save of the same field (save never rejects). */
  function enqueue(channelId: string, field: GuardField, value: number) {
    const key = `${channelId}:${field}`;
    queues.current[key] = (queues.current[key] ?? Promise.resolve()).then(() => save(channelId, field, value));
  }

  function handleNumber(channelId: string, field: GuardField, raw: string) {
    const num = parseInt(raw, 10);
    // 0 would be "off": that is the switch's job, so the box keeps a limit while typing
    if (isNaN(num) || num < 1 || num > 1000) return;
    change(channelId, field, num, 600);
  }

  function handleToggle(channelId: string, field: GuardField, on: boolean) {
    const restore = lastOn.current[`${channelId}:${field}`] ?? GUARD_DEFAULT[field];
    change(channelId, field, on ? restore : 0, 0);
  }

  async function save(channelId: string, field: GuardField, value: number) {
    const key = `${channelId}:${field}`;
    if (mounted.current) { setSaving(s => ({ ...s, [key]: true })); setError(''); }
    // Only the latest edit clears the dirty value; an older save finishing must not
    const settle = (d: Record<string, number>) => {
      if (d[key] !== value || pending.current[key]) return d;
      const next = { ...d };
      delete next[key];
      return next;
    };
    try {
      const config = await botApi.updateChannelBotConfig(channelId, { [field]: value });
      useChannelStore.getState().patchChannel(channelId, { maxBotHops: config.maxBotHops, maxThreadBotHops: config.maxThreadBotHops });
      if (!mounted.current) return;
      setLoaded(l => ({ ...l, [channelId]: { maxBotHops: config.maxBotHops, maxThreadBotHops: config.maxThreadBotHops } }));
      setDirty(settle);
    } catch (err) {
      if (!mounted.current) return;
      // Show what the server still has, not the value that failed
      setDirty(settle);
      setError(err instanceof ApiError ? err.code : 'Failed to save');
    } finally {
      if (mounted.current) setSaving(s => ({ ...s, [key]: false }));
    }
  }

  if (channels.length === 0) return null;

  const guard = (ch: Channel, field: GuardField, label: string, unit: string) => {
    const value = shown(ch.id, field);
    const on = value > 0;
    const key = `${ch.id}:${field}`;
    return (
      <div className="flex items-center gap-2">
        <label className="min-h-11 md:min-h-8 flex items-center gap-1.5 text-xs text-text-muted cursor-pointer">
          <input
            type="checkbox"
            role="switch"
            checked={on}
            onChange={e => handleToggle(ch.id, field, e.target.checked)}
            aria-label={`${label} loop guard in #${ch.name}`}
            className="accent-primary"
          />
          {label}
        </label>
        {on ? (
          <input
            type="number"
            min={1}
            max={1000}
            value={value}
            onChange={e => handleNumber(ch.id, field, e.target.value)}
            aria-label={`${label} limit in #${ch.name} (${unit})`}
            title={`Pause after this many ${unit} in a row`}
            className="min-h-11 md:min-h-8 w-16 px-2 py-1 rounded border border-border bg-surface text-text text-sm text-right"
          />
        ) : (
          <span className="w-16 text-text-muted text-xs">Off</span>
        )}
        <span className="w-12 text-text-muted text-xs" aria-live="polite">{saving[key] ? 'Saving…' : ''}</span>
      </div>
    );
  };

  return (
    <section className="mb-6">
      <h3 className="text-sm font-semibold text-text mb-2">Loop Guard</h3>
      <p className="text-text-muted text-xs mb-3">
        Pauses agents after this many bot posts in a row with no human message. The channel guard counts top-level
        messages; the thread guard counts replies inside each thread. A human message resets both, and the notice
        it posts has Continue, Raise limit and Turn off buttons.
      </p>
      {error && <p className="text-danger text-xs mb-2" role="alert">{error}</p>}
      <div className="flex flex-col gap-1">
        {channels.map((ch) => (
          <div key={ch.id} className="flex flex-wrap items-center gap-x-6 gap-y-1 px-2 py-1.5 rounded hover:bg-surface-hover">
            <span className="flex min-w-32 flex-1 items-center gap-1 text-sm">
              <span className="text-text-muted">#</span>
              <span className="text-text">{ch.name}</span>
            </span>
            {guard(ch, 'maxBotHops', 'Channel', 'bot messages')}
            {guard(ch, 'maxThreadBotHops', 'Threads', 'bot replies in one thread')}
          </div>
        ))}
      </div>
    </section>
  );
}

// ─── Bot Row (expandable) ─────────────────────────────────────────────────

// Memoized with stable callbacks: opening one bot re-renders that row, not the whole list
const BotRow = memo(function BotRow({
  bot,
  serverId,
  isExpanded,
  onToggle,
  onChanged,
}: {
  bot: Bot;
  serverId: string;
  isExpanded: boolean;
  onToggle: (botId: string) => void;
  onChanged: () => void;
}) {
  const [pausing, setPausing] = useState(false);
  const [pauseError, setPauseError] = useState('');
  const [savingAccess, setSavingAccess] = useState(false);
  const isPaused = !!bot.pausedAt;

  async function changeAccess(access: RuntimeAccess) {
    if (access === 'auto' && !confirm(`Let ${bot.username} run code without approval? Runs still execute in the sandbox with its limits.`)) return;
    setSavingAccess(true);
    setPauseError('');
    try {
      await runtimeApi.setBotAccess(serverId, bot.id, access);
      onChanged();
    } catch (err) {
      setPauseError(err instanceof ApiError ? err.code : 'Failed to update code run access');
    } finally {
      setSavingAccess(false);
    }
  }

  async function togglePause() {
    setPausing(true);
    setPauseError('');
    try {
      if (isPaused) {
        await botApi.setPaused(serverId, bot.id, false);
      } else {
        const reason = prompt('Pause this bot? It will be read-only until resumed.\n\nReason (optional):');
        if (reason === null) return;
        await botApi.setPaused(serverId, bot.id, true, reason.trim() || undefined);
      }
      onChanged();
    } catch (err) {
      setPauseError(err instanceof ApiError ? err.code : 'Failed to update pause state');
    } finally {
      setPausing(false);
    }
  }

  return (
    <div className="border border-border rounded-lg overflow-hidden">
      <div className="flex items-center hover:bg-surface-hover">
      <button
        onClick={() => onToggle(bot.id)}
        aria-expanded={isExpanded}
        className="min-h-11 flex-1 flex items-center justify-between px-4 py-3 text-left"
      >
        <div>
          <span className="text-text font-medium">{bot.username}</span>
          {isPaused && (
            <span
              className="ml-2 inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-semibold leading-none bg-warn/20 text-warn"
              title={bot.pausedReason ? `Paused: ${bot.pausedReason}` : 'Paused'}
            >
              PAUSED
            </span>
          )}
          <span className="text-text-muted text-xs ml-2">
            {new Date(bot.createdAt).toLocaleDateString()}
          </span>
          {pauseError && <span className="text-danger text-xs ml-2">{pauseError}</span>}
        </div>
        <svg
          className="h-4 w-4 text-text-muted transition-transform"
          style={{ transform: isExpanded ? 'rotate(180deg)' : 'rotate(0deg)' }}
          fill="none"
          viewBox="0 0 24 24"
          stroke="currentColor"
          strokeWidth="2"
        >
          <polyline points="6 9 12 15 18 9" />
        </svg>
      </button>
      <label className="flex items-center gap-1 pr-3 text-xs text-text-muted" title="Whether this bot may run code in the sandbox">
        Code runs
        <select
          className="min-h-11 md:min-h-8 bg-surface border border-border rounded px-2 py-1 text-xs text-text"
          value={bot.runtimeAccess ?? 'none'}
          disabled={savingAccess}
          onChange={e => changeAccess(e.target.value as RuntimeAccess)}
          aria-label={`Code run access for ${bot.username}`}
        >
          <option value="none">Off</option>
          <option value="approval">Need approval</option>
          <option value="auto">Auto-run</option>
        </select>
      </label>
      <div className="pr-3">
        <Button variant="secondary" onClick={togglePause} loading={pausing}>
          {isPaused ? 'Resume' : 'Pause'}
        </Button>
      </div>
      </div>
      {isExpanded && (
        <BotDetailPanel botId={bot.id} serverId={serverId} onDeleted={onChanged} />
      )}
    </div>
  );
});

// ─── Bot Detail Panel ─────────────────────────────────────────────────────

function BotDetailPanel({
  botId,
  serverId,
  onDeleted,
}: {
  botId: string;
  serverId: string;
  onDeleted: () => void;
}) {
  const [detail, setDetail] = useState<BotDetail | null>(null);
  const [allChannels, setAllChannels] = useState<Channel[]>([]);
  const [tokens, setTokens] = useState<BotToken[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [showCreateToken, setShowCreateToken] = useState(false);
  const [showInvite, setShowInvite] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [channelLoading, setChannelLoading] = useState<string | null>(null);
  const [avatarInput, setAvatarInput] = useState('');
  const [avatarSaving, setAvatarSaving] = useState(false);
  const [avatarError, setAvatarError] = useState('');

  const fetchDetail = useCallback(async () => {
    try {
      const [d, channels] = await Promise.all([
        botApi.get(serverId, botId),
        serverApi.getChannels(serverId),
      ]);
      setDetail(d);
      setAvatarInput(d.avatarUrl || '');
      // Only show text channels (type 3) for bot access
      setAllChannels(channels.filter(c => c.channelType === 3));
      if (d.canManageTokens) {
        const t = await botApi.listTokens(serverId, botId);
        setTokens(t);
      }
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to load bot details');
    } finally {
      setLoading(false);
    }
  }, [serverId, botId]);

  useEffect(() => { fetchDetail(); }, [fetchDetail]);

  async function handleDelete() {
    if (!confirm('Delete this bot? This cannot be undone.')) return;
    setDeleting(true);
    try {
      await botApi.remove(serverId, botId);
      onDeleted();
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to delete bot');
      setDeleting(false);
    }
  }

  async function handleRevokeToken(tokenId: string) {
    try {
      await botApi.revokeToken(serverId, botId, tokenId);
      setTokens(prev => prev.map(t => t.id === tokenId ? { ...t, revokedAt: new Date().toISOString() } : t));
    } catch (err) {
      if (err instanceof ApiError && err.status === 403) {
        // Permissions changed — refetch detail
        fetchDetail();
      }
      setError(err instanceof ApiError ? err.code : 'Failed to revoke token');
    }
  }

  async function handleClearBinding(tokenId: string) {
    try {
      await botApi.clearTokenBinding(serverId, botId, tokenId);
      setTokens(prev => prev.map(t => t.id === tokenId ? { ...t, boundClient: null, boundAt: null, lastRefused: null } : t));
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to clear the binding');
    }
  }

  async function toggleDirect(channelId: string, canDirect: boolean) {
    setChannelLoading(channelId);
    setError('');
    try {
      await botApi.setCanDirect(channelId, botId, !canDirect);
      setDetail(await botApi.get(serverId, botId));
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to update who may direct');
    } finally {
      setChannelLoading(null);
    }
  }

  async function toggleChannel(channelId: string, hasAccess: boolean) {
    setChannelLoading(channelId);
    try {
      if (hasAccess) {
        await botApi.revokeChannel(channelId, botId);
      } else {
        await botApi.grantChannel(channelId, botId);
      }
      // Refetch detail to get updated channel list
      const d = await botApi.get(serverId, botId);
      setDetail(d);
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to update channel access');
    } finally {
      setChannelLoading(null);
    }
  }

  if (loading) {
    return <div className="px-4 py-3 border-t border-border text-text-muted text-sm">Loading...</div>;
  }

  if (error && !detail) {
    return <div className="px-4 py-3 border-t border-border text-danger text-sm">{error}</div>;
  }

  if (!detail) return null;

  const botChannelIds = new Set(detail.channels.map(c => c.id));
  const directChannelIds = new Set(detail.channels.filter(c => c.canDirect).map(c => c.id));
  const activeTokens = tokens.filter(t => !t.revokedAt);
  const revokedTokens = tokens.filter(t => t.revokedAt);

  return (
    <div className="border-t border-border px-4 py-4 flex flex-col gap-5 bg-bg/50">
      {error && <p className="text-danger text-sm">{error}</p>}

      {/* ── Avatar ── */}
      <section>
        <h4 className="text-sm font-semibold text-text mb-2">Avatar</h4>
        <div className="flex items-start gap-3">
          <Avatar userId={botId} username={detail.username} avatarUrl={detail.avatarUrl} className="h-12 w-12 text-sm" />
          <div className="flex-1 min-w-0">
            <input
              type="text"
              value={avatarInput}
              onChange={(e) => { setAvatarInput(e.target.value); setAvatarError(''); }}
              placeholder="data:image/svg+xml;base64,..."
              className="min-h-11 md:min-h-9 w-full px-3 py-1.5 rounded border border-border bg-surface text-text placeholder:text-text-muted/70 text-sm"
            />
            {avatarError && <p className="text-danger text-xs mt-1">{avatarError}</p>}
            <div className="flex gap-2 mt-2">
              <Button
                variant="secondary"
                className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
                loading={avatarSaving}
                onClick={async () => {
                  setAvatarSaving(true);
                  setAvatarError('');
                  try {
                    const res = await botApi.update(serverId, botId, { avatarUrl: avatarInput || null });
                    setDetail(prev => prev ? { ...prev, avatarUrl: res.avatarUrl } : prev);
                  } catch (err) {
                    setAvatarError(err instanceof ApiError ? err.code : 'Failed to save avatar');
                  } finally {
                    setAvatarSaving(false);
                  }
                }}
              >
                Save Avatar
              </Button>
              {detail.avatarUrl && (
                <Button
                  variant="secondary"
                  className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
                  onClick={async () => {
                    setAvatarSaving(true);
                    setAvatarError('');
                    try {
                      const res = await botApi.update(serverId, botId, { avatarUrl: null });
                      setDetail(prev => prev ? { ...prev, avatarUrl: res.avatarUrl } : prev);
                      setAvatarInput('');
                    } catch (err) {
                      setAvatarError(err instanceof ApiError ? err.code : 'Failed to remove avatar');
                    } finally {
                      setAvatarSaving(false);
                    }
                  }}
                >
                  Remove
                </Button>
              )}
            </div>
          </div>
        </div>
      </section>

      {/* ── Channel Access ── */}
      <section>
        <h4 className="text-sm font-semibold text-text mb-2">Channel Access</h4>
        {allChannels.length === 0 ? (
          <p className="text-text-muted text-xs">No text channels found.</p>
        ) : (
          <div className="flex flex-col gap-1">
            {allChannels.map((ch) => {
              const hasAccess = botChannelIds.has(ch.id);
              const isLoading = channelLoading === ch.id;
              return (
                <label
                  key={ch.id}
                  className="min-h-11 md:min-h-9 flex items-center gap-2 px-2 py-1.5 rounded hover:bg-surface-hover cursor-pointer text-sm"
                >
                  <input
                    type="checkbox"
                    checked={hasAccess}
                    disabled={isLoading}
                    onChange={() => toggleChannel(ch.id, hasAccess)}
                    className="accent-primary"
                  />
                  <span className="text-text-muted">#</span>
                  <span className="text-text">{ch.name}</span>
                  {isLoading && <span className="text-text-muted text-xs ml-auto">...</span>}
                  {hasAccess && (
                    <span
                      className="ml-auto flex items-center gap-1 text-xs text-text-muted"
                      title="Lets this bot give other agents instructions in this channel. Only the server owner can change it."
                      onClick={(e) => e.stopPropagation()}
                    >
                      <input
                        type="checkbox"
                        checked={directChannelIds.has(ch.id)}
                        disabled={isLoading}
                        onChange={() => toggleDirect(ch.id, directChannelIds.has(ch.id))}
                        className="accent-primary"
                      />
                      can direct agents
                    </span>
                  )}
                </label>
              );
            })}
          </div>
        )}
      </section>

      {/* ── Tokens (owner / admin only) ── */}
      {detail.canManageTokens && (
        <section>
          <Button onClick={() => setShowInvite(true)}>Invite Agent</Button>
          {showInvite && <CreateAgentInviteModal serverId={serverId} botId={botId} onClose={() => setShowInvite(false)} onCreated={() => {}} />}
          <div className="flex items-center justify-between mb-2">
            <h4 className="text-sm font-semibold text-text">Tokens</h4>
            <Button
              variant="secondary"
              className="min-h-11 md:min-h-8 !px-3 !py-1 !text-xs"
              onClick={() => setShowCreateToken(true)}
            >
              New Token
            </Button>
          </div>
          {activeTokens.length === 0 && revokedTokens.length === 0 ? (
            <p className="text-text-muted text-xs">No tokens yet.</p>
          ) : (
            <div className="flex flex-col gap-1">
              {activeTokens.map((t) => (
                <div key={t.id} className="flex items-center justify-between px-2 py-1.5 rounded bg-surface text-sm">
                  <div>
                    <span className="text-text">{t.name || 'Unnamed'}</span>
                    <span className="text-text-muted text-xs ml-2">
                      Created {new Date(t.createdAt).toLocaleDateString()}
                    </span>
                    {t.lastUsedAt && (
                      <span className="text-text-muted text-xs ml-2">
                        Last used {new Date(t.lastUsedAt).toLocaleDateString()}
                        {t.lastUsedClient ? ` by ${t.lastUsedClient}` : ''}
                        {t.lastUsedIp ? ` from ${t.lastUsedIp}` : ''}
                      </span>
                    )}
                    {t.boundClient && (
                      <span className="text-text-muted text-xs ml-2" title="Requests from any other client are refused">
                        Bound to {t.boundClient}
                      </span>
                    )}
                    {t.lastRefused && (
                      <span className="block text-danger text-xs">
                        Refused {t.lastRefused.client ? `use by ${t.lastRefused.client}` : 'a use with no client name'}
                        {t.lastRefused.ip ? ` from ${t.lastRefused.ip}` : ''} on {new Date(t.lastRefused.at).toLocaleString()}.
                        If that wasn't you moving this agent, revoke the token.
                      </span>
                    )}
                  </div>
                  <div className="flex shrink-0">
                    {t.boundClient && (
                      <button
                        onClick={() => handleClearBinding(t.id)}
                        className="min-h-11 md:min-h-8 px-2 text-text-muted text-xs hover:underline"
                        title="The next client that uses the token binds it again"
                      >
                        Clear binding
                      </button>
                    )}
                    <button
                      onClick={() => handleRevokeToken(t.id)}
                      className="min-h-11 md:min-h-8 px-2 text-danger text-xs hover:underline"
                    >
                      Revoke
                    </button>
                  </div>
                </div>
              ))}
              {revokedTokens.map((t) => (
                <div key={t.id} className="flex items-center px-2 py-1.5 rounded bg-surface text-sm opacity-50">
                  <span className="text-text line-through">{t.name || 'Unnamed'}</span>
                  <span className="text-text-muted text-xs ml-2">Revoked</span>
                </div>
              ))}
            </div>
          )}

          <CreateTokenModal
            serverId={serverId}
            botId={botId}
            isOpen={showCreateToken}
            onClose={() => setShowCreateToken(false)}
            onCreated={async () => {
              const t = await botApi.listTokens(serverId, botId);
              setTokens(t);
            }}
          />
        </section>
      )}

      {/* ── Delete Bot ── */}
      <div className="pt-2 border-t border-border">
        <Button variant="danger" onClick={handleDelete} loading={deleting}>
          Delete Bot
        </Button>
      </div>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { api, ApiError } from '../../lib/api';
import { Button } from '../../components/ui/Button';
import { SIWC_DOCS_URL, USAGE_URL } from './chatgptPlanLinks';

/**
 * "Continue with ChatGPT" for a Codex agent (docs/codex-chatgpt-plan.md). The sign-in runs on
 * the agent's host: Agora asks the host, the host opens the browser on that machine, and the
 * person signs in there and allows the agent to use their ChatGPT plan. Tokens stay on the
 * host; this page only sees the connection's state and the account's email.
 */

export interface PlanConnection {
  profileId: any;
  status: 'requested' | 'in_progress' | 'connected' | 'scope_missing' | 'failed' | 'disconnect_requested' | 'disconnected';
  accountLabel: string | null;
  error: string | null;
  planOwnerId: string | null;
}

const PENDING = new Set(['requested', 'in_progress', 'disconnect_requested']);

const ERROR_TEXT: Record<string, string> = {
  consent_declined: 'Sign-in was declined in the browser.',
  sign_in_timeout: "Timed out: sign-in didn't finish in the browser in time. Try again.",
  request_timed_out: 'Timed out: the host never picked up the request. Check that agora-host is running and this profile is set to "auth": "siwc", then try again.',
  browser_unavailable: 'The host could not open a browser. Run `agora-host siwc login` on that machine instead.',
  callback_port_unavailable: 'The host\'s sign-in port is in use.',
  account_mismatch: 'A different ChatGPT account signed in than the one saved for this agent.',
  invalid_id_token: 'The ChatGPT identity could not be verified. Try again.',
  registration_incomplete: 'ChatGPT did not finish registering Agora. Try again.',
  invalid_grant: 'The sign-in code expired. Try again.',
  siwc_not_configured: 'This agent isn\'t set to "auth": "siwc" in its host\'s config, so the host can\'t sign it in.',
  revocation_unconfirmed: 'Signed out on the host, but OpenAI did not confirm it. Disconnect Agora in ChatGPT settings.',
};

function statusText(plan: PlanConnection | undefined, hostName: string): string {
  switch (plan?.status) {
    case 'requested': return `Request sent. Waiting for ${hostName} to pick it up…`;
    case 'in_progress': return `Browser opened on ${hostName}. Finish signing in there.`;
    case 'disconnect_requested': return `Waiting for ${hostName} to sign out…`;
    case 'connected': return `Using ChatGPT plan${plan.accountLabel ? ` (${plan.accountLabel})` : ''}. Only its plan owner can wake this agent.`;
    case 'scope_missing': return 'Signed in, but using your ChatGPT plan wasn\'t allowed. Continue with ChatGPT again and allow it, or use an API key profile.';
    case 'failed': return ERROR_TEXT[plan.error ?? ''] ?? `Failed${plan.error ? ` (${plan.error})` : ''}.`;
    case 'disconnected': return plan.error ? ERROR_TEXT[plan.error] ?? 'Disconnected.' : 'Disconnected.';
    default: return 'Not connected. Run this agent on your own ChatGPT Plus or Pro plan.';
  }
}

export function ChatGPTPlanConnect({ serverId, profileId, hostName, plan, siwcMode, onChange }: {
  serverId: string; profileId: string; hostName: string; plan: PlanConnection | undefined;
  /** The host reported this profile as "auth": "siwc". */
  siwcMode: boolean;
  onChange: () => void;
}) {
  const [error, setError] = useState('');
  const pending = !!plan && PENDING.has(plan.status);
  // While the host works on it, check again every few seconds
  useEffect(() => {
    if (!pending) return;
    const t = setInterval(onChange, 3000);
    return () => clearInterval(t);
  }, [pending, onChange]);

  const send = async (action: 'connect' | 'disconnect') => {
    setError('');
    try {
      await api.post(`/servers/${serverId}/agent-profiles/${profileId}/plan`, { action });
      onChange();
    } catch (err) {
      setError(err instanceof ApiError
        ? (err.status === 403 ? 'Only the server owner or the person who registered this host can do this.' : ERROR_TEXT[err.code] ?? err.code)
        : 'Request failed');
    }
  };
  const connected = plan?.status === 'connected';

  return (
    <div className="mt-2 rounded border border-border bg-bg/50 p-2 text-xs" data-testid={`plan-${profileId}`}>
      <div className="flex flex-wrap items-center gap-2">
        <span className="font-semibold text-text">ChatGPT plan</span>
        <span className="text-text-muted" role="status">{statusText(plan, hostName)}</span>
      </div>
      {!siwcMode && (
        <p className="mt-1 text-text-muted">
          {hostName} doesn't run this profile with Sign in with ChatGPT. Set <code>"auth": "siwc"</code> for it in the host's config and restart the host first.{' '}
          <a className="text-primary hover:underline" href={SIWC_DOCS_URL} target="_blank" rel="noreferrer">How to set it up</a>
        </p>
      )}
      {siwcMode && !connected && (
        <p className="mt-1 text-text-muted">The browser opens on {hostName}, not on this device: sign in at that computer. Approving from a phone isn't possible.</p>
      )}
      <div className="mt-2 flex flex-wrap items-center gap-2">
        {siwcMode && !connected && (
          <Button variant="secondary" disabled={pending} onClick={() => void send('connect')}>Continue with ChatGPT</Button>
        )}
        {connected && (
          <>
            <a className="min-h-11 md:min-h-8 inline-flex items-center px-2 text-primary hover:underline" href={USAGE_URL} target="_blank" rel="noreferrer">Manage usage</a>
            <Button variant="secondary" onClick={() => void send('disconnect')}>Disconnect</Button>
          </>
        )}
      </div>
      {error && <p className="mt-1 text-danger" role="alert">{error}</p>}
      <p className="mt-1 text-text-muted">Local and self-hosted use only; Agora is open source. Tokens stay on {hostName}.</p>
    </div>
  );
}

