          <Button
            variant="danger"
            disabled={busy}
            onClick={() => {
              if (!window.confirm(`Delete @${agent.name}? Its bot is deleted too.`)) return;
              run(() => aiApi.deleteAgent(serverId, agent.id), 'Failed to delete');
