function AddProviderForm({ serverId, adapters, onCancel, onCreated }: {
  serverId: string;
  adapters: AIAdapter[];
  onCancel: () => void;
  onCreated: () => void;
}) {
  const [adapterId, setAdapterId] = useState(adapters[0]?.id ?? '');
  const [label, setLabel] = useState('');
  const [apiKey, setApiKey] = useState('');
  const [baseUrl, setBaseUrl] = useState('');
  const [accountId, setAccountId] = useState('');
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const adapter = adapters.find(a => a.id === adapterId);

  async function save() {
    if (!adapter) return;
    if (adapter.requiresApiKey && !apiKey) { setError(`${adapter.label} requires an API key`); return; }
    if (adapter.requiresAccountId && !ACCOUNT_ID.test(accountId.trim())) { setError(`${adapter.label} requires an account ID`); return; }
    setSaving(true);
    setError('');
    try {
      await aiApi.createProvider(serverId, {
        adapter: adapter.id,
        ...(label.trim() ? { label: label.trim() } : {}),
        ...(apiKey ? { apiKey } : {}),
        ...(adapter.supportsBaseUrl && baseUrl.trim() ? { baseUrl: baseUrl.trim() } : {}),
        ...(adapter.requiresAccountId ? { accountId: accountId.trim() } : {}),
      });
      onCreated();
    } catch (err) {
      setError(errorText(err, 'Failed to add provider'));
      setSaving(false);
    }
  }

  return (
    <div className="border border-border rounded-lg p-4 mb-4 space-y-3">
      <div className="flex flex-col gap-1">
        <label className="text-sm text-text-muted" htmlFor="ai-adapter">Type</label>
        <select id="ai-adapter" className={inputClass} value={adapterId} onChange={e => setAdapterId(e.target.value)}>
          {adapters.map(a => <option key={a.id} value={a.id}>{a.label}</option>)}
        </select>
      </div>
      <Input label="Label" value={label} onChange={e => setLabel(e.target.value)} placeholder={adapter?.label ?? ''} />
      {adapter?.requiresAccountId && (
        <div>
          <Input label="Account ID" autoComplete="off" value={accountId} onChange={e => setAccountId(e.target.value)} />
          <p className="text-xs text-text-muted mt-1">
            Your Cloudflare account ID (Workers AI → Use REST API). The token needs Workers AI Read and Edit.
          </p>
        </div>
      )}
      <Input
        label={adapter?.requiresAccountId ? 'API token' : adapter?.requiresApiKey ? 'API key' : 'API key (optional)'}
        type="password"
        autoComplete="off"
        value={apiKey}
        onChange={e => setApiKey(e.target.value)}
      />
      {adapter?.supportsBaseUrl && (
        <div>
          <Input
            label="Base URL (optional)"
            value={baseUrl}
            onChange={e => setBaseUrl(e.target.value)}
            placeholder={adapter.defaultBaseUrl}
          />
          <p className="text-xs text-text-muted mt-1">
            Any OpenAI-compatible server, e.g. Ollama at <code>http://localhost:11434/v1</code>, OpenRouter, Groq, vLLM.
          </p>
        </div>
      )}
      {error && <p className="text-danger text-sm">{error}</p>}
      <div className="flex gap-2">
        <Button onClick={save} loading={saving}>Add</Button>
        <Button variant="secondary" onClick={onCancel}>Cancel</Button>
      </div>
    </div>
  );
}

function ProviderRow({ serverId, provider, adapter, testModel, onChanged }: {
  serverId: string;
  provider: AIProvider;
  adapter?: AIAdapter;
  testModel?: string;
  onChanged: () => void;
}) {
  const [model, setModel] = useState(testModel ?? adapter?.defaultModels.chat ?? Object.values(adapter?.defaultModels ?? {})[0] ?? '');
  const [chosenCapability, setChosenCapability] = useState<AICapability | null>(null);
  const capability = chosenCapability ?? (provider.capabilities.includes('chat') ? 'chat'
    : provider.capabilities.find(c => c === 'tts' || c === 'stt') ?? 'chat');
  const speech = provider.adapter === 'openai' && (capability === 'tts' || capability === 'stt');
  const [testing, setTesting] = useState(false);
  const [result, setResult] = useState<AIConnectionResult | null>(null);
  const [newKey, setNewKey] = useState('');
  const [editingKey, setEditingKey] = useState(false);
  const [editingUrl, setEditingUrl] = useState(false);
  const [newBaseUrl, setNewBaseUrl] = useState(provider.baseUrl ?? '');
  const [savingUrl, setSavingUrl] = useState(false);
  const [editingAccount, setEditingAccount] = useState(false);
  const [newAccountId, setNewAccountId] = useState(provider.accountId ?? '');
  const [error, setError] = useState('');

  async function run(action: () => Promise<unknown>, fallback: string) {
    setError('');
    try {
      await action();
      onChanged();
    } catch (err) {
      setError(errorText(err, fallback));
    }
  }

  async function test() {
    setTesting(true);
    setResult(null);
    try {
      setResult(await aiApi.testProvider(serverId, provider.id, model.trim() || undefined, provider.adapter === 'openai' ? capability : undefined));
    } catch (err) {
      setResult({ ok: false, error: errorText(err, 'Test failed') });
    } finally {
      setTesting(false);
    }
  }

  async function saveBaseUrl() {
    setSavingUrl(true);
    await run(async () => {
      await aiApi.updateProvider(serverId, provider.id, { baseUrl: newBaseUrl.trim() || null });
      setEditingUrl(false);
      setResult(null);
    }, 'Failed to save base URL');
    setSavingUrl(false);
  }

  return (
    <div className={`border border-border rounded-lg p-3 ${provider.enabled ? '' : 'opacity-60'}`}>
      <div className="flex items-center gap-2 flex-wrap">
        <span className="text-text font-medium">{provider.label}</span>
        <span className="text-xs text-text-muted">{adapter?.label ?? provider.adapter}</span>
        {provider.capabilities.map(c => (
          <span key={c} className="px-1.5 py-0.5 rounded text-[10px] font-semibold leading-none bg-primary/20 text-primary-text">
            {CAPABILITY_INFO[c].label}
          </span>
        ))}
        <span className="ml-auto flex items-center gap-3 text-xs">
          <span className={provider.hasApiKey ? 'text-online' : 'text-text-muted'}>
            {provider.hasApiKey ? 'Key saved' : 'No key'}
          </span>
          <label className="min-h-11 md:min-h-8 flex items-center gap-1.5 text-text-muted cursor-pointer">
            <input
              type="checkbox"
              className="accent-primary"
              checked={provider.enabled}
              onChange={e => run(() => aiApi.updateProvider(serverId, provider.id, { enabled: e.target.checked }), 'Failed to update')}
            />
            Enabled
          </label>
        </span>
      </div>
      {provider.baseUrl && <p className="text-xs text-text-muted mt-1 break-all">{provider.baseUrl}</p>}
      {provider.accountId && <p className="text-xs text-text-muted mt-1 break-all">Account {provider.accountId}</p>}

      <div className="flex items-center gap-2 mt-3 flex-wrap">
        {provider.adapter === 'openai' && (
          <select aria-label={`Test capability for ${provider.label}`} value={capability}
            className={`${inputClass} py-1 text-sm`} onChange={e => { setChosenCapability(e.target.value as AICapability); setResult(null); }}>
            {(['chat', 'tts', 'stt'] as const).map(c => <option key={c} value={c}>{CAPABILITY_INFO[c].label}</option>)}
          </select>
        )}
        <input
          className={`${inputClass} py-1 text-sm w-56`}
          value={model}
          onChange={e => setModel(e.target.value)}
          placeholder="model to test"
          aria-label={`Test model for ${provider.label}`}
        />
        <Button variant="secondary" onClick={test} loading={testing} disabled={editingUrl || (!speech && !model.trim())}>Test</Button>
        {adapter?.supportsBaseUrl && <Button variant="secondary" disabled={testing || savingUrl} onClick={() => {
          setNewBaseUrl(provider.baseUrl ?? ''); setEditingUrl(v => !v); setError('');
        }}>Edit base URL</Button>}
        {adapter?.requiresAccountId && <Button variant="secondary" onClick={() => {
          setNewAccountId(provider.accountId ?? ''); setEditingAccount(v => !v); setError('');
        }}>Edit account ID</Button>}
        <Button variant="secondary" onClick={() => setEditingKey(v => !v)}>
          {provider.hasApiKey ? 'Replace key' : 'Add key'}
        </Button>
        <Button
          variant="danger"
          onClick={() => {
            const routes = provider.capabilities.length
              ? `\n\nIt currently serves: ${provider.capabilities.map(c => CAPABILITY_INFO[c].label).join(', ')}. Those routes will be removed.`
              : '';
            if (confirm(`Delete provider "${provider.label}"?${routes}`)) {
              run(() => aiApi.deleteProvider(serverId, provider.id), 'Failed to delete');
            }
          }}
        >
          Delete
        </Button>
        {result && (
          <span className={`text-sm ${result.ok ? 'text-online' : 'text-danger'} break-all`}>
            {result.ok ? 'Connection OK' : result.error || 'Connection failed'}
          </span>
        )}
      </div>

      {speech && <p className="text-xs text-text-muted mt-1">Checks the speech server connection without generating audio. Use read-aloud or transcription to check the output.</p>}

      {editingUrl && (
        <div className="mt-3 space-y-2">
          <Input label="Base URL" id={`base-url-${provider.id}`} value={newBaseUrl}
            disabled={savingUrl} placeholder={adapter?.defaultBaseUrl}
            onChange={e => setNewBaseUrl(e.target.value)} />
          <p className="text-xs text-text-muted">Leave empty to use {adapter?.defaultBaseUrl || 'the provider default'}.</p>
          <div className="flex gap-2">
            <Button onClick={saveBaseUrl} loading={savingUrl}>Save base URL</Button>
            <Button variant="secondary" disabled={savingUrl} onClick={() => setEditingUrl(false)}>Cancel</Button>
          </div>
        </div>
      )}

      {editingAccount && (
        <div className="flex items-center gap-2 mt-2">
          <input
            className={`${inputClass} py-1 text-sm flex-1`}
            autoComplete="off"
            value={newAccountId}
            onChange={e => setNewAccountId(e.target.value)}
            placeholder="Account ID"
            aria-label={`Account ID for ${provider.label}`}
          />
          <Button
            onClick={() => run(async () => {
              await aiApi.updateProvider(serverId, provider.id, { accountId: newAccountId.trim() });
              setEditingAccount(false);
              setResult(null);
            }, 'Failed to save account ID')}
            disabled={!ACCOUNT_ID.test(newAccountId.trim())}
          >
            Save account ID
          </Button>
        </div>
      )}

      {editingKey && (
        <div className="flex items-center gap-2 mt-2">
          <input
            className={`${inputClass} py-1 text-sm flex-1`}
            type="password"
            autoComplete="off"
            value={newKey}
            onChange={e => setNewKey(e.target.value)}
            placeholder="New API key"
            aria-label={`New API key for ${provider.label}`}
          />
          <Button
            onClick={() => run(async () => {
              await aiApi.updateProvider(serverId, provider.id, { apiKey: newKey });
              setNewKey('');
              setEditingKey(false);
            }, 'Failed to save key')}
            disabled={!newKey}
          >
            Save key
          </Button>
        </div>
      )}
      {error && <p className="text-danger text-sm mt-2">{error}</p>}
    </div>
  );
}

