}) {
  const info = CAPABILITY_INFO[capability];
  const adapterOf = (id: string) => adapters.find(a => a.id === eligible.find(p => p.id === id)?.adapter);
  const defaultModel = (id: string) => adapterOf(id)?.defaultModels[capability] ?? '';
  const choicesFor = (id: string) => adapterOf(id)?.modelChoices?.[capability];

  const initialProvider = route?.providerId ?? eligible[0]?.id ?? '';
  const initialChoices = choicesFor(initialProvider);
  // A saved value outside the adapter's fixed choices (e.g. an LLM name left on a Tavily route) can't work
  const savedModelInvalid = !!(route && initialChoices && !initialChoices.includes(route.model));

  const [providerId, setProviderId] = useState(initialProvider);
  const [model, setModel] = useState(
    route?.model && !savedModelInvalid ? route.model : defaultModel(initialProvider),
  );
  const choices = choicesFor(providerId);
  const [enabled, setEnabled] = useState(route?.enabled ?? capability === 'chat');
  const [showLimits, setShowLimits] = useState(false);
  const [requests, setRequests] = useState(route?.dailyRequestLimit?.toString() ?? '');
  const [tokens, setTokens] = useState(route?.dailyTokenLimit?.toString() ?? '');
  const [costLimit, setCostLimit] = useState(microsToDollars(route?.dailyCostLimitMicros ?? null));
  const [inPrice, setInPrice] = useState(microsToDollars(route?.inputPriceMicrosPerMtok ?? null));
  const [outPrice, setOutPrice] = useState(microsToDollars(route?.outputPriceMicrosPerMtok ?? null));
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');

  if (eligible.length === 0) {
    return (
      <div className="border border-border rounded-lg px-4 py-3 flex items-center gap-3">
        <CapabilityName label={info.label} description={info.description} />
        <span className="ml-auto text-xs text-text-muted">No configured provider supports this yet</span>
      </div>
    );
  }

  async function save() {
    const limits = {
      dailyRequestLimit: parseLimit(requests),
      dailyTokenLimit: parseLimit(tokens),
      dailyCostLimitMicros: dollarsToMicros(costLimit),
      inputPriceMicrosPerMtok: dollarsToMicros(inPrice),
      outputPriceMicrosPerMtok: dollarsToMicros(outPrice),
    };
    if (Object.values(limits).some(v => v === undefined)) {
      setError('Limits must be positive whole numbers; prices must be non-negative dollar amounts.');
      return;
    }
    if (limits.dailyCostLimitMicros === 0) {
      setError('Daily cost limit must be greater than $0 (leave blank for no limit).');
      return;
    }
    setSaving(true);
    setError('');
    try {
      const value = choices && !choices.includes(model) ? choices[0] : model.trim();
      await aiApi.putRoute(serverId, capability, {
        providerId, model: value, enabled, ...(limits as Record<string, number | null>),
      });
      onChanged();
    } catch (err) {
      setError(err instanceof ApiError ? (err.message || err.code) : 'Failed to save');
      setSaving(false);
    }
  }

  async function remove() {
    try {
      await aiApi.deleteRoute(serverId, capability);
      onChanged();
    } catch (err) {
      setError(err instanceof ApiError ? err.code : 'Failed to remove');
    }
  }

  const limitsSummary = [
    route?.dailyRequestLimit ? `${route.dailyRequestLimit} req/day` : null,
    route?.dailyTokenLimit ? `${route.dailyTokenLimit.toLocaleString()} tokens/day` : null,
    route?.dailyCostLimitMicros ? `$${microsToDollars(route.dailyCostLimitMicros)}/day` : null,
  ].filter(Boolean).join(' · ');

  return (
    <div className="border border-border rounded-lg px-4 py-3">
      <div className="flex items-center gap-3 flex-wrap">
        <CapabilityName label={info.label} description={info.description} />
        {!route && <span className="text-xs text-text-muted">Not set</span>}
        {savedModelInvalid && (
          <span className="text-xs text-danger">Saved model “{route!.model}” isn’t valid here; pick one and save</span>
        )}
        {route && !route.enabled && <span className="text-xs text-warn">Off</span>}
        {limitsSummary && <span className="text-xs text-text-muted">{limitsSummary}</span>}
      </div>

      <div className="flex items-center gap-2 mt-3 flex-wrap">
        <select
          className={`${inputClass} py-1 text-sm`}
          value={providerId}
          aria-label={`${info.label} provider`}
          onChange={e => {
            const next = e.target.value;
            // A different provider type means different model names: start from its default
            (!model.trim() || adapterOf(next)?.id !== adapterOf(providerId)?.id) && setModel(defaultModel(next));
            setProviderId(next);
          }}
        >
          {eligible.map(p => <option key={p.id} value={p.id}>{p.label}{p.enabled ? '' : ' (disabled)'}</option>)}
        </select>
        {choices ? (
          <select
            className={`${inputClass} py-1 text-sm w-56`}
            value={choices.includes(model) ? model : choices[0]}
            onChange={e => setModel(e.target.value)}
            aria-label={`${info.label} model`}
          >
            {choices.map(c => <option key={c} value={c}>{c}</option>)}
          </select>
        ) : (
          <input
            className={`${inputClass} py-1 text-sm w-56`}
            value={model}
            onChange={e => setModel(e.target.value)}
            placeholder="model"
            aria-label={`${info.label} model`}
          />
        )}
        <label className="min-h-11 md:min-h-9 flex items-center gap-1.5 px-1 text-sm text-text-muted cursor-pointer">
          <input type="checkbox" className="accent-primary" checked={enabled} onChange={e => setEnabled(e.target.checked)} />
          On
        </label>
        <button className="min-h-11 md:min-h-9 px-2 text-sm text-primary-text hover:underline" onClick={() => setShowLimits(v => !v)}>
          {showLimits ? 'Hide limits' : 'Limits & prices'}
        </button>
        <span className="ml-auto flex gap-2">
          <Button onClick={save} loading={saving} disabled={!providerId || !model.trim()}>Save</Button>
          {route && <Button variant="secondary" onClick={remove}>Remove</Button>}
        </span>
      </div>

      {showLimits && (
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-3 mt-3">
          <LimitInput label="Requests / day" value={requests} onChange={setRequests} placeholder="unlimited" />
          <LimitInput label="Tokens / day" value={tokens} onChange={setTokens} placeholder="unlimited" />
          <LimitInput label="Cost / day ($)" value={costLimit} onChange={setCostLimit} placeholder="unlimited" />
          <LimitInput label="Input price ($ / 1M tokens)" value={inPrice} onChange={setInPrice} placeholder="not tracked" />
          <LimitInput label="Output price ($ / 1M tokens)" value={outPrice} onChange={setOutPrice} placeholder="not tracked" />
          <p className="text-xs text-text-muted sm:col-span-3">
            Prices are only used to estimate cost; enter them from your provider's pricing page. The cost limit
            needs prices to take effect.
          </p>
        </div>
      )}
      {error && <p className="text-danger text-sm mt-2">{error}</p>}
    </div>
  );
}

function CapabilityName({ label, description }: { label: string; description: string }) {
  return (
    <div>
      <span className="text-text font-medium">{label}</span>
      <span className="text-xs text-text-muted ml-2">{description}</span>
    </div>
  );
}

function LimitInput({ label, value, onChange, placeholder }: {
  label: string;
  value: string;
  onChange: (v: string) => void;
  placeholder: string;
}) {
  return (
    <label className="flex flex-col gap-1 text-xs text-text-muted">
      {label}
      <input
        className={`${inputClass} py-1 text-sm`}
        inputMode="decimal"
        value={value}
        onChange={e => onChange(e.target.value)}
        placeholder={placeholder}
      />
    </label>
  );
}

import { useState } from 'react';
import { aiApi, ApiError } from '../../../lib/api';
import type { AIFileTag, AIFileTagInput, AITaggingQueue } from '../../../lib/api';
import { Button } from '../../../components/ui/Button';
import { inputClass } from './format';

interface Props {
  serverId: any;
  tags: AIFileTag[];
  max: number;
  queue: AITaggingQueue;
  taggingOn: boolean;
  onChanged: () => void;
}

const errorText = (err: unknown, fallback: string) => (err instanceof ApiError ? (err.message || err.code) : fallback);

/**
 * The server's file tags. A decision model cannot make up tags: it answers one
 * yes/no question per tag in this list about every uploaded text file. Admins
 * write the question and what counts as yes and as no.
 */
export function TagsSection({ serverId, tags, max, queue, taggingOn, onChanged }: Props) {
  const [adding, setAdding] = useState(false);
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState('');
  const [error, setError] = useState('');

  async function retag(includeFailed: boolean) {
    setBusy(true);
    setError('');
    setMessage('');
    try {
      const res = await aiApi.retagFiles(serverId, includeFailed);
      const queued = res.created + res.requeued + res.retried;
      setMessage(queued === 0 ? 'Every file is already up to date.' : `${queued} file${queued === 1 ? '' : 's'} queued for tagging.`);
      onChanged();
    } catch (err) {
      setError(errorText(err, 'Failed to queue files'));
    } finally {
      setBusy(false);
    }
  }

  const waiting = queue.pending + queue.running;

  return (
    <section className="mb-10">
      <h3 className="text-lg font-semibold text-text mb-2">File tags</h3>
      <p className="text-sm text-text-muted mb-3">
        When file tagging is on, each uploaded text file or PDF is checked against every tag below, and
        files can then be found by tag. A tag is a yes/no question: say what it means, and what counts as
        yes and as no. Images, audio and video are not tagged.
      </p>

      {!taggingOn && (
        <p className="text-sm text-text-muted mb-3">
          File tagging is off. Turn it on under Decision model above; you can prepare the tags first.
        </p>
      )}

      <div className="flex flex-col gap-2">
        {tags.map(tag => (
          <TagRow key={`${tag.id}:${tag.updatedAt}`} serverId={serverId} tag={tag} onChanged={onChanged} />
        ))}
        {tags.length === 0 && <p className="text-sm text-text-muted">No tags yet.</p>}
      </div>

      {adding ? (
        <div className="border border-border rounded-lg px-4 py-3 mt-2">
          <TagForm
            submitLabel="Add tag"
            onCancel={() => setAdding(false)}
            onSubmit={async data => {
              await aiApi.createTag(serverId, data);
              setAdding(false);
              onChanged();
            }}
          />
        </div>
      ) : (
        <div className="flex items-center gap-3 mt-3 flex-wrap">
          <Button variant="secondary" onClick={() => setAdding(true)} disabled={tags.length >= max}>Add a tag</Button>
          {taggingOn && (
            <Button variant="secondary" onClick={() => retag(false)} loading={busy}>Tag files now</Button>
          )}
          {taggingOn && queue.failed > 0 && (
            <button className="min-h-11 md:min-h-9 px-2 text-sm text-primary-text hover:underline" onClick={() => retag(true)} disabled={busy}>
              Retry {queue.failed} failed
            </button>
          )}
          <span className="text-xs text-text-muted">{tags.length} of {max} tags</span>
        </div>
      )}

      <p className="text-xs text-text-muted mt-3">
        Files: {queue.done} tagged
        {queue.stale > 0 && `, ${queue.stale} out of date (a tag changed since)`}
        {waiting > 0 && `, ${waiting} waiting`}
        {queue.skipped > 0 && `, ${queue.skipped} skipped (no readable text)`}
        {queue.failed > 0 && <span className="text-danger">, {queue.failed} failed</span>}
        . Changing what a tag means makes its results out of date; files are re-checked for that tag in the
        background, or at once with “Tag files now”.
      </p>
      {message && <p className="text-sm text-text-muted mt-2">{message}</p>}
      {error && <p className="text-danger text-sm mt-2">{error}</p>}
    </section>
  );
}

function TagRow({ serverId, tag, onChanged }: { serverId: string; tag: AIFileTag; onChanged: () => void }) {
  const [editing, setEditing] = useState(false);
  const [error, setError] = useState('');

  async function run(action: () => Promise<unknown>, fallback: string) {
    setError('');
    try {
      await action();
      onChanged();
    } catch (err) {
      setError(errorText(err, fallback));
    }
  }

  if (editing) {
    return (
      <div className="border border-border rounded-lg px-4 py-3">
        <TagForm
          initial={tag}
          submitLabel="Save"
          onCancel={() => setEditing(false)}
          onSubmit={async data => {
            await aiApi.updateTag(serverId, tag.id, data);
            setEditing(false);
            onChanged();
          }}
        />
      </div>
    );
  }

  return (
    <div className="border border-border rounded-lg px-4 py-3">
      <div className="flex items-start gap-3">
        <div className="min-w-0">
          <span className={`font-medium ${tag.enabled ? 'text-text' : 'text-text-muted line-through'}`}>{tag.name}</span>
          {!tag.enabled && <span className="text-xs text-warn ml-2">Off</span>}
          <p className="text-sm text-text-muted break-words">{tag.instructions}</p>
          {(tag.criteriaTrue || tag.criteriaFalse) && (
            <p className="text-xs text-text-muted break-words mt-1">
              {tag.criteriaTrue && <>Yes: {tag.criteriaTrue} </>}
              {tag.criteriaFalse && <>No: {tag.criteriaFalse}</>}
            </p>
          )}
        </div>
        <span className="ml-auto flex items-center gap-2 shrink-0 text-sm">
          <label className="min-h-11 md:min-h-8 flex items-center gap-1.5 px-1 text-text-muted cursor-pointer">
            <input
              type="checkbox"
              className="accent-primary"
              checked={tag.enabled}
              onChange={e => run(() => aiApi.updateTag(serverId, tag.id, { enabled: e.target.checked }), 'Failed to update')}
            />
            On
          </label>
          <button className="min-h-11 md:min-h-8 px-2 text-primary-text hover:underline" onClick={() => setEditing(true)}>Edit</button>
          <button
            className="min-h-11 md:min-h-8 px-2 text-danger hover:underline"
            onClick={() => {
              if (window.confirm(`Delete the tag “${tag.name}”? It is removed from every file.`)) {
                void run(() => aiApi.deleteTag(serverId, tag.id), 'Failed to delete');
              }
            }}
          >
            Delete
          </button>
        </span>
      </div>
      {error && <p className="text-danger text-sm mt-2">{error}</p>}
    </div>
  );
}

function TagForm({ initial, submitLabel, onSubmit, onCancel }: {
  initial?: AIFileTag;
  submitLabel: string;
  onSubmit: (data: AIFileTagInput) => Promise<void>;
  onCancel: () => void;
}) {
  const [name, setName] = useState(initial?.name ?? '');
  const [instructions, setInstructions] = useState(initial?.instructions ?? '');
  const [criteriaTrue, setCriteriaTrue] = useState(initial?.criteriaTrue ?? '');
  const [criteriaFalse, setCriteriaFalse] = useState(initial?.criteriaFalse ?? '');
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');

  async function submit() {
    if (!/^[A-Za-z0-9][A-Za-z0-9 _.&+/-]{0,39}$/.test(name.trim())) {
      setError('The name must start with a letter or digit and use only letters, digits, spaces and _ . & + / - (40 characters at most).');
      return;
    }
    if (!instructions.trim()) {
      setError('Say what the tag means.');
      return;
    }
    setSaving(true);
    setError('');
    try {
      await onSubmit({
        name: name.trim(),
        instructions: instructions.trim(),
        criteriaTrue: criteriaTrue.trim() || null,
        criteriaFalse: criteriaFalse.trim() || null,
      });
    } catch (err) {
      setError(errorText(err, 'Failed to save'));
      setSaving(false);
    }
  }

  return (
    <div className="flex flex-col gap-3">
      <label className="flex flex-col gap-1 text-xs text-text-muted">
        Name
        <input className={`${inputClass} py-1 text-sm`} value={name} onChange={e => setName(e.target.value)} maxLength={40} placeholder="protocol" />
      </label>
      <label className="flex flex-col gap-1 text-xs text-text-muted">
        What the tag means
        <textarea
          className={`${inputClass} py-1 text-sm`}
          rows={2}
          maxLength={500}
          value={instructions}
          onChange={e => setInstructions(e.target.value)}
          placeholder="Rules or steps that participants must follow when working together."
        />
      </label>
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
        <label className="flex flex-col gap-1 text-xs text-text-muted">
          Counts as yes (optional)
          <textarea className={`${inputClass} py-1 text-sm`} rows={3} maxLength={500} value={criteriaTrue} onChange={e => setCriteriaTrue(e.target.value)} />
        </label>
        <label className="flex flex-col gap-1 text-xs text-text-muted">
          Counts as no (optional)
          <textarea className={`${inputClass} py-1 text-sm`} rows={3} maxLength={500} value={criteriaFalse} onChange={e => setCriteriaFalse(e.target.value)} />
        </label>
      </div>
      <div className="flex items-center gap-2">
        <Button onClick={submit} loading={saving}>{submitLabel}</Button>
        <Button variant="secondary" onClick={onCancel}>Cancel</Button>
      </div>
      {error && <p className="text-danger text-sm">{error}</p>}
    </div>
  );
}

