}

// ─── Icons ──────────────────────────────────────────────────────────────────

const ICON = 'h-4 w-4 shrink-0';
const STROKE = { fill: 'none', viewBox: '0 0 24 24', stroke: 'currentColor', strokeWidth: 2, strokeLinecap: 'round', strokeLinejoin: 'round' } as const;

const AccountIcon = () => (
