  error: string | null;
  /** Read a message now, interrupting anything playing. */
  speak: (message: Speakable) => void;
  /** Queue a newly arrived agent reply if the person asked for automatic reading here. */
  autoRead: (message: Speakable) => void;
  stop: () => void;
}

