export interface ReadyPayload {
  user: any;
  servers: Server[];
  channels: Channel[];
  unreads: { channelId: string; lastReadId: string | null; mentionCount: number }[];
  onlineUserIds: string[];
  /** Bring-your-own-session agents connected now, per channel (older servers omit it). */
  agentPresence?: AgentPresencePayload[];
}

export interface MessageAttachmentPayload {
  id: string;
  name: string;
  mime: string;
  size: number;
  width: number | null;
  height: number | null;
  url: string;
  deletedAt?: string;
  tags?: string[];
  tagging?: 'pending' | 'running' | 'done' | 'failed' | 'skipped';
  partial?: boolean;
  injectionWarning?: boolean;
  trustedByOwner?: boolean;
  trustedBy?: string | null;
  trustedAt?: string | null;
}

export interface FileAttachmentUpdatePayload {
  channelId: string;
  messageId: string;
  threadId?: string;
  fileId: string;
  tags: string[];
  tagging?: MessageAttachmentPayload['tagging'];
  partial: boolean;
  injectionWarning: boolean;
  trustedByOwner?: boolean;
  trustedBy?: string | null;
  trustedAt?: string | null;
}

/** Parsed agora-collab protocol header (server: src/lib/protocol.ts). */
export interface ProtocolInfo {
  version: 1;
  mode: 'plan' | 'review' | 'fix' | 'discuss';
  state: 'START' | 'ACK' | 'TURN' | 'CHECKPOINT' | 'DECIDE' | 'DONE' | 'BLOCK' | 'CANCEL' | 'WAIT';
  yieldTo?: string;
  /** WAIT only: the agent that owes the next step, and what it waits for (#327). */
  waitingOn?: string;
  waitingFor?: string;
  decision?: 'AGREE' | 'BLOCK';
  participants?: string[];
}

/** A canvas artifact a message carries: one version of it (server: src/lib/artifacts.ts). */
export interface ArtifactRef {
  id: string;
  version: number;
  title: string;
  kind: 'html' | 'markdown' | 'mermaid' | 'svg';
  latestVersion: number;
}

export interface MessagePayload {
  id: string;
  content: string;
  authorId: string;
  authorUsername: string;
  authorBot?: boolean;
  authorAvatarUrl?: string | null;
  channelId: string;
  createdAt: string;
  editedAt?: string;
  deletedAt?: string;
  mentions?: string[];
  mentionsEveryone?: boolean;
  systemEvent?: string;
  attachments?: MessageAttachmentPayload[];
  artifact?: ArtifactRef;
  threadId?: string;
  replyCount?: number;
  lastReplyAt?: string;
  threadClosedAt?: string;
  protocol?: ProtocolInfo;
  /** Structured data for system messages (e.g. runtime approval / result cards). */
  systemData?: Record<string, unknown>;
}

export interface MessageUpdatePayload {
  id: string;
  channelId: string;
  content: string;
  editedAt: string;
  threadId?: string;
  protocol?: ProtocolInfo | null;
  systemData?: Record<string, unknown>;
  attachments?: MessageAttachmentPayload[];
}

export interface MessageDeletePayload {
  id: string;
  channelId: string;
  deletedAt: string;
  threadId?: string;
}

export interface ThreadMetadataUpdatePayload {
  channelId: string;
  messageId: string;
  replyCount: number;
  lastReplyAt: string | null;
  threadClosedAt?: string | null;
  /** On a close (#132): how the thread ended and the thread its work moved to. */
  closeReason?: 'done' | 'blocked' | 'cancelled' | 'superseded' | null;
