export interface Message {
  id: string;
  content: string | null;
  authorId: string;
  authorUsername: string;
  authorBot?: boolean;
  authorAvatarUrl?: string | null;
  channelId: string;
  createdAt: string;
  editedAt?: string;
  deletedAt?: string;
  pending?: boolean;
  failed?: boolean;
  streaming?: boolean;
  systemEvent?: string;
  systemData?: Record<string, unknown>;
  attachments?: Attachment[];
  /** A canvas artifact this post carries (one version of it). */
  artifact?: ArtifactRef;
  replyCount?: number;
  lastReplyAt?: string;
  threadClosedAt?: string;
  protocol?: ProtocolInfo;
}

interface MessageState {
  byChannel: Map<string, Message[]>;
  hasMore: Map<string, boolean>;

  loadMessages: (channelId: string) => Promise<void>;
  loadOlder: (channelId: string) => Promise<void>;
  sendMessage: (channelId: string, content: string, authorId: string, authorUsername: string, attachmentIds?: string[]) => Promise<boolean>;
  editMessage: (channelId: string, msgId: string, content: string) => Promise<void>;
  deleteMessage: (channelId: string, msgId: string) => Promise<void>;

  addMessage: (msg: MessagePayload) => void;
  updateMessage: (payload: MessageUpdatePayload) => void;
  updateFileAttachment: (payload: FileAttachmentUpdatePayload) => void;
  removeMessage: (payload: MessageDeletePayload) => void;
  updateThreadMetadata: (channelId: string, messageId: string, replyCount: number, lastReplyAt: string | null, threadClosedAt?: string | null) => void;
  streamUpdate: (messageId: string, channelId: string, content: string, streaming: boolean, attachments?: Message['attachments']) => void;

  clearChannel: (channelId: string) => void;
  clear: () => void;
}

const PAGE_SIZE = 50;

// Temporary ids for optimistic rows. The counter keeps two sends in the same millisecond apart.
const TEMP_PREFIX = 'pending-';
let tempSeq = 0;
export function tempMessageId(): string {
  return `${TEMP_PREFIX}${Date.now()}-${++tempSeq}`;
}

/**
 * The optimistic row a socket echo of the user's own post confirms, or -1 (#149).
 * The POST response and the echo race. If the response came first, the row already has
 * the real id. If the echo comes first, the row still has its temporary id: the echo
 * carries no client nonce, so match the oldest unconfirmed row with the same author and text.
 */
export function findOptimistic(list: Message[], msg: MessagePayload): number {
  const byId = list.findIndex((m) => m.pending && m.id === msg.id);
  if (byId !== -1) return byId;
  return list.findIndex((m) =>
    m.pending && m.id.startsWith(TEMP_PREFIX) && m.authorId === msg.authorId && (m.content ?? '') === (msg.content ?? ''));
}

