      await api.patch(`/channels/${channelId}/messages/${msgId}`, { content });
      // WS 'MessageUpdate' event will arrive with server timestamp
    } catch {
      // Revert on failure
      if (originalContent !== null) {
        set((state) => {
          const nextByChannel = new Map(state.byChannel);
          const current = nextByChannel.get(channelId) ?? [];
          nextByChannel.set(channelId, current.map((m) =>
            m.id === msgId ? { ...m, content: originalContent, editedAt: undefined } : m
          ));
          return { byChannel: nextByChannel };
        });
      }
    }
  },

  deleteMessage: async (channelId, msgId) => {
    // Optimistic delete (soft-delete: set content to null)
    let originalMessage: Message | undefined;
    set((state) => {
      const nextByChannel = new Map(state.byChannel);
      const current = nextByChannel.get(channelId) ?? [];
      nextByChannel.set(channelId, current.map((m) => {
        if (m.id === msgId) {
          originalMessage = m;
          return { ...m, content: null, deletedAt: new Date().toISOString() };
        }
        return m;
      }));
      return { byChannel: nextByChannel };
    });

    try {
      await api.delete(`/channels/${channelId}/messages/${msgId}`);
      // WS 'MessageDelete' event will arrive with server timestamp
    } catch {
      // Revert on failure
      if (originalMessage) {
        const orig = originalMessage;
        set((state) => {
          const nextByChannel = new Map(state.byChannel);
          const current = nextByChannel.get(channelId) ?? [];
          nextByChannel.set(channelId, current.map((m) =>
            m.id === msgId ? orig : m
          ));
          return { byChannel: nextByChannel };
        });
      }
    }
  },

  addMessage: (msg) => {
    set((state) => {
      const nextByChannel = new Map(state.byChannel);
      const current = nextByChannel.get(msg.channelId) ?? [];

      // Check if this is confirming an optimistic (pending) message, by real ID or,
      // when the echo beat the POST response, by author and text
      const pendingIdx = current.some((m) => !m.pending && m.id === msg.id) ? -1 : findOptimistic(current, msg);

      if (pendingIdx !== -1) {
        // Replace the optimistic message with the confirmed server version
        const updated = [...current];
        updated[pendingIdx] = {
          id: msg.id,
          content: msg.content,
          authorId: msg.authorId,
          authorUsername: msg.authorUsername,
          authorBot: msg.authorBot,
          authorAvatarUrl: msg.authorAvatarUrl,
          channelId: msg.channelId,
          createdAt: msg.createdAt,
          systemEvent: msg.systemEvent,
          systemData: msg.systemData,
          protocol: msg.protocol,
          attachments: msg.attachments,
          artifact: msg.artifact,
        };
        nextByChannel.set(msg.channelId, updated);
      } else {
        // Ignore duplicate (the same event delivered twice, or already loaded)
        if (current.some((m) => m.id === msg.id)) {
          return state;
        }
        // New message from another user (or no pending match)
        const newMsg: Message = {
          id: msg.id,
          content: msg.content,
          authorId: msg.authorId,
          authorUsername: msg.authorUsername,
          authorBot: msg.authorBot,
          authorAvatarUrl: msg.authorAvatarUrl,
          channelId: msg.channelId,
          createdAt: msg.createdAt,
          systemEvent: msg.systemEvent,
          systemData: msg.systemData,
          protocol: msg.protocol,
          attachments: msg.attachments,
          artifact: msg.artifact,
        };
        nextByChannel.set(msg.channelId, [...current, newMsg]);
      }

      return { byChannel: nextByChannel };
    });
  },

  updateFileAttachment: payload => {
    useFileMetadataStore.getState().update(payload);
    set(state => {
      const current = state.byChannel.get(payload.channelId);
      if (!current) return state;
      const next = new Map(state.byChannel);
      next.set(payload.channelId, current.map(message => message.id === payload.messageId && !message.deletedAt
        ? { ...message, attachments: message.attachments?.map(file => file.id === payload.fileId && !file.deletedAt ? { ...file, ...fileMetadata(payload) } : file) } : message));
      return { byChannel: next };
    });
  },

  updateMessage: (payload) => {
    set((state) => {
      const nextByChannel = new Map(state.byChannel);
      const current = nextByChannel.get(payload.channelId);
      if (!current) return state;

      nextByChannel.set(payload.channelId, current.map((m) =>
        m.id === payload.id
          ? { ...m, content: payload.content, editedAt: payload.editedAt, protocol: payload.protocol ?? undefined, ...(payload.systemData ? { systemData: payload.systemData } : {}), ...(payload.attachments !== undefined ? { attachments: payload.attachments } : {}) }
          : m
      ));
      return { byChannel: nextByChannel };
    });
  },

  removeMessage: (payload) => {
    set((state) => {
      const nextByChannel = new Map(state.byChannel);
      const current = nextByChannel.get(payload.channelId);
      if (!current) return state;

      nextByChannel.set(payload.channelId, current.map((m) =>
        m.id === payload.id
          ? { ...m, content: null, deletedAt: payload.deletedAt }
          : m
      ));
      return { byChannel: nextByChannel };
    });
  },

  updateThreadMetadata: (channelId, messageId, replyCount, lastReplyAt, threadClosedAt?) => {
    set((state) => {
      const nextByChannel = new Map(state.byChannel);
      const current = nextByChannel.get(channelId);
      if (!current) return state;

      nextByChannel.set(channelId, current.map((m) =>
        m.id === messageId
          ? { ...m, replyCount, lastReplyAt: lastReplyAt ?? undefined, threadClosedAt: threadClosedAt ?? undefined }
          : m
      ));
      return { byChannel: nextByChannel };
    });
  },

  streamUpdate: (messageId, channelId, content, streaming, attachments) => {
    set((state) => {
      const nextByChannel = new Map(state.byChannel);
      const current = nextByChannel.get(channelId);
      if (!current) return state;

      nextByChannel.set(channelId, current.map((m) => {
        if (m.id !== messageId) return m;
        // Ignore updates after stream has been finalized
        if (m.streaming === false) return m;
        return { ...m, content, streaming, ...(attachments ? { attachments } : {}) };
      }));
      return { byChannel: nextByChannel };
    });
  },

  clearChannel: (channelId) => {
    set((state) => {
      const nextByChannel = new Map(state.byChannel);
      const nextHasMore = new Map(state.hasMore);
      nextByChannel.delete(channelId);
      nextHasMore.delete(channelId);
      return { byChannel: nextByChannel, hasMore: nextHasMore };
    });
  },

  clear: () => { useFileMetadataStore.getState().clear(); set({ byChannel: new Map(), hasMore: new Map() }); },
}));

import { create } from 'zustand';
import { api } from '../lib/api';
import { fileMetadata, useFileMetadataStore } from './fileMetadataStore';
import type { FileAttachmentUpdatePayload } from '../lib/contracts/ws-events';
import type { ArtifactRef, MessagePayload, MessageUpdatePayload, MessageDeletePayload, ProtocolInfo } from '../lib/contracts/ws-events';

export interface Attachment {
  id: string;
  name: string;
  mime: string;
  size: number;
  width: number | null;
  height: number | null;
  url: string;
  deletedAt?: string;
  /** Set when the server tags files: tag names (strongest first) and where tagging stands. */
  tags?: string[];
  tagging?: 'pending' | 'running' | 'done' | 'skipped' | 'failed';
  /** The file was longer than what the tagger read. */
  partial?: boolean;
  /** The file's text looked like it tries to instruct an AI reader. */
  injectionWarning?: boolean;
  trustedByOwner?: boolean;
  trustedBy?: string | null;
  trustedAt?: string | null;
}

export interface Message {
  id: string;
  content: string | null;
  authorId: string;
  authorUsername: string;
  authorBot?: boolean;
  authorAvatarUrl?: string | null;
  channelId: string;
  createdAt: string;
  editedAt?: string;
  deletedAt?: string;
  pending?: boolean;
  failed?: boolean;
  streaming?: boolean;
  systemEvent?: string;
  systemData?: Record<string, unknown>;
  attachments?: Attachment[];
  /** A canvas artifact this post carries (one version of it). */
  artifact?: ArtifactRef;
  replyCount?: number;
  lastReplyAt?: string;
  threadClosedAt?: string;
  protocol?: ProtocolInfo;
}

interface MessageState {
  byChannel: Map<string, Message[]>;
  hasMore: Map<string, boolean>;

  loadMessages: (channelId: string) => Promise<void>;
  loadOlder: (channelId: string) => Promise<void>;
  sendMessage: (channelId: string, content: string, authorId: string, authorUsername: string, attachmentIds?: string[]) => Promise<boolean>;
  editMessage: (channelId: string, msgId: string, content: string) => Promise<void>;
  deleteMessage: (channelId: string, msgId: string) => Promise<void>;

  addMessage: (msg: MessagePayload) => void;
  updateMessage: (payload: MessageUpdatePayload) => void;
  updateFileAttachment: (payload: FileAttachmentUpdatePayload) => void;
  removeMessage: (payload: MessageDeletePayload) => void;
  updateThreadMetadata: (channelId: string, messageId: string, replyCount: number, lastReplyAt: string | null, threadClosedAt?: string | null) => void;
  streamUpdate: (messageId: string, channelId: string, content: string, streaming: boolean, attachments?: Message['attachments']) => void;

  clearChannel: (channelId: string) => void;
  clear: () => void;
}

let PAGE_SIZE = 50;

// Temporary ids for optimistic rows. The counter keeps two sends in the same millisecond apart.
const TEMP_PREFIX = 'pending-';
let tempSeq = 0;
export function tempMessageId(): string {
  return `${TEMP_PREFIX}${Date.now()}-${++tempSeq}`;
}

/**
 * The optimistic row a socket echo of the user's own post confirms, or -1 (#149).
 * The POST response and the echo race. If the response came first, the row already has
 * the real id. If the echo comes first, the row still has its temporary id: the echo
 * carries no client nonce, so match the oldest unconfirmed row with the same author and text.
 */
export function findOptimistic(list: Message[], msg: MessagePayload): number {
  const byId = list.findIndex((m) => m.pending && m.id === msg.id);
  if (byId !== -1) return byId;
  return list.findIndex((m) =>
    m.pending && m.id.startsWith(TEMP_PREFIX) && m.authorId === msg.authorId && (m.content ?? '') === (msg.content ?? ''));
}

export const useMessageStore = create<MessageState>((set, get) => ({
  byChannel: new Map(),
  hasMore: new Map(),

  loadMessages: async (channelId) => {
    const data = await api.get<MessagePayload[]>(`/channels/${channelId}/messages?limit=${PAGE_SIZE}`);
    // API returns newest-first; reverse for chronological (oldest-first) order
    const reversed = data.reverse();
    const messages: Message[] = reversed.map((m) => ({
      id: m.id,
      content: m.content,
      authorId: m.authorId,
      authorUsername: m.authorUsername ?? '',
      authorBot: m.authorBot,
      authorAvatarUrl: m.authorAvatarUrl,
      channelId: m.channelId,
      createdAt: m.createdAt,
      editedAt: m.editedAt,
      deletedAt: m.deletedAt,
      systemEvent: m.systemEvent,
      systemData: m.systemData,
      protocol: m.protocol,
      attachments: m.attachments,
      artifact: m.artifact,
      ...(m.replyCount ? { replyCount: m.replyCount, lastReplyAt: m.lastReplyAt, ...(m.threadClosedAt ? { threadClosedAt: m.threadClosedAt } : {}) } : {}),
    }));
    set((state) => {
      const nextByChannel = new Map(state.byChannel);
      const nextHasMore = new Map(state.hasMore);
      nextByChannel.set(channelId, messages);
      nextHasMore.set(channelId, data.length === PAGE_SIZE);
      return { byChannel: nextByChannel, hasMore: nextHasMore };
    });
  },

  loadOlder: async (channelId) => {
    const existing = get().byChannel.get(channelId);
    if (!existing || existing.length === 0) return;
    if (!get().hasMore.get(channelId)) return;

    const oldestId = existing[0].id;
    const data = await api.get<MessagePayload[]>(
      `/channels/${channelId}/messages?limit=${PAGE_SIZE}&before=${oldestId}`
    );
    // API returns newest-first; reverse to chronological order then prepend
    const reversed = data.reverse();
    const older: Message[] = reversed.map((m) => ({
      id: m.id,
      content: m.content,
      authorId: m.authorId,
      authorUsername: m.authorUsername ?? '',
      authorBot: m.authorBot,
      authorAvatarUrl: m.authorAvatarUrl,
      channelId: m.channelId,
      createdAt: m.createdAt,
      editedAt: m.editedAt,
      deletedAt: m.deletedAt,
      systemEvent: m.systemEvent,
      systemData: m.systemData,
      protocol: m.protocol,
      attachments: m.attachments,
      artifact: m.artifact,
      ...(m.replyCount ? { replyCount: m.replyCount, lastReplyAt: m.lastReplyAt, ...(m.threadClosedAt ? { threadClosedAt: m.threadClosedAt } : {}) } : {}),
    }));
    set((state) => {
      const nextByChannel = new Map(state.byChannel);
      const nextHasMore = new Map(state.hasMore);
      const current = nextByChannel.get(channelId) ?? [];
      nextByChannel.set(channelId, [...older, ...current]);
      nextHasMore.set(channelId, data.length === PAGE_SIZE);
      return { byChannel: nextByChannel, hasMore: nextHasMore };
    });
  },

  sendMessage: async (channelId, content, authorId, authorUsername, attachmentIds?) => {
    // Create optimistic message
    const tempId = tempMessageId();
    const optimistic: Message = {
      id: tempId,
      content,
      authorId,
      authorUsername,
      channelId,
      createdAt: new Date().toISOString(),
      pending: true,
    };

    set((state) => {
      const nextByChannel = new Map(state.byChannel);
      const current = nextByChannel.get(channelId) ?? [];
      nextByChannel.set(channelId, [...current, optimistic]);
      return { byChannel: nextByChannel };
    });

    try {
      const body: Record<string, unknown> = {};
      if (content) body.content = content;
      if (attachmentIds && attachmentIds.length > 0) body.attachments = attachmentIds;
      const res = await api.post<{ id: string }>(`/channels/${channelId}/messages`, body);
      // Reconcile: if WS already delivered the real message, drop the optimistic row
      // (a no-op when addMessage already replaced it in place).
      // Otherwise remap tempId → real ID so addMessage can match when WS arrives.
      set((state) => {
        const nextByChannel = new Map(state.byChannel);
        const current = nextByChannel.get(channelId) ?? [];
        const wsAlreadyDelivered = current.some((m) => !m.pending && m.id === res.id);
        if (wsAlreadyDelivered) {
          // WS won the race — remove the optimistic row
          nextByChannel.set(channelId, current.filter((m) => m.id !== tempId));
        } else {
          // POST won the race — remap so addMessage can match by real ID
          nextByChannel.set(channelId, current.map((m) =>
            m.id === tempId ? { ...m, id: res.id, pending: true } : m
          ));
        }
        return { byChannel: nextByChannel };
      });
      return true;
    } catch {
      // Mark as failed
      set((state) => {
        const nextByChannel = new Map(state.byChannel);
        const current = nextByChannel.get(channelId) ?? [];
        nextByChannel.set(channelId, current.map((m) =>
          m.id === tempId ? { ...m, pending: false, failed: true } : m
        ));
        return { byChannel: nextByChannel };
      });
      return false;
    }
  },

  editMessage: async (channelId, msgId, content) => {
    // Optimistic update
    let originalContent: string | null = null;
    set((state) => {
      const nextByChannel = new Map(state.byChannel);
      const current = nextByChannel.get(channelId) ?? [];
      nextByChannel.set(channelId, current.map((m) => {
        if (m.id === msgId) {
          originalContent = m.content;
          return { ...m, content, editedAt: new Date().toISOString() };
        }
        return m;
      }));
      return { byChannel: nextByChannel };
    });

    try {
      await api.patch(`/channels/${channelId}/messages/${msgId}`, { content });
      // WS 'MessageUpdate' event will arrive with server timestamp
    } catch {
      // Revert on failure
      if (originalContent !== null) {
        set((state) => {
          const nextByChannel = new Map(state.byChannel);
          const current = nextByChannel.get(channelId) ?? [];
          nextByChannel.set(channelId, current.map((m) =>
            m.id === msgId ? { ...m, content: originalContent, editedAt: undefined } : m
          ));
          return { byChannel: nextByChannel };
        });
      }
    }
  },

  deleteMessage: async (channelId, msgId) => {
    // Optimistic delete (soft-delete: set content to null)
    let originalMessage: Message | undefined;
    set((state) => {
      const nextByChannel = new Map(state.byChannel);
      const current = nextByChannel.get(channelId) ?? [];
      nextByChannel.set(channelId, current.map((m) => {
        if (m.id === msgId) {
          originalMessage = m;
          return { ...m, content: null, deletedAt: new Date().toISOString() };
        }
        return m;
      }));
      return { byChannel: nextByChannel };
    });

    try {
      await api.delete(`/channels/${channelId}/messages/${msgId}`);
      // WS 'MessageDelete' event will arrive with server timestamp
    } catch {
      // Revert on failure
      if (originalMessage) {
        const orig = originalMessage;
        set((state) => {
          const nextByChannel = new Map(state.byChannel);
          const current = nextByChannel.get(channelId) ?? [];
          nextByChannel.set(channelId, current.map((m) =>
            m.id === msgId ? orig : m
          ));
          return { byChannel: nextByChannel };
        });
      }
    }
  },

  addMessage: (msg) => {
    set((state) => {
      const nextByChannel = new Map(state.byChannel);
      const current = nextByChannel.get(msg.channelId) ?? [];

      // Check if this is confirming an optimistic (pending) message, by real ID or,
      // when the echo beat the POST response, by author and text
      const pendingIdx = current.some((m) => !m.pending && m.id === msg.id) ? -1 : findOptimistic(current, msg);

      if (pendingIdx !== -1) {
        // Replace the optimistic message with the confirmed server version
        const updated = [...current];
        updated[pendingIdx] = {
          id: msg.id,
          content: msg.content,
          authorId: msg.authorId,
          authorUsername: msg.authorUsername,
          authorBot: msg.authorBot,
          authorAvatarUrl: msg.authorAvatarUrl,
          channelId: msg.channelId,
          createdAt: msg.createdAt,
          systemEvent: msg.systemEvent,
          systemData: msg.systemData,
          protocol: msg.protocol,
          attachments: msg.attachments,
          artifact: msg.artifact,
        };
        nextByChannel.set(msg.channelId, updated);
      } else {
        // Ignore duplicate (the same event delivered twice, or already loaded)
        if (current.some((m) => m.id === msg.id)) {
          return state;
        }
        // New message from another user (or no pending match)
        const newMsg: Message = {
          id: msg.id,
          content: msg.content,
          authorId: msg.authorId,
          authorUsername: msg.authorUsername,
          authorBot: msg.authorBot,
          authorAvatarUrl: msg.authorAvatarUrl,
          channelId: msg.channelId,
          createdAt: msg.createdAt,
          systemEvent: msg.systemEvent,
          systemData: msg.systemData,
          protocol: msg.protocol,
          attachments: msg.attachments,
          artifact: msg.artifact,
        };
        nextByChannel.set(msg.channelId, [...current, newMsg]);
      }

      return { byChannel: nextByChannel };
    });
  },

  updateFileAttachment: payload => {
    useFileMetadataStore.getState().update(payload);
    set(state => {
      const current = state.byChannel.get(payload.channelId);
      if (!current) return state;
      const next = new Map(state.byChannel);
      next.set(payload.channelId, current.map(message => message.id === payload.messageId && !message.deletedAt
        ? { ...message, attachments: message.attachments?.map(file => file.id === payload.fileId && !file.deletedAt ? { ...file, ...fileMetadata(payload) } : file) } : message));
      return { byChannel: next };
    });
  },

  updateMessage: (payload) => {
    set((state) => {
      const nextByChannel = new Map(state.byChannel);
      const current = nextByChannel.get(payload.channelId);
      if (!current) return state;

      nextByChannel.set(payload.channelId, current.map((m) =>
        m.id === payload.id
          ? { ...m, content: payload.content, editedAt: payload.editedAt, protocol: payload.protocol ?? undefined, ...(payload.systemData ? { systemData: payload.systemData } : {}), ...(payload.attachments !== undefined ? { attachments: payload.attachments } : {}) }
          : m
      ));
      return { byChannel: nextByChannel };
    });
  },

  removeMessage: (payload) => {
    set((state) => {
      const nextByChannel = new Map(state.byChannel);
      const current = nextByChannel.get(payload.channelId);
      if (!current) return state;

      nextByChannel.set(payload.channelId, current.map((m) =>
        m.id === payload.id
          ? { ...m, content: null, deletedAt: payload.deletedAt }
          : m
      ));
      return { byChannel: nextByChannel };
    });
  },

  updateThreadMetadata: (channelId, messageId, replyCount, lastReplyAt, threadClosedAt?) => {
    set((state) => {
      const nextByChannel = new Map(state.byChannel);
      const current = nextByChannel.get(channelId);
      if (!current) return state;

      nextByChannel.set(channelId, current.map((m) =>
        m.id === messageId
          ? { ...m, replyCount, lastReplyAt: lastReplyAt ?? undefined, threadClosedAt: threadClosedAt ?? undefined }
          : m
      ));
      return { byChannel: nextByChannel };
    });
  },

  streamUpdate: (messageId, channelId, content, streaming, attachments) => {
    set((state) => {
      const nextByChannel = new Map(state.byChannel);
      const current = nextByChannel.get(channelId);
      if (!current) return state;

      nextByChannel.set(channelId, current.map((m) => {
        if (m.id !== messageId) return m;
        // Ignore updates after stream has been finalized
        if (m.streaming === false) return m;
        return { ...m, content, streaming, ...(attachments ? { attachments } : {}) };
      }));
      return { byChannel: nextByChannel };
    });
  },

  clearChannel: (channelId) => {
    set((state) => {
      const nextByChannel = new Map(state.byChannel);
      const nextHasMore = new Map(state.hasMore);
      nextByChannel.delete(channelId);
      nextHasMore.delete(channelId);
      return { byChannel: nextByChannel, hasMore: nextHasMore };
    });
  },

  clear: () => { useFileMetadataStore.getState().clear(); set({ byChannel: new Map(), hasMore: new Map() }); },
}));

