}

export const useServerStore = create<ServerState>((set, get) => ({
  servers: new Map(),
  activeServerId: null,
  instanceServerId: null,

  setServers: (servers) => {
    const instanceServerId = servers[0]?.id ?? null;
    set({
      servers: new Map(servers.map(s => [s.id, s])),
      instanceServerId,
      activeServerId: instanceServerId,
    });
  },
  setActiveServer: (id) => {
    if (get().activeServerId !== id) set({ activeServerId: id });
